INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (2,0,0,0,0,0,0,0,0,'Most impressive, $N... the claw of Sharptalon could not have been easy to get! The Ashenvale Hunt goes well for you!$B$BSharptalon had long terrorized the peons from the lumber camps near its path as they tried to travel here to Splintertree Post. No doubt once the word gets out that it was you who put down the beast, many rousing songs of your bravery will be heard at campfires and lumber mills across Ashenvale!',12340),
	 (5,6,0,0,0,0,0,0,0,'You need some Crab Cakes, do you? Well I might be able to cook some up for you...',12340),
	 (6,1,0,0,0,0,0,0,0,'Hah - you caught him! You''ve done Elwynn a great service, and earned a nice bounty!',12340),
	 (7,1,0,0,0,0,0,0,0,'Well done, citizen. Those kobolds are thieves and cowards, but in large numbers they pose a threat to us. And the humans of Stormwind do not need another threat.$B$BFor defeating them, you have my gratitude.',12340),
	 (8,4,1,1,14,0,0,0,0,'Oh? A letter? Wonderful news! I''ve been waiting on word from my dear old mother in Deathknell. Such a saint, she is. I wonder how she''s holding up.$B$BWhat? Too cheery? Not buying it, are you?$B$BWell, get lost then... it''s really no business who the letter''s from anyway. Go on! Get lost!$B$BCome back when you''ve got some coin to spend... loafer.$B$BNext thing you know, you''ll be coming back to rest after a long days adventure or some stupid thing like that.',12340),
	 (9,21,0,0,0,0,0,0,0,'Good work, friend. You have earned your pay well. Who knows, perhaps Westfall will prosper once again.',12340),
	 (10,18,0,0,0,0,0,0,0,'He was a good goblin, young Scrimshank.  Let''s hope that his demise was not in vain by what he was able to record with his surveying equipment.$B$BIt seems as though we have quite the situation on our hands here with these bugs.  They''re way too cunning for their own good, and the research we''ve done so far is shaping up to indicate that they might even be under the controlling influence of a third party!  If this is the case, then it bodes ill for not only Gadgetzan, but the whole desert!',12340),
	 (11,66,0,0,0,0,0,0,0,'I see you''ve been busy! You have our thanks, $N.',12340),
	 (12,21,0,0,0,0,0,0,0,'Well done, $N. My scout witnessed your valiant acts. You are proving yourself quite well so far.',12340),
	 (13,1,0,0,0,0,0,0,0,'Your worth to The People''s Militia has been validated by your brave acts thus far.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (14,66,0,0,0,0,0,0,0,'When I left the tainted lands of Lordaeron I returned to a grim state of affairs here in my homeland. But there is hope for Westfall yet. As proven by your valor in battle, it is obvious to me that you serve our cause with honor. It is with great pride that I induct thee into The People''s Militia. May the Light shine upon you.',12340),
	 (15,1,0,0,0,0,0,0,0,'I don''t like hearing of all these kobolds in our mine. No good can come of this. Here, take this as payment, and when you''re ready, speak to me again. I would like you to go back to the mines one more time...',12340),
	 (16,2,0,0,0,0,0,0,0,'Thanks, $N! And come back if you want to trade again.',12340),
	 (17,21,1,1,0,0,0,0,0,'Well done $N, you''ve proven your worth once again! The caps will be an interesting study, yon verily!$B$BAnd now, as promised, enjoy a taste of one of my more potent restorative brews from my personal stock...$B$BIf you are a skilled alchemist, then perhaps we might have some additional business to conduct. Regardless, I thank you for your assistance!',12340),
	 (18,1,0,0,0,0,0,0,0,'Back with some bandanas, I see. The Stormwind Army appreciates your help.',12340),
	 (19,1,0,0,0,0,0,0,0,'Tharil''zun was a vicious, crafty orc. Well done - I''m sure he didn''t go down easy. Here is your reward, $N.',12340),
	 (20,0,0,0,0,0,0,0,0,'That makes for a lot fewer orcs to worry about, thanks.',12340),
	 (21,1,0,0,0,0,0,0,0,'Once again, you have earned my respect, and the gratitude of the Stormwind Army. There may yet be kobolds in the mine, but I will marshal others against them. We have further tasks for you.',12340),
	 (22,4,6,0,0,0,0,0,0,'These are just perfect, $N! Thank you so much. Farmer Saldean and I are going to feast tonight. And here is a little something for you, for the hard work. You didn''t think I was going to let a $C like you go hungry, did you?',12340),
	 (23,1,0,0,0,0,0,0,0,'Ah, the paw of Ursangous! Your skill is impressive, $C; he is credited with numerous kills. The crescent on his paw is no doubt a sign that he was trained by the night elves that skulk about Ashenvale. Ursangous is... was one of the mightiest bears you''d find in these parts. To have bested such a creature is a testament to your will and resolve.$b$bYour ancestors would be proud!',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (24,1,0,0,0,0,0,0,0,'A victory for $N in the Ashenvale Hunt! Well done - the head of Shadumbra is a fitting trophy to claim for such an impressive fight, no doubt.$b$bShadumbra''s savagery was well known throughout the post here. Any trip to the west, especially on foot trying to get out to the Zoram Strand, was wrought with danger because of this tiger. Thanks to you, this danger has abated.',12340),
	 (25,1,0,0,0,0,0,0,0,'Yeah, I heard that someone tore up the lake out there like a dust devil through the Barrens. From the sound of it too, we might be able to set up a possible observation area out there to keep an eye on our Alliance friends. Well, that is if we can keep it on the down low...$B$BLooks like you ended up being quite useful after all; the transports between here and Stonetalon should have an easier time of it. Take this - you''ve earned it.',12340),
	 (26,0,0,0,0,0,0,0,0,'Salutations, young $C; the time has come for you to know our aquatic form. It is one that lets you move freely and indefinitely through water. You will find this aspect a useful tool and a blessing... but it is one that must be earned before it is mastered.$B$BYou will face two trials to overcome. The first will test your ability to work in water under pressure. The second will test your resolve to understand the aspects of the form itself.$B$BStand ready, as the time of testing is now upon us.',12340),
	 (27,0,0,0,0,0,0,0,0,'Salutations, young $C; the time has come for you to know our aquatic form. It is one that lets you move freely and indefinitely through water. You will find this aspect a useful tool and a blessing... but it is one that must be earned before it is mastered.$B$BYou will face two trials to overcome. The first will test your ability to work in water under pressure. The second will test your resolve to understand the aspects of the form itself.$B$BStand ready, as the time of testing is now upon us.',12340),
	 (28,0,0,0,0,0,0,0,0,'Well now. it looks like yet another druid has successfully completed the Trial of the Lake! Well done. my young friend - well done.$B$BAs I''ve said. my name is Tajarri. It is my duty and my privilege to serve as a warden for Moonglade. and specifically this shrine. Keeper Remulos guides the Cenarion Circle in preservation of nature and balance. and his shrine serves as a lasting tribute to such. By using the bauble here. it serves as a nod to the importance of this place within the Circle.',12340),
	 (29,0,0,0,0,0,0,0,0,'Well now. it looks like yet another druid has successfully completed the Trial of the Lake! Well done. my young friend - well done.$B$BAs I''ve said, my name is Tajarri. It is my duty and my privilege to serve as a warden for Moonglade, and specifically this shrine. Keeper Remulos guides the Cenarion Circle in preservation of nature and balance, and his shrine serves as a lasting tribute to such. By using the bauble here, it serves as a nod to the importance of this place within the Circle.',12340),
	 (30,0,0,0,0,0,0,0,0,'You''ve completed the Trial of the Sea Lion, $N - congratulations.$B$BEach task in acquiring the pendant shows that both agility and endurance are necessary to act in harmony with what you desire to do underwater. Neither can exist without the other, and both cannot be done without you willingness to embrace the aspect of the sea lion.$B$BRemember these lessons well, and count on them once you have gained your aquatic form.',12340),
	 (31,0,0,0,0,0,0,0,0,'Very impressive, $N. Your ancestors would be pleased with your progress! You''re ready to learn your aquatic form, and it is my pleasure to teach it to you.$B$BAlso, in recognition of your achievement during the two trials, I give you this item. I hope you''ll find it to be a welcome addition to your gear as a protector of nature and a keeper of the balance.',12340),
	 (32,1,0,0,0,0,0,0,0,'This report... I''ve dealt with these beasts before. Fizzledowser was wise to send this. and you, to me.$b$bThese creatures will consume the Tanaris desert rapidly; they are nothing short of one of the greatest menaces we all will ever face. Familiarize yourself with this name, $N: silithid. The insects mentioned here are the silithid, and they are the tools of one of the greatest threats that both the Horde and Alliance face.$b$bIf only we were smart enough to see that before.',12340),
	 (33,1,0,0,0,0,0,0,0,'''Twas a grim task, friend, but you held up your part of the bargain.
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (34,4,0,0,0,0,0,0,0,'Finally the menace is laid to rest! Thank you, $N, you have done me a great service. The garden shall be in full bloom this season!',12340),
	 (35,1,0,0,0,0,0,0,0,'Yes, murlocs have settled in and around the streams of eastern Elwynn. We don''t know why they are here, but they are aggressive and at least semi-intelligent.',12340),
	 (36,1,0,0,0,0,0,0,0,'That Verna was always such a sweet lass. We''ll miss her here in Westfall but between you and me, she''s a city girl at heart and Stormwind will suit her just fine. But enough gossip! Now we can make Westfall Stew!',12340),
	 (37,0,0,0,0,0,0,0,0,'Although much has been stripped from the corpse, strewn nearby is a medallion with the words: "Footman Malakai Stone" etched upon it.',12340),
	 (38,1,0,0,0,0,0,0,0,'That Okra will thicken up this broth nicely! Now we just add the Stringy Vulture Meat, a few Murloc Eyes and those delicious Goretusk Snouts. And we''re done! For all your help, $N, I want you to take today''s first batch of Westfall Stew!',12340),
	 (39,0,0,0,0,0,0,0,0,'Hmm, this news is troubling. Already our defenses are stretched thin, and losing Rolf and Malakai to those murlocs put us in an even worse position.$B$BIf things don''t improve, there will be fighting in Goldshire by the week''s end!',12340),
	 (40,1,0,0,0,0,0,0,0,'Yes, I spoke with Remy. I respect him as a merchant, though all reports of Murlocs to the east have been sketchy at best.$B$BYour concerns are noted, but unless I receive a military report of a murloc threat, we can''t afford to send more troops east.',12340),
	 (45,0,0,0,0,0,0,0,0,'You find around the neck of the corpse a metal medallion inscribed with the words "Footman Rolf Hartford."',12340),
	 (46,66,0,0,0,0,0,0,0,'You have the fins? Great! Marshal Dughan is anxious about the Murloc situation in eastern Elwynn, and I''d like to tell him that it''s becoming under control.$b$bYour actions have helped realize that.',12340),
	 (47,0,0,0,0,0,0,0,0,'Thanks for the dust, $N. Here''s your cash, and...here is a token from associates of mine. You might find it useful...useful.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (48,33,0,0,0,0,0,0,0,'Hiccup! Ho Ho!',12340),
	 (49,33,0,0,0,0,0,0,0,'Hiccup! Ho ho!',12340),
	 (50,33,0,0,0,0,0,0,0,'Hiccup! Ho ho!',12340),
	 (51,33,0,0,0,0,0,0,0,'Hiccup! Ho ho!',12340),
	 (52,66,0,0,0,0,0,0,0,'Thanks a lot for the help, $N. Something in the forest must be making these animals so bold.$B$BWhatever it is, I hope it stays there.',12340),
	 (53,94,0,0,0,0,0,0,0,'Aged in the barrel, filtered through coal$BIt passes your lips and right through your soul.$BSo lets us drink now, a toast to you$BAnd me while we''re at it, Grimbooze Thunderbrew!',12340),
	 (54,1,66,0,0,0,0,0,0,'Well, it says here that you''ve been awarded Acting Deputy Status with the Stormwind Marshals. Congratulations.$b$bAnd good luck - keeping Elwynn safe is no picnic... what with most the army busy doing who knows what for who knows which noble!$b$bIt''s hard to keep track of politics in these dark days...',12340),
	 (55,1,1,2,0,0,0,0,0,'Morbent Fel has been defeated. The dark riders are still at large, but a small piece of that which I had hoped beyond hope has come to pass.$b$bYou have done the impossible, and your deeds will forever live in the legends of Duskwood.$b$bGo, $N. And perhaps, one day, fate may bring you back to me...',12340),
	 (56,21,0,0,0,0,0,0,0,'Splendid, $N. For your service to the people of Darkshire you shall be rewarded.',12340),
	 (57,21,0,0,0,0,0,0,0,'The people of Darkshire thank you, $N. You have proven yourself to be a great ally of The Night Watch.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (58,66,0,0,0,0,0,0,0,'On behalf of the people of Darkshire and as the Leader of the Night Watch, I thank you, $N, for your bravery and dedication. May the Light shine upon your ways.',12340),
	 (59,0,0,0,0,0,0,0,0,'Ah, thank you for the marker. Please feel free to pick your choice of armor.$b$bLuck to you, brave $C. And may this armor serve you well.',12340),
	 (60,2,0,0,0,0,0,0,0,'You were busy hunting kobolds, were you? Thanks for the candles, $N, and here''s your reward...',12340),
	 (61,1,0,0,0,0,0,0,0,'Here is your payment ... and while you''re here, take a look around! I''m sure we have a potion or other trinket you''d find useful.',12340),
	 (62,1,0,0,0,0,0,0,0,'This is bad news. What''s next, dragons?!? We''ll have to increase our patrols near that mine. Thanks for your efforts, $N. And hold a moment... I might have another task for you.',12340),
	 (63,0,0,0,0,0,0,0,0,'You place the bracers atop the brazier and then pour the remaining drops of Brine''s potion into the flame. The drops crackle as they hit the flame and you begin to incant the simple words Islen taught you....',12340),
	 (64,4,0,0,0,0,0,0,0,'My watch! Thank you so much, kind sir! $b$bWe are but poor farmers and we have lost our land but please accept this reward as a token of our appreciation.',12340),
	 (65,6,0,0,0,0,0,0,0,'So, Stoutmantle sent you? Well, I owe him.',12340),
	 (66,1,0,0,0,0,0,0,0,'Ah so Madame Eva sent you....',12340),
	 (67,0,0,0,0,0,0,0,0,'The old footlocker creaks open. . . .',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (68,1,0,0,0,0,0,0,0,'Interesting. So the chap did spend some time in Moonbrook after all. It is rather odd the letter never got delivered. Nonetheless, I shall update the registry.',12340),
	 (69,6,0,0,0,0,0,0,0,'Stalvan? Sure sounds familiar.',12340),
	 (70,14,0,0,0,0,0,0,0,'You''ve got some nerve bringing this here.',12340),
	 (71,1,0,0,0,0,0,0,0,'You have confirmed my fears, $N. The murlocs are a threat we cannot ignore.',12340),
	 (72,0,0,0,0,0,0,0,0,'You slowly slide the lid of the crate off. . . .',12340),
	 (74,0,0,0,0,0,0,0,0,'I can barely make out those letters. But that writing style reminds me of something I once saw before my vision became so poor.',12340),
	 (75,0,0,0,0,0,0,0,0,'You found it!',12340),
	 (76,5,0,0,0,0,0,0,0,'Kobolds at the Jasperlode Mine, you say? Curses! The situation is worsening by the minute!$B$BThank you for the report, $N. But I wish that the news you brought was good news.',12340),
	 (77,0,0,0,0,0,0,0,0,'Finely executed, $N. I am glad you had enough foresight not to bruise the delicacy of the ripple. There is nothing worse than the bouquet of ripple that has been jostled about needlessly.$b$bIt will take a moment for the magic to be wrought over this precious cargo. Actually, no magic is involved; I merely have some empty packaging for Hinterlands Honey Ripple. Our chicanery shall turn these bottles into an alcoholic treasure of the ages.$b$bOnward - for great booze!',12340),
	 (78,5,0,0,0,0,0,0,0,'By the Light! You bet I recognize that handwriting.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (79,1,0,0,0,0,0,0,0,'My, you have proved yourself to be quite a detective, $C.',12340),
	 (80,5,0,0,0,0,0,0,0,'Why yes! The writing on this page does in fact match that of the registry signatures.',12340),
	 (81,0,0,0,0,0,0,0,0,'Well, let''s see what''s in this barrel!$b$bYes, yes, it looks as though it is all here. Here''s your fee for the package, good job on that. I stand to make five times that fee when I sell it to the tavern! Har har!$b$bThese extra bottles of Hinterlands Honey Ripple are going to be set for a special occasion. I think I''ll drink some with champagne. I''ll call it... champipple.',12340),
	 (82,1,0,0,0,0,0,0,0,'Good work - I''ll start my analysis on these now! I can tell you right from the start though... these are nothing like any insect form I have ever seen. It''s almost as if these bugs are being controlled by an outside force or something.$b$bYou need to go talk to Fizzledowser right away; apparently there is an emergency that he needs your help with on the double! I''m not sure, but I think it involves more of the bugs in the Tanaris desert!',12340),
	 (83,0,0,0,0,0,0,0,0,'Ah, these are nice bandanas, if a little rough...$b$bHere you are!',12340),
	 (84,0,0,0,0,0,0,0,0,'Mm, yum! This pie is the best!$b$bI think my memory is coming back to me...',12340),
	 (85,0,0,0,0,0,0,0,0,'You lost a what? Well I didn''t take no necklace, because I ain''t no thief!$b$bI might know who did but...<grin>...I''m too hungry to remember.',12340),
	 (86,1,0,0,0,0,0,0,0,'Though this wild boar meat is tough, simmer it enough and it sure does make for some tasty pie!',12340),
	 (87,4,0,0,0,0,0,0,0,'Oh, you found it! Thank you, thank you dear!$B$BHere, take this. It was my husband''s and he always said it was lucky. If only he didn''t forget it on his last campaign! *sniff*',12340),
	 (88,1,0,0,0,0,0,0,0,'Thank goodness! That pig was getting so big she''d have eaten our whole crop! Thank you, $N.$b$bNow, do either of these suit you?',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (89,21,0,0,0,0,0,0,0,'Great work, $N. These supplies will help the bridge effort immensely. We''ll get this beauty shored up in no time.',12340),
	 (90,2,0,0,0,0,0,0,0,'Very nice work, $N! Enjoy the delicacy known as Seasoned Wolf Kabob!',12340),
	 (91,66,0,0,0,0,0,0,0,'The Court of Lakeshire recognizes your commitment to justice, $N. By enforcing the laws of the Kingdom you have helped uphold the justice of the land.',12340),
	 (92,21,0,0,0,0,0,0,0,'Well done, $N. Such fine specimens too! And here is your delicious delicacy known as Redridge Goulash!',12340),
	 (93,273,1,0,0,0,0,0,0,'Ah yes, a nice clutch of legs you have there! Let me just get these seasoned with my secret spices (no looking!) and get them to skittering on a skillet for a while...$B$BAnd, although Dusky Crab Cakes are my specialty and I won''t give out the recipe, here''s the recipe for a dish that''s almost as good.',12340),
	 (94,0,0,0,0,0,0,0,0,'You place the Glyph of Azora on the stone. It adheres itself... and you hear from it Theocritus'' disembodied voice:$B$BYou have my gratitude, young $N. You may now speak with me through this Glyph, and I might have future tasks for you... after I have probed the thoughts of my rival.',12340),
	 (95,0,0,0,0,0,0,0,0,'A mound of dirt is here, hastily piled up as if someone had need of hiding something...without much time to do it.',12340),
	 (96,0,0,0,0,0,0,0,0,'This is the proof I asked for. You''ve done well, $N.$B$BI am pleased to be the first to congratulate you and give you this... your water totem.$B$BUse it well, and good luck.$B$BYour next test will not be for some time, so learn your lessons well. Pure water will not only give life back to those who are injured, but can have many other effects. I suggest you seek out a shaman trainer when you have the time. They might have other spells for you to learn.',12340),
	 (97,5,0,0,0,0,0,0,0,'I knew it! Fine work, $N.',12340),
	 (98,1,1,16,0,0,0,0,0,'I know, $N: Stalvan is dead. I sensed a wave of hope ripple through the tainted forest. Once and for all, Duskwood is free from his blood thirst. My joy is hampered by thoughts of those who fell prey to the horrible beast. Nonetheless, you are a brave and cunning $c.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (99,21,0,0,0,0,0,0,0,'Your persistence is commendable. With the knowledge you helped me gather, Arugal will fall and his reckless magic shall be undone. Cheers to you, $N.',12340),
	 (100,0,0,0,0,0,0,0,0,'Thanks to you. Thanks to the shamans.$B$BCorruption ebbs but life continues to wane. Up to shamans to protect life.',12340),
	 (101,1,0,0,0,0,0,0,0,'Very wise of you, $N. This Totem of Infliction will help to protect you against the evil which lurks throughout Azeroth and beyond. When you feel threatened, hold this totem and take comfort in its magical aura. Be brave, fair $C. You will need all the courage you can muster for I see much bloodshed in your future.',12340),
	 (102,66,0,0,0,0,0,0,0,'Well done, $N. With valiant adventurers such as yourself fighting alongside The People''s Militia, Westfall just might return to the prosperous breadbasket it once was. Please accept this in recognition of your tireless efforts.',12340),
	 (103,0,0,0,0,0,0,0,0,'Praise you, brave $C. The rocks of the Westfall Coast shall be lit thanks to your hard work. Many lives will be spared so long as the torch is kept lit.$B$BI died needlessly on this very shore. My afterlife plight is to see that no others follow my destiny.',12340),
	 (104,0,0,0,0,0,0,0,0,'So the foul heathen, Murk-Eye is dead. Well done, $N. By your hands one life was laid to rest but perhaps many more were saved. The Great Sea, wrought with danger as it is, shall be a wee bit safer this night thanks to your heroics.',12340),
	 (105,4,1,0,0,0,0,0,0,'You''ve done it! Araj... the lich is finally defeated!$B$BYou''ve done a tremendous service to the Horde on this day, $N. Your bravery and perseverance are a testament to what it means to be a true hero. Please - accept this as a token for all to see and know that you have delivered the Horde a victory for the ages!',12340),
	 (106,0,0,0,0,0,0,0,0,'Ah! I can''t stand us being apart. I have to see her!!',12340),
	 (107,1,0,0,0,0,0,0,0,'My heart goes out to those two poor souls, Maybell and Tommy Joe. I remember being young and in love, once.$b$bThere must be something I can do to help them! Let me think...',12340),
	 (109,1,0,0,0,0,0,0,0,'Ah, so my friend sent you here? How kind. $B$BWell the Stormwind Monarchy has abandoned our cause. Now it is up to the People''s Militia to keep the land free from corruption. If our cause interests you, I can put your combat skills to use in the name of freedom.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (110,1,0,0,0,0,0,0,0,'Yes, I have the results right here.  They are... unsettling, to say the least$B$BOur initial suspicion that the bugs are being controlled by an outside force, we believe, is correct.  If this is the case, then we are dealing with not only a very powerful unknown force, but also a malignant one.  These bugs have been changed to be pure ravagers.  I''ve never seen anything quite like it.',12340),
	 (111,1,0,0,0,0,0,0,0,'While our families are feuding, Tommy Joe and Maybell don''t have much of a future, but... maybe we can get them together for just a little while.$B$BHm, what can we do...',12340),
	 (112,4,0,0,0,0,0,0,0,'You got them. Good show! Now, just one moment while I concoct the potion...',12340),
	 (113,0,0,0,0,0,0,0,0,'Thank you for delivering the report, Junior Surveyor $n; here is your pay for your diligent service to the Gadgetzan Water Company.$B$BWhile I am usually not thrilled about handing out our valuable information carte blanche to those who would otherwise pay good coin for it, I''ve known Pestlezugg for a number of years now.  If he recommends letting everyone know about it, then so be it.  Give me a moment and I''ll make you a copy.',12340),
	 (114,4,2,0,0,0,0,0,0,'Oh...my! I feel guilty deceiving my family, but my feelings for Tommy Joe are too strong to ignore.$b$bThank you, $N. I''ll drink this liquor as soon as I have the chance and sneak away to my love.$b$bAnd for you... please take this.',12340),
	 (115,1,0,0,0,0,0,0,0,'Thank you, $N. I''ll send these to be destroyed immediately.',12340),
	 (116,21,0,0,0,0,0,0,0,'A job well done, $N! I know well the roads you had to journey to procure this fine array of liquor. But my patrons will be happy once again! $b$bMy wife is quite a seamstress. Please accept this cloak she made in return for your services.',12340),
	 (117,94,0,0,0,0,0,0,0,'Hops and Barley, yeast and malt $bThe taste-buds feel a virtual assault, $bNo need to plead, no need to beg $bFor Thunderbrew Lager comes in a keg!',12340),
	 (118,0,0,0,0,0,0,0,0,'Heh, so old Verner needs some shoes, does he!?!',12340),
	 (119,0,0,0,0,0,0,0,0,'Thank you, this really helps me out.$b$bBut what''s this? Argus sent a note with the crate...What?? Argus wants me to PAY him? Bah!$b$bWell, $N, thank you for your help.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (120,1,0,0,0,0,0,0,0,'At ease, $C.$b$bMagistrate Solomon is a noble leader. His words carry great weight with me. I shall seek the counsel of the King and make the situation clear to him. Assure the good judge that he has the Stormwind Army''s support. Reinforcements will be sent as soon as word is given from His Majesty.',12340),
	 (121,1,0,0,0,0,0,0,0,'Thank you for your time, $C. For your service to Lakeshire and Stormwind I reward you with these coins.$b$bNow if you''ll excuse me, I find this correspondence somewhat of a mystery. Something is amiss in our Kingdom. I fear this is the beginning of conflict, not the end.',12340),
	 (122,0,0,0,0,0,0,0,0,'Thanks! These will get me out of debt to Argus...',12340),
	 (123,1,0,0,0,0,0,0,0,'Hm... I have heard of this "Collector" but I don''t know whom he''s working for. Thank you for the schedule. It will help us solve this mystery.',12340),
	 (124,0,0,0,0,0,0,0,0,'Thank you for all your help, $N.',12340),
	 (125,21,0,0,0,0,0,0,0,'Excellent recovery, $N! I never thought I''d see these tools again.',12340),
	 (126,0,0,0,0,0,0,0,0,'Again, thank you for your help. The Stormwind army is so busy dealing with the orcs, they don''t have the troops to protect Redridge from local threats like the gnolls.',12340),
	 (127,0,0,0,0,0,0,0,0,'Pleasure doin'' business with you, matey!',12340),
	 (128,66,0,0,0,0,0,0,0,'I see you have fought valiantly against the Blackrock Clan, $C. Your service to our township is great indeed.',12340),
	 (129,0,0,0,0,0,0,0,0,'Thanks, I could really use the meal. Guarding Lakeshire from the orcs and gnolls is tough work!',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (130,0,0,0,0,0,0,0,0,'You need a bouquet of flowers? You haven''t been in town very long...have you already found for yourself a sweetheart here?$B$BI know I shouldn''t pry, but it''s nice to see that love is in the air... especially in dangerous times like these.',12340),
	 (131,0,0,0,0,0,0,0,0,'Oh, those are lovely! I can''t wait to put them in some water!$b$bBut...these are Martie''s favorite flowers. Parker didn''t have you go to that jealous vixen for this bouquet, did he? You didn''t tell her who they were for, did you? If you did, then it wouldn''t surprise me if she poisoned them.$b$bOh, but it''s not your fault. Thank you, and here''s your meal.',12340),
	 (132,1,0,0,0,0,0,0,0,'Bah! I should have let that scoundrel rot when I had the chance. But this information is crucial. Good work.',12340),
	 (133,0,0,0,0,0,0,0,0,'Ah, thanks. These will do just the trick!',12340),
	 (134,0,0,0,0,0,0,0,0,'Thank the Nec-...well, thank YOU, $N! You have more than earned your reward.$B$BAha! Happy! Happy nights ahead!!',12340),
	 (135,1,0,0,0,0,0,0,0,'This matter might be more complex than Stoutmantle realizes.',12340),
	 (136,0,0,0,0,0,0,0,0,'The footlocker slowly creaks open. Sand and water seem to be its only contents. But wait! A small crab scurries out with a clue to the treasure in his claws!',12340),
	 (138,0,0,0,0,0,0,0,0,'Good work, treasure hunter!',12340),
	 (139,0,0,0,0,0,0,0,0,'You''re on your way to the jackpot, treasure seeker!',12340),
	 (140,0,0,0,0,0,0,0,0,'The hinges on the old chest are rusty but they still work. You force the chest open and take the booty.$B$BCongratulations!',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (141,1,0,0,0,0,0,0,0,'Edwin VanCleef. . .I know the name well. To think that a man so industrious and talented could turn into such a scoundrel unnerves me. I''ll need further proof before I believe this.',12340),
	 (142,1,25,0,0,0,0,0,0,'This is indeed firm proof that VanCleef is in charge. Now all we need to know is where the Defias gang is hiding out.$b$bWe''ve had a stroke of luck while you were gone. We captured a thief trying to steal Saldean''s wagon. He has promised to lead us to the hideout in exchange for his life. I want you to defend the traitor so he can reveal the hideout. Return to me once you have uncovered the location.',12340),
	 (143,1,0,0,0,0,0,0,0,'Good Messenger, you have served your master well.',12340),
	 (144,1,0,0,0,0,0,0,0,'I do say, this is not good at all. I did not realize that Stoutmantle''s situation was not unlike ours here in Lakeshire. What action is so important that it calls the Stormwind Army away from its people? Bah, I should not ponder aloud.$b$bHere, messenger. Accept these coins in exchange for your service to the Township. I might call upon you again.',12340),
	 (145,0,0,0,0,0,0,0,0,'Thank you for making the long journey here. This is indeed important information.',12340),
	 (146,5,6,1,0,0,0,0,0,'By the Light! The Stormwind Army retreated from Westfall. And the Guard no longer protects Darkshire? There is some treachery abound. How could this be so? $b$bOh I forgot to reward your service, $C. Here are some coins. Now excuse me. Something is amiss in Stormwind and I must get to the bottom of it.',12340),
	 (147,1,0,0,0,0,0,0,0,'You found him? Well done, $N. He won''t be "collecting" from the Elwynn Mines again!$B$BAnd this ring you found is interesting... it''s a membership ring for the old Stonemason''s Guild in Stormwind. Why would a lowly thief have an artisan guild ring, and why are the Defias Thieves collecting money from our mines?$B$BDifficult questions. I hope one day we''ll have answers.',12340),
	 (148,1,0,0,0,0,0,0,0,'Ah, Ghost Hair Thread is what you need, is it? I''m afraid I have none in stock, but I can make some for you...if you can supply the ghost hair.',12340),
	 (149,0,0,0,0,0,0,0,0,'What is this? A comb? It''s lovely! And it glides through my hair as if it weren''t the stiff, stringy horror that it is.$B$BOh, if only I had a mirror...',12340),
	 (150,0,0,0,0,0,0,0,0,'Well done, $N. I hope you didn''t have too much trouble with those murlocs.$B$BIt''s strange seeing them so far from the sea. I wonder if they''re here because they''re running from something...',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (151,21,0,0,0,0,0,0,0,'Thank you so much, $N! Poor Old Blanchy will be so happy!',12340),
	 (152,0,0,0,0,0,0,0,0,'Well done, $N. You have quite a knack for combat. Thanks to you the Coast of Westfall is a safer place.',12340),
	 (153,66,0,0,0,0,0,0,0,'Nice work, $R. Please accept one of these items as payment for all your hard work.',12340),
	 (154,1,0,0,0,0,0,0,0,'I can make a spool of Ghost Hair Thread with this, and have a few strands to spare. Here are some coins for those extra strands.',12340),
	 (155,21,0,0,0,0,0,0,0,'Most excellent, $N! VanCleef is as good as ours now that we know where he is hiding.',12340),
	 (156,2,0,0,0,0,0,0,0,'Good, you got the rot blossoms. And I''ll tell Althea Ebonlocke of the Night Watch that you were killing skeletons.$B$BKeeping the people of Darkshire safe is a grim burden for the Night Watch, and news that others are helping stem the tide of fiends in Duskwood is welcome news indeed.',12340),
	 (157,0,0,0,0,0,0,0,0,'Delightful! This will do splendidly...$b$bHere, good $N, take this as payment for your honorable deed.',12340),
	 (158,0,0,0,0,0,0,0,0,'You need some Zombie Juice, do you? Hmm...that''s some strong stuff - I don''t usually get requests for it.',12340),
	 (159,0,0,0,0,0,0,0,0,'A thousand thanks, $N. You warm an old man''s heart with your foolish-...I mean...with your kindness!$b$bHere you are, friend. Take this as a token of my gratitude.',12340),
	 (160,6,0,0,0,0,0,0,0,'<Ello looks at the letter...>$B$BWhat language is this? It looks ancient...I can''t read it.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (161,1,0,0,0,0,0,0,0,'Ah, well Ol'' Hinderweir is wise to be worried.',12340),
	 (162,1,0,0,0,0,0,0,0,'This report... we night elves know of the terror mentioned here.  Fizzledowser was wise to send this, and you, to me.$B$BThese creatures will consume the Tanaris desert rapidly; they are nothing short of one of the greatest menaces we all will ever face.  Familiarize yourself with this name, $n: silithid.  The insects mentioned here are the silithid, and they are the tools of one of the greatest threats that both the Horde and Alliance face.$B$BIf only we were smart enough to see that before.',12340),
	 (163,430,0,0,0,0,0,0,0,'No! Please don''t kill me! It''s just me... Jitters!! They''re everywhere... I can''t escape them! Monsters in Raven Hill? N-n-n-o... couldn''t be. Only harmless Jitters.',12340),
	 (164,1,0,0,0,0,0,0,0,'These supplies will be most useful. The aid of the Carevin family is always appreciated. Here is a little something for your trouble.',12340),
	 (165,0,0,0,0,0,0,0,0,'Hehe, oh yes... of course, the Carevins.$B$BNo, nothing''s wrong but it is hard for me to go into town now. The roads are dangerous and I''m not getting any younger. Maybe you can do an old man some favors?',12340),
	 (166,66,0,0,0,0,0,0,0,'$N, your bravery is remarkable. The People''s Militia thanks you for your service to the people of Westfall. With VanCleef dead, this marks the beginning of the end for the Defias Brotherhood. Hopefully some day soon peace will once again grace the plains of this fair land.$B$BI salute you, $gLord:Lady;!',12340),
	 (167,1,0,0,0,0,0,0,0,'My suspicions were correct. My poor brother.... Well, thank you for bringing some conclusion to this mystery, even if the conclusion was grim.',12340),
	 (168,1,0,0,0,0,0,0,0,'Thank you for collecting these, $N. Your efforts will help bring peace to the dead in the wake of this tragedy. I will see to it that the families are notified.',12340),
	 (169,21,0,0,0,0,0,0,0,'Fantastic work, $N! Gath''Ilzogg led those brutes into battle, killing many innocent humans. Vindication is ours. This is the first step in reclaiming the keep for the kingdom of Stormwind!',12340),
	 (170,1,0,0,0,0,0,0,0,'If the problems we''ve had here are indicative of what is happening elsewhere in our lands, by Magni''s beard, we have some troubles ahead of us! I can only hope that the king and Senate are taking steps to deal with the threat the troggs pose.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (171,4,2,0,0,0,0,0,0,'May the heavens bless you, $N. You''ve done more for Randis than most would ever think of doing for him. Thank you - you''re a shining star in the skies of the Alliance.$b$bPlease - if you can spare the time, come back and visit us. I know that Randis would like that, as would I.',12340),
	 (172,0,0,0,0,0,0,0,0,'Zug zug! My name is Grunth, and I guess you''re looking after me? You''re an adventurer, like my mom and dad were. My matron says that they died with honor in battle. I''m happy to meet you.$B$BI hope we''ll do plenty of things together. I have some things I''d like to do, and the matron says you''ll be like a big brother to me during this week. I''d like that a whole bunch.',12340),
	 (173,0,0,0,0,0,0,0,0,'Impressive, $N. It would seem that you are capable enough to handle yourself. Perhaps a more suitable challenge could be found for one of your abilities.$b$bIt is curious though... The worgen seemed to just appear out of thin air. But then, with all the other strange creatures that have moved across our borders, I suppose it''s only one of many concerns.',12340),
	 (174,21,0,0,0,0,0,0,0,'This is perfect, $N. The first step is complete!',12340),
	 (175,0,0,0,0,0,0,0,0,'Why yes, I used to own a looking glass.',12340),
	 (176,4,0,0,0,0,0,0,0,'Hah! Well done! I was starting to think no one would take down that monster!$B$BHere you are, $N. And thanks - that Gnoll was giving me a headache the size of Blackrock Spire!',12340),
	 (177,2,0,0,0,0,0,0,0,'Most superb! This will work perfectly. Many thanks!',12340),
	 (178,1,1,0,0,0,0,0,0,'You have my gratitude, $N. I sent that message to the Shadowhide Pendants weeks ago and had believed it a failure. But it seems the spell did reach at least some pendants, after a significant delay.$B$BIn time I hope to learn how to send an attack through the pendants, to immobilize any Shadowhide Gnolls who wear them.$B$BBut before that is possible, I''m afraid that much more research is required.',12340),
	 (179,1,0,0,0,0,0,0,0,'Ah! Wonderful. The wolf meat should do nicely. Oh, don''t worry, $N, I wouldn''t forget my part of the bargain. Here, one of these should fit you.',12340),
	 (180,6,2,0,0,0,0,0,0,'So the evil Lieutenant Fangore is dead? Good riddance to that foul creature. You are very brave, $C. The Township of Lakeshire thanks you for your aid.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (181,4,0,0,0,0,0,0,0,'At last! The stargazing device is complete! Thank you, $N. Now I can continue my research. . .',12340),
	 (182,5,0,0,0,0,0,0,0,'Argh! Those Light-blasted trolls!$B$B<He takes a few breaths and seems to settle down... a bit.>$B$BA group of them came in the night and stole my journal! I knew better than to trust that good-for-nothing appr...',12340),
	 (183,2,0,0,0,0,0,0,0,'Excellent! I can go back to my... leisurely... hunting now. Thank you, $N.',12340),
	 (184,1,0,0,0,0,0,0,0,'Loads of thanks, $N! As I was saying, these parts aren''t fit for honest folk anymore, but if things get better, then this deed will let us reclaim our land.$b$bI don''t have much to offer you, but here -- take this.',12340),
	 (185,21,0,0,0,0,0,0,0,'Nicely done, $n.  You are ready to move on.',12340),
	 (186,21,0,0,0,0,0,0,0,'I am impressed, $c.  You are progressing quite well.',12340),
	 (187,21,0,0,0,0,0,0,0,'Most impressive.  I believe you are almost ready.',12340),
	 (188,21,0,0,0,0,0,0,0,'Most impressive, I do say!  You are a true Master Tiger Hunter, $N!',12340),
	 (189,21,0,0,0,0,0,0,0,'Oh excellent, excellent. That''ll help a little, for the present...$b$b<He trails off, grumbling about profit margins and costs...>$b$bWhat? You''re still here? Reward? Oh, right... of course, here, take this... it should be more than enough.',12340),
	 (190,21,0,0,0,0,0,0,0,'Off to a good start, $N!',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (191,21,0,0,0,0,0,0,0,'Perfectly executed, $N!',12340),
	 (192,21,0,0,0,0,0,0,0,'You''ve done well, $N!',12340),
	 (193,21,0,0,0,0,0,0,0,'So the great Bhag''thera is dead!  Cheers to you, $N.  You are a mighty $c indeed!',12340),
	 (194,21,0,0,0,0,0,0,0,'Nicely done, $g old chap : m''lady;!',12340),
	 (195,21,0,0,0,0,0,0,0,'Now that''s how you get a trophy or two over the ol'' hearth!  Nice killing, $N!',12340),
	 (196,21,0,0,0,0,0,0,0,'Ho ho!! We have ourselves a true raptor slayer!  Nicely done, $g old chap : fair lady;!',12340),
	 (197,21,0,0,0,0,0,0,0,'$G Master : Mistress; $N, the raptor slayer!$b$bHas a nice ring to it, eh?',12340),
	 (198,0,0,0,0,0,0,0,0,'These land mines will help us defend ourselves from that animal Kurzen and his men. Thank you for bringing them. If you need further work, I can probably find something for you to do. And you won''t have to deal with those goblins, hm?',12340),
	 (199,5,0,0,0,0,0,0,0,'This is an alarming discovery, to say the least!',12340),
	 (200,0,0,0,0,0,0,0,0,'These are Bookie Herod''s notes and records.$b$bAmong them are: a list of supplies within the camp, material requests from Colonel Kurzen, and various letters and correspondences.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (201,0,0,0,0,0,0,0,0,'Hmmm, so my information was correct, as usual. Interesting. Well, I don''t suppose they pose any sort of threat of interference with our operation, but perhaps they have a need for some of our excellent manufactured products. Hmmm...',12340),
	 (202,0,0,0,0,0,0,0,0,'I dared not believe the reports, but you bring us proof that... Kurzen and his leaders are defeated. You have saved us!$B$BThese jungles are filled with menaces of all types, but none had the cruel intellect of Kurzen. We may all breathe easier now that he is gone.',12340),
	 (203,0,0,0,0,0,0,0,0,'Well done. The loss of those Jungle Fighters will relieve some of the pressure on our camp.$b$bBut now that you''ve had a taste of the forces we''re up against, do you still want to throw your lot in with us??',12340),
	 (204,0,0,0,0,0,0,0,0,'Well done, $N. These remedies will keep more of us alive and in fighting shape. And the extracts will help us create our own remedies.',12340),
	 (205,0,0,0,0,0,0,0,0,'Thank you.  I will study these fetishes and see if they hold the secret of Kurzen''s fall into evil.',12340),
	 (206,0,0,0,0,0,0,0,0,'Aha! You''ve done it! You are a great force for good, $N, and may your strength never fade!$B$BI will study this Mind''s Eye and determine if it may be used for good. If not... then it must be destroyed.',12340),
	 (207,0,0,0,0,0,0,0,0,'Thank you, $N. I will study these legends to see if there is some link between the trolls and the evil that has possessed Colonel Kurzen.',12340),
	 (208,21,1,1,4,0,0,0,0,'Bloody well done!  Right-o!  Congratulations, $N, for succeeding where others have failed.$b$bI am honored to count you as a comrade of our great hunting party here.  No one will ever doubt your expertise in hunting and tracking!$b$bCheers to you, I say!  Cheers!',12340),
	 (209,0,0,0,0,0,0,0,0,'Ah, good work, good work! Ugh, though you could have done a better job cleaning off the-- Well, no matter, no matter! My thanks to you, $N, our operation will no doubt see increased output and productivity thanks to your help! Good good, now, onto other matters...',12340),
	 (210,0,0,0,0,0,0,0,0,'Oh I see, it''s a Krazek''s Crock Pot! An ingenious piece of work, but it can break a spring or throw a gear now and then. Let me see what''s wrong with this one...$b$bAha! Its steam charger is rusted out, it has a cracked knuckle-gasket and its fobulator is missing teeth. I''m surprised the pot could even boil a turnip in this state!$b$bCan I fix it? Of course I can fix it!$b$bBut there''s a price. Oh yes, there is always a price...',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (211,4,1,0,0,0,0,0,0,'You''ve done it!  Araj... the lich is finally defeated!$B$BYou''ve done a tremendous service to the Alliance on this day, $N.  Your bravery and perseverance are a testament to what it means to be a true hero.  Please - accept this as a token for all to see and know that you have delivered the Alliance a victory for the ages!',12340),
	 (212,4,1,0,0,0,0,0,0,'Ah, this will do nicely! Many, many thanks!$b$bNow if you''ll excuse me, I must get the haunch chopped, marinated and garnished for the banquet.',12340),
	 (213,0,0,0,0,0,0,0,0,'Fascinating. That the crystals have been tumbled using this process can only indicate that they are planning to use them as some sort of fuel or other catalyst. I don''t know much more than that. Samples will have to be dispatched to Head Chemist Gigglefont.',12340),
	 (214,66,0,0,0,0,0,0,0,'Well done, $N! On behalf of The People''s Militia I salute you for your efforts. Soon we will return this land to the people with help from brave souls like you.',12340),
	 (215,0,0,0,0,0,0,0,0,'Yes, what Thorsen told you is true. You must be discrete with this. At one time, we rebels were fiercely loyal to Colonel Kurzen. But such was Kurzen''s corruption, our passion twisted into rage.  If it was made known that Private Thorsen has had recent dealings with Kurzen''s men, then one night he would find himself with a slit throat.$b$bTo my knowledge, only Sergeant Yohwa, Thorsen and I were privy to Thorsen''s mission. But there must be another. A traitor.',12340),
	 (216,4,0,0,0,0,0,0,0,'Well done $C, well done! I will continue to send forces to thin out the furbolg, but I can at least count on a different path that will be free of Alliance entanglements. The Horde conquest of Ashenvale is now in full swing!$b$bYou''ve earned your pay this day, hero. I salute you!',12340),
	 (217,66,0,0,0,0,0,0,0,'Most excellent, $N! You have brought hope to Loch Modan. With Grawmug dead, we stand a better chance of seeing the Troggs eliminated from the land.',12340),
	 (218,1,0,0,0,0,0,0,0,'Wonderful, $N! Many thanks for retrieving my notebook. Well, it would seem that the troll situation here in Coldridge Valley is under control and not much cause for worry.$b$bAfter I put the finishing touches on my report, I''ll need someone to courier it to my brother Senir.',12340),
	 (219,66,0,0,0,0,0,0,0,'You have served the Kingdom well, $C. Thank you for assisting Corporal Keeshan with his escape from those dreaded Blackrock Orcs. You shall be rewarded for your brave acts this day.',12340),
	 (220,0,0,0,0,0,0,0,0,'Ah, a vial of water created and blessed by Brine, and gathered by you, no less.$B$BThe liquid in this vial will be key in creating a sapta for you, but also used in one other task.$B$BThe sapta I create for you should be used to see the water spirits at the shrine in Silverpine Forest, south of the Undercity. The remaining drops, well, the remaining drops I will tell you about if you feel you are ready.$B$BAre you prepared for one more journey, $N?',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (221,0,0,0,0,0,0,0,0,'You performed well against the Dark Runners, $N. But it seems as though their numbers are inexhaustible. Every time we make progress, more spring up to refill their ranks.$b$bWhat is the evil power that draws them here? Why have they come to disturb our unhappy realm...$b$bI will put my faith in Master Carevin. No doubt he will get to the bottom of the problem.',12340),
	 (222,0,0,0,0,0,0,0,0,'$N, to be honest with you, I did not believe that you would get this far, but you are clearly a $C to be reckoned with. In fact, if you wish to formally join Master Carevin''s struggle, I will gladly write for you a letter of recommendation.',12340),
	 (223,0,0,0,0,0,0,0,0,'Excuse me for my cold reception, $N, but as I''m sure you can tell, I am an extremely busy man. I see that you have impressed Calor--and I assure you, that is no small feat--and that he has given his recommendation.$b$bThere are unsavory types afoot, $N, and we can use the help of all who have proven themselves. We battle against demons, the undead, and those who would provide them aid. Be vigilant, be wary, and trust none who would not give aid to our cause.$b$bGlory under the Light.',12340),
	 (224,66,0,0,0,0,0,0,0,'Well done, $N!  You demonstrated uncanny courage on the battlefield.  Our war against the Troggs will be won with efforts such as yours.  You have served King Magni well.$b$bIf you fancy yourself well-suited for this kind of adventuring, I suggest you speak with Mountaineer Gravelgaw.  The Captain has him assigned to a rough patrol that I am sure he can use some help with.  Check with Gravelgaw just inside the tower.',12340),
	 (225,6,1,1,0,0,0,0,0,'Morgan Ladimore?$b$bAhh, yes, of course. His was a long and sorrowful tale. I knew him, well, before he left for the war, but that was the last time I saw him. A noble and good man, he was, but he suffered a bad end.$b$bHere, I should have something here that can tell the tale better than my own recollections...',12340),
	 (226,2,0,0,0,0,0,0,0,'Oh good. You thinned out that pack quite a bit, and without those wolves nipping out our heels, we can bind our minds to dealing with Morbent Fel.$B$BHere, take some of these Flash Bundles. They make them in town, and a lot have been donated to Sven to help with his cause.',12340),
	 (227,274,6,1,1,0,0,0,0,'Morgan Ladimore? Never heard of...$b$bOh, you mean Mor''Ladim! I guess you haven''t heard the story?$b$bWell, I''ll give you the short version. A wandering undead calling itself Mor''Ladim has been wandering Duskwood. From what we''ve gathered, it appears to be the undead body of Morgan Ladimore, of whom you apparently know. He''s been causing us all sorts of problems, attacking Watchmen on patrol and killing people.$b$b<She sizes you up.>$b$bYou seem to be capable enough, maybe you could lay him to rest.',12340),
	 (228,6,66,0,0,0,0,0,0,'You killed him? That''s no small accomplishment, $N! On behalf of the people of Darkshire and the Night Watch, I thank you.$B$BAh... there is one small matter, however...',12340),
	 (229,6,1,0,0,0,0,0,0,'Yes? My father...$B$B<Her eyes become downcast.>$B$BI wish... there was something I could have done for him... If only I had talked to him before he...',12340),
	 (230,0,0,0,0,0,0,0,0,'<Sven reads the book''s pages, then slams it shut.>$B$BThat shadowy figure I saw was a witness to my family''s death! There are questions I''d like to ask that man...if only I knew who he was!',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (231,0,0,0,0,0,0,0,0,'<A ghostly voice sounds on the wind...>$B$BThis is...? Sarah? Could it be she''s still alive? The weight is removed from my shoulders...$B$B$N. Take my sword, Archeus. As my soul is put to rest, I have no more need for it. It was forged to do good, and though I have proved myself unworthy to hold it, perhaps you will carry on the Light through it.$B$BLys, my love...',12340),
	 (232,1,0,0,0,0,0,0,0,'Ah, Zinge needs a kit, does she?  It saddens me that Zinge does not choose to grace myself with her sweet presence.$B$BVery well, let me procure a kit for you.',12340),
	 (233,1,0,0,0,0,0,0,0,'Thank you, I''ve been waiting for these letters for quite some time...$b$bUnfortunately, these letters aren''t all for me. This one is addressed to Grelin Whitebeard. He''s not too far away if you''d like to deliver it to him.',12340),
	 (234,1,0,0,0,0,0,0,0,'Ahh, excellent. It''s been a while since I received word from Ironforge.',12340),
	 (235,1,0,0,0,0,0,0,0,'Welcome to the new frontier, $N. Ashenvale is a land of opportunity, one where a young $C like yourself is able to find boundless chances to prove their mettle. Look around the outpost here, and be sure to travel out to the Zoram Strand, as the Horde has another outpost there as well.$B$BYour presence here tells me that you''ve come to learn more about the hunt. Listen close, and I will gladly share with you what you need to know.',12340),
	 (236,0,0,0,0,0,0,0,0,'Excellent! This will help fuel the flames of war for days to come. ',12340),
	 (237,1,1,0,0,0,0,0,0,'You accomplished your mission well, $r.  The King himself would be proud.$b$bThe reinforcements promised to us never showed, however.  Apparently the Alliance front is a sea of crimson from the blood of our fallen brethren.  The news of the losses leaves a bitter taste in one''s mouth.  But we must not let their deaths go for naught.  We must rally in these grim times and bring glory back to the Alliance.$b$bSpeak with Mountaineer Wallbang for reassignment.  You''re needed now more than ever.',12340),
	 (238,0,0,0,0,0,0,0,0,'Good - it pleases me to be working with someone who takes pride in not wasting my time.$b$bAfter I make some adjustments to this kit, you''ll be ready to head out into the field. You''ll be using it to collect some vital data to the task at hand.$b$bIt will take just a moment for me to finish the modifications. While you are waiting, you should probably start thinking about what you''d like to bring to the desert with you.$b$bYes, I said the desert.',12340),
	 (239,1,0,0,0,0,0,0,0,'Marshall Dughan sent you, eh? Well you''re not from the army, but if Dughan sent you then that''s good enough for me!$b$bOur situation is, to say the least, a stressed one. I hope you can give us a hand.',12340),
	 (240,2,1,0,0,0,0,0,0,'Aha! Thank you, $N. Those really hit the spot!$B$BAnd here, please let me pay you for these!',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (243,0,0,0,0,0,0,0,0,'Ah, our model 4711-FTZ power sources! We normally use them to power the water wells, but THANKS TO THE VILE NOMADS, we have an over abundance of power sources right now.$b$bSure, I can get you a power source for whatever nefarious science experiment you think you''re trying to hide from me. It ain''t gonna be free though, $R. Nothing''s free in Gadgetzan.',12340),
	 (244,0,0,0,0,0,0,0,0,'There are Redridge gnolls that close to Elwynn?? They may be poised to advance into our homeland. Soon the people of Lakeshire may not be the only humans under siege!$b$bHere is your pay, though you bring us dire news. And it comes at a bad time, for we are ill equipped to deal with it.',12340),
	 (245,0,0,0,0,0,0,0,0,'Ah! You''re back. And not too much worse for wear, it''d seem. Of course, $N, the Night Watch is grateful for your work, and I did promise you a reward, so here.',12340),
	 (246,0,0,0,0,0,0,0,0,'<Deputy Feldon listens to your report...>$b$bThere''s a sizable force of gnolls encamped there, and from what you tell me they are tough ones. It must not have been easy for you to gather this intelligence.$b$bHere you are, $N. We are grateful for your aid.$b$bAnd if you haven''t already done so, speak with Marshal Marris and Magistrate Solomon within Lakeshire. Our situation grows ever more desperate - those two will have need of you I''m sure.',12340),
	 (247,0,0,0,0,0,0,0,0,'$N, you have slain all three beasts that comprise the Ashenvale Hunt. You have brought me adequate proof of their demise; there is no question of your strength and tenacity. The blood of a hunter streaks through your veins, and you should be commended!$B$BPlease, accept this bauble as a sign of congratulations on your mighty deeds done in Ashenvale for the Horde today. May your ancestors watch over you!',12340),
	 (248,0,0,0,0,0,0,0,0,'It is a suitable vessel for the Glyph of Azora, allowing Theocritus to delve into the minds within Stonewatch Keep.',12340),
	 (249,21,1,2,0,0,0,0,0,'You have done well, $N. In defeating the warlock Morganth, Stormwind is saved from a grave peril.$B$BI offer you this reward most humbly. And I would bid you peace, if these were peaceful times.$B$BBut instead, I will bid you luck with your trials, and victory in the conflicts ahead.',12340),
	 (250,0,0,0,0,0,0,0,0,'The suspicious looking barrel contains a strange smelling powder.',12340),
	 (251,0,0,0,0,0,0,0,0,'<Sirra begins translating the note...>',12340),
	 (252,0,0,0,0,0,0,0,0,'<Ello reads the letter...and his face goes white. He then looks at you...>$b$bAlthough the aid you gave Abercrombie may have been motivated from kindness, your actions have doomed our town.$b$b<Ello becomes lost in his thoughts...>',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (253,4,0,0,0,0,0,0,0,'You''ve done it! The magic within his heart will be proof against the Embalmer''s evil, and a powerful aegis over the town of Darkshire.$B$BYou have done a great thing for our people, $N. Your name will remain in our annals forever.',12340),
	 (254,0,0,0,0,0,0,0,0,'You dig through the semi-loose dirt over the grave...and find the remains of a coffin.$B$BWithin the coffin you can feel the vibrating scrapes of clawed fingers and the gnashing of rotted teeth...$B$BWill you open the coffin and retrieve the Embalmer''s heart?',12340),
	 (255,1,0,0,0,0,0,0,0,'Ah, this is excellent news! Your efforts are greatly appreciated by myself and the people of Thelsamar. Better yet, if we can solve the ogre problem, we''ll be able to shift our focus to those Light-burning troggs.',12340),
	 (256,5,1,0,0,0,0,0,0,'Yech! What is that thing? And why would you bring it...$b$bBloody--! Is it? Well, Light burn me, is that the head of that bloody ogre? This certainly is a catch then! Here, your reward and the thanks of myself and the people of Thelsamar.',12340),
	 (257,6,1,1,0,0,0,0,0,'What? Success?$B$BTake it from me, $Nama, you don''t let it get to your head. I mean, any unshaven boy with a bow could have killed such... small specimens. And I hope you don''t enjoy killing the buzzards so much, yes? We wouldn''t want them to become extinct.$B$BWell, err... Never let it be said that Daryl the Bold would not hold to his word.',12340),
	 (258,1,1,6,0,0,0,0,0,'You seem a bit worse for wear. No doubt the boars gave you some trouble, hm? No worries, I will be discreet about your struggle, I can imagine how hard it must be for you without the accusations of wagging tongues.$B$BOh! You managed to kill the boars? I... well, that is... that is to say, I''m not surprised! Any child could have--bet?$B$BWhat bet?',12340),
	 (261,21,1,0,0,0,0,0,0,'You have proven your resolve, and the Scarlet Crusade commends you.$B$BIf you do not shy from righteous slaughter, then perhaps your path lies with us...',12340),
	 (262,1,1,0,0,0,0,0,0,'Hmm... Someone handled this book recently, someone who is driven by revenge. But the impressions left on it, at least the impressions from the original owner, are faint.$b$bI can tell, however, that the original owner of this book is not a native of Darkshire.',12340),
	 (263,66,0,0,0,0,0,0,0,'I knew the second I laid eyes on you, $N, that you would make Ironforge proud. You have served King Magni well. Now that you''ve proven yourself to be such a loyal aid to the Kingdom, perhaps you should talk with the Captain to see if he''ll entrust you with a higher detail.$B$BI salute you, $N.',12340),
	 (264,0,0,0,0,0,0,0,0,'You place the worthless pendant on the grave, and the gemstone within the setting seems to dull noticeably.$b$bAs you stand to leave, you look down at the pendant; it lies lifelessly over the hands of the relief sculpted into the top of the coffin. Your thoughts are interrupted by a stiff, cool breeze passing over the Sepulcher. For a moment everything around you is silent.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (265,1,0,0,0,0,0,0,0,'Ah, yes. I sold this book a month ago to a shady person. He didn''t tell me his name, but he was a nervous, jittery chap, always looking over his shoulder.$B$BI hope that helps you...',12340),
	 (266,1,1,0,0,0,0,0,0,'Oh yeah, I remember this book. Its owner rented a room for a few days, and spent his nights at the bar, writing.$B$BHe left town in a hurry, muttering about being hunted by...something. Last I saw him he was heading west out of town, looking for a new spot to hide.$B$BThe first place he''d find to the west is Raven Hill...',12340),
	 (267,66,0,0,0,0,0,0,0,'I am quite impressed, $N.  You have done the Dwarven race a great favor by defending our lands.  King Magni Bronzebeard himself would be proud!',12340),
	 (268,1,0,0,0,0,0,0,0,'This journal explains much to me, and sets me on the path against the dark riders! I have seen these riders in Duskwood, and have seen them speak with the wizard Morbent Fel, at the Forlorn Rowe.',12340),
	 (269,0,0,0,0,0,0,0,0,'<After reading the journal and hearing your intent...>$B$BAn evil taint has gained a foothold within the already beleaguered Duskwood. I thank the Light we have a hero such as you to face it.$B$BBut you must first prepare yourself for the coming trial...for the Necromancer Morbent Fel is immensely powerful, and has cast dark enchantments about himself to protect him from physical assaults. If you are to defeat him, you will need a weapon that is proof against these protections.',12340),
	 (270,1,1,0,0,0,0,0,0,'Lightforge Iron is a precious metal, but it sounds like your quest is a dire one. You''ve come a long way, $gBrother:Sister;. With luck, you might just find what you seek!$B$BAnd if you do get the iron, I know who can fashion it into a weapon against this Necromancer you speak of in Duskwood.',12340),
	 (271,6,1,5,0,0,1000,1000,0,'Er... what''s this? A bear''s head, by the looks at it.$B$B<He runs a finger along his scar unconsciously.>$B$BWell, that''s quite an interesting kill you have yourself there. Couldn''t be that bear from back then...$B$B<He trails off then starts to visibly shake.>$B$BOh, take that away take it away! Get that grisly thing out of here!',12340),
	 (272,0,0,0,0,0,0,0,0,'You''ve completed the Trial of the Sea Lion, $N - congratulations.$B$BEach task in acquiring the pendant shows that both agility and endurance are necessary to act in harmony with what you desire to do underwater. Neither can exist without the other, and both cannot be done without you willingness to embrace the aspect of the sea lion.$B$BRemember these lessons well, and count on them once you have gained your aquatic form.',12340),
	 (273,5,1,0,0,0,0,0,0,'Hmph, it''ll take more than a Dark Iron ambush to stop the deliveries!$b$bBut Saean... I would never have suspected him to be one of their sympathizers. We''ve been working with him for almost a year now... maybe I missed the signs.$b$bWell, I''ll consider that later.',12340),
	 (274,5,0,0,0,0,0,0,0,'A disarming colloid? For Seaforium? Oh heavens!',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (275,0,0,0,0,0,0,0,0,'This land is soothed by your efforts, and for this I will grant you a boon.',12340),
	 (276,0,0,0,0,0,0,0,0,'By reducing the Gnolls'' number, you have tended to the health of the Wetlands. Although my faith in your people has been taxed in the past, $R, it may yet be restored.',12340),
	 (277,0,0,0,0,0,0,0,0,'... thank you. I will smash these flints and cast them into the sea, so that they may never again be used to burn living wood.',12340),
	 (278,0,0,0,0,0,0,0,0,'Just in time, $N!',12340),
	 (279,21,0,0,0,0,0,0,0,'Ah, well done $N.$b$bAccept this as payment for fulfillment of your contract with the Merchant Marines.',12340),
	 (280,0,0,0,0,0,0,0,0,'The keg fizzles slightly as the Disarming Mixture settles in.',12340),
	 (281,0,0,0,0,0,0,0,0,'This crate is covered with clawed scratches, and the marks of water damage. Prying it open reveals soggy and rotted straw, as if something of value was stored in the crate. You search through the straw...$B$B...and find a an armload of red-colored bottles.',12340),
	 (282,1,0,0,0,0,0,0,0,'Hm, well, if Whitebeard is sending you to Dun Morogh on important business, I can''t very well stop you, can I?$b$bAt least let me provide you with some advice and directions.',12340),
	 (283,4,2,0,0,0,0,0,0,'Thank you so much, $N!! You have saved the Stonewrought Dam! Without your help, the Dark Iron terrorists would have surely seen to this mighty landmark''s demise. You have made the Kingdom and the Alliance proud, brave $C.$b$bThe Dam is once again safe. . . for the time being at least. . . .',12340),
	 (284,0,0,0,0,0,0,0,0,'This barrel is largely untouched. Prying it open...$B$B...you are assaulted by the pungent odor of cheese. It''s a little wet, but still tasty!',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (285,0,0,0,0,0,0,0,0,'This barrel is halfway buried amidst the mud and grass ...',12340),
	 (286,0,0,0,0,0,0,0,0,'The captain of the Blind Princess will be relieved to hear this precious cargo has been recovered. You have well earned this payment for services rendered.$B$BIt is good to see dependable folk like you, especially in trying times such as these.',12340),
	 (287,0,0,0,0,0,0,0,0,'Ah, $n! I didn''t think you''d have much trouble finding the place, my directions are excellent, you know...$b$bLet me just finish up my report then.$b$b<He brings out some paper and scribbles on it momentarily.>$b$bThere! Well, haha, now this certainly is funny... I don''t suppose, $n, that you would mind doing one last favor for me?',12340),
	 (288,4,0,0,0,0,0,0,0,'Ah! That hits the spot, and loosens the tongue. Thanks, mate!',12340),
	 (289,2,0,0,0,0,0,0,0,'My thanks to you, $N. And the gratitude of my cursed brethren goes to you as well.',12340),
	 (290,0,0,0,0,0,0,0,0,'The key is rusted but it fits the lock neatly.',12340),
	 (291,0,0,0,0,0,0,0,0,'<He quickly peruses the report.>$b$bAuthority of the KING!? Has Magni taken complete leave of his senses! And that damnable Whitebeard... Taken matters into his own hands, has he? The Senate will not be pleased to hear about this, not one bit.$b$bWhat, are you still here? Go, before I call the guards!',12340),
	 (292,1,0,0,0,0,0,0,0,'An Eye of Paleth? Amazing! Hmm... there''s something wrong with this one. You found it on one of those shipwrecks? Well that explains it! But... I didn''t know they had such an Eye on the Third Fleet...$B$BIt''s no wonder Fitzsimmons was so spooked. A Cursed Eye of Paleth is no cause for mirth.',12340),
	 (293,1,0,0,0,0,0,0,0,'An Eye of Paleth. But this one has seen much sorrow...it must have been witness to a terrible, terrible tragedy.$b$bLet me cleanse it, for the Eyes were created to shine bright, and their powers can be quite dangerous if tainted like this one.',12340),
	 (294,1,0,0,0,0,0,0,0,'Killing is a dirty business, but you did your job well, $N. If I weren''t obligated to stay with the Prospector and Merrin, I''d be down there shedding blood right along side you.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (295,21,0,0,0,0,0,0,0,'You did a bang-up job of clearing out those Raptors, $N!',12340),
	 (296,2,0,0,0,0,0,0,0,'Thank you, $N. Your efforts here will not be forgotten. Many innocent Dwarves died at this site, simply doing their jobs. The vengeance you delivered to those evil creatures should make them think twice before attacking King Magni''s subjects ever again.',12340),
	 (297,21,0,0,0,0,0,0,0,'You got them! Nicely done, $N!$B$BAnd you don''t look too worse for wear, even with those berserk Troggs about. I''m going to keep my eye on you...you show some promise.',12340),
	 (298,1,1,6,0,0,0,0,0,'Bah! Ironband''s having trouble with the Troggs. I wonder if he wants that blastpowder to aid his digging, or to aid his efforts against the Trogg beasts...$b$bWell, either way it''s powder well spent!$b$bBut what''s strange is, I sent him plenty of blastpowder weeks ago. I wonder where it went...',12340),
	 (299,1,0,0,0,0,0,0,0,'Ah the Goaz Stone is complete! Fine work, $N. Fine work indeed. Now I can continue with the delicate translation of this Titan script. I can make out new words already! Hmm. . .it says here, "Old Gods. . .Chained Beneath the Land." This is the beginning of something epic.',12340),
	 (301,5,6,0,0,0,0,0,0,'Curse that Ironband! I sent him a load of blastpowder weeks ago, but he''s made no mention of it in this report.$b$bSo...where did the blastpowder go?!?',12340),
	 (302,6,1,0,0,0,0,0,0,'What? Stormpike wants you to personally see the shipment to Ironband?$b$bI... suppose that''s fine, the only problem is, I''ve already sent Huldar with the porters, Miran and Saean. You just missed them, they left just a short while ago.',12340),
	 (303,66,0,0,0,0,0,0,0,'You upheld your orders well, $C. You have proven yourself to be a valiant soldier and loyal servant to King Magni and for that I salute you! With the pressure you applied to the Dark Iron encampment, we now stand a chance of driving them off our lands for good. . .if only the damned reserve would show. . . .',12340),
	 (304,1,1,2,0,0,0,0,0,'Balgaras the Foul is finally dead. While his death will not bring back the many innocent dwarves who died needlessly by his hand, it will help to restore peace of mind to those who survived. With Balgaras dead, the remaining Dark Iron scum should be easy enough to manage. Now, we must wipe them out before a new leader is sent to these parts.$B$BYou have done well, $C.',12340),
	 (305,5,0,0,0,0,0,0,0,'Oh, thank the heavens you are here!',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (306,5,6,1,0,0,0,0,0,'Such horrible news! At least 3 of them survived. But when will the killing end? I long for the day when King Magni''s subjects can live without fear.',12340),
	 (307,1,5,0,0,0,0,0,0,'Did you see a lot of Kobolds in there? I can''t wait for the order to clear them out of the mine. The thought of their grimy hands clawing around our mine makes my stomach rumble!',12340),
	 (308,0,0,0,0,0,0,0,0,'For me?  You''re a true hero, $N!',12340),
	 (309,1,1,2,0,0,0,0,0,'Oh, thank the Light the powder is here. But it is troubling news that you bring as well. To think that the Dark Irons have sympathizers able to procure this sort of material for their dastardly plans.$b$bThat''s a matter for someone else to consider, some other time. I must put this powder to good use.',12340),
	 (310,0,0,0,0,0,0,0,0,'You quickly place Marleth''s barrel of Barleybrew Scalder among the Thunderbrew barrels.',12340),
	 (311,0,0,0,0,0,0,0,0,'Not bad, $N!  Did you have a hard time getting past their guard?$B$BNo matter - many thanks, and if you''re ever in need of stout with a kick, don''t forget the Barleybrews!',12340),
	 (312,2,0,0,0,0,0,0,0,'What a kind soul you are, $N! Thanks to your bravery I won''t find myself starving when the cold season flurries blow in.',12340),
	 (313,0,0,0,0,0,0,0,0,'Ah yes, these manes will work great!  You show a lot of grit, $C - I wager we''ll see great things from you.',12340),
	 (314,21,0,0,0,0,0,0,0,'Very well done! Veron will be so happy when he hears the good news. To kill Vagash is no easy task. I imagine one day you''ll be fighting alongside King Magni''s men on the Alliance Front.',12340),
	 (315,0,0,0,0,0,0,0,0,'Great!  I can''t wait to use these in some of my recipes.  There''s one in particular I think it''ll work great in...',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (317,2,0,0,0,0,0,0,0,'By Magni''s beard, you sure did a lot of hunting!!  Thank you, $N.',12340),
	 (318,6,0,0,0,0,0,0,0,'Bellowfiz needs some of my Evershine?  Hm...all right.',12340),
	 (319,2,0,0,0,0,0,0,0,'Thank you, $N.  It''ll be nice to work our crafts without hearing so many growls and snorts outside the village.',12340),
	 (320,0,0,0,0,0,0,0,0,'Yes, this will do just fine.  I think I''ll open a bottle right now and have a taste...',12340),
	 (321,0,0,0,0,0,0,0,0,'This chest is waterlogged, and its siding broken. Many claw marks mar both the inside and outside of the chest...as if Murlocs have searched through it and stolen its treasure.$b$bBut tucked deep within the chest is a single Lightforge Ingot. Unfortunately, many more will be needed if enough metal to fashion a weapon is to be gained.',12340),
	 (322,1,2,0,0,0,0,0,0,'That is quite a tale you have. And lightforge iron! Not for years have I worked with such a metal. It will be an honor to craft with it again. And you must return to me later with the story of your battle against the Necromancer.$b$bBut we get ahead of ourselves. First, your weapon against Morbent Fel...',12340),
	 (323,21,0,0,0,0,0,0,0,'Your skill in combat, $N, can not be doubted. Your resolve may yet see us through to the end of Morbent Fel!',12340),
	 (324,1,0,0,0,0,0,0,0,'Ah, you found them! Now let''s get this lightforge iron hammered into something useful, eh?',12340),
	 (325,21,0,0,0,0,0,0,0,'Ah, this will be proof against the fiend Morbent Fel! Well done!$b$bYou are ready. Morbent Fel will fall.',12340),
	 (328,0,0,0,0,0,0,0,0,'Opening the strongbox, it''s clear that this is where Herod keeps his more valuable coins and items.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (329,0,0,0,0,0,0,0,0,'Thank you, $N. This note is the clue we need to root out the traitor!',12340),
	 (330,0,0,0,0,0,0,0,0,'Oh, yes I can check that for you. Let''s see...last week it was...$B$B...why, it was Private Merle scheduled with Thorsen. They had the same patrol times all of last week.',12340),
	 (331,0,0,0,0,0,0,0,0,'It pains me to find out it was Merle who betrayed us. He has always been a brave soldier, and I had thought his heart was true. But it is a great relief to have found him out - with a spy like him among us...we would not last long against Colonel Kurzen.',12340),
	 (332,1,0,0,0,0,0,0,0,'Ah, so you''ve seen Renato? Well here you are, $G sir:madam;. A bottle of our special pinot noir. You''ll not find its equal in all of Azeroth!',12340),
	 (333,1,1,0,0,0,0,0,0,'It says here that Harlan''s business is booming. That''s good news, but I wonder why people have need of all that armor. I''ve heard nothing of open war... is there something the nobles aren''t telling us?$B$BWell, thank you for bringing the request. Here''s your payment, and I''ll see to it that Harlan gets his supplies.',12340),
	 (334,0,0,0,0,0,0,0,0,'Oh, blast! I thought forgetting my kit would free me from work. Now I guess I''ll have to help the Larsons with their sewing...$B$BOh, well. Fun will come later I guess.',12340),
	 (335,21,0,0,0,0,0,0,0,'Most excellent! These are fine samples indeed!',12340),
	 (336,1,0,0,0,0,0,0,0,'Ah, thank you for bringing me this fine looking stout, servant. Here''s a copper for you. Now, out of sight with you and let me enjoy my drink!',12340),
	 (337,5,1,2,0,0,0,0,0,'Oh my! This book hasn''t rested on these shelves since before the rebuilding of Stormwind, years ago. It will have to be restored of course, it''s in bad shape, but I would be honored to place it within our rare books collection.$B$BThank you, $N. Please accept this as payment for returning the book!',12340),
	 (338,4,0,0,0,0,0,0,0,'You''ve certainly saved me a heap of trouble, $N! I can''t thank you enough. It shouldn''t be long now until we see Master Nesingwary''s book in libraries throughout the world!',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (339,0,0,0,0,0,0,0,0,'At last! Chapter I is complete!',12340),
	 (340,0,0,0,0,0,0,0,0,'Chapter II is finally complete! Well done!',12340),
	 (341,0,0,0,0,0,0,0,0,'Phew! Good work, $N. Chapter III is now back together in one piece!',12340),
	 (342,0,0,0,0,0,0,0,0,'Superb! We now have Chapter IV ready to go!',12340),
	 (343,6,1,0,0,0,0,0,0,'Metallurgy? Ah yes, we have many books on the subject, and are happy to aid Brother Kristoff with his speech! Now...which particular book was it the good brother needed?',12340),
	 (344,6,1,0,0,0,0,0,0,'Mr. Sheaf is wondering where his book is? Well this is a tad embarrassing. I have the book, but I''m still making my copy and I''m not quite ready to give the original up!',12340),
	 (345,5,0,0,0,0,0,0,0,'You need what?? Maybe you haven''t noticed, but we''re busy fortifying Lakeshire''s defenses and repairing damage from recent orc attacks. If you need Rethban Iron Ore, you''ll have to get it yourself!',12340),
	 (346,2,0,0,0,0,0,0,0,'That''s the one! Thank you, $N. May the Light shine brightly upon both your body and spirit!',12340),
	 (347,4,2,0,0,0,0,0,0,'Oh, splendid! I can use this ore to make my dye, and then can finish copying The Stresses of Iron.$B$BThank you, $N!',12340),
	 (348,0,0,0,0,0,0,0,0,'...feel strength returning....$b$bWhere might be?  Booty Bay?  Oh my!  I had the strangest dream...$b$b...the weakness has not completely left me....',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (349,5,1,1,0,0,0,0,0,'Witch Doctor Unbagwa like Gorilla Fangs!  For you I talk to spirits.  Make Mokk the Savage come.$b$bYou protect Witch Doctor Unbagwa from other Gorilla-beast though or no Mokk for you!',12340),
	 (350,6,1,11,1,0,0,0,0,'You''re kidding? Shaw wants my help again? Of all the nerve...$b$bThe Defias Brotherhood, you say? Well, you''re certainly the bearer of wonderful news, aren''t you? Next you''re going to tell me that Deathwing is still alive and attacking the city.$b$bAll right, tell me everything from the beginning. And don''t leave out something you think might not be important. I need to know it all.',12340),
	 (351,0,0,0,0,0,0,0,0,'You place the egg... distress beacon... inside the chicken... homing robot.$B$BHums and whirs are heard from inside the robot as it struggles to stand up.  After the robot comes to life, Oglethorpe''s voice is heard once more, but now from inside the robot:$B$B"OOX-17/TN is working at least, but it needs major repairs!  It is much too heavy for you to carry it... but I think I have an idea.  Are you up for watching over it some more?"',12340),
	 (353,4,2,0,0,0,0,0,0,'Aha! So Grimand finally finished my axe! I can''t wait to try it against some troggs and kobolds!$b$bMany thanks, $N. It was a long distance to travel for this delivery.  Here are some coins for your efforts.',12340),
	 (354,0,0,0,0,0,0,0,0,'Revenge has a sweet taste, don''t you think? When you destroyed the Agamands, did you catch any hint of free will within them? I hope so. I hope they knew fear before they were smashed into oblivion.$b$bIt is a foolish hope, I know. But it is a hope I foster nonetheless.',12340),
	 (355,0,0,0,0,0,0,0,0,'Coleman speaks well of you, $N, telling of your successful forays into the Agamand Mills.$b$bThe Forsaken have need of your talents once again...',12340),
	 (356,0,0,0,0,0,0,0,0,'Very good.  Your efforts do much to keep the Scourge at bay.  A commendation will be sent to my superior, Executor Zygand.',12340),
	 (357,0,0,0,0,0,0,0,0,'Very good, $N.  I will study this book and determine the identity of that lich.  You have served your Queen well.$B$B<Bethor opens the book and stares intently at its glowing pages...>$B$BAstonishing!  The book you retrieved belongs to no one other than Gunther Arcanus!$B$BGunther was a skilled Necromancer in life; he and I were friends and comrades-in-arms, before the Plague.  And judging from his book he has grown even more powerful in death.$B$BHis skills would be a great boon to us.',12340),
	 (358,0,0,0,0,0,0,0,0,'Expertly done, $N. The Scourge are mistaken if they think they can use those corpses against us, and the fluid you gathered from the Rot Hide slaves will be studied by our Apothecaries. It may have secrets we can use against them.$b$bAs I said, well done. But our struggle continues, and the conflict will surely offer you more chances to prove your worth to the Forsaken.',12340),
	 (359,1,0,0,0,0,0,0,0,'Magistrate Sevren wants a report? Very well: the defenders at The Bulwark are holding the majority of the Scourge at bay, but some do slip through on occasion.$b$bWe have seen sporadic Scourge activity east of this station, with a concentration around the Balnir Farmstead.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (360,0,0,0,0,0,0,0,0,'It is troubling to hear of the Scourge slipping past the Bulwark.  The Lich King and his minions are ceaseless in their assaults.$B$BBut we will not give in.  He will not take us again!',12340),
	 (361,0,0,0,0,0,0,0,0,'Oh...my poor Thurman! I begged him to leave Agamand Mills with me and my father, but his family loyalty was too strong! And I knew it! I just knew it that Brand meant him harm!! Oh, curse this Plague, and the Scourge!$B$B<Yvette''s face then smoothes and grows cold.>$B$BBut regrets are for the weak. As a Forsaken, I have new goals and love is not one of them. I would thank you for delivering this letter, for I had wondered what happened to my past love.$B$BBut that life is over. Forever.',12340),
	 (362,0,0,0,0,0,0,0,0,'Thank you. Devlin''s bones will rest nicely on my mantle.$b$bIf my cold heart can find warmth, it is in knowing that the Agamands are destroyed. They failed me and my family when the Plague came - now I swear I will smash their remains under my heel!',12340),
	 (363,1,0,0,0,0,0,0,0,'Another of the walking dead, hm? Must have been quite a shock, waking up in the crypt with only the cold and Mordo to greet you...$b$bI see the confusion on your face. Let me try to explain our... situation... to you.$b$bWe have been freed from the control of the Lich King by our new leader, Lady Sylvanas. The Dark Lady guides us in our war against the hated Scourge and the holdouts of humanity who dog our every step.',12340),
	 (364,0,0,0,0,0,0,0,0,'It is unfortunate that the Scourge cannot be brought into the fold, their large numbers would be useful in the battles ahead.$b$bBut they will not join us, so we have no choice but to destroy them.',12340),
	 (365,1,0,0,0,0,0,0,0,'You have performed your bidding well, young $C. You are proving yourself to be quite an asset to The Dark Lady''s army.',12340),
	 (366,0,0,0,0,0,0,0,0,'My book?!? So you were the thief who stole it!$b$bBut...what is this new enchantment upon it...Bethor? He is in Lordaeron?$b$bIf he still exists, then perhaps he too escaped from the Lich King''s grasp...',12340),
	 (367,1,0,0,0,0,0,0,0,'You have done well, $N and I thank you for your efforts.',12340),
	 (368,21,0,0,0,0,0,0,0,'The scales are perfect, $N. Exactly what I needed for this concoction.',12340),
	 (369,21,0,0,0,0,0,0,0,'Ah, this venom will do perfectly, $N. Everything else has been added to my concoction and boiled down. Finally, I am ready to try this new deadly agent!',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (370,1,0,0,0,0,0,0,0,'Captain Perrine''s death will undoubtedly please The Dark Lady.  You have performed your duty well, $c.',12340),
	 (371,1,0,0,0,0,0,0,0,'Captain Vachon''s death will slow down the Scarlet Crusade''s advancement in Tirisfal quite a bit.  But other threats loom.',12340),
	 (372,1,0,0,0,0,0,0,0,'You have done extremely well, $C. With ruthless fighters like you conquering in the name of The Forsaken our race is one step closer to defeating Arthas once and for all. I have a good feeling about you, comrade.',12340),
	 (373,6,2,1,0,0,0,0,0,'Edwin VanCleef, you say? I would as much expect a letter from my dead grandmother... So you''ve killed him then? Pardon me in saying, but I''m somewhat surprised. He was a peerless fighter in his younger years. Let''s see what he finds the need to write to me about after so many years.$b$b<Baros peruses the letter.>$b$bEdwin... I see the years haven''t changed you a bit, an idealist as ever, and a romantic. He doesn''t care who he hurts, $N. Revenge has consumed him. But then, I''m not sure I can blame him.',12340),
	 (374,66,0,0,0,0,0,0,0,'Varimathras would be proud.  You serve your leaders well, $c.',12340),
	 (375,1,0,0,0,0,0,0,0,'I appreciate your efforts, $N. May Slyvanas recognize your bravery one day. . . .',12340),
	 (376,1,0,0,0,0,0,0,0,'Thank you, $N. This armor should help you out.$b$bHopefully, it should do you more good than the last one to wear it...',12340),
	 (377,1,5,0,0,0,0,0,0,'So Dextren Ward finally paid for his crimes against humanity? Good riddance to the scum I say. And cheers to you, my friend! Not only have you given the families of the dead the peace of mind they deserve, you sent a poignant message to those corrupt bureaucrats in the House of Nobles. Stormwind must rise to the needs of the people of Duskwood or we will break free from their tyranny.',12340),
	 (378,1,1,0,0,0,0,0,0,'So Kam Deepfury finally got to feel what it is like to be on the receiving end of Death? Good. Serves the cowardly Dark Iron scum right. You have done well, $C. The victims of the Thandol Span attack were but mere victims in a world torn with war and unrest. Their families will have the peace of knowing Deepfury got the punishment he deserved. Longbraid''s brother''s death has been avenged.',12340),
	 (379,5,0,0,0,0,0,0,0,'Excellent, the power source is yours. Now, it isn''t completely designed for use in a science kit like that, so you''ll only have a limited amount of time before all the data you collect will go kablooey!$B$BWhen you collect everything you need for whatever it is you are doing, bring it to me and I''ll shut it down properly. You''ll have at most two hours to get what you need to get done, done.$B$BIf you don''t get it done in time, I can always sell you another power source to try again. You heard me - sell!',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (380,1,0,0,0,0,0,0,0,'Hmm, well, it''s a start. It''ll take a few weeks or months to fully clean out the infestation. After that, we''ll have to get down there with some torches to burn away the webbing.$b$bYou''ve done your duty well, $N, I''m sure I can find something else for you to do.',12340),
	 (381,11,0,0,0,0,0,0,0,'If only they listened to reason, eh, $N? Perhaps we could sit them down for reasonable discourse... ha!$b$bLight-blinded fools.',12340),
	 (382,0,0,0,0,0,0,0,0,'Hmm... Let''s see what you''ve got...$b$b<He begins to rifle through the documents you recovered.>$b$bSome news of their exploits against us... Worthless. Scouting reports... New orders, "Continue to build up a camp near the ruined city..." Nothing we didn''t know already... Ah, what''s this? A map of the dispositions of some of their field commanders and agents! We can use this.',12340),
	 (383,0,0,0,0,0,0,0,0,'Yes, this is very good. You''ve done well in obtaining this information, $N. Hmm... names of the officers in the Tirisfal Glades...$b$bImagine the blow we could deal to the morale of those bloody zealots if we were to kill their leaders in one swift strike.',12340),
	 (384,4,0,0,0,0,0,0,0,'The Malt is brewed, the Boars are dead$BAnd before all is done and anything said$BWe will have to fight for first dibs$BOn these savory Beer Basted Boar Ribs!',12340),
	 (385,21,0,0,0,0,0,0,0,'Well now, these are excellent specimens you collected, $N. Good money for high quality materials, that''s for sure.',12340),
	 (386,1,66,0,0,0,0,0,0,'Targorr the Dread has finally met his fate. I for one am glad to hear the beast now knows what it is like to be on the receiving end of Death''s ruthless grip. You have done well, $N. Sometimes the truest justice can only be found outside the courtroom and beyond the clouded vision of politics.',12340),
	 (387,1,66,0,0,0,0,0,0,'Your efforts in The Stockade were valiant, $N. It''s obvious this problem is bigger than the both of us. But you have performed well and for that I am thankful.',12340),
	 (388,1,1,0,0,0,0,0,0,'So these bandanas -- filthy tokens of corruption -- are what my Mac had to die for?  Such a waste.  Such a tragic sacrifice. $b$bBut alas, I cannot return to the past.  Just know, $N, that you have brought my family justice through your deeds.',12340),
	 (389,6,5,1,1,0,0,0,0,'What in the Light do you want? Can''t you see we have a crisis here?$b$bBazil Thredd?! Why would you want to speak with that bastard? How am I supposed to know you''re not one of his cronies, come down to help with his bloody riot? If all the blasted cells weren''t open, I might throw you in one for a while!',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (391,1,1,1,0,0,0,0,0,'Without Thredd to lead them, hopefully the riots will be more controllable. We shall see.$B$BI must say, after a half hour, I hardly expected you to come out, but it seems I misjudged you.$B$BI''d guess, then, that you didn''t get much useful information out of him? But I know a thing or two that might be of interest to you about Thredd''s activities.',12340),
	 (392,6,1,1,0,0,0,0,0,'Hmm. Maelik? No, the name doesn''t sound familiar and neither does this description. But it could be anybody! A former Stonemason, one of the Defias Brotherhood... Though if he is as well connected as Thelwater suggests, perhaps someone else might recognize him. Let me think.',12340),
	 (393,6,1,1,0,0,0,0,0,'What? What''s this? Yes, I think I do know who this man is, but his name is not Maelik. Assassins wear many names and many masks, discarding them as they lose their usefulness. Another alias known to be used by this man is Marzon; though even that is surely not his true name.$b$bRegardless, he is an assassin and I know a good deal about him.$b$bMarzon is currently under the employ of Lord Gregor Lescovar, a lord of shady reputation, even given the corruption of the nobility of Stormwind.',12340),
	 (394,6,1,11,2,0,0,0,0,'He is dead, then? Your justice was swift, $N. I pray to the Light that I never become your quarry!$b$b<He laughs and claps you on the shoulder.>$b$bI mean no criticism, $N. How could I, being the master of all assassins? But in truth, you have done the people of Stormwind a great service, and for that, I thank you.',12340),
	 (395,2,1,1,0,0,0,0,0,'It''s good to see you, $N. I have heard that Lord Gregor Lescovar was found dead not long ago.$b$bIt would seem that you were successful in your mission. You have my gratitude that you have saved me, and many others, from VanCleef''s revenge.',12340),
	 (396,1,1,2,0,0,0,0,0,'You are to be commended for the service you have done for Stormwind, $N. If VanCleef had been successful in his machinations, he would no doubt have done considerable harm to the kingdom--something we must obviously avoid.$B$BTake this, $C, as a token of the my appreciation.',12340),
	 (397,0,0,0,0,0,0,0,0,'Master says give gift to $N. Zggi wants to keep nice gift but Zggi knows better than to betray Master.',12340),
	 (398,66,0,0,0,0,0,0,0,'Maggot Eye''s dastardly acts have finally been avenged. Maybe your acts of valor will send a clear message to those who wish to bring harm to our people. On behalf of the town of Brill I thank you, $N.',12340),
	 (399,1,2,0,0,0,0,0,0,'Oh, thank you, $N! It''s of no practical use to me, but the sentimental value... Needless to say, thank you for bringing this to me... at some cost to your own well-being, not to mention the time it took to go all the way down to Westfall. You have my gratitude, and have this as a token of my thanks.',12340),
	 (400,0,0,0,0,0,0,0,0,'You have my tools? Well done, lad, well done! I just broke my last fang-ratchet an hour ago and I need one of those to finish repairs on Pilot Stonegear''s siege engine. You did a good thing by lugging those tools here, $N.$b$bHere, take these coins for your help.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (401,0,0,0,0,0,0,0,0,'There we are.  It''s translated...$B$B<The air grows heavy, as if a thick, black curtain is drawn over the land...>',12340),
	 (403,0,0,0,0,0,0,0,0,'This barrel of ale is guarded by Jarven Thunderbrew.  As long as he''s in the basement, no barrels may be disturbed.',12340),
	 (404,0,0,0,0,0,0,0,0,'Well done. I regret not being there to see you smash those undead into rotting pulp!',12340),
	 (405,0,0,0,0,0,0,0,0,'Ah, you are the agent sent by Magistrate Sevren. Then yes, your business with me is crucial.$b$bI trust Sevren has mustered someone suitable for my task...but we shall see.',12340),
	 (407,0,0,0,0,0,0,0,0,'By the Light!  Finally some food!  Sweet, sweet pumpkin. . . .',12340),
	 (408,0,0,0,0,0,0,0,0,'Your actions struck a telling blow against the Scourge. And your victory will not go unnoticed - not by the Forsaken, nor by our enemies.$b$bContinue the struggle as we all do, $N, and one day we will drive the Lich King himself from Azeroth!',12340),
	 (409,1,0,0,0,0,0,0,0,'You have defeated Lillith Nefara, proving you are an enemy of the Scourge. Incredible.$b$bI had believed I was the only Undead with free will, but you have shown me there are others who have broken the Lich King''s domination.',12340),
	 (410,0,0,0,0,0,0,0,0,'You place the Candle of Beckoning upon the table and light it...',12340),
	 (411,0,0,0,0,0,0,0,0,'You convinced him to join us! You have done a great deed for the Forsaken, $N. The Dark Lady will be informed.',12340),
	 (412,1,0,0,0,0,0,0,0,'These Gyromechanic Gears and Restabilization Cogs are in perfect accordance with Ozzie''s schematics for the Recombobulation Device.  Once I add some hydrolubricant to the inner combustion pistons, adjust the crank-o-ratchet and increase of the viscosity of the electrogum gel, the gnomish race will be as good as new.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (413,7,4,0,0,0,0,0,0,'<Mountaineer Barleybrew tastes the Shimmer Stout...>$B$BOh.  Whoa!  This stuff really puts a shine in your eyes.  I feel like I can see in the dark!',12340),
	 (414,7,5,0,0,0,0,0,0,'Now, let me have a taste...$b$bMagni''s Beard! This stuff gets your head turning! And it lightens the limbs, too.$b$bI feel like I can fly!',12340),
	 (415,5,0,0,0,0,0,0,0,'$N! You know that Shimmerweed you brought me? Well I used it in a few recipes I''ve been working on, and one of them turned out great!$b$bHere, try it out and tell me what you think...',12340),
	 (416,34,1,0,0,0,1000,0,0,'Ugh! When I asked for those ears I didn''t realize they''d smell so bad!$b$bHere''s your reward, $N. Well done.',12340),
	 (417,1,2,0,0,0,0,0,0,'This is grim news, for Hildelve was a good friend. And I wish I could have been there with you when you found the beast, Mangeclaw!$b$bThank you, $N. Your deed will be remembered by the pilots of the Ironforge Siege Brigade.',12340),
	 (418,1,0,0,0,0,0,0,0,'Trust me, it seems a lot harder than it looks, but...$b$bOh, I''ve never known someone to take much interest in the making of sausages, but I''ll give you the recipe just in case. Here you go, mind you eat them fresh!',12340),
	 (419,0,0,0,0,0,0,0,0,'Here is the corpse of a dwarf -- mauled, frozen, and picked clean by mountain scavengers. Clutched in its hand is a book containing the roughly scribbled notes of Mori Hildelve. And around its frame, still in superior condition, is a Brigadier''s Vest.$b$bThis grisly scene must have been where the Siege Engine pilot met his end.',12340),
	 (420,1,0,0,0,0,0,0,0,'What''s this? Ah, my brother''s report. Hmm...$b$bI told him to be sparing with the use of the King''s name, but he didn''t listen. No harm, I suppose, though it''s sure to ruffle some feathers in the Senate. Not that those weren''t some feathers that needed ruffling! Hah!$b$bNonetheless, I guess that means that I should send my report on to Ironforge as well, but I must admit I''m a bit behind. Bloody cold.$b$bI should have some work for you later, if you''re interested.',12340),
	 (421,1,0,0,0,0,0,0,0,'You have served me well, $C. It is obvious to me that you will be a worthy aide to me as I prepare to rid Silverpine Forest of Arugal''s curse.',12340),
	 (422,1,0,0,0,0,0,0,0,'This is precisely the spell I was in search of, $C. If your dedication to The Dark Lady''s cause remains infallible you will find you have quite a future amongst The Forsaken.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (423,1,0,0,0,0,0,0,0,'I hope I can acquire enough energy from such a limited sample. Perhaps I should have had you get more shackles.$b$bNonetheless, you showed great skill in collecting these, $C.',12340),
	 (424,0,0,0,0,0,0,0,0,'Most excellent. The mine will provide superb resources for our forces as we spread throughout Silverpine and into Azeroth.',12340),
	 (425,0,0,0,0,0,0,0,0,'Ah, thank you. You have my gratitude, $N.$b$bAnd I will include you in the report I make to my superiors.',12340),
	 (426,0,0,0,0,0,0,0,0,'Your efforts in the war are felt among us, $N. I will not thank you for doing what is necessary, but the Deathguards of Tirisfal will remember your name.',12340),
	 (427,1,0,0,0,0,0,0,0,'Most excellent, $C. Your skill in the art of combat is undeniable.',12340),
	 (428,0,0,0,0,0,0,0,0,'You found us! And not a moment too soon...',12340),
	 (429,0,0,0,0,0,0,0,0,'<Renferrel takes the hearts>$b$bIt is troubling to hear our Deathstalkers have failed their mission.$b$bLet us hope that these failures are rare.$b$bI''ll give you the potion in a moment, but here is its recipe - if those Deathstalkers find themselves in need of future aid, then perhaps you can give it yourself.',12340),
	 (430,0,0,0,0,0,0,0,0,'<Quinn takes the potion and drinks it>$b$bYes, I can feel it working. I will soon be able to travel.$b$bYou have done me a great favor, $N.',12340),
	 (431,0,0,0,0,0,0,0,0,'You grab one of the candles and place it in your pack.',12340),
	 (432,1,5,0,0,0,0,0,0,'Well, that makes me feel a little better...$b$bBut I won''t be happy until they''re all dead! All of them!',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (433,0,0,0,0,0,0,0,0,'It is a start. Hopefully we can take advantage of it, and move some Mountaineers in to secure the area. Then we can begin to restore our infrastructure and get the miners back to work.$b$bThank you for your assistance, $N.',12340),
	 (434,6,1,1,0,0,0,0,0,'So it is done? Good. Thank you greatly for your discretion, $N. You''ve proven worthy on more than one count. I''ll be sure to keep my eyes on you and your progress within the Alliance.$B$BBe sure to keep your nose clean.',12340),
	 (435,1,0,0,0,0,0,0,0,'Thank you for the aid, $N. I had feared Erland was overcome by the dangers of Silverpine. With your help, I see that he has not.',12340),
	 (436,6,1,5,0,0,0,0,0,'Jern wants to know what the slowdown is, eh?$b$bIronband is putting together his latest progress report with details, but I can tell you this:$b$bIt''s the Troggs!!',12340),
	 (437,0,0,0,0,0,0,0,0,'I heard of your successful raid against the rot hides, $N, and this essence is proof of Nightlash''s death.$b$bThe Scourge have lost ground this day. Your value to the Forsaken grows.',12340),
	 (438,0,0,0,0,0,0,0,0,'Heaped within this boat is a pile of wrapped corpses. And looking east across Lordamere Lake, an opposing dock on Fenris Isle can be seen.$B$BThe fate of the corpses must lie on Fenris Isle.',12340),
	 (439,0,0,0,0,0,0,0,0,'You say that this ring was worn by a woman, recently killed?$B$BThe only nearby source of such a body would be the mass graves in Tirisfal. The Rot Hide Gnolls must be taking those corpses to Fenris Isle!',12340),
	 (440,0,0,0,0,0,0,0,0,'A Deliah did live in Brill not long ago. She was buried in the mass grave but if what you say is true, then the Rot Hide Gnolls must have stolen her body and taken it to Silverpine.$b$bThe Rot Hides, like all the Scourge, must be destroyed. I trust you are taking steps to make that happen.',12340),
	 (441,1,1,0,0,0,0,0,0,'Yes, this ring was my wife''s. Her fate was the fate of all who fail to endure these harsh times. I feel nothing for her death, nor for the story you tell of her body''s abduction.$b$bSuch feelings have long since grown cold within me. But desire does still burn in my dead heart, $N.$b$bDesire for revenge.',12340),
	 (442,0,0,0,0,0,0,0,0,'The death of Thule Ravenclaw was no small event, $N. Renferrel tells me that the energies released when you destroyed Thule were felt even as far as the Sepulcher.$b$bYour actions ring through the ranks of the Forsaken. Your value to us grows.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (443,0,0,0,0,0,0,0,0,'Very good. This ichor will help us understand the nature of the rot hides, and may show us their weakness...$b$b...if they have one.',12340),
	 (444,0,0,0,0,0,0,0,0,'This substance is laced with powerful spells, some of which I have not seen for a long, long time...$b$bOne moment -- I must invoke a spell of divination...',12340),
	 (445,1,0,0,0,0,0,0,0,'Ah, how good of Apothecary Johaan to send his research. With so many new developments here in Silverpine, I nearly forgot about the findings coming out of Lordaeron and Tirisfal Glades. Which reminds me, I need to get those samples off to the Necropolis soon.$b$bBut you must excuse my rambling. Extend your stay in Silverpine, $N. We could use an able bodied $C like you around here.',12340),
	 (446,1,0,0,0,0,0,0,0,'This scroll is laced with powerful magic. I''ve never used such forces in a potion ... it will be a powerful mixture, and should serve you well should you attack Thule in his stronghold on Fenris Isle.',12340),
	 (447,273,0,0,0,0,0,0,0,'How good of Apothecary Renferrel to send you to me, $N. These samples will indeed prove useful to the cause. I will begin studying their toxic and contaminable properties at once.',12340),
	 (448,0,0,0,0,0,0,0,0,'If what Bethor says is true then Thule Ravenclaw is a force that must be dealt with, and dealt with soon.$b$bTo aid in this task, you may take something from our arsenal here...',12340),
	 (449,0,0,0,0,0,0,0,0,'I hadn''t accounted for the level of Scourge presence we''ve seen in Silverpine Forest, nor for the troubles our Deathstalkers have had in their scouting efforts.$b$bYour aid to our Deathstalkers was invaluable, $N. And you will be commended.',12340),
	 (450,5,0,0,0,0,0,0,0,'Apothecary Berard''s journal! Why you are quite brave, $N. Now let''s see what Berard was up to before he went mad. . .',12340),
	 (451,0,0,0,0,0,0,0,0,'Such a blow to the Royal Apothecary Society to lose Berard. But through your hard work and Apothecary Renferrel''s diligent research Berard''s studies will still be useful to The Dark Lady''s plight.$b$bWe are on the cusp of something great here, $N. If you were not so skilled in the ways of combat I would try to recruit you for membership in the Society.',12340),
	 (452,0,0,0,0,0,0,0,0,'You fought like a true disciple of the Dark Lady, $N. With the council dead, perhaps we can gain control of this town once and for all and drive Arugal from Shadowfang Keep. I salute you!',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (453,0,0,0,0,0,0,0,0,'<Jitters sighs...>$B$BYes, I''m the author of that book. You finally found me, eh?$B$BWell if you read that journal...then you only know the half of it!',12340),
	 (454,2,1,1,0,0,0,0,0,'Hello, $C.$b$bYou''ll be escorting me to the excavation site? That''s good to hear... After Saean and his cronies, who knows what else the Dark Irons might have up their sleeves?$b$bAnyways, let me just make some final checks. Talk to me again when you''re ready to go.',12340),
	 (455,0,0,0,0,0,0,0,0,'Your report is full of bad news!$b$bI see the Dragonmaws are making a strong move into Algaz. Normally the Dragonmaws just hide up in the hills. What made them surge into Algaz is still a mystery...$b$bThank you, $N. And we''ll probably want your help dealing with these orcs.',12340),
	 (456,21,0,0,0,0,0,0,0,'You performed your duties well, $N.',12340),
	 (457,21,0,0,0,0,0,0,0,'You have proven your dedication to nature well, $N. A young $C like yourself has a promising future.',12340),
	 (458,0,0,0,0,0,0,0,0,'I see you found me, young $R. Melithar is a wise druid to have sent you.',12340),
	 (459,0,0,0,0,0,0,0,0,'Your service to the creatures of Shadowglen is worthy of reward, $N.$b$bYou confirmed my fears, however. If the grells have become tainted by the Fel Moss, one can only imagine what has become of the Gnarlpine tribe of furbolgs who once lived here.$b$bShould you find yourself in Dolanaar, able $C, seek out the knowledgeable druid, Athridas Bearmantle. He shares our concern for the well being of the forest.',12340),
	 (460,0,0,0,0,0,0,0,0,'Thank you, $N. I had feared the Gnolls destroyed my body. It is good to know they did not.',12340),
	 (461,0,0,0,0,0,0,0,0,'There we are, it''s open. Leave me here. I spent the best days of my life in this keep, and the thought of resting within its walls gives me comfort.$b$bBe sure to close the alcove tight - I don''t want those Rot Hides to find me.$b$bOh, and take this. You''ve earned it.',12340),
	 (463,0,0,0,0,0,0,0,0,'The roots and ferns speak well of you, small one. Although I have many names, I answer to only a few. But you may call me Rethiel.$B$BAnd you must harken...for these lands weep from festered wounds, and I would charge you to heal them.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (464,0,0,0,0,0,0,0,0,'Well fought, $N. The Dragonmaws are not the same threat they were when they had dragons, but they''re still fierce opponents.$b$bThe Dragonmaws are led by Nek''rosh, son of Nekros, who was the former head of the Dragonmaws years ago. Nekros used powerful magic to tame the Red Dragons, but when that magic failed him...the dragons were not happy.$b$bNekros was killed, and his son has vowed revenge against the dragons who slew his father.',12340),
	 (465,0,0,0,0,0,0,0,0,'You place some of the tinder on the catapult then strike a spark onto it.$B$BFlame erupts and quickly spreads!',12340),
	 (466,5,0,0,0,0,0,0,0,'You got the ore! Well done, $N! I''ll get someone to work with this right away. Let''s hope he doesn''t blow himself up!',12340),
	 (467,3,0,0,0,0,0,0,0,'Hello $N. You''re here about the task I have, eh? It''s good to see a young $R like yourself whose blood burns at the prospect of adventure!',12340),
	 (468,66,1,0,0,0,0,0,0,'Hello, $C! You''re here for the scouting mission, are you? Very good!$b$bI hope your gear is in good condition, because this "scouting" mission has changed into something more messy...',12340),
	 (469,6,0,0,0,0,0,0,0,'Hmm, this is from Einar, right? Hasn''t delivered his skins to me in person for almost a week now. No doubt it''s some differences with the wife!$b$bMaybe I''ll have my wife go speak with Sida sometime...',12340),
	 (470,0,0,0,0,0,0,0,0,'Oh, thank you, $N! I was afraid that it was lost for good!$B$B<She quickly empties the contents of the ooze-covered bag onto the ground, before scooping them up.>$B$BHm, I don''t have much use for this anymore, but wash it off and I''m sure you could make use of it.',12340),
	 (471,6,11,0,0,0,0,0,0,'Hmm... Don''t suppose you''d be interested in becoming my apprentice, would you?$b$bHah! No, I''m just kidding. You''re much too old, for one thing. Besides - from the looks of you, it would seem that you have other ambitions in life. Nonetheless, these are some fine skins you''ve procured, and I''ll be able to put them to good use.',12340),
	 (472,6,1,0,0,0,0,0,0,'What brave $C sends word from Menethil? Ah $N, they call you.$b$bYou bring hope to a hopeless situation. ''Tis good news indeed that young Harlo survived. While fleeing he received a grievous wound. We had but little time to send him on his way on the back of the only surviving steed with the regiment.$b$bBut now we face a perilous situation. Dun Modr has fallen and we are but a shadow of the great regiment we once were.',12340),
	 (473,66,0,0,0,0,0,0,0,'$N. Valstag briefed me on your past success with the Dragonmaw Orcs at Dun Algaz. You''re a $R of worth.$b$bAnd I have a task for you.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (474,66,0,0,0,0,0,0,0,'Stoutly done, $N. You have dealt a telling blow to the Dragonmaw orc clan. They may never recover. And the destruction of those catapults has made Menethil Harbor safe.$B$BYou are a $R of merit, and the kingdom of Ironforge rewards those who serve it well.',12340),
	 (475,0,0,0,0,0,0,0,0,'Thank the forest spirits you are here! I knew Athridas would sense trouble and send help.',12340),
	 (476,5,0,0,0,0,0,0,0,'By the stars! This is quite disturbing indeed!',12340),
	 (477,0,0,0,0,0,0,0,0,'<Prying open the lid of the crate, you find an assortment of carefully-packed objects. On the top of the crate lies a bundle of maps, yellowing with age, that appear to depict Silverpine Forest and other parts of western Lordaeron.$b$bUnderneath the maps is a mysterious-looking magical pendant.>',12340),
	 (478,0,0,0,0,0,0,0,0,'Maps and this... pendant, hm? Interesting.$b$bIt is obvious that the Dalaran wizards are interested in Ambermill for some purpose, but still, their aim is hidden to me.$b$bPerhaps Dalar will know something of their use.',12340),
	 (479,0,0,0,0,0,0,0,0,'Dalar has found that the weaving is quite far along, despite the setback.$b$bA wizard of great power is guiding the magic energy. He must be stopped quickly.',12340),
	 (480,0,0,0,0,0,0,0,0,'The magic of the wizards dissipates, and the ley energies fade into dormancy. Your efforts have been fruitful, $N, and we have dealt a major blow to our enemies, and to the overbearing wizards of Dalaran.$b$bWe must be vigilant, however, knowing that source of energy lies so close at hand... Plans must be made for the future.',12340),
	 (481,0,0,0,0,0,0,0,0,'Interesting, more machinations of the Kirin Tor, it would seem. This is a powerful artifact. It was used frequently by powerful wizards of the Kirin Tor to channel magical energies.$b$bThat they are delivering so many to Ambermill indicates that they must be undergoing a project of some magnitude.$b$bI will see if I can pierce their shields and ascertain their intent.',12340),
	 (482,0,0,0,0,0,0,0,0,'Ill news you bring, $N. If Dalar is correct--and I''ve no reason to believe he isn''t--we must move quickly.$b$bI must confer with him on our plan of attack. But in the meanwhile we will have to delay their progress.',12340),
	 (483,4,0,0,0,0,0,0,0,'You have succeeded, young $C! Well done. And just in time I might add.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (484,21,0,0,0,0,0,0,0,'Nice work you''ve done here, $N. The quality of these skins is superb. I''ll have to get them into the curing process as soon as possible. Oh, but before I get to that, there''s some other work I need done that I think you might be able to take care of.',12340),
	 (485,0,0,0,0,0,0,0,0,'You place the egg... distress beacon... inside the chicken... homing robot.$b$bHums and whirs are heard from inside the robot as it struggles to stand up. After the robot comes to life, Oglethorpe''s voice is heard once more, but now from inside the robot:$b$b"OOX-09/HL is working at least, but it needs major repairs! It is much too heavy for you to carry it... but I think I have an idea. Are you up for watching over it some more?"',12340),
	 (486,1,1,2,0,0,0,0,0,'$N you have proven yourself a most worthy and able $C. A night elf who follows the path of honor as sure as you do is certain to find great glory in this world.$b$bMay the forest spirits protect you wherever your travels may take you.',12340),
	 (487,1,66,0,0,0,0,0,0,'You have served the good people of Dolanaar and Darnassus well, brave $C. As a member of the Sentinel force of Teldrassil I salute your efforts.',12340),
	 (488,0,0,0,0,0,0,0,0,'Ha ha! Well, done indeed.$b$bWho would have ever guessed that I, Zenn Foulhoof, would have a $R to do my bidding? Certainly not me! But so it goes... this beloved world of ours is full of surprises.$b$bThree cheers for the naive and gullible!',12340),
	 (489,0,0,0,0,0,0,0,0,'Ah, what a sweet $R! I knew you would come in handy!',12340),
	 (491,0,0,0,0,0,0,0,0,'...what is this? Thule had our Woven Wand? I thought it was lost when our friendship sundered and he sided with the Lich King!$b$bHe must not have invoked its power, for if he had I would have sensed it. And it is good that he did not use it...$b$bThis is a marvelous find. You have my gratitude, $N, and will be rewarded.',12340),
	 (492,1,0,0,0,0,0,0,0,'Ah, a drink at last.  I''m sure it''s no Rhapsody Malt but I''ll take anything to whet the old whistle at this point.',12340),
	 (493,273,0,0,0,0,0,0,0,'Ah, most excellent. Apothecary Renferrel has my utmost respect. I am anxious to study his work.',12340),
	 (494,6,1,0,0,0,0,0,0,'The raven''s cry from the west doth beckon?$b$bSuperb news! Hillsbrad is ripe for attack. We can carry out our plan of destruction now. Varimathras will be pleased.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (495,0,0,0,0,0,0,0,0,'You were sent by Shalindra? Very well then, you''ll find I don''t waste much time with idle chatter.$B$BMug''Thol is an irritant, and we will deal with him quickly, thoroughly, and without incident.',12340),
	 (496,1,0,0,0,0,0,0,0,'These specimens are perfect. Well, $N, you have managed to bring me the slightest hint of joy on yet another miserable day. Your efforts are appreciated.',12340),
	 (498,6,5,1,0,0,0,0,0,'So the humans thought to turn our warriors into slaves, did they? We''ll show them!$b$bIt would seem that they have taken Gol''dir, our leader, to another location. We must find him and rescue him. But we currently have no clue where he is...$b$bWhen we have a lead, I will be sure to tell you, $N.',12340),
	 (499,0,0,0,0,0,0,0,0,'Croak!',12340),
	 (500,0,0,0,0,0,0,0,0,'Very good, $N You must have hacked through a whole mess of ogres to get all these knucklebones.$B$BThat should keep them out of our hair. At least, for a while.',12340),
	 (501,4,0,0,0,0,0,0,0,'Superb collecting, $N.',12340),
	 (502,0,0,0,0,0,0,0,0,'You pour some of the elixir into your hand and hold it before Stanley''s mouth.',12340),
	 (503,2,1,0,0,0,0,0,0,'Thank you, $N. I led the expedition from Durotar under the Warchief''s orders, but as you can see, our plans went somewhat awry. They have held me captive here in this town, forcing me to work, hauling burdens, digging...$b$bWhat I have suffered is unimportant, however. There is important information you must deliver to whomever is leading our group now.',12340),
	 (504,0,0,0,0,0,0,0,0,'Very good. Here is your reward.$B$BAnd when you were hunting those Warmongers, how did Alterac city look? It''s in bad shape I would guess. Ogres are not known for their cleanliness.$B$BThankfully, your efforts will help keep them away from Southshore.',12340),
	 (505,0,0,0,0,0,0,0,0,'Thank you, $N. Although they may still be lurking about, we hope that some of the thieves and footpads you slew were responsible for the last magistrate''s death. But even if they weren''t, the Syndicate is a taint on this land and a stain on the human race.$B$BTheir deaths are welcome to Southshore.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (506,5,0,0,0,0,0,0,0,'The nerve of those overbearing humans! We''ll show them that the orcs shall never submit to their will!$b$bThis will now be our mission, in addition to recovering the trinket the Warchief desires. It would seem that by accomplishing one, we will also accomplish the other.',12340),
	 (507,20,0,0,0,0,0,0,0,'No, no please don''t hurt me! I never meant your people any harm, he''s had me against my will! Please... spare me!',12340),
	 (508,1,0,0,0,0,0,0,0,'It is strange that the Warchief would expend so much over such a small thing. I do not claim to understand him, but I will follow him, whatever his commands. You did well, $N, no doubt the Warchief will be glad to hear of your success.',12340),
	 (509,1,11,0,0,0,0,0,0,'Ah, the horrible reek of Mudsnout Blossoms. At least those filthy Gnolls are good for something.',12340),
	 (510,0,0,0,0,0,0,0,0,'<Maleb reads the documents.>$B$BThese are very troubling, $N. From the information in these documents, and from the Syndicate''s actions in the past, we must assume that band of cutthroats has waged war on Southshore.',12340),
	 (511,0,0,0,0,0,0,0,0,'What is this? Hold a moment... let me take a closer look.$B$B...$B$BHm, I have never before seen this form of encryption, but I must admit that my knowledge in that area is by no means complete.',12340),
	 (512,0,0,0,0,0,0,0,0,'Stripping the Syndicate of its nobility will remove its ability to act decisively, and reduce it to nothing more than a gang of thugs.$B$BYou serve your Alliance well, $N.',12340),
	 (513,6,1,0,0,0,0,0,0,'Apothecary Lydon sent you? Ah, why didn''t you say so!$b$bDespite his gloomy disposition, Apothecary Lydon is one of our most dedicated and skilled members.$b$bThe good chap sends Mudsnout Composite! I know what our friend in Hillsbrad is up to now. And I like the way he thinks. The Dark Lady would be most impressed with the progress he is making toward the new plague.',12340),
	 (514,1,0,0,0,0,0,0,0,'Ah, encryption! A specialty of mine. Let me see here...',12340),
	 (515,5,0,0,0,0,0,0,0,'The excitement of this experiment has me feeling giddy! You have been such a great help, $N. Together we will spread death and disease to this land!',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (516,0,0,0,0,0,0,0,0,'If our scouts and agents continue to procure valuable information such as this, we shall have the Lich King''s Scourge removed from our lands in no time.',12340),
	 (517,5,0,0,0,0,0,0,0,'Finally! Now we are ready for action!',12340),
	 (518,0,0,0,0,0,0,0,0,'The snow blooms red with the blood of the ogres, but we cannot cease our efforts until the spirit and numbers of the Crushridge have been crushed and ground into the dirt and snow.',12340),
	 (519,0,0,0,0,0,0,0,0,'...and I thought ogres smelled foul enough to begin with.$b$bWhen you bring me Mug''Thol''s head, I will have the four of them mounted on pikes above Alterac. A fitting monument to those who go against the Dark Lady''s wishes.',12340),
	 (520,0,0,0,0,0,0,0,0,'You have done your duty well, $N. Mug''Thol''s head shall adorn the highest peak of the ruins of Alterac, and the Deathguard will sweep the remnants of the Crushridge into the ground.',12340),
	 (521,0,0,0,0,0,0,0,0,'So this is the relic the ogre used to duck the will of the Dark Lady...$b$bStrange that something so simple could wield so great a power. And to fall into as clumsy hands as those. Well done, $N, I will deliver the crown to Lady Sylvanas, and see that she hears of your accomplishment.',12340),
	 (522,0,0,0,0,0,0,0,0,'<Maleb inspects the contract.>$B$BThat explains the latest attack on Southshore. The Syndicate must be after me, just as they were the last magistrate!',12340),
	 (523,2,0,0,0,0,0,0,0,'Thank you, $N. My head rests a little easier, knowing that villain lost his.',12340),
	 (524,0,0,0,0,0,0,0,0,'You rest the tainted deg on the dusty rug.',12340),
	 (525,0,0,0,0,0,0,0,0,'<Maleb reads the letter.>$B$BThis is translated from a letter you found in a Syndicate encampment? This was not written by a thief, or even a noble of Alterac.$B$BIt appears The Syndicate has ties to another power, and I shudder to think what that might be.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (526,0,0,0,0,0,0,0,0,'Ah, you found them! Now let''s get this lightforge iron hammered into something useful, eh?',12340),
	 (527,25,0,0,0,0,0,0,0,'At ease, $C. I see you have returned from battle. My sources tell me you performed well on the Hillsbrad front.',12340),
	 (528,1,0,0,0,0,0,0,0,'The grip of death is tightening around the town of Hillsbrad. The battle goes well.',12340),
	 (529,21,0,0,0,0,0,0,0,'Mission accomplished, $C. And carried out quite skillfully, I might add.',12340),
	 (530,1,0,0,0,0,0,0,0,'Ah, good. These hands killed my wife, Deliah. Revenge for her murder was my only care, and you were the instrument of that revenge.$b$bHere, take the ring you returned earlier. Deliah has been dead to me for so long, her ring is a bauble I no longer care to keep. Instead, I will keep these hands as a remembrance of my friend''s betrayal.',12340),
	 (531,2,1,0,0,0,0,0,0,'Thanks for helping me out with my little plan, $N. I''ve been itching for months to get back at that snooty, stuck-up boy, and I''d say we did a pretty good job! Here, have this, you''ve earned it.',12340),
	 (532,21,0,0,0,0,0,0,0,'News of your glories in Hillsbrad traveled fast. You have done well, $C.',12340),
	 (533,1,0,0,0,0,0,0,0,'Finally, we know where Gol''dir is being held. The camp in question is not too far from here, and hopefully they will not be as well prepared as they were when they captured us the first time.',12340),
	 (535,0,0,0,0,0,0,0,0,'Given my impending death, I think I can safely say that this is the sweetest tasting thing ever... Here, take this, won''t do me any good when I''m dead.$B$BWell, get on with it!',12340),
	 (536,0,0,0,0,0,0,0,0,'I hope this will be enough to convince Redpath that I''ve--ha!--been carrying out his orders and ridding Southshore of the terrible and horrible menace of the dreaded murlocs! For there could be no greater evil than the ravages of overgrown fish!',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (537,1,0,0,0,0,0,0,0,'Well done, $N. The Argus Wake does not sound like a group we want running the Syndicate.$B$BAnd although you may have destroyed their leader here, Nagaz was merely the servant of another. The Argus Wake might run deep through the continent of Azeroth.$B$BOr even the world.',12340),
	 (538,1,1,0,0,0,0,0,0,'Ah yes, I remember Milton. A bookworm, no doubt. Bless him.$B$BAnd he''s right. The Ruins of Alterac still hold stores of knowledge in danger of being lost!$B$BOgres now dwell in Alterac, and they don''t care much for higher learning.',12340),
	 (539,21,0,0,0,0,0,0,0,'The Dark Lady will be pleased when she learns that she has a new mine from which she can arm her soldiers.',12340),
	 (540,4,0,0,0,0,0,0,0,'Oh, you got them! Splendid! I must begin studying the Arm of Gri''lek immediately!',12340),
	 (541,21,0,0,0,0,0,0,0,'Your actions on the battlefield are worthy of the highest praise.',12340),
	 (542,5,2,1,0,0,0,0,0,'My oh my! Look at these! I can''t believe they survived the ruination of Alterac. And all those ogres too!$B$BThank you, $N. Thank you so much! You have helped preserve human knowledge, and you add to the grandeur of the Royal Library of Stormwind.',12340),
	 (543,1,0,0,0,0,0,0,0,'Ah, this is splendid. This will have to be cleaned of course, but you really outdid yourself, $N. I will have someone prepare the tiara and place it within our collection posthaste.',12340),
	 (544,0,0,0,0,0,0,0,0,'You have done a great service for the Forsaken, $N. These artifacts have been sorely missed.$b$bAnd it is good to hear that Kegan and the other betrayers have found justice.',12340),
	 (545,0,0,0,0,0,0,0,0,'Very good. Those ruins should now be safe enough to search, if one is careful.$B$BThank you, $N.',12340),
	 (546,4,0,0,0,0,0,0,0,'Precious skulls! So beautiful! I owe you as promised, $N!',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (547,4,0,0,0,0,0,0,0,'You found it!$b$bAh, I feel so complete with my precious sword back in my hand. Many thanks to you!',12340),
	 (549,21,0,0,0,0,0,0,0,'Excellent, $C. At this rate, the Syndicate pest will be rid from the land in no time.',12340),
	 (550,0,0,0,0,0,0,0,0,'So you are the infamous $C who struck such a decisive blow against the Alliance forces in the Hillsbrad Foothills? Word of your glorious exploits traveled quickly to the Undercity.$b$bYou have quite a future in the Dark Lady''s ranks if you continue to show such leadership and expertise in battle.$b$bWhile our primary threat is the Lich King''s Scourge army descending from the north, the human "problem" continues to impede our battle plans. You, however, have shown that the humans can and will fall.',12340),
	 (551,6,1,0,0,0,0,0,0,'More encrypted notes?$B$BI wish I had the talents to decrypt all the strange bits of writing that trickle down from Alterac. But I''m afraid I lack the knowledge.',12340),
	 (552,0,0,0,0,0,0,0,0,'You found it! Most excellent, $N!',12340),
	 (553,0,0,0,0,0,0,0,0,'A great rumbling emanates from the ground.',12340),
	 (554,1,0,0,0,0,0,0,0,'A wise decision. I don''t believe there is a scholar other than myself with the skills to translate this scroll. And if its contents prove interesting, fear not. I will send for you.',12340),
	 (555,21,0,0,0,0,0,0,0,'Everyone will be so pleased: Chef Jessen''s Soothing Turtle Bisque is served once again!',12340),
	 (556,0,0,0,0,0,0,0,0,'These will do nicely. Although it looks like their magic is faded, it would be best if the Magus'' initial experiments were on inert specimens such as these.$b$bThank you, $N.',12340),
	 (557,0,0,0,0,0,0,0,0,'You found them. I trust the elementals from which you removed these bracers were amenable?$b$bHm...death has not only stopped my heart, but robbed me of my comedic timing, it seems.$b$bWell thank you, $N. You serve the Magus, and hence the Dark Lady, well.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (558,0,0,0,0,0,0,0,0,'WOW! You got Lady Jaina''s autograph for me! Thank you very much! And wow... she wrote a personal message on here - to me! I knew she''d be totally cool, and maybe someday I''ll thank her myself... when I become a hero of the Alliance!$B$BYou''re the best, $N. Thank you for being so nice to me.',12340),
	 (559,0,0,0,0,0,0,0,0,'Oh for the Love of the Light... they''re dripping on the ground.$b$bCan''t stand touching those things, myself. Fish are all well and good, but when they grow legs and start walking around... Haven''t eaten a fish in weeks, let me tell you, and in Southshore, that means you aren''t eating much.',12340),
	 (560,1,0,0,0,0,0,0,0,'Farren''s errand boy, are you?$b$bIf you assisted Farren in procuring these heads, then thank you. Southshore needs hard workers and effort to maintain its protection.',12340),
	 (561,0,0,0,0,0,0,0,0,'The naga, eh? Redpath must have just received the same information as me... Ha! He''ll not receive a promotion from my toil. Let me explain.',12340),
	 (562,4,0,0,0,0,0,0,0,'With the naga put down in Southshore, I''ll be a shoe-in to be reassigned. I''ll get to see Stormwind again... get away from this Light-forsaken port.',12340),
	 (563,0,0,0,0,0,0,0,0,'What''s this? Ah... so my attentive pupil has applied himself to the problem of the naga in Southshore. Thank you for bringing this to me, I will certainly take it into account when I review personnel assignments in the next month.',12340),
	 (564,2,0,0,0,0,0,0,0,'Ain''t that great news! Should-a gone and found me a regular ol'' war hero from day one to take care of them beasts. You''d-a made your pappy proud, $N.',12340),
	 (565,94,0,0,0,0,0,0,0,'Now it is time for the great Bartolo to work his magic! I require no wizard''s staff, no $C''s rod. For I, the great Bartolo, work magic with a mere needle and thread!',12340),
	 (566,21,0,0,0,0,0,0,0,'Productive work you do, $N. With Baron Vardus dead, the number of Syndicate leaders grows smaller. Their resistance and irritation will be short-lived.',12340),
	 (567,21,0,0,0,0,0,0,0,'You are quite the bounty hunter, $C. Well done.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (568,66,0,0,0,0,0,0,0,'Your duty was performed with honor, $C.',12340),
	 (569,66,0,0,0,0,0,0,0,'Well done. You have served the Warchief with honor.',12340),
	 (570,1,0,0,0,0,0,0,0,'Your knowledge of the jungle is strong, $N. These specimens will be perfect. I will thank the spirits for sacrificing such fine beasts for the cause of the Horde.',12340),
	 (571,1,0,0,0,0,0,0,0,'A most ideal sinew, $N. Your efforts will pay off soon.',12340),
	 (572,1,0,0,0,0,0,0,0,'Most excellent. I will prepare these at once.',12340),
	 (573,1,66,0,0,0,0,0,0,'With this Holy Spring Water the ceremonial choker is ready for enchantment.$B$BWear this with pride, $N, in the name of the Warchief and in defense of the mighty Horde.',12340),
	 (574,0,0,0,0,0,0,0,0,'$N. Sergeant Yohwa trusted your abilities, and I trust her. The defeat you brought to Kurzen''s forces is almost too much to hope for. I had feared we rebels were alone, and alone we could never stand up against the Colonel''s brilliance.$b$bPerhaps hope of our survival yet remains.',12340),
	 (575,0,0,0,0,0,0,0,0,'These skins should do. Their quality isn''t too important, given that they''ll make up the inside layer of the boots, but it''s still important that they''re comfortable.$b$bIf they''re a bit too rigid, I''ll use some tiger blood to soften it up. Tricks o'' the trade, you know?',12340),
	 (576,4,0,0,0,0,0,0,0,'Shiver me timbers and timber me shivers!  Ye found me beautiful eye!  Let''s see if she still fits.$b$b$n ho!  Blimey, I can see!!',12340),
	 (577,0,0,0,0,0,0,0,0,'My boots... they''re like sausages, $N. Look great, taste great. I tell you they''re filled with nothing but the finest ingredients and meats, and you eat it, and you love it.$b$bIt''s safer--and more enjoyable--if you just trust me, and don''t ask too carefully what''s really inside.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (578,0,0,0,0,0,0,0,0,'So the stories were true! Incredible!$B$BHowever, we will need to figure out a way to defeat the curse of the Stone of the Tides, if we are to retrieve it. The curse is magical business, we''ll need one of those wizards to help us out.',12340),
	 (579,6,0,0,0,0,0,0,0,'Do any of these titles interest you, $N?',12340),
	 (580,2,0,0,0,0,0,0,0,'Shiver me timbers!  Ye found the Cap''n''s grog!$b$bI owe ye big time, friend.$b$bSeems like a storm is a brewin'' outside.  Maybe I''ll just keep warm with one o'' these here bottles while we wait for it to pass....',12340),
	 (581,0,0,0,0,0,0,0,0,'These are good tusks, $N. You prove that you have the strength to hunt the Bloodscalps.$b$bAnd that is good, because you are not done hunting them.',12340),
	 (582,0,0,0,0,0,0,0,0,'Thank you, $N. I will inspect these heads to ensure poor Yenniku was spared the headhunter''s axe.',12340),
	 (583,2,1,0,0,0,0,0,0,'Jolly nice to make your acquaintance, $N. Haven''t seen a $C around these parts for some time.$b$bI situated myself with this expedition for one purpose: to hunt a great and elusive beast. Seeing that you''re a hero of sorts I am willing to let you take part in the hunt, but you must first prove yourself.$b$bI shall teach the ways of raptor killing to you. Ajeck will train you with tiger hunting. And Sir Erlgadin is a master of panther tracking.$b$bProve your skill and I''ll let you in on the big hunt.',12340),
	 (584,0,0,0,0,0,0,0,0,'You place the heads of Gan''zulah and Nezzliok within the cauldron...',12340),
	 (585,0,0,0,0,0,0,0,0,'Yes. These will serve me well. When my spirit is freed, I will enter the Nether with three fine servants!$b$bYou are a credit to your $R clan, and you have appeased me.',12340),
	 (586,0,0,0,0,0,0,0,0,'I do not want to believe it, but I cannot deny what you have done. And my rage eases, now that Ana''thek is defeated. $b$bYour might will drive you to great deeds, $N. But one day...I will see you in the Nether and we will again match strength.$b$bI will be waiting.',12340),
	 (587,0,0,0,0,0,0,0,0,'Good show, $n!  And just before I need to ship out too!  Can''t thank you enough, old friend.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (588,0,0,0,0,0,0,0,0,'Zanzil the Outcast??$b$bIf Yenniku is held by that troll, a vile and powerful witchdoctor, then I fear that only a faint hope remains. Faint. And tiny as the smallest insect.$b$bBut still, it is hope.',12340),
	 (589,0,0,0,0,0,0,0,0,'You have done well, $N. These shards are well formed. Already I hear them sing to me.$b$bAnd while you were gone, I spoke with the spirits of the jungle. I know where the Mind''s Eye rests...$b$b...And who guards it.',12340),
	 (590,15,0,0,0,0,0,0,0,'Incredible! What skill!$B$BThought you''d be easy prey, $N. Got me good, you did.$B$BHere''s the coin I promised... not as much as I said it''d be, but that''s on a count o'' me lying to ya in the first place.',12340),
	 (591,0,0,0,0,0,0,0,0,'You retrieved the eye! Your might is the stuff of legends, $N!$b$bAnd in getting the Eye, you must have defeated Mai''Zoth and sent him to the Nether. That is why the spirits would not mention him before.$b$bIt is good that he is gone from the world of flesh and bone, but now that he is in the realm of spirits...I fear he will begin a new reign.$b$bBut that is a worry for another time. Now, I must perform a ritual to bend the Mind''s Eye to our needs...',12340),
	 (592,0,0,0,0,0,0,0,0,'You''ve done it! You freed Yenniku from the will of Zanzil, and completed the mission I had thought was so desperate.$b$bOur tribe will remember your name in songs, $N, and we will etch your tale in stone so that it will live forever.',12340),
	 (593,0,0,0,0,0,0,0,0,'You place the Soul Gem upon his forehead. He shudders as his soul is sucked in, leaving his body, a mindless husk, behind.',12340),
	 (594,0,0,0,0,0,0,0,0,'Have you come to free me?',12340),
	 (595,0,0,0,0,0,0,0,0,'On top of the barrel, you discover a map with some hastily written text on it along with some coins.',12340),
	 (596,0,0,0,0,0,0,0,0,'Ah, very good. I will boil these, and leech them, and the spirits of their owners will weaken as I render their necklaces to paste!$b$bHere, $N. This will repay my debt to you.',12340),
	 (597,0,0,0,0,0,0,0,0,'Sure, I remember you, $C. Back from scouting I see....',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (598,0,0,0,0,0,0,0,0,'Your strength is great to have gained these necklaces, $N. The Skullsplitters fall to you like young saplings stomped to earth by a Basilisk!$b$bYour deeds are a boon to us.',12340),
	 (599,6,0,0,0,0,0,0,0,'Bloodsail Buccaneers attacking Booty Bay? They might as well throw themselves off the Overlook Cliffs. Nonetheless, by bringing me this information you have done my fleet of swashbucklers a great service. The Blackwater Raiders thank you.',12340),
	 (600,4,0,0,0,0,0,0,0,'Great! Wonderful! I can get a bundle for these!!$b$bThat Venture Company sure picked the wrong jungle to mine in, didn''t they? We''d all be in better shape if they moved out of here.$b$bThank you, $N. You''ve done a good deed this day.',12340),
	 (601,0,0,0,0,0,0,0,0,'Hm, I haven''t the eye to examine these bracers to see if any of them will be of any use, but I''m sure at least one of them will be able to help. Take them to Dalaran and have a mage look at them.$B$BAfter all, I can''t very well leave Booty Bay just to chat with those tiresome old mages.$B$BNot that I''m worried anyone would try to elbow their way into being the new baron. No one crosses Revilgaz and lives to tell of it.',12340),
	 (602,0,0,0,0,0,0,0,0,'The Stone of the Tides? Most interesting. It might surprise you to know that I wrote a tome - several years ago - pertaining to the legends of the Gurubashi Empire. I do know quite a bit about the Stone.$B$BAt least one of these bracers appears to have some magical residue I can analyze.$B$BLet''s see what I can see...',12340),
	 (603,0,0,0,0,0,0,0,0,'My dagger? What are you, some sort of comedian?$B$BWhat? Do you just want me to repeat the story of how I''ve gone from the best knife fighter in Booty Bay to the laughing stock of piratedom!$B$BI lost a knife fight to one of the Bloodsail Buccaneers--bunch of right bastards they are!--and he took my blade as spoils.$B$BIt''s not as though I can get by as a knife fighter with insults and a sharp tongue alone...',12340),
	 (604,1,0,0,0,0,0,0,0,'Perfect, $n.  Now that we know their plan, it''s just a matter of time.$b$bAnd to think the fools have dropped anchor just off the cape....',12340),
	 (605,0,0,0,0,0,0,0,0,'Aha!  These will do nicely, $N.  Yes, quite nicely!$B$BHere is your cut, and...it was a pleasure doing business with you.',12340),
	 (606,6,0,0,0,0,0,0,0,'Ack!  Where''d you get these?  No, don''t tell me. I don''t want to know!$B$BWho sent you?  Sea Wolf?',12340),
	 (607,11,0,0,0,0,0,0,0,'Heh heh, well done!  And when you showed Shaky those giblets, how hard did he shake?$B$BHah!  He''s so easy to read, when I play cards with him I can''t help but win!$B$BThanks for your help, $N.  Now it''s your turn to get paid...',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (608,21,0,0,0,0,0,0,0,'Ah, what a great day for the Blackwater Raiders!  Three cheers to you, $n!',12340),
	 (609,0,0,0,0,0,0,0,0,'Great! I can get a good price for these, especially for what''s inside Maury''s foot! Thanks much, $N!$b$bI hope those three learned their lesson: don''t bet something you can''t afford to lose.$b$bAnd maybe it''s too late for them, but...they should be careful of who they gamble with.',12340),
	 (610,0,0,0,0,0,0,0,0,'You beat Duncan? I guess you aren''t as wet behind the ears as you looked at first glance.$b$bI suppose that also means I shouldn''t challenge you to a fight any time soon!',12340),
	 (611,0,0,0,0,0,0,0,0,'Amazing! The Stone of Tides! It shall have a place of prominence in my collection of ancient troll artifacts. Did you see how it almost seems as though a tide is trapped within its surface? Magnificent!',12340),
	 (613,4,0,0,0,0,0,0,0,'You found it! Thanks a million, $N. You''ve been a big help to me!$b$bHere you go - you earned this!',12340),
	 (614,4,0,0,0,0,0,0,0,'You found it! Oh happy day, this is! Thank you, $N. Getting back my chest cools some of the fire in me.$b$bBut my revenge isn''t complete...',12340),
	 (615,0,0,0,0,0,0,0,0,'Hello hello, $N. Captain told me you''re going after Negolash, eh?',12340),
	 (616,0,0,0,0,0,0,0,0,'Interesting. Some time ago, I seem to remember reading a book once that suggested...$b$bAh, of course, a troll legend it was. If what Krazek reports is true, perhaps I will soon be able to add the Stone of the Tides to my collection of ancient artifacts and relics.',12340),
	 (617,1,0,0,0,0,0,0,0,'Well done, $N. 10 stalks of akiris reed wasn''t too much a challenge after all, huh? No offense to the naga, but hey, everybody''s gotta make a living.',12340),
	 (618,0,0,0,0,0,0,0,0,'You got my cutlass from Negolash! I can''t believe my fortune, $N! Meeting you has turned my luck to the better, make no mistake there!$B$BThank you! And if I ever get a new ship and you''re looking to sail the seas, you would be my honored guest.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (619,0,0,0,0,0,0,0,0,'You pile food and drink upon the raft...',12340),
	 (620,0,0,0,0,0,0,0,0,'Hello. Do you have business with me?',12340),
	 (621,1,0,0,0,0,0,0,0,'Ah, very good!  Here is your pay.$B$BAnd here is a little something extra... for your discretion.',12340),
	 (622,0,0,0,0,0,0,0,0,'It''s fixed! This is great, now I can get dinner started! Thanks so much, $N.$B$BI hope you were okay in Booty Bay. That place can get pretty rough, and... I heard rumors that the goblins will sometimes drag drunk sailors to their slave boats and take them to who-knows-where... to do who-knows-what...',12340),
	 (623,0,0,0,0,0,0,0,0,'What?! I got a lot better things to do then talk to the likes of you, $c. Make it worth my while or get outta my face.$B$BHuh? Bloads sent ya, huh? Well, whaddaya got for me?$B$B<Privateer Groy looks over the bundle carefully.>$B$BNot bad, not bad at all. Another bundle will make my client quite happy.$B$BI suppose yer next question''s gonna be about money, huh, $c? Of course it is!$B$BHere, take this coin and some advice: get off my docks.',12340),
	 (624,0,0,0,0,0,0,0,0,'The soggy parchment contains the next clue....',12340),
	 (625,0,0,0,0,0,0,0,0,'You find a musty scroll.',12340),
	 (626,0,0,0,0,0,0,0,0,'You open the chest to discover....',12340),
	 (627,0,0,0,0,0,0,0,0,'Ah, splendid! That was a big favor you did for me.$B$BHere is your payment...',12340),
	 (628,0,0,0,0,0,0,0,0,'Great! Thanks to your help I''ll have this order filled and sent off to Director Riddlevox on the next boat to Undermine. Ahead of schedule, even!$b$bFor all your hard work, here, I made some extras, so take a pair. It''s on Drizzlik.$b$bAnd remember, there''s no boot so fine as one of Drizzlik''s Excelsior line!',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (629,2,0,0,0,0,0,0,0,'This is good. When I return to Orgrimmar I will place this shard in a sacred place. It will remind us of the might and honor of Gri''lek.$b$bThank you, $N. Your deeds mark a growing friendship with the Darkspear tribe.',12340),
	 (630,1,0,0,0,0,0,0,0,'$N, you have saved me from a great dishonor. If it was within my power, I would offer you a place among my tribe. But for now, all I can only offer you is this token for the courage and nobility you have shown.',12340),
	 (631,0,0,0,0,0,0,0,0,'You search the tiny, dwarven corpse. Engraved into the helmet you can clearly read: Ebenezer Rustlocke.',12340),
	 (632,18,0,0,0,0,0,0,0,'Oh my, the news is grave....',12340),
	 (633,21,0,0,0,0,0,0,0,'The remaining bridge is saved! You have done a great service to King Magni and the people of Khaz Modan.$B$BNow if we can only hold out long enough for reinforcements to show...',12340),
	 (634,1,0,0,0,0,0,0,0,'My condolences go out to Longbraid and his brave soldiers. The news of the Thandol Span tragedy and the fall of Dun Modr hangs heavy in my heart.$b$bBut Stromgarde has fallen! Hence our presence here at Refuge Pointe. We are faced with retaking our own great city.$b$bHonor and duty require that we do not leave the Highlands until Stromgarde raises the mighty banner of the King once again. I will send word to Longbraid that he is on his own...',12340),
	 (635,0,0,0,0,0,0,0,0,'This crystal pulses, as if a living force is trapped within it.',12340),
	 (637,5,0,0,0,0,0,0,0,'You say you saw my Sully pinned beneath the icy waters? Say it isn''t so!$B$BLet me read what he wrote....',12340),
	 (638,2,0,0,0,0,0,0,0,'How you doing, $C? The task set before us by Vol''jin will be a difficult one, and any assistance you might provide will be appreciated and necessary.',12340),
	 (639,0,0,0,0,0,0,0,0,'Excellent, mon. That''s a good start to collecting the sigils we''ll need to remove Trol''kalar from Trollbane''s tomb.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (640,0,0,0,0,0,0,0,0,'Ah, you need me to reconstruct this sigil? It shouldn''t be too difficult... all the pieces seem to be here and the magical structure will be easy to reform.$b$bYou might want to close your eyes.',12340),
	 (641,0,0,0,0,0,0,0,0,'We''re halfway to being able to remove Trol''kalar from Trollbane''s tomb. We are not exactly sure where the third sigil is, as its holders seem to move around Arathi quite a bit, but I have faith that you''ll be able to find it.',12340),
	 (642,0,0,0,0,0,0,0,0,'Ah! You activated these shards. Already I feel more myself!$b$bBut alas, I am still far from free...',12340),
	 (643,1,0,0,0,0,0,0,0,'Losing their cavalry leader will prove a large blow to the Stromgarde defenders. Better yet, it means that we are only one sigil from being able to have Trol''kalar for ourselves.',12340),
	 (644,0,0,0,0,0,0,0,0,'Quite a day this is, $C. The blood of Trollbane will no longer haunt my people, and the sigils needed to take Trol''kalar are in our possession. Soon, very soon, we will strike against the hated trolls of Zul''Gurub.',12340),
	 (645,0,0,0,0,0,0,0,0,'Matching the lines on the face of Trollbane''s tomb with the glowing lines of the Sigil of Ignaeus, a flash of light consumes the Sigil, and the legendary sword Trol''kalar is released from the stone hands'' grip.',12340),
	 (646,1,1,2,0,0,0,0,0,'For generations, the forces of Strom and Arathor ravaged the trolls. Now their greatest weapon is in our hands. Our inching progress in the steamy forests of Zul''Gurub will be no more.$b$bYour assistance has been great, $N, and the Darkspear trolls are indebted to you.$b$bI will be sure that the sword is delivered to Nimboya at Grom''gol.',12340),
	 (647,1,2,0,0,0,0,0,0,'Ah, nothing like Foggy MacKreel''s Moonshine to warm you up on a brisk day! And here I was thinking the little bugger was going to be overdue on his bills again. Thank you, friend! Many thanks indeed!',12340),
	 (648,4,0,0,0,0,0,0,0,'Oh, YOU''RE the great savior of OOX-17/TN! I cannot even begin to express my thanks for your assistance! My homing robot series needs more developing, but your recovery has saved me countless hours of rebuilding time, as well as many gold pieces in rebinding costs!$b$bPlease, take your choice of any of these items I have. Hopefully, you will make good use of one of them. Thank you again for your generous assistance, my robots and I are in your debt!',12340),
	 (649,1,0,0,0,0,0,0,0,'Oh yeah, about the ripple dad wants! He wants to sell the ripple to a tavern here in Orgrimmar, but we''ll get more money if it is in its original packaging. I know someone who can do that, and he''s in the Hinterlands where the ripple is. But he''s, um, a high elf.$b$bWell, he''s a good high elf, as he''s not a part of the Alliance. Well, he''s not so much a good high elf as he is a drunken high elf. He loves, and I mean LOVES the hooch.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (650,6,0,0,0,0,0,0,0,'Ah, so you know Malton? He is an old drinking companion of mine. You see, I have found something that transcends the boundaries of artificial treaties and alliances - alcohol. Were we all to slake our thirsts on its blissful qualities, we all would be in a much better place spiritually.$b$bAlas, something tells me that your visit here is not to learn of alcohol''s redeeming values, now is it.',12340),
	 (651,0,0,0,0,0,0,0,0,'<Myzrael speaks through the stone.>$b$bYou have done it! You opened the Stones of Binding! I can feel the shackles about me loosen, and freedom draws ever closer.$b$bYou are a noble $C, $N. My rescuer!',12340),
	 (652,0,0,0,0,0,0,0,0,'You place the rod in the keystone. And a shudder is felt beneath you...',12340),
	 (653,2,0,0,0,0,0,0,0,'The Lady told me of your coming, $C. You are welcome in my abode for you, like I, serve a higher cause.',12340),
	 (654,0,0,0,0,0,0,0,0,'All right then, it will take me just a second to remove the power source. After that, you can do with it whatever you like now without having to worry about losing the data inside.',12340),
	 (655,1,0,0,0,0,0,0,0,'Ah, Gor''mul you speak of. Yes, from what he says, it seems he has never recovered from the death of Doomhammer.$B$BGor''mul was a captive here when Thrall and Orgrim fought to free the camp, but as the earth shook and our brethren escaped, he was left behind. He wandered alone and lost for years without direction or hope, until we returned to establish ourselves here in Hammerfall.',12340),
	 (656,0,0,0,0,0,0,0,0,'As the eldritch shackles are placed around the Shards, an unhuman wail is heard from far below. The scream is followed by a roar.$b$bThe Shards of Myzrael no longer invoke feelings of warmth and security as they once did. Now they pulse with an open menace... as if the thing beneath them holds ill will toward the surface.',12340),
	 (657,1,1,0,0,0,0,0,0,'If it brings Phin peace, I''ll destroy every single one of the Forsaken personally. He''s done so much for us since the plague. We never thought we''d find friends or family again.$B$BWhen you''re prepared, come let me know. We''ll get started right away.',12340),
	 (658,4,0,0,0,0,0,0,0,'Excellent!$B$BLet''s see what this is about...',12340),
	 (659,1,0,0,0,0,0,0,0,'Try and stay as quiet as possible, traveler.$B$BOrcs don''t take too well to being spied on, and there is more to this farm than meets the eye.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (660,2,0,0,0,0,0,0,0,'You''ve done a great service for us, $N. Thank you.$B$BI hope Kin wasn''t too much of a handful down there. She''s very friendly, but can be just as deadly when you''re her enemy.',12340),
	 (661,11,1,2,0,0,0,0,0,'So, the two troublemakers are all right after all? Haha, I''m glad to hear it. I thank you for bringing me news of their whereabouts and status--it pleases me greatly that they are still alive; the two of them are irreplaceable as friends and traveling companions.$B$BBut... it''s more important I thank you properly for your help. Here. Take this along with my group''s thanks.$B$BWith any luck, we''ll figure out what the Forsaken are up to, and put an end to it.',12340),
	 (662,0,0,0,0,0,0,0,0,'Knowing this information is secure will bring some ease to the command in Booty Bay. Well done, $N.',12340),
	 (663,3,1,1,0,0,0,0,0,'Ahoy, matey.$b$b''Twas a horrible mess. Seahorn will have my ship if he finds out what went down.$b$bOne of the Professor''s contraptions indicated the lost treasure was near this cove. I brought the Harbinger in to dock and signaled for the Spirit of Silverpine and Maiden''s Folly to follow suit.$b$bThen the sea rumbled. The tides lowered and the two ships crashed into the reef.$b$bIt''s not just a reef. Something''s down there....$b$bHelp my crew out and you''ll be rewarded handsomely.',12340),
	 (664,1,0,0,0,0,0,0,0,'Nice work out there, $N.$b$bThose scum deserved what they got. While nothin'' will ever bring me ship or me crew back, the death of those naga gives me some solace.',12340),
	 (665,21,0,0,0,0,0,0,0,'The goggles work perfectly now! Well done, $N.',12340),
	 (666,4,0,0,0,0,0,0,0,'Most superb, $N! The Captain will be very pleased! And just wait until word gets back to Fleetmaster Seahorn!',12340),
	 (667,4,0,0,0,0,0,0,0,'We survived the attack!$b$bWe could not have done it without you, $N.$b$bWe''ll be heading out as soon as the tide rises. If you weren''t such a promising hero I''d offer you a place on my crew. But I can tell you have bigger fish to fry.$b$bEven if you are a puny $r....',12340),
	 (668,11,0,0,0,0,0,0,0,'So the little gnomes proved their worth after all? I knew we kept those ankle biters around for a reason!',12340),
	 (669,273,0,0,0,0,0,0,0,'Ah, leave it to good old Shakes O''Breen! I knew that he was the right Captain for the mission!',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (670,2,0,0,0,0,0,0,0,'Thank you for making such a long and perilous journey. You have the gratitude of the Blackwater Raiders.',12340),
	 (671,0,0,0,0,0,0,0,0,'It will take some time for me to ascertain the true intentions of the Syndicate, but their obvious association with dark, demonic magic troubles me. I will tell you when I know more.',12340),
	 (672,1,0,0,0,0,0,0,0,'Excellent. The spirits of the raptors that gave these eyes will lend strength to the bearer of this amulet.',12340),
	 (673,2,0,0,0,0,0,0,0,'My restless nights will turn to peaceful slumber when I have destroyed this orb. Thank you, $n. It is a chilling reminder of the terrible power the demons held over the orcs before Hellscream released them from their curse.',12340),
	 (674,0,0,0,0,0,0,0,0,'What is this? Polished bone. What use have I for polished bone? Will a trinket restore the Horde to its glory?',12340),
	 (675,6,0,0,0,0,0,0,0,'It did not work, I see. Nonetheless, I feel that showing him the power of the shamans will eventually return Gor''mul to his once proud self. The amulet''s power was not great enough to show him our newfound power.',12340),
	 (676,6,1,0,0,0,0,0,0,'So, you think you''re strong enough to help Hammerfall? So be it.$b$bTallow either sent you to that ogre mound in the hopes that you would kill yourself or he thinks you''re strong enough to aid us. Either way, you''re here now and I am in need of more soldiers in our fight against the constant attacks.$b$bIf you plan on staying in Hammerfall then get some rest, and come speak to me again when you''re ready. There''s no shortage of fighting to be had.',12340),
	 (677,1,0,0,0,0,0,0,0,'The signs of war are upon your garments, and sweat drips from your brow. Good, very good indeed.',12340),
	 (678,21,0,0,0,0,0,0,0,'You are as strong as a kodo, and your lust for battle does your people proud.',12340),
	 (679,4,0,0,0,0,0,0,0,'You do your people proud, $N. The threat has been greatly lessened, and I am sure we will begin to thrive here in the Highlands.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (680,2,0,0,0,0,0,0,0,'You have done me a great service, $N. Know that my husband''s life and the safety of Hammerfall has been protected for another day because of your deeds. Please take this as a reward for your courage.',12340),
	 (681,1,0,0,0,0,0,0,0,'Very good, $N. With the deaths of those Syndicate members we should have an easier time receiving supplies from Southshore.$b$bPerhaps our cause yet has hope.',12340),
	 (682,66,0,0,0,0,0,0,0,'Thank you, $N. We will inform the families of these fallen soldiers that they were killed in battle.$b$bIt will be grim news to bear, but it is better than the uncertainty of a missing loved one.',12340),
	 (683,0,0,0,0,0,0,0,0,'It will take but a moment for me to peruse this letter...',12340),
	 (684,21,0,0,0,0,0,0,0,'You took down Marez Cowl? Well done, $N. Well done indeed!$b$bMarez menaced our Stromgarde defenders, and it is rumored she was an emissary between the Syndicate and some other, darker power. We are glad to see she''ll longer ply her powers against us.',12340),
	 (685,21,0,0,0,0,0,0,0,'Falconcrest and Otto? Wonderful!$b$bHere is your reward, $N. I am happy to pay it.',12340),
	 (686,6,5,0,0,0,0,0,0,'So King Magni Bronzebeard himself sent ye?$B$BMy, my! This must be important!',12340),
	 (687,3,5,1,0,0,0,0,0,'Hello. Hello, hello hello hello hello HELLO!$B$BI''m sorry - wait, no I''m not! Don''t be rude!$B$BOh no...that was crazy talk.$B$BBut...sometimes being crazy is my only solace.',12340),
	 (688,2,0,0,0,0,0,0,0,'Welcome, $C. The Lady has informed me of your coming, and if we are to bring her back to the surface then we have much to discuss...',12340),
	 (689,2,0,0,0,0,0,0,0,'Perfect! Better than I could have imagined!$B$BAnd I have quite an imagination you know...',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (690,6,1,0,0,0,0,0,0,'So, Malin sent ye? I don''t care if Muradin rose up from the dead and whisked ye here on a dragon. I''m busy! Talk to Kryten if you need somethin''.',12340),
	 (691,5,1,1,0,0,0,0,0,'Incredible! I can see why Malin asked you to come join us - very well done indeed!$B$BAt this rate, Skuerto and I will be headed back to Stormwind in no time at all.$B$BI believe my dwarven companion is back from scouting Boulderfist Hall; go speak to him when you''re ready.$B$BIt looked as though he might have had a bit of a scuffle with the ogres. Don''t mention that to him, though; he''s very sensitive about criticisms to his skills at scouting.',12340),
	 (692,1,0,0,0,0,0,0,0,'Ah, you found them! Good work, $N! These might be the only chance we have against the evil of Myzrael!$b$bJust let me find my scrap-ratchet and see if I can re-attach these fragments...',12340),
	 (693,5,1,0,0,0,0,0,0,'Brilliant, $N. One item down an'' three more to go, based on my list. The other three items are all in Stromgarde.$B$BTake a rest an'' get your strength back--the next phase of my plan''ll require a little more time an'' effort. Come back to me after you''ve gotten a warm meal an'' some rest.',12340),
	 (694,1,0,0,0,0,0,0,0,'You amaze me, $N. Well done again.$B$BGive me a moment to cast the proper spell to enchant the gem, an'' you''ll be ready.',12340),
	 (695,0,0,0,0,0,0,0,0,'Good, good.$b$bIf there are no other delays, how about we get started?',12340),
	 (696,21,0,0,0,0,0,0,0,'Malin couldn''t''ve asked a worthier person to come here an'' aid us, $N. You''ve done a grand job!$B$BHe''ll be pleased to see what an overwhelming success our mission''s been.',12340),
	 (697,5,1,1,2,1000,0,0,0,'<Archmage Malin opens the letter, and his eyes grow wide.>$B$BBy the Light, you''ve done it. How wonderful. Trelane will be so pleased. I''m sure Kryten and Skuerto are just as excited as I am to have them on their way back to Stormwind.$B$BThank you, $N. Please, take this to help you in your journeys.',12340),
	 (698,2,0,0,0,0,0,0,0,'Ah! Wonderful. Fresh meat for the fire tonight. Thank you, $N.$b$bYou''ve helped make the coming nights more tolerable. The fire burns bright, and our stomachs will be full.$b$bIts a pleasant surprise to have you bring us a shipment; Dar''s not the most attractive orc anyone''s laid eyes upon, but at least his attitude reeks far less than his smell.',12340),
	 (699,1,0,0,0,0,0,0,0,'Glad to see you''re alive and well, $N.$b$bThese claws should make do nicely. The more weapons we have at the ready for attacks against us, the better off we''ll be.$b$bI''ll get started on your weapon as soon as possible. It will only take a short time. I''ve become quite adept and quick at their production.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (700,1,1,0,0,0,0,0,0,'The granite seems but a small token compared to a great dwarf''s life. But no dwarf shall last on this planet for eternity.$B$BLet us just hope that the memorial stands as a reminder to those who will trod the great Azeroth of the future. Lest we not forget it is for them that brave soldiers such as Sully Balloo so valiantly gave their lives.',12340),
	 (701,1,0,0,0,0,0,0,0,'Yes, these will work perfectly. I will transfer their power and the spirit of the raptors into this orb. This orb will imbue Gor''mul with the fiery strength and intelligence of the raptor.',12340),
	 (702,0,0,0,0,0,0,0,0,'At least it is something interesting you bring to me this time. A strange power it emits...',12340),
	 (703,0,0,0,0,0,0,0,0,'Ah, I''ll get started on those wings right away. I can almost taste them already!$b$bAnd here''s the recipe in case you want to make them yourself!',12340),
	 (704,21,1,2,0,0,0,0,0,'Well done! With luck and diligence, we will find whatever link exists between the troggs and these ancient artifacts.$B$BYou have done a great deed for the Prospectors, $N. Your efforts will not be forgotten. And neither will Agmond.',12340),
	 (705,0,0,0,0,0,0,0,0,'These will work great! I just need to smash them into powder...then mix them with a little of this and a little of that.$b$bWatch out, scavengers! Prepare to be flashed!',12340),
	 (706,273,0,0,0,0,0,0,0,'Ah yes, this will do excellently. This will enable your weapons to strike with searing heat!',12340),
	 (707,6,0,0,0,0,0,0,0,'So Stormpike sent you, did he?  Good.$B$BI have a big task for you...',12340),
	 (709,4,0,0,0,0,0,0,0,'Oh, fortune is with us! Thank you! We may yet be saved!',12340),
	 (710,1,0,0,0,0,0,0,0,'These shall do nicely, $N. Thank you. Hmm, a bit more sand than I''d anticipated. Have to adjust the coefficient of friction. No, wait; it should still be negligible with the frost oil.$B$B<Mumbling to himself, Lotwil puts one fist into the palm of his other hand and stares at them as if fascinated.>',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (711,21,0,0,0,0,0,0,0,'$N, simply amazing! I would have thought it''d take half a dozen tauren to bring all these to me.',12340),
	 (712,6,0,0,0,0,0,0,0,'$N, have you ever considered becoming a research assistant? No? I''m not sure what I''ll do without your abilities here. Intelligence, curiosity, and strength--all combined into one package.',12340),
	 (713,4,1,0,0,0,0,0,0,'Stupendous! This should be the perfect coolant for my new bracers. If the enchantments don''t last a century, then I''ll give all my belongings to Servo.$B$BAll the mages of the Assembly will be in such awe after I finish this, $N. You just wait and see.',12340),
	 (714,25,1,0,0,0,0,0,0,'HA!$b$b<Lotwil grabs the gyrochronatom from you.>$b$bPerfect... just about done. No, really. I AM almost done now. This project is my top priority... at the moment. Let me pop this into place, and you can see for yourself what you''ve helped me create. It''ll just take me a few more minutes... maybe... possibly longer. Well, maybe a lot longer. We''ll see...',12340),
	 (715,273,1,0,0,0,0,0,0,'YES!$b$bI mean, thank you, $N. These will be helpful while traveling through the Badlands.',12340),
	 (716,25,0,0,0,0,0,0,0,'Here you go, $N. Try these on.',12340),
	 (717,4,0,0,0,0,0,0,0,'No longer will the Kirin Tor need to worry over the prisoners of Lethlor. I will return to report success to my master. Krasus will no doubt be pleased.',12340),
	 (718,1,1,0,0,0,0,0,0,'Thanks so much, $N. While you were gone, I... er... swallowed a mouthful of sand. It...$B$BWell, enough of that, we''ll go out and get some food tonight. Eat like kings!',12340),
	 (719,2,0,0,0,0,0,0,0,'Ye''re me savior, $C. I''m glad someone could teach those Shadowforge a lesson or two. Thanks for yer help.',12340),
	 (720,5,0,0,0,0,0,0,0,'Hammertoe''s alive?! This is amazin'', $N!',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (721,33,6,0,0,0,0,0,0,'Yes? Ah''m sorry... <cough> Feel so weak. Can ye come closer, $C?$B$BRyedol sent ye? Muradin be praised, that boy''s not as slow in the head as I once thought. <cough>',12340),
	 (722,33,273,0,0,0,0,0,0,'Ha! <cough cough>$B$BAh knew you''d find me amulet, $N.$B$B<weeze> Well done indeed, $N. <cough>',12340),
	 (723,6,1,0,0,0,0,0,0,'Hammertoe''s amulet? I think my spirits were higher when I thought he was dead. Knowin'' fer sure only makes the pain worse. This amulet was his life''s work. I can''t let his death be in vain.',12340),
	 (724,6,1,25,0,0,0,0,0,'Oh! Well, this is a different matter entirely. You probably don''t realize the gravity of this matter yet, do you?$B$BI care deeply about Hammertoe''s demise, but if he sent you here with his amulet, then he understood what''s at stake.$B$BWe will have to take time to mourn his death later.$B$BLet me show you one of the reasons this amulet is so valuable.',12340),
	 (725,1,0,0,0,0,0,0,0,'Ah, word from Historian Karnik. Excellent.$B$BI always have time for his business.$B$B<Advisor Belgrum opens the note and begins to read.>',12340),
	 (726,1,1,1,0,0,0,0,0,'You''re treating this matter with an urgency I''d expect from the king himself, $N.$B$BAll right, then. I know what''ll bring the Shadowforge down.$B$BTheir presence in Uldaman can be slowed if we strike them at their base of operations: Angor Fortress.',12340),
	 (727,2,0,0,0,0,0,0,0,'Oh. Greetings, brother.$B$BAnd praise to the dwellers beneath.',12340),
	 (728,25,1,0,0,0,0,0,0,'Be discrete with your signs, $C. There are those who do not believe the righteousness of our pledge.$B$BAnd there are those who would see us fail if they knew of us.$B$BWe must always be careful. And watchful. And patient.',12340),
	 (729,6,0,0,0,0,0,0,0,'Hollee. is that you? I need some help chiseling this stone. Hand me my stone brush, I think I see something.$b$bHey, you''re not Hollee! Don''t suppose you''ve seen my stone brush?$b$bNever mind that now! I promised the League I''d send the mysterious fossil I found. Where did Hollee go?$b$bSo much work to be done! Now where is that mysterious fossil... and my brush... and Hollee...$b$bAnd who are you... ''tis no matter, so long as you''re here to help.$b$bLet me know when you''re ready to start looking.',12340),
	 (730,1,0,0,0,0,0,0,0,'I''m so glad Chief Archeologist Greywhisker sent for us.... ',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (731,4,0,0,0,0,0,0,0,'Thank the stars Prospector Remtravel is safe! I told you he was absent minded. I can''t believe he insisted on staying there with all of those horrible creatures lurking about.',12340),
	 (732,1,1,0,0,0,0,0,0,'Good tidings you bring bearing the Sign, $N. The Sign of the Earth was created by the Dark Iron dwarves of Angor Fortress to bind two of Deathwing''s ruthless lieutenants, the twins Blacklash and Hematus.',12340),
	 (733,1,1,0,0,0,0,0,0,'It''s a start, $N, and it''ll have to do until we hear word from Ironforge or the Explorers'' League.$B$BNow, if only I could find some salt somewhere for my quenching barrel...',12340),
	 (734,6,0,0,0,0,0,0,0,'Cog #5, huh? Yeah, this isn''t going to be good.',12340),
	 (735,21,0,0,0,0,0,0,0,'You are resourceful, $C. If it truly is your charge to begin a new chapter of our order, then I believe you will run it well.',12340),
	 (736,21,0,0,0,0,0,0,0,'I am impressed! You possess great skill, or great fortune, to have gained these relics. Either way, you are an asset to us.',12340),
	 (737,4,1,1,5,0,0,0,0,'You got it! Oh, hope glimmers!$B$BYour efforts may yet save us, $N. A monument they should make of you! A shrine they should build! May your name be praised until your grandchildren have grandchildren!$B$BUnless...THEY are freed and rise to the surface.  If that happens then you can forget about children.$B$BIf THEY are freed, then we''re all worm food.',12340),
	 (738,0,0,0,0,0,0,0,0,'This skeleton must be the unfortunate remains of Agmond. His body is broken and battered, and his bones picked clean.',12340),
	 (739,1,1,0,0,0,0,0,0,'This is sobering news, $N. But Agmond had a strong arm and a fierce hammer-swing, and his skull was as thick as they come! Although he was killed by those cursed troggs I''m sure he took a lot of them down with him.',12340),
	 (741,5,0,0,0,0,0,0,0,'Oh my! Leave it to Prospector Remtravel to discover such a find!',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (742,1,0,0,0,0,0,0,0,'Welcome to the new frontier, $N. Ashenvale is a land of opportunity, one where a young $C like yourself is able to find boundless chances to prove their mettle. Look around the outpost here, and be sure to travel out to the Zoram Strand, as the Horde has another outpost there as well.$B$BYour presence here tells me that you''ve come to learn more about the hunt. Listen close, and I will gladly share with you what you need to know.',12340),
	 (743,0,0,0,0,0,0,0,0,'You have done well, $N. You seem well prepared to travel onward. Let the wind always be at your back.',12340),
	 (744,0,0,0,0,0,0,0,0,'Thank you for your help, $N.$b$bMy part in my brother''s ceremony is almost complete. Giving him his headdress and witnessing the ceremony are all my duty requires of me.',12340),
	 (745,1,0,0,0,0,0,0,0,'$N, it is good you''ve taken my task seriously. Respect of the land and its creatures is important. Death and life are a circle... a necessity. One cannot exist without the other. Take time to ponder this and do well to never forget it.',12340),
	 (746,1,0,0,0,0,0,0,0,'Thank you, $N. This will calm the beasts of Mulgore. And, spirits willing, it will teach the dwarves that hollowing the land is not the path to knowledge.',12340),
	 (747,2,0,0,0,0,0,0,0,'The tauren of Narache thank you, $N. You show much promise.',12340),
	 (748,1,0,0,0,0,0,0,0,'You have done well, $N. I will take these and bind their power into a totem of cleansing.',12340),
	 (749,0,0,0,0,0,0,0,0,'All sides of the crate are stamped with the sign of the Venture Co. Mining Division. Notes printed carefully on the side of the carton indicate that the contents are due for processing at one of their central plants.',12340),
	 (750,2,0,0,0,0,0,0,0,'The tauren of Narache thank you for these provisions, $N. With your skill in the ways of the hunt you will surely be revered in Thunder Bluff someday.',12340),
	 (751,0,0,0,0,0,0,0,0,'It does indeed appear that the Venture Co. is attempting to rob us of our natural resources. It is good to know this for true, and now it seems, we must do something about it.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (752,24,0,0,0,0,0,0,0,'You traveled all this way just to help an old woman? My my, aren''t you a keeper?',12340),
	 (753,6,1,0,0,0,0,0,0,'You carried this pitcher back at the Greatmother''s bidding, I see.$b$bYour willingness to help others and provide for the tauren of Camp Narache leads me to believe you would make the tribe proud in Thunder Bluff someday.',12340),
	 (754,2,0,0,0,0,0,0,0,'News of your deed reached me moments ago -- already the beasts near the well drink from it eagerly.$b$bYou have done a great thing for the land, $N. And you have done a great thing for the Tauren people.',12340),
	 (755,6,0,0,0,0,0,0,0,'Chief Hawkwind sent you? Embarking on the Rites of the Earthmother is no small task...',12340),
	 (756,2,0,0,0,0,0,0,0,'Thank you, $N. The purity with which these beasts hunt is vital in the creation of the next cleansing totem.$b$bThe goblins will never learn the difference between contending with the land, and living in harmony with it.',12340),
	 (757,21,0,0,0,0,0,0,0,'You have passed the first test of the Rites of the Earthmother. The tribe will be proud.',12340),
	 (758,2,0,0,0,0,0,0,0,'Ancestors of the Thunderhorn clan spoke to me in a dream, praising you for your actions near their well.$b$bFor their gratitude, they wish to give you this...',12340),
	 (759,1,0,0,0,0,0,0,0,'Very good, $N. I can feel the sacrifice of the land in this offering, and my spirit swells with sadness, and pride.',12340),
	 (760,2,0,0,0,0,0,0,0,'You''ve done it. You have cleaned the wells, and healed our land. Bloodhoof village is grateful, $N.$b$bMay the wind whisper your deeds for a hundred seasons, and may the waters of Mulgore remain clean forever.',12340),
	 (761,2,0,0,0,0,0,0,0,'I know that gathering these quills was not an easy task, $N.  In doing this, you prove that you are a $c of merit.  It is good to have you at Bloodhoof Village.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (762,2,1,1,0,0,0,0,0,'$N, your dedication to Ironforge and to the dwarven people cannot be refuted. I thank you for your help in this matter.$B$BI shall send word to Historian Karnik informing him that you have succeeded, and I shall also have aid sent to the Badlands as soon as possible to help recover the excavation site. Thank you again.$B$BBefore you go, there is one more thing I would ask of you in the name of King Bronzebeard.',12340),
	 (763,1,0,0,0,0,0,0,0,'Word from my good friend, Chief Hawkwind! Ah, I can see by his carvings you are of a special breed.',12340),
	 (764,0,0,0,0,0,0,0,0,'I don''t think there could be too much misinterpreting or ignoring of that signal, hm? The Venture Co. will know not to take the tauren lightly, or to be so arrogant as to believe we would allow them to steal the natural resources around us without protest.',12340),
	 (765,0,0,0,0,0,0,0,0,'My anger is somewhat lessened at the news that the villain Fizsprocket is dead. I will go through his personal effects and see if there is any additional information about what the Venture Co. has planned for the future. Thank you for your efforts, $N.',12340),
	 (766,2,1,0,0,0,0,0,0,'Ah, thank you, $N. Using the items you brought me, I will be able to create the remedy I need to stop the spread of the infection and, eventually, cure it completely. I owe you my life in thanks.$b$bBut I''ll never forget that screeching call when Mazzranache came upon me, the blaze of color as its beak descended...$b$bBe wary on your travels.',12340),
	 (767,2,0,0,0,0,0,0,0,'I sensed you would be coming to me, $c. I can always recognize one who is trying to pass the Rites of the Earthmother.',12340),
	 (768,1,0,0,0,0,0,0,0,'Ah, these are very nice pieces. They''ll make fine leather goods.$B$BHere, $N. Take this in trade...',12340),
	 (769,2,0,0,0,0,0,0,0,'Ah, good. Thank you, $N. My heart swells with pride to see youths interested in the craft of leatherworking.',12340),
	 (770,5,2,0,0,0,0,0,0,'I can barely believe my old eyes!  You defeated the great wolf Ghost Howl?  I look upon you with new respect, young $c.  You are a hunter of extreme skills!$b$bLet me offer you something.  My days of hunting are over, but I would be honored if you used one of my weapons in your hunts.$b$bMay it strike true, and bring you renown.$b$bAnd let us hope that Ghost Howl''s spirit has finally found peace.',12340),
	 (771,1,0,0,0,0,0,0,0,'I see you have learned to gather from our sacred land, $N. It will take but a moment for me to brew the Water of the Seers.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (772,2,0,0,0,0,0,0,0,'Be not afraid, $N. You have successfully passed the Rite of Vision.',12340),
	 (773,1,0,0,0,0,0,0,0,'You have shown great diligence in your yearning to pass the Rites of the Earthmother, $N.$b$bWe, the Ancestral Spirits, represent the mighty tauren who gave their lives bravely to found and protect our great city of Thunder Bluff. I hereby pass the duty of that protection over to you.$b$bYou have passed the Rite of Wisdom, young $C. Enter Thunder Bluff with pride.',12340),
	 (775,1,0,0,0,0,0,0,0,'Hail, young $c. I see you found your way to my doorstep.',12340),
	 (776,1,21,0,0,0,0,0,0,'Well done! A fine kill that was.$b$bI will send a gathering party to collect the carcass so we can retrieve the hide and meat.$b$bYou have done a great deed for your people, $N.',12340),
	 (777,1,0,0,0,0,0,0,0,'Ah, perfect. Stand back while I prepare to make more history!$b$b<Lotwil continues to work feverishly.>',12340),
	 (778,2,1,0,0,0,0,0,0,'Thank you, $N. That was quite an ordeal, wasn''t it?$b$bI''m not sure what could have gone wrong. It was a good thing my magics were here to help send the creature back to its home plane.$b$bPerhaps a little token of appreciation for all your hard work...',12340),
	 (779,0,0,0,0,0,0,0,0,'As you place the Runestones into the matching recesses, a violent rumbling shakes the earth as the Seal is broken.',12340),
	 (780,4,0,0,0,0,0,0,0,'Most excellent. These ingredients will make a fine stew and the loss of those boars should be a fair lesson to those vile Bristlebacks.',12340),
	 (781,0,0,0,0,0,0,0,0,'This is quite alarming indeed! But with this information we can call on our brethren from Bloodhoof Village to help thwart the attack. You have saved the lives of many tauren, $N.',12340),
	 (782,0,0,0,0,0,0,0,0,'With Tho''grun dead, his corpse picked clean by the desert winds and scavenging buzzards, the ogres will be put into disarray. Though a small victory, this will lead to a much larger one$B$BThe Sign of the Earth is now in our possession, and we can open the black drakes'' prison in Lethlor.  We shall free them from endless imprisonment, albeit to their doom!',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (783,1,0,0,0,0,0,0,0,'Ah, good.  Another volunteer.  We''re getting a lot of you these days.$B$BI hope it''s enough.$B$BThe human lands are threatened from without, and so many of our forces have been marshaled abroad.  This, in turn, leaves room for corrupt and lawless groups to thrive within our borders.$B$BIt is a many-fronted battle we wage, $N.  Gird yourself for a long campaign.',12340),
	 (784,66,0,0,0,0,0,0,0,'Word of your bravery travels fast, $c. Tales of your victory at Tiragarde Keep will be heralded in Orgrimmar.',12340),
	 (786,66,0,0,0,0,0,0,0,'The Horde would surely prevail if the Kolkar centaurs were to attack. But by preventing such an attack, we have spared our mighty warriors unnecessary bloodshed.$B$BAnd as sure as there is sand in the Tanaris desert, we know that there will be blood spilled before these trying times are through.$B$BYou have served your people well, $c.',12340),
	 (787,0,0,0,0,0,0,0,0,'Another one of Eitrigg''s recruits, hm?$B$BA sorry state of affairs we find ourselves in if this is the best the Horde can produce.  No matter.  By the time we think you''re ready to leave the Valley, you''ll be a proud warrior of the Horde.',12340),
	 (788,11,0,0,0,0,0,0,0,'Hmmm, not bad, $N. But don''t let it get to your head...you''ll fight tougher than boars in your career.$b$bNonetheless, you''ve proven yourself well, and your next trial will be against a considerably more dangerous opponent, so you''ll need some extra protection.',12340),
	 (789,0,0,0,0,0,0,0,0,'There is an important lesson that you must take away from fighting scorpids. The smallest or largest of opponents can still send you to your doom. In fierce combat, any number of things can prove your downfall.$b$bI have no more to teach you, $N. You have done well, and I will watch your progress with interest.',12340),
	 (790,0,0,0,0,0,0,0,0,'My blow was not enough to kill him, but looking at the damage I inflicted gives me some small measure of pride. That small measure will be all I have to sustain myself if I die, and in that light, the short list of my life''s accomplishments fills me with anger.',12340),
	 (791,4,0,0,0,0,0,0,0,'Most excellent, $N. Any good $c will surely find a use for this bag on the battlefield.$b$bI salute your vigor and willingness to die in the name of the Horde!',12340),
	 (792,21,0,0,0,0,0,0,0,'You have done well, $N.$b$bAlthough the Vile Familiars were merely pets of the darker powers within the Burning Blade, your success against them foretells greater deeds ahead.',12340),
	 (793,0,0,0,0,0,0,0,0,'The black dragonflight continues to ally with the renegade Blackrock orcs, and both must be brought into line, or removed. With Blacklash and Hematus dead, we can turn our attentions westwards, towards Blackrock Spire.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (794,2,0,0,0,0,0,0,0,'You retrieved it! Well done!$b$bYour efforts within the Burning Blade Coven are key in rooting out this cult in the Valley of Trials. But I fear they have further aims in our land.$b$bWe have not seen the end of them.',12340),
	 (795,0,0,0,0,0,0,0,0,'As you place the Runestones into the matching recesses, a violent rumbling shakes the earth as the Seal is broken.',12340),
	 (804,0,0,0,0,0,0,0,0,'From your description of the beast, I believe you must be speaking of Sarkoth! It is no wonder that Hana''zua was overtaken by it. Aid will be dispatched to him immediately, trouble yourself no more with Hana''zua''s plight.$b$bHowever, I must say, I am most impressed to hear that you brought Sarkoth to death. It is a feat to be proud of, $N. And that you would fight for a stranger''s honor, while other tasks occupied your time, your own honor is heightened.',12340),
	 (805,1,0,0,0,0,0,0,0,'Hm... your report comes at a bad time. The Burning Blade is not seen here in Sen''jin, but their evil has taken seed off the coast, on the Echo Isles.$b$bThe orcs are friends of the Darkspear Trolls. Honorable friends. We want to help the orcs, but... we need help too.$b',12340),
	 (806,4,1,0,0,0,0,0,0,'Aha! You got him!$b$bYou do your clan proud, $N. And because of you, Durotar is free of one more agent of evil.',12340),
	 (808,0,0,0,0,0,0,0,0,'Thank you, $N. You have saved Minshina. You have saved my brother''s spirit from slavery!',12340),
	 (809,6,0,0,0,0,0,0,0,'Neeru wants the Demon Seed destroyed, does he? Strange...$b$bVery well. If he wishes the seed gone, then I will tell you how to remove it.',12340),
	 (812,2,1,1,0,0,0,0,0,'$N, you''ve saved my life. Thank you.$B$BPlease take this; I hope it can at least help you in your travels, if not bring you some coin. From what you say, I won''t be usin'' it anytime soon. Kor''ghan is gonna march me through more of his rituals until I prove myself. More killin'' boars, more gatherin'' scorpid tails... <sigh>',12340),
	 (813,1,0,0,0,0,0,0,0,'Here is the antidote, $N. Take it to Rhinag as soon as you can, and be cautious.',12340),
	 (815,1,1,0,0,0,0,0,0,'You might be weak, but at least you''re not clumsy, $N.$b$bHere, take this and get outta my way. I''ve got cooking to do.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (816,18,1,0,0,0,0,0,0,'Oh, my son... my beautiful son.$b$bUncertain of my son''s fate, I have tormented myself since he left. Now that I know what''s happened, perhaps I can finally begin to mourn.$b$bThank you, $N. Please take this. I was going to give it to Kron as a gift when he returned successful. Now that I know he is dead, I cannot bear to look at it.',12340),
	 (817,1,1,0,4,0,0,0,0,'I am pleased, $N. Because of your help, our people will be protected, and not go cold as the seasons change.$b$bThank you.',12340),
	 (818,2,1,4,0,0,0,0,0,'Well done, young one... well done indeed.',12340),
	 (819,1,0,0,0,1000,0,0,0,'Well, I''ll be...$B$BThis was one of Chen Stormstout''s kegs. He traveled with Rexxar a long time ago. I haven''t seen or heard about him in a kodo''s age. I appreciate you bringing this to me, $N.',12340),
	 (821,11,1,0,0,0,0,0,0,'Haha... I never thought I''d make more of this stuff ever again.$B$BYou''ve stirred in me a great sense of nostalgia, $N. Kind of reminds me of the last time I blacked out from too much trogg ale. Thank you. The memories warm my stomach.',12340),
	 (822,11,1,0,0,0,0,0,0,'Haha! I knew you couldn''t resist some of this brew. Come back again anytime you want some more, $N. Just bring me more of the ingredients I had you collect.',12340),
	 (823,2,0,0,0,0,0,0,0,'Yes? You have something to report? Well then, let''s have it!',12340),
	 (824,1,0,0,0,0,0,0,0,'This globe... it is most disturbing. Many of the more powerful elementals receive their power and energy through such devices. To find one like this nearly intact is one thing - to find it so tainted is another.$b$bI will see that this globe is studied properly by the Earthen Ring. Perhaps we can bring an end to this corruption of the elements. Please - accept this as a fair exchange for bringing this globe to the attention of the Earthen Ring.',12340),
	 (825,66,0,0,0,1000,0,0,0,'Your recovery mission was a success, $c. I will see to it that these tools get to Orgrimmar with the next caravan.$b$bNicely done.',12340),
	 (826,0,0,0,0,0,0,0,0,'With Zalazane gone, our tribe can again sleep in peace.$b$bThank you, $N. The Darkspear tribe owes you much. If you suffer from an ailment, visit my assistant Bom''bay, behind me. His voodoo is strong...',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (827,0,0,0,0,0,0,0,0,'Good. Hiding within these collars is the secret behind the Burning Blade. And I will uncover that secret...',12340),
	 (828,2,1,0,0,0,0,0,0,'Welcome, $N.  Word reached me of your coming, and of your exploits in Durotar.$b$bYou are a $c of growing skill and renown.$b$bStay on the pure path, and your future will be great indeed.',12340),
	 (829,0,0,0,0,0,0,0,0,'Ah, and where did you get this? Good Margoz in Razor Hill sent you to me, did he?$b$bWell, let me take a closer look...',12340),
	 (830,1,0,0,0,0,0,0,0,'This does not bode well at all. You were wise to bring this information to my attention.',12340),
	 (831,5,1,0,0,0,0,0,0,'Countless times I urged the Warchief not to trust the humans, but personal pride is not what is at stake here.$b$bYou have served the Horde honorably, young $c.$b$bNow excuse me, I must counsel Thrall on these matters at once....',12340),
	 (832,1,2,0,0,0,0,0,0,'<Examines the Eye of Burning Shadow>$b$bIntriguing. The voice you heard mentioned my name? I am known for hunting down enemies of our Warchief, but...it is strange that I was singled out. Stranger still that the Burning Blade cultists from whom you recovered this pendant have a name so close to my own.$b$bI must study this pendant. I must study and, and must ponder the meaning of its message.$b$bThank you for bringing this to my attention, $N. You have done your people a great service.',12340),
	 (833,1,0,0,0,0,0,0,0,'Well done. You have sent those foul Bristlebacks a clear message. They will think twice before attempting to meddle in this holy spot again.',12340),
	 (834,0,0,0,0,0,0,0,0,'Hey, now isn''t that just the thing! You''ve got our supplies back for us. That''s great. I''ll be able to get back to work just as soon as I can find someone to haul these sacks for me.',12340),
	 (835,0,0,0,0,0,0,0,0,'I think I can breathe easy now, knowing that the harpies won''t be bothering our supply caravans anymore. And not one moment too soon, either. I hear I''m being sent some fun little toys with the next shipment!$B$BYou''re pretty good at what you do, $N, you ought to track down my boss in Ratchet. I''ll bet he could find some work for you.$B$BOh, and don''t worry, I wouldn''t forget to pay you for the service you provided me.',12340),
	 (836,4,0,0,0,0,0,0,0,'Oh, YOU''RE the great savior of OOX-09/HL! I cannot even begin to express my thanks for your assistance! My homing robot series needs more development, but your recovery has saved me countless hours of extra rebuilding time, as well as many gold pieces in manufacture costs!$b$bPlease, take your choice of any of these items I have. Thank you again for your generous assistance $N, my robots and I are in your debt!',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (837,0,0,0,0,0,0,0,0,'I will pass along word that the quilboars have been removed from their lairs, and that their structures may be set to fire. The removal of the Razormane from Durotar brings us closer to fully securing the borders of our new homeland.',12340),
	 (838,1,0,0,0,0,0,0,0,'Yes, $C, the High Executor mentioned you might be the one to trust in the matter of the key. I''ve dedicated a fair portion of my recent studies to the Scholomance, and I believe I know a means by which you can acquire one that will let you past the front door at will.$b$bThis task will not be easy, but such tasks seldom are. You most assuredly look like the type to know this as fact.',12340),
	 (840,6,0,0,0,0,0,0,0,'Oh, so Takrin sent you? He''s an excellent scout, I''m not sure what I''d do without him.$b$bI''ll sign your recruitment letter, but what we really need is someone at the Crossroads.',12340),
	 (841,0,0,0,0,0,0,0,0,'Very well, here is another power source. I highly recommend you using it properly this time, unless you are eager to spend ten more water pouches for another water source.',12340),
	 (842,0,0,0,0,0,0,0,0,'Alright, $n. You want to earn your keep with the Horde? Well there''s plenty to do here, so listen close and do what you''re told.$b$b$gI see that look in your eyes, do not think I will tolerate any insolence. Thrall himself has declared the Hordes females to be on equal footing with you men. Disrespect me in the slightest, and you will know true pain.:I''m happy to have met you. Thrall will be glad to know that more females like you and I are taking the initiative to push forward in the Barrens.;',12340),
	 (843,0,0,0,0,0,0,0,0,'Khazgorm met the fate he earned. I feel no remorse for the fool. He was an infidel on these lands.$B$BMay his death serve as a warning to all those who threaten to disrupt our way of life.$B$BNow let me take a moment to study the dwarf''s journal....',12340),
	 (844,1,0,0,0,0,0,0,0,'Very good, $N. With the plainstriders gone we''ll have an easier time keeping our supply chains intact. And I hope you learned a few tricks out there in the Barrens, for your next prey has a little more fire in its blood than the plainstriders...',12340),
	 (845,1,0,0,0,0,0,0,0,'Not bad, $N. Those zhevra hold a lot of strength in their legs. A sharp kick from them can knock even a tauren on its haunches!$B$BIt looks like you have some strength in you too. Are you ready for a real challenge?',12340),
	 (846,21,0,0,0,0,0,0,0,'I see you are quite industrious, $C.$B$BNo doubt we shall soon have a fitting surprise for those dwarves.',12340),
	 (847,1,1,0,0,0,0,0,0,'When the enchantment wears off, I will speak with Gor''mul. My thanks to you for your help in returning Gor''mul to the land of the living. I have no doubt he thanks you greatly as well.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (848,0,0,0,0,0,0,0,0,'Ah, yes. These are good specimens. Potent.$B$BI am Forsaken, and we honor our contracts. Here is your reward, $N.',12340),
	 (849,4,0,0,0,0,0,0,0,'You have done well, $N! May you be revered in Thunder Bluff as a defender of sacred tauren lands and a champion of the lost tribe.',12340),
	 (850,1,0,0,0,0,0,0,0,'Well done, $N. The centaur are low, brutish creatures, but a few have the wit and vision to lead. And those are the most dangerous.$B$BBarak was such a centaur. It is good that he is dead.',12340),
	 (851,0,0,0,0,0,0,0,0,'Very good. You must have really stirred up those centaur -- our guards spotted activity down near the Stagnant Oasis, which was probably you.$B$BYou should be proud of your deed, $N. There is much bravery in you.',12340),
	 (852,1,0,0,0,0,0,0,0,'I commend you, $N. These centaur are undisciplined and cannot focus their rage as the orcs can, but they are fierce nonetheless. In defeating them, your valor is proven.',12340),
	 (853,0,0,0,0,0,0,0,0,'Ah, the spores from the Barrens that Helbrim was gathering. He garnered your aid in delivering them? Good.$B$BAnd the emulsion is still potent, so you must have wasted no time in the delivery. Well done, $C.',12340),
	 (854,0,0,0,0,0,0,0,0,'It is good to see that more of our $R allies have come to assist us from as far away as Thunder Bluff. Again, I welcome you.',12340),
	 (855,1,0,0,0,0,0,0,0,'Nicely done. I''m sure you''ve struck fear into the surviving centaurs, $N. If they have sense, they''ll now calm themselves and stop their advances.$B$BBut I don''t think they will, and that is unfortunate.$B$BUnfortunate...for them.',12340),
	 (857,15,0,0,0,0,0,0,0,'At last, the power is mine again! Mine I say!',12340),
	 (858,0,0,0,0,0,0,0,0,'Yep, this looks like the right key. Let me just make sure I know how to work this thing...$B$BHmm... rotation control... This regulates speed and stability... fine arm movement control. Just look at this! I can''t believe the Venture Company could design something this much better than ours. I''ve got to get this back to Ratchet!',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (860,0,0,0,0,0,0,0,0,'You want to hunt in the Barrens?$b$bYour eyes are eager, and young. They''re not yet squinted from tracking your prey across this land''s dry plains.$b$bBut worry not. We''ll toughen your body and your mind. And we''ll teach you that there is more to hunting than finding and killing your quarry.$b$bPrepare yourself. Your journey begins. Now.',12340),
	 (861,1,0,0,0,0,0,0,0,'Skorn Whitecloud is a wise tauren.  He has hunted for years and years, and although his body is old, his spirit burns fiercely.  We are honored to have him with us.$b$bIf Skorn sent you to me, then you too must have the hunter''s spirit.  And to have gathered these claws shows your burgeoning skills.$b$bPerhaps you are ready to walk the path.',12340),
	 (862,0,0,0,0,0,0,0,0,'Normally I don''t like to eat these rodents when they''re so.... so... ripe. Like to let them rot for a few weeks to really bring out the flavor. But you look so hungry.$B$BLet me fix you some Dig Rat Stew. Ah, there we go.$B$BHere you go!',12340),
	 (863,0,0,0,0,0,0,0,0,'Hopefully we''ll be able to get something of value from the wrecked shredder prototype... my time''s running out! I''ll dispatch a salvage team to Wizzlecrank''s location on the double.$B$BOh, let me give you something for your trouble, too.',12340),
	 (864,1,0,0,0,0,0,0,0,'I will analyze this data immediately. Perhaps Keever''s insanity will prove to be my genius after all.$B$BAs for you... you are useful to me, and I reward quite well those who remain useful. Take this item, this coin, and most importantly my thanks along with them.$B$BCheck back with me from time to time - I wager that our working together on this project is not at an end.',12340),
	 (865,0,0,0,0,0,0,0,0,'Great, you got them! Now I just need to ground them down and mix them with some wine, and...',12340),
	 (866,0,0,0,0,0,0,0,0,'Yes yes, these are very nice! I will grow specimens from these roots and study them. I hope to find new properties from them. Hidden, valuable properties...!$B$BAnd don''t worry -- if I do then you''ll be the first to know. Because I''ll need someone to gather more!',12340),
	 (867,5,0,0,0,0,0,0,0,'Oh, these are nice. Real nice... Good job, $N. I look forward to seeing more of your work in the future.',12340),
	 (868,0,0,0,0,0,0,0,0,'You please me, $N. The eggs and the tool. Well done.$B$BAnd for your reward...',12340),
	 (869,0,0,0,0,0,0,0,0,'You got rid of the raptors!$B$BThank you, $N. You are a $C of worth.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (870,6,0,0,0,0,0,0,0,'You found a fissure in the earth, with gases bubbling from it? Strange. This may be an answer to our questions, but we cannot yet be sure.$B$BBut it is a clue. And I am grateful that you found it.',12340),
	 (871,2,1,0,0,0,0,0,0,'You have done well, $N. Those insolent quilboars will finally learn that the might of the Horde is not to be ignored.',12340),
	 (872,1,1,0,0,0,0,0,0,'Well done, $N. With Kreenig''s death, there will be a definite decline in the attacks on our caravans.$B$BYour people should be proud to count you among them.',12340),
	 (873,1,0,0,0,0,0,0,0,'You now are one with Isha Awak, $N. His spirit is with you. He lurks in your eyes...$B$BEyes that, one day, will learn to see.',12340),
	 (874,6,0,0,0,0,0,0,0,'My brother sent you, did he? Then you must have proven yourself to him. If you have earned the respect of Jorn, then you have my respect as well.$B$BAre you ready to tread farther down the hunter''s path?',12340),
	 (875,1,0,0,0,0,0,0,0,'Excellent work my friend. I think you''ll go far within the Horde.',12340),
	 (876,11,0,0,0,0,0,0,0,'HA! Well done, $N! Very well done... I wasn''t sure you were up to the task, but you''ve proved yourself quite the cut-throat. Thank you again for helping us suppress the Harpy epidemic. Here is your reward, use it well.',12340),
	 (877,5,0,0,0,0,0,0,0,'Your findings are amazing! The seeds I gave you were dried, and dead. Whatever rests under these oases can create life from nothing!$B$BWe must study this more...',12340),
	 (878,0,0,0,0,0,0,0,0,'Yes, yes... filled with joy because finally <snort> the Bristleback know my tribe''s pain, $R. That is how I should feel, but that <snort> is not the case.$B$BYou aid your people and they honor you. Mangletooth aids his people, and what do they do? They turn their backs on him. They forget him and leave him to rot in cage!$B$BI aid them even from locked behind bars and they send no one to save me!',12340),
	 (879,0,0,0,0,0,0,0,0,'It is done then. Better it ends this way, says Mangletooth. <snort> They should have <snort> made sure I was dead when they turned their backs on me instead of leaving <snort> me here in this forsaken cage.$B$BThere is but one task left for you to finish, $R.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (880,2,0,0,0,0,0,0,0,'Thank you, $N. Studying the beasts of an area can tell much about the area itself. We shall see what tale these shells tell.$B$BPlease accept my gratitude for your aid ... and perhaps you can use these coins. I find that I do not need them.',12340),
	 (881,1,0,0,0,0,0,0,0,'You''ve beaten Echeyakee, and though his days of hunting are over... his spirit is with you. He will show you the strength found in subtlety, and the honor in mercy.$B$BYour path is still long, $C. Let''s hope you stride it well.',12340),
	 (882,1,0,0,0,0,0,0,0,'This fang is merely a token, but what it represents is profound.$B$BIshamuhale''s strength is in you, $N. May you use it with temperance. That is your burden.$B$BThat is your honor.',12340),
	 (883,1,0,0,0,0,0,0,0,'Lakota''mani is called Earthshaker in our language, and his steps are like gathered thunder. He is with you now, and his courage mingles with yours. Together there is no conflict you cannot face.$B$BWalk tall, $N. Walk tall, Earthshaker.',12340),
	 (884,1,0,0,0,0,0,0,0,'The thunder lizard Owatanka is called Bluebolt by the tauren, for within him resides a speed that belies his size. It is said that lightning struck Bluebolt long ago and, fed from the sky''s rage, the great beast''s energy is without limit.$B$BMay his energy flow through you, $N. For you now keep pace with Owatanka.',12340),
	 (885,1,0,0,0,0,0,0,0,'The thunderhawk is a rare beast of the Barrens, and its death can portend great fortune, or great doom.$B$BBut Washte Pawne, called Spirit Biter in Taurahe, can bring neither... or both.$B$BThe pain you felt from hunting Spirit Biter is the pang all feel who make great gains at great costs. The sting you felt is the pain of regret.$B$BBut I can see you have conquered this. You have learned that regret turns to wisdom, and that through pain one gains strength.$B$BYou have learned much, $N.',12340),
	 (886,2,0,0,0,0,0,0,0,'My brethren in Thunder Bluff were wise to send you, young $c.  For the mystery of the Barrens is one that I alone cannot unravel.$B$BWith your aid, let us hope we can find answers to our questions.',12340),
	 (887,4,0,0,0,0,0,0,0,'You did good, kid. A little more work like that, and it''ll be one less thing I''ll have to worry about. Hopefully they''ll be convinced that they should relocate their operation elsewhere.$B$BIn the meantime, there is the small matter of getting back the goods they stole from me!',12340),
	 (888,0,0,0,0,0,0,0,0,'It''s a relief to get all this stuff back, so thanks for your help, $N. You know, I could use a $R like you to help out with my operation here. If you''re ever looking for work, don''t forget about how well Gazlowe pays for service!',12340),
	 (889,0,0,0,0,0,0,0,0,'Good. Go with Agamaggan''s spirit as your guide, $R. Return to me if you desire more of Agamaggan''s magics.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (890,0,0,0,0,0,0,0,0,'Ah, Gazlowe sent you, did he? Just a moment, let me take a look here and check my own logs and make sure I didn''t have Gazlowe''s shipment sent to the wrong place.$B$BBet he''s waiting for those boots from Drizzlek...',12340),
	 (891,4,1,0,0,0,0,0,0,'Alas, the righteous Alliance guns have been silenced. You shall be rewarded for your aid, $N.$B$BNow to tend to the grim task of recovering the bodies of the dead....',12340),
	 (892,1,0,0,0,0,0,0,0,'No dice, eh? I guess it must have been the Freebooters then... Dizzywig''s on the level, I''m sure he wouldn''t cheat me like that. After all, he is on the payroll.$B$BLooks like I''ve got some goods to get back, $N. What do you say?',12340),
	 (893,4,0,0,0,0,0,0,0,'Excellent, excellent specimens indeed.$B$BThe quilboar are further along than I had expected.$B$BHere, $C, take this and get out of my way. I''d better take a closer look at these weapons. We may have underestimated our enemy, and that''s the kind of mistake we can''t afford to make.',12340),
	 (894,0,0,0,0,0,0,0,0,'A variety of buttons, levers and blinking lights are somewhat erratically arrayed on the face of the control console. A small gauge indicates that the apparatus is currently operating within optimal levels, and indicates that control valves one through three are currently open. There is a small keyhole set into the lower right side of the control panel.',12340),
	 (895,0,0,0,0,0,0,0,0,'Ahhhh! That sort of business. You know, I saw the Heedless once on the open seas. Fearsome ship, or was that boat... those sailors are so particular!$B$BAnyways, watching her glide across the water was quite a sight to see. I''m glad her infamous captain will trouble my ships no longer.',12340),
	 (896,4,0,0,0,0,0,0,0,'Look at the size of that thing, $N! We''re going to be rich! Let''s see, according to the rates I''ve seen on gems going into Undermine, I should be able to figure out your cut--fifty percent, don''t worry!$B$BNow let''s see... I think this should do about right. Pleasure doing business with you, $N.',12340),
	 (897,274,1,0,0,0,0,0,0,'I can tell nothing of the nature of this beast, for its spirit has fled. But as you guessed, it does not belong in the Barrens. I fear it may herald a grim future for our people...$B$BBut for now, prepare yourself, and let us hope that time unravels the mystery of this creature.',12340),
	 (898,4,2,0,0,0,0,0,0,'And to think, we thought Firebough was long dead!$B$BYour heroics have earned you a place of honor with the Thalo''dan Privateers, $N.',12340),
	 (899,1,1,0,0,0,0,0,0,'$C, you take my task seriously, and for that I thank you.$B$BAlthough my desire for revenge remains, I can at least smile seeing that the quilboars have felt pain themselves.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (900,0,0,0,0,0,0,0,0,'The lights indicating the three control valves dim as they are shut off. Green lights slowly fade into yellow, and the switch controlling the apparatus is now moveable, with the valves closed, it can be turned off.',12340),
	 (901,0,0,0,0,0,0,0,0,'Turning the key in the lock, the control console unlocks. A red light at the top of the console turns off and all power drains from the terminal.',12340),
	 (902,0,0,0,0,0,0,0,0,'This is... er... interesting... yes. I''ll have it sent along to the Tinkers'' Union headquarters in Undermine. I''m sure after some careful dissection and research, they''ll be able to make some sense of it.$B$BBut, perhaps I''ll have a little look myself first...',12340),
	 (903,1,0,0,0,0,0,0,0,'Ah, I see you''ve been busy, lurking in the grasses and hunting prowlers. Do you think, then, it is time to face a champion among them?',12340),
	 (905,1,0,0,0,0,0,0,0,'Is your task finished? Ponder the life of the Scytheclaw as you do it. There are important lessons within every creature''s lifespawn. $B$BSome of the others believe I have been too heavy handed in my lesson. I know that you are simply following my orders, but I want you to consider the life of the creatures you are slaughtering. $B$BThough they are at times a nuisance, they only become threatening when we seek their slaughter. This days defilement will cause us more trouble than it will solve problems...',12340),
	 (906,5,4,1,0,0,0,0,0,'You found the Razormane leader and killed him yourself, $N? Amazing.$B$BI am without words, but that does not mean I am without thanks. The people of the Crossroads would do well to respect your strength.$B$BI must admit, I thought the leader of these raids on our supply lines was another quilboar. Thank you again, $N.',12340),
	 (907,1,0,0,0,0,0,0,0,'It is good to see you return with proof of victory. And it is good to know you have done so with your bones unbroken.',12340),
	 (908,0,0,0,0,0,0,0,0,'This is exactly what I need! A fathom core is an incredible well of information that we will be able to draw much good from. Whatever the Twilight''s Hammer is up to in there - and believe me when I say it is no good - my comrades and I will now uncover.$b$bYou''ve done well here today; the Earthen Ring looks upon you warmly for assisting us. You''ve also helped the Horde as a whole, and for that you should be proud.',12340),
	 (909,0,0,0,0,0,0,0,0,'This... this is quite the find, $N.$b$bYou acquired this from Baron Aquanis in Blackfathom, you say? Baron Aquanis has long been thought of as a corrupted elemental power; this globe will prove what exactly had corrupted him. While it would be no surprise if it turned out to be the Twilight''s Hammer, our studies will also show how they did it as well.$b$bYou did well in bringing this to me. Please - take this, along with the Earthen Ring''s warmest regards.',12340),
	 (910,0,0,0,0,0,0,0,0,'Wow, the ocean is HUGE! There were a lot of sea gulls and stuff too - It''s just as noisy and as bustling as I thought it would be. There are pirates near by too - so cool!$B$BThank you for taking me to Ratchet, $N. That was so awesome!',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (911,0,0,0,0,0,0,0,0,'Wow, Ashenvale is where real adventure happens! Have you ever fought in Ashenvale, $N? When I become a hero when I grow up, I wanna come to Ashenvale and fight for the glory Horde!$B$BThank you for taking me to the frontier, $N. You''re the best!',12340),
	 (913,2,0,0,0,0,0,0,0,'You, like the thunderhawk, should be proud. You have bested every foe we set you before, and have done so with strength, courage and honor.$B$BBut your path, $N, continues. In fact, you will find that true hunters forever strive, forever walk their path with the same pride you have shown me.$B$BNow, it is time to move on.',12340),
	 (914,4,1,2,0,0,0,0,0,'You have done it, $N. You killed the leaders of the Druids of the Fang. My dreams are now free of their wicked faces, and you have helped save the Barrens from a cursed future.$b$bI thank you, $N. I thank you for myself, for the druids of Thunder Bluff, and for the land.',12340),
	 (915,0,0,0,0,0,0,0,0,'Mmmmmmmmm! I love their strawberry ice cream! If there''s one thing Tigule and Foror know to do, it''s make ice cream!$B$BThank you very much $N - this is the best treat ever!',12340),
	 (916,1,0,0,0,0,0,0,0,'Thank you, $N. When I return to Darnassus I will compare the venom within these sacs with the venom of other spiders. It is my belief that it will have properties linked to the recent growth of our new world tree.',12340),
	 (917,1,2,0,0,0,0,0,0,'Ah, very good. I will have this egg and the venom transported to Darnassus, then return there when my studies are done here. I expect to find out a great deal from these specimens, $N. You have been a great help to me.',12340),
	 (918,2,0,0,0,0,0,0,0,'You got them. This is good!$b$bI will plant these seeds in special soil I have prepared. I believe the seeds will sprout into timberlings who are much more docile. Perhaps later you can see the results!',12340),
	 (919,1,2,0,0,0,0,0,0,'That''s a lot! I''m afraid they''re spreading at a dangerous rate. I hope I can solve the riddle of what is tainting them.$b$bThank you for your help, $N. The land is a cleaner place from your efforts.',12340),
	 (920,1,0,0,0,0,0,0,0,'Ah, $N. I was hoping you''d be prompt in answering my summons. I have an important task that I would like you to perform.',12340),
	 (921,1,0,0,0,0,0,0,0,'So you have heard the first part of the aftermath of the Battle of Mount Hyjal. There is much more to be told and the task you have begun here will continue through the rest of your journey through Teldrassil and into Darnassus.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (922,1,0,0,0,0,0,0,0,'Ah, a timberling seed? I wanted to try growing one of these to help Denalan with his studies.$b$bBut I''m afraid I''ve discovered that a corruption has grown in many of the timberlings, and seeds from such creatures carry their parent''s taint. They are beyond my talents to repair.$b$bDenalan is very skilled with things that grow. He may find a cure for future timberlings. He may be their only hope.',12340),
	 (923,2,0,0,0,0,0,0,0,'Well done! These tumors are the symptom of the timberling''s disease. They are filled with a poison that we must cleanse from our new land.$b$bI will dispose of these tumors. Thank you, $N.',12340),
	 (924,0,0,0,0,0,0,0,0,'Your task is complete. You have destroyed the Demon Seed as Neeru bid. But this is not the end...$b$bThe destruction of the Demon Seed sent waves of power through the ether, waves of staggering force. I felt them, and I am sure other beings did as well. Others who will wonder why their toy was broken...$b$bBut regardless of future troubles, I have something for you. Neeru sent it as payment. And he bid me thank you.$b$bSo, thank you.',12340),
	 (925,0,0,0,0,0,0,0,0,'WOW! You got Cairne''s hoofprint for me! Thank you very much! And wow... he wrote a personal message on here - to me! I knew he''d be totally cool, I just did! Maybe someday I''ll thank him myself... when I become a hero of the Horde!$B$BYou''re the best, $N. Thank you for being so nice to me.',12340),
	 (926,0,0,0,0,0,0,0,0,'These stones are infused with magical energy, but purposefully flawed. They are very unstable and once removed from the table they will consume themselves quickly.',12340),
	 (927,0,0,0,0,0,0,0,0,'...What is this? A timberling heart?? It''s covered with a foul moss!$b$bThank you for bringing this to me, $N. I will examine the heart and, if fortune shines, determine the nature of the moss about it.',12340),
	 (928,1,0,0,0,0,0,0,0,'Ah, I see. You were sent by Tenaron. Well then, it would seem we have much to talk about, much to do, and little time to do it in.$B$BI think we''d best get started.',12340),
	 (929,1,0,0,0,0,0,0,0,'After the Battle of Mount Hyjal, we were without direction. Nordrassil smoked from the fire it unleashed, and our immortality--the very essence of our beings!--was lost.$B$BIt was in this trying time that the Betrayer was freed from his prison, and Shan''do Stormrage disappeared. A dark time for all.',12340),
	 (930,5,1,0,0,0,0,0,0,'You found this on Teldrassil? Intriguing... this fruit is exotic. Perhaps its seeds were brought here from far off. Perhaps even as far as Azeroth! And there''s something about this fruit... it seems to have reacted very strangely with the soil of Teldrassil.$b$bThank you, $N. Now if you''ll excuse me, I must study this further...',12340),
	 (931,6,2,0,0,0,0,0,0,'Where did you get this? I haven''t seen a plant like this since a sojourn I made to the Swamp of Sorrows... decades ago! It''s amazing that a specimen made its way to Teldrassil. And it''s grown to such a size!$b$bThank you, $N. Forgive my shortness of words, but there is a test I would like to perform on this frond...',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (932,0,0,0,0,0,0,0,0,'With Lord Melenas laid to rest I can finally move on to other matters. Thank you, $N.',12340),
	 (933,1,0,0,0,0,0,0,0,'Shan''do Stormrage never returned, and the druids were in disarray, and to this day we still do not know what became of him. With Malfurion missing, Arch Druid Fandral Staghelm took over the leadership of the druids, convincing the Circle of Ancients in Darkshore that it was time for our people to rebuild, and that it was time for our people to regain their immortality.$B$BWith the approval of the Circle, Staghelm and the most powerful druids grew Teldrassil, the new World Tree.',12340),
	 (934,0,0,0,0,0,0,0,0,'To be in the presence of the Oracle Tree... it is almost to feel wisdom take form. Let me continue the telling...$B$BWith Teldrassil grown, the Arch $C approached the dragons for their blessings, as the dragons had placed upon Nordrassil in ancient times. But Nozdormu, Lord of Time, refused to give his blessing, chiding the $C for his arrogance. In agreement with Nozdormu, Alexstrasza also refused Staghelm, and without her blessing, Teldrassil''s growth has been flawed and unpredictable...',12340),
	 (935,1,0,0,0,0,0,0,0,'Ah yes, the water I had requested. Tenaron and Corithras certainly took their time in having it delivered... perhaps not choosing the most reliable of messengers... hmm.$B$BNonetheless, I can finally get back to my work then. The weight of Teldrassil''s problems fall upon my shoulders. A yoke I would wish to soon be rid of.$B$BTake this, you may find some use for it.',12340),
	 (936,2,0,0,0,0,0,0,0,'Greetings, $C; I am glad you are interested in assisting our research. There is much to do, and I would be doing you a disservice if I informed you that the work this entails is not dangerous. Hopefully this will not scare you off... but from the looks of you, I take it that danger is something that you have dealt with before.',12340),
	 (937,1,0,0,0,0,0,0,0,'I am impressed by what you have accomplished here in so short a time, $N. Would that I could ask you to remain here to assist me with my duties... but I know in my heart that greater tasks lie ahead for you.$b$bI have noticed the Oracle Tree has just shed a piece of its bark. No doubt it has a task that it wishes completed. You should speak with it.',12340),
	 (938,1,0,0,0,0,0,0,0,'Oh, thank you, $n! I feared I would never see Mist again, knowing only her death in my heart, never to be united with my faithful companion. I owe you more than you can know, and you have my eternal gratitude.',12340),
	 (939,1,0,0,0,0,0,0,0,'I sense the suffering of ancient ones, $N...$B$BHolding these items is almost unbearable...',12340),
	 (940,1,0,0,0,0,0,0,0,'I wondered why the Oracle Tree had not communicated with me for so long... It seems that some problems are lessened while others grow to greater concerns.$b$bI fear my work on Teldrassil shall never be completed, and our immortality never restored.$b$bNonetheless, you have done the Oracle Tree''s task well, and should be rewarded for your diligence.',12340),
	 (941,0,0,0,0,0,0,0,0,'You place the heart within the planter, and it quickly digs itself in!$b$bA few seconds later it wriggles back out, cleansed. It pulses slightly... beckoning for you to take it.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (942,6,5,0,0,0,0,0,0,'Oh my! You say this came from the distant lands of Kalimdor?$B$BAmazing! Simply amazing!',12340),
	 (943,4,0,0,0,0,0,0,0,'Most excellent, $N!$B$BNow to see if I can use the stone to decipher the powers of the fossils.',12340),
	 (944,0,0,0,0,0,0,0,0,'The Twilight''s Hammer is at the Master''s Glaive?$b$bUnfortunate.$b$bThe old lord impaled by the glaive is long dead, but that does not mean slivers of his power do not still remain.$b$bThe Twilight''s Hammer must be seeking this power.',12340),
	 (945,0,0,0,0,0,0,0,0,'My sister was where?? Therylune doesn''t mind getting herself dirty, but still! That''s a long way to wander, and the Master''s Glaive is an unwholesome place...$B$BWell thank you, $N. It was very nice of you to let me know she''s all right.',12340),
	 (947,2,0,0,0,0,0,0,0,'Many thanks, $N. These mushrooms are fine specimens!$b$bAnd when you were at Cliffspring Falls, did you find anything to confirm the warnings of the Ancients?$b$bThe Ancients are wise, but I had hoped that, this time, they were wrong.',12340),
	 (948,0,0,0,0,0,0,0,0,'$N. You are here.$b$bGood.$b$bWe have matters...to discuss. You and I.',12340),
	 (949,0,0,0,0,0,0,0,0,'This book is hand printed in an ancient language, and illustrated by a master artist.',12340),
	 (950,0,0,0,0,0,0,0,0,'A chaotic, primal magic surrounds this parchment of scribbles. I sense the work of the old ones in it.$b$bLet us hope it reveals the purpose of the Twilight''s Hammer in Darkshore...',12340),
	 (951,0,0,0,0,0,0,0,0,'Thank you. These relics are from a time when Mathystra shone. That once great bastion of the elves has faded, but shards of its magic remain. Let us hope we can unlock the secrets of that place before our enemies...$b$bBe vigilant, $N.',12340),
	 (952,0,0,0,0,0,0,0,0,'Ah. Thank you, $N. It is strange, though. The Arch Druid always seems in such a hurry. The forest knows that all shall come to pass in the appointed time. Shan''do Stormrage understood that.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (953,1,2,0,0,0,0,0,0,'We have few records from the time around the War of the Ancients, especially near the destruction of the Well of Eternity. Given the upheaval and cataclysmic events that were taking place, it is no big surprise.$B$BThank you, $N. With your help, my work here is finished, and I will be able to deliver a full report to the Circle.',12340),
	 (954,6,0,0,0,0,0,0,0,'Ahh... To what could I possibly owe the exceedingly special honor of a $r such as yourself as company. Truly it says much of my current companions--with no offense to my hosts, the noble grells and satyrs--that your presence could be considered an improvement.$b$bBut please, do not let my uncivil tongue drive you from the place. It has indeed been many years, decades even, since I had civil accompaniment.',12340),
	 (955,0,0,0,0,0,0,0,0,'Indeed... The grells of Bashal''Aran do not possess that which I am searching... however they have come into contact with it recently. Recently... I would reckon that by your time, not mine. Recent for me stretches into the veil of the past, almost another Age...',12340),
	 (956,0,0,0,0,0,0,0,0,'It... it is hard for me to even believe that what I hold now is that which has held me for so long. Let us waste no time, $N. When the seal is destroyed, I might walk the forests of the earth freely again.',12340),
	 (957,15,0,0,0,0,0,0,0,'I am freed, $N! I can now see with my own eyes the changes that have come to our world... Only bits and pieces have I known. To think that when I last walked freely, the Well still stood and the Highborne held court with Azshara, our beloved queen.$B$BI sense that my jailor, my former master, Athrikus, still lives... Already my feelings of hopelessness will give way into thoughts of vengeance.',12340),
	 (958,1,0,0,0,0,0,0,0,'Though it is surely a figment of my imagination, I feel as though I can almost feel the taint of foul Highborne magic upon them. I will have these destroyed, so that their long dormant evil might never be released again.',12340),
	 (959,4,0,0,0,0,0,0,0,'Superb! And just as I was about to lose my job too! I will see to it that Gazlowe gets this gift immediately.$B$BThank you, $N. Nicely done, I say!',12340),
	 (961,0,0,0,0,0,0,0,0,'The finding of Twilight''s Hammer cultists is troubling.  I must meditate on their intentions...$B$BWhen you have more information, speak to me through a scrying bowl.  If you require a phial of scrying in order to create a bowl, then...here is another.',12340),
	 (962,4,0,0,0,0,0,0,0,'Ah, splendid specimens. You have done well, $N.',12340),
	 (963,2,0,0,0,0,0,0,0,'Thank you, $n. Perhaps it would have been better... if I had done it myself. But even after these thousands of years, I could not bear to raise my hand against my beloved.$b$bPlease, I would be alone with my grief...',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (964,5,0,0,0,0,0,0,0,'This''ll work, $N! My turn now - I will imbue these with a suitable temper that will allow them to survive the intense forging process they will eventually go through.$b$bThe next step will be to get an appropriate mold for the key. I know a goblin blacksmith in Tanaris that has in the past made molds for similarly macabre items. He works for whom goblins usually work for - the highest bidder.',12340),
	 (965,6,0,0,0,0,0,0,0,'Elissa sent you? Then it is good tidings you bring. I have troubling news to report to her, and had no means with which to deliver it.',12340),
	 (966,2,1,5,0,0,0,0,0,'Many thanks, $n. This should shed some light on this warlocks'' gathering...$b$bHmm... the Cult of the Dark Strand... I have never heard of this group before. Having no knowledge of their history, it is all but impossible to say what their plans must be.$b$bThere is no more time to delay. Warning must be delivered to Delgren immediately.',12340),
	 (967,1,0,0,0,0,0,0,0,'If you don''t mind my saying, you seem a bit well-equipped for a messenger, hm? I suppose Balthule wanted to be certain that his letter reached my hands. Let''s see what he has to say...$B$BThis is disturbing news. When undead or demonic forces are found, I help the Sentinels destroy them.$B$BAt first I was unaccustomed to the manners of the night elves, but I have grown to respect them greatly as allies.',12340),
	 (968,1,1,6,0,0,0,0,0,'Ah, a copy of The Powers Below. An interesting text, this is. And some might find it useful...$B$BBut this one''s in sad shape. And look here! There are notes in the margin of almost every page!$B$BHm...I know this copy. I sold it to Bolgar last year. Are you...a friend of his? Yes, I thought you were. You have that same fire behind your eyes!$B$BWell, by definition, a friend of Bolgar''s is a friend of mine. And we take care of our own, yes?',12340),
	 (969,5,0,0,0,0,0,0,0,'Ahh, yes... I will make da charm for ya now. Just you wait!',12340),
	 (970,0,0,0,0,0,0,0,0,'Hmm, some dark magic enchants this soulstone. Let''s see what''s trapped inside, shall we?',12340),
	 (971,4,1,0,0,0,0,0,0,'You found the manuscript! What a joyous day this is! Copies will be made and distributed, and the ancient knowledge of Lorgalis will finally be known to my brothers and sisters!$B$BYour service to us is more than you know, $N. But I hope that this gift shows you the gratitude we extend to our allies.',12340),
	 (972,0,0,0,0,0,0,0,0,'Take the water sapta and find the corrupted pool of water in Silverpine, $N. I have great faith in your abilities.',12340),
	 (973,4,0,0,0,0,0,0,0,'It was a grand thing you did today, $n. You should be quite proud of yourself for having faced down a warlock of such power.$b$bNow, let''s see what we can learn from Ilkrud''s writings.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (974,4,0,0,0,0,0,0,0,'Yes, I definitely see the correlation here between the temperature of the volcano and the hot springs. I''ll have to double-check my equations for accuracy, but it seems like the distance and the rate that the heat is transferred... Hmm...',12340),
	 (975,6,0,0,0,0,0,0,0,'Here it is, $N. Remember, ya have ta carry it with you. Why don''t ya head back to Winterspring, an'' see what ya be findin'' there?',12340),
	 (976,1,2,0,0,0,0,0,0,'You have done well today, $C. The items we sent to aid Auberdine will be of immediate use in dealing with the dark threats that infest the forest.$B$BTake these with my heartfelt thanks.',12340),
	 (977,1,0,0,0,0,0,0,0,'I can''t wait to show my friends! Now, just wait a moment while I attach these...$b$bPerfect!',12340),
	 (978,1,0,0,0,0,0,0,0,'Now I can compare the feathers... Let''s see...',12340),
	 (979,3,0,0,0,0,0,0,0,'Hi! Erelas sent you? Great, I was just preparing to travel up to the caves now, and I wouldn''t mind company.',12340),
	 (980,1,0,0,0,0,0,0,0,'Hi there, $N. Yes, what Krakle told you is true...',12340),
	 (981,273,1,2,0,0,0,0,0,'I knew you would be up to the task, $N.$B$BI sense great deeds before you, and that you will right many of the wrongs that plague our lands. Bear my blessings, $N, as well as this gift.',12340),
	 (982,4,0,0,0,0,0,0,0,'You''ve done us here in Auberdine a great service, lad. We''ll make sure that their effects are properly taken care of.$b$bAs for you, please have this. It is the least I can do for someone with the bravery to set things right.',12340),
	 (983,0,0,0,0,0,0,0,0,'As you place the Crawler Legs inside the machine, you hear gears begin to grind. Judging from the banging sounds coming from the Buzzbox, you believe the Crawler Legs are being put in their proper place. Soon the machine begins to hum, and you hear a tiny voice calling out from within.$b$b"Hello? Uhh... Hello! You fixed it! This is Wizbang by the way! Thanks a lot... Hey, you wouldn''t want to fix another one, would ya?"',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (984,18,0,0,0,0,0,0,0,'This is terrible news indeed, $N.$B$BWith the furbolgs this close to Auberdine, we will have to prepare ourselves for the inevitable.$B$BThank you, $N.',12340),
	 (985,2,0,0,0,0,0,0,0,'Wash the blood from your garments, $N, and do not mourn what you had to do. Instead, give thanks. You have lessened the threat to our people here in Auberdine, even if Darkshore is still in jeopardy from the effects of fel moss.',12340),
	 (986,0,0,0,0,0,0,0,0,'These will do nicely, $N. I shall set to work on the cloak immediately.$B$BGive me a few moments, then return to me.$B$BOh, one more thing: after you''ve used the enchantment on the cloak you''ll be limited in your interactions with others. If you can help it, do no more than speak to others. Much more than that could dispel the illusion.',12340),
	 (990,1,0,0,0,0,0,0,0,'Ah, a $C from Darkshore. Selarin has done well to send you here so quickly, $N. I wish your trip here wasn''t under such dire stress. Perhaps with your help we can improve matters.$B$BI would start my visit by speaking to the other citizens of Astranaar. Some could surely use your aid.',12340),
	 (991,0,0,0,0,0,0,0,0,'Teronis'' body lies broken atop the island. For some unknown reason, the murlocs have left it alone.$B$BThe deep slashes across his corpse obviously came from the weapons and claws of the murlocs.',12340),
	 (992,5,0,0,0,0,0,0,0,'What''s this?  You were ambushed by some sort of bad mojo creepy-crawly?  Oh, this does not bode well for the Gadgetzan Water Company, no indeed...$B$BI guess I should have told you about the reports coming in on some crazy bug-creatures that appear to be sucking up all the water in the desert.  At first, I thought it was just a crock.  We have enough trouble with the nomads as is; I thought it was just more of their shenanigans.  Well, now we know at least!',12340),
	 (993,0,0,0,0,0,0,0,0,'Wonderful! Terenthis found someone to help me.$b$bAnd look. a moonstalker cloak...<cough> Oh... that hurts. Thank you, $N.$b$bThe furbolgs wounded me before I managed to evade them. Give me a moment, and I should be fine to talk some more.',12340),
	 (994,2,0,0,0,0,0,0,0,'$N! I''m pleased to see you''ve returned successfully. Your assistance to Volcor has given me faith that we can overcome the challenges facing us here in Darkshore and beyond.',12340),
	 (995,2,0,0,0,0,0,0,0,'$N! I''m pleased to see you''ve returned successfully. Your assistance to Volcor has given me faith that we can overcome the challenges facing us here in Darkshore and beyond.',12340),
	 (996,0,0,0,0,0,0,0,0,'You apply two Cenarion plant salves to the windblossom. It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (997,1,0,0,0,0,0,0,0,'Ah, it''s here! I have waited for this rare earth for quite some time. I hope it''s still fresh...$b$bThank you for bringing it to me, $N. You are a $R who is generous with $Ghis:her; time.',12340),
	 (998,0,0,0,0,0,0,0,0,'You apply two Cenarion plant salves to the windblossom. It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant.',12340),
	 (1000,2,1,0,0,0,0,0,0,'Greetings, $C.$b$bI am pleased to see the likes of you taking an interest in the well being of nature; tales of your mighty deeds precede you, and you are welcomed here. Seeing you before me instills the feeling of confidence that the Cenarion Circle will get the proper aid it needs.$b$bOur connection with the Cenarion Circle in Moonglade transcends racial and political divides. Remember this as you work on behalf of the Circle, and you will do well.',12340),
	 (1001,0,0,0,0,0,0,0,0,'The Buzzbox hums to life soon after you place the Thresher Eyes inside. There is a moment of static before you hear a familiar tiny voice call out.$B$B"Crawler wine is the best..." *hic*$B$B"What? Oh, you fixed it already? Wow, you''re a fasht one. Sho, would ya like to fix another?"$B$BYou believe you hear a liquid being poured into a cup, followed by loud gulping sounds.',12340),
	 (1002,0,0,0,0,0,0,0,0,'The Buzzbox suddenly leaps into action, and you can hear the distinct sounds of teeth being ground to dust coming from within.$b$b"Sho, ya made it! Thatsh exshellent newsh... Sho... Why doncha move along? Oh! Unless you want another job!"',12340),
	 (1003,0,0,0,0,0,0,0,0,'"Sho yash gotsh the scalps in? That''sh sho great... Wha? Well, yesh I shuppose ya have realized that I can speaksh to ya without the materials in the machine. But I was telling the truth when I shaid they were broken!$b$bSee, in addition to being communimacation toolsh, the Buzzboxes also brew and distill fine liquor. Shorry for any deceptshion, but the nightelves do not apprecimerate my liquor trade in their townsh. I put shomething special in thish box to show my gratitude for yer effortsh. Enjoy!"',12340),
	 (1004,2,1,0,0,0,0,0,0,'Greetings, $c.$b$bI am pleased to see the likes of you taking an interest in the well being of nature; tales of your mighty deeds precede you, and you are welcomed here. Seeing you before me instills the feeling of confidence that the Cenarion Circle will get the proper aid it needs.$b$bOur connection with the Cenarion Circle in Moonglade transcends racial and political divides. Remember this as you work on behalf of the Circle, and you will do well.',12340),
	 (1007,0,0,0,0,0,0,0,0,'You found it! Thank you, $N!$B$BThe old city of Zoram holds many secrets, and this statuette may be the key to many of them.',12340),
	 (1008,1,66,0,0,0,0,0,0,'Very well done, $N.  Your actions in the Zoram Strand against the naga are commendable.$B$BI know your feat was not easily accomplished, for the strength and guile of the naga is well known to the night elves.  We know this, for we share a history with them.$B$BIt is a history I care not to repeat.',12340),
	 (1009,0,0,0,0,0,0,0,0,'You found the ring! Thank you, $N. Please take this as payment, and know that your deeds today will remain forever in my memory.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (1010,2,1,0,0,0,0,0,0,'Ah, you have the hair!  Now I will mix a cure for the child, and pray my concoction works.$B$BAnd... Forsaken are at Bathran''s Haunt?  Very troubling to hear, that is.  Very troubling indeed...',12340),
	 (1011,0,0,0,0,0,0,0,0,'Very good, $N. Now... by testing the contents of this bottle, the goals of the Forsaken will be revealed!',12340),
	 (1012,1,0,0,0,0,0,0,0,'I felt the anguish of the Dor''danil Barrows lessen, and knew you had completed your task.$B$BIt was grim work you did, $N, for the spirits you destroyed were merely victims of the Forsaken''s evil. But with their destruction, let us hope the other maddened spirits find peace.',12340),
	 (1013,0,0,0,0,0,0,0,0,'Very good. This book will add nicely to my collections of the workings of Ur. His knowledge was great, but his conscience held him from true power. And so when the Scourge came and his strength was tested, it failed.$B$BWe of the Forsaken cannot afford such weakness, if we are to survive...',12340),
	 (1014,4,0,0,0,0,0,0,0,'Silverpine Forest is finally free from the vice of that wretch Arugal. You have done the Dark Lady a great service, $N. Your tenacity shall be rewarded.',12340),
	 (1015,6,1,0,0,0,0,0,0,'What makes you think I wish to be pestered by the likes of you, $C? Wait - let me stop the important duties I attend to on a daily basis so I can help you locate a doodad somewhere. By all means, the welfare of Darnassus - nay, all of Teldrassil - should come second to the acquisition of a bauble for your collection.$B$BThe fools in Moonglade waste my time with their call for assistance, and now I must endure this?',12340),
	 (1016,1,6,0,0,0,0,0,0,'Well done, $N, this should give us the information we need to have the culprit discovered. How would you feel about taking out the mage who fills our pools with corrupt elementals? The corruption of Ashenvale and beyond makes my stomach turn on its own--to have a wizard actively attempting to destroy it further sickens me to no end. We shall make him pay.',12340),
	 (1017,11,1,0,0,0,0,0,0,'Now I can see that repugnant smile wiped from his face forever. You have done very well, $N. Take this, the Light of Elune, drink of it when all seems lost and death is near. It may save you, Goddess willing.',12340),
	 (1018,2,1,0,0,0,0,0,0,'Greetings, $c.$b$bI am pleased to see the likes of you taking an interest in the well being of nature; tales of your mighty deeds precede you, and you are welcomed here. Seeing you before me instills the feeling of confidence that the Cenarion Circle will get the proper aid it needs.$b$bOur connection with the Cenarion Circle in Moonglade transcends racial and political divides. Remember this as you work on behalf of the Circle, and you will do well.',12340),
	 (1019,6,1,0,0,0,0,0,0,'What makes you think I wish to be pestered by the likes of you, $c? Wait - let me stop the important duties I attend to on a daily basis so I can help you locate a doodad somewhere. By all means, the welfare of Darnassus - nay, all of Teldrassil - should come second to the acquisition of a bauble for your collection.$b$bThe fools in Moonglade waste my time with their call for assistance, and now I must endure this?',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (1020,6,2,0,0,0,0,0,0,'This is from Orendil?$B$BHis skill with herbs and healing is great.  This cure gives me hope, when before I had little...',12340),
	 (1021,0,0,0,0,0,0,0,0,'Judging by the gaping wound in her side, Anilia is on the verge of death.',12340),
	 (1022,6,0,0,0,0,0,0,0,'The Tome of Mel''Thandris works in strange ways. The events it records, the events it shows... No one truly understands why it does what it does.$B$BNonetheless, it is clear that what Priestess Starsong received--this Scythe of Elune--bears further investigation.',12340),
	 (1023,5,1,1,0,0,0,0,0,'This is terrible, $N. Teronis is dead?!$B$BThe time for mourning will come, but for now we must focus our efforts. I shall send some of the Sentinels to recover Teronis'' body as soon as possible.$B$BYou have Teronis'' journal and the gem he was seeking. Do you think you''re capable of completing his task? I would rest much better knowing his death was not in vain.',12340),
	 (1024,0,0,0,0,0,0,0,0,'Oh, Raene sent you? It must be serious indeed. What can I help you with?',12340),
	 (1025,2,0,0,0,0,0,0,0,'You have done well, $N. Thank you.',12340),
	 (1026,0,0,0,0,0,0,0,0,'I''m pleased to see you''re back, $N.',12340),
	 (1027,0,0,0,0,0,0,0,0,'You found the final piece? Wonderful for you... and for Raene.$B$BI guess we''ll have to see about repairing it, won''t we?',12340),
	 (1028,0,0,0,0,0,0,0,0,'After the glow dies, you can see the re-enchanted rod within the shrine''s basin.',12340),
	 (1029,6,1,0,0,0,0,0,0,'You''ve recreated the rod Teronis had set out to find? That''s wonderful to hear.$B$BTeronis would be proud to see his quest is continuing even after his tragic passing.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (1030,0,0,0,0,0,0,0,0,'Yes, yes... you are one of my kind, but still whole. Still clean.$B$BI am unsure how you have escaped the atrocities the night elves have visited upon our people, but I am glad to know that I am no longer alone.$B$BCorruption now runs through the veins of our kin, young one, corruption brought down upon us by the prideful night elves. They are the ones who did this to our people... They are the ones I blame for being cast out of my tribe.$B$BAt night I can still see the campfires burning in the darkness.',12340),
	 (1031,0,0,0,0,0,0,0,0,'Anilia died? No... that can''t be! It was just yesterday that we were running and playing together in the woods.$B$BI guess those days are over...',12340),
	 (1032,0,0,0,0,0,0,0,0,'Thank you, kind $R. My sister''s spirit is gladdened by your efforts.',12340),
	 (1033,5,2,0,0,0,0,0,0,'Oh, you found it! I will place the tear in a stew, and pray that it will cure her.$B$BThank you! Thank you, $N!',12340),
	 (1034,5,2,0,0,0,0,0,0,'You gathered the dust! I will create a poultice from these -- it should bring down Relara''s fever.$B$BThank you again, $N. Without your help, my child would surely perish.',12340),
	 (1035,4,2,0,0,0,0,0,0,'Oh, $N, you have saved my daughter! I know the power of the moonstone will give back my daughter her strength!$B$BI can never repay you fully for the aid you have given me, but... please, take this. Other than Relara, it is my most dear possession.',12340),
	 (1036,0,0,0,0,0,0,0,0,'Avast ye, scallywag. I hears that ye be the type for a bit o'' the skullduggery. Well, if yer no friend of Booty Bay, then ye might have a special place with the Bloodsail Buccaneers.$B$BArrrrr...',12340),
	 (1037,0,0,0,0,0,0,0,0,'Velinde Starsong? That the priestess disappeared some time ago is almost certainly common knowledge. As to further details about the events that surrounded her departure... it would take good reason for me to divulge such information.',12340),
	 (1038,1,0,0,0,0,0,0,0,'It seems that Velinde''s disappearance is more troubling than it originally appeared. Even still, I cannot believe that she has come to a bad end. Perhaps it would be beneficial for us to make contact with her.$B$B$N, since you have shown a vested interest in this matter, I would like to enlist your aid.',12340),
	 (1039,6,0,0,0,0,0,0,0,'$R, eh? Must admit, we don''t get much of your type out here. Looking for someone, eh? Just give me a moment, I''m sure I have it written in one of my ledgers.$B$BLot of people travel through here, though, so just give me a moment.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (1040,0,0,0,0,0,0,0,0,'Yes? Now, it doesn''t look to me like you''re the sort with goods that need shipping, so either you''re looking for a job with my caravan--and there''s no jobs to be had now--or you''re probably talking to the wrong goblin.$B$BSo which one is it?',12340),
	 (1041,1,0,0,0,0,0,0,0,'With all the strange happenings of the last few years, I keep as good records of strangers as I can. Never know when it might come in handy... though it''s usually not pleasant business when it does. Not to suggest anything about this Velinde you''re looking for.',12340),
	 (1042,1,0,0,0,0,0,0,0,'Dark times these are. Ill news is whispered from every swaying branch, and evil can be found under every rock.$B$BAnd in such times an unknown stranger enters my home and asks of worgen... I''ll ask no forgiveness for my suspicions, only answers.$B$BAnd answers, I will have.',12340),
	 (1043,1,0,0,0,0,0,0,0,'It is an interesting story you tell, $N. Though the Carevin family''s influence is not large enough that we might find the root of these troubles and finish them once and for all, we will do what we can to contain the worgens'' numbers in Duskwood.$B$BAlready I have instructed Calor to make this his first priority.',12340),
	 (1044,6,1,2,0,0,0,0,0,'So this is the fate of Velinde, is it? The high priestess will be disappointed to hear of this, they were good friends before her disappearance. Still, the Scythe of Elune was surely granted to her as a boon by our goddess, and it is unsettling to me that it has fallen out of her servants'' hands.$B$BAnother matter for another time, however. I owe you my thanks in no small amount for what you have accomplished.',12340),
	 (1045,1,0,0,0,0,0,0,0,'You have done well, my friend.$B$BThe forest is still tainted, but at least we know we have done a small part to return it to its former glory. If you wish to return to me again, I would enjoy the company of my own kind.$B$BBe well. Perhaps our tribes will meet again under less violent times.',12340),
	 (1046,6,1,2,1,0,0,0,0,'So, this is the skull of the fiercest furbolg threat in Ashenvale?$B$BI am more than pleased with your abilities, $N. The Sentinels cannot thank you enough. I hope we can rely on you again in the future to help our people.$B$BI shall put this skull and Dartol''s Rod in a place of reverence for others to see.$B$BTeronis would be proud. Thank you again.',12340),
	 (1047,6,1,0,0,0,0,0,0,'What makes you think I wish to be pestered by the likes of you, $c? Wait - let me stop the important duties I attend to on a daily basis so I can help you locate a doodad somewhere. By all means, the welfare of Darnassus - nay, all of Teldrassil - should come second to the acquisition of a bauble for your collection.$b$bThe fools in Moonglade waste my time with their call for assistance, and now I must endure this?',12340),
	 (1048,0,0,0,0,0,0,0,0,'You have served the Dark Lady well, $c. ''Twas no small task I asked of you.$b$bYour loyalty to the Forsaken has been noted. And your tenacity in combat will be remembered.',12340),
	 (1049,5,2,0,0,0,0,0,0,'The Compendium of the Fallen! I was beginning to wonder if the very book existed!$b$bYou have served the Tauren of Thunder Bluff well, $N. Your dedication shall not be forgotten.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (1050,4,1,2,0,0,0,0,0,'You have rescued the sacred text!$b$bYour journey was long and acquiring the book was undoubtedly no easy task. But  the dwarves of Ironforge stand to benefit from your success.$b$bThank you, $n, on behalf of the Explorers'' League.',12340),
	 (1051,0,0,0,0,0,0,0,0,'Vorrel led such a troubled existence. And what a good mate he was...$b$bDamn those filthy humans!$b$bVorrel is gone, never to enjoy undeath again. At least I can take solace in the revenge you took in his name. For that I thank you.$b$bNow let me be to mourn....',12340),
	 (1052,6,0,0,0,0,0,0,0,'Brother Anton still spreads the word of the Scarlet Crusade? Oh my....',12340),
	 (1053,1,1,66,0,0,0,0,0,'While disciples of the Light never revel in the loss of life, we must accept that on occasion, such sacrifices must happen for the greater good of the Kingdom and the planet.$B$BThrough your deeds in the Monastery you have spared many innocent lives, $N. I salute your tenacity.',12340),
	 (1054,2,0,0,0,0,0,0,0,'Well done, $N.$B$BWe are under constant threat from the furbolg. Hopefully this will keep them at bay for a bit longer.',12340),
	 (1055,0,0,0,0,0,0,0,0,'You''ve done it, $N! Well done!',12340),
	 (1056,0,0,0,0,0,0,0,0,'Alas, you arrive. I see Faldreas has listened to the forest spirits...',12340),
	 (1057,0,0,0,0,0,0,0,0,'Now that the Bloodfuries have suffered such a great loss, perhaps the true work of restoring the land can begin....',12340),
	 (1058,0,0,0,0,0,0,0,0,'Oh how happy these little woodland nymphs shall be! We''ll make them feel right at home with this special concoction!',12340),
	 (1059,1,0,0,0,0,0,0,0,'Keeper Albagorm was wise to send you with such urgency.$B$BLet us see if we cannot call forth aid from the great forest to travel to the Charred Vale before it is too late.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (1060,0,0,0,0,0,0,0,0,'Ahh, a letter from Darsok. I have not heard from him in many years.$b$bSo the last of the Bloodfeathers are dead, eh? That is good news, I can remember when my friend Rokhan went with that crazy mok''nathal to kill her older sister. Ah, to be young again, like you.',12340),
	 (1061,1,0,0,0,0,0,0,0,'Ah, a $C. Very good. We will need your skills to deal with these plunderers!',12340),
	 (1062,1,0,0,0,0,0,0,0,'Bravely done, $N.$b$bWe may ultimately need the wisdom of tauren elders to calm the spirits of Stonetalon, but...$b$bRidding the Venture Company of its personnel is a good first move against them.',12340),
	 (1063,2,0,0,0,0,0,0,0,'I bid you greetings. You are here seeking council?',12340),
	 (1064,1,0,0,0,0,0,0,0,'Magatha sent word of your coming, $N. Although my heart beats no longer, I still feel sorrow for the spirits of Stonetalon.$b$bThe Forsaken are eager to offer what help we can.',12340),
	 (1065,6,5,0,0,0,0,0,0,'A note from Zamah? Her needs must be great to send word from so far. Let us see what she says...$b$bAh, splendid! I know exactly what to do!',12340),
	 (1066,273,1,0,0,0,0,0,0,'Very good!  I trust the Syndicate gave you little trouble?$B$BAs I mentioned, the blood of innocents is not an easy thing to obtain.  We are lucky the Syndicate shadow mages did the difficult work for us.$B$BNow hold a moment while I create my concoction...',12340),
	 (1067,1,0,0,0,0,0,0,0,'A toxin from Apothecary Lydon? Very good. If I know Lydon, then this toxin will be quite effective against the Venture Company...',12340),
	 (1068,1,2,0,0,0,0,0,0,'The destruction of the machines XT:4 and XT:9 have soothed many of the spirits of Stonetalon, $N. With their loss, let us hope the Venture Company will remove itself from these mountains.$b$bFor if they do not, then I fear the atrocities this place has suffered will pale to what lies ahead.',12340),
	 (1069,2,0,0,0,0,0,0,0,'You got them! Thank you!$B$BI''ll have these sent to Dizzywig and get them shipped to Booty Bay. I can already taste the profits!$B$BHere is your cut, $N. I couldn''t have made this deal without you.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (1070,1,2,0,0,0,0,0,0,'Ah, you''ve come from Ashenvale at the behest of Thenysil -- how I miss her, my homeland and friends. She must be doing well with the Sentinels to be sequestering adventurers for other tasks. I''m proud of her.$B$BIt is a pleasure to meet you, $N.',12340),
	 (1071,2,1,0,0,0,0,0,0,'Thanks so much for your help, $N. You''re actually back just in time.$B$BI think I''ve got the perfect plan. Explosives. No, that''s not the plan, but it''s part of the plan.$B$BSee, I''ve been using high explosives--don''t worry, they''re not as dangerous as everyone thinks--to scare the goblins back a bit. I can herd ''em pretty good with a few key detonations along the mountains'' edges, but I''ve been low on supplies now for a few days.',12340),
	 (1072,6,0,0,0,0,0,0,0,'Ahhh. Gaxim sent you, huh? How do I know you''re not lying to me?! Hmm? Hmm?',12340),
	 (1073,273,1,0,0,0,0,0,0,'This''ll do nicely.$B$BIf I didn''t know better, stranger, I''d say you knew somethin'' about alchemy. Good, good... the world''s not all about swords and sorcery, you know?',12340),
	 (1074,21,0,0,0,0,0,0,0,'Your task has been done flawlessly, $N.$B$BNG-5 is the unequivocal component in the recipe to ignite the wagons of dynamite.$B$BWhat? Yes, dynamite... wagons of it. It''s the perfect distraction, I tell you... just wait and see.',12340),
	 (1075,0,0,0,0,0,0,0,0,'Now, this spell you need; one that will allow you detonate explosives from a distance... hmmm.',12340),
	 (1076,0,0,0,0,0,0,0,0,'Allow me just a few moments and I shall have your scroll ready for you.',12340),
	 (1077,21,0,0,0,0,0,0,0,'This is perfect, $N! Well done.$B$BThis spell, mixed with the NG-5, shall make the perfect remote explosive.$B$BWe''ll be able to create the perfect distraction for you so you can sneak in and steal the Venture Co.''s letters and engineering plans.$B$BThat will surely slow down their deforestation acts.',12340),
	 (1078,4,0,0,0,0,0,0,0,'This is perfect, $N. Thank you greatly.$B$BPerhaps one day in the future I''ll be able to help you as you have helped me.',12340),
	 (1079,4,0,0,0,0,0,0,0,'Truly amazing! This is a huge blow to the Venture Co.$B$BWe''ll be able to find weaknesses in their machines and also incorporate their designs into our own creations. This is a wonderful day, indeed.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (1080,4,0,0,0,0,0,0,0,'Incredible, $N! Kaela and the Sentinels will be so happy. With your skill and my creations, we''re unstoppable.',12340),
	 (1081,1,0,0,0,0,0,0,0,'Hello, $N. I have indeed heard your name before, and although you are still full of youth, I am pleased to see the path you have set for yourself.$B$BYou would do me a great honor if you would accept this as a gift of appreciation.',12340),
	 (1082,2,0,0,0,0,0,0,0,'Thank you, $N. You have done a service to the Sentinels.$B$BI''m glad to see Kaela... and even Gaxim, are doing well.$B$BYou''ve earned our appreciation.',12340),
	 (1083,2,0,0,0,0,0,0,0,'The remains of our enemy... your strength serves us well, $N. Thank you.',12340),
	 (1084,2,0,0,0,0,0,0,0,'Thank you, $N.$B$BThis should be more than sufficient for Gaxim to figure out how the treants were corrupted. I shall give this to him right away.',12340),
	 (1085,1,0,0,0,0,0,0,0,'Treacherous...treacherous and dangerous, that''s what this land is.$B$BBut I''m here to show the night elves that it''s a little safer with the help of good ole engineering and a dash of magic.$B$BSee, swearing off magic completely won''t help the night elves -- they need it. The world needs it. And with engineering and alchemy to boot, you can''t go wrong. The possibilities are endless.',12340),
	 (1086,21,1,1,0,0,0,0,0,'You found the port? Well done, $N! I am sure the goblins were quite surprised from your delivery! Let us hope that toxin finds its way to their headquarters.$B$BYou have served your people well, and I advise you to ignore any guilt you might harbor for poisoning the Venture Company. They are deserving of far worse.$B$BAnd if there is one mote of wisdom the Forsaken might teach its allies, it is this:$B$BDo not shy from dark paths... if those paths lead to victory.',12340),
	 (1087,0,0,0,0,0,0,0,0,'Already I can feel it... yes... power so sweet... the rushing flood. The kaldorei are foolish to spurn the gifts of this world, to reject the coursing of magic as it flows singing through your veins.$b$bWhat a pale mockery life is without its burning embrace!',12340),
	 (1088,0,0,0,0,0,0,0,0,'I knew Ordanus once, long ago. He had the arrogance of his kind, holding himself above even the Highborne.$b$bHis head does not rise so high now, does it, $N?$b$bI promised you a reward, and you shall have it. Attend to me.',12340),
	 (1089,0,0,0,0,0,0,0,0,'As the three keys are slid into their matching openings, in the middle of the glowing light a number of items appear.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (1090,2,0,0,0,0,0,0,0,'Thanks, $N. It was looking a little dicey there for a second and we''ve probably drawn far too much attention to ourselves.$b$bThe important part is that we have the ore sample, though, and we should get it to Ziz as soon as possible.',12340),
	 (1091,1,2,0,0,0,0,0,0,'This is interesting indeed.$B$BYou and Gaxim have done very well, $N. Thank you.',12340),
	 (1092,1,0,0,0,0,0,0,0,'Ahhh, I knew that I did the right thing by telling Piznik to stay behind. I''m sure the engineers in Undermine will be most interested to look at this...$b$bOf course I''ll want to keep a little piece for myself, but what they don''t know won''t hurt them, yes?',12340),
	 (1093,0,0,0,0,0,0,0,0,'Hey, is that what I think it is? Great!$b$bNow, let''s see. Ugh... how am I supposed to understand this stuff... can''t figure out the way gnomes think. Lemme tell you, I''m surprised they could build the wheel, let alone those flying machines they like so much.',12340),
	 (1094,0,0,0,0,0,0,0,0,'Fizziks, eh? Can''t say I trust him, but this information seems good enough. What I wouldn''t give to have the Venture Company out of my hair.$b$bThey do come up with some good machines though... I can''t deny that we''ve benefited from using some of the improvements they''ve devised.',12340),
	 (1095,1,0,0,0,0,0,0,0,'Eliminate Gerenzo? Now there is a prospect that I have no objections to.$b$bGnomes are bad enough as it is, but what I learned about Gerenzo only makes it worse. Apparently, he was one of the head engineers in Gnomeregan, where he was working on their secret project--we could never infiltrate Dun Morogh well enough to find out specific details. It was a failure. Our reports say that whatever it was literally exploded in their faces.',12340),
	 (1096,1,0,0,0,0,0,0,0,'Look at that thing... it''d take a gnome to come up with something like that. I can''t understand why you''d cut off an arm, and replace it with that, when you could just keep both arms and add a third!$b$bGnomes, I tell you...$b$bAt least Gerenzo''s out of commission. Hopefully that''ll be enough proof, and Sputtervalve will assign me to one of the Tinkers'' Union workshops in Gadgetzan or maybe even Undermine.',12340),
	 (1097,6,0,0,0,0,0,0,0,'You''re here to help with my delivery? Very good!',12340),
	 (1098,0,0,0,0,0,0,0,0,'Vincent''s body lies broken, and still.$b$bAlthough Deathstalker Adamant will send his report to Hadrec... whatever additional details Vincent gained must remain with him.$b$bBut clutched in his hand is a small trinket...',12340),
	 (1100,6,0,0,0,0,0,0,0,'You say you found this journal on a deceased dwarf? Give me but a moment to peruse the pages...',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (1101,1,1,1,0,0,0,0,0,'The crone has been laid to rest. This is fantastic news, $N.$B$BIn these times of peril, it is refreshing to see one as brave as yourself.$B$BWith Razorflank''s minions taken care of, our studies in the area can continue. Perhaps now we can gain further knowledge of exactly what happened to corrupt the resting place of Agamaggan.$B$BHowever, I fear the answer to that question lies in treachery as well...',12340),
	 (1102,1,1,0,0,0,0,0,0,'I see the nasty tribe of Razorfen Kraul now knows the pain of my people. Serves the foul beasts right.$b$bTo drive one from a holy land is a sin worthy of the most severe revenge.$b$bThank you, $N, for aiding me in my plight.',12340),
	 (1103,0,0,0,0,0,0,0,0,'Ahhh, den yur ready...$B$BI''ll put me items in the brazier den, and you c''n talk wit'' da spirit too.$B$BAn'' dontchu worry none ''bout seein'' into da spirit world wit'' da sapta... ol'' Tiev know a trick or two ''bout how da sapta magic works.$B$BCome now, head down wit'' me to the shrine and let''s speak to da spirits together, brotha.',12340),
	 (1104,4,0,0,0,0,0,0,0,'All right! This venom is going to work great! Thanks, $N!$b$bNow I just need to boil it down, apply skipper-otomer, add a nega-catalyst, and... Drat! Where are my notes!?',12340),
	 (1105,2,5,11,0,0,0,0,0,'You got them! Thanks, $N!$B$BWow, these shells are harder than I thought! When I work with them I''ll probably need a whole box full of tools!',12340),
	 (1106,1,0,0,0,0,0,0,0,'Fizzle sent you? Well that changes things! Of course I''ll help you. Fizzle and his brother are two of the few people who don''t want me dead!$b$bSo Fizzle wants to make pistons, eh? Pistons strong enough to take whatever stresses he has planned, and if I know Fizzle, then this new car of his is a volcano on wheels!',12340),
	 (1107,2,1,0,0,0,0,0,0,'Thank you, $N! After I grind these down and fuse them with a few other ingredients, the composite will be ready. And after that, the car will be safe from its own speed.$b$bSafe, as long as it doesn''t hit anything...',12340),
	 (1108,1,0,0,0,0,0,0,0,'Ah yes, these will do fine. Now let''s put them in some heat and see how they fare...',12340),
	 (1109,0,0,0,0,0,0,0,0,'Splendid! This is just the start we needed, $N.',12340),
	 (1110,1,0,0,0,0,0,0,0,'Whoa, look at all that! There''s some good stuff in that heap of junk. I''m sure I can pawn it off for a hefty sum.$b$bAnd... is that an ear I see squashed between those two sheets of metal?? Ouch! Heh, I sure wouldn''t want to be that pilot!$b$bThanks, $N. Here''s your pay. And here''s some advice, free of charge...$b$bIf you look hard enough, you can always find profit in someone else''s tragedy.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (1111,0,0,0,0,0,0,0,0,'Oh yes. Parts for Kravel. I''m glad you''re here. These things have been sitting out here for days, and I was afraid they''d rust!',12340),
	 (1112,4,0,0,0,0,0,0,0,'Great, you got them! Now we need to get them to the gnomes. But first...$b$bLet''s take out one small item...',12340),
	 (1113,0,0,0,0,0,0,0,0,'My what an abundance of gore you have brought me, $N! Your efforts have been most excellent!',12340),
	 (1114,4,0,0,0,0,0,0,0,'There they are! My hydro ratchets and repeater bolts! These will do just fine. Thank you!',12340),
	 (1115,0,0,0,0,0,0,0,0,'You want to know about Nazz Steamboil? He''s a racer pilot out in the Shimmering Flats, isn''t he?$b$bYeah, I might be able to find something out about him... but it won''t be easy. Or fast.$b$bOr cheap.',12340),
	 (1116,0,0,0,0,0,0,0,0,'Well, look at that. You found the dream dust!$b$bAnd how did you like the swamp, $N? It''s not easy to get a hot meal there, is it?',12340),
	 (1117,0,0,0,0,0,0,0,0,'Well well! This is interesting... very interesting. Heh, perhaps I should bow to the goblin pilot the next time I see him.$b$bThis is worth plenty, $N. I''m sure Nazz will pay a small fortune to keep his secret... a secret.',12340),
	 (1118,0,0,0,0,0,0,0,0,'I see. Kravel has a big scheme planned. He has a sinister mind -- I like that about him.$b$bSo you''ll need something to addle wits, eh? Something powerful...$b$bI wonder if the mixture Zanzil feeds his zombies could be used...',12340),
	 (1119,4,0,0,0,0,0,0,0,'Wonderful! Fizzlebub came through! I''ll remember that next time I see him.$b$bAnd thank you, $N. You''re doing a great job, and we both stand to make a lot of money from this...',12340),
	 (1120,0,0,0,0,0,0,0,0,'Stout? How considerate! Thank you!$b$bWe shouldn''t be drinking with the race coming up, but... maybe my boys could do with just a little. Besides, it can''t be that strong, can it?',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (1121,0,0,0,0,0,0,0,0,'What do we have here? Booze, eh?$B$BWell, I don''t mind if we have just a little...',12340),
	 (1122,0,0,0,0,0,0,0,0,'It says here that the fool''s stout was a success. That''s good news!$b$bIf you ever want more of the stuff, then let me know and I''ll have you gather more of Zanzil''s Mixture.',12340),
	 (1123,2,1,1,0,0,0,0,0,'I am Rabine Saturna, and on behalf of Keeper Remulos and all of the denizens of this sacred glade I bid you welcome.$B$BI appreciate your interest and eagerness to assist the Cenarion Circle. The tauren have shown an incredible propensity to the tenets of Cenarius, and by their proxy the Horde is welcomed within the safety of this glade. The preservation of Azeroth is a common goal we both share.$B$BYou are among friends here, $N.',12340),
	 (1124,6,1,1,0,0,0,0,0,'Rabine sent you, did he? Well, consider yourself welcomed here... as much as this desolate and forsaken land can welcome someone.$b$bI wasn''t alive during the time of the great tribulations that took place here, but there are parts of this desert that might as well be eerie pictures of that forgotten past. With your help, the Cenarion Circle might be able to bring finality to a threat that was supposed to have died generations ago.',12340),
	 (1125,1,1,2,0,0,0,0,0,'I had thought that maybe the huge swirling hive near the ruins of the village had played a part in its demise. It would seem that your work has proven this to be correct; the proximity of the hive poses a threat to any future work we may do here.$b$bI thank you for your benevolence in freeing the souls of the fallen; such work is never easy, I know. When you''re ready, however, I''d like to ask for your assistance once more...',12340),
	 (1126,6,1,1,0,0,0,0,0,'What the... what is it?$b$bIt has the shape of a... box, maybe? It''s encrusted over something fierce. Wait, there a portion here that''s exposed... is that a book underneath all this gunk?$b$bI think you''ve stumbled across quite the find here, $N... well, at least I hope it is. Perhaps it is a journal or a log from ancient times, preserved in this shell.$b$bI think I know a way to find out what this is.',12340),
	 (1127,0,0,0,0,0,0,0,0,'Ah, very good! Here is your pay.$B$BAnd here is a little something extra... for your discretion.',12340),
	 (1130,2,0,0,0,0,0,0,0,'So, $N, you have come. Now, are you prepared to journey through distant lands?$B$BIf so, young $C, then listen on...',12340),
	 (1131,2,0,0,0,0,0,0,0,'In defeating the creature Steelsnap, you have cleansed the Thousand Needles of a horrible taint.$b$bAnd that, $N, is your lesson this day.',12340),
	 (1132,0,0,0,0,0,0,0,0,'Good day to you! You were sent by Mr. Flint in Menethil Harbor? Well Mr. Flint is a strong judge of character. If he sent you, then there''s no doubt you belong here in Kalimdor!',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (1133,0,0,0,0,0,0,0,0,'You are here to offer your services to the Alliance, $N? We welcome the aid, for although its beauty remains... Ashenvale Forest is not the peaceful place it once was.',12340),
	 (1134,2,1,0,0,0,0,0,0,'Thank you, $N. It saddens me to order the slaughter of creatures who may not willingly aid our enemies, yet it is my duty to do so.$B$BYour heart might weep for the pridewings you slew, my friend, but may your heart then swell in knowing that your allies are safe from the pridewings'' venom.',12340),
	 (1135,0,0,0,0,0,0,0,0,'Ah, most of these are nearly bursting with venom, $N. Such are normally only gathered from young wyverns, or fertile females. It must have been quite a slaughter up there in Highperch!',12340),
	 (1136,1,0,0,0,0,0,0,0,'Both strength and cunning were needed to find and defeat Frostmaw, $N. You have both.$b$bYour path has taken you to the valleys of Thousand Needles and to the high mountains of Alterac. It will one day lead you through all the Earthmother''s lands, for such is the way of the hunter.',12340),
	 (1137,5,0,0,0,0,0,0,0,'$N, you''re back! You found Martek? You spoke with him? What did he say? Can he help??$b$bTell me, tell me, tell me!!',12340),
	 (1138,273,0,0,0,0,0,0,0,'Wow, these fine crab chunks are what I need.  Thanks $N!  I found this while I was fishing a while ago, and I have no use for it.  Maybe you can do something with it.  It sure don''t make any good crab dishes.$B$BI told you all about crabs, right?',12340),
	 (1139,6,1,2,0,0,0,0,0,'<Advisor Belgrum shakes his head in disbelief as you hand him the stone shard.>$B$B$N, this is amazing. I shall have this brought to the king''s mages as soon as possible. They will want to study it to find out if the legends are true. But that is a discussion for another time: you have aided our people more than I would have ever expected--thank you.',12340),
	 (1140,1,0,0,0,0,0,0,0,'Perhaps the satyrs have been allowed to persist in the forest for too long. I will speak with Elissa about it when next I travel to Auberdine.$B$BNonetheless, with the soulgems destroyed, Athrikus'' power will be greatly diminished. We must seize on this opportunity to eliminate him and his cult.',12340),
	 (1141,4,0,0,0,0,0,0,0,'Them''s some real nice groupers, $N!  Thanks for helping me out!$B$BYou''re at least as good of a fisherman as my cousin, Graun Blump.  She also has a beard and she smells kinda funny, but that don''t do nothing to stop her fishing.  I reckon you have what it takes to use a Blump Family Fishing Pole.',12340),
	 (1142,0,0,0,0,0,0,0,0,'No!$B$B''Tis not fair. Oh, cruel and intolerable world!$B$BI must now carry this burden of grief and not let Heralath''s work die with him.$B$BYou were brave to journey from such a dangerous place, $N. But please leave me now.$B$BIn solitude I shall mourn.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (1143,4,0,0,0,0,0,0,0,'With the death of Athrikus, I hope that the demonic forces in this area will be driven back. I have no doubt that they will regroup and return, but then we shall be even more prepared to meet their threat.',12340),
	 (1144,0,0,0,0,0,0,0,0,'Thanks again, friend! I told you I''d make it worth your while.',12340),
	 (1145,0,0,0,0,0,0,0,0,'Ah, a note from Korran. He has been a loyal servant for some time now. I was wondering how his duties were going in the Crossroads.',12340),
	 (1146,2,0,0,0,0,0,0,0,'Don''t mind the thundering echoes off the mountains'' walls. The goblins and gnomes are out among the Flats racing one another in atrocities created by what they call science. There are bigger threats here in Thousand Needles, one of which killed more than half my war party.$B$BBut we remain here until we hear word from Belgrom in Orgrimmar. Until then, we hold our position here, and stay vigilant.',12340),
	 (1147,11,1,1,2,0,0,0,0,'Ha! That ichor you''re covered in actually makes you prettier, $N! It certainly does make you reek at the same time though. Don''t stand too close to the kodo; you''ll either start a stampede or cause them to go into heat.$B$BI think my companions would agree that your smell alone is proof you''ve done your part to help us against those insect creatures. Thank you, $N.',12340),
	 (1148,1,0,0,0,0,0,0,0,'Ahh, you''ve seen Moktar recently? He always be lookin'' out for me. I''m sorry to hear he spends his time watching over his little war band instead of seeing battle, but I''m sure he be takin'' great joy in killing members of the Explorers'' League.$B$BYou be smart to bring me these specimens, $N. Along with the eggs we be findin'' in the Field of Giants, these should give me a good start in figuring out what these insects are, and what they be wantin''.',12340),
	 (1149,1,0,0,0,0,0,0,0,'It is not until faced with unforeseen adversity that we begin to see how strong our spirits are. You took the leap of faith even though you had no guarantees that you would survive. Your mind is open, and your spirit is prepared for what is to come.$b$bIf you are willing, then the next of your tests is ready.',12340),
	 (1150,1,0,0,0,0,0,0,0,'Grenka was powerful, even by $r standards. You should be proud of your accomplishment this day.$b$bDuring your test of faith you displayed strength of spirit, and now you have shown endurance in battle by taking on the Roguefeather harpies, but the time has come for a new test.',12340),
	 (1151,1,0,0,0,0,0,0,0,'The Test of Strength is done. You have shown strength and bravery, and you are now prepared for the final test before these rites are completed.',12340),
	 (1152,1,0,0,0,0,0,0,0,'The days and nights grow colder throughout the world as goblins rape the land, and the night elves point fingers at the younger races. The Forsaken and orcs are not the only ones to blame for the hardships found throughout Kalimdor and Lordaeron. Many of the intelligent races have contributed to the world''s pain. Dorn knows this, and he has sent you to me because you have shown the attributes necessary to realize it also.$b$bNow you stand before Braug.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (1153,2,0,0,0,0,0,0,0,'A good sample, $N. A good sample indeed.$B$BThose travelers can no longer lord over me the ore they found, now that you have been successful.$B$BI shall get to work on it immediately. If it proves strong enough, I will send a weapon crafted from the material back to the warchief to show him our success.$B$BI shall not forget your help, $C.',12340),
	 (1154,1,0,0,0,0,0,0,0,'This is the book I named. There is hope you will answer my question correctly then... unless you''ve forgotten to study its contents.$b$bWhen you are prepared, speak to me again and I shall ask a question of you.',12340),
	 (1159,6,274,0,0,0,2000,0,0,'Braug sent you? Impossible.$b$b<Parqual looks you up and down.>$b$bBraved Dor''Danil, took a leap of faith, fought and overpowered a powerful elemental? Bah! You''re probably a farce; some adventurer that overheard talk in a tavern. And now you think you have what it takes to pass my test. So be it... $C.',12340),
	 (1160,1,0,0,0,0,0,0,0,'This is the book I sent you to search for.$b$b<Parqual slowly caresses his hand over the top of the book as he stares down at it.>$b$bSo now you wish a question to prove your mind is as powerful as your body and spirit. If you have studied the book long enough, then I shall ask you your question and you can be done with these tests!',12340),
	 (1164,1,2,0,0,0,0,0,0,'You stand before me as a figure of vengeance, and I bow down before you in thanks.$B$BWith that cow''s death, and knowing that their seed will no longer spread over the face of Azeroth, I can put my energy into something more lucrative. I hope you looted their farmstead after you finished them off.',12340),
	 (1166,0,0,0,0,0,0,0,0,'You good $r. Me miss things very much. Me like you now.',12340),
	 (1167,5,1,6,0,0,0,0,0,'Ah, it''s good to see you again, $N! The strangest things have been happening around here, I''m glad you showed up!$B$BIt was very strange, $N. Everything seemed normal--well, as normal as things get around here--and then suddenly there was a blinding flash of light from the upper room of the tower. Then came the screams. The cries split the air, and lightning struck the ground from time to time. What''s going on?',12340),
	 (1168,0,0,0,0,0,0,0,0,'You kill many of the black dragon army. You brave $r.$b$bMake Tharg happy.',12340),
	 (1169,0,0,0,0,0,0,0,0,'''Twas a perilous affair, no doubt, collecting all of these hearts and tongues. I shall delve into the depths of the arcane to trace the origin of the black menace which has descended upon our former home.',12340),
	 (1170,1,0,0,0,0,0,0,0,'Why you tell me ''bout dragons? Me no like dragons. Me like it here. No dragons here.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (1171,0,0,0,0,0,0,0,0,'That lazy coward!$b$bMok''Morokk displayed strength when Rexxar was our leader. But soon after Rexxar''s departure Mok''Morokk fell prey to temptations of power. Rather than lead, he demanded. He does not serve his people but rather expects us to serve him.$b$bSomething must be done.',12340),
	 (1172,0,0,0,0,0,0,0,0,'Splendid! It will be sometime before Onyxia can produce more eggs.$b$bOn behalf of my people, I thank you, $n.$b$bI have asked much of you so far. Perhaps you can do the Stonemaul Clan one last service.$b$bMok''Morokk is not fit to lead us. Tharg would make an excellent leader but is hindered by his injuries and age. Drive Mok''Morokk from this place by force. Only then can we appoint a new leader to return us to our proper home in the south.',12340),
	 (1173,1,1,0,0,0,0,0,0,'That cowardly fat mass Mok''Morokk fled like a scared child. You have done a great service, $N.$B$BNow my people can appoint a new leader, one who will help us reclaim our old home once and for all.',12340),
	 (1175,1,0,0,0,0,0,0,0,'I hope you didn''t kill any of the basilisks on the tracks themselves! It takes a long time for the carcasses to decay in the sun, and I''d rather not have to take a shovel out to clean up.',12340),
	 (1176,0,0,0,0,0,0,0,0,'Great! I can get the crew working on this right away. Thanks, $n!',12340),
	 (1177,0,0,0,0,0,0,0,0,'Me like fishy head!$B$BMe no eat you now.',12340),
	 (1178,0,0,0,0,0,0,0,0,'Pozzik sent you, huh? You know, Pozzik was one of the most respected tinkerers in Undermine before he retired to start working on the racers.$b$bThe first thing he did when he joined the team was develop the two engine model racers. Could be that the businesses will suffer without him working with the Tinkers'' Union, but who cares, right? There''s nothing like the races!',12340),
	 (1179,4,0,0,0,0,0,0,0,'Ah!  Longbeard sent you with a load of helmets!  Hooray!$B$BNow maybe we can talk a pilot into driving our car...',12340),
	 (1180,1,0,0,0,0,0,0,0,'Shipments to Ratchet? Let me just check the logbooks...$b$bNo, the most recent shipment I have on record of going out to Ratchet were boots from Drizzlik. Hasn''t been much else, other than building supplies and tools. Definitely no race parts.',12340),
	 (1181,0,0,0,0,0,0,0,0,'Oh, sure of course I know what you''re talking about. Nope, can''t help you though. Some of my men were supposed to go track down the blueprints for the fuel regulator, but they came back empty-handed.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (1182,0,0,0,0,0,0,0,0,'Now, let me just get a copy of these blueprints for my own notes and you can bring these straight to Pozzik. Wouldn''t want him to think that one of his sponsors was abandoning him.',12340),
	 (1183,0,0,0,0,0,0,0,0,'I was hoping that it would be already assembled, but this does present the unique opportunity to improve on the design from the ground up. Thanks, $N. I''ll be able to sketch up some improved schematics, build the thing, and have it installed real soon.',12340),
	 (1184,2,1,1,0,0,0,0,0,'I''m appreciative of your efforts, $c. The warchief will enjoy hearing how tenacious you have been in your duties.$B$BOh, of course I will mention your name to him. He speaks to me often and values my opinions greatly.$B$BGo now, I have much to do. And if you speak to Korran soon, and he has news of these creatures, then return to me--I would think they are a threat that must be taken seriously.',12340),
	 (1185,5,1,1,0,0,0,0,0,'Hey, it''s you again! Well, I mean you - as in the you that is $N! Yes - that you!$B$BHey, let me start over!$B$BThat object you found in Silithus - it was in fact a book. It was a journal written in a very ancient dialect of what we now call the Darnassian tongue. It''ll take a while, but I''m going to go over it very thoroughly. I thought you should know that what you found was extremely valuable for the Circle.$B$BThe den mother''s all excited and everything!',12340),
	 (1186,1,0,0,0,0,0,0,0,'You''re the $R that''s been helping Pozzik out, right? I was like you once, running around the pit area, helping with whatever work the mechanics would let me do.$b$bNow look at me! The goblin racing team''s pilot extraordinaire!',12340),
	 (1187,4,0,0,0,0,0,0,0,'Just take a look at this beauty! Fifteen pounds of solid seaforium power! Once I get this strapped on to the side of my racer, I''ll be around the track so fast I''ll beat the gnomes twice!',12340),
	 (1188,0,0,0,0,0,0,0,0,'Only Razzeric would take a look at this and say that I''d somehow put some sort of safety lock on it. This booster is almost completely seaforium explosives. I already modified it so that more of its payload would be delivered upon use, but Razzeric is never content unless he goes to eleven!',12340),
	 (1189,0,0,0,0,0,0,0,0,'Now that''s more like it! I wish I could see the look on the gnomes'' eyes when they see me set this baby off.$b$bToo bad I''ll be too busy pulling off a new course record!',12340),
	 (1190,0,0,0,0,0,0,0,0,'Scribbled in a hasty, hurried hand, a scroll of notes and designs for the refinement of some raw material.',12340),
	 (1191,0,0,0,0,0,0,0,0,'Let''s go!',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (1192,0,0,0,0,0,0,0,0,'Excellent! I''ll get the crew to work right away on the parts we''ll need for the next race.',12340),
	 (1193,0,0,0,0,0,0,0,0,'The thorium widget slides effortlessly into place, creating a conduit to pour the frost oil down. Once the last drops of oil have been emptied into it, the trap snaps into position.$B$BWoe be to any unwary ogre that should just so happen to wander by!',12340),
	 (1194,0,0,0,0,0,0,0,0,'Indurium? Interesting... If it is capable of resisting heat to the degree that you say, it would explain the performance increase the gnomes have displayed of late.$B$BThis sample you''ve brought to me will be invaluable, also. I will be able to perform some tests on this, but I''ll need more for this to actually be of any use to us.',12340),
	 (1195,0,0,0,0,0,0,0,0,'Very good. This should fill Rau''s request just fine. Could you deliver this to him? You might enjoy spending some time out in the Needles.',12340),
	 (1196,0,0,0,0,0,0,0,0,'Hm, yes, this phial of water will serve our purposes perfectly. Because of the shared ancestry of the dryads and the centaurs, the water of the moonwells will enable us to breach the protection of the eternal flame surrounding the centaur relic.',12340),
	 (1197,1,0,0,0,0,0,0,0,'I sense a strange energy emanating from the Hoof... I have no doubt that we will discover surprising new information about the centaur from its study.$B$BMy thanks, $N. Now I must begin to decipher the mysteries you have brought to me.',12340),
	 (1198,0,0,0,0,0,0,0,0,'Dawnwatcher Shaedlass was good to send you. There is indeed a wicked plot underway in this corrupted place.',12340),
	 (1199,66,0,0,0,0,0,0,0,'You are no doubt of brave and noble blood, $N. The Argent Dawn commends you for your efforts against evil.',12340),
	 (1200,1,1,66,0,0,0,0,0,'Kelris has eluded us for quite some time.$B$BIt seems as though whenever evil made its presence known in these parts, Kelris had played a role. For some time we considered him dead or missing.$B$BBut this makes perfect sense. By ending his reign you have spared the lives of many innocent people.$B$BBy the light! To sacrifice someone to a servant of an Old God for one''s personal gain is beyond reproachful!$B$BYou have done a great deed, $N. I salute you on behalf of the Argent Dawn.',12340),
	 (1201,0,0,0,0,0,0,0,0,'Good work.  Their infiltrators are skilled, but they''re not good enough to escape the watchful eye of the Horde!',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (1202,66,0,0,0,0,0,0,0,'I commend you, $N. This was not an easy mission. But the documents you gained are valued greatly by our superiors.',12340),
	 (1203,1,36,4,0,0,0,0,0,'That''s a good blade. It has a good swing. It''s a good swing blade. Thank you. Thank you, thank you, thank you!!! Now I want to try it....$B$BLater. I''ll try it later. But like I was saying... thanks.',12340),
	 (1204,4,1,0,0,0,0,0,0,'These will do fine! Thank you, $N!$B$BNow I''ll try different cooking techniques on these tongues to find the best way to bring out their flavor.$B$BEventually I''ll have a dish worthy of serving at the Blue Recluse in Stormwind!',12340),
	 (1205,1,0,0,0,0,0,0,0,'Very good, $N.$b$bI am sure the hunt was not easy, but it is good to know the beast''s pain has finally ended.',12340),
	 (1206,4,1,3,0,0,0,0,0,'You got the eyes! You got the eyes! Tasty, tasty spider eyes!$B$BSome eyes... when you stare at them they stare back. Eat those last. They keep you company... out in the swamp.$B$BHello, little spider eyes. Hello! You taste like chicken. Gooey, salty chicken!$B$BMmmh.',12340),
	 (1218,4,0,0,0,0,0,0,0,'Ah, that''s the spice!  Now here''s some swampy good stew.',12340),
	 (1219,1,0,0,0,0,0,0,0,'Hm... I can''t read orcish very well, but this looks like a report... written by an orc spy!',12340),
	 (1220,1,0,0,0,0,0,0,0,'A report from an orc spy!  How did you find this?  No matter -- let''s see what it says...',12340),
	 (1221,4,0,0,0,0,0,0,0,'Great, you got them! I can sell these to my contacts for a bundle!$B$BThanks for the delivery, $N! You are a great partner.',12340),
	 (1222,1,2,0,0,0,0,0,0,'Mr. Ignatz was just here with the bogbean leaves, and he told me you helped him out of some real trouble.$B$BThank you, $N.  I will ask my uncle to treat you to a feast the next time you visit the Blue Recluse in Stormwind.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (1238,1,0,0,0,0,0,0,0,'Good work, $N. Our agent, Marg Nighteye, was stationed outside Theramore. He was charged to spy on the city. $b$bThis is his latest report, and it may be his last -- from your testimony, I fear that Marg met his end in the swamp...',12340),
	 (1239,1,0,0,0,0,0,0,0,'This is the head of Marg Nighteye! As I feared, he is dead.$b$bLook at the wound on his neck! Could a weapon have made that ragged cut, or did some beast slay our agent?$b$bThis is a mystery we must solve, $N. We must discover if Marg''s death was at the hands of the Alliance!',12340),
	 (1240,1,0,0,0,0,0,0,0,'Ah, I now see. The spirit of this orc is bound in our world, boiling with rage from a task yet undone.$b$bWell, let us have words with this angry orc...',12340),
	 (1241,1,1,6,0,1000,0,0,0,'Hmm... <Jorgen looks up at you through squinted eyes.>$b$bAll right. I''ll help ya, but not because I want to, but because I''m obligated.$b$bAnd let''s get one thing straight: you''re knowin'' far more than you should to begin with. Let''s keep this our little secret, and don''t go blabbin'' at any taverns about anything you find out. Understand?',12340),
	 (1242,6,11,0,0,0,0,0,0,'I''m sorry, a letter for me? Well, I''ll be... not often you get a delivery that''s not a crate or barrel when all you do is work. Let''s see what this is about.$B$B<Elling looks up at you while he opens the letter.>$B$BYou look a little tense, you okay, $N?',12340),
	 (1243,6,11,6,0,0,0,0,0,'Oh, Trias sent you, huh? That''s a little different.$B$BFeel free to fight whatever monstrosities come at you from the darkness. I''m sure you''ll be able to handle it pretty easily if you''re the type to be hanging around with the likes of him.$B$BSo, what does my friend need of me on such a gloomy day as this?',12340),
	 (1244,1,1,0,0,0,0,0,0,'You''re back safe and sound. Couldn''t ask for much more than that, could you?$B$BNow, let''s see what we have here. This looks pretty official as far as any Defias documents I''ve seen. But it could be a dupe just to throw you off track of whatever it is you''re looking for.',12340),
	 (1245,1,1,0,0,0,0,0,0,'Yeah... this is an interesting read. Jorgen and DeLavey were smart to bring me in on this.$B$BSeems the Defias have been trying pretty hard to complete this plan of theirs. Hmm... what''s this? Fist? That''s a familiar name.',12340),
	 (1246,14,1,0,0,0,0,0,0,'What?!$B$BYou come into me alley and ask questions about me personal business? Business which you obviously have nothing to do with.',12340),
	 (1247,3,1,1,0,0,0,0,0,'Good to see you''re still alive, $N. So, it went well with Dashel then, huh?$B$BI''ve been reading up more on this plan of theirs, and although it doesn''t state the name of the diplomat they were after, it does talk about this plan B they enacted after failing on their first attempt to capture him.$B$BThis Slim that Dashel mentioned doesn''t have any other name written here, but if you say he''s in Menethil, then that''s a start.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (1248,3,1,6,1,0,0,0,0,'Welcome, welcome, welcome, $N. Good of you to join us. Perhaps an ale today? Or some mutton?$B$BName your pleasure and I''ll see to it that you''re taken care of. My name is Mikhail, and I look forward to serving you.$B$BHmm? What''s that? Trias? Keep your voice down, my friend. This isn''t something for the whole tavern to hear about.',12340),
	 (1249,6,1,1,6,0,0,0,0,'Caught him, huh? Good for you. I''m surprised that was Slim.$B$BI''ll be honest, I never thought I''d miss the excitement of some of the more devious underground activities. I guess old habits die hard. Don''t mention that to Elling--he''d probably try and get me to come back to Stormwind if he heard I missed the action.$B$BI''m glad I could at least be of a little service to you while you were in Menethil. If you need anything else, just ask.',12340),
	 (1250,5,1,1,1,0,0,0,0,'THE KING?! I mean... the king? The real king? Are you joking? You didn''t mention you were looking for the king''s kidnappers. I didn''t even hear he was missing--that would explain his son being crowned some.$B$BI''ll send word to Elling right away. He''ll want to know you''re on the trail.$B$BI would never have guessed Jahn would sell out Stormwind for some lousy coin. Even a rogue''s got to have honor when it comes to some things.$B$BThe key now is to find this Hendel. And I think I can help with that.',12340),
	 (1251,1,0,0,0,0,0,0,0,'I grant that humans have strange decorating tastes, but would they use a plain iron shield to adorn their fireplace? Perhaps this shield was placed there by the ones who burned the inn.$b$bA warning? A threat?',12340),
	 (1252,1,0,0,0,0,0,0,0,'It''s never good news when a guard''s badge is brought to me.$b$bSometimes it''s a man or woman who''s fallen in battle, and I''m left to bring the news to the grieving family. Other times we never find out what happened to them. And other times it''s even worse than that.',12340),
	 (1253,1,0,0,0,0,0,0,0,'Hm, I''m no expert with the construction of arms and armor. Their use, yes, but not their making.$b$bThis shield seems as ordinary as any, excepting the damage from the fire that engulfed the inn.',12340),
	 (1258,1,0,0,0,0,0,0,0,'These are wonderful specimens, $N! The shells are in perfect condition, and the meat is pink and tender. The blood of a chef is in your veins, I''m sure of it!',12340),
	 (1259,0,0,0,0,0,0,0,0,'Hello, $n. You''d like information about a specific member of the Theramore guard? Reethe, was it?$b$bJust give me a moment to find the right book.',12340),
	 (1260,6,1,0,0,0,0,0,0,'Oh, my uncle sent you, did he?$b$bWell I''ve been researching recipes and I have some leads, but I need help.$b$bHelp from someone willing to get his feet wet.',12340),
	 (1261,6,66,0,0,0,0,0,0,'This pendant was worn by a soldier of Stormwind??$B$BThank you, $N. You have revealed the secret of Marg''s death. But this pendant is a new mystery to solve, one that may have dire effects on the Alliance, and the Horde.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (1262,0,0,0,0,0,0,0,0,'This pendant was crafted with great skill and precision, $N. No orc would covet such a jewel...$B$BBut many humans would.$B$BI will have this pendant studied. In time let us hope that its mysteries will be revealed to us.',12340),
	 (1264,66,1,1,0,0,0,0,0,'A pleasure to meet you, $N. I am Commander Samaul. I''m in charge of Miss Proudmoore''s forces here in Theramore.$B$BAlthough I''m quite busy, if you have any questions, please feel free to speak up. I might have to keep it short, but there''s no reason for me to be rude if you need my help.$B$BIf you plan on traveling out of the city, I''d suggest you be careful. Besides ogres, orcs and murlocs, the southern part of the swamp is filled with black dragons.',12340),
	 (1265,1,1,2,0,0,0,0,0,'The man you seek, the one known as Hendel, is not here. Other sources have brought to the Lady Proudmoore information I believe you already know. She has asked me to find you, and give you aid in your venture. If you would allow it, I will tell you where to find Private Hendel so we can bring him to justice.',12340),
	 (1266,2,1,1,1,0,0,0,0,'Hello, citizen. This is a dangerous place to be wandering about. I wouldn''t hang around too long if you value your life.$B$BIf you keep your questions short, I''ll see if I can help you. Just keep your eyes open for any of those filthy ogres. Rumor has it there''s a Horde base somewhere in the swamps. The infiltrators are doing what they can to find it, but the process has been slow going and we''ve had little progress.',12340),
	 (1267,1,1,0,0,0,0,0,0,'Let me be first to thank you for all you''ve done, $n. You have been an incredible blessing to my people and the people of Stormwind. I am sorry I couldn''t make your acquaintance under better circumstances.$b$bUnderstand also that I cannot overtly thank you for your efforts, but I assure you again, it is appreciated.$b$bWhen you visit Theramore in the future, seek me out and I shall try to keep you appraised of the situation.$b$bThank you again, $n.',12340),
	 (1268,0,0,0,0,0,0,0,0,'Hoofprints... It could have been the quilboar, I suppose. Or maybe even the centaur. Their presence in the Barrens is not insignificant, and I would not think it a stretch to commit such an act.$b$bDid I tell you? It wasn''t just that the inn was burned down... The owner''s woman and pup were killed. Bad business, that.$b$bNonetheless, I will send Kagoro to find where the tracks lead.',12340),
	 (1269,0,0,0,0,0,0,0,0,'I know this human, Paval Reethe. Pathetic, even for his kind. He deserted his fellow soldiers and is now hiding out in the woods.$b$bI sent Ogron out to track him down. Some of the others suspect he''s been stealing from our supplies. I think I saw Ogron heading off to the southeast.',12340),
	 (1270,0,0,0,0,0,0,0,0,'Stinky was here with the herbs I ask of him, and he told me you helped him out of a bind. Good work! A friend of Stinky''s is a friend of mine!$B$BHe asked me to give you this if I ever saw you, right before he walked back south toward the marsh.',12340),
	 (1271,1,2,0,0,0,0,0,0,'My nephew said you aided him with his research in Dustwallow, and that you helped his associate out of a tight spot.  Well, we Sterns stick together and we don''t ignore our friends!$B$BSo wash your hands, $N, because we''re about to throw a party in your honor!',12340),
	 (1273,0,0,0,0,0,0,0,0,'Hmph. It is good that Reethe will no longer be lurking around the swamp, but it is a shame that humans are built so frail that he could not recover from a little arrow wound.$b$bIt seems that this thread of the mystery has led nowhere, and we must look elsewhere.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (1274,2,1,1,0,0,0,0,0,'Hello, $N. I am Bishop DeLavey.$B$BNo doubt if you''re asking me about my business here in the keep then young Thomas has succeeded in requisitioning you to help our kingdom. He has always been adept at following my requests.$B$BI''m afraid I don''t have time to elaborate much, so allow me to be blunt... and please, try to keep this from becoming common knowledge.',12340),
	 (1275,1,2,0,0,0,0,0,0,'You have traveled far and undoubtedly faced great peril.$B$BYour actions have been selfless. ''Tis for the good of all Azeroth that you help me with my research. I thank you, $N, for all that you have done.$B$BNow if you''ll excuse me I have much work to do....',12340),
	 (1276,0,0,0,0,0,0,0,0,'Yes, you are certainly correct. This is a shield that I made.$b$bI''m afraid there''s not much more I can tell you though, $n. I craft so many different shields and sets of armor, I can''t keep track of them all.',12340),
	 (1282,1,1,1,0,0,0,0,0,'James Hyal''s his real name. He opened an inn at the edge of the Barrens. Wanted to make a nice place for travelers to stop over...$B$BMight be he was thinking too big, but the inn did do well for a while. Then we lost control of the roads in the marsh, and the ogres took over.$B$BJames was too stubborn to give up his dream for safety within our walls, and the Shady Rest Inn was burnt to the ground. We''re investigating, but haven''t had much luck. If you want to help out, see what you can find in the rubble.',12340),
	 (1284,6,0,0,0,0,0,0,0,'Hoofprints, eh? It is true that there is an extraordinary amount of centaur activity in the lands near the Dustwallow Marsh. In brief excursions into the Barrens, we found their camps and holdings dotting the area.$b$bI''ll send out Falgran Hastil, one of our trackers, to see if he can find where the tracks lead.',12340),
	 (1285,1,0,0,0,0,0,0,0,'Missing? That would be Tesoran''s kind way of saying traitor.$b$bNo doubt he''s one of those fools so blindly loyal to Admiral Daelin that he turned traitor.  Isn''t that a delicious irony? The deserters accuse us of betraying the Alliance.',12340),
	 (1286,0,0,0,0,0,0,0,0,'Did Vimes send you? Couldn''t do his dirty work himself, could he...',12340),
	 (1287,1,0,0,0,0,0,0,0,'I will send Lieutenant Caldwell to deal with the deserters at Lost Point. In addition, I will instruct him to find Reethe. The marsh is not so big and trackless that he should be unable to find him.',12340),
	 (1301,6,1,0,0,0,0,0,0,'James? Oh, he left quite some time ago.$B$BFelt the second wind of patriotism, I suppose. Not hard to see why he would. With all the insanity in Lordaeron, many people joined up with Jaina Proudmoore when she went across the sea.',12340),
	 (1302,6,1,0,0,0,0,0,0,'James Hyal, James Hyal... Why does that name sound so familiar?$b$bOf course! The Shady Rest Inn incident. If you have any information about what happened there, I would urge you to speak with Captain Vimes about it. He''s handling the investigation.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (1319,1,0,0,0,0,0,0,0,'Hm... interesting piece of iron you have here. Definitely not made by any of the blacksmiths I know over on this side of the sea, and it''s certainly not my work.',12340),
	 (1320,1,0,0,0,0,0,0,0,'That''s not much information to work on, but we''ll have to keep it in mind. Hopefully some of the other pieces of this mystery will fall into place, and paint a more helpful picture of what happened.',12340),
	 (1321,0,0,0,0,0,0,0,0,'This is good shield. Very strong, heavy, good. But Do''gol don''t need it. I make shields, not buy them, $n.$b$bYou should know that.',12340),
	 (1322,0,0,0,0,0,0,0,0,'I don''t like spiders that are so big I can''t sit on them and squish them.$b$bThanks for getting them, $n. Now I rip them open and pour them onto the shield...',12340),
	 (1323,1,0,0,0,0,0,0,0,'Mosarn? Sounds familiar... I can''t put my finger on it. Maybe it''ll come to me later.$b$bIt probably isn''t important. A shield can come from anywhere and not mean anything...',12340),
	 (1324,1,1,1,0,0,0,0,0,'I assure you, we''re all quite upset about current events, but allow us to take him back to Theramore for some questioning, and we''ll see about finding the King.$B$BI''m sure my lady Proudmore would like to thank you for your help. Speak to her when you have a moment.',12340),
	 (1338,1,0,0,0,0,0,0,0,'Ah, a request from one of the Stormpikes. That''s a proud clan, full of quality dwarves. Rich ones, too.$B$BThank you, $N. I''ll get to work on Mountaineer Stormpike''s shield by the end of the day.',12340),
	 (1339,1,0,0,0,0,0,0,0,'That''s right.  I have a task that I can''t do while I''m guarding.  In fact, it''ll take you far from Loch Modan.$B$BYour perfect chance for adventure!',12340),
	 (1358,1,0,0,0,0,0,0,0,'Ah, very good. If initial reports are true, then the toxicity of these hearts could lead to further advances in our knowledge of poisons.$b$bThis is a welcome delivery, $N. Your reward is well earned.',12340),
	 (1359,1,0,0,0,0,0,0,0,'Ah yes, the heart samples of which Renferrel spoke. I am eager to experiment with these... it is always of interest to the Royal Apothecary Society when new forms of toxins are discovered.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (1360,2,1,0,0,0,0,0,0,'Ah, I feel complete again - thank you kindly.$B$BSome dwarves may treasure the luster of metal, and some may treasure the glint of gems... but a Stoutarm without a treasured stein in hand is hardly a Stoutarm at all!',12340),
	 (1361,0,0,0,0,0,0,0,0,'Yes, I am recruiting. This mission leads into Desolace, against the centaur there. I will be brief so that you may quickly begin.',12340),
	 (1362,6,1,0,0,0,0,0,0,'You are here on orders from Regthar? Then you are here to deal with the centaur. Good.$B$BI hope you''re rested. I don''t know how our campaign against the centaur will end, but I know the struggle will be long.$B$BHave a seat, and listen.',12340),
	 (1363,0,0,0,0,0,0,0,0,'It wasn''t my fault. Really it wasn''t.',12340),
	 (1364,0,0,0,0,0,0,0,0,'Ah, most splendid!$B$BFor some time I had feared my request for Khadgar''s Essays on Dimensional Convergence had been overlooked by Master Mazen of the Academy of Arcane Arts and Sciences.$B$BHe must be bogged down with requests considering the many strange happenings going on.$B$BNow, if you''ll excuse me, I need to begin my research at once. To finally glimpse the insight of one as great as Khadgar excites me to no end.',12340),
	 (1365,1,0,0,0,0,0,0,0,'Well done. This swift act against the Kolkar is an effective show of strength, and strength is what the centaur understand best.$B$BThe death of the Kolkar leader will not only disrupt that clan, but give pause to the others.',12340),
	 (1366,1,66,0,0,0,0,0,0,'By now, the centaur must know your name. I''m sure they know it, and respect it, and fear it. And just as they know you, they know the banner under which you ride.$B$BThe banner of the Horde.',12340),
	 (1367,0,0,0,0,0,0,0,0,'The Gelkis cry when they hear your name, $N. They fear you and they hate you. They hate you like they hate the Magram!$b$bMaybe you are strong like the Magram. We will see...',12340),
	 (1368,0,0,0,0,0,0,0,0,'The earth speaks to me. And it says you have killed many Magram. This is good.$B$BIf you are a friend of the Gelkis, then listen. I have more tasks for you.',12340),
	 (1369,0,0,0,0,0,0,0,0,'You got the tears! Now the Gelkis will know that Theradras will not help them. She will not cry when we crush them! The Magram will rule!$B$BYou are smart to help us, $N. We are the strongest.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (1370,0,0,0,0,0,0,0,0,'Good. I can hear the loud Magram bellies grumble from their village, far away!$B$BI will give this meat to the Gelkis. And we will fight for many days without rest.$B$BWhat you did is good for the Gelkis, $N.',12340),
	 (1371,0,0,0,0,0,0,0,0,'Yes, this is what I had! I will make it move again. It makes me laugh!',12340),
	 (1372,0,0,0,0,0,0,0,0,'Zraedus was just telling me about the nosey little Infiltrator before you arrived.$b$bQuite a problem, indeed. The last thing we need is a busybody sniffing around Beggar''s Haunt.$b$bI am sure the orcs of Stonard would be quite anxious to hear what our friend has to say. Seeing that they are our allies, ahem, we must help them to get any information they can from the human.$b$bWork with me, $N, and we will deliver a truth serum to Stonard.$b$bFor the Horde!$b$b...did I get that right?',12340),
	 (1373,0,0,0,0,0,0,0,0,'Yes, this is the shard of which the earth whispered. I can feel strong magic in it! I will use this magic against the enemies of the Gelkis.$B$BYou have done one more task for us, $N. Maybe soon, we will call you friend.',12340),
	 (1374,0,0,0,0,0,0,0,0,'Khan Jehn was strong, but stupid. He thought his own strength was great. He did not see that earth magic is stronger. The Magram centaur will now fall without their leader, and the Gelkis will one day rule!',12340),
	 (1375,0,0,0,0,0,0,0,0,'Khan Shaka is dead!  I will place his head on a pike, and keep it with me so Shaka can see the strength of the Magram!',12340),
	 (1380,0,0,0,0,0,0,0,0,'He is dead! Khan Hratha is dead! And now the Maraudine will fall! When the Gelkis rule this land, $N, we will remember you. And the spirits of the earth will sing your name for all time.',12340),
	 (1381,0,0,0,0,0,0,0,0,'Khan Hratha is dead!  Now the Magram are the strongest of the centaur!  We will crush the others, and rule Desolace!$B$BWe will remember, you, $N, and you will be spared our hooves when all others are trampled.',12340),
	 (1382,0,0,0,0,0,0,0,0,'Your name is whispered among the Gelkis. You have much Magram blood on your hands. This is good.$B$BMaybe it is also good if we speak. Speak of what you can do for the Gelkis, and what we can do for you.',12340),
	 (1383,4,0,0,0,0,0,0,0,'Splendid, $N! And just in time too. From what Zraedus tells me, the Infiltrator has recovered from his wounds and is ready to be questioned by the orcs.$B$BGive me but a moment to prepare the pois - I mean prepare the truth serum.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (1384,0,0,0,0,0,0,0,0,'You do a good thing for the Gelkis. The Kolkar are weak and will die. Their magic is pathetic and will not save them. You showed them this, and their fear will make them even more feeble!$B$BAnd in our lands, the feeble soon die.',12340),
	 (1385,0,0,0,0,0,0,0,0,'Many Gelkis fall to you. I like that. Maybe you can do more things I like. Maybe you and the Magram can be friends.',12340),
	 (1386,0,0,0,0,0,0,0,0,'The Kolkar fear you now! I hope you laughed when you killed them. It is better to laugh when you kill, so the enemy can see he is weak.',12340),
	 (1387,1,66,0,0,0,0,0,0,'Ah, the ears. Well done.$B$BYour service to the Alliance is unquestioned, $N. The blood you spilled in Desolace will, no doubt, save countless lives.',12340),
	 (1388,1,0,0,0,0,0,0,0,'I knew old Faustin would come up with something good! You were a tremendous help, no doubt.$B$BNow let''s get down to business, shall we?',12340),
	 (1389,2,0,0,0,0,0,0,0,'Thank you, $N. We, are in your debt.',12340),
	 (1390,0,0,0,0,0,0,0,0,'Thanks for the done work!',12340),
	 (1391,6,0,0,0,0,0,0,0,'A drink for me? How kind. It''s been days since they''ve allowed me to drink. Let me drink this down and then I''ll tell you what I''ve learned....',12340),
	 (1392,1,0,0,0,0,0,0,0,'You have gained the weapon of the dreaded Noboru?  Is he then dead?$B$BThis is a joyous day for the Harborage.  Noboru and his gang were a terror to us, wandering the swamps and killing any Draenei who crossed his path.  He was a direct threat to our survival, and we did not have the strength to face him.$B$BWe are fortunate to have a friend in you, $N.',12340),
	 (1393,0,0,0,0,0,0,0,0,'The keyhole of this strongbox is filled with black resin. It is impossible to open.$b$bBut Galen told you of a hidden latch on the box''s bottom... $b$b...After a quick search the latch is found. The latch is flipped, and the strongbox opens...',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (1394,1,1,0,0,0,0,0,0,'Ah, $N. It has been a long time since you have last stepped into my home. It seems like many moons have passed since you took your first leap that set you upon your path.$b$bAnd now you return to me stronger than you once were... more enlightened. This pleases me. And you should be justly rewarded for seeing my tests to the end.',12340),
	 (1395,4,2,0,0,0,0,0,0,'Ah, the powerstones! The mages will be happy to see these!$B$BMany thanks, $N. I know your trip from Darkshire was not an easy one.',12340),
	 (1396,4,0,0,0,0,0,0,0,'The sounds of animals are now faint, more distant. Thank you, $N. Now let''s hope they don''t return!',12340),
	 (1398,2,0,0,0,0,0,0,0,'This wood is light, but tough. Thank you, $N. It will work nicely.',12340),
	 (1418,6,0,0,0,0,0,0,0,'Helgrum wants a report, eh? I sent an outrunner to Stonard not three days past. Did he fail his mission? If Stonard does not have my report, then it appears he did fail.$b$bLet''s hope the next runner I send has more skill, or more luck.',12340),
	 (1419,1,0,0,0,0,0,0,0,'That''s a nice collection of jawbones, $N. Now those coyotes won''t be tearing through our supplies for scraps.$B$BWell done. The coyotes of the Badlands aren''t easy prey. Your deed shows me that you might just survive here.',12340),
	 (1420,1,0,0,0,0,0,0,0,'Thank you, $N. From Neeka''s report, I see the Alliance is not without its own problems. And we may find that some enemies are shared between us.',12340),
	 (1421,1,0,0,0,0,0,0,0,'Ah, you found them! With these, the wizards in Nethergarde may continue their work. I do not know what it is that they do, but it is linked to the Dark Portal in the Blasted Lands, and is vital to the security of the Alliance.',12340),
	 (1422,1,0,0,0,0,0,0,0,'Be silent a moment, $C. Even over the dull roar of the sea you can still hear those disgusting gurgles from the fish men.',12340),
	 (1423,2,0,0,0,0,0,0,0,'Ah, thank you $N! So many supplies are lost from Darkshire to here. It''s good to see that some are recovered.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (1424,1,0,0,0,0,0,0,0,'Your diligence in collecting the Atal''ai artifacts is worthy of praise, $C.',12340),
	 (1425,6,2,0,0,0,0,0,0,'What? A package from Biggs'' caravan? We thought it, and he, were lost.$B$BThank you, $N. With luck, these supplies will carry the much needed reagent, Azoran Crystals. Our stock is running low...',12340),
	 (1426,1,0,0,0,0,0,0,0,'The sea seems vast and relentless, but you have stained her with the blood of her own spawn. The fish men know pain. Their stupidity will force them to refortify their ranks from the devastation you''ve caused, and that is good.$B$BLet their gurgling screams overshadow the sea''s roar long into the night. I shall smile every time I hear one of them silenced.$B$BReturn to me if you wish to slay more of the fish men. I will gladly reward you again.',12340),
	 (1427,1,1,0,0,0,0,0,0,'Ah, $N, you''ve returned. Good. I''ve finished crafting more weapons for our fight against the murlocs. For bringing us the fresh sawtooth meat, and for bringing a small smile to Katar''s face, I offer one of them to you.',12340),
	 (1428,2,1,0,0,0,0,0,0,'Well done, $C. I call for more of their blood. Let all the fish men perish.',12340),
	 (1429,6,1,0,0,0,0,0,0,'You bring me the summoning artifacts of the Atail''ai?$b$bI see Jammal''an the Prophet is leading the disciples of the Chamber of Blood towards their chosen fate. Has Hakkar returned to the Temple I wonder? Has their fate been met?',12340),
	 (1430,4,0,0,0,0,0,0,0,'Ah, this should be perfect. I can''t wait to taste these after they are prepared perfectly over an open fire. You should take a sample of it with you on your travels. It truly is delicious.',12340),
	 (1431,2,1,0,0,0,0,0,0,'Putanni, noble $C. I am Keldran, student of magic... and other mystical arts.$b$bThe business Craven sent you here to speak to me about requires a touch more subtlety than you''ve previously needed, but that does not mean you can not still aid our cause.$b$bPlease, make yourself comfortable, and I shall tell you why the Warchief has need of my aid... and yours.$b$bIt starts with appearances, $N. How the Horde sees itself. How our allies see us. And most importantly, how our enemies see us.',12340),
	 (1432,2,1,0,0,0,0,0,0,'Greetings, $C. You bring news from Orgrimmar; that is good.$b$bThe demon infestation overwhelms this area even more than the smell of centaur dung. The horse-men claim this land as their own, but clearly there are influences out of their control that will crush them if not kept in check.$b$bIt does not please me that we aid the centaur indirectly, but it is for the good of the Horde, so I do my duty for the Warchief, even if it means helping the warlocks within the Horde.',12340),
	 (1433,2,1,0,0,0,0,0,0,'Ah, yes. Aid from those loyal to the Warchief is always appreciated.$b$bMy name is Maurin. I am here at the behest of Keldran and the Warchief cub Thrall. It is my desire to aid the youngling leader against the evils that threaten his rule.$b$bCome, come closer, $C. I shall explain to you my plan for removing the festering boil that is the Burning Blade.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (1434,2,1,0,0,0,0,0,0,'You have done well, $c. You have shown honor and dedication.$B$BWhen our campaign in Desolace is done, the Warchief will know that you aided us in our actions here, and that you helped make his will manifest.$B$BI thank you.',12340),
	 (1435,1,0,0,0,0,0,0,0,'Ah, you''ve returned successful. That is good. Give me the gems and I shall put them someplace safe....$B$BMy tasks for you are complete, $C. Speak to Takata when you are rested. He may have other tasks for you, or perhaps needs you to return to Orgrimmar to inform Keldran of our progress here in Desolace.',12340),
	 (1436,1,1,0,0,0,0,0,0,'You have returned from Desolace more than successful, $N. Thank you.$B$BThank you for your efforts, your time, and your understanding to my plea. Thrall understands and desires peace between the Horde and Alliance, and by taking measures to insure our appearance is acceptable, we will not provoke any further threats of unnecessary violence.',12340),
	 (1437,0,0,0,0,0,0,0,0,'As you rummage around the remains of the wagon, it becomes obvious that it was attacked by both spells and weapons. The battle seemed one-sided and quick; there''s no blood to be found, and no remains of any bodies.$B$BWhoever attacked the wagon was efficient and swift.',12340),
	 (1438,20,1,1,0,0,0,0,0,'Thank Elune someone has finally come to help. Please, $C, I need your help. My brother Tyranis and I were captured and brought here by the Burning Blade. I think they mean to sacrifice me to their demon masters!$B$BI knew coming to Desolace was a mistake, but Tyranis has recently begun craving knowledge of all things arcane--even against the wishes of our people. He decided to make this trek even after hearing tales of this land''s demon infestation.$B$BI fear the worst for him.',12340),
	 (1439,18,1,1,0,0,3000,0,0,'This is terrible! But I suppose it was necessary. If it wasn''t by your hand, it would have surely been by that of my people''s. I suppose I should thank you--please forgive me if it doesn''t seem sincere. I mean no offense.$B$BWith the knowledge of my brother''s fate in hand, it seems the time for my escape has come. If you are still willing, I will accept your aid in escaping this horrible place.$B$BWhen you are ready, we can make our way to safety.',12340),
	 (1440,2,1,1,0,0,0,0,0,'Thank you, $N. Dalinda made it safely back here to Nijel''s Point, and in much better condition than I could have asked for. The fact that she arrived here under her own power was a good sign. I hope you''re well?$B$BIt pains me to know that both Tyranis and Dalinda didn''t return, but the embarrassment of Tyranis'' decisions is hers to endure. It is something she will have to deal with when she returns to Darnassus.',12340),
	 (1442,0,0,0,0,0,0,0,0,'This is indeed the gem Stilwell desires, but before I can allow you to bring it to him, it must be purified of corruption--the naga wenches imbue the gems with power, that much is true, but of their own, evil kind.$B$BLet Stilwell know that its power is intact, and it should work well for whatever ritual he wishes it to be part of.$B$BI hope you know what you''re doing, $C, this is no simple item you possess.',12340),
	 (1444,1,6,0,0,0,0,0,0,'It has been quite some time since we spoke, $C. I hope your journey was successful.$b$bWhat knowledge did you gain from the exiled Atal''ai in the Hinterlands?',12340),
	 (1445,4,5,0,0,0,0,0,0,'Brave $C, you have proven yourself to be a great champion of the Horde.$b$bNow this collection of fetishes of Hakkar must be dealt with at once!',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (1446,1,2,0,0,0,0,0,0,'Jammal''an''s reckless trust of false visions led my people to their eternal doom.$b$bI thank you, $C, for avenging my exile. I mourn for my people. I have no home to return to.',12340),
	 (1447,1,6,0,0,0,0,0,0,'So, you came to me for a reason. What is it you need?',12340),
	 (1448,6,1,0,0,0,0,0,0,'The Temple of Atal''Hakkar has been sunk beneath the Pool of Tears? And surrounded by the green dragonflight?$B$BAn amazing discovery, $C. But obviously something has gone terribly wrong.',12340),
	 (1449,6,5,0,0,0,0,0,0,'What do you want, laddy? Can''t you see I''ve got problems to take care of here? Who has time to stand around yapping with some $R chatterbox?$B$BThere are trolls coming out of the woodwork! Make it snappy.',12340),
	 (1450,1,1,1,0,0,0,0,0,'Ah, yes. Of course I remember sending one of my gryphon riders to lend a hand to Brohann Caskbelly.$B$BAlways had a soft spot in my heart for the Explorers'' League. My father helped with the initial excavation team that discovered Uldaman as a matter of fact.$B$BI sent who I thought was my best gryphon rider at the time with Brohann. He was a chap by the name of Rhapsody Shindigger.$B$BAnd what a gryphon jockey he was! Well until...',12340),
	 (1451,33,14,33,5,0,0,0,0,'Hiccup!$B$BI''m a-lookin'' right at you but you keep bobbing up and down. Makin'' me dizzy. Hoho!$B$BHiccup!$B$BWhoa! Did ya feel that? Ground is a-shakin'', my friend. I need a drink.$B$BHiccup!',12340),
	 (1452,1,33,0,0,0,0,0,0,'I see ya had no trouble at all getting me what I need! Musta been quite a stint you had over there in far-off Kalimdor.$B$BIt won''t take but a moment for me to extract what I need from these gizzards and livers. Hiccup!$B$BThen I can distill me a fierce ol'' drink and finally tell ya what ya wanna know.$B$BHiccup!$B$BGetting shivers just thinking about that ol'' swamp.$B$BHiccup!$B$BLemme whip up a drink real fast.',12340),
	 (1453,2,0,0,0,0,0,0,0,'Glad to see the Reclaimers aren''t in short supply of work, or adventurers willing to help out.$B$BI''m Kreldig, $N. You''ve made a smart move helpin'' out the Reclaimers. Everyone needs something these days: they''ve lost a family heirloom, a magic item, a loved one. You never can tell. But with the Reclaimers around, there''s no reason, for the right price, everyone can''t find what they''ve lost. ',12340),
	 (1454,0,0,0,0,0,0,0,0,'You notice the chest does not seem to have any water damage.$B$BThe second thing you notice is that the top has been forced open, and whatever magical traps were set to safeguard it have long been triggered--this much is obvious from the burn marks around its edges.',12340),
	 (1455,1,6,0,0,0,0,0,0,'Welcome back to Nijel''s Point, $N. So, tell me what you found.$B$BWhat!? Nothing? An empty chest ain''t gonna get us paid, I''m afraid.$B$BTell me more about these marks you saw... these slashes.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (1456,4,1,0,0,0,0,0,0,'This is great, $N! You found Karnitol''s belongings!$B$BThose blasted naga, always causing trouble. I think I''d rather spend my life at war with the Horde than have to go against their kind. You''ve done a great service to the Reclaimers.',12340),
	 (1457,1,6,1,0,0,0,0,0,'Ah, the Karnitol business in Desolace. Excellent!$B$BSo, the chest was destroyed, but the items are all here, huh? Well, I''ll let him be the judge of that. One good part about this business I got going on here is that if they''re not satisfied, I can tell ''em to shove it! They''re relyin'' on us to find their stuff... not make sure it''s all pretty and in good shape when they get it back.$B$BGood work, $N. Let''s see about gettin'' you paid.',12340),
	 (1458,1,1,0,0,0,0,0,0,'Good good, $N. Not sure if these are of any good quality, but if Leftwitch wanted a specific type, he should have specified before sending the Reclaimers out here to begin with.$B$BWhat say you to getting on with the next item on his list?',12340),
	 (1459,1,1,0,0,0,0,0,0,'Your help here''s a boon, $N. You''re cutting my time spent here in Desolace by half at least. I''ll be back in Ironforge warming my feet in no time with your help.$B$BWhen we get this list taken care of, and I''m back home, look me up, I''ll buy you an ale for sure.$B$BBut until then, let''s get the rest of these reagents gathered.',12340),
	 (1464,0,0,0,0,0,0,0,0,'May fire burn within your heart, $N.$B$BThe elements await you.',12340),
	 (1465,5,1,6,1,0,0,0,0,'Infuriating! This entire fiasco!$B$BThe two of them were warned about how dangerous coming here would be. Now they''re both missing... or worse.$B$BYou said you saw tracks heading to a fort nearby? That may be our best bet.$B$BFrom what the locals have said, that fortress is infested with members of the Burning Blade--orcs who have dedicated themselves to demon causes. They may not represent the majority of the Horde''s beliefs, but they are evil and will slay you on sight if you''re caught spying.',12340),
	 (1466,1,1,0,0,0,0,0,0,'Honestly? I wouldn''t have thought it. You''re amazing, $N. Taking on demons for a mage''s experiments, and coming back in one piece to boot. Great job!$B$BI''m personally gonna tell Roetten about you when I get back to Ironforge.',12340),
	 (1467,1,1,0,0,0,0,0,0,'Ah, the package for Leftwitch from Desolace. Excellent. I ''preciate the work, and your timeliness, $C. Glad to have you aboard for at least this small bit of work.$B$BI got your payment right here. Let it be known that Reclaimers Inc. always pays well for a hard week''s work.',12340),
	 (1468,0,0,0,0,0,0,0,0,'Um... hi. My name is Randis and I guess you''re looking after me? You''re an adventurer, like my mom and dad were. I''m happy to meet you.$B$BI hope we''ll have a lot of fun together. I have some things I''d like to do and the matron says you''ll be like a big $gbrother:sister; to me during this week. I''d like that a whole bunch, yes $gsir:lady;.',12340),
	 (1469,5,1,1,0,0,0,0,0,'Rhapsody Shindigger! That''s right... how could I forget such a name?$B$BSo he knew about the sinking of the temple all along? Well, that certainly would have saved you some leg work.$B$BBut this Atal''ai artifact! Why, it''s quite a find!',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (1470,0,0,0,0,0,0,0,0,'Though you are still untested and young in your learning, you have proven that you possess sufficient ability to master the summoning and binding of an imp. Do not be deceived by an imp''s size. Though it lacks physical strength, it possesses powers and a cleverness that will serve you well.$b$bAttend me carefully, $N, for I will not repeat this lesson, and I will leave its mastery to you.',12340),
	 (1471,0,0,0,0,0,0,0,0,'You have done well, $N. Now, I will impart to you the spell used for summoning the voidwalker.$B$BThe power that it unleashed upon you is now yours to command. Use it wisely.',12340),
	 (1472,0,0,0,0,0,0,0,0,'You were sent by Carendin? Sithel, then.$b$bDo not think light of me because my sight is gone. I see things that lie behind now, with clarity I had never known. What I once thought a curse, is now a boon.',12340),
	 (1473,0,0,0,0,0,0,0,0,'Ah, this is excellent. Like as not, Perrine was ignorant to the true power of the musty book he had stolen from us.$B$BIt will not fall out of our hands again. Observe, $N, the structure of the spell, the manner in which your power must be channeled.',12340),
	 (1474,0,0,0,0,0,0,0,0,'Again, you have done well, $N. It has been quite some time since I have seen a young $c with as much potential as you. Be assured that I will continue to watch your progress, and prepare and assist you in your future trials.$B$BFor now, let me show you the summoning spell for your newly dominated succubus.',12340),
	 (1475,4,1,2,0,0,0,0,0,'The Atal''ai Tablets! Thank you, $N!$B$BOnce I deliver these to the Explorers'' League our names shall go down in history together. You have helped an old dwarf fulfill his final obligation in life. For that I am eternally grateful.',12340),
	 (1476,0,0,0,0,0,0,0,0,'The heart of a goodly man seems much the same as any, when you see it like this, don''t you think?$B$BPerhaps we possess something of a... different... view on the subject. These will do, though. I have no doubt that a succubus would be attracted by their purity.',12340),
	 (1477,6,0,0,0,0,0,0,0,'Andromath sent you? Very good. I have an important task for you...',12340),
	 (1478,1,0,0,0,0,0,0,0,'Good, I see Ageron managed to find you, $n. Let us waste little time with small talk and pleasantries and focus on your training. There is still much you have to learn.',12340),
	 (1479,1,1,0,0,0,0,0,0,'Wow, it was cooler than I even imagined - the Bough of the Eternals! I didn''t think it''d be so big, but it was! Did you see the bird on top of it too?! I wonder how they got the branches to look like that!$B$BThanks for taking me to Darnassus, $N. You''re awesome!',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (1480,1,0,0,0,0,0,0,0,'Hmm, these runes are indeed a language, $N, an old language. They seem remotely similar to the Eredun language, but the differences are drastic. If I am not mistaken, this is a contract of some kind.... Here, yes, this symbol is the demon''s signature: Lord Azrethoc.',12340),
	 (1481,1,0,0,0,0,0,0,0,'The shadowstalkers were unable to slay you, $c. Impressive... most impressive.$B$BThis scalp will do nicely for my spell. While you were away, I was able to gather some of the other reagents needed for the spell.$B$BI am almost ready. I only need a focus for the spell--something to project an image of the demon lord and his whereabouts.',12340),
	 (1482,1,0,0,0,0,0,0,0,'A precious oracle crystal... flawless... beautiful. Indeed.$B$BWe shall begin immediately. Finding this demon lord should be our primary concern, and its slaying demands our utmost attention.$B$BTake a step back, $c, and let us see what this demon is, and where he may be found.',12340),
	 (1483,0,0,0,0,0,0,0,0,'I thought those Venture Company higher-ups were slave drivers, but then I met Sputtervalve, the cruelest of them all!$b$bHa! Though it''s better than being out of a job, I suppose... Or worse, working with that Gerenzo. If you''re here to help, I''ve got something for you to do.',12340),
	 (1484,1,0,0,0,0,0,0,0,'I witnessed what just occurred with Maurin and the demon lord. That creature, even as an apparition, seems to have more power than my warlock companion. I wonder if he''s up to the task of defeating the monster? It would serve the Warchief better if I go myself, but with my responsibilities here, I would disgrace my clan if I turned my back on my duties here to battle this evil for my own honor.',12340),
	 (1485,0,0,0,0,0,0,0,0,'Throughout your training as a $C, you will learn to call forth beings of many sorts. Some may not seem it, but all are useful tools.$B$BDo not be fooled by the imp''s small size. As you no doubt noticed, it is still a formidable adversary.',12340),
	 (1486,2,0,0,0,0,0,0,0,'Your efforts shall not go unnoticed in gathering these hides, $N.$b$bThank you for your dedication.',12340),
	 (1487,1,2,0,0,0,0,0,0,'As a Disciple of Naralex, I commend your bravery, $N.$b$bYour aid in ridding the caverns is the first step in our long plight to see the Barrens restored.$b$bThank you and may you prosper.',12340),
	 (1488,4,1,0,0,0,0,0,0,'A mighty victory for us all, $N. Let us rejoice in your success. I trust now that our future here is not as bleak as I once thought.$B$BThe demons will be slain, the Burning Blade will fail in their efforts, and we may one day have a place we can safely call home again.',12340),
	 (1489,1,0,0,0,0,0,0,0,'I bid you greetings, $N. You are welcome here, and I suggest you gather all your strength. For the task we now set before you ... is a dire one.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (1490,1,5,0,0,0,0,0,0,'Yes, it is true. I know of the druids in the Wailing Caverns. I have seen their twisted, scaled faces. I know their crimes, and I know their plans.$b$bYou must stop them, $N.',12340),
	 (1491,4,0,0,0,0,0,0,0,'Great, you got it! I can''t wait to try it out. This is going to make me a fortune, I just know it!$B$BThank you, $N. Take this, and after I''m rich I''ll send you more, I promise!',12340),
	 (1492,1,0,0,0,0,0,0,0,'A small enough crate. Yes, I should be able to find room for this aboard the ship. It sails with the next tide, I trust this is soon enough? Excellent. Let me just enter it into my ledger.$B$BAll taken care of! Good day to you, $C.',12340),
	 (1498,0,0,0,0,0,0,0,0,'Ah. I see you have defeated the thunder lizards, which proves you are tough. Now I will show you how tough skin and shrewd movements can combine to form an impenetrable wall of defense.$b$bLearn your lesson well, $N. And be ready for future instruction.',12340),
	 (1499,0,0,0,0,0,0,0,0,'You have done well, $n.$b$bAlthough the vile familiars were merely pets of the darker powers within the Burning Blade, your success against them foretells greater deeds ahead.',12340),
	 (1501,0,0,0,0,0,0,0,0,'Good. I hope you inflicted some other losses on the Burning Blade when you went to retrieve this.$B$BThey have been a source of great annoyance for the Warchief, and a great blight upon warlocks as a whole.',12340),
	 (1502,0,0,0,0,0,0,0,0,'My eyes have long dried out from staring into the forge''s flame, but some things I can still see. I can see you want something.$b$bAnd if you found your way here, then I can guess what you desire.',12340),
	 (1503,0,0,0,0,0,0,0,0,'You found them! And all the bars are here, which doesn''t surprise me. I didn''t think the Razormanes would know what to do with fine steel like this.$b$bThank you, $N. Here is your reward. May it serve you well.',12340),
	 (1504,0,0,0,0,0,0,0,0,'You have done well, $N. I will show you how to summon the voidwalker similar to the one you just defeated.$B$BYou should know that we have high expectations for you, and you have, so far, matched them.$B$BDo not let it go to your head, however, as the tasks that still lie before you will make this seem as simple as waking in the morning.',12340),
	 (1505,0,0,0,0,0,0,0,0,'Hello, young one. Here for some instruction, are you?',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (1506,0,0,0,0,0,0,0,0,'Good. I was afraid Ophek wouldn''t reach you.$B$BIt is time that I further your warlock training. Any business you have currently will have to wait.$B$BI trust there will not be a problem with this?',12340),
	 (1507,0,0,0,0,0,0,0,0,'Hm... Zarm. You are still new to your path, but I sense the possibility for greatness in you.$B$BYou were born with gifts, $N. See that they do not go to waste.',12340),
	 (1508,0,0,0,0,0,0,0,0,'Have you come with news of Dogran? He was to have returned days ago, and I have heard nothing...',12340),
	 (1509,0,0,0,0,0,0,0,0,'Zankaja? That''s Dogran''s mate, right?$B$BYeah, I''ve heard from him, but it''s not the sort of news we should let get back to her...$B$BNo, he''s not dead. But he is injured and a prisoner of the quilboar.',12340),
	 (1510,0,0,0,0,0,0,0,0,'Another $R, eh? I hope you haven''t come for the other. He didn''t make it. Those goblins did him in good.$B$BHe said he needed a healing draught, but not much else.',12340),
	 (1511,0,0,0,0,0,0,0,0,'Well, it''s about time! Dogran has been dying out there, waiting for this.$B$BWe need to get this out to him right away, but most of the grunts stationed here are out on a foraging mission.',12340),
	 (1512,0,0,0,0,0,0,0,0,'If you tell me that this will suffice, then I trust you, $N. Allow me to clean it though... Pristine and shining, it may be even more enticing to a succubus.',12340),
	 (1513,0,0,0,0,0,0,0,0,'Success! Be sure I expected nothing less from my star pupil.$B$BYou have proven your worth, and gladly will I show you the method of summoning your subdued succubus. Go now, you have much to learn, and when next I see you, I will expect you to have found true mastery over your succubus.$B$BLeave the sorrow of Dogran and Zankaja to those of us who are longer in years, but remember it, and hold it as protection against the wiles of the dark power you have learned to summon today.',12340),
	 (1514,0,0,0,0,0,0,0,0,'You apply two Cenarion plant salves to the windblossom. It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant.',12340),
	 (1515,0,0,0,0,0,0,0,0,'Foul tasting brew...$B$BI can feel the strength in me now, enough to hobble away... But my leg, I will have lost it for the rest of my life. My arm, too.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (1516,1,1,0,0,0,0,0,0,'Excellent. Your success shows that you are prepared.$B$BOf all the elements, earth represents the foundation of all things. It is your strength, your stamina, and your patience. Earth will protect you, but only if shown the proper respect. Like the other elements, even earth can be fickle. Earth is the basis for life, and by observing its laws, you will gain greater wisdom. Never forget the secrets earth shares with you.$B$BI shall make a sapta for you now, and by accepting it, you will realize your path.',12340),
	 (1517,0,0,0,0,0,0,0,0,'Ah... $N... pleased is the earth to have you here.$B$BBound together in body and spirit, you will go forward knowing that the mountains are your strength; the plains, your patience; and the world itself your essence.$B$BStanding before the earth humbly is all that is required of you for you to pass this rite. But the others are not as passive. They may be chaotic and often violent, but such is the nature of the elements. Dual natures opposing one another, you must come to learn these things intricately.',12340),
	 (1518,1,1,0,0,0,0,0,0,'Excellent!$B$BThe totem I will craft for you is more than a symbol of your status among $C--it has abilities beyond that. One use of the totem is as a focus for spells. Those spells are tied to the earth, and as you earn greater and greater wisdom, more of the earth''s abilities will be made accessible to you.$B$BThe trainers will know when you are ready for greater knowledge.$B$BBut for now, take this earth totem, and a scroll to teach you your first ability.',12340),
	 (1519,0,0,0,0,0,0,0,0,'Good, $N. Your return here signifies that you are indeed prepared for the next step.$B$BOf all the elements, earth represents the foundation of all things. It is your strength, your stamina, and your patience. The Earth Mother will protect you, but only if you show her proper respect. She is the basis for life, and by observing her laws, you will gain a greater wisdom. Never forget the secrets she shares with you.$B$BI shall make your sapta for you now, and by accepting it, a new path will open before you.',12340),
	 (1520,0,0,0,0,0,0,0,0,'Ah... $N... pleased is the earth to have you here.$B$BBound together in body and spirit, you will go forward knowing that the mountains are your strength; the plains, your patience; and the world itself your essence.$B$BStanding before the earth humbly is all that is required of you for you to pass this rite. But the others are not as passive. They may be chaotic and often violent, but such is the nature of the elements. Dual natures opposing one another, you must come to learn these things intricately.',12340),
	 (1521,0,0,0,0,0,0,0,0,'Splendid.$B$BThe totem I will craft for you is more than a symbol--it has abilities beyond that. One use of the totem is a focus for spells. Those spells are tied to the earth, and as you earn greater and greater wisdom, more of the earth''s abilities will be made accessible to you. Trainers found throughout Kalimdor will know when you are ready for greater knowledge and will let you know as much when you visit them.$B$BBut for now, take this earth totem, and a scroll to teach you your first ability.',12340),
	 (1522,0,0,0,0,0,0,0,0,'Hmmm, Searn sent you to me, did he?$B$BWell then, Searn could always be trusted, so that must mean you''re ready to take part of the next sapta--the sapta of fire.$B$BI see it in your eyes already, the burning, the desire. You''ve tasted power, and now you''re ready for more of it. Patience, $N. Remember what earth taught you. Power and destruction will come easily, but you must still know when to stay your hand.',12340),
	 (1523,0,0,0,0,0,0,0,0,'Hmmm, Narm sent you to me, did he?$B$BWell then, Narm could always be trusted, so that must mean you''re ready to take part of the next sapta--the sapta of fire.$B$BI see it in your eyes already, the burning, the desire. You''ve tasted power, and now you''re ready for more of it. Patience, $N. Remember what earth taught you. Power and destruction will come easily, but you must still know when to stay your hand.',12340),
	 (1524,0,0,0,0,0,0,0,0,'Ah, my mistake, $N. I apologize. I did not realize you possessed the Torch. I am pleased to make your acquaintance.$B$BMany adventurers find their way here while looking for lost treasure or the promise of mystical creatures to slay, only to be turned away from a seemingly empty shrine. But we know the truth, do we not, $N?$B$BThis shrine holds a greater secret from the mundane members of the Horde. To us, it is sacred.',12340),
	 (1525,0,0,0,0,0,0,0,0,'These will do nicely, $N.$B$BFire is more than chaos and destruction--do well to remember that. It is also about life, and creation. All things are tied together in such a way. Forces oppose one another, but at the same time, one cannot exist without the other. Both extinguish one another, but also give one another meaning. Always remember this.$B$BUsing different types of magic in conjunction with one another will show not only true skill, but great wisdom.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (1526,0,0,0,0,0,0,0,0,'A white hot flame ignites within the bowl as you place the ember within. You can feel the magical effects of the sapta coursing through your body and the fire dances rhythmically before you.$B$BYou place the top of the torch within the basin, and it immediately catches on fire.',12340),
	 (1527,0,0,0,0,0,0,0,0,'Your spirit burns brighter than any torch I''ve ever seen, $N, and for that, you should be proud.$B$BIf you continue down this path, the elements will be yours to command, and our brethren will look to you for guidance and wisdom. Let me be the first to congratulate you and present to you your newest totem.',12340),
	 (1528,0,0,0,0,0,0,0,0,'The wind approaches you quickly from the horizon; the earth is steady beneath your feet; and your spirit is already warmed by fire--I would say it is time for you to learn about the purity of water.$B$BYour path has led you this far, and your spirit will give you the strength to carry on even further. But the first step is yours to take.',12340),
	 (1529,0,0,0,0,0,0,0,0,'The wind approaches you quickly from the horizon; the earth is steady beneath your feet; and your spirit is already warmed by fire--I would say it is time for you to learn about the purity of water.$B$BYour path has led you this far, and your spirit will give you the strength to carry on even further. But the first step is yours to take.',12340),
	 (1530,0,0,0,0,0,0,0,0,'Yes?$B$BMmm. I have a feeling I know what you''re going to ask me: what would possess someone to live out here in the deepest part of the Barrens, the threat of quilboar all around, and no protection? Well, we all have our reasons to justify why we act the way we do. The real question is, what brings a lowly $R to the deepest reaches of the Barrens to speak to a woman who obviously has no concern for her own well-being?$B$BI''m willing to bet we both know the answer to that.',12340),
	 (1531,0,0,0,0,0,0,0,0,'For the time being. I shall give you what you need to focus your spells and to call upon the spirits of air. Take this totem, and when you are ready, train with me some more.',12340),
	 (1532,0,0,0,0,0,0,0,0,'For the time being, I shall give you what you need to focus your spells and to call upon the spirits of air. Take this totem, and when you are ready, train with me some more.',12340),
	 (1534,0,0,0,0,0,0,0,0,'Wonderful, $N. With all three samples gathered, I can create for you a vial of the purest water any living creature will find. It will be used in the next steps of your rite of passage.$B$BI am pleased to count you among our kind, $N. You do all $C proud, and I look forward to hearing about your exploits in the future.',12340),
	 (1535,0,0,0,0,0,0,0,0,'I thought some bloodshed might ensue if you tried to take water from the pool. It is a pity the quilboar do not realize that all living things are tied together; that their greed only perpetuates the pain and suffering of their people. How much could they accomplish if they were to put their differences aside and their clans came together.$B$BAgain, a pity, but more than likely a boon for the other races of the Barrens.',12340),
	 (1536,0,0,0,0,0,0,0,0,'This is good, $N. You''re dedicated to the task at hand and have the ability to seek out that which is needed.$B$BOne more sample is all I need to create the reagent needed for your sapta. Islen will be pleased as well.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (1558,1,1,0,0,0,0,0,0,'WOW - the dam was WAY bigger than I thought! I could barely hear myself talk from the sound of all the rushing water! Hey, do you think it would ever run out of water? Man, what would happen if that damn ever broke! WOW, that would be scary!$B$BThanks for taking me to see the dam. That was very kind of you. I told you I wouldn''t lean over too far!',12340),
	 (1559,0,0,0,0,0,0,0,0,'So you''re an engineer, eh? Well, for your help in getting me those pearls, here''s the recipe for flash bombs.$b$bGood luck, and try not to blind yourself!',12340),
	 (1560,0,0,0,0,0,0,0,0,'So he couldn''t find his way back on his own? Figures.$B$BWell, I guess you deserve something for your troubles....',12340),
	 (1578,2,1,0,0,0,0,0,0,'Ah, apologies! I didn''t realize you were here to help resupply our troops. The stuff you made will be a big help!$B$BHere are plans for some armor. I hope you find them useful.',12340),
	 (1579,5,0,0,0,0,0,0,0,'I can''t believe you found them! You must be the luckiest $R in Kalimdor!',12340),
	 (1580,4,0,0,0,0,0,0,0,'I can''t believe it! You found them! You are the best fisherman I''ve ever seen!$b$bThank you, $N. And here, take these. Although you''re so good and you probably don''t need them, they will help you with your fishing.',12340),
	 (1581,0,0,0,0,0,0,0,0,'These are nicely mixed. You take great care in your trade, $N, and that is important for an alchemist.$b$bHere are your herbs, freshly gathered. May you use them well.',12340),
	 (1582,1,0,0,0,0,0,0,0,'Yes, these are good pieces. You have a skilled hand and an eye for detail. Your future as a leatherworker is promising.$B$BHere, $N. Let me show you the pattern to make the Moonglow Vest.',12340),
	 (1598,0,0,0,0,0,0,0,0,'Excellent... I was never able to gain access to this text, it was held in a protected wing of the library that would have looked suspicious for me to be loitering around.$B$BWell, you did a good job in getting this, and I''m convinced that you can probably handle your own imp, so there''s no reason for me not to show you how to summon one.',12340),
	 (1599,1,1,11,0,0,0,0,0,'Very good, very good! You''ve done well, $N. Perhaps the interest that is being shown in you is deserved, after all.$B$BThat''ll be for the others to decide--assuming your imp doesn''t overpower you and nip your career in the bud. For now, I''m satisfied that you''ll probably survive your first few months as a $c.$B$BA word about the imp, $N. As a $R knows, don''t let its size fool you, its magic can be very dangerous.',0);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (1618,2,1,0,0,0,0,0,0,'Thank you, $N. This will help me out tremendously. With the Blackrock orcs attacking from Stonewatch Keep and the Redridge gnolls lurking in the foothills to the north, I''m always fixing armor and making new weapons for our troops.$B$BThe supplies you brought will give me a moment''s peace. I will have enough time to teach you something...',12340),
	 (1638,1,6,0,0,0,0,0,0,'Oh ho! Have a drink with me, $N. You look tough on the outside, but let''s see if your gut can handle a few mugs of the Pig and Whistle''s strongest!!$B$BOr... were you here for a lesson?',12340),
	 (1639,3,6,0,0,0,0,0,0,'Hello, fancy $gboy:girl;! What''s a prissy thing like you doing in the Pig and Whistle? Be careful, or you might break a nail...',12340),
	 (1640,5,0,0,0,0,0,0,0,'You''re a lot tougher than you look!',12340),
	 (1641,2,1,1,0,0,0,0,0,'Here in Stormwind, I am responsible for putting paladins on the path to greater virtue as they devote themselves to the Light and defend Azeroth from the Scourge and other threats.$B$BThe time has come for you to take your first step towards being truly virtuous. If you accept it, I will give you a Book of Divinity. In studying it, you shall learn some about the Light, and what is expected of you. If you understand it, and are capable, then you will succeed in attaining greater abilities.',12340),
	 (1642,2,6,1,1,0,0,0,0,'Hello again, $N. How goes your studies of the Tome of Divinity?$B$BThen you should be prepared to have yourself tested. There are always tasks to be done throughout the city and our lands; acts of compassion and understanding; people who need help; creatures to slay.$B$BBy proving you have the patience to help others, especially those who are less fortunate, you prove that you are a servant of the Light and of sound mind.',12340),
	 (1643,1,1,1,0,0,0,0,0,'Oh, hello, luv. How go your adventures? Oh, I''m so glad to hear you''re doing well.$B$BOh, me? Thank you for asking--I''m doing well, all things considered.$B$BThe increase in tradesmen has kind of put a damper on the amount of leather and cloth people are willing to part with these days, so it''s been tougher to make clothing for the children at the orphanage, but we''ll manage. By "we" I mean my husband and I. He''s up in Ironforge trying to seek help from the citizens there.',12340),
	 (1644,21,1,1,2,0,0,0,0,'Thank you, $N, thank you so much!$B$BThe children will be so pleased, and you''ve saved me so much time. I''ll now be able to focus on the children''s other needs, and hopefully my John will be able to return home sooner than we thought.$B$BThank you again, $N. I knew I could rely on the charity of others. The Light be with you.',12340),
	 (1645,2,6,1,1,0,0,0,0,'Here in Ironforge, I am responsible for putting paladins on the path to greater virtue as they devote themselves to the Light and defend Azeroth from the Scourge and other threats.$B$BThe time has come for you to take your first step towards being truly virtuous. If you accept it, I will give you a Book of Divinity. In studying it, you shall learn some about the Light, and what is expected of you. If you understand it, and are capable, then you will succeed in attaining greater abilities.',12340),
	 (1646,0,0,0,0,0,0,0,0,'Welcome back, $N. You''ve spent time reading the book, I hope?$B$BThen you should be prepared to have yourself tested. There are always tasks to be done throughout the city and our lands; acts of compassion and understanding; people who need help; creatures to slay.$B$BBy proving you have the patience to help others, especially those who are less fortunate, you prove that you are a servant of the Light and of sound mind.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (1647,5,2,1,0,0,0,0,0,'THE ORPHANAGE OF STOR... oh, sorry, didn''t mean to shout at you, sir.$B$BMy name is John Turner. How are you?$B$BGood, good, glad to hear things go well for you. I''ve had a long day of work already, and I miss my wife terribly, but that''s the price you have to pay when there are mouths to feed and backs to clothe.',12340),
	 (1648,21,1,1,2,0,0,0,0,'This is so wonderful of you, $N. Thank you again.$B$BYou''re a noble man for doing this for me. It''s no wonder you''ve chosen to follow the Light. I wish there was some way I could repay you for all you''ve done... what''s that? It''s the least you could do? See? That''s what I''m talking about, $N, noble to the end.$B$BBe safe, and may the Light protect you in your travels.',12340),
	 (1649,2,1,1,6,0,0,0,0,'Ah, you wish to petition me for a test of valor. Splendid.$B$BThere are many tasks throughout the city and surrounding lands that hold much challenge, and they could use a man with your skills.$B$BThis test should not be taken lightly, $N. This, like many things along our path, could take our lives. The Church always wishes to bolster its ranks, but it understands the sacrifices needed to ensure the paladins serving it are worthy.$B$BAre you prepared?',12340),
	 (1650,2,1,1,24,0,0,0,0,'Hello, $N. I''m assuming by all that armor and weapon of yours, you''re either here to try and take my land, or the Church finally sent someone to help protect me while my Jordan''s gone.$B$B Well, let me introduce myself: I''m Daphne Stilwell. It''s a pleasure.$B$BNow, you''re not too late... I''ve only killed a half dozen of the scum since last sun up. They''ve been a little slow getting ''round the bend up there, but they probably saw you coming, which means they''ll probably be here any minute.',12340),
	 (1651,4,1,1,0,0,0,0,0,'We''ve done it, $N! Thank you for your help. You were truly amazing out there. I never thought a $C could handle so many enemies at once.$B$BYou''ve truly shown bravery in the face of overwhelming odds.',12340),
	 (1652,1,4,1,0,0,0,0,0,'So, we meet again, $N, and you are in high spirits, I see.$B$BThe Stilwell home will be safe for another day, and from your story I see that there was no shortage of danger to be found. Well done.$B$BDaphne and Jordan have helped the Church greatly, and having you protect their property--and their very lives--was the least we could do for them.$B$BFor your valor, you will be rewarded.',12340),
	 (1653,2,1,1,6,0,0,0,0,'Good day, $n. The Light is with you, I trust?$b$bWhat''s that? You were sent by Duthorian!? My wife, how is she? I knew there was going to be trouble if I left. Please tell me she''s... oh, thank goodness. I''m so glad that she''s safe. The Defias were a threat long before these attacks, but now the King''s advisors cannot deny it.$b$bWhat else did Duthorian have to say?$b$bYou''re the one that was sent to protect my wife? Then I thank you again, $n. I couldn''t think of a better test of valor than that.',12340),
	 (1654,4,1,1,0,0,0,0,0,'This is wonderful! You''ve gotten all the items.$B$BI should have no problem forging you a grand weapon with these. I''ve actually had the plans for doing this for some time. I just never had the opportunity to gather the goods. Thank you, $N.$B$BIt feels good to have my father''s hammer again...and a Kor gem. I never thought I''d see one of these myself.',12340),
	 (1655,273,1,1,0,0,0,0,0,'Yup yup, this is it. Ha! If I''d known you were really gonna head out there and fight some o'' them ogres, I woulda given you a list of things to get instead of just this one thing. But, you''re not here doin'' business for me, are ya?.$B$BA deal''s a deal; Jordan wanted a shipment of me alloy, that''s what he''s gonna get.$B$BTell ''em hello fer me, and be safe, $C.',12340),
	 (1656,1,1,1,0,0,0,0,0,'Ah, the furs I was expecting. Thank you.$B$BThese came faster than I had expected. They will make good blankets for anyone who wishes to stay here.$B$BPlease feel free to stay as long as you like. My inn is always open and all of our people are welcome here. And don''t underestimate a good night''s rest, it can make a great difference while you''re out traveling.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (1661,0,0,0,0,0,0,0,0,'Congratulations, and may the Light protect you.',0),
	 (1665,273,1,0,0,0,0,0,0,'There it is! He sure didn''t want to part with it, but you were persuasive. Well done.$B$BNow for your lesson...',12340),
	 (1666,6,1,5,0,0,0,0,0,'Who''s that?$B$BBurlguard, is that you?$B$BYou''ll have to step a little closer. My eyes aren''t what they used to be.$B$BWalking up like that, I thought you were a gnoll!',12340),
	 (1667,4,1,0,0,0,0,0,0,'Great, you found it! I feared it was gone forever, used by the Defias to impersonate a Stormwind official. Well that won''t happen now, thanks to you.$B$BHere are some weapons I used when I was a Marshal. I kept them in great shape--take your pick!',12340),
	 (1678,0,0,0,0,0,0,0,0,'Vejrek sure was an ugly one, eh? Nicely done, $N! You have what it takes, now let''s start your lesson...$b$bYou may not know it, but a strong defense is very important to a $C. It keeps him standing against foes that''d fell others, and that''s what your allies need.',12340),
	 (1679,0,0,0,0,0,0,0,0,'Ah, $N. I heard the warriors of Dun Morogh bouncing your name around. I hope you haven''t spent all your time in the breweries!',12340),
	 (1680,0,0,0,0,0,0,0,0,'Muren sent you, did he? Yes, I can make you a nice weapon... but before I do that, I have a favor to ask of you.$b$bDon''t worry. It''s plenty dangerous and could mean your death; it''s exactly the sort of job a $C wants.',12340),
	 (1681,0,0,0,0,0,0,0,0,'You found it! Well done!$b$bI hope you killed a host of Dark Iron dwarves while searching. I fear that Ironband''s compound won''t be the last place we see them.$b$bBut thank you for the ore, $N. I''m eager to work it and find its properties.',12340),
	 (1682,0,0,0,0,0,0,0,0,'Here are some weapons, hot off the anvil and made with the new umbral ore you brought me!$B$BPlease, $N, take your pick!',12340),
	 (1683,0,0,0,0,0,0,0,0,'Well done, $N. It is good to know Vorlus is defeated and our moonwell cleansed, and it is good to see young warriors eager to keep our beloved Teldrassil free of corruption.$B$BNow let us begin your training...',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (1684,0,0,0,0,0,0,0,0,'I bid you greetings, $N. Your name rings loudly in Darnassus, for you show promise. But we shall soon see if you possess the strength of will to follow the path of the $C.',12340),
	 (1685,1,1,0,0,0,0,0,0,'About time you showed up. Though, perhaps I should have sent someone more capable than Remen to find you.$B$BNo matter.$B$BYou''ve gone too long without training, and a warlock without training isn''t like to keep his head on his shoulders for long.',12340),
	 (1686,0,0,0,0,0,0,0,0,'Bravely done, $N.$B$BYou have given the Shade of Elura much deserved peace, and we will use the gathered elunite to make a fine weapon for you.',12340),
	 (1687,2,1,0,0,0,0,0,0,'WOW, that was a real life ghost! That was so awesome - I can''t wait to tell everyone back at the orphanage. Captain Grayson... he even looked like a pirate! When I grow up I wanna be a ghost pirate too!$B$BThanks for taking me to Westfall, $N. I know there are scary things out there in the wilds of Westfall, and I hope I wasn''t too much of a pain. You''re awesome!',12340),
	 (1688,1,1,0,0,0,0,0,0,'Surena was talented, but not enough so to gain mastery of $C magic on her own. It''s a shame to see talent wasted, but sometimes it is necessary.$B$BI hope my investment in you will bear different results.',12340),
	 (1689,1,1,0,0,0,0,0,0,'You did better than I expected, $N, but as well as I''d hoped. Now, you can learn to command your subjugated voidwalker, an ally you will find valuable in the trials that are sure to stand before you.$B$BI have nothing more to teach you at the present, but I am far from done with you, $N.',12340),
	 (1690,4,0,0,0,0,0,0,0,'Now that''s what I call efficiency!  You''ve helped thin out the nomad''s numbers enough now that we can start to think about how we can win back those water wells.$B$BThe Gadgetzan Water Company thanks you for your help, but we''re far from done in dealing with those foul nomads.  Listen close - here''s what we need next...',12340),
	 (1691,66,0,0,0,0,0,0,0,'Top notch work, $N... top notch! You''ve thinned down the nomad population to a point where we can actually take the fight to them!$b$bIf you haven''t already, talk to Spigot Operator Luglunket here; he gives a bounty on any of the Wastewander water pouches you may have run across while bringing those nomads to justice!',12340),
	 (1692,0,0,0,0,0,0,0,0,'Ah, elunite ore. This is a fine metal to work with, for it is blessed by the goddess Elune herself. It would be an honor to craft weapons with it.$B$BPlease wait while I work...',12340),
	 (1693,0,0,0,0,0,0,0,0,'$N, I have crafted these weapons with the elunite you brought to me. Please, take whichever most suits you.$B$BAnd I must thank you. Working with elunite is both an honor and a pleasure.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (1698,6,25,0,0,0,0,0,0,'Hah! So you heard of my challenge, did you?$B$BWell sit down and listen. Have a drink, and savor it... because it might be your last.',12340),
	 (1699,5,0,0,0,0,0,0,0,'You made it! Well done! Three cheers for $N!',12340),
	 (1700,6,5,0,0,0,0,0,0,'Furen wrote this? How dare he! Why, I taught him everything he knows! To think he could teach me something is outrageous! Outrageous!$B$BHm... but there is something in his notes that I''d like to try...',12340),
	 (1701,5,0,0,0,0,0,0,0,'You got it all? Amazing! I was afraid those chimaeras would eat you up for sure!$B$BWell let''s get started on that armor...',12340),
	 (1702,1,273,0,0,0,0,0,0,'Ah, Barleybrew Scalder. Great stuff! So you''ve been to see Yorus, eh?$B$BI can get you a shield, yes sir! You won''t find a better one, and that''s no lying!',12340),
	 (1703,1,2,0,0,0,0,0,0,'These are interesting, very interesting indeed. My dwarven colleague Furen has made quite a grand discovery!$B$BThank you, $N. It will be an honor to apply his new techniques to my own craftings.',12340),
	 (1704,5,0,0,0,0,0,0,0,'Oh my! These notes are amazing! And what''s more... they''re incredible and they''re stupendous and they make my knees go all a-wobbly!$B$BFuren had a breakthrough! A real breakthrough! I can''t wait to try out his new technique!',12340),
	 (1705,1,0,0,0,0,0,0,0,'Nice work! Now if you''ll excuse me, I have some work to do myself...',12340),
	 (1706,5,1,0,0,0,0,0,0,'I can barely believe it! Furen''s technique was a success, and this armor should withstand tremendous levels of stress.$b$bHere you are, $n. And thank you. I wouldn''t have believed Furen''s discovery if you hadn''t gathered the materials I needed to test it myself.',12340),
	 (1707,4,0,0,0,0,0,0,0,'Excellent - the more water pouches we are able to reclaim, the further away from disaster we''ll all be!  Keep ''em coming, and I will be sure to reward you for every five water pouches you bring me.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (1708,273,5,0,0,0,0,0,0,'That''s the stuff! Well done! Now let me get this smelted and hammered so I can apply Furen''s technique with my own and then we can see what happens!$B$BOh my, oh my! I just know the armor will be very very very tough!',12340),
	 (1709,4,5,0,0,0,0,0,0,'Here''s your armor, $N. Furen''s process worked brilliantly! Perfectly! Marvelously, truly!$B$BYou could run this armor over with a siege engine and it would spring right back into shape!',12340),
	 (1710,2,0,0,0,0,0,0,0,'Ah, thank you. These will work splendidly!$B$BI will begin fashioning the armor immediately...',12340),
	 (1711,1,2,0,0,0,0,0,0,'I have finished with your piece of armor, and I am quite pleased. Furen''s new techniques meshed perfectly with my own and I am sure this armor will prove to be quite resilient.$B$BThank you, $N. And may this serve you well in future battles.',12340),
	 (1712,1,0,0,0,0,0,0,0,'You have gathered the items for my spell, and have shown me your strength and cunning. But the next stage of our quest is even more perilous.$b$bLet us hope your strength does not falter.',12340),
	 (1713,4,0,0,0,0,0,0,0,'You did it! You defeated Cyclonian and gained the Whirlwind Heart!',12340),
	 (1714,0,0,0,0,0,0,0,0,'The charms sink slowly into the cauldron''s depths...$B$BA large bubble rises to the surface of the liquid and breaks...$B$B...And a churning lump of molten rock is revealed.',12340),
	 (1715,6,1,0,0,0,0,0,0,'Sent by Blackwrench, were you? Damn warlocks in Ironforge need to get things sorted out. There''s only so much room and so many teachers in Stormwind. With all the increased traffic, we''re sure to attract attention sooner or later.',12340),
	 (1716,0,0,0,0,0,0,0,0,'Was your crossing difficult, $N? You have come a long way to speak with me. But fear not, I know why Gakin has sent you, and he was wise to, for I can help you in your search.',12340),
	 (1717,1,1,0,0,0,0,0,0,'About time you showed up. Though, perhaps I should have sent someone more capable than Remen to find you.$B$BNo matter.$B$BYou''ve gone too long without training, and a warlock without training isn''t like to keep his head on his shoulders for long.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (1718,3,0,0,0,0,0,0,0,'Hello, $N. It''s good to see you made it to Fray Island. I hope you find it to your liking...',12340),
	 (1719,21,0,0,0,0,0,0,0,'Well done, $N. You have passed The Affray!$B$BYou are a worthy warrior, and I am honored to teach you...',12340),
	 (1738,1,1,0,0,0,0,0,0,'Yes, I can tell this will do nicely, let me just work with it for a moment...$B$BTakar is a resourceful fellow to have around, isn''t he? If only I could persuade him to move back to civilization.',12340),
	 (1739,21,0,0,0,0,0,0,0,'Well done, well done, $N. I see we''ve done right in deciding to train you. Your performance certainly does not disappoint.$B$BI''ve no qualms in showing you the way to control your newly bound succubus. Observe carefully.',12340),
	 (1740,0,0,0,0,0,0,0,0,'Yes... The orb was not greatly fragmented, and almost all of the pieces are here. It is a simple thing to recreate them, to make Soran''ruk whole again.$B$BI have dedicated my life to the study of the Burning Legion''s orbs and their recreation. You have done me a favor collecting these pieces to study, and I will give you them back - fully reconstructed - in a form of your choosing.',12340),
	 (1758,0,0,0,0,0,0,0,0,'Tome of Cabal? Hmm...sounds familiar. I have never seen it here before, though--and believe me, I remember every book I read. $B$BHmm... Ah, yes!$B$BI have seen reference to it in library cataloging books.',12340),
	 (1778,6,1,1,0,0,0,0,0,'So, you''ve returned so quickly, huh? And what pray tell have you accomplished in your time away from here?$B$BWere you able to help a noble cause? Perhaps you''ve learned the value of charity or some more about your obligations to the citizens of Azeroth. Tell me, who have you helped and how.... Impressive, $N, those are surely the actions of one who follows the Light.$B$BSuch sacrifice will always be rewarded in time.',12340),
	 (1779,33,2,1,1,0,0,0,0,'*cough*$B$BGood day to ya, $C. Don''t mind me wounds, the good priest ''ere''ll take care of ol'' Muiredon in time. Not needin'' the power of that Symbol of Life ya got there quite yet.$B$BSo, me wife sent ya o''er to speak to me, huh? Fair ''nough. I''ll take the time to talk to ya-I''ll tell ya exactly wut happened to Muiredon and his best friend Narm, a $C jus'' like yerself.',12340),
	 (1780,1,1,1,0,0,0,0,0,'You''ve returned so quickly, $N. And what have you accomplished in your time away from the Cathedral?$B$BHave you helped a noble cause? Perhaps you''ve learned the value of charity or some more about your obligations to the citizens of Azeroth. Tell me, who have you helped and how... Well, I''m impressed, $N, those are surely the actions of one who follows the Light and values others above oneself.$B$BSuch sacrifice will always be rewarded in time.',12340),
	 (1781,33,2,1,1,0,0,0,0,'*cough*$B$BPleasure to meet you, $R. Don''t mind my wounds, the good priest here can take care of ol'' Gazin this time. I won''t be needing the power of that Symbol of Life you''ve got there... not yet anyway.$B$BSo, Duthorian sent you to speak to me, huh? Fair enough. I''ll tell you exactly what befell me and my friend Henze. And with any luck, and some skill on your part, perhaps you can still help us all.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (1782,1,1,0,0,0,0,0,0,'Here''s your armor, $N. This will stand up to the strongest assaults or my name isn''t Furen Longbeard!$B$BAnd I have to thank you. I learned a lot while working with the materials$Byou brought me. I think I''ll have another breakthrough one day!$B$BI''m going to send what I learned to other$Bblacksmiths of the Alliance.$B$BI''ll tell them you were a big help, and maybe they''ll want to return the favor.',12340),
	 (1783,2,1,1,1,0,0,0,0,'I can''t thank you enough, $gbrother:sister;.$B$BI can only assume that Tiza and Muiredon sent you here to aid me if you carry the Symbol of Life.$B$BIt''s true, I fell to the Dark Iron while trying to attain one of the scripts: I was able to hold on long enough to allow Muiredon to escape, but the Light had almost embraced me fully when you came along. The fact that you were powerful enough to use the Symbol means great things for you, but there''s time to speak of that later.',12340),
	 (1784,4,1,0,0,0,0,0,0,'Haha! You''ve done it! Ya saved Narm, and ya found the proof me wife needs to take to the council. Yer a blessin'' o'' the Light if I ever saw one... not includin'' me wife o'' course.$B$BThank ya again, $N.',12340),
	 (1785,1,1,1,2,0,0,0,0,'You''ve done all of Ironforge a great favor today, $N. I''m proud to count you among us, and if you feel you''re ready, I would like to bless you with this scroll. The Symbol of Life would only have worked when used by a $C who was ready for one of the Light''s greatest blessings-the power to restore the dead back to life.$B$BI will teach you the ability to resurrect your companions. Use it wisely, $N, and thank you, on behalf of myself, my husband, and Ironforge.',12340),
	 (1786,2,1,1,1,0,0,0,0,'Thank you, $Gbrother:sister;.$B$BSeeing you wield the Symbol of Life, may I assume Duthorian or Gazin sent you?$B$BI fell to the Defias spell casters while Gazin and I tried to get their plans from them: I was able to hold on long enough to allow Gazin to escape, but in the end, their magics overwhelmed me.$B$BBut you were able to bring me back: the ability to use the Symbol doesn''t come to just anyone, $N. It bodes well for you that you were able to empower it with your own faith.',12340),
	 (1787,4,1,0,0,0,0,0,0,'Wonderful! You made it, and saved Henze. The Light is with you for sure, $N!',12340),
	 (1788,1,1,1,2,0,0,0,0,'You''ve done well this day, $N. You should take some pride in what you''ve accomplished.$B$BEven more so, you should be proud of your abilities. Not everyone can use the power of the Symbol of Life. Calling upon the Light to bring back the dead means you''re prepared for one of the $C''s greatest honors: the power of resurrection.$B$BYou shall have the power to bring back fallen companions much like you did for Henze.$B$BBe well, $N. The Light shines upon you and you should welcome it wholly.',12340),
	 (1789,1,1,0,0,0,0,0,0,'Make haste, $N, more than one life hangs in the balance if you fail.$B$BIf for some reason you fail to help Muiredon and Narm, then return to me and I will give you another Symbol of Life for your travels.$B$BDon''t mistake my aid as simple charity, you must prove yourself worthy like any other $C and continual failure may reflect upon you later.',12340),
	 (1790,1,1,0,0,0,0,0,0,'Make haste, $N, more than one life hangs in the balance if you fail.$B$BIf for some reason you fail to help Gazin and Henze, then return to me and I will give you another Symbol of Life for your travels.$B$BDon''t mistake my aid as simple charity, you must prove yourself worthy like any other $C and continual failure may reflect upon you later.',12340),
	 (1791,6,0,0,0,0,0,0,0,'You have traveled far, young $C. I see fire in your eyes. You seek a weapon of great power, yes?$B$BI can help you with your quest. And you can help me with mine.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (1792,1,0,0,0,0,0,0,0,'I have the whirlwind heart, and am ready to place it within your vessel of choice.$B$BChoose your weapon, $N, and know that its power is the power of Cyclonian.',12340),
	 (1793,1,1,6,1,0,0,0,0,'It has been proven that the Light is with you, $N, but as times grow more dangerous, it becomes important to know what strength lies beneath the flesh. When demons, dragons, or any other evil set foot in your lands, your mettle will be tested. Will you be strong enough?$B$BBravery, regardless of the situation, is as much a part of paladinhood as the Light, your armor, and your weapon. Protecting the weak, and not losing faith are two more lessons you must master while you study in the Cathedral of Light.',12340),
	 (1795,0,0,0,0,0,0,0,0,'I must say I''m impressed, $N. When I faced down my felhunter, I barely escaped with my life. I sense that you have the potential to become one of the most powerful warlocks of this era.',12340),
	 (1796,1,1,0,0,0,0,0,0,'This will do nicely, $N.$B$BAll magical items must begin with an item of high quality. The more effort and skill put into an item, the greater the magics it can hold. Rare and more expensive components hold the magic better. You will not regret having the robes fashioned into the ones we will make for you later on.',12340),
	 (1798,0,0,0,0,0,0,0,0,'$N? Ah, of course. Our latest prodigy. The real thing can not live up to the legend, I am afraid. $B$BNo matter, you have come here to learn, not to hear me make jokes to myself.',12340),
	 (1799,6,1,0,0,0,0,0,0,'Oh, so Menara sent you. Fair enough... I suppose you may stay as my guest for the time being. But you must be on some pressing business - perhaps you''re here seeking lost power? Maybe I''m mistaken. Maybe corruption isn''t too far away from you after all.',12340),
	 (1800,0,0,0,0,0,0,0,0,'That throne room was scary, $N! Even though it was empty, it felt like a great evil had happened there. I felt mad... but I also felt sad too. I understand why the matrons tell us such stories; I will never betray my people like that!$B$BThank you for taking me to the throne room, $N. I learned a lot.',12340),
	 (1801,0,0,0,0,0,0,0,0,'Map making! Pictures, estimations of reality. I have no use for such things.$b$bIn books, narrative, description! That is where truth lies. I would trade all the maps in this store for one book on the rise of necromancy, or a tale of the Dark Lady''s triumph.',12340),
	 (1802,0,0,0,0,0,0,0,0,'Fantastic! Now I may join the ranks of the few that have spied its contents.$B$BI can''t wait to further peruse this text. This is a great day, $N! If you will just allow me to glance at it before you leave. I''m sure that Strahad will be willing to send me a copy.',12340),
	 (1803,0,0,0,0,0,0,0,0,'Well well well! What do we have here?$B$BThis is impressive, $N. I wouldn''t have thought it possible, but here it is in my very hands, the complete Tome of the Cabal.$B$BAllow me to leaf through its pages for just a moment before you are off again.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (1804,0,0,0,0,0,0,0,0,'Well done! The Tome of the Cabal and three pristine--slightly scratched, I suppose--rods of channeling.$B$BThis will be interesting. It''s been some time since a young $C took on a felhunter to make his own.',12340),
	 (1805,0,0,0,0,0,0,0,0,'Well done! The Tome of the Cabal and three pristine--slightly scratched, I suppose--rods of channeling.$B$BThis will be interesting. It''s been some time since a young $C took on a felhunter to make his own.',12340),
	 (1806,1,1,2,0,0,0,0,0,'Here it is, $N. A weapon worthy of a champion of the Light such as yourself. I''ve named it after a great dwarven paladin who was a friend of mine. His name was Verigan... Bosch Verigan.$B$BPlease take it on behalf of myself and my wife. We owe you a great debt, and the world will be a safer place with one of your skill traveling the land.',12340),
	 (1818,0,0,0,0,0,0,0,0,'You''re here for a mission? Good. I have an important one, and one that will test your skill in combat... and your resolve in the defense of the Forsaken.',12340),
	 (1819,0,0,0,0,0,0,0,0,'Well done, $N. Ulag was no minor agent of the Scourge. You have shown the Deathguards, and hence the Dark Lady, that you are a $C of skill and resolve, and are worthy of further instruction.',12340),
	 (1820,0,0,0,0,0,0,0,0,'Yes, it is true. I have need for your skills in combat. My means are small, but my task aids both me and the Forsaken''s cause. Do it, and your reward will be twofold.',12340),
	 (1821,0,0,0,0,0,0,0,0,'Ah! You retrieved them! Now the last semblance of honor and memory is stripped from the cursed Agamand lands. The family truly is no more!',12340),
	 (1822,0,0,0,0,0,0,0,0,'I will keep three of the weapons you returned to me, as mementos of my pain and loss. But please, $N, choose your favorite of the heirlooms and keep it for yourself.$B$BMay it serve you greater than it served its cursed, former owners.',12340),
	 (1823,0,0,0,0,0,0,0,0,'You are here for my trial, $N?',12340),
	 (1824,0,0,0,0,0,0,0,0,'Nicely done, $N! In passing the trial at the Field of Giants, you take one more step down the $C''s path.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (1825,0,0,0,0,0,0,0,0,'Yes, you have come. This is good, for we have much to discuss, you and I.',12340),
	 (1838,0,0,0,0,0,0,0,0,'You brought all that I asked. Now, I will do my part...',12340),
	 (1839,0,0,0,0,0,0,0,0,'Greetings, $N. Old Thun''grim sent word to me of your coming, but had he kept silent your presence here would not have surprised me.$B$BThe spirits follow your progress, young $C, and they tell me that many foes have fallen before you.',12340),
	 (1840,0,0,0,0,0,0,0,0,'Greetings, $C. I am Orm, and Thun''grim tells me you wish a helm made?',12340),
	 (1841,0,0,0,0,0,0,0,0,'You are here for leg armor? Great!$b$bUm... am I making the armor for you, or are you making it for me?$b$bThat was joke. Was it funny? I can''t tell... I lost my sense of humor the same time I lost my sense of smell. Which was about the same time I stopped breathing.',12340),
	 (1842,0,0,0,0,0,0,0,0,'Ah, you have them! Now, just as the Satyrs leeched the strength of Ashenvale, I will leech the power held within these hooves and harness it into my crafting...',12340),
	 (1843,0,0,0,0,0,0,0,0,'Thank you, $N. These gauntlets are my best work. Take them. In wearing them, you bring honor to me and my ancestors.',12340),
	 (1844,0,0,0,0,0,0,0,0,'You have completed your task, $N, and shown me your worth and resolve. The helm will be yours...',12340),
	 (1845,0,0,0,0,0,0,0,0,'I give this helm to you.$B$BGreat deeds brought you to me, $N, and Earthmother willing... even greater deeds lie before you.',12340),
	 (1846,0,0,0,0,0,0,0,0,'Well done! These all look strong. I think they''ll do quite nicely. How did those orcs mind you taking their shins, $N? Complain much?$B$BThat was another joke. You''re not laughing.$B$BI''m not very funny these days, am I...',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (1847,0,0,0,0,0,0,0,0,'Here are your legguards, $N. Let me know how they fit or if you need any modifications. I aim to please! At least I used to.$B$BThese days I don''t care much for my craft. But it beats being a mindless minion of the Scourge!$B$BI guess.',12340),
	 (1848,0,0,0,0,0,0,0,0,'I am sure you endured much hardship and shed much blood on my task, $N. Here is the product of your toil.$B$BMay you wear it well, and may you one day return here with stories of its service to you.',12340),
	 (1858,0,0,0,0,0,0,0,0,'Hmmm, now this is interesting. You''ve more than proved your worth with this, $n. I am quite impressed. Consider yourself the newest member of the Shattered Hand. And take this, it will be a great help to you in the future, I think.',12340),
	 (1859,0,0,0,0,0,0,0,0,'Very good, I''m glad Kaplak was able to get a hold of you.$b$bWe have some things to speak of, not the least of which is your future with the Hand.',12340),
	 (1860,6,1,0,0,0,0,0,0,'You have been sent to aid me in my task, $n?  Good.  It is heartening to see young mages eager to help in our cause...$b$bWhat cause, you ask?  In time, young one.  You shall know... in time.',12340),
	 (1861,2,1,0,0,0,0,0,0,'Thank you, $N. I will test this water for magical properties. Let us hope that it contains none, or we may find that those who drink from Mirror Lake for too long will be adversely affected.$B$BHere, $N. Take this orb or staff as a token of your service. May it serve you well.',12340),
	 (1878,4,0,0,0,0,0,0,0,'Excellent - the more water pouches we are able to reclaim, the further away from disaster we''ll all be! Keep ''em coming, and I will be sure to reward you for every five water pouches you bring me.',12340),
	 (1879,1,1,0,0,0,0,0,0,'Oh, I can see you have promise, yes you do! But it takes more than promise to be a good $c.  And if you''re not a good $c, then you''re a bad $c.  And bad mages are part of the problem, yes they are!$b$bOops, I''m getting ahead of things.  Let''s begin at the start!',12340),
	 (1880,4,1,2,0,0,0,0,0,'Oh, splendid day!  When I made the gizmonitor I never realized how dependent on it I would become.  Now I can begin my studies anew!$b$bThank you, $n!  And here--these were my first tools as a $c.  They''re a little scratched but they''re well tested.  Take your pick--I''m sure you''ll find either of them useful.',12340),
	 (1881,1,0,0,0,0,0,0,0,'Greetings, $n.  You were wise to answer my call, and wiser still if you heed what I next say...',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (1882,0,0,0,0,0,0,0,0,'Ah, a fine specimen this is. I will send it to be studied by our apothecaries to determine the extent of the Plagueland''s taint.$B$BWell done, $N. For your services, I present to you this choice: an orb or staff. Whichever you choose, you will find it quite useful.',12340),
	 (1883,0,0,0,0,0,0,0,0,'Hail, $n.  Praise to you, for my call for aid is now answered.  Let us hope you are up to the task...',12340),
	 (1884,0,0,0,0,0,0,0,0,'I sense that Zalazane''s ju-ju heaps were destroyed, and with time, and luck, the flow of magic in Durotar will return to normal.$b$bA great deed you have done for your people, $N. And you have shown your worth to us, the mages of the Horde.',12340),
	 (1885,0,0,0,0,0,0,0,0,'Hm. No doubt you made your way here at first mention of my summons, yes? Of course. I would expect no less from a prospective Deathstalker.',12340),
	 (1886,0,0,0,0,0,0,0,0,'Well done, $N. You''ve passed the first part of this test. Hopefully Andron will not have caught wind of your activities, and we will be able to convince him that you are, in fact, the messenger he is expecting.',12340),
	 (1898,0,0,0,0,0,0,0,0,'Ah, yes, I''ve been expecting you. I have no doubt our mutual acquaintances are pleased with the information that I have provided so far?$B$BI suppose there''s no point in asking you, I doubt they would burden you with this knowledge. Why place so much trust in the messenger, hm?',12340),
	 (1899,0,0,0,0,0,0,0,0,'Well, this is certainly more information than I suspected to get out of Andron. Give me a moment to peruse it, before I set you to your next task.',12340),
	 (1918,6,1,0,0,0,0,0,0,'You find a nasty ball of water and decide to bring it to me? Who am I, the Earthen Ring or something?$b$bActually, that does give me an idea... perhaps you do need the Earthen Ring for this. I mean, if it helps clear up the situation at the lake for good, then I''m all for it.$b$bYou know who the Earthen Ring are, $N?',12340),
	 (1919,1,0,0,0,0,0,0,0,'$N, I have a mission for you, here in the $C district. Listen closely, for there is no time to waste.',12340),
	 (1920,21,1,0,0,0,0,0,0,'Very well done!  I will study these creatures and, with diligence and luck, determine how they slipped into our world.$B$BYour value to the society of mages grows, $N.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (1921,273,0,0,0,0,0,0,0,'Yes, these are great pieces of linen.  I can make a fine robe with them.  And after I weave the rift gems into it, we''ll have a garment fit for a $C!',12340),
	 (1938,1,1,0,0,0,0,0,0,'I feared that Morganth had hidden the book elsewhere, or that he had found a way to open it and read its contents.$B$BIt is good to see that he did not, and that the seals we placed on Ur''s Treatise on Shadow Magic still hold.',12340),
	 (1939,2,0,0,0,0,0,0,0,'Greetings, $N. I am pleased to see you, and hope you have time to listen to an old man''s words...',12340),
	 (1940,273,0,0,0,0,0,0,0,'Nice specimens, these. I''ll get right to work!',12340),
	 (1941,1,0,0,0,0,0,0,0,'Here is your robe.  It''s one of my best made yet!  Wear it with pride, and when people ask... tell them you got it at the Larson Clothiers!',12340),
	 (1942,1,6,11,0,0,0,0,0,'Your garment is ready!  And that silk you gathered was so nice... you don''t mind if I made it a little short so that I''d have some silk left over for me, do you?$B$BI''m only joking.  It''ll fit you great, and will be perfect for both adventure and formal dining.  Enjoy!',12340),
	 (1943,0,0,0,0,0,0,0,0,'Good, you have come.  My task is not an easy one, but vital to the society of mages.  If you aid me, I am sure you will find it worthwhile.',12340),
	 (1944,0,0,0,0,0,0,0,0,'Ah, very good. I trust the satyrs of Xavian gave you little trouble?$B$BThank you, $N. I will study this sample of Xavian water immediately.',12340),
	 (1945,0,0,0,0,0,0,0,0,'Ah, this hair will weave into a fine robe, $N. It is a pity the laughing sisters had to die to part with it, though I do doubt they would ever give it willingly.$B$BA pity, but only a small one.',12340),
	 (1946,0,0,0,0,0,0,0,0,'Here is your nether-lace, $N.  It is both comfortable and durable, and holds the magic of the laughing sisters'' hair.$B$BEnjoy, and if you find it amenable, please mention so to Deino.  She is a $C on whose good side I wish to stay...',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (1947,1,0,0,0,0,0,0,0,'Quiet!  I''m in a delicate juncture and mustn''t be disturbed!$B$BOne moment...',12340),
	 (1948,4,6,0,0,0,0,0,0,'Aha! You got the jade and made the bramble! Well done!$B$BIs that smoke I see rising from your ears? You might have gotten too close when the lightning struck the totem sticks, but don''t worry. Being hit by lightning is good luck!',12340),
	 (1949,5,1,25,0,0,0,0,0,'What?  Speak up!  These old ears aren''t as sharp as they used to be.$B$BWell, I hope you''re here with a fresh mug of ale or some hot tips on the next race!  If not, then you best keep walking... because I have a polymorph wand with your name on it!',12340),
	 (1950,1,1,0,0,0,0,0,0,'Ah, now I remember...$B$BI had forgotten about that little curse I put on Johnson.  I can''t remember why I did it but I''m sure it served him right, the little ingrate!',12340),
	 (1951,1,0,0,0,0,0,0,0,'That''s it!  It''s just what I need to prepare for the ritual to create your wand!  I hope it wasn''t too much trouble to find...',12340),
	 (1952,1,0,0,0,0,0,0,0,'Here are the wands I made.  Take your pick!',12340),
	 (1953,6,1,0,0,0,0,0,0,'Ah, yes.  You are here for an orb or a staff, $N?  Very well.  I will aid you in its construction.$B$BBut be forewarned--the process is a perilous one and could mean your death.$B$BOr my death.  Definitely someone''s death... $B$BBut let''s hope it''s someone else''s death, eh?',12340),
	 (1954,1,1,5,0,0,0,0,0,'Oh, that''s a nice one!  No, I don''t mean it''s "nice" like cool juice is nice on a hot day.$B$BIn fact, it''s very NOT nice now that I think about it.  Not the juice.  The orb!$B$BFocus, $N!  We''ll need you focused if we''re ever to finish our task!',12340),
	 (1955,21,1,1,0,0,0,0,0,'Nicely done, $N! You gave that demon a lesson he won''t soon forget.$B$BHe''ll think twice before he sticks his ugly head back in this world, looking for the stupid mortal who beat him. Probably with friends this time. Big, scaly friends who''d want nothing more than to tear you into little $R pieces.$B$BI didn''t scare you, did I...$N?',12340),
	 (1956,21,1,1,0,0,0,0,0,'You did it?  Well done!$B$BI was chatting with some of my colleagues and when your name came up they said, "You know that $N sure works well under stress!"$B$BBut when I told them I sent you to Uldaman against the obsidian sentinel, they said I was crazy!  They said, "Tabetha, you''re crazy!  There''s no way $N could take on that sentinel!"$B$BAnd I said, "We''ll see," and then they said "Yeah, we''ll see..."$B$BWell we sure showed them, didn''t we!',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (1957,4,1,0,0,0,0,0,0,'You did it!  I never doubted you for a second!  Ok, maybe for just a second, or two... but basically I didn''t have much doubt.$B$BHonest.',12340),
	 (1958,1,1,0,0,0,0,0,0,'You should be proud of yourself, $N.  Many mages have fallen to the creatures you faced.$B$BThe Celestial Orb is ready.  Or if you''d like I can mount it atop a staff.  It''s up to you.  I''d prefer the orb, but who am I to judge?',12340),
	 (1959,0,0,0,0,0,0,0,0,'It is true.  A magical disturbance has been detected in our city.  We are not yet sure of its origin, or whether it is malign or benign.  We must first gather more information...$B$BAnd that, $N, brings us to your task.',12340),
	 (1960,0,0,0,0,0,0,0,0,'Very good, $N.  The creatures within these containment coffers will be studied by our finest minds, and the reason behind their presence in the Undercity will be determined.$B$BIf their appearance is caused by a rift in the natural flow of magic, then we must determine if the rift was random.  If it was not random, but instead an attack by some magical force, then we must prepare for future, more serious disturbances.',12340),
	 (1961,0,0,0,0,0,0,0,0,'This is very good material, and although I lack the talent to gauge the quality of these mana gems, we''ll soon know if they possess the power needed to create spellfire robes...',12340),
	 (1962,0,0,0,0,0,0,0,0,'Here are your robes, $N.  Wear them well.',12340),
	 (1963,0,0,0,0,0,0,0,0,'Hm, while I am glad to hear that Tazan is no longer with us, a locked satchel does us no good. We need the information kept within.$b$bThis should prove a worthy second challenge for one who wishes to join the Shattered Hand.',12340),
	 (1978,0,0,0,0,0,0,0,0,'Hmm, this is interesting. The Deathstalkers have performed their duties admirably in ferreting this out.$B$BFrom what I understand, you also deserve commendation for your performance. I hope that this will become routine for you, $N, my Deathstalkers always have use of a good man.',12340),
	 (1998,0,0,0,0,0,0,0,0,'You''ve done well, $N. It occurs to me that you have performed many services for the Deathstalkers, proving your worth, and that perhaps it is time that we furthered your training in the shadow arts.',12340),
	 (1999,0,0,0,0,0,0,0,0,'Very good, $N! You have learned the fine art of lockpicking well, and faster than I could have possibly expected.$B$BI see that I was right to place my trust in you. Believe me, boy, I foresee that you will go far in this line of work.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (2038,4,0,0,0,0,0,0,0,'You''ve done the movement a great service, $N. The troggs and leper gnomes infesting Gnomeregan will soon feel the brunt of a gnomish air assault!',12340),
	 (2039,6,0,0,0,0,0,0,0,'So Gnoarn doesn''t trust my reconnaissance abilities? I wonder why...$b$bNevermind that, I need your assistance! Nay! The movement needs your assistance!',12340),
	 (2040,4,0,0,0,0,0,0,0,'Well done, $N. Thanks to you, Gnomeregan is one step closer to its day of liberation!',12340),
	 (2041,6,0,0,0,0,0,0,0,'Do you bring word from central command?',12340),
	 (2078,397,0,0,0,0,0,0,0,'Yarrr... Ye be provin'' yerself to be more than a yella sea dog, landlubber.$B$BThe Cap''n may promote ye to poop deck swabby if ye be keepin'' this up...',12340),
	 (2098,4,0,0,0,0,0,0,0,'Avast ye scurvy sea dog! Ye did it! Soon me first mate be back in workin'' order and them beasties won''t know what hit em!$B$BHrm, have ye seen me first mate?',12340),
	 (2118,1,0,0,0,0,0,0,0,'Our work has only just begun, $N. Are you prepared for your next task?',12340),
	 (2138,0,0,0,0,0,0,0,0,'You have done Auberdine a great service, $N, but your task is not yet complete.',12340),
	 (2139,0,0,0,0,0,0,0,0,'You have fought for Auberdine with bravery and honor, $N. In our war torn lands, death and despair are common. Many will not rise to meet the challenge of life in our new home, choosing instead to hide in their homes or escape to the more fortified lands of the Alliance.$b$bThank you, $N. Perhaps someday soon we shall fight along side as comrades versus another foe.',12340),
	 (2158,2,0,0,0,0,0,0,0,'Rest and relaxation for the tired and cold -- that''s our motto! Please, take a seat by the fire and rest your weary bones.$B$BWould you like to try a sampling of some of our fine food and drink?',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (2159,1,0,0,0,0,0,0,0,'Ah yes, the delivery of herbs from Shadowglen.  It is a shame Porthannius could not bring it himself, for we have much to discuss, he and I.  But I am glad to get the herbs nonetheless, and I am glad you came.$B$BWhile you are here, please, rest yourself.  Heroes must keep their strength and spirits high, and must find rest and solace whenever they may.  For to neglect one''s peace of body and mind is a sure path to failure.$B$BSo... rest.',12340),
	 (2160,1,2,0,0,0,0,0,0,'Ah, at last, the supplies from Hands! I was beginning to worry, we''ve had scarce word from Anvilmar ever since the troggs overran the pass.$b$bThanks for bring this to me, $N. And please, make yourself comfortable. You must be tired after your journey.',12340),
	 (2161,6,1,0,0,0,0,0,0,'Ah, this is the food Ukor brought to the Valley of Trials.  Did they not need it? Well, I guess they like to starve you heroes in training.  Builds spirit, they say!$b$bThank you for returning the food.  I''ll stick it back on the shelves... but here, let me offer you some refreshment first!$b$bAnd don''t forget to rest here in the inn. You may be a brave $c ready to take on the world, but if your energy is sapped you won''t be doing yourself, or the Horde, much good.',12340),
	 (2178,5,0,0,0,0,0,0,0,'Fantastic! Try it and tell me what you think, $N!',42083),
	 (2198,25,0,0,0,0,0,0,0,'Yes... I am the jeweler who made this necklace. I also am not in the business of handing out information as though it were free. Information is never free, friend. If I am going to help you out, you need to help ME out first.',12340),
	 (2199,21,0,0,0,0,0,0,0,'You''re all right in my book; I don''t care what everyone else has been saying... I kid, I kid!  Seriously, thank you my friend.$B$BNow, the necklace you have is one of my finest creations, but it is missing three gems that help bind magic power to it.  I crafted it for a paladin some time ago.  He was on a self-appointed quest to clear out the "evil taint" present at an excavation site in the Badlands called Uldaman.$B$BWell... that paladin died in Uldaman, and that was just the beginning of my woes.',12340),
	 (2200,0,0,0,0,0,0,0,0,'Remains of a paladin: Reading the journal reveals that after much effort, the paladin had identified the location of all three missing gems:$b$bThe Shadowforge dwarves hid the ruby in their barricaded area as they battled the Troggs for control of Uldaman.$b$bThe troggs stashed the topaz in an urn located near some unusual inhabitants of Uldaman - Alliance dwarves!$b$bFinally, the trogg elder himself took the sapphire as his own.',12340),
	 (2201,1,0,0,0,0,0,0,0,'Yep, those indeed are the three gems.  Good job!  Unfortunately, your work isn''t quite over just yet.$B$BNo, I''m not trying to pull a fast one here, silly $C.  This is about making magic jewelry - Talvash del Kissel quality-level jewelry!  You need a strong power source to give it some oomph.  Well, that necklace has no more oomph to give.',12340),
	 (2202,21,1,0,0,0,0,0,0,'Well done $N, you''ve proven your worth once again! The caps will be an interesting study, you betcha.$B$BAnd now, as promised, enjoy a taste of one of my more potent restorative brews from my personal stock...$B$BIf you are a skilled alchemist, then perhaps we might have some additional business to conduct. Regardless, I thank you for your assistance!',12340),
	 (2203,2,0,0,0,0,0,0,0,'From one alchemist to another, I salute you.  Here, take this recipe and commit it to your knowledge.  May it bring you the success and rewards that it has brought me over the years.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (2204,1,0,0,0,0,0,0,0,'Well I''ll be - I sure am glad to see you and this power source in one piece.  It will take me a moment to magically fuse the power source with the necklace now that the gems have been reunited with it.  Once it is done, however, the necklace will be yours!$B$BYou''re excited, aren''t you?  All tingly with anticipation?  Now where did I put that spell focus at...',12340),
	 (2205,1,6,0,0,0,0,0,0,'You found me - and by looking at you, I''d say the run and subsequent search may have been a great strain on your system, both mentally and physically.$B$BWould you like Renzik to show you the way to an inn or are you ready for some work?',12340),
	 (2206,1,1,0,0,0,0,0,0,'I am astonished... Astonished that Keryn finally found a recruit that could possibly have the makings of a proper $C. Take this blade, $N. A day will come when you will be called upon again to serve the SI:7. Hone your skills, keep your eyes open and that blade sharp.$B$BYou won''t see us coming but you''ll feel it when we get there...',12340),
	 (2218,6,1,2,0,0,0,0,0,'So ye think yer a right scoundrel? Destined to be one o'' Blackbeard''s chosen few - an officer o'' the Hidden Circle?$B$BOnly a good fer nothin'' scallywag would think so highly o'' hisself.$B$BThat''s exactly what we be lookin'' fer! Welcome aboard, $N!',12340),
	 (2238,6,1,2,0,0,0,0,0,'Shhhh! Keep it down you daft fool. They''ll hear us. ',12340),
	 (2239,5,1,0,0,0,0,0,0,'Long route? In the name o'' me own beard!$B$BYe done good, $N. Take this dagger and be gone with ye. The Circle will call upon ye again when step three be ready to be set into motion.$B$BWhat''s step three? It comes right after step two - me putting me boot up yer backside.$B$BInterested?',12340),
	 (2240,6,5,1,0,0,0,0,0,'You have seen the Chamber of Khaz''mul?  Amazing!  Baelog was sure it existed, but I must admit that I had my doubts.$B$BThank you, $N.  With luck your finding will incite our leaders to renew their efforts to retake Uldaman.  And if it is ever again under Ironforge control, then the secrets of the Chamber of Khaz''mul will be ours!',12340),
	 (2241,0,0,0,0,0,0,0,0,'Had I saved every flower that dolt, Jannok, had sent me, I would have had the means to open a shop. Regardless, it seems as if Jannok''s latest courier may prove to be useful.Interested in some work, $C?',12340),
	 (2242,0,0,0,0,0,0,0,0,'This is grim news, $N. It would seem that the sickness which has gripped the forests and rivers of Darkshore has begun to taint our home.$B$BYou have served us well, but there is nothing more you can do here. Take this blade as a reward for your service to Teldrassil.',12340),
	 (2258,21,1,0,0,0,0,0,0,'Ah, well done! These should last me for a little while, at least. Here is your pay as promised.$B$BIf you''re interested, I have some more reagents I could use. These, however, are only found in the depths of the Uldaman excavation. They will not be easy to get, but I will make it worth your while if you are interested in helping me again.$B$BPerhaps something more than some shiny coins, yes?',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (2259,0,0,0,0,0,0,0,0,'It is time to branch out, $R - the world awaits.',12340),
	 (2260,0,0,0,0,0,0,0,0,'You have answered SI:7''s calling, $N and journeyed from distant shores to join our ranks, however, there is much for you to learn.',12340),
	 (2278,0,0,0,0,0,0,0,0,'Following the instructions of the stone watcher, you once again access the Discs of Norgannon now that you have learned about the history of the Earthen, the troggs, and the dwarves. A faint, brief hum is heard from within the discs. The stone watcher then speaks:$b$b"The discs have now been synthesized. Access the Discs of Norgannon once more to receive your personal copy."',12340),
	 (2279,5,0,0,0,0,0,0,0,'What do you have there... oh my.  You found this where?$B$BNo, really?$B$BYou spoke to whom about what?$B$BNO, REALLY?!$B$BMy fine $C, you may have just made the archaeological find of the year!  By the Gods who am I kidding, the find of the century!  If these discs are what I think them to be, then this could be the very key we have been looking for!  This may well prove outright once and for all the legitimacy of the Dwarves'' enchanted creation!',12340),
	 (2280,6,1,0,0,0,0,0,0,'What are these here then?$b$bImpressive, young one! These discs, in them I sense secrets that the earth has held on to tightly for many years. You were very wise to bring them here to me.',12340),
	 (2281,6,11,0,0,0,0,0,0,'Ah, so your fingers are a little fat, eh? Don''t worry, $N, I''ve turned more useless thieves than you into accomplished rogues.',12340),
	 (2282,25,0,0,0,0,0,0,0,'Cracked it open, did you? Nice work, $N.$B$BIf you die now, we can rest easy knowing it was due to your own stupidity and not inexperience.',12340),
	 (2283,0,0,0,0,0,0,0,0,'Mmmm salvage!  I can smell the necklace from here.  Now let''s look at that beauty...$B$BHey, what do you think you''re trying to do here?  This necklace is missing the gems!  You think we wouldn''t notice?  Even Malton could see that the gems are gone.$B$BWell, maybe you didn''t steal them... but this necklace is worthless without those gems!  Your job isn''t done here yet, not by a long shot!',12340),
	 (2284,0,0,0,0,0,0,0,0,'You seem to have found the remains of the paladin that Dran had mentioned from before. Searching the remains uncovers what would appear to be his journal. The book is in poor condition, as dried blood has stained most of the text in the book. What you can read, however, is gibberish; it is written in the native tongue of the humans, to the best of your knowledge.$b$bYou will need the book translated if you are to glean any knowledge from it.',12340),
	 (2298,1,0,0,0,0,0,0,0,'It''s always good to have one of Hulfdan''s rogues among our ranks!',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (2299,25,0,0,0,0,0,0,0,'Keep yer voice down, $N, the guards may hear ye.',12340),
	 (2300,6,0,0,0,0,0,0,0,'Are you ready to get to work or do you need to take a nap before we get started?',12340),
	 (2318,1,0,0,0,0,0,0,0,'Mighty $C, I know what you are doing out here in the Badlands. I know you seek my gift of tongues. You''re after the parts to that necklace you found in Uldaman.$b$bSurprised? Don''t be - it''s my job to know such things. Instead, let''s discuss what you''re going to do for a translated journal. Trust me - I''m the only one you''ll find that can translate it.$b$bBetter still, let me make you a better offer than Dran Droffers is, and it''ll let you still complete your deal with them. Interested now, yes?',12340),
	 (2338,1,0,0,0,0,0,0,0,'You know a good deal when you see one - I knew I could count on you.$b$bIt will be just a moment while I cast a spell to quickly translate the human tongue into a form you will understand. I am a troll of my word; ask anyone in the Horde about Jarkal Mossmeld. Now, let''s get this started...',12340),
	 (2339,1,0,0,0,0,0,0,0,'Very well done, $C.  Now the fruits of our redirection will pay themselves out handsomely.  I''m finished with the necklace itself, and I am confident I can duplicate the construction process consistently.$B$BBut first, I will use a specially prepared incantation to quickly analyze those gems before you take them and the necklace back to Orgrimmar.  This will take just a brief moment to do.',12340),
	 (2340,273,0,0,0,0,0,0,0,'Yep, it''s all here. Say, mind if we keep the bag too? No? Thanks, appreciate it! Har!$b$bThis necklace will be our greatest haul yet! Don''t feel too bad though; I''m sure the necklace wouldn''t fit you anyway. Har again!$b$bA deal is a deal, so here''s your fee for the salvage. Our business is done here for now; check back later to see if we have more work. Until then, beat it!',12340),
	 (2341,1,1,0,0,0,0,0,0,'The power source you gave me exceeded every expectation I had for it. I was able to make both you and me a necklace, and I have enough left over to make at least three more. They will fetch quite the fee, with Droffers and Son Salvage none the wiser.$b$bHere you go, my friend. I give you my thanks on a splendid job... and something quite special for your trouble.',12340),
	 (2342,0,0,0,0,0,0,0,0,'At last - a broom worthy of a Garrett.  You''re bloody well worth every silver I spent on you, I say!$B$BDo you hear me, foul bats?  I now wield the Garrett family weapon of choice!  Tremble, bats, tremble!!',12340),
	 (2358,21,1,0,0,0,0,0,0,'To deny Ravenholdt the artifact, would be to deny one''s own existence. Well done, $C. You may yet walk among the assassins of Ravenholdt.$B$B As a young rogue adventuring in Darkshore, I discovered a tea that replenishes energy in combat. It has served me well throughout the years and now I pass on a taste of the thistle tea to you. Drink of it when you tire, $N, and fight with vigor once more!$B$B',0),
	 (2359,1,1,1,0,0,0,0,0,'This would explain the Defias drones you and Kearnen saw outside of the tower, $N. It would also explain the Venture Company''s involvement with the Defias and the strange shipments out of Duskwood.$B$BAccording to this book, the Zanzil trolls in Stranglethorn have discovered a way to raise the dead through potions... or to be more specific: poison.$B$BYou''ll be of no use to SI:7 without a firm understanding of poisons, $N -- especially with the recipe to create undeath at our fingertips.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (2360,6,0,0,0,0,0,0,0,'Mathias finally sent another agent to back me up, eh? Well I hope he''s ready to hear some bad news.',12340),
	 (2361,2,0,0,0,0,0,0,0,'I gladly give you this necklace, mighty $C.  You have done me an invaluable service, and for that I thank you.  Wear it with pride, and make sure you mention loudly and repeatedly who made it for you!$B$BAlso, if you could toss in the fact that it really isn''t cursed, that would be great.',12340),
	 (2378,6,0,0,0,0,0,0,0,'So, you are what our mighty allies have sent Shenthul? How uninspiring....',12340),
	 (2379,0,0,0,0,0,0,0,0,'Perhaps Zando''zan was wrong. Zando''zan apologizes.',12340),
	 (2380,0,0,0,0,0,0,0,0,'It is important that the Shattered Hand remains vigilant in the face of the changes Thrall wishes to bring about to the Horde. Our numbers alone will not be enough to overcome his rule - stealth and deception must be mastered.',12340),
	 (2381,0,0,0,0,0,0,0,0,'Incredible! Improbable! Simply amazing! You''ve got talent, Weir. Either that or you''re the luckiest man alive!$b$bHere''s your cut of the action. I''m sure you would make better use of this stuff than I could.$b$b',12340),
	 (2382,0,0,0,0,0,0,0,0,'Another one? The last five that crazy troll sent me ended up as shark food. Let''s hope you fare a little better, eh?$b$b',12340),
	 (2383,1,1,0,0,0,0,0,0,'Ah, that''s my parchment. I heard you''d be coming to the Valley, $N. I''m glad to see you made it--let''s hope you survive the trials ahead. Like I said, as you gain in power, come to me--I will do what I can to train you in the ways of the $C.$b$bGood luck, $N, and return to me whenever you feel ready.',12340),
	 (2398,5,1,0,0,0,0,0,0,'It''s about time you showed up! I was in danger of losing a bet with Olaf!$B$BHe wagered that his beard would grow to his knees before he saw another living $R. Well here you are, and as you can see Olaf''s beard has a few more inches to go.$B$BThanks, $N. I''ll split the winnings with you.',12340),
	 (2399,0,0,0,0,0,0,0,0,'The fronds Denalan planted within his garden have sprouted and grown.  They tremble, eager to be picked....',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (2418,2,0,0,0,0,0,0,0,'That''s great, you found some!  Thanks a lot, $N.  You''re the most dependable $r I''ve met!$B$BI can''t wait to try these on some devices I''ve been tinkering with.  I bet that, under the right circumstances, devices powered with these stones will keep going, and going, and going...',12340),
	 (2438,4,0,0,0,0,0,0,0,'My emerald dreamcatcher is of great importance to me. It is a gift only given to few. Thank you for returning it, $N.',12340),
	 (2439,1,0,0,0,0,0,0,0,'As yes, a voucher from the Explorers'' League... and quite the valuable one, might I add.$B$BThe Explorers'' League lends me the authority to offer you a choice in your compensation directly from their vault.  You are to receive this item, and you may choose between five superior healing potions or five greater mana potions as your reward.',12340),
	 (2440,6,1,0,0,0,0,0,0,'Well $N, you must have pleased Sage Truthseeker greatly for him to give you this item. You are also to be granted a gift from his cache of potions; you may choose between 5 superior healing potions or 5 greater mana potions as your reward.',12340),
	 (2458,1,1,0,0,0,0,0,0,'It''s good to see another agent of the Shattered Hand in these parts, however, the flare may have been a little too much!$B$BNext time you need to speak with me, blow into this whistle twice and I''ll know you are an ally.',12340),
	 (2459,2,0,0,0,0,0,0,0,'Now I can repair my dreamcatcher. Thank you, $N.',12340),
	 (2460,0,0,0,0,0,0,0,0,'Well done, $N. You are now ready to proceed.',12340),
	 (2478,0,0,0,0,0,0,0,0,'Poor Fizzule, he was a good agent -- one of our best. Alas, it is the price we pay, $N. Being a field agent of the Shattered Hand is dangerous work.$B$BYou have performed your duty well, $C. It would be a shame if you did not live to serve us again.',12340),
	 (2479,0,0,0,0,0,0,0,0,'You look deliciously pale, $C. And what is that foul aroma you are giving off? I must know!',12340),
	 (2480,0,0,0,0,0,0,0,0,'The cure is ready! Drink this anti-toxin and the creeping madness will stop, however, I will not be able to do anything about the smell.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (2498,1,0,0,0,0,0,0,0,'Ah, so Rellian sent you to aid me. I am glad you arrived here so soon.$b$bI have discovered something quite disturbing!',12340),
	 (2499,1,0,0,0,200,0,0,0,'I knew you were more than capable of ridding the lake of that horrible beast.$B$BIt is a distressing situation; Oakenscowl was once a grand leader amongst his kind... but corruption does not discriminate between the lowly and the noble.$B$BThe size of this tumor is quite disturbing, but I must study it to learn more about the disease that upsets the timberling population.$B$BThank you, $N.',12340),
	 (2500,21,1,1,0,0,0,0,0,'Ah, well done $N.  These should last me for a little while at least.  Here is your pay, as promised.$B$BIf you''re interested, I have some more reagents I could use.  These, however, are only found in the depths of the Uldaman excavation.  They will not be easy to get, but I will make it worth your while if you are interested in helping me again.$B$BPerhaps something more than some shiny coins, yes?',12340),
	 (2501,2,1,0,0,0,0,0,0,'From one alchemist to another, I salute you.  Here, take this recipe and commit it to your knowledge.  May it bring you the success and rewards that it has brought me over the years!',12340),
	 (2518,2,0,0,0,100,0,0,0,'The forest mourns for Lady Sathrah, but it was something that had to be done.$B$BThank you, $N.',12340),
	 (2519,0,0,0,0,0,0,0,0,'So, Sister Aquinne sent you?',12340),
	 (2520,0,0,0,0,0,0,0,0,'The loss of Lady Sathrah is distressing, but in this way only may she be reborn with a renewed spirit.$b$bMay Elune willingly accept the sacrifice that you have offered her.',12340),
	 (2521,0,0,0,0,0,0,0,0,'Do my eyes deceive me? Impossible! Where did you... How...$B$BPerhaps now a rift can be opened, returning us to our homeland.',12340),
	 (2522,0,0,0,0,0,0,0,0,'Simply amazing. I had doubted that you could find another sphere, yet here it is, pulsating in my hands.$B$BWell done, $N!$B$BShould you find anymore--and I believe this to be an impossibility--return them to me and I shall reward you again.',12340),
	 (2523,0,0,0,0,0,0,0,0,'You apply some Cenarion plant salve to the songflower. It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (2541,2,0,0,0,0,0,0,0,'Thank you, $N.$b$bWhat an odd trinket this is... I can sense the vile aura emanating from it; this is a very powerful enchantment.',12340),
	 (2561,0,0,0,0,0,0,0,0,'I am finally free of the control of the Gnarlpine. Thank you, $N.$b$bMy spirit may now rest peacefully forever in the Emerald Dream.$b$bPerhaps one day we may meet again, young $C. But, for now, please accept this reward as a symbol of my gratitude.',12340),
	 (2581,5,1,0,0,0,0,0,0,'How do you feel, $N? You radiate with the aura of the snickerfang--your strength, unmatched by mortals!$b$bUnfortunately, with the components you brought to me, I could only make enough of the assay for one tablet. I will require more components, should you require another tablet.',12340),
	 (2582,1,0,0,0,0,0,0,0,'There you go! Remember, use it sparingly. If you require another, come see me after you finish the one you currently have in your possession.',12340),
	 (2583,25,6,0,0,0,0,0,0,'The spirit of the boar illuminates your being, $N! I wonder, do you believe yourself to be as invulnerable as these beasts?',12340),
	 (2584,25,1,0,0,0,0,0,0,'I must warn you, $N, do not attempt to mix the formulas I have created. The chemical properties of the formula you most recently ingested will always take precedence over former enchantments; thus, rendering the other formulation null.',12340),
	 (2585,1,1,0,0,0,0,0,0,'Fascinating. This has been the most difficult of all assays to analyze.$b$bTake a pinch of this residual salt and place it under your tongue. You should experience a slight feeling of euphoria followed by a state of unprecedented agility and quickness.',12340),
	 (2586,21,1,0,0,0,0,0,0,'Fine work, $N. Here is one sample of the assay for you and the remaining nine will be used in my research.$b$bAnytime you require more of the ground scorpok assay, return to me and we shall work out a deal.',12340),
	 (2601,4,1,0,0,0,0,0,0,'This is wondrous, $N! My offering to you is a taste of the inner workings of the redstone basilisk.$B$BShould the compound be to your liking, more can always be made... for a price.',12340),
	 (2602,1,1,0,0,0,0,0,0,'Yes, yes, give me a moment and more of the compound will be ready for your consumption, $N.$B$BTake it... and $N, do not attempt to consume these experimental concoctions in rapid succession. The results could be disastrous.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (2603,21,1,0,0,0,0,0,0,'Most excellent! I shall get to work immediately. Perhaps a cure for many of the ailments of the world is to be found!$B$BAh yes, your reward - of course, should you require more of the gum, return to me and another task you shall be given.',12340),
	 (2604,1,1,0,0,0,0,0,0,'Perhaps one day I shall be able to isolate the active enzymes of this assay and produce a much more efficient resultant. Unfortunately, you will have to settle for what I am currently able to produce. Return to me should you require more gizzard gum.',12340),
	 (2605,7,0,0,0,0,0,0,0,'Oh, wonderful! Give it here -- let me drink it!',12340),
	 (2606,1,0,0,0,0,0,0,0,'Marin''s a good guy, don''t get me wrong -- just a little... eccentric, I''d say.$B$BAnd of course he needs my help, yet again.',12340),
	 (2607,5,0,0,0,0,0,0,0,'It''s about time! Just put the cheese on the table and skedaddle. Osborne will pay you on the way out.',12340),
	 (2608,22,0,0,0,1500,0,0,0,'Give me a moment to confer with my colleagues, $N. Dr. Montgomery, Mr. Noarm, let us conference!',12340),
	 (2609,6,5,0,0,0,0,0,0,'What am I doing? What does it look like I''m doing? I''m devising a cure for your ''itis!'' Don''t get indignant with me now, $n!$b$bJust a few more seconds. There! Just spray this, um, fantastic smelling medicine on yourself and you''ll be as good as new.',12340),
	 (2621,1,1,0,0,0,0,0,0,'Thrall''s Grasp... The story is still fresh in my mind.$b$b<Commander Ruag shakes his head>$b$bTerrible thing that happened to that regiment. The horde lost some of its best soldiers when that battalion was destroyed.',12340),
	 (2622,0,0,0,0,0,0,0,0,'Swamp tal... talk.. talker...$b$b',12340),
	 (2623,18,0,0,0,0,0,0,0,'It is worse than I imagined. Nineteen of my men could have been spared from the agony which they faced. If only I had not acted so irrationally.$b$bYou must help them, $N! I am powerless to act.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (2641,4,0,0,0,0,0,0,0,'That''s the stuff, $N!$B$BIt looks so good, I might just...  Haha, gotcha!',12340),
	 (2661,0,0,0,0,0,0,0,0,'Violet Powder, eh? Let''s give it a try -- it sure couldn''t make it any worse, that''s for sure!',12340),
	 (2662,4,5,11,0,0,0,0,0,'Drink this! It''s absolutely wonderful!!!$B$BI knew I had it in me... Oh thanks again, $N for your help, but please, stand a little to the side, will you? You''re blocking my business! I''m going to make millions on the fabulous Noggenfogger Elixir, millions!$B$BWhat''s that? Sprinkle says I owe her a favor? Oh, that Sprinkle, such a kidder!',12340),
	 (2681,0,0,0,0,0,0,0,0,'You have done it, $N! The poor, tortured souls can finally rest.$b$bOur work is not yet over, $N. We have much to discuss and much more to accomplish.',12340),
	 (2701,0,0,0,0,0,0,0,0,'You are temporarily blinded by the sparkle and gleam.',12340),
	 (2702,1,0,0,0,0,0,0,0,'Indeed, you have honored us all. Our thanks alone are not sufficient.',12340),
	 (2721,6,0,0,0,0,0,0,0,'Trebor? Trebor sent you?',12340),
	 (2741,0,0,0,0,0,0,0,0,'You place the hippogryph egg into the machine. A series of beeps follows along with some strange mechanical sounds.$B$BIt appears that the Eggometer has weighed, measured, and packaged your egg. Now that''s speedy service!',12340),
	 (2742,0,0,0,0,0,0,0,0,'This troll tablet must be the "secret" that Rin''ji was talking about.$B$BCovered with strange markings, you can not decipher what the tablet says.',12340),
	 (2743,0,0,0,0,0,0,0,0,'The demon lord displays a cunning almost as calculated as his brutality, $N.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (2744,25,0,0,0,0,0,0,0,'I will help you. Although, I do not think you fully understand what you are up against.',12340),
	 (2745,5,1,6,5,0,0,0,0,'What the...?! Don''t sneak up on me like that! And keep your voice down! What in the name of the Shadow are doing sneakin'' up on me for? Can''t you see I''m busy, you daft fool?$b$bWhat do you mean, what am I doing? I''m waiting for the next Dark Portal to open, what the heck do you think I''m doing? Speak your peace and be off with you... ''fore the guards notice the two of us hiding in the bushes together. I have a reputation to maintain.',12340),
	 (2746,1,1,1,0,0,0,0,0,'These will do nicely, $N. Great job.$b$bI have the rest of the gear I''ll need in my pack... thank the Light I just got a tailor friend of mine to make me a silk bag. I was running out of room carrying all my gear around.$b$bBefore Spybot heads in, let''s get the details set so you know what you have to do.',12340),
	 (2747,1,0,0,0,0,0,0,0,'Well now, you have one--amazing!$B$BI hope you always remember the good you have done today.',12340),
	 (2748,1,0,0,0,0,0,0,0,'Very good, $N. I will be sending this egg to Darnassus where I hope it will soon hatch!$B$BPlease accept this as a symbol of my gratitude.',12340),
	 (2749,1,0,0,0,0,0,0,0,'So, you have found an ordinary egg, $N? Please give it to me... And we can only hope for the best.$B$BI don''t have much, but please accept this reward. If you ever find yourself in Feralas again, know that I am always here to take the eggs you find there.',12340),
	 (2750,1,0,0,0,0,0,0,0,'I am afraid I have bad news for you, $N. This egg is too far gone. I can take it from you so that it may be disposed of properly.$B$BPlease don''t be discouraged; we cannot save them all. If you find yourself in Feralas again, please try again. Bring another egg for the Super Egg-O-Matic!',12340),
	 (2751,0,0,0,0,0,0,0,0,'The bloodline will fade but perhaps the legend of Omosh will continue!$B$BYou have proven that you are a blacksmith, $N. For the blacksmith the reward is the satisfaction of seeing their weapons and armors coated in the blood of their enemies!$B$BMay the breastplates you create for the generations ahead be drenched in the blood of your enemies!',12340),
	 (2752,0,0,0,0,0,0,0,0,'You do Orokk proud, $N. Read, learn of iron shoulders!',12340),
	 (2753,0,0,0,0,0,0,0,0,'You remind Orokk of his grandfather, Chief Gorokk of Omosh! Read, learn of the iron boot.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (2754,0,0,0,0,0,0,0,0,'Astounding! You have learned the way of the Omosh, $N!',12340),
	 (2755,0,0,0,0,0,0,0,0,'<Orokk pants.>$B$BIt has been a very long time since Orokk has done the Omosh dance of joy. Learn now, $N!',12340),
	 (2756,1,1,5,0,0,0,0,0,'It seems you are but another complacent lemming of the Warchief, $N. How disappointing.$b$bHow I long for a glorious death upon the battlefield. Instead, I am stuck here, by order of Thrall, to teach infants how to craft! Watch and learn, child!',12340),
	 (2757,5,0,0,0,0,0,0,0,'By Blackhoof''s back hair -- finally, one worthy of the Mithril Order!$b$b',12340),
	 (2758,1,1,1,0,0,0,0,0,'Very good, $N! Listen and learn.$B$BBlacksmithing never comes from here! <Hank points to his hammer.>$B$BBlacksmithing never comes from here! <Hank points to the anvil.>$B$BBlacksmithing only comes from here! <Hank points to his heart.>$B$BAnd now you know the origin of blacksmithing.',12340),
	 (2759,5,0,0,0,0,0,0,0,'By Blackhoof''s back hair -- finally, one worthy of the Mithril Order!',12340),
	 (2760,1,0,0,0,0,0,0,0,'Ah, many years it has been since one has been worthy of the mithril order''s initiation. We will start now!',12340),
	 (2761,21,0,0,0,0,0,0,0,'Your work ethic is impeccable, $N! You are starting to understand the ways of Galvan mineralogy! Take this and learn from it all that you can.',12340),
	 (2762,1,1,5,0,0,0,0,0,'She''s a cruel mistress, is she not, $N? I''m speaking of truesilver, naturally. Aye, Galvan spent over a decade in the mountains of Alterac learning this lesson. Take this and learn from it all that you can!',12340),
	 (2763,1,2,0,0,0,0,0,0,'One can barely keep their eyes from leaving its splendor, $N. Aye, citrine is a glorious gem.$B$BPay attention and learn what such a discovery may teach us!',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (2764,5,2,0,0,0,0,0,0,'Galvan the Ancient sent you??$B$B<Trenton bows.>$B$BIt is a great honor to meet another of the master''s pupils!',12340),
	 (2765,1,2,0,0,0,0,0,0,'It is only fitting that you receive a trinket of far greater power than the one you sacrificed to get here. Use it in good health, $N.',12340),
	 (2766,0,0,0,0,0,0,0,0,'You place the egg... distress beacon... inside the chicken... homing robot.$b$bHums and whirs are heard from inside the robot as it struggles to stand up. After the robot comes to life, Oglethorpe''s voice is heard once more, but now from inside the robot:$b$b"OOX-22/FE is working at least, but it needs major repairs! It is much too heavy for you to carry it... but I think I have an idea. Are you up for watching over it some more?"',12340),
	 (2767,4,0,0,0,0,0,0,0,'Oh, YOU''RE the great savior of OOX-22/FE! I cannot even begin to express my thanks for your assistance! My homing robot series needs more development, but your recovery has saved me countless hours of extra rebuilding time, as well as many gold pieces in manufacture costs!$b$bPlease, take your choice of any of these items I have. Thank you again for your generous assistance $N, my robots and I are in your debt!',12340),
	 (2768,4,0,0,0,0,0,0,0,'You found it!  Well done, $N!  Did you have to fight Bly for it?  I hope you knocked him and his band down good and hard!',12340),
	 (2769,5,0,0,0,0,0,0,0,'Ah, you want to help me?  Great!$B$BThere''s a part I want for an experiment I''m working on, and I need a brave $C like you to help me get it!',12340),
	 (2770,4,6,0,0,0,0,0,0,'Wow, you got the scale!  Thanks, $N.  I can''t wait to get to work on this thing!$B$BSo you saw Gahz''rilla?  Was he as big as they say??',12340),
	 (2771,0,0,0,0,0,0,0,0,'Excellent! A fair tradeoff, if I do say so myself. Watch and learn, $N!',12340),
	 (2772,0,0,0,0,0,0,0,0,'The world will be at your feet, $N! Let them all come at your legs, for you are now unsweepable!',12340),
	 (2773,0,0,0,0,0,0,0,0,'Thank you for all that you have taught me, $N. The master and commander of the ornate mithril set will soon be in your possession.$B$BBehold!',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (2781,4,0,0,0,0,0,0,0,'Finally - justice is served!  You have struck a mighty blow against those vile nomads!  With Scorpidsting''s demise, this might be just the thing to finally push those squatters off of Gadgetzan''s water wells!$B$BBy the authority of the Gadgetzan Water Company, I gladly award you with this bounty.  You''ve done a great service for us all.',12340),
	 (2782,1,0,0,0,0,0,0,0,'This tablet... Quite unusual... Where did you find this, $N?',12340),
	 (2783,0,0,0,0,0,0,0,0,'The Alliance wishes to assist?$B$BI thought to never see this day again. A day in which the Alliance fights side by side with the Horde against a common enemy.$B$BIt shall be... we will unite.',12340),
	 (2784,0,0,0,0,0,0,0,0,'As a spirit, I am powerless, $N. Assist me. Allow me to regain my honor.',12340),
	 (2801,0,0,0,0,0,0,0,0,'The time to act is now, $N.',12340),
	 (2821,6,1,2,0,0,0,0,0,'Did you stop and examine the texture of these hides?  Properly treated, these hides could very well be stronger than iron.  Not many people know about these hides, and that in combination with the vast treating solutions I know will allow me to potentially make items with a true mark of quality... thanks to you, of course!$B$BAnd now, please choose from what I am able to offer you for your service!',12340),
	 (2822,5,0,0,0,0,0,0,0,'Ah, excellent! These hides, when given a special treatment, are as resilient as iron I tell you! It will take many tries in order to get the right mix down for the tanning, but I am confident they will bring my mark of quality to the next level.$b$bAs for you, $N... your assistance has proven invaluable to me. Please take your choice from these items I have crafted.',12340),
	 (2841,0,0,0,0,0,0,0,0,'I knew you could do it, $N! Sovik on the other hand, he had his doubts.$B$B<Nogg clears his throat.>$B$BNow that we have the blueprints in our possession, it is only a matter of time before we figure out all of the gnomish innovations that went into the creation of the rig and make them goblin innovations for our new shredder models.',12340),
	 (2842,0,0,0,0,0,0,0,0,'She''s a beauty, isn''t she? Pinnacle of goblin transport technology -- only exploded a dozen or so times.$b$bDon''t worry, $N, I''ve got her all fixed up. She won''t blow up on you - and if she does, it''ll be quick and painless.',12340),
	 (2843,0,0,0,0,0,0,0,0,'All done! When you''re ready, just step on the pad.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (2844,4,0,0,0,0,0,0,0,'Oh, I am so glad you found me! I must admit, I am a bit lost... But isn''t this a beautiful place?',12340),
	 (2845,0,0,0,0,0,0,0,0,'What? You say dis bell will work when Shay runs off? Well, how ''bout that!$B$BSince you did so much fer me, here ya go, $N. ',12340),
	 (2846,4,1,0,0,0,0,0,0,'Wonderful!  You found it!  And what''s just as important--Velratha no longer has it!  Thank you, $N.  I am forever in your debt!$B$BAnd if I sounded a little... mean before, pay it no mind.  You''ll find me a much nicer person to those who haven''t stolen from me.',12340),
	 (2847,1,1,0,0,0,0,0,0,'Well $N, I''m glad to have you on board. You''ve made a smart decision as a leatherworker; those who wear leather armor will be clamoring to you once you learn how to make any of the Wild Leather armor pieces.$B$BLet''s get to work - where do you want to start?',12340),
	 (2848,1,1,0,0,0,0,0,0,'These armor kits are of solid quality, $N. If there is one thing I demand in not only my work, but the work of those in my employ, it is quality.$B$BYou''ve done well to earn this pattern; I hope it brings you the rewards it has brought me.',12340),
	 (2849,1,1,0,0,0,0,0,0,'These are some very nice pieces here, $N. The craftsmanship and care put in to making these alone would fetch several silver more than the average piece made.$B$BYou''ve filled my order, and with that comes your reward. The knowledge of making Wild Leather vests is now yours!',12340),
	 (2850,1,1,0,0,0,0,0,0,'This Nightscape equipment you have supplied fills the order perfectly, $N. I expect no less from a leatherworker of your caliber.$B$BYou have definitely earned this pattern. I give it to you freely, and hope you will profit from it accordingly.',12340),
	 (2851,1,0,0,0,0,0,0,0,'Once again, you''ve filled a complex order with the skill of a seasoned professional. You have earned this pattern, as well as my thanks.',12340),
	 (2852,1,1,0,0,0,0,0,0,'Again, you''ve filled an order without flaw. Perhaps some day I will come to YOU seeking knowledge, eh $N?$B$BHere is the pattern for the leggings, along with my thanks. Commit this lore to your knowledge, and let your finished products tap into your impressive skills!',12340),
	 (2853,1,1,1,0,0,0,0,0,'Ah yes, Pratt sent you. Though he is a human, he reminds me of us night elves sometimes. His dedication and his talents with leather are impressive. For him to compliment you so in this letter, it is a sign of respect I acknowledge.$B$BI am aware that he has taught you the art of Wild Leather. Allow me to finish your training with this pattern. Make good use of it; few in the world know the secrets of Wild Leather cloaks.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (2854,0,0,0,0,0,0,0,0,'Well $N, I''m glad to have you on board as my apprentice. You''ve made a wise decision as a leatherworker; those who make use of leather armor will be clamoring to you once you learn how to master the art of Wild Leather.$b$bLet''s get to work - where do you want to start?',12340),
	 (2855,0,0,0,0,0,0,0,0,'These armor kits are of solid quality, $N. If there is one thing I demand in not only my work, but in the work of those I give tutelage to, it is quality.$b$bYou''ve done well to earn this pattern; I hope it brings you the rewards it has brought me.',12340),
	 (2856,0,0,0,0,0,0,0,0,'These are some very nice pieces here, $N. The craftsmanship and care put in to making these show you have chosen to dedicate yourself fully to these tasks.$b$bYou''ve met my requests, and with that comes your reward. The knowledge of making Wild Leather vests is now yours!',12340),
	 (2857,0,0,0,0,0,0,0,0,'This Nightscape equipment you have supplied perfectly meets the requirements I have given to you, $N. I expect no less from a leatherworker of your caliber.$b$bYou have earned the honor of crafting Wild Leather helmets. I give this pattern to you freely, and hope you will profit from it accordingly.',12340),
	 (2858,0,0,0,0,0,0,0,0,'Once again, you have produced items with the skill of a seasoned professional. You have earned this pattern, as well as my congratulations.',12340),
	 (2859,0,0,0,0,0,0,0,0,'Again, you''ve completed my task without flaw. Perhaps some day I will come to YOU seeking knowledge, eh $N?$b$bHere is the pattern for the leggings, along with my thanks. Commit this lore to your knowledge, and let your finished products tap into your impressive skills!',12340),
	 (2860,0,0,0,0,0,0,0,0,'Ah yes, Jangdor sent you. I am pleased to see that one of my finest students now has a student of his own.$b$bHis dedication and his talents with leather are impressive. For him to compliment you so in this letter, it is a sign of respect I acknowledge.$b$bI am aware that he has taught you the art of Wild Leather. Allow me to finish your training with this pattern. Make good use of it; few in the world know the secrets of Wild Leather cloaks.',12340),
	 (2861,1,6,0,0,0,0,0,0,'That''s right. I do have a bone to pick with a troll. A few bones. All her bones!$b$bWant to help me?',12340),
	 (2862,21,0,0,0,0,0,0,0,'This is proof of a good start, $N. Your skills as a soldier are to be commended.$B$BYou are not the only one I ask that task of. Many before you have fought them, and in times past our efforts have kept them at bay. Recently though, their attempts to push northward into our area of influence have increased dramatically. Their attacks have also become more savage... almost as if they were desperate.$B$BI have a plan though, $N, that might settle things once and for all against them...',12340),
	 (2863,66,0,0,0,0,0,0,0,'You''ve done as I have asked, and for that I salute you. Take this small reward as compensation for your efforts, $N.$B$BWith their numbers thinned and their leaders slain, the gnolls will think twice about storming the camp. This doesn''t conclude the issue at hand, however...$B$BThere must be some reason why the gnolls have been whipped into such a frenzied state. Before they have a chance to regroup though, I want to find out what is causing it.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (2864,3,0,0,0,0,0,0,0,'Hello!$B$BOh, you spoke to my cousin Krazek?  How is he?  I hope Booty Bay is treating him well...$B$BScarab shells, you say?  Well... let me tell you a story...',12340),
	 (2865,1,0,0,0,0,0,0,0,'Oh, great!  You got them!$B$BThanks, $N.  You''re a real lifesaver!',12340),
	 (2866,0,0,0,0,0,0,0,0,'Examining the gazebo reveals some interesting and unusual things in contrast to the surrounding ruins.$B$BFirst, the gazebo is clearly a more recent construction than the other objects in the ruins.  Second, the gazebo has a small series of glyphs engraved into the sides of it; the glyphs repeat in their pattern, but it otherwise is unknown in origin and meaning.  Third, the stone of the gazebo itself is warm to the touch.$B$BThis certainly quantifies as "standing out" in the search of the ruins!',12340),
	 (2867,2,1,0,0,0,0,0,0,'Welcome back, $N.  Your report on this gazebo is most... disturbing.  It would seem that even if the naga there were not planning on an attack, their continued presence bodes ill for our push into Feralas.  At any rate, here is compensation for your investigation.$B$BIt would seem that Feathermoon Stronghold is in dire need of additional assistance concerning the Hatecrest naga.  I''d like to offer you the task, if you are so inclined.  There is much to do.',12340),
	 (2869,1,1,25,0,0,0,0,0,'Yes, yes, these scales are more than satisfactory.  Actually, I think I will send these down to Pratt for him to take a look at.  Maybe he can craft something useful out of them.$B$BAs for you, I have another mission I want to send you on.  But first, here is your bounty for the scales.  Your continued service to the General and Feathermoon Stronghold at large is a blessing in the face of adversity.',12340),
	 (2870,4,1,2,0,0,0,0,0,'Well played, $N! Lord Shalzaru''s demise will throw the naga into disarray for some time, if not permanently.  The threat they pose is now under more of our control than it has ever been, and we have you to thank for it.$B$BHere is more bounty money from the stronghold treasury - you''ve earned every copper.  You and yours are welcome in Feathermoon Stronghold anytime, my friend.$B$BOne more thing before you depart, $N... if you could...',12340),
	 (2871,6,1,1,0,0,0,0,0,'Interesting... this came from the Ruins of Solarsal, you say?  Well, Latro''s right that I need to look at this.  At first glance, it seems non-indigenous to the ruins.  Then again, this isn''t of naga design... not something as alien as this.$B$BIt is going to take some time to research this item.  Once my research on it is done, maybe I will make use of your talents, should you be around.$B$BHere, take one of these extra items we have; I hope you''ll find some use for it!',12340),
	 (2872,1,0,0,0,0,0,0,0,'Ah, so you''ve been speaking with MacKinley, have you?$B$BIt''s not what he thinks!  I''m not afraid to give him some Steamwheedle Bilge Rum...$B$BI just don''t have any rum to give him!',12340),
	 (2873,4,0,0,0,0,0,0,0,'Great, thanks for the shipment!  Now MacKinley and I can finally settle our wager.',12340),
	 (2874,1,0,0,0,0,0,0,0,'Hm, let''s try this...$b$bI can''t believe it! This stuff is... terrible! That''s great!$b$bWell I guess Stoley can keep the money he owes me. He''s true to his word about Steamwheedle bilge rum. That stuff is as thick as gravel and burns like lava!',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (2875,1,0,0,0,0,0,0,0,'Ah, Andre''s head.  So I guess he''ll make his trial after all!$B$BMuch appreciated, $N.  Now if you''ll just sign here, I can issue you payment for services rendered.$B$BDon''t worry about the small print.  It''s harmless, and... I don''t think there''s a magnifying glass small enough to read it anyway.',12340),
	 (2876,5,1,0,0,0,0,0,0,'Oh my, this looks to be a list of ship departures and arrivals, with accurate dates and times and everything!  If the captain of a pirate ship got his hands on this, he could have himself a field day!$B$BYou say you got this from a pirate?  Well that''s disturbing news...$B$BThank you, $N.  I''m glad you took it from him, and I''m glad that pirate''s eating dirt right now!',12340),
	 (2877,4,0,0,0,0,0,0,0,'Well look at you, helping out the Wildhammers!  You''re a $c of action, and action is what we respect around here.$B$BYour little clean-up mission is a lot more important than you might think it is.  With folks thinning out the oozes and sludges, we''ll be able to extend our sphere of influence in no time. Here - have a little something in addition to just making new friends here in Aerie Peak!',12340),
	 (2878,0,0,0,0,0,0,0,0,'You apply some Cenarion plant salve to the songflower. It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant.',12340),
	 (2879,0,0,0,0,0,0,0,0,'Holding the energized stave is almost impossible. Its power rumbles through your body.$B$BYou reach out to the cold surface of the Equinex Monolith...$B$BA small door opens, allowing you to reach in and take the artifact inside.$B$BBeams of light fill the area around the Equinex Monolith.',12340),
	 (2880,4,0,0,0,0,0,0,0,'Now that''s what I am talking about!  See - these necklaces prove that you''re willing to get your hands dirty.  We Wildhammers value that in those we associate with.$B$BYou keep this up, and you''ll be in our good graces yet.',12340),
	 (2881,0,0,0,0,0,0,0,0,'Now that''s what I am talking about! See - these necklaces prove that you''re willing to get your hands dirty. We Wildhammers value that in those we associate with.$B$BYou keep this up, and you''ll be in our good graces yet.',12340),
	 (2882,0,0,0,0,0,0,0,0,'Captain Cuergo''s hidden treasure awaits!',12340),
	 (2902,0,0,0,0,0,0,0,0,'Examining the map reveals it to be the battle plans that Hadoken Swiftstrider wants. Numerous arrows that perhaps represent troop movements are drawn on the map, though most seem to be headed toward the south rather than to the north where Camp Mojache lies.$B$BAnother section of the map has a picture of what you think is a large insect of some kind, with various tick marks under it. From the looks of the gnolls, it perhaps represents their losses against the unknown bugs...',12340),
	 (2903,0,0,0,0,0,0,0,0,'Ah, this is exactly what we needed. While I am not so skilled at ciphering what most of the scrawling on this map is, I''ve seen enough battle plans in my day to understand what is happening with the gnolls. It looks like they are currently fighting a two front war. One is with us... but it seems that their main energy has been against a foe to their south.$B$BThere''s more at hand here than meets the eye. Perhaps it is time to figure out who this other foe they face really is.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (2904,0,0,0,0,0,0,0,0,'I suppose you should be rewarded for bringing Kernobee back to us in one piece, $N. If you go back to Gnomeregan, these might give you the edge you''ll need in defeating that good-for-nothing backstabber, Mekgineer Thermaplugg.',12340),
	 (2922,4,1,0,0,0,0,0,0,'Oh, this is wonderful!  Thank you, $N!  I''ll get to work immediately!!$B$BPoor, poor Techbot... Don''t feel bad.  We''ll get you fixed.$B$BNow, where did I put that plug for my hydro-jack swivel spanner...',12340),
	 (2923,18,6,0,0,0,0,0,0,'Yes it''s true. Techbot has gone $C! Please, can you help me?',12340),
	 (2924,4,2,0,0,0,0,0,0,'You got them!  Now I can begin my new experiments!$B$BI can''t thank you enough, $N!  Your bravery has advanced gnomish research by a leap and a bound!',12340),
	 (2925,273,0,0,0,0,0,0,0,'I do!  I do need help with a mission into Gnomeregan.  And you''re just the $C to do it!',12340),
	 (2926,1,0,0,0,0,0,0,0,'Excellent work! The time has come to test the new formula. If this works, not only should that captured leper gnome be cured, but I should have a full head of hair! Stand back!',12340),
	 (2927,1,1,0,0,0,0,0,0,'I thought the loss of that outstanding head of hair would have been the end of him for sure, but he survived!$B$BI was standing right next to him when he was hit by the radiation bolt. Those delightful brown locks of hair hit the floor in clumps! Clusters! The horror of it all was only compounded when Gnoarn completely freaked out! Oh yes, freaked out I say! Gnoarn touched his bald head in disbelief, the look in his eyes screamed revenge, $N! Then he turned his anger towards the troggs!$B$B<Ozzie cringes.>',12340),
	 (2928,1,0,0,0,0,0,0,0,'This will do nicely, $N. One gyrodrillmatic excavationator fixed; 398 left to go.',12340),
	 (2929,5,0,0,0,0,0,0,0,'I like to think that the last thing that went through his head as he collapsed to the ground was your foot, $R. With Thermaplugg dead, our plans to retake Gnomeregan are one step closer to becoming a reality.',12340),
	 (2930,4,2,0,0,0,0,0,0,'You did it!  You found the prismatic punch card and recovered the lost data!  Vitally, critically, immeasurably important data that we could not live another moment without!$B$BYour service to the gnomes will be long remembered, $N.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (2931,1,0,0,0,0,0,0,0,'I''m organizing data extraction missions into Gnomeregan.  If you''re here for that, then listen up!',12340),
	 (2932,1,0,0,0,0,0,0,0,'Word reached me of your deed. A grim deed, but one of honor. Let us hope the Witherbarks heed your message.',12340),
	 (2933,6,0,0,0,0,0,0,0,'Ah, and what is this? It appears to be venom... from some arachnoid creature I deem. And where did you get it?',12340),
	 (2934,4,0,0,0,0,0,0,0,'Oh, splendid! The venom is quite fresh and I''m sure very deadly. Thank you!',12340),
	 (2935,1,0,0,0,0,0,0,0,'Ah, so you want fresh venom from the spider of the witherbarks, yes? Well, sit down... you''re not going to like what I have to tell you.',12340),
	 (2936,0,0,0,0,0,0,0,0,'Ah, Elortha no Shadra... speak this name only in whispers, for its utterance carries much weight in the realms of the spirit.$b$bI will put it to parchment and create for you a spell of summoning...',12340),
	 (2937,4,0,0,0,0,0,0,0,'Sweet, you got it!',12340),
	 (2938,1,1,2,0,0,0,0,0,'Ah, very good. Lydon mentioned the poison in this parcel is the most potent he has come in contact with, and is busy working on new applications with it.$b$bWith luck, we will find many.$b$bThank you, $N. Your service to the Royal Apothecary Society is undeniable.',12340),
	 (2939,6,0,0,0,0,0,0,0,'Oh, so Troyas Moonbreeze sent you?$b$b<mutters>...always bothering me with his wild notions that he found something important...$b$bLook, $N, I''ll be blunt. Troyas always thinks he has found something important in those ruins. The truth is, anything that was truly valuable was probably hoarded away long ago by the ogres or the harpies that now reside there.$b$bYou''re welcome to take a look around, but I don''t know if you''ll find any books here that will help you.',12340),
	 (2940,6,1,0,0,0,0,0,0,'So, you''d like to borrow Feralas: A History?$b$bLet me think...$b$bI will allow you to borrow this book, $N, but only if you do something for me first.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (2941,6,1,0,0,0,0,0,0,'Are you another one of Daryn''s interns? She''s quite a knowledgeable historian, $N. You should be grateful to be studying under her leadership.$b$bNow, let me get the Super Snapper FX. You''re gonna love it!',12340),
	 (2942,1,1,2,0,0,0,0,0,'I have been reading since you left, $N. This stone you have found is called the Morrow Stone. While I am not entirely sure what its purpose is yet, you can be sure that it is something of great significance to be hidden away inside the Equinex Monolith the way it was.$B$BI will continue my studies, and I hope I will be able to count on you in the future, $N. Thank you for all your help.',12340),
	 (2943,4,0,0,0,0,0,0,0,'You have brought a book along. Excellent!',12340),
	 (2944,1,0,0,0,0,0,0,0,'Well! Curgle''s invention lived up to its expectations.$B$BDon''t get too excited, but do know that I am pleased with your work, $N.$B$BNow, where did I leave that book...',12340),
	 (2945,0,0,0,0,0,0,0,0,'You place the ring inside the Sparklematic 5200 and deposit a silver coin into the slot.$B$BPainful grinding noises emanate from the machine as it begins to jerk around violently.  One can only guess what is happening with the ring inside the machine...$B$BThe machine suddenly stops, trumpeting its cessation with a simple "Ding!"  The item receptacle opens up to reveal a small box that is neatly wrapped with a red bow.  It would appear that the Sparklematic 5200 also gift wraps!',12340),
	 (2946,0,0,0,0,0,0,0,0,'As you touch the pedestal, the miniature discs from Uldaman hum and glow in your backpack. A familiar feeling tingle washes over your hands, as the image of another Stone Watcher springs to life in front of the gates of Uldum.$b$b"Salutations. I am a guardian of entry. The discs that have been used for access are missing the correct entry discs, the Plates of Uldum. Please incorporate these plates with the disc structure and repeat your access sequencing. Thank you."',12340),
	 (2947,0,0,0,0,0,0,0,0,'A ring, you say?  Let''s see... yep, I made that ring by golly.$B$BBefore Gnomeregan went up, I had a small shop there.  Perhaps it''s one I left behind when I ran for the hills; it''s a simple design, and I made several like it.  Maybe it''s from someone who didn''t make it out.$B$BDark Iron dwarves had this?  Well, that puts a new layer of conspiracy on the nine different layers already floating about.  Maybe the authorities would like to know; it''s wasted on the likes of me.$B$BNow, back to the ring...',12340),
	 (2948,0,0,0,0,0,0,0,0,'Ah, exactly what I needed!  Someday, when I find myself out of this hole that I am unjustly in, I will make for you, for EVERYONE the finest trinkets in all of Azeroth!  Until then, thanks for being a sport about the reagents.  I''d normally charge ten times what I have charged you for a ring of this quality...$B$BSpeaking of rings, here''s your new one!',12340),
	 (2949,0,0,0,0,0,0,0,0,'A ring from Gnomeregan?  Let''s see... not mine, but interesting.$B$BThe Gnomeregan thing - couldn''t have happened to a nicer bunch of numbskulls.  For years they''re a joke, and now almost overnight they''re making better rigs than us?$B$BDark Iron dwarves had the ring?  That''s even more interesting!  You know, maybe the gnomes stole their crazy golem plans and modified them.  Those Dark Irons, they''d definitely want some major payback.  It''s certainly worth investigating.$B$BYou know, about that ring...',12340),
	 (2950,0,0,0,0,0,0,0,0,'Here''s your ring, better than before.  Thanks again for the information about those Dark Iron dwarves.  This seems like a reasonable lead as to how those gnomes suddenly were struck with goblin-like inspiration.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (2951,0,0,0,0,0,0,0,0,'You insert the grime-encrusted item and three silver coins into the Sparklematic 5200. The machine surges to life in a frenzied attempt to purge the grime from the unknown item. Loud, violent churning sounds beat from the heart of the machine. The metal frame of the beast creaks and groans as it lurches from side to side...',12340),
	 (2952,0,0,0,0,0,0,0,0,'As quickly as it started, the Sparklematic 5200 comes to an abrupt halt. A simple "ding" is heard from the machine, and the mouth of the machine spirals upward. Inside the Sparklematic 5200 is a small box wrapped in a little bow. The machine would appear to wrap an object up after eliminating its grime-encrusted status. Even if the machine didn''t work, at least the item is now wrapped in a pretty box.$B$BWell, there is one way to find out if it cleaned the item or not...',12340),
	 (2953,0,0,0,0,0,0,0,0,'The Sparklematic 5200 comes to life, lurching to and fro. Inside, the helpless grime that has encrusted the object placed within it is being pulverized by the machine''s gnomish cleaning agent.$B$BThe Sparklematic 5200 comes to a halt, heralded by a familiar "ding!" The item receptacle of the machine spirals open, revealing a neatly wrapped box.',12340),
	 (2954,0,0,0,0,0,0,0,0,'The stone watcher''s voice resonates with power and authority:$b$b"Your discs will be returned to you once you access the pedestal. When you have obtained the Plates of Uldum and incorporated them into your existing disc set, you may then enter the complex."',12340),
	 (2962,1,0,0,0,0,0,0,0,'<Ozzie examines you.> Impressive, you still have all of your limbs. Now it''s time to see what this stuff can do!',12340),
	 (2963,1,1,0,0,0,0,0,0,'I am glad you''re maintaining your interest in exploration, $N!  With your natural talent and moxie, we could crack open secrets that we never thought were possible!$B$BThe Discs of Norgannon in Uldaman were a repository of vast information; you were only permitted to access the top layers, as it were, of the information stored there.  The Creators were rumored to have more repositories located throughout Azeroth.  This now brings us to Uldum...',12340),
	 (2964,1,1,1,0,0,0,0,0,'We''re all in agreement then - the best plan of attack is putting this on hold until we can narrow down the areas where these plates might lie hidden.  You''ve brought us this far $N, and I hope you will be the one to head back in to the field to unlock Uldum for us all!$B$BAllow me to give you this honorarium in the meantime; this should cover any expenses you''ve encountered in assisting us, and a little something extra.  Be sure to check back with us soon... Uldum beckons!',12340),
	 (2965,1,1,0,0,0,0,0,0,'There is a place deep in the Tanaris desert called the Valley of the Watchers.  The discs that you recovered... their translated glyphs make mention of a place called Uldum.  Most think this place to be a myth.$B$BI know this to be false; Uldum exists.  I''ve been there.  Well... outside, at any rate.$B$BThe crux is this, $N: we think there is a connection between the discs and Uldum, and we want you to go there.',12340),
	 (2966,0,0,0,0,0,0,0,0,'As you touch the pedestal, the miniature discs from Uldaman hum and glow in your backpack.  A familiar feeling tingle washes over your hands, as the image of another Stone Watcher springs to life in front of the gates of Uldum.$B$B"Salutations.  I am a guardian of entry.  The discs that have been used for access are missing the correct entry discs, the Plates of Uldum.  Please incorporate these plates with the disc structure and repeat your access sequencing.  Thank you."',12340),
	 (2967,6,1,1,0,0,0,0,0,'You were missing some discs?  Interestingly enough, it seems that the discs of Norgannon are only parts of the complete set - like keys on a key ring, if you will.$B$BIf we can find the Plates of Uldum, then we could actually access the Uldum complex itself.  I don''t know whether to be excited by that prospect, or be terrified.$B$BWe may need to risk everything to ensure that those secrets the earth keeps which would destroy us all remain just that - secrets.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (2968,1,1,1,0,0,0,0,0,'We''re all in agreement then - the best course of action is to wait until we can narrow down the areas where these plates might lie hidden. You''ve brought us this far $N, and I hope you will be the one to head back in to the field to confront the secrets of Uldum.$B$BAllow me to give you this honorarium in the meantime; this should cover any expenses you''ve encountered in assisting us, and a little something extra. Be sure to check back with us soon... Uldum beckons us all, young one.',12340),
	 (2969,2,1,0,0,0,0,0,0,'Thank Elune, $N! You are a great blessing to us and to the darters you saved. Jer''kai and I would never have been able to help the dragons ourselves--your intervention in the Grimtotem''s affairs will be remembered.$B$BSpeak to Jer''kai now... I have to prepare for our retribution. Just because the faerie dragons are free, it doesn''t mean they will remain so. Jer''kai and I will now go on the offensive.',12340),
	 (2970,1,1,0,0,0,0,0,0,'Kindal was right about you, $N--you do have a knack for this. You are a more seasoned adventurer than the both of us, and for that we thank you.$B$BThe Grimtotem clan is much more hostile than most tauren... I wonder if their own kind frowns upon their actions. I wouldn''t be surprised. As you are probably aware, many races on Azeroth have ties to less kindly counterparts.$B$BBut that is a discussion for another day.',12340),
	 (2972,1,1,0,0,0,0,0,0,'That''s an amazing story, $N. It pleases us that you''ve not only helped dragonkind, but also one of our own priestess. Jer''kai was right to send you to me. I will make sure she has her ring returned to her--I have scouts heading the direction of Feralas soon. This will be one more thing for them to investigate while on their mission.$B$BThank you again, and please, make yourself at home while you''re here.',12340),
	 (2973,11,0,0,0,0,0,0,0,'Wonderful, $C! These will do nicely. There are enough here to make a cloak for Korrin, and possibly even more! Thank you.$b$bI hope the trip wasn''t too dangerous? The area of Feralas is not known for being forgiving, but you''ve obviously done well enough.$b$bThank you again, $C.',12340),
	 (2974,0,0,0,0,0,0,0,0,'These are good horns, $C. Well done. I''ll take these from you and be sure to tell Belgrom as soon as we return to Orgrimmar. You''ve helped me twice now, and for that, you have my mark. Perhaps in the future I can help you! Good luck to you.',12340),
	 (2975,1,0,0,0,0,0,0,0,'Excellent, $N. In time, the land will heal. We must not give up.',12340),
	 (2976,5,1,0,0,0,0,0,0,'The Grimtotem!? This is interesting. You say you came across them while hunting in Feralas? Truly?$b$bMy peers will want to hear your news, $C. Tell me more and I''ll count out your coin while you do so.$b$bAnd before you go, know that I give you thanks for the information you''ve passed on to me this day.',12340),
	 (2977,6,1,1,0,0,0,0,0,'You were missing some discs?  Interestingly enough, it seems that the discs of Norgannon are only parts of the complete set - like keys on a key ring, if you will.$B$BIf we can find the Plates of Uldum, then we could actually access the Uldum complex itself!  Imagine actually exploring the place where the Creators worked without having to bring a huge shovel!$B$BNot that there''s anything wrong with shovels... or digging...',12340),
	 (2978,0,0,0,0,0,0,0,0,'This scroll... You found this in the Gordunni Outpost?',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (2979,0,0,0,0,0,0,0,0,'This orb will provide us with more information about the Gordunni... which we will then use in planning their downfall, $N.',12340),
	 (2980,2,0,0,0,0,0,0,0,'You have proven yourself to be a trustworthy and dependable ally, $N.',12340),
	 (2981,1,0,0,0,0,0,0,0,'So, Belgrom sent you. You are just in time, $R.$B$BLet me explain the situation, and then you can decide if you are up to the challenge... But if Belgrom sent you, I am sure your courage is unquestionable.',12340),
	 (2982,2,0,0,0,0,0,0,0,'I am very grateful you were able to do this for me.$B$BNow, please, don''t mention a word to Troyas about this...',12340),
	 (2983,0,0,0,0,0,0,0,0,'Hmmm, Swart sent you to me, did he?$B$BWell then, Swart could always be trusted, so that must mean you''re ready to take part of the next sapta--the sapta of fire.$B$BI see it in your eyes already, the burning, the desire. You''ve tasted power, and now you''re ready for more of it. Patience, $N. Remember what earth taught you. Power and destruction will come easily, but you must still know when to stay your hand.',12340),
	 (2984,0,0,0,0,0,0,0,0,'Hmmm, Narm sent you to me, did he?$bbWell then, Narm could always be trusted, so that must mean you''re ready to take part of the next sapta--the sapta of fire.$b$bI see it in your eyes already, the burning, the desire. You''ve tasted power, and now you''re ready for more of it. Patience, $n. Remember what earth taught you. Power and destruction will come easily, but you must still know when to stay your hand.',12340),
	 (2985,0,0,0,0,0,0,0,0,'The wind approaches you quickly from the horizon; the earth is steady beneath your feet; and your spirit is already warmed by fire--I would say it is time for you to learn about the purity of water.$B$BYour path has led you this far, and your spirit will give you the strength to carry on even further. But the first step is yours to take.',12340),
	 (2987,0,0,0,0,0,0,0,0,'Perfect! I will take these along as I continue my travels, $N. I''m sure I can find someone that will pay a pretty penny for this cobalt.$b$bHere, take this for your trouble.',12340),
	 (2988,1,0,0,0,0,0,0,0,'Sharpbeak wasn''t at the villages?  Hm... this is grim news.  That gryphon is destined to lead the next generation of gryphons.  If he is lost then the strength and spirit of our fleet will suffer immensely.',12340),
	 (2989,1,0,0,0,0,0,0,0,'Sharpbeak wasn''t there?  That is bad news, but it is good news too...$B$BIt is good that he was not at the Altar of Zul for the Vilebranch trolls are known for performing sacrifices.$B$BI thank you for all of your aid, but I''m afraid I have an even greater task ahead.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (2990,1,0,0,0,0,0,0,0,'Ah, yes.  This feather belongs to a fine gryphon.  One destined for great things... if he can survive into adulthood undamaged.$B$BYou wish to find him?  Then listen close, brave $C...',12340),
	 (2991,1,0,0,0,0,0,0,0,'Ah, the medallion of Nekrum.  It is rumored to have given the troll an unnatural long life, but at a cost.  I hope to discover a way to reap the medallion''s power while avoiding its... unpleasant side effects.$B$BYou have done me a service, $N.  I shall now uphold my end of our bargain.',12340),
	 (2992,1,0,0,0,0,0,0,0,'The ritual was a success.  I have seen Sharpbeak and can tell you how to find him.',12340),
	 (2993,6,5,0,0,0,0,0,0,'You''ve spoken with Grimshade?  What did he say?$B$B...What?  The Vilebranch trolls have Sharpbeak?  That''s unbearable!  We must organize a force to get him back!',12340),
	 (2994,4,2,1,0,0,0,0,0,'Swiftwind and Keenclaw returned with their child moments ago, and are fussing over him like new parents.  Seeing them together again is enough to give even this old dwarf mist in the eyes...$B$BWe cannot repay you enough for what you have done, $N.  The gryphons of Aerie peak, and their riders, will sing your name for a long, long time.',12340),
	 (2995,1,0,0,0,0,0,0,0,'Perfect, $N. While the Highvale work to recover their lost information, we will be able to seal off the lines even further...',12340),
	 (2996,0,0,0,0,0,0,0,0,'A busy day in Ratchet, isn''t it? How I enjoy watching the toil of a port city. So much mystery, so much adventure... so much ignorance.$B$BIs that hatred I see in your eyes, $N? Good, we will put that to good use.',12340),
	 (2997,2,0,0,0,0,0,0,0,'Well met, $N. I hope the Light shows you the true path and keeps you safe from evil.',12340),
	 (2998,1,1,0,0,0,0,0,0,'It is beautiful here in Stormwind, is it not?$B$BYour timing actually couldn''t have been better, $N.',12340),
	 (2999,2,0,0,0,0,0,0,0,'Well met, $N. I hope the Light shows you the true path and keeps you safe from evil.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (3000,2,0,0,0,0,0,0,0,'I greet you, and bid you welcome, $N.',12340),
	 (3001,0,0,0,0,0,0,0,0,'A busy day in Ratchet, isn''t it? How I enjoy watching the toil of a port city. So much mystery, so much adventure... so much ignorance.$B$BIs that hatred I see in your eyes, $N? Good, we will put that to good use.',12340),
	 (3002,5,0,0,0,0,0,0,0,'Fascinating, $N...$b$bThis orb is very powerful, but also very dangerous.',12340),
	 (3022,1,0,0,0,0,0,0,0,'Thank you for your help, $N. The hippogryph population simply wouldn''t flourish if it weren''t for us. Ah, but I am sure you understand all too well, having traveled to Feralas yourself, and seen the devastation of the Gordunni there.$B$BWell, as you can see, I am hard at work here, so you''d best be on your way.$B$BThanks again, $N.',12340),
	 (3042,1,0,0,0,0,0,0,0,'Ah, this is very nice temper indeed!  And so much of it!  I''ll be at work for days before I use it all!$B$BThank you, $N.  Please, take this as payment.',12340),
	 (3062,2,0,0,0,1000,0,0,0,'Now I know that Edana is truly dead. This heart; I will keep it in memory of what did here for me, $N. Thank you.',12340),
	 (3063,2,0,0,0,0,0,0,0,'Thank you, $N. You have put an old tauren''s mind at peace.',12340),
	 (3065,1,1,0,0,0,0,0,0,'You''ll find this place fitting as you continue to train in the $C ways. If you have any questions, feel free to ask anyone around, and when you feel you''re ready, come back to me for training. I''ve mastered as much as any $C here in the Valley and can pass that knowledge on to you... for a price.',12340),
	 (3082,1,1,0,0,0,0,0,0,'Now we teach them those things, and they teach us others. We become one race... almost. We be allies for long time now. So you remember to help them. And Jen''shan remember to help you.$b$bJen''shan teach you da ways of the $C--teach you good. You never forget, $C''s be respected greatly by da tribe. You be havin'' a large role to play in da future... you never forget that.$b$bWhen you feel da need, come to Jen''shan. She teach you as much as she can when she feel you ready.',12340),
	 (3083,1,1,0,0,0,0,0,0,'Until such time comes, you''ll be under my tutelage. I will show you the ropes as some folks say. Whenever you feel prepared, come to me and I will see about training you further. Until then, practice your skills and keep them honed to a razor''s edge. You''ll never know when you''ll need even the most insignificant ability.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (3084,1,1,1,0,0,0,0,0,'As you probably know, the elements give us our power. Fire, earth, water and air--these are our tools.$b$bOur strength comes from the spirits of our ancestors. We are the leaders of our people. Like Thrall is to the Horde, so shall we be to the villages and towns we visit. They will look to us for wisdom and protection. To be better prepared, you must train often. When you feel you''ve gained more power, come to me and I shall teach you what I can.',12340),
	 (3085,1,1,0,0,0,0,0,0,'As ya test yeself, ya''ll find ya have better an'' better control o''er da spirits--ya''ll be callin'' on dem fer greata an'' greata tings... dat''s where ol'' Ken''jai come in. You come talk to ole Ken''jai when ya feel yer ready. If da spirits agree, den we see ''bout teachin'' ya more powerful abilities... but only if da spirits agree.$B$BGo now, talk to da rest of da Valley''s people. Speak to me again later.',12340),
	 (3086,1,1,1,0,0,0,0,0,'You be among da most powerful beings on da planet, $N... there no arguin'' dat. And everyone know it... know it good, too!$B$BBut ya must be weary! ''cause it not orc, or elf, or dwarf dat you should be scared of... it be da tings you can''na see. Magic be powerful. Make you do tings you may not want to do. Make ya tink you more powerful then you really be. Be patient. Be smart.$B$BWhen ya tink you be ready for trainin'', come back to Mai''ah. She teach you what you ready to learn, no problem.',12340),
	 (3087,1,1,0,0,0,0,0,0,'When we finish speakin'', you should talk to da rest of da citizens in da Valley. They ask you to do tings for them... tings that will test your skill and teach you some of da dangers of this land.$B$BAs you grow in experience and wisdom, you be needin'' Jen''shan to show you better techniques and skills. Come back to Jen''shan often. I will let you know what I can teach you.',12340),
	 (3088,1,1,0,0,0,0,0,0,'Now that you know where I''m holding up, I should let you know: the Shattered Hand''s asked me to look out for you. They want me to train you and keep you informed of anything they might need. Even if you''re not interested in helping them yet--which you''d be a fool not to be--I''ll do what I can to train you... for a small fee. Come back to me anytime you think you''re ready, and we''ll see what you''re ready to learn.',12340),
	 (3089,1,1,1,0,0,0,0,0,'You will be the conduit in which our ancestors communicate. You will have the power of the elements at your beck and call. Sundering your enemies will be child''s play; healing your allies as easy as breathing. Keep these things in mind as you face new challenges, and come back to me as often as you''d like. I will remain here to teach you new spells and set you on the correct path when you are ready.',12340),
	 (3090,0,0,0,0,0,0,0,0,'And now you''ve joined our ranks also. Don''t misunderstand, $n. Just because you have access to power that many will be jealous of, it does not mean you will be accepted easily. Thrall allows our kind into Orgrimmar because we are still his fellow kin--he cannot turn his back on us, or we would become as pathetic as the humans who enslaved him. My point is: be careful. You can be powerful, but if you are foolish, then you are as good dead.$B$BIf you need training in spells then return to me.',0),
	 (3091,1,1,0,0,0,0,0,0,'Each of us plays a role in our tribe. Each of us must also go through all the same rites. Do not ever let your pride tell you otherwise.$b$bI remain here to train new warriors that seek the glory of battle and who follow the ways of our oldest ancestors. When you feel ready, come back to me and I will do what I can to train you further. Go with the tribe''s blessing, $N.',12340),
	 (3092,1,1,0,0,0,0,0,0,'And it is my job to make sure you are prepared by teaching you the basics of our profession--how to tame your pet, how to fire your rifle, and many other skills that will become necessary.$b$bHunters are a strong part of our tradition and history, $n. You would do well to remember how important you are to the tribe. You will be respected and revered if you serve our people well.',12340),
	 (3093,1,1,0,0,0,0,0,0,'We will meet many times in the days to come. Each time you will hopefully leave my company a little more powerful... a little more prepared. Like the Eternal Flame, your spirit will burn bright and hot.$b$bGo now, $N. Go and test yourself. I will be here for you when you need.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (3094,1,1,0,0,0,0,0,0,'Though we share a common bond, do not expect much welcome from the night elves. Their pride still limits their sight, but that is none of our concern. The teachings of the Earthmother are all you must concern yourself with, and I will teach you what I know as you grow in wisdom.$b$bReturn to me often, $N. You will find that the Earthmother grants incredible abilities to those who are most dedicated.',12340),
	 (3095,0,0,0,0,0,0,0,0,'I will be here to train you as you grow in experience... find me as often as you like. I charge a minimal fee, but you''ll find everything I can teach you to be worthwhile.$B$BGo now and test your skill. Many more things will become known to you as you gain experience, some of which I am unable to discuss with you here. Just know that Sylvanas will need warriors with your type of strength in the future. You will be the backbone of our salvation. Do not forget it.',12340),
	 (3096,0,0,0,0,0,0,0,0,'I spend most of my time here in the inn keeping an eye out for new faces and just keeping tabs on up-and-coming prospects. Keep your nose clean and I''ll do what I can to teach you a few things. Just come back to me whenever you want, and we''ll see if you''re ready for a new skill or two.',12340),
	 (3097,0,0,0,0,0,0,0,0,'There is only one thing you must know: we have survived through will alone. It is faith in ourselves that separates us from others, and with our powers, we will cause great change in all of Azeroth. The weak will come to lean on you. The lepers will call you Lord. And the ignorant will look to you for guidance. It is my duty to make sure you have the necessary tools so when the time comes, you are prepared. As you grow in experience, seek me out. I will teach you greater powers if you are ready.',12340),
	 (3098,1,0,0,0,0,0,0,0,'You must return to me often if you are to become powerful enough to destroy those who would oppose us. The rules of magic still apply to you, $N. You will still find corruption follows you like hungry wolves in the night. You will find its caress is not unlike an addiction, an old lover still wanting to be by your side. But these things can be staved off. These things will only control you if you allow them to.$b$bGo now, return to me when you''ve grown more powerful.',12340),
	 (3099,1,0,0,0,0,0,0,0,'I mentioned a slave still being a slave, no matter the master. Do you remember? We both know that it is that type of control--that type of power--that now drives us. We seek to have creatures serve us. We know we are more powerful and deserve more respect than others give us ... and so now we look to take it.$b$bI will be your ally in this struggle--the struggle for our own freedom. Freedom to seek our own allegiances. When you feel ready, return to me and I will teach you all I know.',12340),
	 (3100,1,1,0,0,0,0,0,0,'Get yourself squared away, learn the layout of the land, and come back to me whenever you need training. I''ll be here night or day.$B$BThe Knights of the Silver Hand have done well in making this place fairly safe, but as you meet the other citizens, I think you''ll find they all have problems they could use some help with - help a $C can give them. Good luck.',12340),
	 (3101,1,1,0,0,0,0,0,0,'In the meantime, you should know one or two other things. You are a symbol to many here in this land--act accordingly. The Holy Light shines within you, and it will be obvious to both your allies and your enemies.$B$BAlso, as you gain in wisdom and power, you will need to train to learn new abilities. That''s where I come in. When you feel you''ve gained some experience here in Northshire, come back to me and I will teach you what I feel you are ready to learn. Good luck... $C!',12340),
	 (3102,1,1,1,0,0,0,0,0,'You''re gonna find that there a number of outfits that''ll covet our skills, Cailel. Adventurers, SI:7... heck, even the Defias Brotherhood wouldn''t mind a spy or two inside Stormwind. But you remember this, you''re your own man. Don''t let nobody bully you into doing something you don''t wanna do! Besides, we hold all the cards... at least, we do before the game''s done. Know what I mean?$b$bAnyway, just wanted to introduce myself and let you know that I''m here if you need any training. Come by anytime.',12340),
	 (3103,1,1,0,0,0,0,0,0,'As you grow in experience, return to me and I will do what I can to impart my knowledge upon you. Until then, go with compassion in your heart, and let wisdom be your guide. Remember, the world only becomes a better place if you make it so.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (3104,11,0,0,0,0,0,0,0,'Haha, I knew my note would not dissuade you from your path. So, you''re prepared then, are you? Prepared to accept your fate? Prepared to challenge the gods and any other forces that stand before you in the pursuit of knowledge and power?$B$BI will not lie, $N, you will be feared as much as respected. But also know this, I will be here for you when you need training. Simply seek me out as you grow more powerful.',12340),
	 (3105,1,0,0,0,0,0,0,0,'As you grow in power, you will be tempted--you must always remember to control yourself. I will not lie--corruption can come to any practitioner of the arcane; especially one who deals with creatures from the Twisting Nether. Be patient, and be prudent... but do not let that repress your ambition.$B$BAs you grow more powerful, return to me and I will teach you more about our ways.',12340),
	 (3106,1,1,0,0,0,0,0,0,'Other things you''ll probably see too, just so yer in the know: dwarves usin'' magic in a fight ''stead of a rifle. Some of us takin'' to worshippin'' the Holy Light like some of the humans, and, last but not least, troggs. You''ll learn more ''bout them later, but What you need to know now is that I''m here to help ya.$b$bI be here to teach ya how to be a real $C. Anytime ya think ya need more trainin'', come back to me and I''ll see what I can do.',12340),
	 (3107,1,1,6,0,0,0,0,0,'The humans have taught us a great deal about the Holy Light and how important their order is to them... and to protecting all of Azeroth. We have a great respect for how stepped in tradition it is, and how just one figure, one sacrifice, can make the difference between pain and salvation.$B$BThe two of us are gonna be working together for a bit. Any time you think you''re ready, come back to me and we''ll see about getting you some training. Can''t have you go out into the world unprepared, now, can we?',12340),
	 (3108,1,1,0,0,0,0,0,0,'One thing you should always remember is that you gotta respect the world you''re livin'' in. The beasts that choose to fight along side you; the shine of your weapon; the weight of your ammo; the bite of a bitter wind; all these things you need to know intimately.$B$BI''ll do what I can to help you, but most of the work''s up to you. Anytime you think you''re ready, come back and talk to me. I''ll train you when I can.',12340),
	 (3109,1,1,0,0,0,0,0,0,'Anyway, as you start peekin'' around Coldridge you''ll probably have need of training at some point. You just come back to me whenever you feel you need it and I''ll teach you what I know--a trick here, a maneuver there. You know, the stuff that keeps you alive and makin'' a little extra coin.$B$BKeep an eye out on our gnomish friends too... they kinda got the short end of the stick what with Gnomeregan being... destroyed. They''ll need our help to feel welcome.',12340),
	 (3110,1,1,0,0,0,0,0,0,'I''m the one who can train ya as you start to find your way around Coldridge Valley. When ya feel yer ready, come back to me and we''ll see about maybe teaching you a new spell or two to fend off the valley from them blasted troggs.$B$BYa got the Light on yer side, along with all of Ironforge, $N... no pressure on ya to become somethin'' special.',12340),
	 (3112,1,1,0,0,0,0,0,0,'Well, seein'' how this is your prime directive, or whatever yer callin'' it these days, I gave my word I''d do whatever I can to make sure you and yours were ready to take back your home... and that''s just what I''m gonna do.$B$BAny time you feel yer ready, come back to good ol'' Thran and I''ll be happy to share my knowledge wit ya. There''s some cost to me trainin'' ya, but it won''t be too expensive. Good luck.',12340),
	 (3113,1,1,0,0,0,0,0,0,'I pretty much keep to myself around here so we don''t get a bad wrap for things gone missing, but if you need anything, some training or somethin'', just come back anytime.$B$BYou and me got an understandin''. We know when it comes down to it you can only trust family... and that''s just what we got going on here, isn''t it? Regardless of Gnomeregan being... overrun, and whatever else is thrown our way, we got one another to back each other up. Right?',12340),
	 (3114,1,1,1,0,0,0,0,0,'Oh, yeah! Arcane Arts... of course.$b$bHere''s what you need to know, $N: Don''t get into too much trouble. Save some coin to buy me an ale... or any spells ya might want. And stay the heck away from Gnomeregan. Other than that, have a good day! I''ll be here if you need me or want to train... or whatever.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (3115,1,1,1,0,0,0,0,0,'But none of that matters. What matters is that you''ve seen your own Holy Light! You know where power truly comes from. You realize that having our own allies is much more... prudent. Special allies. Allies that, no matter the task, will obey till their last breath.$b$bAnd that''s where I come in, $N. I can train you in the beginnings of those special powers. Seek me out often and I will do what I can to teach you more spells.',12340),
	 (3116,1,1,0,0,0,0,0,0,'Soon you will see others from different races in the boughs of our home--do not let it cause any prejudice within you. They are welcome. They will aid us when they can. Not all of them will be altruistic, but they should be granted some amount of trust.$b$bBut none of this matters now. Now we must focus on you, and how you can aid our people. I am here for that very purpose. I will train you in the ways of a $C as you become stronger. Return to me whenever you wish and I will do what I can to aid you.',12340),
	 (3117,1,1,0,0,0,0,0,0,'As you experience what Shadowglen has to teach you, come see me--I will be able to help you understand more about your role as a $C and what you are capable of.$B$BThese are dangerous times, $N, do not take for granted the skill of your pets--there are things in this world more dangerous than you can imagine. Go with Elune and return to me again.',12340),
	 (3118,1,1,0,0,0,0,0,0,'Until then, know that our kind are needed more than ever in this tenuous time. Peace with the other races can fail at any moment, and there is much talk about members of the Horde looking to sow even greater seeds of distrust. Remember that.$b$bAs you gain in power and feel more prepared, come back to me here and I will see about getting you some training. It''s important that you know how to handle your weapon of choice, among other things.',12340),
	 (3119,1,1,0,0,0,0,0,0,'Do not concern yourself with the world below Teldrassil for now. There will be time for that later. Go now and speak to the others in Shadowglen--they can tell you more about what events have transpired. Help them in any way you can, and anytime you feel you need more training, come back to me and I will teach you what I can.',12340),
	 (3120,1,1,0,0,0,0,0,0,'I will be your mentor and guide for now. It is my duty to teach you how to interpret not only what the spirits communicate to us, but also the complexities and secrets of the Emerald Dream.$b$bAs you learn and grow in power, you will learn more of our sleeping trance. But until then, return to me as often as you like and I will teach you what I can in the ways of our kind.',12340),
	 (3121,1,0,0,0,0,0,0,0,'I have been waiting for Uzer''i to deliver this...$b$bLet me give you the herb mixture I prepared for his... well, experiments...',12340),
	 (3122,1,0,0,0,0,0,0,0,'This is just what I need to prepare the muisek vessel, $N. Soon we will see if my latest incantations prove to be as powerful as I had hoped.$b$bPlease, a moment. I must perform the ritual and apply the herbs.',12340),
	 (3123,1,0,0,0,0,0,0,0,'Upon a violent death, the muisek of a creature may escape and seek revenge. Shrinking the creatures, as you did, $N, prevents the muisek from escaping. Now we may use it as we please!',12340),
	 (3124,1,0,0,0,0,0,0,0,'After killing an animal, if we allowed the muisek to escape, it may take the form of an even greater creature. We would never be safe from its vengeance.$b$bThis is a dangerous job I have given you, $N. Again, you have completed it well.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (3125,1,0,0,0,0,0,0,0,'Thank you, $N. Now the spiritual powers of the faerie dragon will be available to us.$b$bI hope you willing to perform another task for me.',12340),
	 (3126,1,0,0,0,0,0,0,0,'Thank you, $N. Our muisek collection is almost complete.',12340),
	 (3127,1,4,0,0,0,0,0,0,'Just imagine the possibilities of what we now possess, $N. Along with the materials that you have collected, I will be able to forever trap the muisek of these creatures into whatever I wish.',12340),
	 (3128,4,0,0,0,0,0,0,0,'Excellent! These materials, combined with the muisek, should yield just the results we''ve been wanting.',12340),
	 (3129,1,4,0,0,0,0,0,0,'As promised, you have your choice, $N. The muisek of the creatures has been forever sealed into the power of these weapons.$b$bYou may now wield their energy as your own. Use it well.',12340),
	 (3130,66,1,0,0,0,0,0,0,'Excellent, $N - I value a "can do" attitude in those who I work with.$B$BI''ve been tasked by General Feathermoon to address the naga in a direct manner.  My plans are two fold: one, we will weaken their forces both in number and in command, and two, we will uncover what they are up to in the ruins.  With your help, we''ll counter the naga presence without sacrificing the general security of the stronghold.',12340),
	 (3141,0,0,0,0,0,0,0,0,'So be it...',12340),
	 (3161,0,0,0,0,0,0,0,0,'Perfect; these ornaments are perfect for my studies. Thanks so much for the help, $N.$B$BOh, can I get my helmet back?',12340),
	 (3181,6,5,1,0,0,0,0,0,'What have you got there? A fake obviously!$B$BI''ve been face to face with Margol and I know for a fact that her horn is at least eight times larger than the one you''ve got in your hands, $N. You probably got that off of a stormsnout in the Barrens. No ma''am, you can''t fool Pebblebitty!',12340),
	 (3182,6,5,0,0,0,0,0,0,'What''s this?$B$BOh my, I don''t believe it! Do you realize what you''ve got here, $R? This is the horn of Margol the Rager! Margol, the bane of every archaeologist that ever set foot in the Searing Gorge.$B$BMay I keep it?',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (3201,1,1,0,0,0,0,0,0,'I don''t know how someone as weak as you overcame Margol, but a deal is a deal. Here is the key.$B$BIf anything happens to you after this, it will be your own fault.',12340),
	 (3221,1,0,0,0,0,0,0,0,'Ah, very good. There is a matter regarding the wolf hearts you brought to me earlier that demands our attention.',12340),
	 (3261,1,0,0,0,0,0,0,0,'Greetings, young one.  You are here to walk the hunter''s path?$B$BVery good.  Let us begin.',12340),
	 (3281,1,0,0,0,0,0,0,0,'Aha! So the raptors did hide the silver at their lair. It''s hard to believe these beasts would have the desire for silver. Perhaps the stories of their intelligence are not as far from the mark as I thought!$B$BThank you, $N. Take this as a reward for your service to us, and know that the guards of the crossroads owe their next month''s pay to you.',12340),
	 (3301,6,1,2,0,0,0,0,0,'Ah, what is this? This shell has an inner glow, as if it still pulses with life. Amazing! I must study it further.$B$BThank you, $N. With luck, this shell will hold a secret I can use to aid the poor land of Silverpine.',12340),
	 (3321,0,0,0,0,0,0,0,0,'Rise and be recognized, $N, blacksmith of the Mithril Order.',12340),
	 (3341,0,0,0,0,0,0,0,0,'The loyalty of a Lich is unswerving, $N. Let them know that such loyalty will only bring them destruction.',12340),
	 (3361,4,0,0,0,0,0,0,0,'Huzzah, you''ve found them! You''re an absolute savior, my friend. Here, it''s not much, but it''s something for the trouble I''ve put you through! Thank you!',12340),
	 (3362,6,0,0,0,0,0,0,0,'They''re that big? I might have to rethink my plan...$b$bBut you did hold up your end of the bargain, so here''s what I promised.',12340),
	 (3363,0,0,0,0,0,0,0,0,'You apply some Cenarion plant salve to the songflower. It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (3364,4,0,0,0,0,0,0,0,'Ah good, now this will hit the spot. Allow me to take a small break while I enjoy this scalding mornbrew!',12340),
	 (3365,4,0,0,0,0,0,0,0,'Excellent, $N! You''d be surprised how many couriers I meet who forget to do something as simple as bring back the mug. Mugs don''t grow on trees, or so they tell me!$b$bHere''s a little something for the effort. Thanks again for your help.',12340),
	 (3367,0,0,0,0,0,0,0,0,'This letter was dropped by Dorius when he was shot.',12340),
	 (3368,5,0,0,0,0,0,0,0,'<Thorius wipes his face dry.>$B$BIn the name of the Light, he will have his wish. This I vow.',12340),
	 (3369,6,1,1,1,0,0,2000,0,'Falla sent you to me? Well now, let''s see that shard that you say she was so hesitant to talk about...$B$B<Hamuul peers into the shard>$B$BOh... I didn''t... Well.$B$B$N, thank you for delivering this to me. It isn''t wise to speak of things such as this, though, I advise you. These are matters that you should not concern yourself with.$B$BLet''s just say that things in the Emerald Dream are not as we thought...$B$BPerhaps in the future, our paths may cross again.$B$B',12340),
	 (3370,6,1,1,1,0,0,2000,0,'Falla sent you to me? Well now, let''s see that shard that you say she was so hesitant to talk about...$B$B<Mathrengyl peers into the shard>$B$BOh... I didn''t... Well.$B$B$N, thank you for delivering this to me. It isn''t wise to speak of things such as this, though, I advise you. These are matters that the Cenarion druids alone must attend to.$B$BLet''s just say that things in the Emerald Dream are not as we thought...$B$BPerhaps in the future, our paths may cross again.',12340),
	 (3371,0,0,0,0,0,0,0,0,'Forget about me, help the others.',12340),
	 (3372,0,0,0,0,0,0,0,0,'You place the mysterious artifact on the altar of Suntara.',12340),
	 (3373,0,0,0,0,0,0,0,0,'You place the gem inside the essence font.$B$B"Thank you mortal, you have - no... this, this cannot be! No!  The corruption of this accursed god even taints the sanctity of a Green Dragonflight essence font!  No please, I feel my essence ripping from me!  THE PAIN!  I feel the grip of an eternal nightmare taking hold on me..."$B$B"Mortal, I implore you!  Find one of the Green Dragonflight to stop this... help me... I am chained in darkness... forever in agony... please do not torture..."',12340),
	 (3374,0,0,0,0,0,0,0,0,'You have made your choice, and so it begins. Your choices have been, to date, what I would consider to be the correct ones; your actions and deeds henceforth will determine whether this is to continue.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (3375,1,0,0,0,0,0,0,0,'The mighty adventurer delivers. Hooray for me. By the way, I lied - I had another phial. Ungh, take it.$B$BWell, what did you expect?! "Oh, here, have another one! I''m just some goofball who has nothing better to do than hand out magical communication devices to adventurers!" Rest assured though, what you have given to me will be enough make you another phial when you lose that too.$B$BPlease prove me wrong and don''t lose the new one, okay?',12340),
	 (3376,0,0,0,0,0,0,0,0,'Justice has been served on this day by your swift actions, $N.  Let this deed serve as a warning to all who would threaten our home.$b$bYou have earned this reward to help you on your sojourn, young $c.',12340),
	 (3377,0,0,0,0,0,0,0,0,'I have accepted my fate here in this cage, but the prayer must be found.',12340),
	 (3378,2,0,0,0,0,0,0,0,'Elune smiles upon you this eve, $N. You have returned a lost soul to her. Please accept this as a token of our gratitude.',12340),
	 (3379,1,1,0,0,0,0,0,0,'Excellent work, $N.$B$BI am sure that this is a piece of shadoweave that you have not yet seen.',12340),
	 (3380,0,0,0,0,0,0,0,0,'Yes, the Sunken Temple, I can say that I have seen it with my own eyes. Perhaps you''d like to hear more about it?$b$bYou look like the adventurous type -- I know things that may intrigue you...',12340),
	 (3381,0,0,0,0,0,0,0,0,'Two feathers, just as I asked. And not bad ones at all.$b$bReady then? Just say the word and you''re on your way.$b$bOh, and once again, mind yourself... my master doesn''t take kindly to imbeciles, but he is very generous to those that please him.',12340),
	 (3382,0,0,0,0,0,0,0,0,'You''ve done it! Thank you! Surely this was one of the most brutal battles I''ve ever taken part in. I can''t thank you enough.$B$BI only wish more of my crew could have lived through this trial.$B$BI would ask you to speak to any surviving passengers from the Horizon Scout. Some of them had business in the area, and may have a request or two of you if you''re willing. Again, thank you for all your help.',12340),
	 (3385,5,1,1,0,0,0,0,0,'You have struck a decisive blow against the Undermarket. Their leaders will think twice before sending more cronies into the gorge.$B$BOh, and I also found nothing of use in the trader''s satchel. You may keep whatever you find inside.',12340),
	 (3402,4,4,5,0,0,0,0,0,'Kovic slain??! This is a glorious day, $N! For years that scoundrel has been running shady undermarket trades, undercutting honest, hard working traders all over the world.$b$bYou deserve a fine reward for this accomplishment! And a fine reward you shall have!',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (3421,1,1,0,0,0,0,0,0,'I will return you to Sanath''s camp now.$B$BDo not mind his bad manners--he is rude to everyone save for the master. Perhaps he shall learn his lesson one day.',12340),
	 (3441,0,0,0,0,0,0,0,0,'Have you heard enough? Are you prepared to act?',12340),
	 (3442,21,1,1,0,1000,500,0,0,'Well done, $N. We are almost ready.',12340),
	 (3443,1,1,0,0,0,0,0,0,'You''re an exceptional laborer, $N. Have you ever considered a change of vocation? Perhaps a detective? Junk collector? Oh, I know, one of those silly gnomes that crawl across the beaches of Azeroth with their metal detecting contraptions, looking for lost treasure. Yes, that would be an ideal position for you.',12340),
	 (3444,4,0,0,0,0,0,0,0,'Yes... This is the stone.$b$bIt''s all coming back to me now, $N...',12340),
	 (3445,0,0,0,0,0,0,0,0,'Yes, the Sunken Temple, I can say that I have seen it with my own eyes. Perhaps you''d like to hear more about it?$b$bYou look like the adventurous type -- I know things that may intrigue you...',12340),
	 (3446,0,0,0,0,0,0,0,0,'You push the stone circle into the opening, and you hear it lock into place.$b$bNow that the stone is in place, you may continue... but what should you do next?$b$bPerhaps you should examine this altar further...$b$b',12340),
	 (3447,0,0,0,0,0,0,0,0,'The eye of the idol glitters brightly even in the half-darkness of the temple. Its transparency reveals something shiny behind it. Sliding it to the side, you reach in and grasp what lies inside the statue.$B$BThe Atal''ai treasure is now yours.',12340),
	 (3448,6,1,1,0,0,0,0,0,'Ah, Karnik sent you, did he? I expected to hear from him soon. I''ve discovered such wonderful things about Azshara.. I know night elves have incredible life spans, but everyone forgets some of the more... unfortunate events in their lives sometimes. That''s not meant as a criticism, just an observation.$B$BLong ago, there were cities created by the elves filled with knowledge about magic and other lost arts. Being a student of such things, I started my investigation. What I found was quite thrilling.',12340),
	 (3449,1,1,0,0,0,0,0,0,'Good to see you safe and sound, $N. I hope things weren''t too tough for you.$B$BI''ll get these to Tymor right away. He''ll be thrilled to take a look at these things.$B$BGo ahead and toss the flare gun... probably won''t be any good to you anymore anyway, and I already got a new one.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (3450,6,1,0,0,0,0,0,0,'What can I do for you, $N? Kinda busy at the moment preparing my ship for a long trip. I just came over to see some of the tank pilots--I need some wendigo manes to line my cockpit and they usually have extra.$B$BI can give you a minute if you''re brief... one of the boys just took off to Steelgrill''s Depot to see if the pilots down there have extra manes for me.',12340),
	 (3451,1,1,1,0,0,0,0,0,'Here''s my standard issue flare gun, and be patient after you fire off the gun--there are only a couple charges in one of these, and it might take me a minute to get to you depending on how far out to sea I am. Just look out to sea after you fire off the flare.',12340),
	 (3452,1,1,0,0,0,0,0,0,'The symbol radiates foul magic; perfectly suited for our task.',12340),
	 (3453,1,1,0,0,0,0,0,0,'There is one final task that you must complete.
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (3501,0,0,0,0,0,0,0,0,'You truly disgust me, $r. A grown $g man : woman; drooling over a pile of junk? Pitiful! Take your reward and get out of my sight.',12340),
	 (3502,0,0,0,0,0,0,0,0,'You truly disgust me, $r. A grown $g man : woman; drooling over a pile of junk? Pitiful! Take your reward and get out of my sight.$B$BSounds familiar? It should, because I say it a thousand times per day.$B$BOh how I loathe this world.',12340),
	 (3503,1,6,0,0,0,0,0,0,'There was a time when I could ask whatever I wished from those who sought out my master.  But now, you need only ask and I will send you to him.$b$bIt is upsetting to me, but I do not question his orders.  I can only take enjoyment in making fun of the ridiculous clothes you wear or the pathetic look on your face.  Even that bores me...$b$bEven this rambling bores me!  Do you wish to see my master or not?',12340),
	 (3504,0,0,0,0,0,0,0,0,'We''ve sent everything we had at her and her workers, but they are strong in battle. None have bothered to return. I''m assuming some have died, but I''m sure others simply ran... cowards.$b$bBut now that reinforcements have arrived, perhaps there''s still something we can do. Perhaps we can still punish her for lying and betraying Belgrom.$b$bWhat do you say, are you in?',12340),
	 (3505,0,0,0,0,0,0,0,0,'You begin to skim some of the pages until you come to a page that''s marked by a thin, black strip of silk cloth.$b$bAs you try to decipher the script, you see a diagram on the bottom of one of the pages. A quick look around at the scene before you and you realize that the crystals, the circle, and even some of the other components on the ground are set up in a similar pattern as the diagram.',12340),
	 (3506,0,0,0,0,0,0,0,0,'RAR!! Incredible!$b$bYou''ve done it! Belgrom will be pleased! Finally the spirits of dozens of our warriors can be at peace. Thank you, $N.',12340),
	 (3507,0,0,0,0,0,0,0,0,'HAHA! Look at you now, pathetic woman! I spit on your remains!$b$bThank you, $N. Thank you from the bottom of my heart! This is indeed a great day!$b$bI would give you a kingdom if it were in my power! But perhaps you will settle for this.$b$b<Belgrom looks down at the head of the mage who had betrayed him.>$b$bHaha! Stupid blood elf, look at you now... in a burlap sack and missing your body! You should never have betrayed Belgrom!',12340),
	 (3508,0,0,0,0,0,0,0,0,'The name of the beast must be found.',12340),
	 (3509,0,0,0,0,0,0,0,0,'A demon lord?$b$b<Lord Arkkoroc laughs.>$b$bPerhaps the one can assist you with this information; but first, you must assist the one.$b$b',12340),
	 (3510,0,0,0,0,0,0,0,0,'Finally, one worthy of the wisdom of Arkkoroc!',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (3511,0,0,0,0,0,0,0,0,'The temper will add the necessary vitriol we require for the forging of the weapons. There is but one more step in their creation.',12340),
	 (3512,1,0,0,0,0,0,0,0,'Itharius was wise to send you to me. While he is not dead as you understand death, Eranikus will soon give us advice in his own words. For now though, I cannot directly help you... at least not yet.$b$bI will lend my skill at death-speaking to you, but first I need the help of one who - unlike me - is not limited by the frailties of old age. My most potent augury device has been taken from me against my will, and unless I have it back we will be at a loss to help Eranikus.',12340),
	 (3513,6,0,0,0,0,0,0,0,'Well now... Where did you find this?',12340),
	 (3514,4,1,2,0,0,0,0,0,'You''re a tough one! Ridding the Den of Rynthariel is a major step, $N. They will be slow to regroup, and so we can count on less Alliance runners in the Barrens. They will think again before sending another this way.$B$BThank you.',12340),
	 (3517,0,0,0,0,0,0,0,0,'Perfect, $N, and in good condition also. These should get us a good price from all the parties concerned.$b$bLet''s not dawdle around here any longer than we have to. We have some money to make.',12340),
	 (3518,0,0,0,0,0,0,0,0,'Ah, at long last, the Tablet of Beth''Amara. I was wondering if my partnership with Jediga had failed or if the poor orc had found her death in Azshara. I am glad she was successful.$b$bBeth''Amara was one of the Highborne''s most influential alchemists. The wizard alone was said to have mastered transmuting metals among other things.',12340),
	 (3519,0,0,0,0,0,0,0,0,'Oh dear; I was wondering why I hadn''t seen Iverron yet today. And I''ve always warned him about those spiders...',12340),
	 (3520,2,0,0,0,0,0,0,0,'You have done well, $N.  Perhaps now it is time to reveal more...$B$BThere is an ancient prophecy among the trolls, where the dead god Hakkar, the Soulflayer, will one day return to this earth.  Some say the coming of Hakkar will bring joy and glory to trollkind, while others believe his resurrection marks the end of all things.$B$BI do not believe this myth, but I do know the essence of Hakkar holds great power, and this power should be kept from those who would abuse it...',12340),
	 (3521,2,0,0,0,0,0,0,0,'Thank Elune that you have gathered these ingredients so quickly!$b$bIn just a moment, I will have the antidote prepared.',12340),
	 (3522,0,0,0,0,0,0,0,0,'What is this, $N?$b$bOh, I knew Dirania would be able to help me!$b$b<Iverron drinks the antidote>$b$bI''m always getting into trouble and Dirania, well, she always manages to help me out of it.$b$bI am feeling much better, but I think I will sit here for a while longer, until I feel completely better. Well, that, and I was hoping you''d clear a path for me through those vicious Webwood spiders...',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (3523,0,0,0,0,0,0,0,0,'Fantastic, I thought you looked to be the heroic type!  We''ve got our work cut out for us $N, I''m not going to lie to you.  If we stay focused on the task at hand, we should be able to come out on top.$B$BNow, let me bring you up to speed on what''s been going on...',12340),
	 (3524,1,0,0,0,0,0,0,0,'I hope the murloc did not give you much trouble in collecting this for us! I will be sure to get this on the next hippogryph to Darnassus. The Temple of the Moon has given me some funds to hand out for assistance; please have some with our thanks.$B$BYour success here emboldens me to offer you a chance to aid the Temple of the Moon further, if you are interested...',12340),
	 (3525,0,0,0,0,0,0,0,0,'Belnistrasz''s sudden departure has left behind a burning brazier.  As you stare in to the flame, the image of a great-winged red dragon fills your mind.  A more graveled version of Belnistrasz''s voice speaks directly to you.$B$B"Indeed mortals, you are the heroes I had hoped you would be.  Thanks to you the butchery these beasts were perpetrating is a thing of the past.  My faith in mortals such as yourself has been once more renewed.  Take this as a reward befitting of a hero."',12340),
	 (3526,25,1,0,0,0,0,0,0,'Well $N, you were wise to seek my tutelage! Any schlep can become an expert at the basics of engineering - the gnomes and their irradiated home of Gnomeregan are proof of that. It takes a strong mind and a steady hand (emphasis on STEADY) though to master the discipline of Goblin Engineering.$B$BKeep your ears perked $N, and you might learn something.',12340),
	 (3527,1,0,0,0,0,0,0,0,'Ah, this is good. I can fuse these ancient tablets together, and then study their hidden secrets.$b$bMy debt to you grows, $N. And it will grow further still.',12340),
	 (3528,5,1,1,0,0,0,0,0,'The essence of Hakkar has been collected! Even now the Egg stirs with life! Could the myths of Hakkar be true?$b$bThat must not be true, for it is then I fear what Hakkar may do if birthed again. I will keep this egg safe and be sure it does not fall into evil hands.$b$bYour labors with me are finished, $N. You have touched a legend, and your actions may one day change the face of our world.',12340),
	 (3541,0,0,0,0,0,0,0,0,'Ahhh, Jediga be sendin'' her package all the way from Azshara. Good. I be waitin'' on this.$B$BJediga, now that be a fine woman... deadly too. What could be better?$B$BLook at this... the tablet be in perfect condition. You make a good messenger, $N.',12340),
	 (3542,0,0,0,0,0,0,0,0,'Here, take some coin... get yerself... <hic>... some new armor or something....$b$bThis''ll bring a shiny gold or two to the right... <hic> people.',12340),
	 (3561,0,0,0,0,0,0,0,0,'Ah, the Tablet of Sael''hai... how long I''ve longed to study it.$b$bThank you, $N. You may tell Jediga that she has done well. This will definitely be worth the payment she asked for.',12340),
	 (3562,0,0,0,0,0,0,0,0,'Ah, good. She was much more reasonable than I expected... at least towards you. I half expected her to have you punished for my insolence in sending someone in my place. She must really want that tablet. Interesting.$b$bSomething to ponder another time.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (3563,0,0,0,0,0,0,0,0,'I can see he was more than pleased by the looks of his note.... a little too pleased.$B$BPerhaps some day I''ll take time to make sure he knows how much I appreciate his advances also. Well, at least there''s one reason to look forward to spending more time in Azshara.$B$BHere''s your share of our payment.',12340),
	 (3564,0,0,0,0,0,0,0,0,'Perfect... wait a minute.$b$bHaha! What''d you tell him when you delivered the tablet, $N? He overpaid us way too much! Not that I''m complaining. Did you tell him the deal changed? Or was he drunk again?$b$bDoesn''t matter... here, take an extra share also.',12340),
	 (3565,0,0,0,0,0,0,0,0,'No problems? None at all? Well, that''s something to be said... I expected him to show some sort of reluctance or to at least betray our deal. Hmm, maybe he can be trusted after all.$b$bWell, no need to dwell on it that much. Here''s your share. Thank you for your help.',12340),
	 (3566,5,18,0,0,0,0,0,0,'<Thorius'' face turns white.>$B$BThis... this cannot be. My own brother? He set this all up?$B$B<Thorius'' face contorts in anger.>$B$BHe betrayed me, he betrayed Ironforge! It seems as if the influence of the Old Gods is still strong in these lands. I fear that if my brother - a once noble and honorable man - was so easily turned to the will of Ragnaros, no one is safe.',12340),
	 (3567,0,0,0,0,0,0,0,0,'Would you like to see the view atop one of the twin colossals? I can send you there, $R.$B$BDo consider how you will get down, though. This is a one way trip only.',12340),
	 (3568,0,0,0,0,0,0,0,0,'Wonderful. You''re back before she died. Good, good.$B$BLet''s get started on this then, shall we?$B$BI''ve been studying her symptoms for some time now, and it''s quite ugly. I''m surprised she''s still standing. She''s vomited three or four times all over the place... quite a pleasant odor.$B$BGive me just a moment to put something together to test on our... friend.',12340),
	 (3569,1,0,0,0,0,0,0,0,'Chemist Cuely has been very accommodating... disturbingly so. But if he says this will help me, then I have no other choice. I don''t have time to find any other solution. I''ve already spoken to priests and shamans, none of which could help me.$B$BLet us hope that the Earthmother watches over my spirit.',12340),
	 (3570,4,11,0,0,0,0,0,0,'I never dreamed the elixir would take hold that quickly. Thank you, $n. I will get to work on the rest of these samples right away. I''m sure they''ll be usable by the Lady Sylvanas and the Forsaken soon enough.',12340),
	 (3601,0,0,0,0,0,0,0,0,'Haha! You got them good, didn''t you?!$b$bThis is great! That''ll teach those Blood elves to betray their partners... especially someone as loyal as a goblin merchant! Bah, Blood elves...!$b$bWell, the least I can do for you is pay you for your time... just like I said I would.$b$bHere you go... those should be useful.',12340),
	 (3602,0,0,0,0,0,0,0,0,'Your tasks in Azshara are complete, mortal. I must now forge the necessary components for the next step in your adventure.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (3621,5,0,0,0,0,0,0,0,'My goodness, I can only imagine what you went through to get these materials. Few venture into Azshara and return alive, let alone those that face demi-gods and giants!$b$b',12340),
	 (3625,1,0,0,0,0,0,0,0,'<Galvan wipes the sweat from his brow.>$b$bA finer demon slayer has never existed, $N.',12340),
	 (3626,1,0,0,0,0,0,0,0,'You look battle hardened, $N. Are you prepared to face Razelikh and his minions?',12340),
	 (3627,0,0,0,0,0,0,0,0,'The amulet of Razelikh the Defiler is once again complete but he senses the disruption in his chain of command. He knows you come for him...',12340),
	 (3628,66,0,0,0,0,0,0,0,'Today is a day that will be remembered for all eternity. The demonic overlord of the Blasted Lands has finally fallen!',12340),
	 (3629,25,1,0,0,0,0,0,0,'Well $N, you were wise to seek my tutelage! Any schlep can become an expert at the basics of engineering - the gnomes and their irradiated home of Gnomeregan are proof of that. It takes a strong mind and a steady hand (emphasis on STEADY) though to master the discipline of Goblin Engineering.$B$BKeep your ears perked $N, and you might learn something.',12340),
	 (3630,1,2,0,0,0,0,0,0,'Ah, a young engineer interested in pursuing the one, true discipline of engineering! Well forgive my melodrama, friend. While our situation remains dire, it still is always a good day to see another engineer respond to the clarion call of true engineering!',12340),
	 (3631,0,0,0,0,0,0,0,0,'Good luck, $N. I look forward to seeing you in the future.',12340),
	 (3632,1,2,0,0,0,0,0,0,'Ah, a young engineer interested in pursuing the one, true discipline of engineering! Well forgive my melodrama, friend. While our situation remains dire, it still is always a good day to see another engineer respond to the clarion call of true engineering!',12340),
	 (3633,25,1,0,0,0,0,0,0,'Well $N, you were wise to seek my tutelage! Any schlep can become an expert at the basics of engineering - the gnomes and their irradiated home of Gnomeregan are proof of that. It takes a strong mind and a steady hand (emphasis on STEADY) though to master the discipline of Goblin Engineering.$B$BKeep your ears perked $N, and you might learn something.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (3634,1,2,0,0,0,0,0,0,'Ah, a young engineer interested in pursuing the one, true discipline of engineering! Well forgive my melodrama, friend. While our situation remains dire, it still is always a good day to see another engineer respond to the clarion call of true engineering!',12340),
	 (3635,6,1,0,0,0,0,0,0,'You''ve come to learn about gnome engineering, eh? Well, you''ve come to the right gnome. While the ruling faction of Gnomeregan may use politics to ostracize those they view as an intellectual threat, they know that knowledge is something they cannot control.$B$BThey and I both know that when I left Gnomeregan, they lost one of their greatest gnome engineers alive today. If you''re a capable student, I''ll teach you what I know.',12340),
	 (3636,1,2,0,0,0,0,0,0,'Thank you , $N. The Scourge will now think twice before attempting to bolster its ranks again.$B$BMay you be blessed by the Light.',12340),
	 (3637,6,1,0,0,0,0,0,0,'You''ve come to learn about gnome engineering, eh? Well, you''ve come to the right gnome. While the ruling faction of Gnomeregan may use politics to ostracize those they view as an intellectual threat, they know that knowledge is something they cannot control.$B$BThey and I both know that when I left Gnomeregan, they lost one of their greatest gnome engineers alive today. If you''re a capable student, I''ll teach you what I know.',12340),
	 (3638,2,1,0,0,0,0,0,0,'Welcome aboard, Goblin Engineer $N! You soon will have access to the most powerful engineering schemata anywhere on Azeroth.$b$bNow that you have committed yourself to the pursuit of this knowledge, it is time to examine your goblin-oriented engineering work. From there, we''ll help you build a plan to maximize your goblin engineering talents!',12340),
	 (3639,0,0,0,0,0,0,0,0,'Here is your first Goblin Engineer Membership Card!$b$bThis card has its dues paid for in advance for fourteen days; all cards expire after two weeks of activity. When it does, pay your next set of dues to any goblin engineer trainer in order to get another card; without the card, your membership will temporarily lapse and you cannot access new schemata.$b$bThis never affects what you already know; once a goblin engineer, always a goblin engineer.',12340),
	 (3640,2,1,0,0,0,0,0,0,'Welcome aboard, $N! You soon will have access to the most advanced engineering schemata anywhere on Azeroth.$B$BNow that you have committed yourself to the pursuit of this knowledge, it is time to examine your gnome-oriented engineering work. From there, we''ll help you build a plan to maximize your gnome engineering talents!',12340),
	 (3641,0,0,0,0,0,0,0,0,'Here is your first Gnome Engineer Membership Card!$B$BThis card has its dues paid for in advance for fourteen days; all cards expire after two weeks of activity. When it does, pay your next set of dues to any gnome engineer trainer in order to get another card; without the card, your membership will temporarily lapse and you cannot access new schemata.$B$BThis never affects what you already know; once a gnome engineer, always a gnome engineer.',12340),
	 (3642,2,1,0,0,0,0,0,0,'Welcome aboard, $N! You soon will have access to the most advanced engineering schemata anywhere on Azeroth.$B$BNow that you have committed yourself to the pursuit of this knowledge, it is time to examine your gnome-oriented engineering work. From there, we''ll help you build a plan to maximize your gnome engineering talents!',12340),
	 (3643,0,0,0,0,0,0,0,0,'Here is your first Gnome Engineer Membership Card!$B$BThis card has its dues paid for in advance for fourteen days; all cards expire after two weeks of activity. When it does, pay your next set of dues to any gnome engineer trainer in order to get another card; without the card, your membership will temporarily lapse and you cannot access new schemata.$B$BThis never affects what you already know; once a gnome engineer, always a gnome engineer.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (3644,1,1,0,0,0,0,0,0,'Since you''re a practitioner of Goblin engineering and are in good standing, I am able to renew a lapsed membership card for the fee of two gold pieces. Once this fee is paid, you will be reissued a new membership card. This will allow access to Goblin engineering schemata from appropriate trainers.$B$BThis card will last for two weeks of activity, at the end of which your membership fees will become due again! If you want to access schemata, you''ll need to bring your dues out of arrears.',12340),
	 (3645,1,1,0,0,0,0,0,0,'Since you''re a practitioner of Gnomish engineering and are in good standing, I am able to renew a lapsed membership card for the fee of two gold pieces. Once this fee is paid, you will be reissued a new membership card. This will allow access to Gnomish engineering schemata from appropriate trainers.$B$BThis card will last for two weeks of activity, at the end of which your membership fees will become due again! If you want to access schemata, you''ll need to bring your dues out of arrears.',12340),
	 (3646,1,1,0,0,0,0,0,0,'Since you''re a practitioner of Goblin engineering and are in good standing, I am able to renew a lapsed membership card for the fee of two gold pieces. Once this fee is paid, you will be reissued a new membership card. This will allow access to Goblin engineering schemata from appropriate trainers.$B$BThis card will last for two weeks of activity, at the end of which your membership fees will become due again! If you want to access schemata, you''ll need to bring your dues out of arrears.',12340),
	 (3647,1,1,0,0,0,0,0,0,'Since you''re a practitioner of Gnomish engineering and are in good standing, I am able to renew a lapsed membership card for the fee of two gold pieces. Once this fee is paid, you will be reissued a new membership card. This will allow access to Gnomish engineering schemata from appropriate trainers.$B$BThis card will last for two weeks of activity, at the end of which your membership fees will become due again! If you want to access schemata, you''ll need to bring your dues out of arrears.',12340),
	 (3661,2,0,0,0,0,0,0,0,'Thank you for bringing these to me, $N.$B$BWhat did you learn of the Wildkin?$B$BPerhaps these feathers will tell us more. Ferocious monsters, or simply misguided pets? One day I''d like to know the truth...$B$BI am going to continue my research -- please come back and talk to me again after some time has passed.',12340),
	 (3681,0,0,0,0,0,0,0,0,'Welcome to the Cathedral of Light, $C.',12340),
	 (3701,5,0,0,0,0,0,0,0,'Oh my! This information explains quite a lot about Thaurissan.$B$BThere is much more to learn!',12340),
	 (3702,6,0,0,0,0,0,0,0,'Shall we proceed?',12340),
	 (3721,0,0,0,0,0,0,0,0,'You''ve recovered three of my OOX homing robots!  You''ve gone above and beyond what you needed to, so I will give you something special for all your help.  It is a miniature version of the very same robot that you have come to know and love, the OOX!$B$BI normally wouldn''t let anyone have such a potentially lethal device, but you''ve been a real help.  Besides - the combat mechanisms and the homing logic on this one have been disabled.$B$BOther than that, it''s an OOX by golly!',12340),
	 (3741,4,1,6,0,0,0,0,0,'Thank you for finding my necklace mister $C... you are very kind! My kitty thanks you too - isn''t that right Effsee?',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (3761,0,0,0,0,0,0,0,0,'Oh that''s right Private $N, don''t make any effort to help me unload this soil up on to the piles! If the Great Spirits had wanted it done they would have miracled it up there, now wouldn''t they?!$B$BArch Druid Runetotem wants to speak with you again, but for his next task you find that a journeyman''s understanding of Herbalism would be helpful. If you don''t know it though, he''ll still find a use for you.',12340),
	 (3762,2,0,0,0,0,0,0,0,'Greetings, $C; I am glad you are interested in assisting our research. There is much to do, and I would be doing you a disservice if I informed you that the work this entails is not dangerous. Hopefully this will not scare you off... but from the looks of you, I take it that danger is something that you have dealt with before.',12340),
	 (3763,1,0,0,0,0,0,0,0,'Well now, $c... since you were informed that I was leading this research myself, you obviously came as quickly as you could.$B$BNow that you are here, be sure to pay attention the first time I tell you the details; I have no desire to repeat myself.',12340),
	 (3764,1,0,0,0,0,0,0,0,'Unload your precious cargo here, noble $C. It must have been quite the burden... not unlike the burden I carry being a visionary. Here is an honorarium for your work, as dictated by the Arch Druid himself.$B$BArch Druid Staghelm wants to speak with you again $N, but for his next task you will be aided if you have a journeyman''s understanding of Herbalism. If you don''t know it though, you will still be able to aid the Circle!',12340),
	 (3765,6,0,0,0,0,0,0,0,'Ah, so my brother, Argos, sent you? I realize you must be weary from your travels. But we have much to talk about.',12340),
	 (3781,1,0,0,0,0,0,0,0,'Yes, this voucher is good for twenty packets of seeds. If you run out, we have more that can be provided. Unfortunately though, Tharlendris seeds are quite costly to produce in significant numbers. This is why the Cenarion Circle asks that those who are assisting us help out by offsetting some of the cost.$B$BThose who return with morrowgrain find that the reward the Arch Druid offers far makes up for the cost.',12340),
	 (3782,1,0,0,0,0,0,0,0,'Yes, this voucher is good for twenty packets of seeds. If you run out, we have more that can be provided. Unfortunately though, Tharlendris seeds are quite costly to produce in significant numbers. This is why the Cenarion Circle asks that those who are assisting us help out by offsetting some of the cost.$B$BThose who return with morrowgrain find that the reward the Arch Druid offers far makes up for the cost.',12340),
	 (3783,1,0,0,0,0,0,0,0,'These furs are perfect, $N. We''re off to a great start here!',12340),
	 (3784,2,0,0,0,0,0,0,0,'Greetings, $C; I am glad you are interested in assisting our research. There is much to do, and I would be doing you a disservice if I informed you that the work this entails is not dangerous. Hopefully this will not scare you off... but from the looks of you, I take it that danger is something that you have dealt with before.',12340),
	 (3785,4,0,0,0,0,0,0,0,'Well done $N, I will be sure to give these to the Arch Druid himself when he has need of them. Meanwhile, please accept this as a token of the Cenarion Circle''s appreciation.$b$bOur need for morrowgrain, for now, is constant; if you wish to continue aiding us, then please return when you have cultivated more of it.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (3786,4,0,0,0,0,0,0,0,'Well done $N, I will be sure to give these to the Arch Druid himself when he has need of them. Meanwhile, please accept this as a token of the Cenarion Circle''s appreciation.$B$BOur need for morrowgrain, for now, is constant; if you wish to continue aiding us, then please return when you have cultivated more of it.',12340),
	 (3787,2,1,0,0,0,0,0,0,'I thank you for coming, weary traveler!  Allow me to introduce myself - I am Quintis Jonespyre, druid and humble servant of Malfurion and the Cenarion Circle.  My colleagues (General Shandris Feathermoon and the Protectorate - mayhap you''ve heard of us) and I wanted to talk with you about the work you are doing for Fandral Staghelm in Darnassus.$B$BBefore we get much further, I''d like to ask that our discussion stay between just us.  If you have no problem with this, then we may proceed.',12340),
	 (3788,2,1,0,0,0,0,0,0,'I thank you for coming, weary traveler!  Allow me to introduce myself - I am Quintis Jonespyre, druid and humble servant of Malfurion and the Cenarion Circle.  My colleagues (General Shandris Feathermoon and the Protectorate - mayhap you''ve heard of us) and I wanted to talk with you about the work you are doing for Fandral Staghelm in Darnassus.$B$BBefore we get much further, I''d like to ask that our discussion stay between just us.  If you have no problem with this, then we may proceed.',12340),
	 (3789,1,0,0,0,0,0,0,0,'Well now, $C... since you were informed that I was leading this research myself, you obviously came as quickly as you could.$B$BNow that you are here, be sure to pay attention the first time I tell you the details; I have no desire to repeat myself.',12340),
	 (3790,1,0,0,0,0,0,0,0,'Well now, $C... since you were informed that I was leading this research myself, you obviously came as quickly as you could.$B$BNow that you are here, be sure to pay attention the first time I tell you the details; I have no desire to repeat myself.',12340),
	 (3791,6,1,0,0,0,0,0,0,'Gah, these morrowgrain make me feel... weird.  What in the name of Elune is Staghelm up to with these things?$B$BAnyway, thank you again for your help.  Here''s a little something... you know, for the effort.  My research on morrowgrain is going to take a while, and I no doubt am going to need more.  While I''m at it, I suppose I could take the time to see if morrowgrain have some pertinent alchemical uses.  Still, I feel uncomfortable even being around them.',12340),
	 (3792,2,1,0,0,0,0,0,0,'Thanks $N; I''ll just store these out of the way for the time being.  While I don''t command the resources that Staghelm does, I am able to give you a little something for your trouble.  Anyway, who knows what will happen if Staghelm keeps getting Morrowgrain after Morrowgrain.  There''s something fishy going on, mark my words.$B$BRemember that I''m always looking for more Morrowgrain.  I''ll take them in quantities of five at a time.',12340),
	 (3801,1,1,1,0,0,0,0,0,'Whether it is greed which brought you here or an act of selfless devotion, what you are about to undertake is for the good of us all. ',12340),
	 (3802,0,0,0,0,0,0,0,0,'The hammer slides firmly into place, within the grasp of the massive Dark Iron monument. A tiny compartment opens at the base of the statue. Inside you find...',12340),
	 (3803,4,0,0,0,0,0,0,0,'Excellent - this morrowgrain will no doubt please the Arch Druid.  I must admit though... just being near them makes me feel a little uncomfortable.  I can only imagine how difficult it is for the Arch Druid to tolerate them in such large numbers!$B$BThis is for you, $N.  The Cenarion Circle thanks you for your continued support.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (3804,4,0,0,0,0,0,0,0,'Excellent - this morrowgrain will no doubt help when the time comes.  We know that the night elves are conducting similar research into these herbs, though it isn''t clear to what end they will use them for if they discover anything.  The Arch Druid thinks that the need for morrowgrain will remain until we''ve figured out the mysteries behind this herb.$B$BThis is for you, $N.  The Cenarion Circle thanks you for your continued support.',12340),
	 (3821,1,0,0,0,0,0,0,0,'My poor Thal''trak.$B$BWe were planning on moving in with my mother and father in the Hinterlands after our tours were over. Now those plans are ruined!',12340),
	 (3822,1,18,0,0,500,0,0,0,'<Thal''trak collapses.>$B$BWe were going to move to the Hinterlands. Did she tell you? This was going to be her last mission.$B$B<Thal''trak sobs.>$B$BI don''t want it, $N. Keep it, throw it away, I don''t care! The ring means nothing to me now. Not without her...',12340),
	 (3823,5,0,0,0,0,0,0,0,'Outstanding, soldier! The orcs and ogres will be reeling from this blow for minutes, maybe even hours!',12340),
	 (3824,5,11,0,0,0,0,0,0,'Just look at it, soldier. Disgusting! When the remaining Firegut ogres see this fat mug stuck on a pike sitting at the top of their mountain, mass hysteria will ensue!$B$B<Oralius cackles wildly.>',12340),
	 (3825,66,5,0,0,0,0,0,0,'Outstanding work, soldier! Simply amazing! Oh I''ll get the medal of bravery for this, er, I mean you''ll be rewarded handsomely for this!',12340),
	 (3841,1,1,6,0,0,0,0,0,'Ah, a sprite darter egg, and one near maturation, if I''m not mistaken. Remarkable you''ve found one, let alone in this good a condition. They''re rarely seen in Feralas these days. I understand there were various poachers in the area trying to capture and kill them for many reasons. Too bad really... such beautiful creatures when they reach adulthood.$B$BHow did you come across such a find?',12340),
	 (3842,21,0,0,0,0,0,0,0,'Wonderful. These will do nicely. Give me a moment to mix together my components and we shall see how well this egg is going to do.',12340),
	 (3843,1,1,0,0,0,0,0,0,'Well, well, well... I haven''t seen one of these in a dragon''s age. Faerie dragon, if I''m not mistaken... looks to be of the sprite darter variety. Excellent, excellent indeed.$B$BWell, if this little fella''s gonna hatch and live to be strong and healthy, then we should get some food for it. Good ya got it to me in time.',12340),
	 (3844,0,0,0,0,0,0,0,0,'A water-logged pack rests at the bottom of the pond.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (3845,1,0,0,0,0,0,0,0,'Oh... Yes, these things do look familiar... well, kind of...',12340),
	 (3861,0,0,0,0,0,0,0,0,'"BACAW!!!"$B$BThe chicken starts to gobble up the feed you put down.$B$BAfter a moment, the chicken looks around, startled. It uncomfortably shuffles back and forth. Is this chicken pregnant? You think you better check underneath it.',12340),
	 (3881,4,0,0,0,0,0,0,0,'You got both our foodstuff AND our research equipment back!  You''ve not only saved the expedition, you''ve also saved our lives.  I and the rest of my team can''t thank you enough; we just might make it here for a while now thanks to you.$B$BWhile we don''t have much, I''m certainly not going to leave you high and dry for the invaluable help you''ve given us.  Thank you, $N - you''ve got a friend in Marshal Expeditions!
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (3905,1,4,0,0,0,0,0,0,'Let''s see here...$b$bOh my! Milly''s grapes have been saved! When she told me that brigands overran her vineyards I nearly despaired, but my faith in the Light did not waver!$b$bAnd through your bravery, we now have grapes for more wine! May the Light bless you, $N, and keep you safe!',12340),
	 (3906,0,0,0,0,0,0,0,0,'This cannot be... it must not be. The destruction of Pyron has merely lifted a veil. Within the depths of Blackrock is a much more insidious source of corruption.',12340),
	 (3907,0,0,0,0,0,0,0,0,'<Thunderheart clutches the Tablet of Kurniya.>$b$bRagnaros... here...$b$bThe elders were right to fear the corruption emanating from Blackrock Mountain. A general of the Old Gods! IN OUR WORLD! We must reassess our position here in Kargath. We must decide on whether we stay and fight or run for fear of a new sundering.$b$bBe weary of any further exploration in Blackrock Mountain, $N. A far greater evil than anything that exists in this world resides in those fiery depths.',12340),
	 (3908,1,0,0,0,0,0,0,0,'Well, of course I can temper this sword. While I''m working, you can explain what took Linken so long to get this to me. He''s not usually one to forget things...',12340),
	 (3909,1,0,0,0,0,0,0,0,'I''ll need one vial to make sure that this is truly the elixir... Yes... This is the stuff. ',12340),
	 (3911,0,0,0,0,0,0,0,0,'Wonderful! I will have these sent by courier to the Undercity at once!$B$BAs for you - here is payment, as promised. Keep the change, you filthy beast!',12340),
	 (3912,1,0,0,0,0,0,0,0,'It has been long since any have come to talk with me...',12340),
	 (3913,0,0,0,0,0,0,0,0,'You push on the stone firmly, and it slides away, revealing a small depression underneath it.$B$BPlacing Linken''s Sword into the depression, you realize that it fits perfectly...',12340),
	 (3914,4,6,0,0,0,0,0,0,'My sword... It''s finished!$b$bNow, if only I could remember why I needed this...$b$bHere, let me at least pay you for your work.',12340),
	 (3921,6,0,0,0,0,0,0,0,'Oh, what''s this? A samophlange, you say? What''s a samophlange??$B$BAh... but look at the way it moves when you handle it. And there''s the sound of intricate gears inside. Oh my! I want to fix it and see what it does, don''t you??',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (3922,4,0,0,0,0,0,0,0,'Great, you got them! Now I can get to work...',12340),
	 (3923,5,0,0,0,0,0,0,0,'What''s this? Why, it''s a samophlange! Where did you get this thing? Have you been poking around the Venture Company holdings in the Barrens?$B$BYou must be very brave, or very stupid.',12340),
	 (3924,4,1,0,0,0,0,0,0,'You got the manual! I can''t wait to read it and find out how to fix the Samophlange! I spoke with Sputtervalve in Ratchet--he wanted to thank you for your help, and wanted to reward your efforts.$B$BI want to thank you too, and if I ever get this thing fixed I''ll let you know...',12340),
	 (3941,5,0,0,0,0,0,0,0,'Stay where you are for just a moment... I am testing out a new combination of crystals...',12340),
	 (3942,3,0,0,0,0,0,0,0,'Hello, $C. Is there something I can help you with?',12340),
	 (3961,6,0,0,0,0,0,0,0,'Did J.D. help you at all?',12340),
	 (3962,2,1,1,0,0,0,0,0,'Thank you, $N.$B$BThe Golden Flame will now be returned back to my homeland, where it may be protected, never again to be used for evil.$B$BSince you did so much for me, I''d like you to have this. Without you, I''d still have no idea who I am!',12340),
	 (3981,1,0,0,0,0,0,0,0,'We haven''t got much time. Listen carefully, $R. What I have to tell you is classified and for your ears only.',12340),
	 (3982,1,0,0,0,0,0,0,0,'That was a close call. They have been alerted to your presence... more will surely come.',12340),
	 (4001,1,25,0,0,0,0,0,0,'This is a chance for the Horde to change the political climate of our war torn world forever. Listen carefully, $N.$B$BFailure of this mission is not an option.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (4002,0,0,0,0,0,0,0,0,'There is no going back beyond this point, $N.',12340),
	 (4003,18,0,0,0,0,0,0,0,'What have you done!',12340),
	 (4004,1,1,0,0,1000,0,0,0,'<Thrall is taken aback by the information you have presented to him.>$B$BA new threat now looms on the horizon. As Magni''s years dwindle down, the way shall be opened for this unborn Dark Iron to become ruler of Ironforge.$B$BYou have accomplished what I asked of you and for that, you shall be rewarded.$B$BNow leave me, $N! I must confer with Sylvanas and Cairne.',12340),
	 (4005,1,0,0,0,0,0,0,0,'Blazerunner, you say...$b$bYes, I am aware that a strong elemental resides in the charred center of the crater. We all just keep our distance; none have been able to penetrate the powerful aura that surrounds him. Many have been pushed from the rocky paths onto the ground below when trying to face him.',12340),
	 (4021,4,1,66,0,0,0,0,0,'You have done it! You have defeated the Kolkar!$B$BI will be sure Thrall receives word of your actions here, $N.$B$BStand tall. You do yourself, and the Horde, proud.',12340),
	 (4022,0,0,0,0,0,0,0,0,'<Cyrus examines the molt.>$B$BYou have proven that you are not entirely useless, mortal.',12340),
	 (4023,0,0,0,0,0,0,0,0,'<Cyrus examines the molt.>$B$BYou have proven that you are not entirely useless, mortal.',12340),
	 (4024,0,0,0,0,0,0,0,0,'<Cyrus snatches the fiery essence from your hands.>$B$BYES!$B$BTake your prize and be gone. Leave my sight at once!',12340),
	 (4041,11,0,0,0,0,0,0,0,'So, you pulled a fast one on ol'' Miblon, eh?',12340),
	 (4061,1,0,0,0,2000,0,0,0,'<Theodora lays the fragments out before her.>$b$b<Theodora carefully examines the fragments with an enormous monocle.>$b$bInteresting. Etched into the structural foundation of each of these fragments are... initials.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (4062,1,0,0,0,0,0,0,0,'<Lotwil''s face turns white.>$b$bI... I know these markings.',12340),
	 (4063,5,1,0,0,0,0,0,0,'What is this?!? This head is not flesh. This is some sort of dark iron creation: A shadow of Argelmach - ANOTHER machine! I suspect that your destruction of Argelmach will be short lived as another shall rise to take ''its'' place soon.',12340),
	 (4081,1,25,0,0,0,0,0,0,'This first strike should put a crease in Angerforge''s pants. Now, move along soldier. I have work to complete, battles to plan, enemies to crush!$B$BCheck the wanted signs for more work.',12340),
	 (4082,1,1,0,0,0,0,0,0,'Angerforge is undoubtedly... angry. Return to me when you receive a third tribute and we shall proceed with Operation: Death to Angerforge. I cannot go into any detail of what this entails, but rest assured, it involves somebody dying.',12340),
	 (4083,0,0,0,0,0,0,0,0,'The spectral chalice floats in the air, slowing rising and falling... as if to the beat of a dying heart.',12340),
	 (4084,1,0,0,0,0,0,0,0,'Very well, $N. I can see you are serious about helping your friend.',12340),
	 (4101,1,0,0,0,0,0,0,0,'This blood amber will be used to find a means of defeating the corruption present in Felwood. You''ve proven to me that you''re willing to do whatever it takes for the Cenarion Circle. I trust you now, friend.$B$BIt might seem odd that killing the elementals proved yourself to me, but the end of saving countless sentient beings must justify the means we take. You and I can now focus on the preservation of life through the salves I can make.$B$B$N, the time has come to cleanse Felwood.',12340),
	 (4102,1,0,0,0,0,0,0,0,'This blood amber will be used to find a means of defeating the corruption present in Felwood.  You''ve proven to me that you''re willing to do whatever it takes for the Cenarion Circle.  I trust you now, friend.$B$BIt might seem odd that killing the elementals proved yourself to me, but the end of saving countless sentient beings must justify the means we take.  You and I can now focus on the preservation of life through the salves I can make.$B$B$N, the time has come to cleanse Felwood.',12340),
	 (4103,1,0,0,0,0,0,0,0,'Very well then, here are your Cenarion plant salves. Scour Felwood for corrupted plants, $n! Wherever they are, use the salve I have given you to purify them.',12340),
	 (4104,0,0,0,0,0,0,0,0,'Very well then, here''s some Cenarion plant salve. If you find more vitriol when you mine in Felwood, remember to hold on to it for me! The more of it you find, the more salve I will be able to make.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (4105,0,0,0,0,0,0,0,0,'Excellent work $n - every bit of this, once we purify it, will help us take back Felwood. Here, take some doses of Cenarion plant salve and head into the forest. The reclaiming of the land from the corruption waits for no $r!',12340),
	 (4106,0,0,0,0,0,0,0,0,'This is exactly what I need. Here - take these plant salves and use them to reclaim Felwood from the corruption. We must persevere, $n!',12340),
	 (4107,0,0,0,0,0,0,0,0,'Here are some Cenarion plant salves - I only need one lesser nether essence for this, $n. Essence is by far the most potent item I can make use of to turn swords into plowshares, as it were. If you need more salve, then find me here!',12340),
	 (4108,1,0,0,0,0,0,0,0,'Very well then, here are your Cenarion plant salves. Scour Felwood for corrupted plants, $n! Wherever they are, use the salve I have given you to purify them.',12340),
	 (4109,0,0,0,0,0,0,0,0,'Very well then, here''s some Cenarion plant salve. If you find more vitriol when you mine in Felwood, remember to hold on to it for me! The more of it you find, the more salve I will be able to make.',12340),
	 (4110,0,0,0,0,0,0,0,0,'Excellent work $n - every bit of this, once we purify it, will help us take back Felwood. Here, take some doses of Cenarion plant salve and head into the forest. The reclaiming of the land from the corruption waits for no $r!',12340),
	 (4111,0,0,0,0,0,0,0,0,'This is exactly what I need. Here - take these plant salves and use them to reclaim Felwood from the corruption. We must persevere, $n!',12340),
	 (4112,0,0,0,0,0,0,0,0,'Here are some Cenarion plant salves - I only need one lesser nether essence for this, $n. Essence is by far the most potent item I can make use of to turn swords into plowshares, as it were. If you need more salve, then find me here!',12340),
	 (4113,0,0,0,0,0,0,0,0,'You apply some Cenarion plant salve to the songflower. It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant.',12340),
	 (4114,0,0,0,0,0,0,0,0,'You apply some Cenarion plant salve to the songflower. It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (4115,0,0,0,0,0,0,0,0,'You apply two Cenarion plant salves to the windblossom. It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant.',12340),
	 (4116,0,0,0,0,0,0,0,0,'You apply some Cenarion plant salve to the songflower. It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant.',12340),
	 (4117,0,0,0,0,0,0,0,0,'You apply 3 Cenarion Plant Salves to the Whipper Root. It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant.',12340),
	 (4118,0,0,0,0,0,0,0,0,'You apply some Cenarion plant salve to the songflower. It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant.',12340),
	 (4119,0,0,0,0,0,0,0,0,'You apply 4 Cenarion Plant Salves to the Night Dragon. It immediately begins to shed it''s corrupted form, blossoming into a vibrant and healthy plant.',12340),
	 (4120,1,0,0,0,0,0,0,0,'It sounds from your descriptions as if the creatures show a mindless ferocity...$b$bStay alert, $N. It would be in your best interest to learn more of the corruption. Always know your enemy.',12340),
	 (4121,1,0,0,0,0,0,0,0,'Your heroics will not go unrecognized, $N. You have earned this tribute. The Warlord will speak with you now in regards to the final mission.',12340),
	 (4122,6,0,0,0,0,0,0,0,'Can you not see the power we gain by joining the legion of Blackrock? ',12340),
	 (4123,0,0,0,0,0,0,0,0,'You have the heart!  Amazing!  It is even more beautiful than I imagined!$B$BPlease, $N, take this as payment!',12340),
	 (4124,1,1,0,0,0,0,0,0,'Latro sent you to me, I presume.  While I think it is a lost cause at this point, I''ll take whatever assistance you can offer.  I must admit... I''ll be glad once I can put my mind to rest on this matter.  Every day I set out into the wilds of Feralas looking for signs of Raschal, and every night I have come back with nothing to show for my work save gnoll teeth and disappointment.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (4125,0,0,0,0,0,0,0,0,'You have found what appears to be a wrecked row boat.  Through the slightly muddy water you see gaping holes riddling the port side; the boat is nearly shredded down to its simple wooden frame.  Whatever broke this boat most likely tried to snap it in two.  A small crest of the Feathermoon Stronghold is painted on the starboard side.$B$BIn the mud at the base of the boat, a glint of something metallic catches your eye...',12340),
	 (4126,4,2,0,0,0,0,0,0,'You found it! Well done! And I hope you gave those Dark Irons, and Hurley Blackbreath, a good thumping!$b$bThe Thunderbrews are at your service, $N. You are a hero of heroes!',12340),
	 (4127,1,1,6,0,0,0,0,0,'Interesting... I believe that this is Raschal''s knife.  You say you found it at the bottom of the water, along with his boat?  Well, just the knife''s discovery might not be enough to connect this to Raschal''s disappearance; we do, however, have an unconventional option available to us to try and learn more.$B$BHave you ever heard of psychometry?',12340),
	 (4128,5,0,0,0,0,0,0,0,'You''re right I''m mad!  I''ve been robbed!  Robbed of one of our family recipes!  How dare they!  As if I didn''t have enough cause to hate the Dark Iron dwarves!  Now, oh... now they''re in for it!',12340),
	 (4129,1,0,0,0,0,0,0,0,'Thank you, $N.$B$BWhile psychometry isn''t an exact art by any stretch of the imagination, I''ve used it in times past to give insight into situations that others have chalked up to lost causes.  I think using it on the knife you''ve uncovered will give us a glimpse into what happened to Raschal.$B$BIt will only take a moment to do, but it isn''t what I''d call a caster-friendly task.  Bear with me on this.',12340),
	 (4130,2,1,0,0,0,0,0,0,'Thanks for passing along Quint''s visions to me, $N.  I''ll try to remember to be a little easier on him the next time we play cards.$B$BRaschal can hold his own in a fight, and gnolls aren''t anything that would get him worried - nay, terrified.  Still, maybe you and yours can act on this new information and make the breakthrough we desperately need.',12340),
	 (4131,0,0,0,0,0,0,0,0,'Tacked up on a nearby tree are two large leather backpacks.  Each bears a small insignia of the Feathermoon Stronghold on the front of the pack...',12340),
	 (4132,0,0,0,0,0,0,0,0,'Finally! The villain been brought to justice! You are a remarkable individual, $N. Wear this medallion as a symbol of your stalwart dedication to the Horde and the K.E.F.',12340),
	 (4133,2,0,0,0,0,0,0,0,'Thank you for coming, $N. This place is not without a stark charm, but is lacks the amenities of the Apothecarium.$b$bEnough with the pleasantries. To business, yes?',12340),
	 (4134,1,11,0,0,0,0,0,0,'Very good. I will send this recipe to the Apothecarium to be studied, and in time we will unlock its secrets. One day, the dwarves of the Alliance may find the virtues of this drink used against them!$b$bI find that terribly amusing. Perhaps death has an affect on one''s sense of humor... do you think?',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (4135,0,0,0,0,0,0,0,0,'You have discovered a large pod of an alien nature.  The texture of the pod appears mucous, though hardened protrusions stick out from random parts of it.  The pod itself has the height and width to easily encompass a humanoid inside of it... and from the faint humanoid shape visible through the skin of the pod, you surmise that this is what it indeed encapsulates.',12340),
	 (4136,0,0,0,0,0,0,0,0,'Aha! You found him! And... it appears that my little brother didn''t want to come quiety. It''s a pity. I would have liked to see the look on his face when I told him our plans to turn him in to Revilgaz.$b$bThank you, $N. You''ve made my family very happy. And Ribbly''s never looked as peaceful as he does now.',12340),
	 (4141,0,0,0,0,0,0,0,0,'I hope they didn''t give you too much trouble, $N. I try to steer clear of them -- they''re wild!$B$BI tried jumping over one... I was attacked! Plants just shouldn''t be acting that way!',12340),
	 (4142,0,1,0,0,0,0,0,0,'Bloodpetal, eh? Hmmm... Well, you better explain the plan, and then I''ll tell you whether or not I can help you.',12340),
	 (4143,1,0,0,0,0,0,0,0,'I admit, I''m a bit hesitant to touch that stuff, $N! But if Gregan says it''ll work, then I''m willing to give it a try!',12340),
	 (4144,1,11,5,0,0,200,0,0,'Here goes nothing, $N! This will get Larion''s attention!',12340),
	 (4145,0,0,0,0,0,0,0,0,'Thanks for your help, $N, but I''m afraid I have some bad news...',12340),
	 (4146,0,0,0,0,0,0,0,0,'So, Marvon wasn''t around? Well, show me what you got, anyway.',12340),
	 (4147,1,0,0,0,0,0,0,0,'Marvon''s been gone quite a long time now, $N. He went off to Tanaris to study some of the ancient troll ruins.$b$bNow, what was it that you said you needed?',12340),
	 (4148,0,0,0,0,0,0,0,0,'Looks like this is going to work perfectly, $N. Now remember, if you see any of those pests around, don''t hesitate to use that zapper!',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (4161,0,0,0,0,0,0,0,0,'Always remember what I have shown you today, $N. You are part of the balance that the night elves strive to keep intact, even during troublesome times.',12340),
	 (4181,25,1,0,0,0,0,0,0,'Well $N, you were wise to seek my tutelage! Any schlep can become an expert at the basics of engineering - the gnomes and their irradiated home of Gnomeregan are proof of that. It takes a strong mind and a steady hand (emphasis on STEADY) though to master the discipline of Goblin Engineering.$B$BKeep your ears perked $N, and you might learn something.',12340),
	 (4182,0,0,0,0,0,0,0,0,'Superb slaying, $N. Now that we know you can handle yourself around dragonkin, we can talk of more pressing matters.',12340),
	 (4183,0,0,0,0,0,0,0,0,'<Magistrate Solomon opens the sealed letter from Helendis and begins reading.>',12340),
	 (4184,0,0,0,0,0,0,0,0,'Dragons? Impossible!',12340),
	 (4185,0,0,0,0,0,0,0,0,'<Bolvar cups his chin as if in deep thought.>$B$BWhile I respect Lady Prestor''s stance, I believe that there is a solution to this dilemma that may put all of our concerns to rest. ',12340),
	 (4186,0,0,0,0,0,0,0,0,'It could have been worse, I suppose...$B$B<Magistrate Solomon looks you over.>$B$BIt appears as if the fate of Lakeshire rests squarely on your shoulders.$B$B<You notice Magistrate Solomon blinking rapidly. He appears to be crying.>',12340),
	 (4201,0,0,0,0,0,0,0,0,'Oh, you''ve done it!  I can now make my potion and use it on Rocknot.  Finally, he will fall victim to my charms!$B$BThank you, $N.  You are a champion of love!',12340),
	 (4221,0,0,0,0,0,0,0,0,'You apply two Cenarion plant salves to the windblossom. It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant.',12340),
	 (4222,0,0,0,0,0,0,0,0,'You apply two Cenarion plant salves to the windblossom. It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (4223,0,0,0,0,0,0,0,0,'<Marshal Maxwell laughs.>',12340),
	 (4224,0,0,0,0,0,0,0,0,'I could have warned you, but what fun is that?',12340),
	 (4241,0,0,0,0,0,0,0,0,'Where is he! I''ll murder him!',12340),
	 (4242,0,0,0,0,0,0,0,0,'He''s gone mad, apparently.$B$B<Maxwell lowers his head in mourning.>$B$BIt is unfortunate that a once proud and noble warrior would be turned into a blithering head case. I GUESS we''ve reached a dead end...$B$BI must reward you for your efforts thus far, $N.',12340),
	 (4243,0,0,0,0,0,0,0,0,'As you look A-Me 01 over, you see two huge dents tarnishing what Karna obviously feels is a well-crafted piece of engineering. One dent decorates A-Me 01''s shoulder, the other is on her head.$B$BNo power seems to be running through her components as you investigate further.',12340),
	 (4244,0,0,0,0,0,0,0,0,'You remove the panel from A-Me 01''s back yet again and carefully remove the old mithril casing that seems to have burnt out. The new one slides into place easily. The only thing left to do, assuming the mithril casing was the problem, is to flip the switch to the "Off" position, and then back to the "On" position.',12340),
	 (4245,4,1,2,0,0,0,0,0,'Oh, you''ve done it! Wonderful! Thank you, $N.$b$bOh, my poor, A-Me. Look at all those dents. We''ll get her up and running perfectly with just a little work.$b$bThank you again, $N. I really appreciate it.',12340),
	 (4261,2,0,0,0,0,0,0,0,'Yes, $N. Felwood has been through much hardship. Thank you for what you have done.$B$BOne day, we may be able to reclaim Felwood from the corruption; every kind deed helps.',12340),
	 (4262,6,0,0,0,0,0,0,0,'Incendius? Oh dear...',12340),
	 (4263,6,0,0,0,0,0,0,0,'Oh dear! Are you sure Incendius said ''Ragnaros?''$b$b<Jalinda hands you something and pats you on the wrist as she fades deep into thought.>',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (4264,0,0,0,0,0,0,0,0,'<Marshal Windsor takes the note and begins reading.>',12340),
	 (4265,2,1,1,0,0,0,0,0,'Welcome home, $N.  Raschal checked in just a little while ago and told me what happened.$B$BI... no, the entire Stronghold can''t even begin to thank you for your great deed; Raschal would have been dead without your timely aid, and your assistance came to us without even so much as the whisper of a mercenary''s fee.  You bear the mark of a true hero.  Know that you will always have a friend in Ginro Hearthkindle.',12340),
	 (4266,66,1,0,0,0,0,0,0,'$N, I give you my warmest thanks for the aid you''ve given us.  Your bravery in the face of overwhelming odds has warranted a reward worth a thousand times greater.  Nevertheless, I hope you accept this on behalf of the entire Stronghold.$B$BNow, if I may... I''d like to ask for your aid one more time.  In light of the discovery of the Zukk''ash hive here in Feralas, I think you''re the best choice for this mission.',12340),
	 (4267,1,1,1,0,0,0,0,0,'We night elves know of the terror outlined in this report.  Shandris was wise to send this, and you, to me.$B$BThese creatures will consume Feralas rapidly; they are nothing short of one of the greatest menaces we all will ever face.  The insects you and the courier encountered are known as the silithid.  They are mere tools of one of the greatest threats that both the Horde and Alliance will ever face.$B$BI pray we will have the resolve to defeat them before they destroy us.',12340),
	 (4281,5,1,1,2,0,0,0,0,'Elune be praised, the delivery from Feathermoon Stronghold has finally arrived!$b$bYour presence here indicates to me that perhaps some ill fate may have befallen Raschal, our usual courier. I hope that everything works out. I know that recently, the Woodpaw have become highly agitated from some source to their south. Maybe he fell to the wilds there; I would be careful, friend.$b$bRegardless, thank you again. Here is payment for this parcel''s delivery.',12340),
	 (4282,0,0,0,0,0,0,0,0,'<Marshal Windsor snatches the two tablets from your hands.>$B$BWe need to get out of here!',12340),
	 (4283,4,5,0,0,0,0,0,0,'You''ve done it! Your reward is: RUB MY BELLY! GO ON! RUB IT!',12340),
	 (4284,4,0,0,0,0,0,0,0,'Now I will continue my experiments! Thank you, $N.',12340),
	 (4285,1,0,0,0,0,0,0,0,'I know the stories are true, $N.',12340),
	 (4286,4,5,1,0,0,0,0,0,'<Oralius starts rummaging through the mountainous pile of fanny packs.>$B$BOH WONDERFUL!$B$B<Oralius sticks his large nose into the pile and takes a whiff.>$B$BDELICIOUS! Look at all these goodies!$B$BTake one for yourself, $N. There''s plenty to go around.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (4287,1,0,0,0,0,0,0,0,'Un''Goro is such a strange place, $N. When you enter the crater, it''s as if you are in a completely different world...',12340),
	 (4288,1,0,0,0,0,0,0,0,'There are many hidden areas of the crater along the sides. Try exploring the winding paths if you can''t think of anywhere else to look, $N.',12340),
	 (4289,0,0,0,0,0,0,0,0,'So, you have proven strong, strong enough to best the great apes of Un''Goro--that is good. The challenge was small compared to Lar''korwi, but I will not take such a great victory away from you.$B$BThese pelts will make wonderful clothing for my tribe. You have helped me and proven worthy.$B$BBefore you set off on another task, let us give praise to the Earth Mother and thank the spirits of those apes you killed--they must know their deaths will not be wasted.',12340),
	 (4290,0,0,0,0,0,0,0,0,'This will do nicely, $N. It seems Lar''korwi eats well these days. Although, I wonder where he found a threshadon in this area. Odd.$B$BRegardless, I will hold onto this until you are ready for your confrontation with the beast. Do not worry for my safety--I am sure you''ve angered Lar''korwi enough that he will not kill me until after he''s tasted your flesh.',12340),
	 (4291,0,0,0,0,0,0,0,0,'Ah, fine specimens, $N. The two pieces you''ve found should be perfect for baiting Lar''korwi into the open. I cannot wait to see the outcome of your fight with the monster. He is a massive thing with claws as sharp as the finest blades. You will look into his eyes and you will know death.',12340),
	 (4292,0,0,0,0,0,0,0,0,'The Earth Mother be praised! You''ve done it! Fair play to you, $N. You have proven to be a great hunter in your own right. Your spirit is strong. Your bravery unmatched. And your strength has been fortified. I bow down to your skills.$B$BOnly the greatest of my ancestors could have accomplished something so incredible. Congratulations.',12340),
	 (4293,0,0,0,0,0,0,0,0,'Ah, excellent. These samples will do nicely. I thank you for your help.$B$BOnce we''ve gathered all the samples of slimes, we''ll be able to determine more. I am beginning to suspect that Lady Sylvanas'' hunch was not only correct, but more insightful than even she could have predicted. These samples are very interesting. Just seeing how they''ve reacted with my compounds... hmm, yes, we''ll definitely need to investigate further.',12340),
	 (4294,0,0,0,0,0,0,0,0,'Truly amazing, $N. This Un''Goro Crater is holding many more secrets than I expected. I wonder what else we will discover as we test further.$B$BSimply amazing... look at the purity of these samples. Hmm, I wonder what it could mean. They seem to be elemental in nature, but... something more. They remind me of... of the Old Gods. We''ve found traces of them throughout Azeroth, and now I wonder if these creatures aren''t related to them somehow.$B$BWe shall have to test further.',12340),
	 (4295,6,4,0,0,0,0,0,0,'What''s this?  Ah!  It smells like Dark Iron Ale!  Drink has blurred my sight, but I can tell that you, $gsir:my lady;, are a real friend!',12340),
	 (4296,4,0,0,0,0,0,0,0,'Ah, you found the tablet!  And your transcription is superb!  Are you sure you''re a $c and not a scribe?$B$BHere you are, $N.  Here is the payment I promised.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (4297,1,6,11,0,0,0,0,0,'These''ll do nicely, and if I''m not mistaken, your little egg''s just about ready to hatch. How does it feel? You know, you about to be a father? Haha, didn''t think ya''d have to deal with such responsibility, now did ya?',12340),
	 (4298,1,1,0,0,0,0,0,0,'Here, take the egg... better you have it so it bonds to you and looks to you to be its dadda.$B$BCongrats, $N. You''re a parent... kinda.',12340),
	 (4300,0,0,0,0,0,0,0,0,'Ah, these do nicely. Thank you, $N. An'' you be here long before they needed... that be good.$b$bMaybe we have a weapon fashioned for you from the claws. What do you say?',12340),
	 (4301,0,0,0,0,0,0,0,0,'Well done, $N. I am pleased. You have done a great thing here today.$B$BU''cha was one of the greatest apes I had ever seen. The fact that you have bested his strength speaks well of your own strength... and courage.$B$BIt is only fitting that I give you this as a sign of respect. You have earned it.',12340),
	 (4321,1,4,0,0,0,0,0,0,'Alright, $N. This is fascinating... I can only hope that my diagrams are correct! I compiled everything into this manual, which you can have.$B$BI believe I can answer any questions you have about the crystals now, $N.',12340),
	 (4322,0,0,0,0,0,0,0,0,'Amazing, $N. Simply amazing. Windsor stormed through here not five minutes ago. He makes some grand claims but purports that they are supported by his evidence. He is on his way to Stormwind now to confront Bolvar and ... Lady Prestor.',12340),
	 (4324,1,0,0,0,0,0,0,0,'Yes, I''m looking for my brother.  We must find him and retrieve him, bless his heart.$B$BBut if we can''t bring all of him... then his head will suffice.',12340),
	 (4341,16,0,0,0,0,0,0,0,'Please, let me explain.',12340),
	 (4342,1,0,0,0,0,0,0,0,'As you can see, there was nothing I could have done.',12340),
	 (4343,0,0,0,0,0,0,0,0,'You apply two Cenarion plant salves to the windblossom. It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (4361,36,0,0,0,0,0,0,0,'<King Magni slams his fist down in anger.>',12340),
	 (4362,18,0,0,0,0,0,0,0,'<Princess Bronzebeard weeps over the loss of Emperor Dagran Thaurissan.>$B$BWhy???',12340),
	 (4363,1,1,0,0,0,0,0,0,'<King Magni Bronzebeard is visibly upset.>$B$BIt seems that even in death, Thaurissan has won.$B$BYou are dismissed, $N. Before you leave, you may choose your reward from the royal vault.$B$B<King Bronzebeard slumps into his throne to mull over this bizarre change of events.>',12340),
	 (4381,0,0,0,0,0,0,0,0,'Arranging the crystals on the table, you carefully align the colors. As you push the last one into place, a burst of light fuses the crystals together.$B$BThe resulting combination is now yours.',12340),
	 (4382,0,0,0,0,0,0,0,0,'Arranging the crystals on the table, you carefully align the colors. As you push the last one into place, a burst of light fuses the crystals together.$B$BThe resulting combination is now yours.',12340),
	 (4383,0,0,0,0,0,0,0,0,'Arranging the crystals on the table, you carefully align the colors. As you push the last one into place, a burst of light fuses the crystals together.$B$BThe resulting combination is now yours.',12340),
	 (4384,0,0,0,0,0,0,0,0,'Arranging the crystals on the table, you carefully align the colors. As you push the last one into place, a burst of light fuses the crystals together.$B$BThe resulting combination is now yours.',12340),
	 (4385,0,0,0,0,0,0,0,0,'Arranging the crystals on the table, you carefully align the colors. As you push the last one into place, a burst of light fuses the crystals together.$B$BThe resulting combination is now yours.',12340),
	 (4386,0,0,0,0,0,0,0,0,'Arranging the crystals on the table, you carefully align the colors. As you push the last one into place, a burst of light fuses the crystals together.$B$BThe resulting combination is now yours.',12340),
	 (4401,0,0,0,0,0,0,0,0,'You apply some Cenarion plant salve to the songflower. It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (4402,1,1,4,0,0,0,0,0,'Wonderful, $N! As promised, here is your cactus apple surprise plus a little something extra.',12340),
	 (4403,0,0,0,0,0,0,0,0,'You apply two Cenarion plant salves to the windblossom. It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant.',12340),
	 (4421,0,0,0,0,0,0,0,0,'Ridding Felwood of Xavathras is only the first step in a long process. It will take much work to repair the damage that has been done here.$B$BI sense that there is something much larger than just the satyrs at work here, but we will only know the truth with time...',12340),
	 (4441,2,0,0,0,0,0,0,0,'Thank you, $N. Now, we must pray that we can undo the damage that has been done...',12340),
	 (4442,2,0,0,0,0,0,0,0,'With the blessed water, I was able to break the link between the flute and the ancient spirit. I do believe though, that if you were to use this flute in a sacred spot, you may be able to summon the ancient spirits.$B$BPerhaps you might try the ruins in the southern part of Irontree Woods. Many corrupted treants inhabited this area at one time, and it is possible that they may still reside there, even in spirit form.',12340),
	 (4443,0,0,0,0,0,0,0,0,'You apply 3 Cenarion Plant Salves to the Whipper Root. It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant.',12340),
	 (4444,0,0,0,0,0,0,0,0,'You apply 3 Cenarion Plant Salves to the Whipper Root. It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant.',12340),
	 (4445,0,0,0,0,0,0,0,0,'You apply 3 Cenarion Plant Salves to the Whipper Root. It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant.',12340),
	 (4446,0,0,0,0,0,0,0,0,'You apply 3 Cenarion Plant Salves to the Whipper Root. It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant.',12340),
	 (4447,0,0,0,0,0,0,0,0,'You apply 4 Cenarion Plant Salves to the Night Dragon. It immediately begins to shed it''s corrupted form, blossoming into a vibrant and healthy plant.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (4448,0,0,0,0,0,0,0,0,'You apply 4 Cenarion Plant Salves to the Night Dragon. It immediately begins to shed it''s corrupted form, blossoming into a vibrant and healthy plant.',12340),
	 (4449,0,0,0,0,0,0,0,0,'Oh, this is great! Nice feel to it too!$B$BWhat? Oh, yeah... geologists. Got ''em good, did ya? I can''t thank ya enough, $N. That''ll give me some time to finish up in here... Thanks again, $N.',12340),
	 (4450,21,1,0,0,0,0,0,0,'Oh, you''ve seen fit to do some of the work I requested. Excellent. And here I thought you were going to ask me to craft you something.$B$BThese are all perfect... and everything''s here. Thank you, $C.$B$BMaybe it wouldn''t hurt to reward you some... hmm, what would you find useful.',12340),
	 (4451,0,0,0,0,0,0,0,0,'Well, I''ll be! How in tarnation!? You found the key! I knew them blasted Dark Irons were hiding it after they locked me in here! Thank ya so much, $N. You''re the greatest! Now, just turn the key and let ol'' Locheed outta here!',12340),
	 (4461,0,0,0,0,0,0,0,0,'You apply 3 Cenarion Plant Salves to the Whipper Root. It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant.',12340),
	 (4462,0,0,0,0,0,0,0,0,'You apply 4 Cenarion Plant Salves to the Night Dragon. It immediately begins to shed it''s corrupted form, blossoming into a vibrant and healthy plant.',12340),
	 (4463,5,0,0,0,0,0,0,0,'Take your trinket, fool. Leave me to my studies!',12340),
	 (4464,0,0,0,0,0,0,0,0,'You apply some Cenarion plant salve to the songflower. It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant.',12340),
	 (4465,0,0,0,0,0,0,0,0,'You apply some Cenarion plant salve to the songflower. It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant.',12340),
	 (4466,0,0,0,0,0,0,0,0,'You apply two Cenarion plant salves to the windblossom. It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (4467,0,0,0,0,0,0,0,0,'You apply two Cenarion plant salves to the windblossom. It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant.',12340),
	 (4481,1,5,0,0,0,0,0,0,'It is disgrace to his memory... a mortal, such as yourself, finishing his life''s work.$B$BTake your amalgamation and be gone!',12340),
	 (4482,1,25,0,0,0,0,0,0,'It took Kariel what would amount to several of your lifetimes to complete the libram that you now hold, $R. All for what? So that his disciple could stand in the Burning Steppes and bastardize his research in order to satiate a never ending arcane craving... Curse this foul addiction.$B$BI am disgusted with your lack of compassion and insatiable greed. Be gone!',12340),
	 (4483,1,1,0,0,0,0,0,0,'Other librams are lost in this world. Lost in places you would not dare enter. Places you would pray did not exist.$B$BI will drink in the energies of these components. You shall be given the residual waste...',12340),
	 (4484,33,5,0,0,0,0,0,0,'My head throbs... The energies of the vast expanses that makes up our universe... ARGGH!$B$BTake what you desire and leave!',12340),
	 (4489,0,0,0,0,0,0,0,0,'So, you''ve decided to grace my presence again. How kind of you.$B$BMy acolytes wondered if you''d ever show up. I told them there was no doubt. When power is concerned, you are drawn in like a moth to the flame.',12340),
	 (4490,0,0,0,0,0,0,0,0,'Good luck, $N. I look forward to seeing you in the future.',12340),
	 (4491,4,0,0,0,2000,0,0,0,'Ringo''s not in the best shape, $N, but I am glad to have him back in one piece!$b$bThank you for finding him.',12340),
	 (4492,0,0,0,0,0,0,0,0,'Oh... I''m so glad someone found me...',12340),
	 (4493,1,0,0,0,0,0,0,0,'Yes, I gathered that Gracina sent you to me. Your experience in fighting these beasties is priceless; no one to my knowledge has ever dealt with their kind before. As for Gracina''s idea that Un''Goro Crater is their heart... perhaps it is. Un''Goro is a mysterious and dangerous jungle to the west of here. Perhaps it is also one step closer to figuring out what the silithid are all about.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (4494,1,0,0,0,0,0,0,0,'Yes, I gathered that Zilzibin sent you to me. Your experience in fighting these beasties is priceless; no one to my knowledge has ever dealt with their kind before. As for Zil''s idea that Un''Goro Crater is their heart... perhaps it is. Un''Goro is a mysterious and dangerous jungle to the west of here. Perhaps it is also one step closer to figuring out what the silithid are all about.',12340),
	 (4495,0,0,0,0,0,0,0,0,'I''m so glad you found me, $N. How did you know I was here?',12340),
	 (4496,21,0,0,0,0,0,0,0,'The scent gland, ah yes. The membrane appears intact - excellent. The soil, yes, this should work out perfectly. With my special additions, I should be able to grind all this up into the perfect lure.$b$bGive me a moment to make the lure, $N. Once it''s ready, we''ll be able to enact the next step that may hopefully stop the silithid before they overrun Gadgetzan... and the rest of Kalimdor.',12340),
	 (4501,1,4,0,0,0,0,0,0,'I am absolutely terrified of the pterrordax here! Thank you for decreasing their numbers, $N. Now I might feel safe enough to venture out of Marshal''s Refuge.',12340),
	 (4502,4,1,0,0,0,0,0,0,'These samples will be perfect for my studies! Thank you, $N! I promise, you''ll be the first one I will tell about my findings.',12340),
	 (4503,1,2,0,0,0,0,0,0,'Yes, these scales are perfect. I should be able to get this flyer off the ground with these scales for sure!$B$BThanks!',12340),
	 (4504,1,0,0,0,0,0,0,0,'Yes, this tar is just the stuff...$B$BHey, wait a minute, my hands... I can''t seem to get them apart...$B$BMaybe this wasn''t such a good idea. Oh, but wait! Super sticky tar remover! That''s where the real money is!',12340),
	 (4505,1,0,0,0,0,0,0,0,'Very well. We must find a way to use this corruption against our enemies...',12340),
	 (4506,4,11,0,0,0,0,0,0,'Excellent!$b$bThe forsaken will resort to any means necessary to crush the alliance! The use of the corrupted water will surely prove useful in our future efforts...',12340),
	 (4507,4,0,0,0,0,0,0,0,'Fantastic, $N!  We''ve won quite the victory here today.  It will take some time for us to fully understand what we have here; we''ll put it to good use though, don''t you worry about that.$B$BAs for the silithid, I genuinely doubt that this was the full extent of their presence.  This is much too clean of a resolution, I''m sorry to say.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (4508,1,0,0,0,0,0,0,0,'While I genuinely appreciate this, I am not sure what good it will do us.  The Alliance ignores threats from any source other than the Horde, and even our own leaders here in Darnassus cannot agree on what exactly this threat is.  Fools like Fandral Staghelm theorize that the silithid are nothing like the threat from the ancient past I claim them to be.  His ignorance is only surpassed by his arrogance.$B$BYou have seen the threat yourself, $N.  We must remain committed to defeating the silithid!',12340),
	 (4509,1,0,0,0,0,0,0,0,'While I genuinely appreciate this, I am not sure what good it will do us.  The Horde ignores threats from any source other than the Alliance.  While Thrall himself might take action were the facts presented to him, he is beset on all sides by conflicting advice.  These fools would have us chase our own imaginary tails were they to think it might catch the Alliance unawares!$B$BYou have seen the threat yourself, $N.  We must remain committed to defeating the silithid!',12340),
	 (4510,1,0,0,0,0,0,0,0,'This bank voucher authorizes me to withdraw an item from Gracina Spiritmight''s account with us and present it to you.  Congratulations would seem to be in order!',12340),
	 (4511,1,0,0,0,0,0,0,0,'This bank voucher authorizes me to withdraw an item from Zilzibin Drumlore''s account with us and present it to you.  Congratulations would seem to be in order!',12340),
	 (4512,5,1,1,0,0,0,0,0,'Amazing results, $N! You got close enough to take a sample of the corrupted things, and managed to look no worse for wear! Thank you. Oh, these samples will be perfect. I can''t wait to start testing on them.$B$BIf I''m right, I could be one of the Explorers'' Leagues greatest scientists!$B$BThat''ll prove to all the dwarves that it wasn''t a mistake to allow us gnomes into Ironforge  after the Gnomeregan incident.',12340),
	 (4513,6,4,1,0,0,0,0,0,'You''ve found it? $N, you are a treasure unto yourself. Your dedication and aid has been magnificent and I could not possibly thank you enough.$B$BPlease, take this for your troubles. I have some work to do, but I''m sure, if you come back at a later time, I''ll have need of your services again.$B$BThank you. Thank you so much.',12340),
	 (4521,0,0,0,0,0,0,0,0,'This is excellent news, $N. With these beasts out of the way, we can begin to adventure further into Winterspring. Are you ready for more?',12340),
	 (4542,0,0,0,0,0,0,0,0,'More bad news! These centaurs have gone too far! They raided one of my supply caravans and slaughtered the whole party. This is an outrage, and it will not go unpunished!$b',12340),
	 (4561,0,0,0,0,0,0,0,0,'You pick up the petri dish with the slime sample in it. The only way to discern if the samples is pure enough is to open it and examine the contents yourself. Ideally you''ll find a sample that fits Chemist Fuely''s criteria.',12340),
	 (4581,2,0,0,0,0,0,0,0,'Ah, Shindrell''s report!  Many thanks, $N.  Shindrell is a fine sentinel, brave and keen.  I must read this for clues of a wickedness I fear is moving through Ashenvale.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (4601,0,0,0,0,0,0,0,0,'You insert the grime-encrusted item and three silver coins into the Sparklematic 5200. The machine surges to live in an almost frenzied attempt to purge the grime from the unknown item. Loud, violent churning sounds beat from the heart of the machine. The metal frame of the beast creaks and groans as it lurches from side to side...',12340),
	 (4602,0,0,0,0,0,0,0,0,'This contraption stands out amongst the gnomes holding out against the madness outside the room. A small plaque on the device reads "The Sparklematic 5200", followed by some text:$B$B"Grime and residue ruining your sparklies? The Sparklematic 5200 puts the shine back in shine-tastic! Insert the item you wish to clean and deposit three silver coins in the coin slot. Give the Sparklematic 5200 a moment for operation, and voila! Your valuables will emerge clean and shiny!"',12340),
	 (4603,0,0,0,0,0,0,0,0,'The Sparklematic 5200 comes to life, lurching to and fro. Inside, the helpless grime that has encrusted the object placed within it is being pulverized by the machine''s gnomish cleaning agent.$B$BThe Sparklematic 5200 comes to a halt, heralded by a familiar "ding!" The item receptacle of the machine spirals open, revealing a neatly wrapped box.',12340),
	 (4604,0,0,0,0,0,0,0,0,'The Sparklematic 5200 comes to life, lurching to and fro. Inside, the helpless grime that has encrusted the object placed within it is being pulverized by the machine''s gnomish cleaning agent.$B$BThe Sparklematic 5200 comes to a halt, heralded by a familiar "ding!" The item receptacle of the machine spirals open, revealing a neatly wrapped box.',12340),
	 (4605,0,0,0,0,0,0,0,0,'As quickly as it started, the Sparklematic 5200 comes to an abrupt halt. A simple "ding" is heard from the machine, and the mouth of the machine spirals upward. Inside the Sparklematic 5200 is a small box wrapped in a little bow. The machine would appear to wrap an object up after eliminating its grime-encrusted status. Even if the machine didn''t work, at least the item is now wrapped in a pretty box.$B$BWell, there is one way to find out if it cleaned the item or not...',12340),
	 (4606,0,0,0,0,0,0,0,0,'As quickly as it started, the Sparklematic 5200 comes to an abrupt halt. A simple "ding" is heard from the machine, and the mouth of the machine spirals upward. Inside the Sparklematic 5200 is a small box wrapped in a little bow. The machine would appear to wrap an object up after eliminating its grime-encrusted status. Even if the machine didn''t work, at least the item is now wrapped in a pretty box.$B$BWell, there is one way to find out if it cleaned the item or not...',12340),
	 (4621,0,0,0,0,0,0,0,0,'Avast ye... Admiral $N!  Yer a pirate of pirates, lass!$B$BIt warms the cackles of me heart to give ye this hat.  Ye will ne''er find one like it anywheres, and all that gazes upon ye will see that yer an Admiral of the Bloodsail Navy!',12340),
	 (4641,6,1,1,4,0,0,0,0,'Another one of Kaltunk''s recruits, hm?$B$BA sorry state of affairs we find ourselves in if this is the best the Horde can produce. No matter. By the time we think you''re ready to leave the Valley, you''ll be a proud $C of the Horde.',12340),
	 (4642,0,0,0,0,0,0,0,0,'Oh, most excellent, $N. This is most excellent.$B$BSuch a tale. Who would have thought the two would interact with one another in such a way... I will have to spend more time looking at the environmental issues that cause changes in these creatures.$B$BI will continue my research for now. Perhaps we will speak again soon. Until then, I wish you well.',12340),
	 (4661,0,0,0,0,0,0,0,0,'You pick up the petri dish with the slime sample in it. The only way to discern if the samples is pure enough is to open it and examine the contents yourself. Ideally you''ll find a sample that fits Chemist Fuely''s criteria.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (4681,4,0,0,0,0,0,0,0,'You''ve been a tremendous help here today; we now have a solid chance at unlocking the mystery of why these creatures choose to beach themselves on the cost of Darkshore. The idea that they might be fleeing the area around Teldrassil is disturbing. Should you come across others in your travels, please let me know. Our research here is but in its infancy.$B$BOn behalf of the Temple of the Moon, please accept this as thanks for the effort you have given. Thank you, $N!',12340),
	 (4701,1,2,0,0,0,0,0,0,'Do not dwell upon her suffering, $N. The beast was corrupt - a product of dark magic. You have done the Alliance a great service and you shall be rewarded.',12340),
	 (4721,0,0,0,0,0,0,0,0,'Hard work is something I have great respect for, $N. Now we can move forward with our plans for Winterspring.',12340),
	 (4722,4,0,0,0,0,0,0,0,'Another discovery for us to research - well done $N!  These remains will be properly studied once they get to Darnassus.  Please accept this small honorarium in exchange for the remains you have provided for our study.',12340),
	 (4723,0,0,0,0,0,0,0,0,'The bones you have are from gentle sea mammals that are known to inhabit the waters surrounding the base of Teldrassil. They had never been known to violently beach themselves like the threshers had been known to. Why would these creatures do this, I wonder? Well, perhaps the study of their remains will bear the fruits of knowledge that we seek.$b$bAgain, thank you for your aid. Please accept this honorarium from the Temple of the Moon.',12340),
	 (4724,6,21,0,0,0,0,0,0,'Rabid pups? Gizrul the Slavener? And you live to tell the tale?! Incredible! A tribute well earned!',12340),
	 (4725,0,0,0,0,0,0,0,0,'I have heard of the kinds of carriages found on the back of the turtle you found. Those I do believe are naga carriages, used both in battle and in transportation of their supplies on to land. The markings on the box you found are of the naga; this would explain their invasive presence in far-northern Darkshore.$b$bI will send this box to Darnassus along with the rest of your discoveries. This is for you - thank you again for your assistance.',12340),
	 (4726,4,0,0,0,0,0,0,0,'It worked!  You got the essence!  Well done, $N!  Well done!$B$BThis essence will be invaluable in my research.  I hope to one day learn how to capture living dragon whelps, or perhaps capture their eggs.  If I could find a way to do that, then I would be the envy of dragon scholars around the world!$B$BMy employer would also be happy, and as I said before, he''s someone you want to keep happy...',12340),
	 (4727,0,0,0,0,0,0,0,0,'The bones you have are from gentle sea mammals that are known to inhabit the waters surrounding the base of Teldrassil. They had never been known to violently beach themselves like the threshers had been known to. Why would these creatures do this, I wonder? Well, perhaps the study of their remains will bear the fruits of knowledge that we seek.$B$BAgain, thank you for your aid. Please accept this honorarium from the Temple of the Moon.',12340),
	 (4728,0,0,0,0,0,0,0,0,'Ah, I believe you discovered one that was originally being examined by the Explorer''s League.  They have a presence here in Darkshore, and they had mentioned that they were studying one of the beached creatures until they were chased out by the murlocs.  You appear to have succeeded where we both have not.  Please - accept this honorarium on behalf of the Temple of the Moon.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (4729,1,0,0,0,0,0,0,0,'You got ''em at the perfect time, $N. Any later and they''d be untrainable! Gimmie a minute and I''ll have the little fella ready for you to take home.',12340),
	 (4730,0,0,0,0,0,0,0,0,'The bones you have are from gentle sea mammals that are known to inhabit the waters surrounding the base of Teldrassil.  They had never been known to violently beach themselves like the threshers had been known to.  Why would these creatures do this, I wonder?  Well, perhaps the study of their remains will bear the fruits of knowledge that we seek.$B$BAgain, thank you for your aid.  Please accept this honorarium from the Temple of the Moon.',12340),
	 (4731,0,0,0,0,0,0,0,0,'I have heard of the kinds of carriages found on the back of that turtle.  Those I do believe are naga carriages, used both in battle and in transportation of their supplies on to land.  The markings on the box you found are of the naga; perhaps the creature you discovered was killed as it was heading further south... to Ashenvale maybe?$B$BI will be sure to send this box to Darnassus with the rest of your discoveries.  This is for you - thank you again for your assistance.',12340),
	 (4732,0,0,0,0,0,0,0,0,'You''ve found even more beached creatures, $N?  Sea turtles were commonly found frolicking along the base of Nordrassil before it was destroyed.  With the birth of Teldrassil, however, these creatures have been seen in ever decreasing numbers.  Some, as we have discovered, end their lives here for some unknown reason.$B$BYour aid will perhaps unlock the mystery before us.  Please accept this in exchange for the remains you have provided for our study.',12340),
	 (4733,0,0,0,0,0,0,0,0,'The dimensions of the thresher you mention are mind-boggling.  Even the eldest of the threshers in this region grow to only a fraction of that size.  While some larger ones were known to be close to Teldrassil, their numbers have declined steadily.  I cannot help but wonder if these creatures beaching themselves here are somehow related to this.$B$BWhile we analyze the bones you have brought us, please accept this on behalf of the Temple of the Moon.  Thank you, $N.',12340),
	 (4734,4,0,0,0,0,0,0,0,'It worked? Splendid! I knew it would!$b$bWhile you were gone I was working on a new version of the eggscilloscope. This one has a much longer range.$b$bHere, you can have one in case you go back to Blackrock Spire.',12340),
	 (4735,4,2,0,0,0,0,0,0,'Wow, you got them! The collectronic module worked! I''m a genius!$B$BThank you, $N. My patron will be very pleased to get these eggs...',12340),
	 (4736,2,1,0,0,0,0,0,0,'Ah, Briarthorn sent you. Good. Then word does reach far enough to find future students. This pleases me.$B$BIt is typical of our kind, $N, to band together, regardless of race. It is especially important since those we deal with most do not discriminate in their malice if we fail to appease them or control them properly.$B$BI feel you''ve learned a great many things, and if you are willing, I would help you create tools to compliment your skills.',12340),
	 (4737,2,1,0,0,0,0,0,0,'Ah, Zevrost sent you. Good. Then word does reach far enough to find future students. This pleases me.$B$BIt is typical of our kind, $N, to band together, regardless of race. It is especially important since those we deal with most do not discriminate in their malice if we fail to appease them or control them properly.$B$BI feel you''ve learned a great many things, and if you are willing, I would help you create tools to compliment your skills.',12340),
	 (4738,2,1,0,0,0,0,0,0,'Ah, Demisette sent you. Good. Then word does reach far enough to find future students. This pleases me.$B$BIt is typical of our kind, $N, to band together, regardless of race. It is especially important since those we deal with most do not discriminate in their malice if we fail to appease them or control them properly.$B$BI feel you''ve learned a great many things, and if you are willing, I would help you create tools to compliment your skills.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (4739,2,1,0,0,0,0,0,0,'Ah, Kaal sent you. Good. Then word does reach far enough to find future students. This pleases me.$B$BIt is typical of our kind, $N, to band together, regardless of race. It is especially important since those we deal with most do not discriminate in their malice if we fail to appease them or control them properly.$B$BI feel you''ve learned a great many things, and if you are willing, I would help you create tools to compliment your skills.',12340),
	 (4740,4,0,0,0,0,0,0,0,'Well, looks like you''re here to more than just inquire! The citizens will be delighted to know that tonight they will sleep a little bit more soundly and safer.$b$bYou''ve acted as the executioner of justice for the people of Auberdine today, $N. For that, I would like to offer you this as a suitable reward... for a true hero of the Auberdine people.',12340),
	 (4741,1,0,0,0,0,0,0,0,'I sense that you are enjoying your work. And I believe that we are onto something here.',12340),
	 (4742,0,0,0,0,0,0,0,0,'<Vaelan''s image blurs for a moment.>$B$B<The pieces that you had collected have disappeared.>$B$BThe Unforged Seal of Ascension is now ready. It is time for the final step.',12340),
	 (4743,0,0,0,0,0,0,0,0,'Stand steady while I cast the final invocation of protection.$B$B<Vaelan''s eyes turn to twin orbs of flame.>$B$BThe Seal of Ascension is complete...$B$BKnow this, I have imbued the artifact with some powerful protective wards. In your darkest hour, when all appears to be lost, the might of the red flight will be at your disposal.',12340),
	 (4761,2,0,0,0,0,0,0,0,'Well met, $c.  Your scouting of the furbolg situation comes at a fortuitous time for us in Auberdine.  For some time we have dealt with not only forest dwellers who are now openly hostile to our presence, but also the outright corruption of the forest itself.  Hopefully you might be able to lend Auberdine aid during these troubling times.',12340),
	 (4762,5,0,0,0,0,0,0,0,'It''s no surprise how tainted this water is, but just look at how putrid it is becoming! It would seem that action is needed sooner than later, eh $N?$b$bTo our east is Felwood; it is the real source of this corruption, one that I have seen in times past. I predict this sample will confirm this. We might be able to enact a cure for it here, but in order to even try we will need assistance. When that time comes $N, I hope you will be able to give the aid we need.',12340),
	 (4763,4,0,0,0,0,0,0,0,'We have just begun this war to reclaim our forest from the forces of corruption, but a battle this day has been won! $N, the people of Auberdine owe you a debt of gratitude that will never be easily repaid. Please accept this along with our thanks. What we have learned here today may one day free our furbolg friends from the shackles of torment permanently.',12340),
	 (4764,1,2,0,0,0,0,0,0,'You found it! So the rumors were true!$B$BThank you, $N. My patron, Count Remington Ridgewell, will be quite pleased to see this addition to this collection.',12340),
	 (4765,2,0,0,0,0,0,0,0,'Ah, so you are he! You have my thanks, $N. And... if you didn''t already know... the gratitude of a noble in the house of Ridgewell is nigh worth a king''s ransom.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (4766,1,0,0,0,0,0,0,0,'You came from Stormwind? Wonderful -- I know of an object of art that Remington would kill to have in his museum, but extracting it won''t be easy.$B$BThat''s where you come in.',12340),
	 (4767,0,0,0,0,0,0,0,0,'Perfect! With these eggs I hope to take the next step to become a wind rider. Here is a token of my appreciation; may good hunting always shine upon you, $C.',12340),
	 (4768,1,2,0,0,0,0,0,0,'Excellent. The formulae etched into this tablet will consume days of research, but I am confident such research will bear sweet fruit.$b$bThank you, $N. You have been invaluable to us.',12340),
	 (4769,273,0,0,0,0,0,0,0,'It is true. I believe there is a tablet held within Blackrock Spire, a tablet that contains old alchemical recipes. I am glad you are here, for I need help in retrieving the tablet.$B$BMake yourself comfortable, and I will explain further.',12340),
	 (4770,5,1,0,0,0,0,0,0,'What!? If I knew that Pao''ka Swiftmountain was going to snoop around Highperch, I would have chained him to a totem! His father was reluctant allowing him to come with me to Thousand Needles. We came here to study the different creatures that inhabit these beautiful lands.$b$bI appreciate the help you have shown Pao''ka. I hope this covers any misfortunes this deed has cost you.',12340),
	 (4771,4,1,2,0,0,0,0,0,'You did it! Vectus is defeated! And Dawn''s Gambit... did it work?$B$BHm... maybe my device wasn''t the success I had hoped, but I''m glad you were able to handle things anyway. Well done, $n!$B$BThe Argent Dawn, and the good people of Azeroth, are in your debt.',12340),
	 (4781,4,1,0,0,0,0,0,0,'Perfect, $N. I''m glad you could find a miner to help you out so quickly. Or did you do this work yourself? Either way, you''ve done well. This will be perfect for the thread.$B$BIt will take some time to create the stuff, so you''ll have to come back--I actually send it off to some princess who we have locked in a tower who''s only job is to spin gold thread... no, seriously. I mean it... okay, not really.',12340),
	 (4782,1,1,0,0,0,0,0,0,'Good, you''ve returned, $N. And where is the thread?$B$BAh, I understand. That is acceptable. The goblin and his brother have not failed us yet--I suppose it is understandable that he did not have it prepared right then. So be it... we have other things we can attend to in the meantime.$B$BAre you prepared for the next step?',12340),
	 (4783,21,6,0,0,0,0,0,0,'Excellent, $N. These will do nicely. I will prepare them now while you move on to your last two components. Are you ready?',12340),
	 (4784,4,1,0,0,0,0,0,0,'Excellent, $N! The components are gathered and we are ready.$B$BI trust you will be pleased.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (4785,0,0,0,0,0,0,0,0,'Here you go, $N. And please tell Menara we say hello.$B$BWe expect great things of you. Perhaps when the Legion falls to its knees, your name will be spoken aloud and in praise of your power. I can''t wait!',12340),
	 (4786,1,1,0,0,0,0,0,0,'It is done, $N. Here you are. Wear it with pride.$B$BYou''ve worked hard and I see great things in your future. Remember, to defy the corruption that comes with our path takes great will and fortitude. As long as your will is your own, then you shall have great success.',12340),
	 (4787,5,2,0,0,0,0,0,0,'Ah, you have the egg! I bow to you, $N. Your strength and bravery will be long remembered.',12340),
	 (4788,5,1,0,0,0,0,0,0,'Unbelievable!  You found them!  You truly are a hero, $N!$B$BThat''s a good thing, because I''ve been reading the tablets you brought me before, and from what I gathered... we''re going to need a hero to stop what''s coming...',12340),
	 (4801,0,0,0,0,0,0,0,0,'Mau''ari can derive da juju for $N... Use da Cache of Mau''ari to cast dis upon yourself or your allies.',12340),
	 (4802,0,0,0,0,0,0,0,0,'Mau''ari can derive da juju for $N... Use da Cache of Mau''ari to cast dis upon yourself or your allies.',12340),
	 (4803,0,0,0,0,0,0,0,0,'Mau''ari can derive da juju for $N... Use da Cache of Mau''ari to cast dis upon yourself or your allies.',12340),
	 (4804,0,0,0,0,0,0,0,0,'Mau''ari can derive da juju for $N... Use da Cache of Mau''ari to cast dis upon yourself or your allies.',12340),
	 (4805,0,0,0,0,0,0,0,0,'Mau''ari can derive da juju for $N... Use da Cache of Mau''ari to cast dis upon yourself or your allies.',12340),
	 (4806,0,0,0,0,0,0,0,0,'Mau''ari can derive da juju for $N... Use da Cache of Mau''ari to cast dis upon yourself or your allies.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (4807,0,0,0,0,0,0,0,0,'Mau''ari can derive da juju for $N... Use da Cache of Mau''ari to cast dis upon yourself or your allies.',12340),
	 (4808,0,0,0,0,0,0,0,0,'That''s no blanket! But what have we here? I letter from Tinkee? I wonder what she has to say...$b$bAh, she''s studying in the Burning Steppes. That makes sense--that''s a good source for dragonkin. Oh, but look! It says here that she needs some parts for a device she wants to build. I guess that''s where I come in, eh?',12340),
	 (4809,0,0,0,0,0,0,0,0,'These are good specimens. They''re packed with cold! Let me get some gloves on, then pack them along with the other things Tinkee needs...',12340),
	 (4810,4,0,0,0,0,0,0,0,'You brought them! Great! I''ll get to work right away! Thanks a ton, $N!$b$bYou''ve been so helpful to me, I might need you for even more important tasks later...',12340),
	 (4811,4,0,0,0,0,0,0,0,'So the crystal exists, $N? Fascinating... anyway, your task has been well executed; good work!$B$BWhat exactly is this crystal? This is but a single question in a sea of questions. Another question that comes to mind is why the moonkin would be drawn to this object? Is the crystal benign in nature, or does it hold a more sinister purpose?$B$BI have many more questions, but we''re going to need to examine that crystal closely to get some answers.',12340),
	 (4812,0,0,0,0,0,0,0,0,'You have made it once more to the mysterious crystal. Removing the stopper on the tube of moonwell water, you gingerly pour the contents out over the top of the crystal. As the water cascades down its lattices, you see the opaque surface turn transparent...',12340),
	 (4813,6,1,0,0,0,0,0,0,'Well, it would seem that even though we know more about this crystal, more unanswered questions are the result!$B$BI''ll take the information you''ve uncovered to the council here in Auberdine. Perhaps they''ll know a course of action to follow on this crystal. Well, that is if there is one to be taken; for now, the threat remains far enough to our east to be out of harm''s way.$B$BAs for you, please have this. Consider it a reward for a job well done, $N.',12340),
	 (4821,1,0,0,0,0,0,0,0,'Yes, finally... the mysterious egg has finally been delivered to me. Now, let me take a closer look at this... What..! What is this..?$b',12340),
	 (4822,4,0,0,0,0,0,0,0,'Mmmmmmmmm! I love their strawberry ice cream! If there''s one thing Tigule and Foror know to do, it''s make ice cream!$B$BThank you very much $N - this is the best treat ever!',12340),
	 (4841,0,0,0,0,0,0,0,0,'For my gratitude, this is for you, $N.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (4842,1,0,0,0,0,0,0,0,'Yes, the demons there in Darkwhisper Gorge; I believe it is their presence that is affecting the land in this way. I am going to continue observing the hot springs here and see if I learn anything more.$b$bI''d wait until you are a bit stronger if you have plans of heading farther into Darkwhisper Gorge.',12340),
	 (4861,0,0,0,0,0,0,0,0,'A severely damaged crate stands out among the rest of the destroyed belongings at the camp...',12340),
	 (4862,4,0,0,0,0,0,0,0,'What a load! I mean, look at all those eggs! These should bring in a right few gold.$B$BAs promised, here''s your own little critter. Don''t get bitten!',12340),
	 (4863,0,0,0,0,0,0,0,0,'Approaching the wagon, it doesn''t appear that there is much more here for Jaron. But, looking on the ground, you notice some crates that look undamaged, despite being half-buried in the snow.',12340),
	 (4864,1,2,0,0,0,0,0,0,'Well, I expected to hear as much, lad. I figured that the crazed beasts destroyed all of my belongings...$B$BBut you did find my tools, and most importantly, the amulet! I wonder why the wildkin so fiercely defended this item... In any case, I''ll think twice before heading their way again!',12340),
	 (4865,5,0,0,0,0,0,0,0,'Vengeance! So, the legend of Arikara is true. Indeed, this is a problem that must be resolved immediately.',12340),
	 (4866,4,6,0,0,0,0,0,0,'This is gonna make the best ale yet!$B$BEh, what did you think I was gonna use this for? Poison or something??$B$BCrazy kids...',12340),
	 (4867,0,0,0,0,0,0,0,0,'Aha! I can already feel my powers returning to me. And my mind is no longer wracked by Urok''s curse.$b$bThank you, $N! Humility is below me, but I must acknowledge your aid.$b$bAnd I bid you fortune in your journeys through Blackrock Spire. You are a fool to think you could make your way to the top, but your bravery is without question.',12340),
	 (4881,11,0,0,0,1000,0,0,0,'They come to kill me? I will show them how a Tauren fights!',12340),
	 (4882,0,0,0,0,0,0,0,0,'An important discovery?',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (4883,1,0,0,0,0,0,0,0,'The energy of this necklace, $N. I believe that it has only one source.$b$b<Nara closes her eyes and is quiet for a moment.>$b$bThe wildkin, now misguided and confused, were once not so. They once had a purpose, and were guided to serve. The night elf goddess Elune created these creatures to guard her most sacred areas.$b$bWhile this fact may seem like it holds little value; I urge you to look deeper.$b$bYou will learn, in time. Thank you for bringing this to me, $N.',12340),
	 (4901,6,0,0,0,0,0,0,0,'Did you meet up with Ranshalla?',12340),
	 (4902,6,0,0,0,0,0,0,0,'Do not hesitate; tell me why you have come.$B$BOh, yes? Hmm. Well.$B$BThank you for bringing this straight to me; it is always best to go right to the top... But... Yes. The druids of the Cenarion Circle have known of the Wildkin for some time. That they are pets of Elune, and were chosen to guard the most sacred of places.$B$BSo while this isn''t news, I definitely compliment you on your effort. Here, take this -- it is something that seems suitable for such a deed.',12340),
	 (4903,0,0,0,0,0,0,0,0,'<Warlord Goretooth''s dull green skin turns a pasty white for a brief moment.>',12340),
	 (4904,0,0,0,0,0,0,0,0,'Thank you, $N. Deep in my bones I knew that she would find her way back to me. She told me of your bravery and how you helped her escape. These items belonged to her brother. I know she would want you to have them.',12340),
	 (4906,1,2,0,0,0,0,0,0,'Thank you for all you have done, $N. May Elune protect you and guide you on the path ahead.',12340),
	 (4907,5,25,0,0,0,0,0,0,'Felnok was right! I do need your help again, and this time... it''s going to be really dangerous.$b$bAre you ready??',12340),
	 (4921,2,0,0,0,0,0,0,0,'I understand. Thank you, $C.',12340),
	 (4941,0,0,0,0,0,0,0,0,'<Thrall appears dismayed by the news you bring.>',12340),
	 (4961,4,1,0,0,0,0,0,0,'Nicely done, $N!  You gave that demon a lesson he won''t soon forget. You''ve shown great power and skill. Now I suppose it''s time you return to Menara with your cleansed orb so you can put it to good use.$B$BGood luck, $C. Perhaps our paths will cross again.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (4962,21,1,0,0,0,0,0,0,'Ah, the spirit of a felhound. Well done, $N.$B$BWhen I have both the spirit and the cleansed orb, I will merge the two for you, but not until then.',12340),
	 (4963,21,1,0,0,0,0,0,0,'Ah, the spirit of an infernal. Well done, $N.$B$BWhen I have both the spirit and the cleansed orb, I will merge the two for you, but not until then.',12340),
	 (4964,1,1,0,0,0,0,0,0,'It is done, $N. Simply tell me which you''d prefer: a staff that would require you to use both hands, or an orb so you may use a dagger or sword as your weapon.$B$BTackling a felhound was a great feat on your part. I am sure your item will serve you well in the future. Continue to work hard in the arts, $N. I will be awaiting details of your exploits.',12340),
	 (4965,6,1,1,0,0,0,0,0,'Ah, you do seek something more... substantial. That I can help you if you truly are prepared.$B$BIt''s a welcome change to see one of our kind seeking more power in forms other than just knowledge.$B$BSo, do you feel you''re ready, $N?',12340),
	 (4966,1,0,0,0,0,0,0,0,'Thank you for your help, $N. I couldn''t have held them off without you.',12340),
	 (4967,6,1,1,0,0,0,0,0,'Ah, you do seek something more... substantial. That I can help you if you truly are prepared.$B$BIt''s a welcome change to see one of our kind seeking more power in forms other than just knowledge.$B$BSo, do you feel you''re ready, $N?',12340),
	 (4968,6,1,1,0,0,0,0,0,'Ah, you do seek something more... substantial. That I can help you if you truly are prepared.$B$BIt''s a welcome change to see one of our kind seeking more power in forms other than just knowledge.$B$BSo, do you feel you''re ready, $N?',12340),
	 (4969,6,1,1,0,0,0,0,0,'Ah, you do seek something more... substantial. I can help you if you truly are prepared.$B$BIt''s a welcome change to see one of our kind seeking more power in forms other than just knowledge.$B$BSo, do you feel you''re ready, $N?',12340),
	 (4970,2,0,0,0,0,0,0,0,'Thank you for assisting me, $N. My opinion of you grows as time passes.',12340),
	 (4971,2,0,0,0,0,0,0,0,'Time feels easier to mend now, thank you $N.  While you might not understand fully the consequences of a fractured timeline, I appreciate that you understand the urgency of countering what I suspect more and more to be a Scourge-driven malfeasance.$B$BI see no harm in rewarding you for your assistance, mortal.  Your greatest feats are to come, and the awarding of a bauble will certainly not alter your future destiny.  Your continued aid, however, is something that I and the dragonflight could use...',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (4972,2,0,0,0,0,0,0,0,'These are exactly what I need, $N.  Thank you.$B$BAllow me to suitably reward you with this.  You may not understand what you would need with such a device.  You might not even know quite what it really is.  Alas, I cannot tell you when you will find it most useful; just know that at some point in the future, you may find this item to have extreme utility and function when consumed.  Whether or not you choose to hold on to it until then... this, my friend, is up to you.',12340),
	 (4973,2,0,0,0,0,0,0,0,'Again, I thank you for your assistance.  Please accept this gift.  While you still may not know when to use such an item, perhaps in the future the path of time will reveal its true intentions to you.  You could say that I''ve seen as such happening to you, $N.',12340),
	 (4974,1,1,0,0,0,0,0,0,'You have dealt a crippling blow to the forces of Blackrock, $N. With their Warchief slain, the Blackrock legion is once again thrown into the maw of chaos.$B$BIn honor of your heroics, the people of Kalimdor shall be rewarded!',12340),
	 (4975,1,1,0,0,0,0,0,0,'It is done, $N. Simply tell me which you''d prefer: a staff that would require you to use both hands, or an orb so you may use a dagger or sword as your weapon.$B$BTackling the infernal was a great feat on your part and this reward will fit you nicely. I wish you further success in the arts, $N.',12340),
	 (4976,21,1,0,0,0,0,0,0,'Well done, $N. This will do nicely.$B$BThe only thing left for you to do is to decide on which demon you want me to imprison within the cleansed orb. Do that, and you will have a magnificent new item to wield.',12340),
	 (4981,1,5,1,11,0,0,0,0,'I won''t lie to you, $R. I needed the money! Kibler pays very, very well - much better than the K.E.F. ever could.$b$bBut don''t doubt my loyalties! Why do you think I''m down here? To get that crazy goblin some exotic animal eggs or something equally inane? No, only someone truly daft would come to Blackrock Spire to collect pets. Yep, I don''t reckon too many people like that exist in this world.$b$b<Bijou laughs.>$b$bThe last thing we need are those kinds of people breeding.',12340),
	 (4982,4,1,0,0,0,0,0,0,'You''ve done it! Once Lexlort has these plans, he''ll forget all about the nasty things he wanted to do to me.$B$B$N, you''re my hero!',12340),
	 (4983,1,1,0,0,0,0,0,0,'I''ve got to hand it to her; she''s managed to weasel her way out of another sticky situation! These reports will prove to be invaluable in our dealings with the Blackrock orcs.$b$bOf course, you will be rewarded for your hard work.',12340),
	 (4984,0,0,0,0,0,0,0,0,'I... I sense that the souls of those wolves you have put down now have rest.  They - and I - thank you for a merciful release.$B$BThe wolves are not alone in their suffering within this damnable place, $N.  Please, I have need of you once more.',12340),
	 (4985,0,0,0,0,0,0,0,0,'"I know that the grizzlies have been put down, their torment at an end.  I... I have one more thing for you.  I wrote it down on... on this branch, sensing that my time in this realm had come to an end.$B$BIndeed... I am at that end.  Thank you again friend... the creatures of this accursed land may rest... and now shall I."$B$BWith that, a heavy sigh is uttered by the druid, followed by what sounds like a death rattle.  His body lies motionless on the cottage floor.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (4986,1,0,0,0,0,0,0,0,'This... this is quite strange.  This druid - this tauren druid no less - entrusted you with a great deal of valuable information on the extent of the Scourge''s plague.  I am surprised a tauren would give a $r such information, and freely at that if what you say is true.  We will make good use of this, I promise you.  Perhaps the tauren have not fallen as far from Cenarius as Fandral would believe...$B$BErm, anyway, please - accept this as a token of thanks from the Cenarion Circle.',12340),
	 (4987,1,0,0,0,0,0,0,0,'This is from Mulgris, you say? We had heard he sought to minister to the creatures suffering in the Plaguelands, but this is most unexpected... and most saddening. Mulgris is... was a good friend. I will mourn his passing deeply.$B$BHis efforts have not gone in vain, thanks to your diligence. In this branch, much lore is stored about the plague the Scourge propagates upon the land. We will study it diligently. As for you, please accept this. It is the least we can do for your noble efforts.',12340),
	 (5001,5,0,0,0,0,0,0,0,'Well I''ll be! Where were they??',12340),
	 (5002,1,1,0,0,0,0,0,0,'This coincides with much of what we already knew. Regardless, it is interesting and rather unfortunate information.$B$BThe markings on this map will prove valuable in thinning the Blackrock menace.',12340),
	 (5021,0,0,0,0,0,0,0,0,'A package in the barn that you might have otherwise overlooked now stands out amongst the decay and ruin.  Perhaps this is the one that the ghost of Janice Felstone was clamoring about...',12340),
	 (5022,6,0,0,0,0,0,0,0,'A package for an Emma Felstone, you say?  Last known address was Stormwind, four years ago?  Well let me see here...$B$BAccording to what we know, there was an Emma Felstone in the city about four years ago.  Well, I should say possibly - this census I refer to is from five years ago, and I don''t have a report of her vacating the city.  This doesn''t mean that she is still here though.$B$BWait a second... this package couldn''t be for Ol'' Emma, could it?',12340),
	 (5023,1,0,0,0,0,0,0,0,'A package for a Jeremiah Felstone, with his last known address as Lordaeron... I should be able to assist you.$b$bJeremiah Felstone was in the city before the plague. Well, I should say the former Jeremiah Felstone - some of the Forsaken have changed their last names to rid themselves of their former countenance. This case is no exception; the former Jeremiah Felstone is now known as Jeremiah Payson.$b$bWait a minute... isn''t he the cockroach vendor?',12340),
	 (5041,4,11,0,0,0,0,0,0,'Haha! Thank you, $N! This will help us greatly. You''re a boon to the Crossroads and to the Horde. If there is anything I can do for you, please, let me know.',12340),
	 (5042,0,0,0,0,0,0,0,0,'If only Mangletooth were free to see you decimate those who betrayed him! <snort>$B$BI thank you for destroying more of the Bristleback by gathering these shards. Please, continue to do so, and I will continue to aid you. <snort>',12340),
	 (5043,0,0,0,0,0,0,0,0,'May your aim be unerring, and the mark of your weapon be true, $R.$B$BAgamaggan''s spirit is with you. Return <snort> to me if you wish. Mangletooth will bless you again if the great boar god deems me worthy. <snort>',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (5044,0,0,0,0,0,0,0,0,'Your enemies should fear you even more, $R. <snort>$B$BTell Mangletooth tales of your cunning in battle when next we meet--be it in this life, or the next. <snort>',12340),
	 (5045,0,0,0,0,0,0,0,0,'Our greatest warriors, and our greatest <snort> shamans would envy your will, $R.$B$BDefeat more of the Bristlebacks knowing that they cannot stop you! <snort>',12340),
	 (5046,0,0,0,0,0,0,0,0,'Go to war, $R.',12340),
	 (5047,6,0,0,0,0,0,0,0,'Alive? Suit worked? And what do we have here?',12340),
	 (5048,1,0,0,0,0,0,0,0,'My name is indeed Emma Felstone - you''re the first person in years to call me that.  Who... who are you?$B$BYou say you knew... my sister?!  Is she still alive?  Who am I kidding, of course she isn''t.  When the plague broke out in Lordaeron, I had come to expect the worst.  So many of my family died... or worse.  Here I am now, crazy Ol'' Emma, all alone.  What are you, a grave-robber or something?  Looking for your next target?$B$BWhat... you have a package for me from my sister?',12340),
	 (5049,0,0,0,0,0,0,0,0,'I haven''t used that name in years... but yes, at one point in my life - before this glorious unlife - that was my last name.$b$bYou claim to have known my sister... or rather, have recently spoken to my sister.$b$bWho''s been dead.$b$bFor four years.$b$bYou know, if my bones weren''t already brittle enough, I''d be tempted to break my foot off on your posterior. You''re quite the vulture, aren''t you?$b$b What... you have a package for me from my sister?',12340),
	 (5050,0,0,0,0,0,0,0,0,'You give the half-charm back to the apparition.  She looks at it, then at you expectantly.$B$B"Honey, where did you put your half of the charm?  We can''t be together unless we have both halves.  Honey... can you see me?"',12340),
	 (5051,0,0,0,0,0,0,0,0,'You hand the reassembled good luck charm to Janice Felstone''s ghost.  As soon as she grasps it, you observe an almost immediate change in her.  Her ethereal form shimmers, and she looks upon you with clear yet sad eyes.$B$B"You''ve freed me... I no longer will need this charm.  Please, take it and perhaps it will give you the solace it has given me."',12340),
	 (5052,0,0,0,0,0,0,0,0,'Ah, you do understand. <snort> My words were not lost on your ears, $R. Mangletooth may be caged, but no cage can stop Agamaggan''s power! <snort>$B$BThe touch of the shard, the feel of it... it has been a long time, $R.$B$BDo you know what it is like? To have your power severed from you?$B$BBut, that is a tale for another time. I promised you information. I promised you Agamaggan''s power. My people turned their backs on Mangletooth. Now, I lose you upon them. <snort>',12340),
	 (5054,1,0,0,0,0,0,0,0,'This was no easy task, yet you have excelled. But do not be too quick to think you have impressed me, $N.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (5055,0,0,0,0,0,0,0,0,'Yes. You have returned. I believe now that you are a true $C by nature. You have faced the most ferocious of creatures and have returned, surpassing my expectations.$b$bYou are now ready for my final request.',12340),
	 (5056,1,2,0,0,0,0,0,0,'You have proven both your strength and your determination. Many more challenges await you, but I have already shown you as much as I am able.$b$bGood luck, $N.',12340),
	 (5057,1,1,1,0,0,0,0,0,'We learn from our life experiences, $N. I am sure that you have only become stronger and wiser as a result of yours. You have grown much since we first spoke.$b$bTake this in remembrance of the difficult tasks you have accomplished as a $R $C, and know that you will always have my respect and admiration.',12340),
	 (5058,0,0,0,0,0,0,0,0,'A diary with yellowing pages lies open to the last entry:$B$B"I don''t know what''s going to happen now that Harold''s turned.  It took everything out of me to drag him into the only place I could find that''d lock him up tight and hold him.  I hid the key on me, and I pray it works...$B$BI hope I can get out of here, but I need money to do that.  Our stuff''s all in the cabinet I think... and now that I think about it, doesn''t Harold keep the key on him?$B$BI''ll rest on it, I''m dead tired now."',12340),
	 (5059,0,0,0,0,0,0,0,0,'Using the key found on the skeleton of the former Mrs. Dalson, you unlock the door to the outhouse.  A bloodthirsty ghoul leaps from the outhouse, having been trapped inside for who knows how long.$B$BIt is clear by the bloodcurdling scream of the ghoul at your presence that the former Farmer Dalson is now beyond saving.',12340),
	 (5060,0,0,0,0,0,0,0,0,'The key taken from Farmer Dalson''s ghoulish remains fits the lock perfectly.  The doors of the cabinet swing open, revealing several items that remain intact and appear quite valuable.',12340),
	 (5061,0,0,0,0,0,0,0,0,'Very impressive, $N. You are ready to learn your aquatic form, and it is my pleasure to teach it to you.$B$BAlso, in recognition of your achievement during the two trials, I give you this item. I hope you''ll find it to be a welcome addition to your gear as a protector of nature and a keeper of the balance.',12340),
	 (5062,1,0,0,0,0,0,0,0,'Good, you have gathered the essential amount of Incendia agave. This rare herb found only in Thousand Needles will help light the dormant sacred fire of life.$b$b<Magatha begins to enchant the Incendia agave.>',12340),
	 (5063,5,0,0,0,0,0,0,0,'Astounding! It must have taken weeks to gather those components... and how did you find a pristine hide?!?$b$bEnjoy the cap, $n!',12340),
	 (5064,0,0,0,0,0,0,0,0,'Great Spirit Totem! This is dire news indeed. I must begin to plan for whatever may come.$b$b$N, as promised, here is your reward for your brave service.$b$b',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (5065,2,1,0,0,0,0,0,0,'You found them!  Great!$B$BThank you, $N.  I will pour over these texts and decipher their meaning.$B$BYou, however, have another task...',12340),
	 (5066,66,0,0,0,0,0,0,0,'Welcome to the Plaguelands, hero.  This is one of the most dangerous frontiers in Azeroth, especially with the looming threat of the Scourge to our north and northeast.  I am glad to hear that the clarion call of duty and service to the greater good did not fall on deaf ears with you!$B$BIf you are ready to get your hands dirty, then there is plenty for willing and able heroes to do here on the edge of the Plaguelands.',12340),
	 (5067,21,0,0,0,0,0,0,0,'Few more improbable tasks I have seen completed by mortals. Bask in the glory of my handiwork! Reap its rewards!',12340),
	 (5068,1,0,0,0,0,0,0,0,'I thought I would be dead and buried before I ever saw this day.$B$BAn accomplishment of this magnitude can only be overshadowed by the reward.',12340),
	 (5081,1,0,0,0,0,0,0,0,'Excellent work, $N. At the very least, you have bought us more time - precious, precious time.',12340),
	 (5082,1,6,0,0,0,0,0,0,'Thanks so much, $N! Now I can get back to work here.$B$BDid you find anything of interest at the Winterfall camp?',12340),
	 (5083,6,0,0,0,0,0,0,0,'You got this from the Winterfall?',12340),
	 (5084,0,0,0,0,0,0,0,0,'Inside the cauldron bubbles a rotting, repulsive-smelling substance...',12340),
	 (5085,5,0,0,0,0,0,0,0,'You are very resourceful, $N. Do you think that the Winterfall furbolgs have been to the Deadwood camp?',12340),
	 (5086,1,0,0,0,0,0,0,0,'I have to compare this to the substance you found in the cauldron, and then I''m sure we''ll know more.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (5087,0,0,0,0,0,0,0,0,'<Donova examines the contents of the crate>$b$bI wonder if consuming this substance makes the furbolg more aggressive. They do seem much larger...',12340),
	 (5088,6,2,0,0,0,0,0,0,'This does not make sense. Why would Arikara be after Cairne Bloodhoof? Magatha could not be wrong, she is our most powerful shaman.$B$B<Motega shakes his head.>$B$BRegardless, your great deed to the Horde shall not go unnoticed - please, choose one of these as a reward for your aid.',12340),
	 (5089,1,0,0,0,0,0,0,0,'The plot thickens...',12340),
	 (5090,66,0,0,0,0,0,0,0,'Welcome to the Plaguelands, hero. This is one of most dangerous frontiers in Azeroth, especially with the looming threat of the Scourge to our north and northeast. I am glad to hear that the clarion call of duty and service to the greater good did not fall on deaf ears with you!$b$bIf you are ready to get your hands dirty, then there is plenty for willing and able heroes to do here on the edge of the Plaguelands.',12340),
	 (5091,66,0,0,0,0,0,0,0,'Welcome to the Plaguelands, hero.  This is one of the most dangerous frontiers in Azeroth, especially with the looming threat of the Scourge to our north and northeast.  I am glad to hear that the clarion call of duty and service to the greater good did not fall on deaf ears with you!$B$BIf you are ready to get your hands dirty, then there is plenty for willing and able heroes to do here on the edge of the Plaguelands.',12340),
	 (5092,4,0,0,0,0,0,0,0,'Mission accomplished, $N!  Well played, well played.$B$BAllow me to reward your work thus far with some coin from the Stormwind coffers.  I''d recommend spending it on materiel that will aid you in your next mission... one that will take you into the ruins of Andorhal itself.$B$BBe ready!  Be vigilant!',12340),
	 (5093,66,0,0,0,0,0,0,0,'Welcome to the Plaguelands, hero. This is one of the most dangerous frontiers in Azeroth, with the looming threat of the Scourge to our east, and then even further still eastward from there. I am glad to hear that the call of duty and service to the Horde did not fall on deaf ears with you!$B$BIf you are ready to get your hands dirty, then there is plenty for willing and able heroes to do here on the edge of the Plaguelands.',12340),
	 (5094,66,0,0,0,0,0,0,0,'Welcome to the Plaguelands, hero. This is one of most dangerous frontiers in Azeroth, with the looming threat of the Scourge to our east, and then even further still eastward from there. I am glad to hear that the call of duty and service to the Horde did not fall on deaf ears with you!$b$bIf you are ready to get your hands dirty, then there is plenty for willing and able heroes to do here on the edge of the Plaguelands.',12340),
	 (5095,66,0,0,0,0,0,0,0,'Welcome to the Plaguelands, hero. This is one of the most dangerous frontiers in Azeroth, with the looming threat of the Scourge to our east, and then even further still eastward from there. I am glad to hear that the call of duty and service to the Horde did not fall on deaf ears with you!$B$BIf you are ready to get your hands dirty, then there is plenty for willing and able heroes to do here on the edge of the Plaguelands.',12340),
	 (5096,4,0,0,0,0,0,0,0,'Finely executed, $N. Your attack on the Scarlet Crusade will buy us time. I have sent one of my best scouts out to watch over the camp and make sure that the Crusade forces that come to reinforce the position will take the bait.$B$BWith the pressure on us lessened, we should now finally be able to risk a mission into Andorhal itself, and an important one at that. I''d very much like it if you''d perform this one as well, based on your success to date.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (5097,4,0,0,0,0,0,0,0,'My priests are reporting that our beacon trackers are picking up extremely strong signals on all four towers!  Dare I say it, but I believe you''ve executed another mission with complete and total success!  Well played once again, $N!$B$BWith the towers marked, our preparations for the attack are now in place.  The time has come to take the fight to the Scourge!',12340),
	 (5098,5,0,0,0,0,0,0,0,'My warlocks are reporting that our beacon trackers are picking up extremely strong signals on all four towers!  You''ve executed my orders with the skill and precision of a seasoned veteran.  Your service to the Horde is duly noted once more, $N!$B$BWith the towers marked, our preparations for the attack are now in place.  The time has come to take the fight to the Scourge!',12340),
	 (5102,1,66,0,0,0,0,0,0,'Surely, we will strike against their dragon lords next. Well done, brave soldier of the Alliance! Well done, indeed.',12340),
	 (5103,0,0,0,0,0,0,0,0,'What the...',12340),
	 (5121,2,0,0,0,0,0,0,0,'Thank you so much, $N. I hope to get back to my studies without worry that I will be ambushed. Please accept this as a reward.',12340),
	 (5122,0,0,0,0,0,0,0,0,'You retrieved the medallion! Now I will be able to leave the chapel and perform my duty.$B$BThat duty is to kill the beast who helped corrupt me and so many of my brothers and sisters, Baron Rivendare!',12340),
	 (5123,1,0,0,0,0,0,0,0,'I wonder what all of this means... I can''t make anything out...',12340),
	 (5124,0,0,0,0,0,0,0,0,'As promised, $N, here''s your recipe! I''m also going to throw in a little something extra for all of your hard work and dedication. What am I going to do with these anyway???',12340),
	 (5125,0,0,0,0,0,0,0,0,'$N, I am dying... but my soul is saved.  For that, I owe you more than words can say.  Please, take this... and fight on, brave $C!',12340),
	 (5126,0,0,0,0,0,0,0,0,'<Lorax laughs.>',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (5127,0,0,0,0,0,0,0,0,'Our pact you did not break. The soul I did take. The reward I shall make.',12340),
	 (5128,1,1,0,0,0,0,0,0,'Yes, if you let me examine this for a while, I might be able to translate it for you.$b$b<Kelek flips through the pages.>$b$bWhen I am able to look over this fully, I will send word to you.$b$bThank you for sharing this with me, $N. Very little is known about the Winterfall furbolg.',12340),
	 (5141,0,0,0,0,0,0,0,0,'I''ll hand it to you - it takes a strong will to make a permanent decision like you''ve just done. I assure you, dragonscale leatherworking will prove to be a profitable and rewarding path for you to follow.$B$BTo train in the art for the future, simply speak to me and I will make available any knowledge that you have yet to commit as yours.',12340),
	 (5142,1,0,0,0,0,0,0,0,'Hello.  I''m Pamela, what''s your name?',12340),
	 (5143,1,1,0,0,0,0,0,0,'You''ve given your finest offerings, and nature will soon permit you to bend her to your will. Once I have finished my tutelage, your work will be a force of nature unto itself.$B$BTo train in the art for the future, simply speak to me and I will make available any knowledge that you have yet to commit as yours.',12340),
	 (5144,0,0,0,0,0,0,0,0,'You''ve cast your lot, and the elements accept you. Once I have finished my tutelage, you shall command the will to craft the finest of leather garbs.$B$BTo train in the art for the future, simply speak to me and I will make available any knowledge that you have yet to commit as yours.',12340),
	 (5145,25,1,0,0,0,0,0,0,'I''ll hand it to you - it takes a strong will to make a permanent decision like you''ve just done. I assure you, dragonscale leatherworking will prove to be a profitable and rewarding path for you to follow.$b$bTo train in the art for the future, simply speak to me and I will make available any knowledge that you have yet to commit as yours.',12340),
	 (5146,25,1,0,0,0,0,0,0,'You''ve cast your lot, and the elements accept you. Once I have finished my tutelage, you shall command the will to craft the finest of leather garbs.$B$BTo train in the art for the future, simply speak to me and I will make available any knowledge that you have yet to commit as yours.',12340),
	 (5147,1,0,0,0,0,0,0,0,'Hah! Well, this is excellent news! I was starting to think that he would never be brought to justice!$b$bHere you are, $N... and thanks. News of Anrak''s foul deeds boiled my blood!',12340),
	 (5148,0,0,0,0,0,0,0,0,'You''ve given your finest offerings, and nature will soon permit you to bend her to your will. Once I have finished my tutelage, your work will be a force of nature unto itself.$B$BTo train in the art for the future, simply speak to me and I will make available any knowledge that you have yet to commit as yours.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (5149,0,0,0,0,0,0,0,0,'You found it!  You found my doll!  Oh, thank you!',12340),
	 (5150,0,0,0,0,0,0,0,0,'Placing the sprouts in front of her, Dadanga seems pleased.$B$BShe nudges a small brown-wrapped package towards you, in exchange for the treat!',12340),
	 (5151,0,0,0,0,0,0,0,0,'My hypercapacitor! This will keep me busy for a while until I can figure out what it does...',12340),
	 (5152,6,18,1,0,0,0,0,0,'You saw Pamela?  How is she?  Is she alive??  Oh, no!  Poor Pamela!  She was so young, and such a happy child...$B$BShe doesn''t know what happened to her father, does she?  My brother, Joseph?$B$BNo... she couldn''t understand what happened to Joseph.  And even if she could, I don''t have the heart to tell her...',12340),
	 (5153,1,0,0,0,0,0,0,0,'What is this?  A wedding ring?  Let me see...$B$BAh!  This ring was once on the hand of a great man, but there is much tragedy in that man''s past.$B$BAre you here to help him?  It''s far too late for him now... but perhaps we can help him in the past!',12340),
	 (5154,6,5,0,0,0,0,0,0,'Well done, you found it!$B$BDid you read it?  Is Joseph Redpath mentioned?  If he is, then perhaps we can save him!$B$BAh.  The Annals of Darrowshire tell a very unsettling tale.  It says that during the battle, Joseph Redpath was corrupted and joined the ranks of the Scourge!  He then betrayed the defenders of Darrowshire.$B$BThat is an ill fate.  If we can, we should try to change that fate, don''t you think?',12340),
	 (5155,4,1,1,0,0,0,0,0,'Good, $N! With their numbers weakening, we can further press them.$b$bHow was your first taste of their power? Were they as strong as you thought they would be? Stronger? Or perhaps they were no challenge for you at all. Wouldn''t that be something?$b$bWe can discuss the details of your exploits later. There are other things we must focus on now.',12340),
	 (5156,0,0,0,0,0,0,0,0,'Good that you''re alive, $N. Bad that the water still exists. I was hoping to find at least one pure source of water here in Felwood. It looks like my search has failed. The process of healing the land could have been made much easier with its existence.$b$bI will have to concern myself with saving what forest creatures I can while destroying those that have become so corrupt that they endanger themselves as much as travelers through this once-mighty forest.',12340),
	 (5157,2,1,0,0,0,0,0,0,'This will do nicely, $N.$b$bNow all we have to do besides apply the waters to the braziers is to have it purified. That should not be difficult--it should only require a little travel.$b$bHopefully we can do this quickly.',12340),
	 (5158,1,1,0,0,0,0,0,0,'Ah, you need the water from this Moon Well cleansed. Stopping this force of malice in Felwood seems noble enough, but it is not for me to decide if the water will be purified. I will ask the spirits of water--it will be up to them to decide if the cause is just.$b$bGive me a moment and I will tell them of your plea. I hope they are as sympathetic as I am to your cause.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (5159,4,1,0,0,0,0,0,0,'This should be more than enough water for our purposes.$b$bI''m glad to hear that Islen was able to help us. Her strength with the water spirits has always been a strong one. She is also wise, and rare is it that the spirits do not agree with her purpose. The fact that both of them have blessed our task gives me hope that we are on the right path.',12340),
	 (5160,1,0,0,0,0,0,0,0,'The Aspects insist that we stay out of the affairs of mortals. In this world, however, such a thing is not always possible - especially when one of our own contemptuously disregards such edicts.',12340),
	 (5161,0,0,0,0,0,0,0,0,'So it shall be...',12340),
	 (5162,2,0,0,0,0,0,0,0,'I am Jeziba, known to many as the Sculptor. What I sculpt, however, are not statues, but heroes.$b$b',12340),
	 (5163,11,11,0,0,0,0,0,0,'Hah! They''ll think twice before making fun of my ideas again!$B$BThanks for your help, $N. I couldn''t have had so much fun without you!',12340),
	 (5164,0,0,0,0,0,0,0,0,'Hundreds upon hundreds of pages filled with garbled text and symbols make up the brunt of this book.',12340),
	 (5165,1,1,0,0,0,0,0,0,'I was able to see you with my spells as soon as the last brazier''s flames died. Well done, $N.$b$bI learned a few things before the Shadow Council''s warlocks were able to recast their spells. Hopefully it will be enough.$b$bFor now, rest. I will tell you what I''ve learned in a moment.',12340),
	 (5166,6,1,0,0,0,0,0,0,'Do you not yet understand? The journey was the destination. Can you not feel the battle scars? The pain you underwent?$B$BHaving survived the ordeal, you are a more powerful being. Much more powerful. This breastplate is merely a reflection of your own innate abilities.',12340),
	 (5167,5,0,0,0,0,0,0,0,'They will smell their kin as you enter their halls, $N. Crush them with their own fear!',12340),
	 (5168,1,0,0,0,0,0,0,0,'You have the libram and the shield!$B$BTheir history is entwined with the history of Darrowshire, and somehow, I know that fate will bring them together again.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (5181,1,0,0,0,0,0,0,0,'You found them!  Well done, $N!  These relics hold a power I do not fully understand, a power you will one day harness.$B$BThey also bring dark memories to my mind, memories of death and treachery, and of the last night of Darrowshire...',12340),
	 (5201,1,0,0,0,0,0,0,0,'I am relieved to hear that for a short moment, we will not have to worry about the Winterfall intrusion.$B$BYou are beginning to show your perseverance, $N.',12340),
	 (5202,4,0,0,0,0,0,0,0,'The key, you''ve found it! Please, give it to me and I can finally escape!',12340),
	 (5203,6,1,1,0,0,0,0,0,'You were the one who helped Arko escape? I''m so glad you found me. She passed by here not too long ago on her way to Darnassus. She had Lightforge in tow and wouldn''t even take time to speak to the druids to be healed. She said it was far too urgent.$b$bBut she did tell me about your encounter with Trey''s spirit. What a terrible fate for a Knight of the Silver Hand. She didn''t show it, but I know it''s tearing her up inside, the thought of losing one of her closest friends.',12340),
	 (5204,0,0,0,0,0,0,0,0,'You gather the paladin''s remains as carefully as you can, recalling that at least his spirit has been released from any pain or suffering that might have been forced upon him.',12340),
	 (5206,1,0,0,0,0,0,0,0,'You found them!  Wonderful!$B$BAlthough I don''t fully understand how they can help us, I feel their power and I know in my bones that they are linked to my home village of Darrowshire.',12340),
	 (5210,6,1,5,0,0,0,0,0,'What is this book?  The Annals of Darrowshire?  That was my home before the war... my home before the battle that destroyed it!  Why did you bring me this book?$B$BBut look here!  At the end there are pages that tell tales of the days beyond the battle!  Here is a passage about me!  And one about my brother Joseph!  Is this book true?$B$BWe must discover the truth!',12340),
	 (5211,1,0,0,0,0,0,0,0,'It is good to hear you found the tortured souls of my brethren and freed them.  My heart will weep less, knowing at least some of the defenders of Darrowshire no longer wallow in the vile subservience of the Scourge.',12340),
	 (5212,1,0,0,0,0,0,0,0,'There is something that has changed in the chemical structure of the plague''s active agents. More data is required.',12340),
	 (5213,5,1,1,0,0,0,0,0,'Astonishing! This will take months to dissect and analyze. The Argent Dawn thanks you for your efforts, $N.$B$BWith our blessing, take your pick between either this Seal of the Dawn or this Rune of the Dawn. You can use either of them instead of a standard Argent Dawn Commission to collect scourgestones on our behalf. Should you lose yours, speak with me and I''ll get you a replacement.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (5214,1,0,0,0,0,0,0,0,'Oh sweet, sweet stogie, how I have missed you...',12340),
	 (5215,2,0,0,0,0,0,0,0,'May the power of the Light shine upon you in these dark times, $c.  I am pleased to serve as your coordinator for our plan to sabotage the Scourge''s cauldrons.$B$BOur goal will be to change the composition of the plague that the cauldrons create into something that negatively affects the Scourge.  In order to affect this change, you will need to secure access to each of the four cauldrons present in the Western Plaguelands.$B$BStand ready hero, for a glorious battle against the vile Scourge awaits you!',12340),
	 (5216,0,0,0,0,0,0,0,0,'The key taken from Cauldron Lord Bilemaw is a perfect fit in unlocking the access panel.  A foul stench emanates from the opened panel as an unknown mix of concentrated substances swirl inside the cauldron.$B$BThere is a small spigot that the bottle fits well enough under, allowing you to draw a sample for High Priestess MacDonnell back at Chillwind Point.',12340),
	 (5217,4,0,0,0,0,0,0,0,'Well done $N - it should take Alchemist Arbington no time at all to analyze this and devise a counter agent to introduce into the cauldron.  If we are able to pump out enough of it into the air, we might be able to weaken all the Scourge present here.$B$BThis will no doubt be an ongoing ordeal; we will need to continually hit these cauldrons and introduce our reagents into their mix.  Still, if we can keep it up, we will have a huge advantage over Scourge when the time comes for battle!',12340),
	 (5218,0,0,0,0,0,0,0,0,'Adding the reagents to the cauldron''s mix begins to change the color and texture of the cloud it spews forth.  Scourge that are even remotely near the cauldron appear to recoil at the introduction of the new components into the environment.',12340),
	 (5219,0,0,0,0,0,0,0,0,'The macabre key found on the cauldron lord easily slides into a keyhole and then disappears, allowing you permanent access to it.  Crude, viscous ichors pulsate through twisted tubes within the cauldrons underpinnings.$B$BThere is a small spigot that the bottle fits well enough under, allowing you to draw a sample for High Priestess MacDonnell back at Chillwind Point.',12340),
	 (5220,21,0,0,0,0,0,0,0,'Ah, there is plenty in here for study.  Well done, $N!$B$BFor now, the next step is in our hands.  We''ll need to produce a list of reagents that, when combined with what is already in the cauldron, will act as its counter.$B$BThe only way we will be able to introduce this is by placing the reagents into the cauldron directly.  Alchemist Arbington will have more information on that, so be sure to speak with him at your earliest convenience.',12340),
	 (5221,0,0,0,0,0,0,0,0,'Adding the reagents to the cauldron''s mix begins to change the color and texture of the cloud it spews forth. Scourge that are even remotely near the cauldron appear to recoil at the introduction of the new components into the environment.',12340),
	 (5222,0,0,0,0,0,0,0,0,'The cauldron lord''s key unlocks the access panel to this cauldron and then disappears, much like the other keys have for the previous two cauldrons you''ve dealt of.  A putrid smelling substance churns violently beneath the platform of the cauldron.$B$BThere is a small spigot that the bottle fits well enough under, allowing you to draw a sample for High Priestess MacDonnell back at Chillwind Point.',12340),
	 (5223,21,0,0,0,0,0,0,0,'Another finely executed mission, $N!  This makes three cauldrons available to us to turn against the Scourge.  If Kel''Thuzad''s necromantic dominance over these lands wasn''t as strong as it currently is, I''d dare say you''d shut them down completely!$B$BAlchemist Arbington will have a report on what this cauldron - as well as the other cauldrons subverted - will require to deliver our counter agent to the plague.  With that, the time has come to bring the last cauldron of the west under our influence!',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (5224,0,0,0,0,0,0,0,0,'Adding the reagents to the cauldron''s mix begins to change the color and texture of the cloud it spews forth. Scourge that are even remotely near the cauldron appear to recoil at the introduction of the new components into the environment.',12340),
	 (5225,0,0,0,0,0,0,0,0,'Cauldron Lord Soulwrath''s key disintegrates as it touches the lock on the access panel at the base of the cauldron''s platform.  A slight clanking noise is heard within, and the access panel swings open to reveal more viscous toxins within the cauldron''s framework.$B$BThere is a small spigot that the bottle fits well enough under, allowing you to draw a sample for High Priestess MacDonnell back at Chillwind Point.',12340),
	 (5226,4,0,0,0,0,0,0,0,'Congratulations $N, you''ve unlocked the last cauldron for us!  Alchemist Arbington will soon know what this cauldron requires as far as reagents needed for the mix.$B$BAs for you, I am sure that Commander Valorfist will want to thank you personally for the assistance you''ve given us.  Without you, our struggle against the Scourge would have been nearly insurmountable.  Thank you, hero!',12340),
	 (5227,0,0,0,0,0,0,0,0,'Adding the reagents to the cauldron''s mix begins to change the color and texture of the cloud it spews forth. Scourge that are even remotely near the cauldron appear to recoil at the introduction of the new components into the environment.',12340),
	 (5228,2,0,0,0,0,0,0,0,'From the shadows, brother $R, I bid you greetings. I am to serve as your coordinator for our plan to sabotage the Scourge''s cauldrons.$B$BOur goal will be to change the composition of the plague that the cauldrons create into something that negatively affects the Scourge. In order to affect this change, you will need to secure access to each of the four cauldrons here in the Western Plaguelands.$B$BThe time has come for you to lead the charge against the Scourge, hero.',12340),
	 (5229,0,0,0,0,0,0,0,0,'The key taken from Cauldron Lord Bilemaw is a perfect fit in unlocking the access panel, though it disappears after you use it.  Still, you think you can open the panel now without a key.  A foul stench emanates from the opened panel as an unknown mix of concentrated substances swirl inside the cauldron.
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (5234,0,0,0,0,0,0,0,0,'Another finely executed mission, $N! This makes three cauldrons available to us to turn against the Scourge. If Kel''Thuzad''s necromantic dominance over these lands wasn''t as strong as it currently is, I''d dare say you''d shut them down completely!$b$bApothecary Dithers will have a report on what this cauldron - as well as the other cauldrons subverted - will require to deliver our counter agent to the plague. With that, the time has come to bring the last cauldron of the west under our influence!',12340),
	 (5235,0,0,0,0,0,0,0,0,'Cauldron Lord Soulwrath''s key disintegrates as it touches the lock on the access panel at the base of the cauldron''s platform. A slight clanking noise is heard within, and the access panel swings open to reveal more viscous toxins within the cauldron''s framework.$b$bThere is a small spigot that the bottle fits well enough under, allowing you to draw a sample for Shadow Priestess Vandis back at the Bulwark.',12340),
	 (5236,0,0,0,0,0,0,0,0,'Congratulations $N, you''ve unlocked the last cauldron for us! Apothecary Dithers will soon know what this cauldron requires as far as reagents needed for the mix.$b$bAs for you, I am sure that High Executor Derrington will want to thank you personally for the assistance you''ve given us. Without you, our struggle against the Scourge would have been nearly insurmountable. I thank you, mighty $C.',12340),
	 (5237,2,0,0,0,0,0,0,0,'$N, your successful re-engineering of the cauldrons is a tremendous victory for us!$B$B<The commander clears his throat and begins to bellow loudly.>$B$BLet all within my presence hear: for service to the Kingdom of Stormwind and to the Alliance above and beyond the call of duty - in the face of overwhelming odds and incredible danger, might I add - I give $N this, and I extend upon $Ghim:her; our undying gratitude as a true hero of the Alliance. Cheers, I say!',12340),
	 (5238,0,0,0,0,0,0,0,0,'$N, your successful re-engineering of the cauldrons is a tremendous victory for us!$B$B<The high executor clears his throat and begins to bellow loudly.>$B$BLet all within my presence hear: for service to the Forsaken and to the Horde as a whole above and beyond what was expected - in the face of overwhelming odds and incredible danger, might I add - I give $N this, and I extend upon $Ghim:her; our undying gratitude as a true hero of the Horde. Huzzah!',12340),
	 (5241,0,0,0,0,0,0,0,0,'You''ve seen Pamela?  She''s alive?$B$BShe''s dead?  No!  Oh, Pamela!  Why does your spirit still suffer in this world.  Why are you perished, while fortune keeps me alive?  In an instant I would switch places with you and wander dead Darrowshire, a ghost and alone!$B$BAh, but this news cannot change fate.  Thank you, $N.  Now my duty, my duty to revenge, burns hot as ever.  ',12340),
	 (5242,4,1,2,0,0,0,0,0,'Earthmother be praised, $N! Thank you! This is a great day, indeed!$b$bThe Shadow Council will be hard pressed to scale to the same levels of power they once held with this blow to their hierarchy. You have done a great thing this day!',12340),
	 (5243,1,1,0,0,0,0,0,0,'Well done, $R. You have proven that while you are tolerant of others, you will stop at nothing to destroy the minions of Kel''Thuzad.',12340),
	 (5244,1,1,0,0,0,0,0,0,'Well, sure, I can tell you more about Kel''Theril. Mind you now, I''m no historian, but I can tell ya about what I saw there...',12340),
	 (5245,0,0,0,0,0,0,0,0,'The past of the high elves is something that I do not wish to discuss, $N. Please, it pains me to think of all that has happened... And that there is no way to make things right.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (5246,1,0,0,0,0,0,0,0,'The pages have gone untouched for many many years...',12340),
	 (5247,1,0,0,0,0,0,0,0,'Using these elements, I can fuse the fragments together... to hopefully what they once were.',12340),
	 (5248,0,0,0,0,0,0,0,0,'Pleeease, leeeave meeeeee...',12340),
	 (5249,6,2,0,0,0,0,0,0,'A friend of Ivy Leafrunner? Nice to meet you, $N.',12340),
	 (5250,6,2,0,0,0,0,0,0,'A student of Daryn Lightwind? Nice to meet you, $N.',12340),
	 (5251,5,1,0,0,0,0,0,0,'Outstanding, $N! Years of intelligence, lost! The Scarlet Crusade will surely feel this blow in the coming weeks.',12340),
	 (5252,0,0,0,0,0,0,0,0,'Is that... what I think it is?',12340),
	 (5253,1,1,1,0,0,0,0,0,'I have heard of the Crystal of Zin-Malor; the user of the crystal becomes capable of incredible arcane power, but only if truly worthy. I am impressed that you not only recovered the crystal, but you also realize your own limits, and did not attempt to use the crystal yourself.$B$BThank you for bringing it to me, $N. We will keep it safe, and may the cursed sprits that once guarded the shattered crystal finally be at peace.',12340),
	 (5261,1,0,0,0,0,0,0,0,'That''s true.  I''m looking for someone to hunt me some wolves!  Are you that person?',12340),
	 (5262,5,6,0,0,0,0,0,0,'What will this mean to the Crusade? Could it be possible that they have been under the control of this demon? Unwittingly serving as the pawns to a greater evil?',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (5263,1,25,0,0,0,0,0,0,'It has been many years since I have ushered a champion into our ranks. You are the first to be granted audience with Lord Maxwell in years.',12340),
	 (5264,1,0,0,0,0,0,0,0,'You are a worthy ally, $N. You shall reap the rewards of your stalwart dedication.',12340),
	 (5265,0,0,0,0,0,0,0,0,'Whoa...',12340),
	 (5281,6,0,0,0,0,0,0,0,'Alen has finally found someone brave enough, eh?',12340),
	 (5282,0,0,0,0,0,0,0,0,'<Egan wipes a tear from his eye.>$B$BDid you see my mother, $N? Did you free her?$B$BYou are a shining example of decency. For your troubles...',12340),
	 (5283,25,1,0,0,0,0,0,0,'This be it, $N. After this, there ain''t no way to turn back. It''s not too late to become a toy maker, er, weaponsmith.$B$BI trust ye''ll make the right decision.',12340),
	 (5284,5,1,0,0,0,0,0,0,'About time! I''ve got customers waiting.$B$BGive those here and pay attention. You''re going to take the first step in your career as a weaponsmith.',12340),
	 (5301,25,1,0,0,0,0,0,0,'This is the final step before you begin your new career as an armorsmith, $N. Should you choose to back out, now would be your last chance. Otherwise, prepare yourself for a lifetime of glory.',12340),
	 (5302,25,1,0,0,0,0,0,0,'This is the final step before you begin your new career as a weaponsmith, $N. Should you choose to back out, now would be your last chance. Otherwise, prepare to be consumed by knowledge!',12340),
	 (5305,4,0,0,0,0,0,0,0,'May you bash in many a brain, $N!',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (5306,15,0,0,0,0,0,0,0,'Knowledge is power!',12340),
	 (5307,1,0,0,0,0,0,0,0,'It should be obvious that a sword is always the best choice.',12340),
	 (5321,4,0,0,0,0,0,0,0,'Oh, I am so happy Kerlonian made it! And I''m sure I''ll find him sleeping somewhere around here, won''t I?$b$bThank you for showing him the way, $N.',12340),
	 (5341,0,0,0,0,0,0,0,0,'Excellent work, $R. Now to secure my inheritance...',12340),
	 (5342,11,0,0,0,0,0,0,0,'Wonderful! Now only I hold the power and fortune of house Barov!$B$B<Alexi throws a large bag at you.>$B$BAnd keep the change, you filthy animal.',12340),
	 (5343,0,0,0,0,0,0,0,0,'Excellent work, $R. Now to secure my inheritance...',12340),
	 (5344,11,0,0,0,0,0,0,0,'A glorious day it is! Finally, the pockmark of house Barov eliminated and my fortune secure!$B$BTake this and leave my sight, peasant.',12340),
	 (5361,1,0,0,0,0,0,0,0,'I know not what connection you have with my brother but it would seem he has trust with you, $C.$b$bI am Nataka Longhorn and would like to welcome you to Ghost Walker Post, we have many needs of a $C! Talk with others, perhaps there is need of you here.',12340),
	 (5381,1,0,0,0,0,0,0,0,'Ah, the Demon Box. Give it to me, $C, and I shall open... and thus reveal to you the Hand of Iruxos.$b$b',12340),
	 (5382,1,0,0,0,0,0,0,0,'I can feel my spirit healing, $N. You have done my husband and I a great service, but I am certain there is more to be done.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (5384,1,1,25,0,0,0,0,0,'With the death of Kirtonos, a chapter in the horrible tale of Scholomance comes to a close. There is, however, more to be done. Others here are now aware of your brave acts. Take this, $N. It is a piece of our own essence. It will allow you to communicate with the other lost souls of Caer Darrow.',12340),
	 (5385,2,0,0,0,0,0,0,0,'You''ve done it! Praise be to Elune and whichever powers you worship, $N. You have done an honorable and noble thing this day. I am certain Arko''narin will be pleased that you not only took the time to save her, but to also slay the creature who tortured one of her best friends.$b$bI wish I could do more for you, but please, take this.',12340),
	 (5386,0,0,0,0,0,0,0,0,'You are a savior, $N! These Bloodbelly fish look almost good enough to eat raw.$B$B<Nataka starts salivating.>$B$BHere you go - choose one of these items as a payment for these fish.',12340),
	 (5401,0,0,0,0,0,0,0,0,'All who fight evil on behalf of the Argent Dawn must don our commission.  Wearing such will earn your right to claim rewards our quartermasters have to offer.$B$BWhile under commission, you''ll be able to acquire Scourgestones from slain Scourge; these are marks of insignia that they sometimes possess.  Procure these insignia and bring them to me.  For each set you turn in, you will receive our marker of heroism - the Argent Dawn Valor Token.$B$BAchieve your destiny, $c - join the fight today!',12340),
	 (5402,4,0,0,0,0,0,0,0,'Congratulations, $N - I am pleased to award you with an Argent Dawn valor token!$B$BThe tokens serve two purposes.  One - they can be used to further your standing within the Argent Dawn; to do so may avail you options and rewards that are reserved for our honored and revered allies.  Two - they can be given to our quartermasters, along with coin, as payment for some of the Dawn''s more prized items.$B$BWhatever you decide, know that you are earning your commission.  Well done!',12340),
	 (5403,4,0,0,0,0,0,0,0,'Congratulations, $N - I am pleased to award you with an Argent Dawn valor token!$B$BEach valor token handed out to worthy recipients is a sign of the tide turning against the Scourge. With more and more heroes fighting the Scourge in their own lands, the Argent Dawn will assuredly be at the forefront when the time comes to wage war on the ultimate evil of the Scourge. I hope that the valor you''ve shown what it took to acquiring your token will carry the day then as well!',12340),
	 (5404,4,0,0,0,0,0,0,0,'Congratulations, $N - I am pleased to award you with an Argent Dawn valor token!
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (5408,4,0,0,0,0,0,0,0,'Congratulations, $N - I am pleased to award you with an Argent Dawn valor token!
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (5482,1,0,0,0,0,0,0,0,'Ah, my doom weed. Excellent!$b$b<Junior Apothecary Holland rubs his hands together greedily>$b$bThese will come in quite handy. You''ve done me, uh, the Lady, a fine service today $N. As promised here is the reward that you deserve.',12340),
	 (5501,4,0,0,0,0,0,0,0,'Ah, goodie!  My bones!$B$BI can''t wait till the chaps at home see my face on the front cover of Goblin''preneur.  I''ll be the richest goblin in the world... and my physical education teacher said I would never amount to anything.',12340),
	 (5502,0,0,0,0,0,0,0,0,'May the spirits bless you, $N. You''ve done more for Grunth than most would ever think of doing for him. Thank you - you''re the epitome of what it means to be a hero of the Horde.$B$BPlease - if you can spare the time, come back and visit us. I know that Grunth would like that, as would I.',12340),
	 (5503,0,0,0,0,0,0,0,0,'All who fight evil on behalf of the Argent Dawn must don our commission. Wearing such will earn your right to claim rewards our quartermasters have to offer.$B$BWhile under commission, you''ll be able to acquire Scourgestones from slain Scourge; these are marks of insignia that they sometimes possess. Procure these insignia and bring them to me. For each set you turn in, you will receive our marker of heroism - the Argent Dawn Valor Token.$B$BAchieve your destiny, $C join the fight today!',12340),
	 (5504,0,0,0,0,0,0,0,0,'Outstanding - your tribute to the Dawn is duly noted, $N. With this accomplished, I am delighted to make our mantles available to you for purchase. So long as you maintain your current status with us, these mantles will be purchasable from any authorized quartermaster of the Argent Dawn.$B$BFor the Dawn, my brother!',12340),
	 (5505,1,0,0,0,0,0,0,0,'Well, here you are, $n - the completed Skeleton Key.  I am certain as I can be that this key will allow you within the confines of the Scholomance.  There''s only one way to be absolutely sure it works, though. Waste no time in trying it out, I say.$B$BGood luck, mighty hero.  May your victories continue to bring you fame and power as you lay waste to Scholomance!',12340),
	 (5507,0,0,0,0,0,0,0,0,'Outstanding - your tribute to the Dawn is duly noted, $N. With this accomplished, I am delighted to make our mantles available to you for purchase. So long as you maintain your current status with us, these mantles will be purchasable from any authorized quartermaster of the Argent Dawn.$B$BFor the Dawn, my brother!',12340),
	 (5508,4,0,0,0,0,0,0,0,'Congratulations, $N - I am pleased to award you with an Argent Dawn valor token!
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (5511,1,0,0,0,0,0,0,0,'Well, here you are, $n - the completed Skeleton Key.  I am certain as I can be that this key will allow you within the confines of the Scholomance.  There''s only one way to be absolutely sure it works, though. Waste no time in trying it out, I say.$B$BGood luck, mighty hero.  May your victories continue to bring you fame and power as you lay waste to Scholomance!',12340),
	 (5513,0,0,0,0,0,0,0,0,'Outstanding - your tribute to the Dawn is duly noted, $N. With this accomplished, I am delighted to make our mantles available to you for purchase. So long as you maintain your current status with us, these mantles will be purchasable from any authorized quartermaster of the Argent Dawn.$B$BFor the Dawn, my brother!',12340),
	 (5514,5,0,0,0,0,0,0,0,'Dithers said you''d deliver the goods, and deliver you have! A deal is a deal; let me pack the fragments into the mold for you.$b$bDid Dithers imbue them already? Excellent... otherwise, it would have been a long trip back to the Bulwark for you.',12340),
	 (5515,5,0,0,0,0,0,0,0,'The bag of horrors!',12340),
	 (5517,0,0,0,0,0,0,0,0,'Most impressive, $N - the Chromatic Mantle of the Dawn is now yours!$B$BAs long as you maintain Exalted status with the Argent Dawn, you will be able to purchase additional Chromatic Mantles. They will be made available to you immediately from any of the Dawn''s quartermasters.',12340),
	 (5518,0,0,0,0,0,0,0,0,'Yeah, this will do the trick.  Just a slip here, and tuck here... heh - this is going to work out just fine!  <A broad smile beams from the chained goblin''s face.>$B$BHere you go, you''re all set.  Remember- this isn''t the most securely fashioned item in the world.  You''ll have ten minutes of use before it falls apart, and then you''re not going to fool anybody!  Try using it just before you approach him, and remember... it only will make him think that YOU are an ally - not your group mates!',12340),
	 (5519,0,0,0,0,0,0,0,0,'Here ya go $N - put this thing on, and you''ll have ten minutes to do whatever.  Good luck!$B$BOh, and if you happen to find a key to get me out of here, BY ALL MEANS LET ME KNOW!!!',12340),
	 (5521,0,0,0,0,0,0,0,0,'Most impressive, $N - the Chromatic Mantle of the Dawn is now yours!$B$BAs long as you maintain Exalted status with the Argent Dawn, you will be able to purchase additional Chromatic Mantles. They will be made available to you immediately from any of the Dawn''s quartermasters.',12340),
	 (5522,273,1,1,0,0,0,0,0,'Ah, very good. You do not know the evil power for whom you have labored, but now you will know the truth. And fear not--I am no servant of that master. I am Leonid Barthalomew, known as "the Revered" to my brethren in the Argent Dawn.$b$bI tricked Tinkee into sending you and the dragon eggs to me. And it is good that my trick was successful, for had these eggs reached their intended destination, a great power would have fallen into the hands of the enemy.',12340),
	 (5524,0,0,0,0,0,0,0,0,'Most impressive, $N - the Chromatic Mantle of the Dawn is now yours!$B$BAs long as you maintain Exalted status with the Argent Dawn, you will be able to purchase additional Chromatic Mantles. They will be made available to you immediately from any of the Dawn''s quartermasters.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (5525,0,0,0,0,0,0,0,0,'You - ranked number one. Everyone else - ranked number two or lower. Oh, thank you for freeing me!$B$BI knew my life was destined for more than just being an appetizer to some ogre!',12340),
	 (5526,0,0,0,0,0,0,0,0,'It is done, brave $C, and with that the Cenarion Circle is in your debt. Though the war is far from over, a great battle has been won against those who would bring about our doom.$b$bPlease - accept this as a token of our enduring gratitude. Know that you are welcomed here as a hero of the Cenarion Circle for your great deed, $N. Thank you.',12340),
	 (5527,0,0,0,0,0,0,0,0,'Indeed, you are as resourceful as many claim. The Cenarion Circle is blessed to have you working in our stead.$b$bWith the Reliquary once more in our hands, my mind is at ease. I feel more comfortable asking you to not only face down a malfeasant demon, but also to bring back a dangerous item in the process...',12340),
	 (5528,0,0,0,0,0,0,0,0,'You da big boss now, so you get free sample of my better brews!  These drinks boost you up AND give you good buzz!  These are da good ones, chief... you try and tell Kreeg yourself!',12340),
	 (5529,4,0,0,0,0,0,0,0,'Well done, $N!  It''ll be a long time before they can grow another clutch of dragons.$B$B...At least, I hope it will!',12340),
	 (5531,4,1,1,6,0,0,0,0,'There they are! And in such a nice container. The perfect size!$b$bWe''ll keep these eggs in a safe place so we can study them later, but right now we need that thing you brought them in.$b$bI have created a device with a very specific use: to destroy the undead scholars of the Scholomance. They are studying dragons in their efforts to create a plagued dragonflight, and we must halt their progress.$b$bI call the device Dawn''s Gambit, because... I''m not sure if it works!$b$bWill you find out for us?',12340),
	 (5533,1,0,0,0,0,0,0,0,'Well met, $c.  I''ve dedicated a fair portion of my recent studies to the Scholomance, and I believe I know a means by which you can acquire a key... one that will let you past the front door.$B$BI can only imagine what horrid sights are to be seen inside, $N.  I don''t know how you heroic types do it sometimes...',12340),
	 (5534,0,0,0,0,0,0,0,0,'Haha! Wonderful!$b$bI''ll be sure to find out what this is for and why Magus Rimtori--she''s the cow that hired me--wanted it. Hah! I got you now, stinkin'' Blood elves! Kim''jael! Ha! I''ll teach them who the rats are!$b$bYa did good, $N. Thanks a bundle. Here, take this coin and be off with ya--I''ve got some things to figure out.',12340),
	 (5535,0,0,0,0,0,0,0,0,'Well done, $C. Thank you for your help. The spirits are at peace, and the threats that their desire for the arcane draw have been lessened.$b$bI am sure that both sides of the conflict that ravishes Azeroth will see you are above such things.',12340),
	 (5536,0,0,0,0,0,0,0,0,'Well done, $C. I see you''re not only skilled but cunning. To defeat such creatures is a testament to your loyalty to the tenants of the Earthmother, even if you do not recognize her as your own deity. She is in all things on this planet and beyond. Her eyes, one dark and one light, travel across the skies always gazing down upon us.$b$bPlease, take this small amount of coin in appreciation for what you have done.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (5537,1,0,0,0,0,0,0,0,'This''ll work, $N!  My turn now - I will imbue these with a suitable temper that will allow them to survive the intense forging process they will eventually go through.$B$BThe next step will be to get an appropriate mold for the key.  I know a goblin blacksmith in Tanaris that has in the past made molds for similarly macabre items.  He works for whom goblins usually work for - the highest bidder.',12340),
	 (5538,5,0,0,0,0,0,0,0,'Arbington said you''d deliver the goods, and deliver you have! A deal is a deal; let me pack the fragments into the mold for you.$b$bDid Arbington imbue them already? Excellent... otherwise, it would have been a long trip back to the Chillwind Camp for you.',12340),
	 (5541,4,2,0,0,0,0,0,0,'Great, more ammo! Old Loslor''s shipment finally came through! The ammo might be late, but just like my grand daddy used to tell me: late''s better than never!$b$bThank you much, $N. I already have buyers eager for this stuff!',12340),
	 (5542,1,5,0,0,0,0,0,0,'Well done, $N. Come. Rest. Let us eat and talk of days long past!',12340),
	 (5543,1,1,5,0,0,0,0,0,'You are a shining example of decency, $r! It has been long since I have felt the blood of heroes pump through my veins. Your acts of bravery are uplifting!',12340),
	 (5544,5,1,0,0,0,0,0,0,'May the Light watch over you! Bless you, young one.',12340),
	 (5545,1,0,0,0,0,0,0,0,'Excellent! Thanks to you, I should be able to complete the order in time. To show my gratitude, I would like to offer some coin as compensation for your troubles.$b$bThank you and farewell.',12340),
	 (5561,0,0,0,0,0,0,0,0,'<Smeed Scrabblescrew begins counting.>$b$bThree, four, and five... excellent, I ask for five tamed kodos and I get five tamed kodos... I am going to be rich... yes, very rich! I hope to see the look on Bibbly''s green face when he hears about my success!',12340),
	 (5581,2,0,0,0,0,0,0,0,'You are to be commended, $N. Your effort has helped greatly in fighting the demon threat, and all of Azeroth is safer because of it.',12340),
	 (5582,0,0,0,0,0,0,0,0,'Excellent! This will be invaluable in my continued studies of the machinations of the Scourge. Thank you, $N, and if you find more of these scales please bring them to me!',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (5601,0,0,0,0,0,0,0,0,'Where is my sister Jessica? She left so long ago, when I was just a little girl. She cried so much when she went away. I don''t know why she cried! Maybe she fell and hit her toe.$b$bWhen Jessica was here we used to play games and dance and pick pretty flowers around the house. And sometimes we''d hide when we saw daddy coming home, then jump out and surprise him!$b$bCome back, Jessica! If you come back then maybe daddy will too and we can all play together again...',12340),
	 (5621,0,0,0,0,0,0,0,0,'You have done well and you have served Elune. For that, I thank you.$B$BPlease, take this robe as a token of my thanks. It signifies you have earned your place among our order. If you wish, wear it with pride, but either way, we will always recognize you as one of our own.$B$BGo with Elune, $N, and thank you.',12340),
	 (5622,0,0,0,0,0,0,0,0,'I''m happy to see Shanda has sent you to find me, $N. Teaching young priests the ways of Elune gives me great satisfaction.',12340),
	 (5623,1,0,0,0,0,0,0,0,'I''m glad you''ve arrived, $N. We have much to discuss about your future and your path within the Light.',12340),
	 (5624,1,0,0,0,0,0,0,0,'Excellent, $N With one more healthy guard out there to help the town, we''ll be that much safer. I''m glad to see you''re already learning to use your abilities wisely. If you feel you are ready for more training at any time, please come back to me. But for now, take this robe. It will let others know that you are one of our order. If you don''t want to wear it, that''s fine. Later there will be more tests and this robe isn''t necessary for those.',12340),
	 (5625,2,1,1,0,0,0,0,0,'Well done, $n. You got the Light inside you, that''s for sure.$B$BHere, take this robe. It''ll denote your role in the church and help people recognize you as a $c--wear it if you want.$B$BLater, there will be more tests that you''ll have to go through. Do what you can to learn about your abilities and what you''re capable of. Try your hand at a fight or two alone, and then again with other travelers.$B$BBut don''t fret none... you''re as powerful as they come.',12340),
	 (5626,6,1,0,0,0,0,0,0,'Oh, so Branstock sent ya, did he? Good, good! He''s right, it is ''bout time you started taking a much larger step into the Light. It''ll build character and make ya stronger... an'' that''s what you''ll need more than anything: strength of body... strength of will.',12340),
	 (5627,0,0,0,0,0,0,0,0,'You''ve proven yourself worthy of Elune''s attention, $N. If you feel you''re ready, I would very much like to teach you one of her spells unique to our people.',12340),
	 (5628,0,0,0,0,0,0,0,0,'Wonderful, you''ve returned home, $N. It always pleases Tyrande and myself when those we''ve trained go out into the world and return to us safely. How have things been with you? Does Elune still bless your travels? Perhaps after we speak more about the business at hand, you could tell me more of your travels.',12340),
	 (5629,0,0,0,0,0,0,0,0,'Wonderful, you''ve returned, $N. It always pleases Tyrande and myself when those we''ve trained go out into the world and return to us safely. How have things been with you? Does Elune still bless your travels? Perhaps after we speak more about the business at hand, you could tell me more of your travels.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (5631,0,0,0,0,0,0,0,0,'Wonderful, you''ve returned home, $N. It always pleases Tyrande and myself when those we''ve trained go out into the world and return to us safely. How have things been with you? Does Elune still bless your travels? Perhaps after we speak more about the business at hand, you could tell me more of your travels.',12340),
	 (5634,0,0,0,0,0,0,0,0,'You have done the Light a great service by becoming a shining example to those who travel in these dangerous lands and beyond. Please, accept this lesson as a thanks for all you''ve done.',0),
	 (5635,0,0,0,0,0,0,0,0,'I''m glad you''ve arrived, <name>. There are many things we will have to discuss, but more importantly is your training in the ways of the Light.$B$BThere are lessons all servants of the Light must learn. If you are ready, we''ll begin discussing some of those now.',0),
	 (5636,0,0,0,0,0,0,0,0,'I''m glad you''ve arrived, <name>. There are many things we will have to discuss, but more importantly is your training in the ways of the Light.$B$BThere are lessons all servants of the Light must learn. If you are ready, we''ll begin discussing some of those now.',0),
	 (5637,0,0,0,0,0,0,0,0,'I''m glad you''ve arrived, <name>. There are many things we will have to discuss, but more importantly is your training in the ways of the Light.$B$BThere are lessons all servants of the Light must learn. If you are ready, we''ll begin discussing some of those now.',0),
	 (5638,0,0,0,0,0,0,0,0,'I''m glad you''ve arrived, <name>. There are many things we will have to discuss, but more importantly is your training in the ways of the Light.$B$BThere are lessons all servants of the Light must learn. If you are ready, we''ll begin discussing some of those now.',0),
	 (5639,0,0,0,0,0,0,0,0,'I''m glad you''ve arrived, <name>. There are many things we will have to discuss, but more importantly is your training in the ways of the Light.$B$BThere are lessons all servants of the Light must learn. If you are ready, we''ll begin discussing some of those now.',0),
	 (5640,0,0,0,0,0,0,0,0,'I''m glad you''ve arrived, <name>. There are many things we will have to discuss, but more importantly is your training in the ways of the Light.$B$BThere are lessons all servants of the Light must learn. If you are ready, we''ll begin discussing some of those now.',0),
	 (5641,0,0,0,0,0,0,0,0,'You''ve got the makings of a great $C, $N. Keep up the good work!$B$BYou''ve already shown you''re ready for battle. Perhaps it''s time we taught ya a little somethin'' more.',12340),
	 (5646,0,0,0,0,0,0,0,0,'Good, you''ve returned, and not a moment too late. We have great things to discuss, $N. Your abilities are growing stronger, and we must make sure you are ready.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (5648,0,0,0,0,0,0,0,0,'Good, then Kor''ja lives and goes off to defend our town from those malicious humans. I often wish to remember days of battle; where power was shown in combat and it was the wise who often destroyed those who relied on just their strength.$B$BYou done good by me, $N. You take this robe now. Maybe it help, maybe you not care, but you earned it and I''m proud to call you brother.',12340),
	 (5649,0,0,0,0,0,0,0,0,'Ahh... so you finally come to Tai''jin. This be good.$B$BYou already know that we are not da same tribe that once joined with the Horde. We be much stronger now. We stronger ''cause we adapt--the Horde teach us that much. We no longer defeat our enemies and gain strength from them; now we gain strength, and then defeat our enemies.$B$BThe difference be subtle, but you will learn. You will see. The tribe count on you to learn such things.',12340),
	 (5650,0,0,0,0,0,0,0,0,'You have passed my test with ease. Good.$B$BSoon, you will be ready to take on more responsibility and that road will lead to darker powers--powers that no $C of another race has.$B$BTake this robe as a symbol of your station. You have earned it. If you do not wish to wear it, then so be it, you may do with it as you will. I and others like us will always acknowledge you for what you''ve achieved in our ranks.',12340),
	 (5651,0,0,0,0,0,0,0,0,'Finally, you''ve arrived. Your faith alone will not allow you to pass the trials before you, young one. A sense of urgency and some ambition will help too.',12340),
	 (5652,0,0,0,0,0,0,0,0,'You would do well to pay heed to this lesson, young one. The Hex of Weakness will be a great boon to you in battle. Later I will have tests for you to further yourself and prove your worth to the tribe.',12340),
	 (5658,0,0,0,0,0,0,0,0,'Ah, young $c, I am glad you have returned here. I would teach you a lesson you would do well to not forget. Are you prepared?',12340),
	 (5659,0,0,0,0,0,0,0,0,'Ah, good, another has arrived. Time may not matter to me, but to you it is of the essence. There is much for you to learn and there is much I wish to teach you. You simply must prove your worth. Do that, and you shall be greatly rewarded.',12340),
	 (5660,0,0,0,0,0,0,0,0,'Ah, good, another has arrived. Time may not matter to me, but to you it is of the essence. There is much for you to learn and there is much I wish to teach you. You simply must prove your worth. Do that, and you shall be greatly rewarded.',12340),
	 (5661,0,0,0,0,0,0,0,0,'Ah, good, another has arrived. Time may not matter to me, but to you it is of the essence. There is much for you to learn and there is much I wish to teach you. You simply must prove your worth. Do that, and you shall be greatly rewarded.',12340),
	 (5662,0,0,0,0,0,0,0,0,'Ah, good, another has arrived. Time may not matter to me, but to you it is of the essence. There is much for you to learn and there is much I wish to teach you. You simply must prove your worth. Do that, and you shall be greatly rewarded.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (5663,0,0,0,0,0,0,0,0,'Ah, good, another has arrived. Time may not matter to me, but to you it is of the essence. There is much for you to learn and there is much I wish to teach you. You simply must prove your worth. Do that, and you shall be greatly rewarded.',12340),
	 (5672,0,0,0,0,0,0,0,0,'By devoting yourself to Elune and our people, you have attained a state that not all of us can achieve. It is tradition that you then be taught even greater abilities for your devotion. Do you accept?',12340),
	 (5673,0,0,0,0,0,0,0,0,'Elune bless you for returning so quickly to us. This is an important time in your training, and a time that all of our order take very seriously. When you''ve rested from your journey here, please, let me know. We can then discuss the continuation of your training and where your path will lead you next.',12340),
	 (5676,0,0,0,0,0,0,0,0,'We were forced to learn some magics to protect us from what is commonly called our greatest enemy: the arcane.$B$BI would teach you a spell to help you defend yourself and your companions from those who would wield such power.',12340),
	 (5677,0,0,0,0,0,0,0,0,'Ah, you have wonderful timing, <name>. I was beginning to wonder if all of my messengers had been successful. I''m glad to see they were, otherwise I would wager you''d still be out in the world learning more about all the threats that exist against our people.$B$BAre you ready? Ready for more training I mean. You''re growing in power more quickly, and I feel you are ready to learn more about our faith.',0),
	 (5678,0,0,0,0,0,0,0,0,'Ah, you have wonderful timing, <name>. I was beginning to wonder if all of my messengers had been successful. I''m glad to see they were, otherwise I would wager you''d still be out in the world learning more about all the threats that exist against our people.$B$BAre you ready? Ready for more training I mean. You''re growing in power more quickly, and I feel you are ready to learn more about our faith.',0),
	 (5679,0,0,0,0,0,0,0,0,'I would teach you Devouring Plague if you feel you are prepared, $N. A spell of no small power, it will aid you in your coming battles. Practice with it--there will be tests later.',12340),
	 (5680,0,0,0,0,0,0,0,0,'Your rites will come soon enough. For now, I teach you a spell that will be of great use to you when you do battle with your enemies.',12340),
	 (5713,2,0,0,0,0,0,0,0,'You bring most welcome news $C. It is good to hear that Aynasha is alive and well thanks to you. I would hope that you might accept a reward for your valor. May Elune watch over you and light your path.',12340),
	 (5721,0,0,0,0,0,0,0,0,'The fighting is over!  I heard my daddy whisper to me.  He scared away all the ghosts and he says he''s coming home!  I''m so happy!$B$BHe also said I should welcome you if came to our house, so I made some tea!$B$BI hope you like lots of sugar!',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (5722,0,0,0,0,0,0,0,0,'The body looks seriously beaten by clubs or fists, but most of the corpse''s clothing and equipment still looks present. It seems the troggs do not overly care much for material wealth.$B$BYou begin to search the body for anything of interest that might help Magatha.',12340),
	 (5723,2,1,0,0,0,0,0,0,'I am glad to see you took Magatha''s task seriously. Thank you, $N. I''m sure the troggs will have a harder time coming to the surface with their numbers so greatly reduced.$B$BPerhaps in the future we can take time to figure out where such creatures came from, and what they really want.',12340),
	 (5724,2,1,0,0,0,0,0,0,'Excellent, $N. Thank you.$b$bMagatha told me that if you were successful in finding her clansman that you be given this. Please, take it in thanks.',12340),
	 (5725,0,0,0,0,0,0,0,0,'Good, $C. You have done well in serving the Dark Lady. Your continued perseverance and ambition will be of great use to the Lady''s subjects. Return to me again in the future. Perhaps I will have other tasks for you that will aid the Dark Lady in her attempts at overtaking the Lich King and completely freeing the Scourge.',12340),
	 (5726,15,1,1,0,0,0,0,0,'Good, $N! The spirits be praised, perhaps you are the one who will finally put my greatest fears to rest! Who would suspect someone so young and so brave would rise up and champion our cause? You remind me of myself when I was younger. I will ensure that you are justly rewarded for your efforts if we both survive the coming storm.$b$bBut there is time for more praise later. You''ve not accomplished anything in comparison to what you will face... but this is a good start.',12340),
	 (5727,4,1,0,0,0,0,0,0,'Excellent! Most excellent, $C!$b$bWhat you have done this day is only the first step in a much broader foundation--a foundation that we will build the destruction of the Shadow Council on, once and for all.$b$bTell me all he said... and leave not one word out--it may be more important than you realize.',12340),
	 (5728,4,1,0,0,0,0,0,0,'I am glad you''ve returned, $N. Some of those loyal to me brought word immediately that the caverns below Orgrimmar were in disarray now that their leaders have been slain. I even heard reports that Neeru was more than agitated. It seems we''ve put a dent in his armor. I can''t say I''m displeased... even with such a minor victory.',12340),
	 (5729,5,2,0,0,0,0,0,0,'What is it?! Oh, you, $c... my apologies. My anger rivals that of a rabid kodo bull... but perhaps it is my own fault. In sending travelers into Ragefire Chasm, I should have seen the possibility that some harm would come from it. It seems both Bazzalan and Jergosh were taken unaware and slain by some of Thrall''s do-gooders. A most inopportune time, but there is nothing that can be done about it now.',12340),
	 (5730,1,1,4,0,0,0,0,0,'Ashenvale? Hmm, I had not heard of any presence of the Council or the Burning Blade in Ashenvale. My spies will investigate, $N. You have done well.$b$bFor now, rest, and keep yourself occupied with other tasks. I will call upon you again soon.$b$bLok-Tar Ogar!',12340),
	 (5741,1,0,0,0,0,0,0,0,'The elusive Sceptre of Light! Your acquisition of it has removed a grave threat to the world. Well done, $C, well done.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (5742,6,0,0,0,0,0,0,0,'The Fordring redemption will be a difficult task. Are you prepared?',12340),
	 (5761,4,1,0,0,0,0,0,0,'Ha! You''ve done it! Thrall will be so pleased.$b$bI will ensure this heart is taken care of properly.$b$bFor now though, you must celebrate your victory. I will inform Thrall of your success.$b$bThank you for your aid, $C.',12340),
	 (5762,2,1,0,0,0,0,0,0,'Great, my package from Koalbeard! Thank you $N. This crate holds special-gauge ammunition, and it''ll serve us well out in the jungle!$b$bHere''s your pay, and tell me, how is crusty old Kravel these days? Still up to no good I''d wager...',12340),
	 (5763,1,0,0,0,0,0,0,0,'Ah, this horn belongs to a Tauren, Roon Wildmane. My father spoke often of the good times they had together hunting the beasts of Desolace. So Roon is inviting me to join him, is he?$B$BWe''re neck deep in the jungle right now, but thank you, $N. Perhaps my next expedition will take me to Desolace, the land of the centaurs.',12340),
	 (5781,1,1,0,0,0,0,0,0,'<Tirion blinks to hold back tears.>$B$BIt was destiny that we meet, $N. You have blessed me with your kindness.
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (5821,0,0,0,0,0,0,0,0,'You know, it doesn''t seem prosperous to be paying the likes of you to guard Gizelton Caravan. $C, if I were a bit taller I could take on a second job and sit kodo-side-saddle with the biggest gun my hands could carry... and I''d show them blasted centaur who''s their papa.',12340),
	 (5841,0,0,0,0,0,0,0,0,'You are indeed a special hero, $N. We welcome you to the world of Azeroth, and offer you one of these unique gifts!',12340),
	 (5842,0,0,0,0,0,0,0,0,'You are indeed a special hero, $N. We welcome you to the world of Azeroth, and offer you one of these unique gifts!',12340),
	 (5843,0,0,0,0,0,0,0,0,'You are indeed a special hero, $N. We welcome you to the world of Azeroth, and offer you one of these unique gifts!',12340),
	 (5844,0,0,0,0,0,0,0,0,'You are indeed a special hero, $N. We welcome you to the world of Azeroth, and offer you one of these unique gifts!',12340),
	 (5845,1,1,1,0,0,0,0,0,'It is as glorious now - even in its tattered state - as the day I looked upon it and took my oath of allegiance.$B$BHis redemption comes and perhaps mine with it...',12340),
	 (5846,1,1,1,1,0,0,0,0,'How could I forget? Many of the spirits on this island are cursed to relive their last happy memory before they met their tragic end.$B$BI too am cursed, but not as they - I am one of the few that remembers all...$B$BPerhaps this thing that you ask me is why I haunt these ruins. Perhaps this thing I tell you shall set me free.',12340),
	 (5847,0,0,0,0,0,0,0,0,'You are indeed a special hero, $N. We welcome you to the world of Azeroth, and offer you one of these unique gifts!',12340),
	 (5848,0,0,0,0,0,0,0,0,'<Tirion nearly collapses when he sees the painting.>$b$b<He begins to sob in an almost frenetic manner.>',12340),
	 (5861,1,1,6,0,0,0,0,0,'I was Tirion''s most trusted advisor when he held rank as Lord of Mardenholde. I openly dissented the verdict passed by the Order of the Silver Hand and was banished for my insolence.$b$bHe has been through much heart ache and disappointment in his life, $R. Are you prepared to right the wrongs set upon the Fordrings?',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (5862,6,1,16,0,0,1000,0,0,'What is this, soldier?$b$b<Taelan opens the box and begins to examine its contents.>$b$bThis... this cannot be true. But all that you have shown me...$b$b<Taelan falls to one knee, his heartbeat quickens. The fury of ages is about to be loosed upon this town.>',12340),
	 (5863,1,4,4,0,0,0,0,0,'I''m so glad you were able to do this for me, $N! Thanks for your help!',12340),
	 (5881,0,0,0,0,0,0,0,0,'This is great news; I have been sitting here guarding this hunk of wood for too long. Now I can spend some time with my family... Yippee!',12340),
	 (5882,1,0,0,0,0,0,0,0,'Very well then, here are your Cenarion plant salves. Scour Felwood for corrupted plants, $n! Wherever they are, use the salve I have given you to purify them.',12340),
	 (5883,0,0,0,0,0,0,0,0,'Very well then, here''s some Cenarion plant salve. If you find more vitriol when you mine in Felwood, remember to hold on to it for me! The more of it you find, the more salve I will be able to make.',12340),
	 (5884,0,0,0,0,0,0,0,0,'Excellent work $n - every bit of this, once we purify it, will help us take back Felwood. Here, take some doses of Cenarion plant salve and head into the forest. The reclaiming of the land from the corruption waits for no $r!',12340),
	 (5885,0,0,0,0,0,0,0,0,'This is exactly what I need. Here - take these plant salves and use them to reclaim Felwood from the corruption. We must persevere, $n!',12340),
	 (5886,0,0,0,0,0,0,0,0,'Here are some Cenarion plant salves - I only need one lesser nether essence for this, $n. Essence is by far the most potent item I can make use of to turn swords into plowshares, as it were. If you need more salve, then find me here!',12340),
	 (5887,1,0,0,0,0,0,0,0,'Very well then, here are your Cenarion plant salves. Scour Felwood for corrupted plants, $n! Wherever they are, use the salve I have given you to purify them.',12340),
	 (5888,0,0,0,0,0,0,0,0,'Very well then, here''s some Cenarion plant salve. If you find more vitriol when you mine in Felwood, remember to hold on to it for me! The more of it you find, the more salve I will be able to make.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (5889,0,0,0,0,0,0,0,0,'Excellent work $n - every bit of this, once we purify it, will help us take back Felwood. Here, take some doses of Cenarion plant salve and head into the forest. The reclaiming of the land from the corruption waits for no $r!',12340),
	 (5890,0,0,0,0,0,0,0,0,'This is exactly what I need. Here - take these plant salves and use them to reclaim Felwood from the corruption. We must persevere, $n!',12340),
	 (5891,0,0,0,0,0,0,0,0,'Here are some Cenarion plant salves - I only need one lesser nether essence for this, $n. Essence is by far the most potent item I can make use of to turn swords into plowshares, as it were. If you need more salve, then find me here!',12340),
	 (5892,0,0,0,0,0,0,0,0,'Well done! I''ll put these supplies to good use! Thanks, $N!',12340),
	 (5893,0,0,0,0,0,0,0,0,'Ah, you got them. Good work, $N! These supplies are a little musty from sitting in that dark mine for so long, but we''ll make use of them nonetheless.$B$BThank you, $N. Your deeds are vital to the maintenance of our fighting forces.',12340),
	 (5901,1,0,0,0,0,0,0,0,'These will do nicely, $N. Thank you.$B$BIf you''re ready, we can get on with the next step.',12340),
	 (5902,0,0,0,0,0,0,0,0,'The termites are obviously getting restless as you place the barrel on top of the crate.',12340),
	 (5903,1,6,0,0,0,0,0,0,'These will do nicely, $N. Thank you. Just look at them... so many of them all huddled up. I almost feel bad for the Crusade, but then again, it was never their mill to take, now, was it?',12340),
	 (5904,0,0,0,0,0,0,0,0,'The termites are obviously getting restless as you place the barrel on top of the crate.',12340),
	 (5921,0,0,0,0,0,0,0,0,'"And so it begins. Father Cenarius. And so it begins."$B$BDendrite makes a quick, invisible gesture in the air above him. A slight aura of power falls over him.$B$B"The first perspective of nature you must adapt to is that of the bear. I will put you on the path to understanding this aspect of druidic life, but it is you that must embrace it and propagate it - now and forever!"',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (5922,0,0,0,0,0,0,0,0,'"And so it begins. Father Cenarius. And so it begins."$B$BDendrite makes a quick, invisible gesture in the air above him. A slight aura of power falls over him.$B$B"The first perspective of nature you must adapt to is that of the bear. I will put you on the path to understanding this aspect of druidic life, but it is you that must embrace it and propagate it - now and forever!"',12340),
	 (5923,0,0,0,0,0,0,0,0,'I am glad you found your way here today. young $C. The time has come for you to take a large step into a much larger world.$B$BInside each of Cenarius'' children is the call to serve nature. Animals and plants are our friends as well as our charges. We choose to devote our lives as preservers of balance for their sakes as well as our own. Your first step into this world will be to learn of the ways of the bear, and to learn strength of body and heart.$B$BReady yourself!',12340),
	 (5924,0,0,0,0,0,0,0,0,'I am glad you found your way here today. young $C. The time has come for you to take a large step into a much larger world.$B$BInside each of Cenarius'' children is the call to serve nature. Animals and plants are our friends as well as our charges. We choose to devote our lives as preservers of balance for their sakes as well as our own. Your first step into this world will be to learn of the ways of the bear, and to learn strength of body and heart.$B$BReady yourself!',12340),
	 (5925,0,0,0,0,0,0,0,0,'I am glad you found your way here today. young $C. The time has come for you to take a large step into a much larger world.$B$BInside each of Cenarius'' children is the call to serve nature. Animals and plants are our friends as well as our charges. We choose to devote our lives as preservers of balance for their sakes as well as our own. Your first step into this world will be to learn of the ways of the bear, and to learn strength of body and heart.$B$BReady yourself!',12340),
	 (5926,0,0,0,0,0,0,0,0,'I am glad you found your way here today. young $C. The time has come for you to take a large step into a much larger world.$B$BInside each of Cenarius'' children is the call to serve nature. Animals and plants are our friends as well as our charges. We choose to devote our lives as preservers of balance for their sakes as well as our own. Your first step into this world will be to learn of the ways of the bear, and to learn strength of body and heart.$B$BReady yourself!',12340),
	 (5927,0,0,0,0,0,0,0,0,'I am glad you found your way here today. young $C. The time has come for you to take a large step into a much larger world.$B$BInside each of Cenarius'' children is the call to serve nature. Animals and plants are our friends as well as our charges. We choose to devote our lives as preservers of balance for their sakes as well as our own. Your first step into this world will be to learn of the ways of the bear, and to learn strength of body and heart.$B$BReady yourself!',12340),
	 (5928,0,0,0,0,0,0,0,0,'I am glad you found your way here today. young $C. The time has come for you to take a large step into a much larger world.$B$BInside each of Cenarius'' children is the call to serve nature. Animals and plants are our friends as well as our charges. We choose to devote our lives as preservers of balance for their sakes as well as our own. Your first step into this world will be to learn of the ways of the bear, and to learn strength of body and heart.$B$BReady yourself!',12340),
	 (5929,0,0,0,0,0,0,0,0,'Dendrite makes another invisible gesture in the air above him as you approach. Another aura of power comes over him. and he smiles ever so slightly.$B$B"I sense wisdom in you, young one, that was not present when we first met. You gaze upon me with strength and knowing intent, though this intent is yet not focused. You will now learn to focus your strength and adopt the nature of the bear into your work."',12340),
	 (5930,0,0,0,0,0,0,0,0,'Dendrite makes another invisible gesture in the air above him as you approach. Another aura of power comes over him. and he smiles ever so slightly.$B$B"I sense wisdom in you, young one, that was not present when we first met. You gaze upon me with strength and knowing intent, though this intent is yet not focused. You will now learn to focus your strength and adopt the nature of the bear into your work."',12340),
	 (5931,0,0,0,0,0,0,0,0,'Welcome back, $N. I sense that your first meeting with the Great Bear Spirit is the same as it is with all druids when they first start down the path of the Claw... a little bewildering, but very intense. I know it was that way with me.$B$BThe Great Bear Spirit has been a part of Azeroth as long as Azeroth has existed in the heavens. We have come to rely on its wisdom and its power to fuel our purpose. Now, the time has now come for your first test of this purpose. Listen closely...',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (5932,0,0,0,0,0,0,0,0,'Welcome back, $N. I sense that your first meeting with the Great Bear Spirit is the same as it is with all druids when they first start down the path of the Claw... a little bewildering, but very intense. I know it was that way with me.$B$BThe Great Bear Spirit has been a part of Azeroth as long as Azeroth has existed in the heavens. We tauren listen closely to such spirits, and we all prosper from its purpose. Now, the time has now come for your first test of this purpose. Listen closely...',12340),
	 (5941,1,0,0,0,0,0,0,0,'Ah yes, there they are.  Together they weave a powerful spell, one that will raise the spirits of Darrowshire.$B$BWith that spell, and with a little luck, we can save Joseph Redpath!',12340),
	 (5942,0,0,0,0,0,0,0,0,'The key fits the lock, and the chest opens...',12340),
	 (5943,0,0,0,0,0,0,0,0,'Not sure it''s a prosperous proposition to be paying so much money to protect the Gizelton Caravan. Cork and Rigger only make one gold piece a week, but as long as they keep paying for my kodos I can care less how they run their business.',12340),
	 (5944,1,1,1,1,0,0,0,0,'The death of my son at the hands of these monsters will not pass without incident. Take solace in knowing that the Order is reborn.$b$bI now take my place as Highlord of the new Order of the Silver Hand.$b$bThese possessions of my past - they are all that I have to offer for all that you have done. Please, take these as a symbol of my gratitude; all have served me well over the years.$b$bMay we meet again, in better times, and reminisce of days long past... battles hard fought... dreams redeemed.',12340),
	 (5961,6,1,0,0,0,0,0,0,'Surely the Dark Lady does not believe you worthy to meet her champion. You are here to feed my hounds, yes? There could be no other reason for this interruption.',12340),
	 (5981,21,0,0,0,0,0,0,0,'Excellent, $N. Your determination has been duly noted.',12340),
	 (6001,0,0,0,0,0,0,0,0,'You have finally taken your large step into a much larger world, $N. I sense the teaching of the Great Bear Spirit within you, and I sense that you have received the strength that Lunaclaw possessed.$B$BThere are no further obstacles in your way... let me now teach you what it means to be a $C of the Claw!',12340),
	 (6002,0,0,0,0,0,0,0,0,'You have finally taken your large step into a much larger world, $N. I sense the teaching of the Great Bear Spirit within you, and I sense that you have received the strength that Lunaclaw possessed.$B$BThere are no further obstacles in your way... let me now teach you what it means to be a $C of the Claw!',12340),
	 (6004,2,1,0,0,0,0,0,0,'Well done, $N. I''m amazed you dealt with them so quickly. Thank you.$B$BI have yet to meet anyone that approves of the Scarlet Crusade and their methods. I believe in the Light as much as anyone else in Stormwind, but they''ve demonstrated that they only want to kill anyone not loyal to their movement... even innocents.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (6021,4,0,0,0,0,0,0,0,'Great, you got him!  And I hope you taught his gang a lesson too!',12340),
	 (6022,274,1,0,0,0,0,0,0,'Disappointing. I was hoping that I''d be feeding you to my hounds, instead.$b$b<Nathanos sighs.>$b$bWell, at least you they''ll have something to eat.',12340),
	 (6023,1,1,0,0,0,0,0,0,'Thank you, $N. You''ve been more help than I could have hoped for. The air here just seems to suck my will. I feel tired, and I can tell I''m not getting any better the longer I''m here.$B$BI''m not really sure how I''m going to infiltrate Hearthglen itself and report on how strong the Scarlet Crusade''s presence is.$B$BBut that''s another matter, before you leave, here, take this... as payment for your help. Thank you again.',12340),
	 (6024,0,0,0,0,0,0,0,0,'Hameya''s chest is opened!!',12340),
	 (6025,1,1,0,0,0,0,0,0,'You''ve done it, $N! Thank you!$B$BI''ll return to Elling... I mean Stormwind as soon as I can. Here, take this coin, it''s the least I can do for you. You''re a credit to your people, $N. Thank you and good luck.',12340),
	 (6026,1,1,0,0,0,0,0,0,'I can pay you half up front and half when the job is done. ',12340),
	 (6027,5,1,0,0,0,0,0,0,'The long lost Book of the Ancients! I will ensure this book is passed on to the high council. You''ve done well today, and for that you are to be thanked... as a hero should be thanked!',12340),
	 (6028,1,0,0,0,0,0,0,0,'Very resourceful, Gregor is. He''s been dealing with the Steamwheedle Cartel for some time now, and has become an expert on the "art" of goblin negotiations. Though it''s true that the goblins'' primary loyalties lie with those who have the largest coin purses, they also know and respect the value of diplomacy. If anything, it provides them with repeat customers...$B$BAt any rate, the Argent Dawn acknowledges you for your effort. Please have this, with our thanks.',12340),
	 (6029,1,0,0,0,0,0,0,0,'Resourceful for a human, Gregor is.  He''s been dealing with the Steamwheedle Cartel for some time now, and has become an expert on the "art" of goblin negotiations.  Though it''s true that the goblins'' primary loyalties lie with those who have the largest coin purses, they also know and respect the value of diplomacy.  If anything, it provides them with repeat customers...$B$BAt any rate, the Argent Dawn acknowledges you for your effort.  Please have this, with our thanks.',12340),
	 (6030,1,0,0,0,0,0,0,0,'This... this is a very special book you have brought me. I''d like to tell you that "special" in this case means "unique and quite possibly illuminating", but that remains to be seen.$b$b"Ooooooo?" Who in their right mind thinks this up?$b$bWell now, I''ve heard of this Umbranse that Gregor spoke of, so this isn''t without merit. I''ll do my best to decipher it. As for you... please, have this - courtesy of the Argent Dawn. While you are here, perhaps there are some other things you can aid us with.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (6031,0,0,0,0,0,0,0,0,'Ah, you brought the cloth.  Such fine material it is!$B$BThank you, $N.  You are a true friend.  Please accept this in exchange.',12340),
	 (6032,0,0,0,0,0,0,0,0,'Ah, very good. This mooncloth will be used for garments sacred to our people. Thank you, $N. Now I will train you.',12340),
	 (6041,1,11,0,0,0,0,0,0,'You''re much darker than I remember. You got that look going for you; the look that says, ''I''ve been charred by a high explosive bomb.''$B$B<Smokey laughs.>$B$BAnyhow! Here''s your cut of the loot. I''ve thrown in a little something extra to help soothe the burns.',12340),
	 (6042,1,0,0,0,0,0,0,0,'It''s incredible what a little anger and rage can get accomplished.',12340),
	 (6061,21,0,0,0,0,0,0,0,'Signs have appeared to me from the Earthmother; you have done well.',12340),
	 (6062,273,0,0,0,0,0,0,0,'You have done well, $N. I believe you are ready for your next task.',12340),
	 (6063,0,0,0,0,0,0,0,0,'Excellent, $N! You are quite a fast learner.',12340),
	 (6064,273,0,0,0,0,0,0,0,'I know, I know; you''re wondering what''s next, aren''t ya?!',12340),
	 (6065,0,0,0,0,0,0,0,0,'Yes, I do believe you are ready...',12340),
	 (6066,0,0,0,0,0,0,0,0,'Yes, I do believe you are ready...',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (6067,0,0,0,0,0,0,0,0,'Yes, I do believe you are ready...',12340),
	 (6068,0,0,0,0,0,0,0,0,'Yes, it is time for you to begin your training.',12340),
	 (6069,0,0,0,0,0,0,0,0,'Yes, it is time for you to begin your training.',12340),
	 (6070,0,0,0,0,0,0,0,0,'Yes, it is time for you to begin your training.',12340),
	 (6071,0,0,0,0,0,0,0,0,'Yes, it is time, $c.',12340),
	 (6072,0,0,0,0,0,0,0,0,'Yes, it is time, $c.',12340),
	 (6073,0,0,0,0,0,0,0,0,'Yes, it is time, $c.',12340),
	 (6074,0,0,0,0,0,0,0,0,'Yes, I do believe you are ready, as well....',12340),
	 (6075,0,0,0,0,0,0,0,0,'Yes, I do believe you are ready, as well....',12340),
	 (6076,0,0,0,0,0,0,0,0,'Yes, I do believe you are ready, as well....',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (6081,1,0,0,0,0,0,0,0,'A young $C, I see. Yes, I will grant you the skills you need to train and guide your pet. Not only will you be able to teach your pet new abilities, you will now be able to feed your pet, as well as revive it, should it fall in battle.$B$BNow, go, $C. We will speak again, at a later date.',12340),
	 (6082,273,0,0,0,0,0,0,0,'You have learned all I can teach you, $N. It is time for you to take what you have learned here and choose a pet of your own.$B$BHere you are, $N. I will now give you the power to tame a beast, as well as call it and dismiss it as you see fit. Use your new skills with pride; you have earned them.',12340),
	 (6083,273,0,0,0,0,0,0,0,'You are a swift learner, $N. You have done well.',12340),
	 (6084,25,0,0,0,0,0,0,0,'When I feel you''ve learned enough, I will grant you the ability to choose any pet of your liking.',12340),
	 (6085,1,0,0,0,0,0,0,0,'Here you are, $N. I will now give ya the power to tame a beast, as well as call it and dismiss it as you please.$B$BFind yerself a good, loyal pet, and enjoy the hunt!',12340),
	 (6086,6,1,1,0,0,0,0,0,'A new recruit, eh? You''re on your way to becoming a great $C, I see.$B$BYes, I can bestow you with the skills you need to train and guide your pet. Not only will you be able to teach your pet new abilities, you will now be able to feed your pet, as well as revive it, should it fall in battle.$B$BRemember that the key to getting the most from your new pet is to respect it and treat it well. In turn, your pet will be your most loyal friend.',12340),
	 (6087,273,0,0,0,0,0,0,0,'Yes... The Earthmother believes that you are ready for the next lesson.',12340),
	 (6088,2,0,0,0,0,0,0,0,'You have learned all I can teach you, $N. May the blessings of the Earthmother guide you in choosing a pet.$B$BHere you are, $N. I will now give you the power to tame a beast, as well as call it and dismiss it as you see fit. Use your new skills with pride and honor the Earthmother.',12340),
	 (6089,1,0,0,0,0,0,0,0,'A young $c, I see. Yes, I can bestow you with the skills you need to train and guide your pet. Not only will you be able to teach your pet new abilities, you will now be able to feed your pet, as well as revive it, should it fall in battle.$B$BNow, go forth. May the Earthmother guide you on your path. We shall speak again, at a later date.',12340),
	 (6101,0,0,0,0,0,0,0,0,'I see your commitment and that you have understood what I have taught you, $N.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (6102,0,0,0,0,0,0,0,0,'You have learned all I can teach you, $N. May I offer you one more piece of advice: use discretion when choosing your first pet. Will you choose a creature of the land, of the water, or of the sky? Whatever it may be, without doubt, your pet will be with you for quite some time.$B$BHere you are, $N. I will now give you the power to tame a beast, as well as call it and dismiss it as you see fit. Use your new skills with pride; you have earned them.',12340),
	 (6103,0,0,0,0,0,0,0,0,'A fledgling $C. I see. Yes. I can bestow you with the skills you need to train and guide your pet. Not only will you be able to teach your pet new abilities, you will now be able to feed your pet, as well as revive it, should it fall in battle.$B$BRemember, $N, always respect the balance and live in awe of nature around you. Now, go forth. We shall speak again, at a later date.',12340),
	 (6121,0,0,0,0,0,0,0,0,'Greetings young $C, I''m glad to see you ready and eager to learn about the curing of poisons.$B$BWhile most druids in the past were put through pre-planned trials, your work will involve no such thing. There has been a rash of animal poisonings at the Crossroads in the Barrens, and they''re unable to bring it under control. Someone there has requested Moonglade for aid, so we are sending you there to aid them. This is no exercise - the work you''ll do is quite real. Bear this in mind.',12340),
	 (6122,0,0,0,0,0,0,0,0,'By Elune, this water is disgusting! No wonder the deer are sick.$B$BSomething is polluting the water, and in turn corrupting Darkshore''s entire water table. Sick deer have been seen all over area, and not just by the river. While this water is most likely a primary source of the sickness spreading, there''s something else at work here.$B$BThis water, believe it or not, will help us formulate a cure. While I research this water, I have need of some items to formulate a cure...',12340),
	 (6123,0,0,0,0,0,0,0,0,'This is good, $N, so much so that it should be enough to make some ample doses of the salve - at least enough to start to make a difference.$B$BMaking a cure for poisons can be quite difficult at times because each one often requires a very specific antidote to counteract it. Imagine being able to cure a poison at will without having to worry about the exact ingredients of what the antidote must be!$B$BNow, let me get to work on this!',12340),
	 (6124,0,0,0,0,0,0,0,0,'You have done well in tending to the sickly deer of Darkshore; they are unwitting victims of a greater taint and corruption that is spreading all throughout the land.  There are those in Darnassus who choose to recognize this threat... and there are those who ignore the growing signs.  I hope you will not be one to put blinders on about what facts stare you in the face, $N.$B$BRegardless, you''ve proven your worth as a friend of nature and the Circle - take this as a symbol of such.',12340),
	 (6125,0,0,0,0,0,0,0,0,'Welcome back - I''ve been following your progress on this lesson since you left, and I must admit I was surprised to learn about the situation in Auberdine.  This does bear some further investigation, as the introduction of such poisons into the environment is most upsetting to the balance.$B$BYou handled yourself with grace under pressure.  For that, I can find no better way to reward you than with permanent power over poison.  Use it well, $N... use it well.',12340),
	 (6126,0,0,0,0,0,0,0,0,'Greetings young druid, I''m glad to see you ready and eager to learn about the curing of poisons.$B$BWhile most druids in the past were put through pre-planned trials, your work will involve no such thing. There has been a rash of animal poisonings at the Crossroads in the Barrens, and they''re unable to bring it under control. Someone there has requested Moonglade for aid, so we are sending you there to aid them. This is no exercise - the work you''ll do is quite real. Bear this in mind.',12340),
	 (6127,0,0,0,0,0,0,0,0,'By my ancestors, this water is disgusting! No wonder the gazelles are sick.$B$BSomething is polluting the water, and in turn beginning to wreck the northern Barrens ecosystem. Sick gazelles have been sighted all north of the east-west road here. While this water is most likely a primary source of the sickness spreading, there''s something else at work here.$B$BThis water, believe it or not, will help us formulate a cure. While I research this water, I have need of some items to formulate a cure...',12340),
	 (6128,0,0,0,0,0,0,0,0,'This is good, $N, so much so that it should be enough to make some ample doses of the salve - at least enough to start to make a difference.$B$BMaking a cure for poisons can be quite difficult at times because each one often requires a very specific antidote to counteract it. Imagine being able to cure a poison at will without having to worry about the exact ingredients of what the antidote must be!$B$BNow, let me get to work on this!',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (6129,0,0,0,0,0,0,0,0,'You have done well in tending to the sickly gazelles of the Barrens; they are unwitting victims of a greater taint and corruption that is spreading all throughout the land. You $R are most eager to understand the ways of Cenarius; you, like your elders in Thunder Bluff, are proving that the need for balance transcends artificial racial barriers.$B$B$N, you''ve proven your worth as an friend of nature and the Circle - take this as a symbol of such.',12340),
	 (6130,0,0,0,0,0,0,0,0,'Welcome back - I''ve been following your progress on this lesson since you left, and I must admit I was surprised to learn about the situation at the Crossroads. This does bear some further investigation, as the introduction of such poisons into the environment is most upsetting to the balance.$B$BYou handled yourself with grace under pressure. For that, I can find no better way to reward you with permanent power over poison. Use it well, $N... use it well.',12340),
	 (6131,0,0,0,0,0,0,0,0,'We suffer much from the events of the past. Thank you for what you have done to help protect the Timbermaw.',12340),
	 (6132,0,0,0,0,0,0,0,0,'My sister Melizza said you''d be coming.  Thanks a lot for getting her out of the jam she was in; it''s too bad that she''s already probably found herself in a new one!',12340),
	 (6133,1,0,0,0,0,0,0,0,'I trust you did not read the registry. Not even you would do something that idiotic...',12340),
	 (6134,4,1,0,0,0,0,0,0,'There it is!  Looks like you got some of it on you too.  Kinda slimey, eh?$B$BWell, thanks a lot for all the trouble, $N.  This stuff will be worth a fortune... if I can convince the centaurs what it is!',12340),
	 (6135,273,0,0,0,0,0,0,0,'Excellent work, imbecile. I shall fashion this fur into something you can use.',12340),
	 (6136,25,0,0,0,0,0,0,0,'Keep this up and I may have to promote you from imbecile to mental deficient, first class.',12340),
	 (6141,1,0,0,0,0,0,0,0,'I received word of aid arriving from the east.  Are you the source of these rumors?  Have you come here to help the Scarlet Brother in its crusade?$B$BIf so, then listen close...',12340),
	 (6142,1,0,0,0,0,0,0,0,'Perfect mon, this is just what the witch doctor told me to do for my headache. He says, ""Mai''Lahii - go fish. It''ll make you feel better""$B$BWell, I feel better already, thanks mon!',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (6143,1,0,0,0,0,0,0,0,'As sweet as it is hearing the news that the naga have been vanquished, my heart still feels empty. For the rest of my life I will be dedicated to having them all killed.$B$BHere mon, your reward as I promised. It''s small in comparison to the gratification of knowing the naga fried for their hated act upon my crew.',12340),
	 (6144,1,1,25,0,0,0,0,0,'The Grand Crusader sits safely in the Scarlet Bastion while his forces pour into our lands, desecrate our structures and monuments and murder our people.$B$BThe time has come to deal with this pest. You will become the instrument of our reckoning.',12340),
	 (6145,0,0,0,0,0,0,0,0,'<Nathanos laughs.>$B$BExcellent! Finally! An opportunity to destroy the Scarlet Oracle!',12340),
	 (6146,6,0,0,0,0,0,0,0,'Where have you been? We had thought the Scourge had captured you.',12340),
	 (6147,11,5,0,0,0,0,0,0,'The fools! My deception went unnoticed! Prepare yourself, $C. We must strike with cold cunning!',12340),
	 (6148,4,66,0,0,0,0,0,0,'They will be reeling from this blow for years! Well done, $N! You have earned not only my respect but also this reward.',12340),
	 (6161,0,0,0,0,0,0,0,0,'Chest opens to reveal Rackmore''s treasure!',12340),
	 (6162,2,1,0,0,0,0,0,0,'You bring honor to me for following through with your word. My husband died in battle--he would have been proud of that. But I could not rest until I knew that the creature that has forced me to live my life alone paid for what it had done.$b$bThank you again, $N.',12340),
	 (6163,6,1,1,66,0,1000,0,0,'I wonder... did it beg for mercy? Could it know what mercy is?$B$B<Nathanos spits.>$B$BI will hang this beast''s head upon my wall.$B$BYou have earned a spot amongst one of my champions, $N.$B$B<Nathanos salutes.>',12340),
	 (6164,4,2,0,0,0,0,0,0,'There it is!  And oh my!  I forgot how full it was!$B$BThis is a glorious day, $N!  Stupendous!  Insanely good, I say!',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (6181,1,0,0,0,0,0,0,0,'You have to get this note to Stormwind? That''s not a problem, you can take one of my gryphons!',12340),
	 (6182,1,1,0,0,0,0,0,0,'After some reports of unusual Forsaken activity in the Eastern Plaguelands, SI:7 agents were dispatched to investigate. The results of that investigation are unsettling.',12340),
	 (6183,1,1,0,0,0,0,0,0,'<Mathias nods.>$B$BI had faith that Wrynn would send me men and women of honor - the most dedicated soldiers of the Alliance.',12340),
	 (6184,1,1,0,0,0,0,0,0,'The first mission will be straight up, $N. You go in, you come out. Recon...',12340),
	 (6185,1,1,1,6,0,0,0,0,'Rutger. Fredo. Turyen. All... dead...$B$B<Flint clutches the insignias tightly.>$B$BWhere were they? Did you discover any more information about this monster, the Blightcaller?',12340),
	 (6186,5,35,6,274,1000,1000,2000,1000,'No. It... NO! How? An agent of the Forsaken? The CHAMPION of the Banshee Queen???$B$B<King Varian Wrynn slumps in defeat.>',12340),
	 (6187,0,0,0,0,0,0,0,0,'It is a tragedy. I think... I believe that our kind is cursed, $N. We are cursed to lose our greatest warriors; our most noble heroes; our most gifted scholars.$B$BWe are indebted to you and I assure you, $N, wherever Nathanos Marris is now, he smiles down upon you.',12340),
	 (6241,0,0,0,0,0,0,0,0,'Thank you for what you have done. Please continue to help us, $N. We have very few allies on which to call upon.',12340),
	 (6261,1,0,0,0,0,0,0,0,'A crate for Westfall, eh? Have you been to Westall before? If so, then it''s no problem, my friend. I have plenty of gryphons trained to fly that route!',12340),
	 (6281,1,0,0,0,0,0,0,0,'Ah, a note from Quartermaster Lewis? I''m not surprised he needs more gear. Sentinel Hill is far away, in a land Stormwind has all but forgotten.$B$BWell thank you, $N. Here''s some money to cover your travel costs.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (6282,1,0,0,0,0,0,0,0,'This is most excellent news! Tell me again how you cast fear into the cold hearts of those vile harpies. The Bloodfuries have been dealt a serious blow!',12340),
	 (6283,1,0,0,0,0,0,0,0,'Already I feel the anger leave me. What will I do with my time? Knowing evil moves near my land kept my thoughts moving, though now they are silent. Perhaps this is a good thing... maybe now I can focus on the good, as all Tauren should.$b$bPlease accept this as a reward for your troubles.',12340),
	 (6284,1,0,0,0,0,0,0,0,'Good hunting, $N! Besseleth is an old predator in these parts... I will miss her not. Take this reward as a token for being the forest champion.$b$b<Maggran rubs the wound caused by Besseleth.>$b$bPerhaps now many more will travel to Sun Rock Retreat without fearing what lurks in the dark.',12340),
	 (6285,4,2,0,0,0,0,0,0,'Great, you brought the armor! We''ll get this divvied to those who need it immediately.$B$BThank you, $N. Your efforts have been a great help to us. And now that you''re no stranger to gryphons, I hope you''ll come and lend your aid to Sentinel Hill often!',12340),
	 (6301,0,0,0,0,0,0,0,0,'Ah, $N, you have the Gaea seeds. Watch and see how the blessing of the Earthmother can cause even these small kernels of life to bloom and flourish.$b$b<Tammra begins to chant.>',12340),
	 (6321,1,0,0,0,0,0,0,0,'Ah, an order for supplies.  You will want to take this to the Undercity, no doubt.  And quickly, for the Sepulcher must not be left under stocked.',12340),
	 (6322,6,0,0,0,0,0,0,0,'This crate must reach the Sepulcher in Silverpine? That is easily done; our bats fly there daily.',12340),
	 (6323,1,0,0,0,0,0,0,0,'An order from the Sepulcher? Very well. It is an honor to serve those who serve our Dark Lady.',12340),
	 (6324,1,0,0,0,0,0,0,0,'Good work, $N. These weapons will ensure our Deathguards don''t get caught unprepared.$B$BYou have done a valuable service for our Dark Lady.',12340),
	 (6341,0,0,0,0,0,0,0,0,'Ah, you wish to get this to Auberdine? Very well...',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (6342,0,0,0,0,0,0,0,0,'A package from Nessa? Thank you, $N! She told me she would send me samples of the fish caught near Rut''theran village. She thinks they may be very different from the fish caught here...$b$bMy! This jawbone is nearly twice the size of the same fish found here. And these scales are as big as a closed fist! Amazing!',12340),
	 (6343,0,0,0,0,0,0,0,0,'This is very interesting. The fish here are large, but I didn''t think the difference in bounties between here and the mainland was so great. There must be a reason for this...$B$BWell thank you, $N. I will discuss with the villagers the news you brought. Perhaps, one day, we will find the root of this oddity. But until then, we shall reap its benefits!',12340),
	 (6344,0,0,0,0,0,0,0,0,'Yes, I have need of a courier who will take a package to Darkshore. Will you help me?',12340),
	 (6361,1,0,0,0,0,0,0,0,'If you must take these hides to Thunder Bluff, then you are speaking to the right orc!',12340),
	 (6362,2,0,0,0,0,0,0,0,'Ah, a new bundle of hides. I will get to work on these immediately!$B$BThank you, $Gbrother:sister;. You have done me a great service. Here are some coins to pay for your time and travel costs.',12340),
	 (6363,6,0,0,0,0,0,0,0,'You need to take this to the Crossroads, eh? That''s not a problem. If you''ve already been there and spoken to Devrak, then you can take one of my wind riders back to him.',12340),
	 (6364,1,0,0,0,0,0,0,0,'Ahanu sent me finished products? Very good. There are many hunters and adventurers in the Crossroads now and business is lively. I am sure I''ll sell these goods very soon.$B$BThank you for all your efforts, $N. I am in your debt.',12340),
	 (6365,1,0,0,0,0,0,0,0,'You have to get this meat to Orgrimmar? That is no problem. For a small fee, my wind rider can take you there.',12340),
	 (6381,0,0,0,0,0,0,0,0,'This is great victory for the land. In time, other things will come to pass: the Venture Co. will pack up their buzz saws and axes, the angry fire spirits will calm, and the harpies will be pushed out by the land.$b$bOnly then $N, will Stonetalon be truly at peace.$b$bYou have done well $C; take one of these items as thanks for the new life you have created here today.',12340),
	 (6382,1,0,0,0,0,0,0,0,'Welcome to the new frontier, $N.  Ashenvale is a land of opportunity, one where a young $C like yourself is able to find boundless chances to prove their mettle.  Look around the outpost here, and be sure to travel out to the Zoram Strand, as the Horde has another outpost there as well.$B$BYour presence here tells me that you''ve come to learn more about the hunt.  Listen close, and I will gladly share with you what you need to know.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (6383,1,0,0,0,0,0,0,0,'There are three legendary creatures that make up the Ashenvale Hunt; you may seek them and test yourself against their cunning and might.  In the process, you will hopefully learn something about yourself.  The creatures are: the bear Ursangous, the nightsaber cat Shadumbra, and the hippogryph Sharptalon.$B$BThe creatures of the Ashenvale Hunt are powerful, and you may find that you''ll need aid in bringing them down.  If you should best them, bring me proof of your deed.',12340),
	 (6384,4,0,0,0,0,0,0,0,'Oh, wonderful! Those are fine cuts! These are from Zargh, are they? That orc sure knows his way into a lady''s heart...$B$BOh, I can''t wait to cook it. But not too much! Meat is best served rare, don''t you think?',12340),
	 (6385,1,0,0,0,0,0,0,0,'You have to get this to the Crossroads in the Barrens? Yes, I can get you there...',12340),
	 (6386,11,1,0,0,0,0,0,0,'Hah! I guess she liked it! Nothing brings red to a lady''s cheeks like a big, juicy steak!$B$BThank you, $N. You''ve done me a great service. Here is some money for your trouble, and don''t be surprised if I invite you to my wedding!',12340),
	 (6387,1,0,0,0,0,0,0,0,'You have to get this to Ironforge, eh? For a small fee I can put you on the back of one of my gryphons, and it''ll take you there. How does that sound?',12340),
	 (6388,1,0,0,0,0,0,0,0,'You have to get these to Thelsamar, eh? That won''t be a problem. As long as you''ve already been to Thelsamar and spoken to Thorgrum Borrelson, then you can take one of my gryphons back to him.',12340),
	 (6389,11,4,0,0,0,0,0,0,'Haha! Thank you, $N! You''ve done it! My father''s spirit can now rest and I can live in peace.$B$BThank you again. If there is anything I can do for you, please, just ask.',12340),
	 (6390,2,0,0,0,0,0,0,0,'Thank you, $N. Here, take this coin. I''m sorry it''s not more, but try to take some joy in helping destroy the Scarlet Crusade''s efforts!',12340),
	 (6391,1,0,0,0,0,0,0,0,'Ah, the lastest list of Brock''s best pupils. I have a batch of honorary picks ready to go. I just need to chisel in the names of the students...',12340),
	 (6392,4,2,0,0,0,0,0,0,'You brought the picks. Great! I''ll get these to my mining students. I''m sure they''re eager to use them on the ore deposits of Loch Modan.$b$bThank you for your help, $N. I am in your debt, but I hope this money will at least cover your travel costs.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (6393,0,0,0,0,0,0,0,0,'The water spirits within me bubble with the excitement. $N, you have given me a glorious victory to report to the Tribunal of the Tides.$b$b',12340),
	 (6394,1,0,0,0,0,0,0,0,'Great, you got it! Thanks a lot, $N. This is my favorite pick! Now if my peons ever finish chopping down these trees, maybe we can find a nice cave to mine!',12340),
	 (6395,0,0,0,0,0,0,0,0,'You have done a good deed today, $N. Although our struggle against the Scourge continues, let us hope that Marla and Samuel will find peace together in their final resting place.',12340),
	 (6401,5,1,0,0,0,0,0,0,'My goodness, my niece Kaya is alive! That is good news indeed. Thank you, $N.',12340),
	 (6402,0,0,0,0,0,0,0,0,'Before we begin, I ask that you first gather an army. We face a dragon, after all!',12340),
	 (6403,0,0,0,0,0,0,0,0,'<Bolvar holds the shattered medallion.>$B$BThe magic held within must be reignited. The dragon''s eye must be attuned.$B$BWindsor''s sacrifice has freed our Kingdom, but the threat of Onyxia and her kin is ever looming.$B$BThis medallion is what held my mind and body captive. It is also what gave me access to Onyxia''s own mind - to her secrets. Albeit the visions are muddled now, some things I do remember.',12340),
	 (6421,1,0,0,0,0,0,0,0,'Ah... Yes! That''s it; the Resonite crystals have a trace of Earthen magic. The Kobolds must have dug deep uncovering an Earthen.$b$bLegend states that the Earthen are creatures created by the Titans. They were used to create the land our feet walk on. This most definitely is a threat that cannot be ignored.$b$b<Mor''rogal shakes his head.>$b$bPerhaps I can enchant these ore samples to use against this Kobold plot.',12340),
	 (6441,0,0,0,0,0,0,0,0,'These are perfect, $N! Thanks for helping me out!$b$bOh, and this is for your time...',12340),
	 (6442,1,0,0,0,0,0,0,0,'We could use more of your kind around here, $N. Thank you for your help.',12340),
	 (6461,1,0,0,0,0,0,0,0,'Sweet, mon! Good news, perhaps we will have fewer unwanted dinner guests tonight.$b$bMany thanks, $N. We are forever in your debt.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (6462,0,0,0,0,0,0,0,0,'You found them! Thank you! Thank you, $N! You do not know how great a thing you have done for me.$b$bA troll without his charm is like an orc without his battle scars...$b$bWorthless.',12340),
	 (6481,1,0,0,0,0,0,0,0,'You bear good news, $C! I fear the possibilities of what an Earthen would mean to Kalimdor.$b$bSlaying Goggeroc was a task for no one less then a hero. You have done well; all of Stonetalon and Kalimdor are indebted to you, noble $C.$b$bAccept this as your reward most honored one.',12340),
	 (6482,5,1,2,0,0,0,0,0,'You found my brother!  He was captured by the Thistlefurs?  That is terrible news to hear, for although many Furbolgs are noble creatures, the Thistlefurs are corrupt.$B$BThank you for rescuing my brother, $N.  I do not want to think of how they treated poor Ruul.  He will likely sleep long after this ordeal...',12340),
	 (6501,0,0,0,0,0,0,0,0,'I should have known - a piece of the black dragon brood mother, Onyxia. How revolting...',12340),
	 (6502,0,0,0,0,0,0,0,0,'This amulet will grant you the access that you seek. The lair of Onyxia can be found in Dustwallow Marsh. As long as you hold the amulet, her wards cannot prevent you from entering.$B$BThe Blue Flight wishes you luck, $N.',12340),
	 (6503,1,0,0,0,0,0,0,0,'Very good, $N. Your hunting skills are impressive...$b$bThe loss of those outrunners help blind the Alliance, and when they lack intelligence they are less likely to launch attacks.',12340),
	 (6504,1,2,0,0,0,0,0,0,'Reading isn''t my strong point... but now I''ll be able to get back to work! Thanks, $N!',12340),
	 (6521,0,0,0,0,0,0,0,0,'Good. Well done, $C.$B$BNow that Malcin is dead, we can at least know that the Scourges advances will be halted. The Dark Lady thanks you for your efforts and wishes to reward you with a gift.$B$BAlthough we do not know the extent of the Scourges influence within the Downs, I am sure we will discover their plots soon enough.',12340),
	 (6522,0,0,0,0,0,0,0,0,'I recognize the insignia on this scroll, $N. You found this on that crone who reigns over Razorfen Kraul? Interesting.$b$bThe Scourge aren''t content with one continent it seems. This Ambassador Malcin--the one who wrote the note--is one of the Scourge''s plagued servants, a human diplomat to the kingdom of Lordaeron before things... changed.$b$bIf the Scourge are trying to gain a foothold in Kalimdor, then it is up to us to act.',12340),
	 (6523,4,2,0,0,0,0,0,0,'Kaya is alive! $N, I have you to thank for rescuing her.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (6541,3,0,0,0,0,0,0,0,'Ashenvale is a divided land, but our most recent efforts have been very successful. We not only have an outpost at the Zoram Strand, but another just north of here called Splintertree.',12340),
	 (6542,3,0,0,0,0,0,0,0,'Ashenvale is a divided land, but our most recent efforts have been very successful. We not only have an outpost at the Zoram Strand, but another just north of here called Splintertree.',12340),
	 (6543,1,0,0,0,0,0,0,0,'I can see that you are one that can be counted on. These updates are crucial to our plans to further our presence in Ashenvale. We can now plan our next move.',12340),
	 (6544,4,1,0,0,0,0,0,0,'So Torek''s attack was successful! Well done, $N. Night elves are decent foes. A little skinny, but strong and fierce! I''m sure the battle was something to see...$b$bAnd I hope you gained a scar or two!',12340),
	 (6545,1,0,0,0,0,0,0,0,'Well, my update will explain all of this to Kadrak. You must return this to him as quickly as possible.',12340),
	 (6546,1,0,0,0,0,0,0,0,'Take my update to Kadrak. Swiftly, $N.',12340),
	 (6547,1,0,0,0,0,0,0,0,'Let Kadrak know of the success we have had here holding off the night elves. Our plans are going well.',12340),
	 (6548,1,0,0,0,0,0,0,0,'$N, I thank you... but I will never forget what the Grimtotem have done to my village.',12340),
	 (6561,0,0,0,0,0,0,0,0,'Kelris has eluded the Argent Dawn for some time.$B$BFor some time they considered him dead or missing.$B$BBy ending his reign you have spared the lives of many innocent people, $N.$B$BEarthmother be praised! To sacrifice another to a servant of an Old God for personal gain is beyond disgusting!$B$BYou have done a great thing this day. Kelris was a creature of evil and sought to bring the world back to a time of chaos by worshipping such creatures as the Old Gods. Thank you, $N.',12340),
	 (6562,1,0,0,0,0,0,0,0,'Tsunaman sent you? Excellent. Then we have matters to discuss.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (6563,1,1,0,0,0,0,0,0,'Well done, $N. These are the crystals I spoke of. Intriguing...$B$BI can feel the power within them. The spirits of water cling to them. Whatever the naga were going to use these for... well, let us be glad they are no longer in their hands.',12340),
	 (6564,1,0,0,0,0,0,0,0,'This is interesting indeed. I am glad you have brought it to my attention.$b$bNow we have a name for our troubles... Lorgus Jett.',12340),
	 (6565,4,0,0,0,0,0,0,0,'Very good!! Thank you, $N. We may not have stopped the Twilight''s Hammer completely, but at least you have staved off another of their plans to return the Old Gods to power.$b$bWho knows what other plans they have manifesting, but we can rest easy for now.',12340),
	 (6566,6,0,0,0,0,0,0,0,'Are you prepared to take on this task?',12340),
	 (6567,1,1,6,0,0,0,0,0,'There is but one way into the dragon''s lair, $R.$B$BYou see, only the strongest of the Black Dragonflight are allowed entry into the lair of the brood mother. Many trials must be passed and the key to enter ceremoniously enchanted by General Drakkisath himself!$B$BSince you are not of black dragonkin, you may have some difficulty in obtaining passage.$B$B<Rexxar grins.>',12340),
	 (6568,11,6,1,1,0,0,0,0,'<Myranda holds the note, pauses, then smiles.>$B$BHow is he? Rexxar, I mean. Oh, come now, do not look so confused. The letter was left intentionally blank. It carried with it the intentions and thoughts of its creator. Judging from its contents, it is no wonder Rexxar left it as such. Imagine if you were captured or slain and this information discovered!$B$BOh, nevermind! Myranda will help you, $R. I owe the Warchief a favor or two.$B$B<Myranda smiles.>',12340),
	 (6569,1,1,0,0,0,0,0,0,'Let Myranda have a look, $R.$B$BOh yes, these will do nicely.$B$BWith these reagents, Myranda will create for you a medallion that will grant an illusion capable of fooling the black dragonflight''s gatekeeper.',12340),
	 (6570,6,0,0,0,0,0,0,0,'Have we run so low on able soldiers that Nefarian is sending me whelps? You will never pass my tests, broodling.',12340),
	 (6571,4,0,0,0,0,0,0,0,'Excellent, $N. You''ve saved me a lot of work!$b$bBut don''t think that I''m not grateful!',12340),
	 (6581,0,0,0,0,0,0,0,0,'This is perfect -- just the thing! Well, here''s the shipment.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (6582,0,0,0,0,0,0,0,0,'One of ssseveral complete...',12340),
	 (6583,0,0,0,0,0,0,0,0,'Another complete...',12340),
	 (6584,0,0,0,0,0,0,0,0,'The most hated remainsss...',12340),
	 (6585,1,0,0,0,0,0,0,0,'I had doubted your dedication, whelp. You persisted, dominating our enemies, bringing honor to our flight.$B$BI must now prepare the skulls for your ascension.',12340),
	 (6601,1,0,0,0,0,0,0,0,'It is merely dragon-talk, $N - more hot air than actual substantive information. Pompous, aggressive behavior is to be expected from their kind.',12340),
	 (6602,4,0,0,0,0,0,0,0,'A victory that will be remembered for many years, $N. The Drakefire Amulet will open Onyxia''s lair. Gather your allies and bring victory to the Horde.',12340),
	 (6603,3,0,0,0,0,0,0,0,'Well, hi there! So Meggi told you of the trouble I have found here?',12340),
	 (6604,1,0,0,0,0,0,0,0,'Aye, what can I do for you?',12340),
	 (6605,6,0,0,0,0,0,0,0,'Ah, $C. I see that there is hope yet. Are you here to assist me?',12340),
	 (6606,0,0,0,0,0,0,0,0,'Ah, so Harlo be sendin'' you? Well, den, who might you be? I s''pose you be wantin'' my help?',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (6607,5,1,0,0,0,0,0,0,'Now that''s a fine catch!$B$BCome over here, lemme show you how to set a few lines.',12340),
	 (6608,0,0,0,0,0,0,0,0,'''Course, you must be a friend of Lumak''s.$B$BFishin''? I can tell you all ''bout fishin''.',12340),
	 (6609,1,0,0,0,0,0,0,0,'I''ve always got room on my island for visitors... I reckon...',12340),
	 (6610,25,0,0,0,0,0,0,0,'You are in for a special treat, $N. Watch and learn!$B$B<Dirge begins to prepare clamlette surprise.>',12340),
	 (6611,33,5,0,0,0,1000,0,0,'<Dirge spits out some leather sandal bits.>$b$bPfftooey...$b$b<Dirge hacks loudly.>$b$bWhat? I''ll have you know that leather is surprisingly high in protein and low in carbohydrates.',12340),
	 (6612,33,5,0,0,0,1000,0,0,'<Dirge spits out leather.>$B$BPfftey...$B$B<Dirge hacks loudly.>$B$BWhat? I''ll have you know that leather is surprisingly high in protein and low in carbohydrates, $R. ',12340),
	 (6621,4,0,0,0,0,0,0,0,'Good work, $N. Issuing that challenge to the Foulwealds and defeating their leader sends them a strong message:$B$BThe Horde is not to be trifled with.$B$BI don''t believe that tribe will be giving us much trouble for a long time.',12340),
	 (6622,2,0,0,0,0,0,0,0,'Doctor $N, welcome to Horde Trauma.',12340),
	 (6623,1,0,0,0,0,0,0,0,'Wonderful. Put on your scrubs, we are to start at once!',12340),
	 (6624,2,0,0,0,0,0,0,0,'Doctor $N, welcome to Alliance Trauma.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (6625,1,0,0,0,0,0,0,0,'Wonderful. Put on your scrubs, we are to start at once!',12340),
	 (6626,0,0,0,0,0,0,0,0,'Thank you, $N! The work you''ve done will be a great help, I''m sure.$B$BI will continue my study of this diplomat and the rest of the quilboar here. If you seek greater adventure, I''d find a few friends and head into the cave that looks like a great boar maw just over there. I''m sure once you''re inside you''ll find greater challenges to face.',12340),
	 (6627,1,0,0,0,0,0,0,0,'Well done, $C. You have studied the text I asked you to, and now you have passed another of our tests.',12340),
	 (6628,21,0,0,0,0,0,0,0,'Well done, $N. I had my doubts if you studied the text I asked you to get, but you''ve answered correctly.',12340),
	 (6629,4,0,0,0,0,0,0,0,'Grundig Darkcloud is dead! $N, I will always be grateful for what you''ve done here today.',12340),
	 (6641,1,2,0,0,0,0,0,0,'I have witnessed many naga attacks since I arrived here. It puts my mind at ease that Vorsha will no longer roam freely.$B$BWe are in your debt, $N.',12340),
	 (6642,1,0,0,0,0,0,0,0,'Your offering has been accepted. Favor you have gained. Continue and you shall be allowed access to the ancient trades.',12340),
	 (6643,0,0,0,0,0,0,0,0,'Your offering has been accepted. Favor you have gained. Continue and you shall be allowed access to the ancient trades.',12340),
	 (6644,1,0,0,0,0,0,0,0,'Your offering has been accepted. Favor you have gained. Continue and you shall be allowed access to the ancient trades.',12340),
	 (6645,0,0,0,0,0,0,0,0,'Your offering has been accepted. Favor you have gained. Continue and you shall be allowed access to the ancient trades.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (6646,0,0,0,0,0,0,0,0,'Your offering has been accepted. Favor you have gained. Continue and you shall be allowed access to the ancient trades.',12340),
	 (6661,1,0,0,0,0,0,0,0,'These''ll werk nicely, matey. Me brother needs em still tickin'' and kickin,'' else they go sour... Ye don''t want to taste no sour rat kabob.',12340),
	 (6662,1,0,0,0,0,0,0,0,'Poor Monty. Ever since the Gnomeregan incident, he hasn''t been the same. That boy has never seen an ocean in his life, let alone being some kind of pirate.$b$b<Nipsy sighs.>$b$bAt least he keeps the flow of twitching critters coming.',12340),
	 (6681,0,0,0,0,0,0,0,0,'Most excellent, young thief.$B$BYou look a bit beaten down, but no worse for the wear.$B$BA long journey awaits you - long and rewarding. Are you prepared to finally embrace your destiny among the masters of Ravenholdt?$B$BSpeak with the guards outside. They will get you started.',12340),
	 (6701,0,0,0,0,0,0,0,0,'Hey, nice work! Keep this up and the other rogues might stop spitting on you.',12340),
	 (6721,0,0,0,0,0,0,0,0,'Yes, it is time, $C.',12340),
	 (6741,0,0,0,0,0,0,0,0,'Thanks again, $N. You do the Horde proud...',12340),
	 (6761,2,1,1,0,0,0,0,0,'Yes $C, thank you for coming. I apologize about the misunderstanding... the air is thick with mistrust between the Arch Druid here and Keeper Remulos in Moonglade. Each suspect the other of chicanery, and the fact that strange corruptions of Teldrassil continue unabated are still an issue here. It does little to quell mistrust.$B$BRegardless, our duty to the Cenarion Circle remains... even if those who lead it may disagree with one another.',12340),
	 (6762,2,1,1,0,0,0,0,0,'I am Rabine Saturna, and on behalf of Keeper Remulos and all of the denizens of this sacred glade I bid you welcome.$B$BI appreciate your interest and eagerness to assist the Cenarion Circle. I also know that Arch Druid of Darnassus expressed his displeasure to you in your lending us aid. Rest assured that it is for the greater good, and that you will be safe from any ill-conceived repercussions you may be the target of.$B$BYou are among friends here, $N.',12340),
	 (6781,0,0,0,0,0,0,0,0,'These are some good pieces, $N. I can use them to fashion new equipment for our troops.$B$BIf my supply level gets high enough, then maybe our seasoned fighting units will enter the field!',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (6801,0,0,0,0,0,0,0,0,'The blood of our enemies has been shed. I shall mix this blood with the rest that has been gathered. Once the offering is complete, the Ice Lord shall show these Stormpike dogs the full wrath of the Frostwolf Clan!',12340),
	 (6804,0,0,0,0,0,0,0,0,'You have done well, $C. The corrupted elementals you cured were an outrage to all bodies of water. Our strength lies in our purity and if we are to win our war with the others, we must remain strong.',12340),
	 (6805,0,0,0,0,0,0,0,0,'Your bravery is proven, as is your worth to us.  Perhaps I may have future tasks for you, tasks more befitting a valued ally of the Waterlords.',12340),
	 (6821,0,0,0,0,0,0,0,0,'Ah, so you do have the strength.  And you have the cunning as well, for Blackrock Spire is more than a match for brute strength alone.$B$BIndeed $N, you may yet prove a valued ally to us...',12340),
	 (6822,0,0,0,0,0,0,0,0,'You have done what most of your kind would think impossible.  You have faced the beings of the Molten Core, and triumphed!$B$BFor so small a creature, you have displayed great resource.$B$BSome day, perhaps we might strike a true allegiance between your kind and the Waterlords.',12340),
	 (6823,0,0,0,0,0,0,0,0,'Your exploits against our enemies ring through the chambers of the Waterlords, $N.  It was thought by some that your form is too small and fragile to fight in our war, but you have made great gains.  You have earned respect among us, an unbelievable feat.',12340),
	 (6824,0,0,0,0,0,0,0,0,'You have the hands!  You defeated the fire captains!  I would not have thought it possible, had I not known you and what you are capable of.$B$B$N, your exploits are without number, but word of this last feat will send waves among the Waterlords.  Your name may one day be legend to us.$B$BSpeak with me again, $N.  I may have yet another task...',12340),
	 (6825,0,0,0,0,0,0,0,0,'The fleet feeds on their flesh. It consumes the enemy.$B$BFlight is imminent!',12340),
	 (6826,0,0,0,0,0,0,0,0,'More! More! Bring more for they are soon to be ready!',12340),
	 (6827,0,0,0,0,0,0,0,0,'Not enough! I would expect this level of work from an initiate, but you, $N? Come on, soldier! HUSTLE! More flesh is needed!',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (6844,5,6,1,0,0,0,0,0,'Well great monkey toads! What have you got here? It''s sort of book shaped, I guess... I''ll try crack this shell on it.$b$bLayo sent you to me from Silithus? I''ve only heard very hushed rumblings - which I guess aren''t all that hushed when you think about it - about the horrors that are going on out there. Couple that with my lack of pleasure for anything bug-like, and you''ve got the recipe for me needing to stay here with the books!',12340),
	 (6845,1,1,2,0,0,0,0,0,'Ah, $N - I had hoped you would stop by. I am glad to see you well.$b$bI received notice you would be coming in from the field, and I wanted to personally express the Cenarion Circle''s gratitude for the assistance you''ve given us thus far. No doubt there are more secrets to uncover from Silithus; your delivery to Umber should prove most interesting once uncovered. Please, accept this as a token of our continued appreciation for your aid.$b$bThank you, generous $C.',12340),
	 (6846,0,0,0,0,0,0,0,0,'Ah, the orders! They say I''m to assault at will, and my will says... now!',12340),
	 (6881,0,0,0,0,0,0,0,0,'Well done, $N. I will use the power of this charm to augment the magic that has already been gathered. When enough power has been amassed, I shall focus the collected energies and call upon the Forest Lord to aid our cause.',12340),
	 (6901,0,0,0,0,0,0,0,0,'It''s about time! Now we can show the Alliance their folly in coming to Alterac Valley!',12340),
	 (6921,4,1,0,0,0,0,0,0,'This is exactly what I need! A fathom core is an incredible well of information that we will be able to draw much good from. Whatever the Twilight''s Hammer is up to in there - and believe me when I say it is no good - my comrades and I will now uncover.$b$bYou''ve done well here today; the Earthen Ring looks upon you warmly for assisting us. You''ve also helped the Horde as a whole, and for that you should be proud.',12340),
	 (6922,0,0,0,0,0,0,0,0,'This... this is quite the find, $N.$B$BYou acquired this from Baron Aquanis in Blackfathom, you say?  Baron Aquanis has long been thought of as a corrupted elemental power; this globe will prove what exactly had corrupted him.  While it would be no surprise if it turned out to be the Twilight''s Hammer, our studies will also show how they did it as well.$B$BYou did well in bringing this to me.  Please - take this, along with the Earthen Ring''s warmest regards.',12340),
	 (6941,0,0,0,0,0,0,0,0,'The flight will be ready soon. Continue your efforts!',12340),
	 (6942,0,0,0,0,0,0,0,0,'Keep em coming, soldier! The Aerie gryphons will be ready to strike in no time at all!',12340),
	 (6943,0,0,0,0,0,0,0,0,'Can you see it? Look at them, soldier! They''re coming around... Soon, Ichman''s flight will once again strike at the heart of the valley! Stormpike will rule the skies!',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (6961,1,1,0,0,0,0,0,0,'Ho ho hello.  I am Greatfather Winter, and I - courtesy of the fine folks of Smokywood Pastures... "Fresh from our farm to your plate, it''s Smokywood Pastures wholesome goodness" - would like to wish you a fantastic Feast of Winter Veil.$B$BIf you''ve been good this year, maybe you will receive treats from Smokywood Pastures as your treat for the Feast of Winter Veil.  Huzzah.',12340),
	 (6962,7,1,0,0,0,0,0,0,'You''re quite the helper to ol'' Greatfather Winter there, $N.  Have a great Feast of Winter Veil.$B$BHere''s a little something... you know, for the effort.',12340),
	 (6963,0,0,0,0,0,0,0,0,'Y-y-you can h-h-hear me!  Thank the b-b-bottom line!$B$BI''m not really a s-s-snowman - my n-n-name is Sacks, and I w-w-work for the Orgrimmar b-b-branch of Smokywood Pastures... I g-g-got sent out here to look for a m-m-missing package, when I was attacked by a c-c-creature I have never seen b-b-before!$B$BSo v-v-very cold...',12340),
	 (6964,0,0,0,0,0,0,0,0,'The Feast of Winter Veil, you say?  Alas, in times past it held a more substantial meaning to us tauren.  Nowadays, it seems as though others have turned the legend of this season of renewal into something that helps to sell candies and presents.$B$BIt''s no surprise that Furmund is bitter about that sort of change.  He and other tauren like him cling to our past like a banner of war.  While I think a little celebration is always good, it is important to remember the origins of the Feast.',12340),
	 (6981,1,0,0,0,0,0,0,0,'Oh... I have never seen anything like this...',12340),
	 (6982,0,0,0,0,0,0,0,0,'Ah, you got them. Good work, $N! These supplies are a little musty from sitting in that dark mine for so long, but we''ll make use of them nonetheless.$B$BThank you, $N. Your deeds are vital to the maintenance of our fighting forces.',12340),
	 (6983,5,4,1,0,0,0,0,0,'You found it!  You''ve saved Smokywood Pasture''s Feast of Winter Veil!$B$BPoor Sacks... we''ll be sure to send a team out there and figure out a way to unfreeze him.  Hopefully, he''ll be back in time for the day of the Feast; he''ll need to make up missed time working though.  Still, this wouldn''t even be possible if it weren''t for you!',12340),
	 (6984,0,0,0,0,0,0,0,0,'Ho ho hello, adventurer!$B$BThe goblins told me that you have earned a special gift this holiday season, and I am pleased to give it to you.  Here you go - have a wondrous Feast of Winter Veil this and every season in the future.',12340),
	 (6985,0,0,0,0,0,0,0,0,'You got them! Nicely done, $N! And I hope you saw a few dwarves during your raid, and shed their blood for the Frostwolves!',12340),
	 (7001,0,0,0,0,0,0,0,0,'I can only hope that those charged with collecting ram hides are as determined as you, $N.$B$BAt this rate, we will have the stables full in a matter of hours!',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (7002,0,0,0,0,0,0,0,0,'Well done, soldier. I will notify you when I have stockpiled enough of the hides.$B$BCarry on!',12340),
	 (7003,4,1,0,0,0,0,0,0,'Splendifimous!  Not only am I glad to see that you''ve returned with the residue, but also with all your major appendages intact!  That is, well, there was never any danger in using the Ultra-Shrinker, now was there!$B$BI do appreciate your effort on my behalf, $N.  Truly, you are a friend to goblins everywhere.  Accept this as a token of my appreciation!',12340),
	 (7021,0,0,0,0,0,0,0,0,'Ho ho hello. I am Greatfather Winter, and I - courtesy of the fine folks of Smokywood Pastures... "Fresh from our farm to your plate, it''s Smokywood Pastures wholesome goodness" - would like to wish you a fantastic Feast of Winter Veil.$B$BIf you''ve been good this year, maybe you will receive treats from Smokywood Pastures as your treat for the Feast of Winter Veil. Huzzah.',12340),
	 (7022,0,0,0,0,0,0,0,0,'Ho ho hello. I am Greatfather Winter, and I - courtesy of the fine folks of Smokywood Pastures... "Fresh from our farm to your plate, it''s Smokywood Pastures wholesome goodness" - would like to wish you a fantastic Feast of Winter Veil.$B$BIf you''ve been good this year, maybe you will receive treats from Smokywood Pastures as your treat for the Feast of Winter Veil. Huzzah.',12340),
	 (7023,1,1,0,0,0,0,0,0,'Ho ho hello.  I am Greatfather Winter, and I - courtesy of the fine folks of Smokywood Pastures... "Fresh from our farm to your plate, it''s Smokywood Pastures wholesome goodness" - would like to wish you a fantastic Feast of Winter Veil.$B$BIf you''ve been good this year, maybe you will receive treats from Smokywood Pastures as your treat for the Feast of Winter Veil.  Huzzah.',12340),
	 (7024,0,0,0,0,0,0,0,0,'Ho ho hello. I am Greatfather Winter, and I - courtesy of the fine folks of Smokywood Pastures... "Fresh from our farm to your plate, it''s Smokywood Pastures wholesome goodness" - would like to wish you a fantastic Feast of Winter Veil.$B$BIf you''ve been good this year, maybe you will receive treats from Smokywood Pastures as your treat for the Feast of Winter Veil. Huzzah.',12340),
	 (7025,0,0,0,0,0,0,0,0,'You''re quite the helper to ol'' Greatfather Winter there, $N.  Have a great Feast of Winter Veil.$B$BHere''s a little something... you know, for the effort.',12340),
	 (7026,0,0,0,0,0,0,0,0,'Well done, soldier. I will notify you when I have stockpiled enough of the hides.$B$BCarry on!',12340),
	 (7027,0,0,0,0,0,0,0,0,'The stables will be full in no time at all. Keep up the good work!',12340),
	 (7028,11,0,0,0,0,0,0,0,'Ha ha ha! I knew you''d be back.$b$b<Willow mutters>$b$b...So easy to convince.$b$b...Will do anything for the right price. Heh heh heh...',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (7029,2,1,0,0,0,0,0,0,'Thank you for returning this, $N. With the remaining liquid you brought me, I can continue my studies.$b$bWhile there is still much to do, you have helped to heal some of the corruption that Vyletongue spread through Maraudon. Please take this with my gratitude.',12340),
	 (7041,2,1,0,0,0,0,0,0,'Thank you for returning this, $N. With the remaining liquid you brought me, I can continue my studies.$b$bWhile there is still much to do, you have helped to heal some of the corruption that Vyletongue spread through Maraudon. Please take this with my gratitude.',12340),
	 (7042,0,0,0,0,0,0,0,0,'Y-y-you can h-h-hear me! Thank the b-b-bottom line!$b$bI''m not really a s-s-snowman - my n-n-name is Sacks, and I w-w-work for the Ironforge b-b-branch of Smokywood Pastures... I g-g-got sent out here to look for a m-m-missing package, when I was attacked by a c-c-creature I have never seen b-b-before!$b$bSo v-v-very cold...',12340),
	 (7043,0,0,0,0,0,0,0,0,'You found it!  You''ve saved Smokywood Pasture''s Feast of Winter Veil!$B$BPoor Sacks... we''ll be sure to send a team out there and figure out a way to unfreeze him.  Hopefully, he''ll be back in time for the day of the Feast; he''ll need to make up missed time working though.  Still, this wouldn''t even be possible if it weren''t for you!',12340),
	 (7044,0,0,0,0,0,0,0,0,'Now that you have recovered the two parts of my scepter, I have hope that Maraudon may one day be rid of the Vyle corruption.',12340),
	 (7045,0,0,0,0,0,0,0,0,'Ho ho hello, adventurer!$b$bThe goblins told me that you have earned a special gift this holiday season, and I am pleased to give it to you. Here you go - have a wondrous Feast of Winter Veil this and every season in the future.',12340),
	 (7046,0,0,0,0,0,0,0,0,'Please take this, and know that the power allotted to you now must be used for good. Continue your journey through the caverns, and with hope, you will find the remains of my uncle. Much danger awaits you, $N.$B$BSpeak with me again should the need arise.',12340),
	 (7061,1,1,66,0,0,0,0,0,'The legends and lore surrounding the Winter Veil are ones that have faded from the forefront of public though over the years.  Yes, I know that the goblins are helping to revive the season for their own ends, the fact that our people reflect upon it at least in some form does good to keep such lore alive.$B$BYour desire to go beyond the material and learn about our past is an admirable trait, young $c.  I salute your wisdom.',12340),
	 (7062,6,1,0,0,0,0,0,0,'The Feast of Winter Veil, you say?  Alas, in times past it held a more substantial meaning to us dwarves.  Nowadays, it seems as though others have turned the legend of Greatfather Winter into something that helps to sell candies and presents.$B$BIt''s no surprise that Goli is bitter about that sort of change.  He and other dwarves like him cling to our past like a banner of war.  While I think a little celebration is always good, it is important to remember the origins of the Feast.',12340),
	 (7063,1,1,66,0,0,0,0,0,'The legends and lore surrounding the Winter Veil are ones that have faded from the forefront of public thought over the years.  While I recognize that the goblins are helping to revive the season for their own ends, the fact that the citizenry thinks about it at least in some form does good to keep such lore alive.$B$BYour desire to go beyond the material and learn about our past is an admirable trait, young $c.  I salute your erudite nature.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (7064,0,0,0,0,0,0,0,0,'This is most wonderful news, $N! Thank you!$b$bI will speak with Marandis and ask his wisdom on the topic of Zaetar''s remains, but at least you have overcome the hardest of the tasks.$b$bI was told that if we were successful in our mission, I had permission to reward those who aided us. I was given these items as tokens from our people--you may choose one.',12340),
	 (7065,0,0,0,0,0,0,0,0,'This is most wonderful news, $N! Thank you!$B$BAlthough it concerns me that you were not able to bring back Zaetar''s remains, who am I to question the will of Cenarius'' first born. Perhaps now the will of the centaur will break and their thirst for blood will lesson--we can only hope.$B$BIf successful in our mission, I was given these items to reward any who aided us. You may choose one as a token of thanks.',12340),
	 (7066,0,0,0,0,0,0,0,0,'So my brother has finally found peace? I am proud to have lived to see this day. In all his arrogance and anger, I truly thought he was lost to us, but this... this symbol of his sacrifice only proves that he is not lost--he has only been reborn. He takes his place in nature as was his duty.$B$BThank you, $N. By bringing this to me, you have secured a small amount of hope that I thought I had once lost. This seed will be important to the people of this war-torn land some day... I can sense it.',12340),
	 (7067,0,0,0,0,0,0,0,0,'This is it, $R! This is it! Now I can begin the great task of uniting the tribes. Thank you.$b$bTake this for your efforts, please. I hope when next we meet, it will be on much different terms.',12340),
	 (7068,0,0,0,0,0,0,0,0,'Ah, these be perfect for me magics. Here, you take one of these trinkets and be on your way... me got much studyin'' to do.',12340),
	 (7070,1,2,0,0,0,0,0,0,'These are perfect, $N. I actually had other adventurers return from there also and from them I was able to fashion these... please, feel free to take one for your hard work. And thank you again for more samples to study.',12340),
	 (7081,66,0,0,0,0,0,0,0,'Well done! Graveyards are vital to our control of Alterac Valley. When you capture one, you help ensure the Alliance''s sovereignty here.$B$BGo now, $N. Reenter the battle, and if you see a graveyard under the Horde''s control... you know what to do!',12340),
	 (7082,0,0,0,0,0,0,0,0,'Well done, $N! With each graveyard under our control, the spirits of our enemies will wander more lost and aimless.',12340),
	 (7101,0,0,0,0,0,0,0,0,'I heard of your mission''s success! That pleases me...$B$BOur troops can now charge forward with impunity, and show the Alliance that Alterac Valley is no place for them!',12340),
	 (7102,21,0,0,0,0,0,0,0,'I received a field report stating you helped secure an enemy banner. Well done, $N! With their ranged troops out of position we can move the line of battle forward!',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (7121,0,0,0,0,0,0,0,0,'It''s good to see fresh troops here, $N, but with a little luck you''ll get into some action and won''t be fresh for long!$B$BSpeak with me again.  I have tasks I must discuss with you....',12340),
	 (7122,4,0,0,0,0,0,0,0,'You did it! Well done, $N!$B$BWhen we control a mine and have troops stationed there, it''s much easier to gather minerals and supplies from it.',12340),
	 (7123,0,0,0,0,0,0,0,0,'Hail, $N! It is good to see a $C like yourself, eager to do his part for the Horde. Speak with me again, for I have vital tasks for you...',12340),
	 (7124,0,0,0,0,0,0,0,0,'You captured a mine! With our own warriors protecting it, it will be much simpler to extract minerals from its depths, or gather supplies that have been cached there.$B$BWell done, $n. The deed you have done is a great boon to our battle efforts.',0),
	 (7141,0,0,0,0,0,0,0,0,'Well done, $N!  With the Horde''s nose bloodied after the death of their general, we''ll have the breathing room we need to explore!',12340),
	 (7142,0,0,0,0,0,0,0,0,'Well done, $N!  Stormpikes have no hope in this foolish invasion.$B$BHah!  So far, all they''ve done is get their general killed!',12340),
	 (7161,0,0,0,0,0,0,0,0,'That burning sensation you feel is your soul being awakened. Your spirit has accepted the call to arms.$B$BYou are now one of the Frostwolf, $N. Congratulations.$B$BCarry this insignia with you at all times. As you advance among the ranks of Frostwolf, I will replace the insignia with other, more powerful insignias.$B$BPerhaps someday you will be exalted among the Frostwolf Clan. Should that day ever come, you will be granted the Eye of Command.',12340),
	 (7162,1,1,0,0,0,0,0,0,'Take and wear this insignia with pride, $N. As your rank among the Stormpike grows, so too will the insignia. Return to me as you gain honor with Stormpike, and I shall replace your insignia with other, more powerful insignias.$B$BPerhaps someday you will grow to be a legend on this field of battle. Should that day ever come, you will be granted the Eye of Command.',12340),
	 (7163,0,0,0,0,0,0,0,0,'This new insignia reflects your rank amongst the Frostwolf. Keep it on you at all times.$B$BAnd $C... Die with honor!',12340),
	 (7164,0,0,0,0,0,0,0,0,'<Warmaster Laggrond salutes.>$B$BGo, $N! Continue your defense of the Frostwolf. This war must be won! For Drek''Thar! For the Warchief!',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (7165,0,0,0,0,0,0,0,0,'<Warmaster Laggrond roars.>$B$BThey have already begun telling tales of your deeds, soldier. The Stormpike shakes in fear when your name is uttered. Carry on!',12340),
	 (7166,0,0,0,0,0,0,0,0,'Soon, all on the field of battle will be under your watchful eye. Command of the Valley and its troops will be yours!',12340),
	 (7167,0,0,0,0,0,0,0,0,'Channel the power of the insignia. Let the enemy hear your words. The might of the Horde is unquestionable!',12340),
	 (7168,66,0,0,0,0,0,0,0,'Let our enemies see that a soldier of rank has struck them down! Fight for the glory of Stormpike!',12340),
	 (7169,66,0,0,0,0,0,0,0,'The king has been made aware of your battlefront heroics, $C. Continue in your stalwart defense of the Stormpike Guard!',12340),
	 (7170,66,0,0,0,0,0,0,0,'When we first met, I would have never guessed that a hero was in the making. Carry on, soldier!',12340),
	 (7171,25,0,0,0,0,0,0,0,'Surely it will be you who carries the Eye of Command!',12340),
	 (7172,66,0,0,0,0,0,0,0,'It is you who must lead our troops to victory, Commander! The soldiers are under your command. They will follow your direct orders. Lead them... Crush the Frostwolf.',12340),
	 (7201,4,1,0,0,0,0,0,0,'Wonderful! I will have these sent by courier to the Undercity at once!$B$BAs for you - here is payment, as promised. Keep the change, you filthy beast!',12340),
	 (7223,0,0,0,0,0,0,0,0,'These are some good pieces, $N. I can use them to fashion new equipment for our troops.$B$BIf my supply level gets high enough, then maybe our seasoned fighting units will enter the field!',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (7224,0,0,0,0,0,0,0,0,'These will do nicely. I''ll melt them down and patch them up and you''ll never know they came from those Stormpike cowards!$B$BThanks, $N. And let me polish up that armor of yours...',12340),
	 (7241,0,0,0,0,0,0,0,0,'To become a soldier of Frostwolf, one must first be tested...',12340),
	 (7261,0,0,0,0,0,0,0,0,'Let''s get to work!',12340),
	 (7281,0,0,0,0,0,0,0,0,'Your heroics will not go unnoticed, $N.$B$BI must waste no time if he is to be saved. Sylvanas must be contacted!',12340),
	 (7282,0,0,0,0,0,0,0,0,'You did remember to burn the corpse, didn''t you?',12340),
	 (7301,0,0,0,0,0,0,0,0,'Unbelievable! You did free them, right? Right??? Well at the very least we know where they were held.',12340),
	 (7302,0,0,0,0,0,0,0,0,'Well done! The information you recovered will be invaluable to our cause.',12340),
	 (7321,1,0,0,0,0,0,0,0,'My soothing turtle bisque will keep you warm on a cold night... if you care about that kind of thing.',12340),
	 (7341,0,0,0,0,0,0,0,0,'Excellent! I am a Tauren of my word, $r. The arrows are yours.',12340),
	 (7342,2,0,0,0,0,0,0,0,'A done deal if I ever saw one! The arrows are yours.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (7361,0,0,0,0,0,0,0,0,'$N, it is but one of thousands. A job well done nonetheless.',12340),
	 (7362,0,0,0,0,0,0,0,0,'Aye, this is definitely gnome. Well done, $R, but there is more work to be done.',12340),
	 (7363,0,0,0,0,0,0,0,0,'It would be easier if they just accepted their illness and gave in to your healing touch. It would also probably be less fun. Carry on! We''ll cure them, one way or another.',12340),
	 (7366,0,0,0,0,0,0,0,0,'Praise be to Benedictus! Another lost soul, soon to be saved by the white hot flames of the Light!$B$BGo ye, oh soldier of Light! More must be saved!',12340),
	 (7383,1,0,0,0,0,0,0,0,'To be in the presence of the Oracle Tree... it is almost to feel wisdom take form. Let me continue the telling...$B$BWith Teldrassil grown, the Arch Druid approached the dragons for their blessings, as the dragons had placed upon Nordrassil in ancient times. But Nozdormu, Lord of Time, refused to give his blessing, chiding the druid for his arrogance. In agreement with Nozdormu, Alexstrasza also refused Staghelm, and without her blessing, Teldrassil''s growth has been flawed and unpredictable...',12340),
	 (7385,0,0,0,0,0,0,0,0,'The blood of our enemies has been shed. I shall mix this blood with the rest that has been gathered. Once the offering is complete, the Ice Lord shall show these Stormpike dogs the full wrath of the Frostwolf Clan!',12340),
	 (7386,0,0,0,0,0,0,0,0,'Well done, $N. I will use the power of these charms to augment the magic that has already been gathered. When enough power has been amassed, I shall focus the collected energies and call upon the Forest Lord to aid our cause.',12340),
	 (7401,0,0,0,0,0,0,0,0,'You now have license to decimate dwarves by the dozen, $C!$B$B<Yazra stares off into the distance for a moment.>$B$BYou never forget your first de-spining...',12340),
	 (7424,0,0,0,0,0,0,0,0,'*Dirk throws the hoof in a pile behind him.*',12340),
	 (7429,0,0,0,0,0,0,0,0,'Oh, thank you for freeing me! You - ranked number one. Everyone else - ranked number two or lower.$b$bI knew my life was destined for more than just being an appetizer to some ogre!',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (7441,1,2,0,0,0,0,0,0,'You have found it! A curse upon that miserable imp. Alas, my material possessions are meager at best. You may choose from what I have to offer.',12340),
	 (7461,0,0,0,0,0,0,0,0,'We thank you, hero.',12340),
	 (7462,0,0,0,0,0,0,0,0,'You open the chest to find...',12340),
	 (7463,0,0,0,0,0,0,0,0,'Wonderful! Who are you again? Oh it matters not. What was I supposed to give you? Hrm... well you are a $C, perhaps you will find this useful.',12340),
	 (7481,1,6,0,0,0,0,0,0,'A shame... a tragedy. The items are lost you say? No trace of him, eh?',12340),
	 (7482,6,0,0,0,0,0,0,0,'A shame... a tragedy. The items are lost you say? No trace of him, eh?',12340),
	 (7483,0,0,0,0,0,0,0,0,'<Lydros yawns.>$B$BAs promised, the Arcanum of Rapidity. Don''t spend it all in once place.$B$B<Lydros snickers.>',12340),
	 (7484,0,0,0,0,0,0,0,0,'Don''t hurt yourself when applying the enchantment, $R.',12340),
	 (7485,0,0,0,0,0,0,0,0,'Yes, yes... Calm yourself. As promised, here is your Arcanum.',12340),
	 (7486,0,0,0,0,0,0,0,0,'Hydraxis'' voice descends from the waters'' surface...$B$B"Choose that which best suits you, $N.  May it protect you against the foes of the Waterlords."',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (7488,21,1,1,2,0,0,0,0,'You retrieved the web!  Well done, $N!  Lethtendris, like many elves of her ilk, are blind to the dangers the abuse of magic can cause to our world.  They believe they are masters of magic; they do not realize that they are slaves to their own addiction.  Her death saddens me, but it was necessary.$B$BThank you, $N.  I will have the energies within the web released safely over a wide area, and then I''ll destroy it to prevent future magical exploits.',12340),
	 (7489,0,0,0,0,0,0,0,0,'You have done well, $N. This web holds within it vast stores of the magic of Dire Maul, and I fear what damage may be unleashed if those energies were harnessed by one so irresponsible as Lethtendris. I am saddened by her death, but I know that she could never part with her web while alive.$b$bThank you, $N. I will send the web to students of magic more responsible than Lethtendris. They will be the new wardens of its power.',12340),
	 (7490,0,0,0,0,0,0,0,0,'This is a great victory for the Horde, $N. So many times you have honored your Warchief. It is time for the Warchief to honor you.',12340),
	 (7491,0,0,0,0,0,0,0,0,'Choose your reward and let the celebration of your glorious victory begin.',12340),
	 (7492,0,0,0,0,0,0,0,0,'Ah, it is good to see a $C heed my summons. I have need of your services, $N, and fear they will take you down a dangerous path...$b$bA path into Dire Maul.',12340),
	 (7494,66,0,0,0,0,0,0,0,'Hail, $N.  I am pleased to see you, but regret that our meeting is not under more pleasant conditions.$B$BListen close, for I have a vital task for you...',12340),
	 (7495,0,0,0,0,0,0,0,0,'For so many years I was held under her captivating gaze. Finally, to see justice meted and the honor of Stormwind restored! Today, we celebrate this glorious victory!',12340),
	 (7496,0,0,0,0,0,0,0,0,'Few are graced with such ceremony, $N. Please, choose your reward so that we may begin the celebration.',12340),
	 (7498,0,0,0,0,0,0,0,0,'Excellent work, $R. Should you find any more tomes, do not hesitate to return them to us.$B$BAs time passes, we tend to change around and even add new rewards for the return of missing tomes.',12340),
	 (7499,0,0,0,0,0,0,0,0,'Excellent work, $R. Should you find any more tomes, do not hesitate to return them to us.$B$BAs time passes, we tend to change around and even add new rewards for the return of missing tomes.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (7500,0,0,0,0,0,0,0,0,'Excellent work, $R. Should you find any more tomes, do not hesitate to return them to us.$B$BAs time passes, we tend to change around and even add new rewards for the return of missing tomes.',12340),
	 (7501,0,0,0,0,0,0,0,0,'Excellent work, $R. Should you find any more tomes, do not hesitate to return them to us.$B$BAs time passes, we tend to change around and even add new rewards for the return of missing tomes.',12340),
	 (7502,0,0,0,0,0,0,0,0,'Excellent work, $R. Should you find any more tomes, do not hesitate to return them to us.$B$BAs time passes, we tend to change around and even add new rewards for the return of missing tomes.',12340),
	 (7503,0,0,0,0,0,0,0,0,'Excellent work, $R. Should you find any more tomes, do not hesitate to return them to us.$B$BAs time passes, we tend to change around and even add new rewards for the return of missing tomes.',12340),
	 (7504,0,0,0,0,0,0,0,0,'Excellent work, $R. Should you find any more tomes, do not hesitate to return them to us.$B$BAs time passes, we tend to change around and even add new rewards for the return of missing tomes.',12340),
	 (7505,0,0,0,0,0,0,0,0,'Excellent work, $R. Should you find any more tomes, do not hesitate to return them to us.$B$BAs time passes, we tend to change around and even add new rewards for the return of missing tomes.',12340),
	 (7506,0,0,0,0,0,0,0,0,'Excellent work, $R. Should you find any more tomes, do not hesitate to return them to us.$B$BAs time passes, we tend to change around and even add new rewards for the return of missing tomes.',12340),
	 (7507,0,0,0,0,0,0,0,0,'You could have gotten quite a lot of gold for this book on the black market, $N. Especially since the protective seal has been broken, leaving the secrets of dragon slaying viewable to any with the requisite intellect to consume the knowledge held within the sacred pages.$B$BPerhaps a grand reward is in order... Well, a reward that will require enormous effort to obtain.$B$B<Lydros grins.>',12340),
	 (7508,0,0,0,0,0,0,0,0,'If you manage to enter the lair of the dragon, heat the blade under her fiery breath, and ultimately temper it in her blood, I shall bind the blade for your use.',12340),
	 (7509,0,0,0,0,0,0,0,0,'<Lydros murmurs something unintelligible.>$B$BAs promised, $C, the blade of Quel''Serrar.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (7541,1,2,0,0,0,0,0,0,'It will take time for our scholars to study the pendant you brought us.  But for your service to the Horde I would like to offer you a small token.$B$BThank you, $N.  Your acts bring honor to you, and to us.',12340),
	 (7562,2,6,1,0,0,0,0,0,'Greetings, $N, and welcome.  Are you here to study near the Altar of Storms as I am, perhaps to harness its energy for some hidden purpose...$B$BOr... are you here to speak with me?  Yes, I believe you are.$B$BYou want to master a dreadsteed?  Such is no easy task.  It will cost you no small amounts of blood, sweat... and of course gold.  But a dreadsteed of Xoroth is a prize well worth winning so if interested, listen on...',12340),
	 (7563,1,1,0,0,0,0,0,0,'Ah, very good. I will have this blood distilled into an ink and use it for the parchment I promised you. And perhaps I will save just a little for myself, as I hear its taste is quite euphoric...',12340),
	 (7564,0,0,0,0,0,0,0,0,'Oh, it''s blood. It must be from master Mor''zul then. He is so enamored with the stuff, and loves to see it spilled. I, however, prefer it coursing through the veins of a small rodent. It stays warm that way... until you want it.$B$BThis is powerful blood. Mor''zul must be making another parchment to summon a dreadsteed! How exciting!$B$BIf that''s true, and you''re going to perform the ritual, then... you''re going to need a lot more than blood, my friend.',12340),
	 (7581,21,0,0,0,0,0,0,0,'Ah, a most excellent recovery. The blood will suppress the Doomguard''s magical defenses.',12340),
	 (7582,1,0,0,0,0,0,0,0,'I merely need to combine the blood of the Wildspawn with these crystals and the prison shall be ready for use.',12340),
	 (7583,21,0,0,0,0,0,0,0,'You have done as I have asked. You are ready to be given the knowledge to conjure and control the beast.',12340),
	 (7601,0,0,0,0,0,0,0,0,'Oh boy, here we go again.',12340),
	 (7602,0,0,0,0,0,0,0,0,'Give me a minute and I''ll combine the essences into Fel fire.',12340),
	 (7603,5,0,0,0,0,0,0,0,'A deal is a deal! Quickly, take this and write this down. I don''t have time! My greatest conjuration is upon us!',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (7604,0,0,0,0,0,0,0,0,'It has been a pleasure doing business with you, $N!$B$BOn behalf of TB Ltd., I wish you luck in your search for Sulfuras!',12340),
	 (7621,0,0,0,0,0,0,0,0,'$C, you are about to undergo a rigorous series of events which shall test all of your abilities.$B$BI suggest that you listen to the story that I have to tell.$B$BBe warned, you must complete this task alone. It is recommended that your allies remain at a distance. Interference by outside agents will result in a most severe punishment.$B$BDestiny has led you and you alone here. Battle with honor. Harness the Light.',12340),
	 (7622,1,1,0,0,0,0,0,0,'Your tenacity and courage are astounding, priestess. You have earned the right to hold the Splinter of Nordrassil. Only one task remains: The Eye of Shadow must be recovered. Scour the world.',12340),
	 (7623,25,0,0,0,0,0,0,0,'My patience spans the millenia, $C.  But do not think that allows you more than an instant of my time...',12340),
	 (7624,1,0,0,0,0,0,0,0,'Ah, how splendid! After rotting a week, this heart will prove a succulent treat! Perhaps I will send for Ulathek''s head and place it before me as I eat...$B$BYou have done me a service, $C, and so my patience for you has grown. Marginally.',12340),
	 (7625,5,0,0,0,0,0,0,0,'There it is! I can hardly believe you got it! You must have struck a big deal with that Dreadlord or else paid a large sum, or both!$B$BMor''zul will have his ink very soon and then he can finally make the glyph parchment, so you can open a portal to Xoroth and pull through it one of the famed dreadsteeds!',12340),
	 (7626,1,0,0,0,0,0,0,0,'Very good! I hope these elixirs weren''t too hard to get. Sometimes alchemists can be so miserly with their creations...$B$BI''ll make the bell and keep it until you''re ready for your ritual.',12340),
	 (7627,1,5,0,0,0,0,0,0,'There they are! I hear that dark iron ore is only found in the depths of Blackrock, and I''m sure these shards weren''t easy to find either. I am often awed at the dedication you warlocks have. If you instead bent all that energy into the art of bug catching, oh... such a feast you would enjoy!$B$BSorry, a small digression. I''ll create the wheel and keep it for you until you''re ready for your ritual.',12340),
	 (7628,21,0,0,0,0,0,0,0,'Ah, very good. I''ll need these to contain the fires of the candle. Now that I have the scales, I''ll make the candle and hold onto it until you''re ready to begin your ritual for the Circle of Greater Summoning.',12340),
	 (7629,1,2,0,0,0,0,0,0,'Ah, good. J''eevee created the parchment. How was the Scholomance? Charming, don''t you think? And the bugs there... I hear they''re delicious!$B$BWell done, $N, and thank you for returning my jar. I''ve had it for a long time... and it''s not for sale!',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (7630,4,0,0,0,0,0,0,0,'You got it! Nicely done! Now I can create the lodestone. When you''re finally ready for your ritual to create the Circle of Greater Summoning, you''ll want a lodestone to make sure the ritual doesn''t fizzle out!',12340),
	 (7631,0,0,0,0,0,0,0,0,'The Xorothian Dreadsteed''s spirit is beaten.  Although rage pulses through its ghostly flanks, you know that the beast''s soul is yours...$B$BIt whispers dark magic into your mind and instills within you the knowledge to summon a dreadsteed.',12340),
	 (7632,0,0,0,0,0,0,0,0,'Of course I recognize my own leaves. Look at that! It''s in perfect condition.$B$BHow good of you to return it, $C.$B$BPerhaps you could be of service to us and we to you.',12340),
	 (7633,0,0,0,0,0,0,0,0,'Your diligence and integrity has been noted, $C.$B$BWe are Ancients: Protectors of this once great forest. Our physical forms were destroyed 10,000 years ago when Archimonde and the Burning Legion marched upon Hyjal. Our spirits, however, remain intact.$B$BThere are tasks that we can offer. Tasks that if completed will open up the secrets of the Ancients to you.$B$BKnow this, should you complete these tasks, merely return to this rock and we shall answer the calling.',12340),
	 (7634,0,0,0,0,0,0,0,0,'May my leaves provide your arrows protection from harm. May your arrows strike true. May the enemies of our world be smitten.',12340),
	 (7635,0,0,0,0,0,0,0,0,'A most foul dragon this one was. The sinew reeks of evil.$B$BGive me a moment to cleanse the filth from this flesh and apply the proper enchantments.',12340),
	 (7636,0,0,0,0,0,0,0,0,'You have served us well, $N! Take this stave and combine it with the bow string that Stoma is able to create. Together, they form a most formidable weapon.',12340),
	 (7637,2,1,0,0,0,0,0,0,'Blessings onto you, friend $C! Your donation goes far beyond what was needed. Your sacrifice will not only help us recover what we have lost, but also help us to help those most in need here in Ironforge.$B$BNow, let me make sure I''ve suitably prepared this censer for your future needs...',12340),
	 (7638,1,1,25,0,0,0,0,0,'I am glad to see you $N. I know that you have awaited word as to how to acquire your charger, and now that time has come.$B$BYou will be surely tested in many different ways, but most importantly in your willingness to rise above numerous obstacles thrust before you. These are not done as a learning exercise - your stature is beyond simple educational tests. You must save your future companion from the clutches of the evil you have spent your life fighting.$B$BTake heed, your time has come!',12340),
	 (7639,1,1,0,0,0,0,0,0,'Yes, this will do. You will be called upon more than once during this process to make acts of sacrifice; I am glad to see that you are willing to do just that. Sacrifice is a key component in what it takes to uphold the duties of being a Paladin... but I don''t have to lecture you on that.$B$BNow $N, you will need to show due judgment in your actions. To that end, this censer will act as your vessel to dispense such judgment on tortured spirits of lands lost to us.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (7640,21,1,0,0,0,0,0,0,'Well done, $N. To render the judgment of the Light on those that dwell in darkness is a task we must approach with vim and zeal; you have done just that with your sacrifice in Ironforge and your judgments of the spirits in Terrordale.$B$BYour next steps will call on both sacrifice and judgment again as you now strive to reclaim the spirit of a fallen charger who now serves a Death Knight known as Darkreaver.',12340),
	 (7641,3,1,0,0,0,0,0,0,'Hello there - Lord Shadowbreaker sent me word ahead of time that you''d be coming around this way to see me. I''m willing to make the barding you need, but it won''t be either cheap or easy; let''s get that out in the open first and foremost.$B$BI will say this much, and Grayson will back me up when I make this claim... you''ll not find better barding made anywhere in all of Azeroth than right here.',12340),
	 (7642,1,0,0,0,0,0,0,0,'This... well, this is exactly what I needed.  You''re quite the resourceful $C, aren''t you?$B$BAll right then, let''s get this barding finished up for you!',12340),
	 (7643,0,0,0,0,0,0,0,0,'The Ancient Equine Spirit accepts the offering of the Manna-Enriched Horse Feed, nuzzling the container as it helps itself to the special oats and grains. After it has eaten a little, it looks at the barding you possess and positions itself as though it wants you to place it upon its back...',12340),
	 (7644,1,1,0,0,0,0,0,0,'You''ve come far, my friend. Your barding is now suitably prepared for the last task at hand.$B$BYou will be using this barding to harness your charger once the task of redemption is complete. Before that, however, you will have a monumental struggle to overcome. Your time draws near - huzzah!$B$BThere is one last item that needs to be made before we begin this, $N. Hopefully your resourcefulness has not departed you since you had your barding made...',12340),
	 (7645,1,6,1,0,0,0,0,0,'YES, NOW WHO - wait - you''re giving me the gold too? You weren''t the one who called me mad (actually they called me a fruitcake nut-job)... still, you''re willing to show sacrifice even for wrongs you''ve not committed?$B$BI... I misjudged you, $N.  Should you need more horse feed, come see me. I will give it to you free of charge. Thank you... noble $C.$B$BI am going to keep the money though - I''m not that much of a nut-job as to give up a fortune.',12340),
	 (7646,1,1,0,0,0,0,0,0,'These are fine specimens, $N - the final pieces are now in place. At long last, your time has come!$B$BIn the depths of the Great Ossuary of Scholomance are the skeletal remains of many beings. Amongst them is a once-noble charger. The hollowed soul of this charger now serves as the steed for Death Knight Darkreaver. It is he whom you will face, and it is this steed that you will pass judgment upon. Only you, $N, can redeem its soul and save it from the torment of its servitude.',12340),
	 (7647,0,0,0,0,0,0,0,0,'A glimmer of life - long vacant from the poor beast - shines in its eyes as you hand its judged soul back to it. You feel a holy rush of power surge around you as you place the barding on its back, having judged the charger redeemed. The charger nuzzles your hand as the burdens of the past are lifted from the beast. You now feel as though you could call upon this beast to serve as your steed, should the need arise.$B$BYou have claimed your epic charger, $C! Congratulations!',12340),
	 (7648,1,1,0,0,0,0,0,0,'This is most impressive work. It seems that as Grimand gets older, his craftsmanship continues to improve. That''s quite the feat when his work was already some of the finest you''d find anywhere when he made my barding back in the day.$B$BWhile this barding would be a fine addition to any normal steed, we are not dealing with such a mundane beast. You''ll need this barding blessed by an appropriate source for it to be worthy of resting on a $C''s charger. I''ll hold onto it for you until then.',12340),
	 (7649,0,0,0,0,0,0,0,0,'Well done, my $gboy:girl;.$B$B<Lorekeeper Lydros tears out a page from the book.>$B$BI am sure you can make use of this recipe.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (7650,0,0,0,0,0,0,0,0,'Well done, my $gboy:girl;.$B$B<Lorekeeper Lydros tears out a page from the book.>$B$BI am sure you can make use of this recipe.',12340),
	 (7651,0,0,0,0,0,0,0,0,'Well done, my $gboy:girl;.$B$B<Lorekeeper Lydros tears out a page from the book.>$B$BI am sure you can make use of this recipe.',12340),
	 (7652,1,1,0,0,0,0,0,0,'Aright, $gmister:lady;, I got a hot deal for ya.$B$BI''m lookin'' to offload some of these here Imperial plate armor recipes and need someone willing to take on the burden. All I want in exchange is some thorium bars. Sound good?',12340),
	 (7653,1,0,0,0,0,0,0,0,'A pleasure doin'' business with ya.$B$BAnd $N, wipe that look of disgust off yer face.',12340),
	 (7654,1,0,0,0,0,0,0,0,'A pleasure doin'' business with ya.$B$BAnd $N, wipe that look of disgust off yer face.',12340),
	 (7655,1,0,0,0,0,0,0,0,'A pleasure doin'' business with ya.$B$BAnd $N, wipe that look of disgust off yer face.',12340),
	 (7656,1,0,0,0,0,0,0,0,'A pleasure doin'' business with ya.$B$BAnd $N, wipe that look of disgust off yer face.',12340),
	 (7657,1,0,0,0,0,0,0,0,'A pleasure doin'' business with ya.$B$BAnd $N, wipe that look of disgust off yer face.',12340),
	 (7658,1,0,0,0,0,0,0,0,'A pleasure doin'' business with ya.$B$BAnd $N, wipe that look of disgust off yer face.',12340),
	 (7659,1,0,0,0,0,0,0,0,'A pleasure doin'' business with ya.$B$BAnd $N, wipe that look of disgust off yer face.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (7666,6,1,0,0,0,0,0,0,'Are you headed back into the Scholomance, $n? You''ve already paid such a great price for the use of the Divination Scryer - perhaps you''d like to take another one with you. With it, you''d be able to face the perils of the Great Ossuary once more.$b$bBy all means, have it. You''ve certainly earned it.',12340),
	 (7667,0,0,0,0,0,0,0,0,'Your generosity is unrivaled, $N. I thank you for your kindness.$B$BI will be able to finish my divination scryer now, and I should be able to fashion more without further need of diamonds... perhaps you would be interested in helping me in its use? It is for a most important task, I assure you... one that left unchecked could spell unmitigated disaster for the spirit realm!',12340),
	 (7670,1,1,25,0,0,0,0,0,'I am glad to see you $N.  I know that you have awaited word as to how to acquire your charger, and now that time has come.$B$BYou will be surely tested in many different ways, but most importantly in your willingness to rise above numerous obstacles thrust before you.  These are not done as a learning exercise - your stature is beyond simple educational tests.  You must save your future companion from the clutches of the evil you have spent your life fighting.$B$BTake heed, your time has come!',12340),
	 (7701,1,1,0,0,0,0,0,0,'I never thunk I''d be lookin'' at thish ugly mug again!$B$BHe acshually looksh better without the resht o'' him attached.$B$BHere''s yer reward *hic*, $r.',12340),
	 (7703,0,0,0,0,0,0,0,0,'Wow... you ARE da true $gking:queen;! I never think I see this gauntlet in my life! It look like it got no mojo left anymore... maybe that creepy elf try and ruin gauntlet. Well, I say HAR HAR to him!$b$bLook - this mark on da gauntlet an old old OLD timey magic mark, older than da Gordok they say. Well, as Captain of da Gordok, we all learn one thing over and over - how to make mark come to life and give power back to gauntlet!$b$bI do it for you, $gking:queen;! Here, take da gauntlet and rule FOREVER!',12340),
	 (7721,4,1,0,0,0,0,0,0,'Scrumdillyriffic!  These cores will keep me working for some time.  Add to that the benefit of there now being fewer elementals along the coast, and I might no longer cry myself to sleep at the prospect of having set up shop in perhaps the worst place imaginable!$B$BThank you, $N, for your efforts on my behalf.  While it certainly straps me financially to do this, allow me to show you some gratitude you may understand and appreciate... loot!',12340),
	 (7722,0,0,0,0,0,0,0,0,'I hope you kicked his teeth in too, $N. Ragnaros knows, he deserved it.$B$BNow we can get down to business.',12340),
	 (7723,1,21,0,0,0,0,0,0,'Ye''re a good $g lad:lass;, ye are. I got ye a lil'' present fer yer troubles.',12340),
	 (7724,1,5,0,0,0,0,0,0,'<Hansel sneezes.>$B$BI think I''m gettin'' a cold. Damn this frigid climate!',12340),
	 (7725,4,1,0,0,0,0,0,0,'Inconceivably fantastical, $N!  You''ve come through for me again, and for that I thank you.$B$BThank you!$B$BWhile you may find this coin to be a little less than you''re accustomed to, rest assured your great deeds on the field of goblindom are echoing through the halls of power in the Steamwheedle Cartel.  Should you need something else to do, then by all means talk to me!',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (7726,4,1,0,0,0,0,0,0,'Top notch, $N, top notch!  While the coin I give you might not be the most you''ll ever receive for such work, rest assured my comrades in the Steamwheedle Cartel will hear about your efforts!$B$BIf you are looking for anything else to do, then let me know.  I can always use more elemental cores and such.',12340),
	 (7727,1,0,0,0,0,0,0,0,'Oh me achin'' feets.$B$BI figured since ye didn''t have a luffa...',12340),
	 (7728,1,21,0,0,0,0,0,0,'Fantastic work! Now for your reward.',12340),
	 (7729,0,0,0,0,0,0,0,0,'15.9 pounds! That may be a new record for blood and gut weight on apparel! Congratulations, $c!',12340),
	 (7730,4,0,0,0,0,0,0,0,'Well done, $C.  Though the extensiveness of the Zukk''ash presence will not be thwarted with anything less than a full-scale invasion, you have bought us some time so we can devise a proper strategy.$B$BI will be sure to have these carapaces analyzed; we''ll need to learn everything about them before we deal with what has unfortunately turned into a much larger issue than we had anticipated.',12340),
	 (7731,1,0,0,0,0,0,0,0,'Impressive, $C... most impressive!  If Stinglasher is indeed one of their strongest creatures, the study of the beast will prove to be quite valuable in time.  It''s now my charge to make sure we defend ourselves long enough to take advantage of it.$B$BPlease accept this coin bounty as a token of the entire camp''s thanks, $N.  Well done.',12340),
	 (7732,1,1,0,0,0,0,0,0,'Ah, I''ve been expecting this.  These creatures you faced... they are an ancient threat that the Horde continues to choose to ignore.  Hadoken was wise to bring this - and you - to me.$B$BThe Zukk''ash are nothing more than creatures called the silithid.  Some would think that they are a mindless nuisance, but let me assure you - they are a far, far worse threat than anything the Alliance could muster.$B$BIf you''re willing and strong enough, I could use your aid in bringing this threat to light.',12340),
	 (7733,1,2,0,0,0,0,0,0,'Excellent, excellent!  These are going to work out incredibly well - I can already tell that they''re going to be much harder when properly cured.$B$BThanks again for your help $N.  Here - please take one of my latest creations.',12340),
	 (7734,1,0,0,0,0,0,0,0,'Excellent, excellent!  These are going to work out incredibly well - I can already tell that they''re going to be much harder when properly cured.$B$BThanks again for your aid, $N.  Here - please take one of my latest creations.',12340),
	 (7735,5,1,2,0,0,0,0,0,'Incredible!  You may have found the granddaddy of all yeti hides with this!$B$BYou better believe I''ll pay you for it.  I normally don''t pay that much for a single hide, but I''m pretty sure I can make something special from it.  Thanks for thinking of me on this, $N!',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (7736,1,0,0,0,0,0,0,0,'There''s always room for more fiery flux, junior. Keep it comin''... unless I tell you to stop.',12340),
	 (7737,5,0,0,0,0,0,0,0,'Keep the residue pouring in!',12340),
	 (7738,1,0,0,0,0,0,0,0,'This is an incredible find! I believe this is the finest yeti hide specimen I have ever seen!$B$BIndeed, this is certainly worthy of an appropriate bounty. I normally don''t pay that much for a single hide, but I''m confident I can make something special from it. Thanks for thinking of me on this, $N!',12340),
	 (7789,0,0,0,0,0,0,0,0,'<Captain Shatterskull roars in triumph.>$B$BHow much more can they withstand? How many more Alliance filth must perish at the hands of the Horde for them to retreat? Only time will tell, $R... ',12340),
	 (7791,4,0,0,0,0,0,0,0,'Wonderful! We thank you for your generous donation, $N!',12340),
	 (7792,4,0,0,0,0,0,0,0,'Wonderful! We thank you for your generous donation, $N!',12340),
	 (7793,4,0,0,0,0,0,0,0,'Wonderful! We thank you for your generous donation, $N!',12340),
	 (7794,4,0,0,0,0,0,0,0,'Wonderful! We thank you for your generous donation, $N!',12340),
	 (7795,4,1,0,0,0,0,0,0,'Fantastic - these will go right to use, I assure you. Thank you again for your assistance! We''d certainly be lost without you.$b$bWith all the donations you''ve made, I would certainly process any additional runecloth donations you care to make in the future. Just be sure to check in with me, and I''ll personally make sure that your good deeds won''t go unrecognized!',12340),
	 (7796,2,0,0,0,0,0,0,0,'$N - without heroes like you working on behalf of the tribe, we''d surely suffer. Thank you for your continued efforts!',12340);
