	 (7814,4,0,0,0,0,0,0,0,'Wonderful! We thank you for your generous donation, $N!',12340),
	 (7815,1,0,0,0,0,0,0,0,'Oh, mon! I can''t thank you enough! Hopefully this here fishing pole will be reward enough for the job.',12340),
	 (7816,5,0,0,0,0,0,0,0,'MON! This is fantastic! With my best lure and the snapjaw population down, the fish will pile up.',12340),
	 (7817,4,0,0,0,0,0,0,0,'Wonderful! We thank you for your generous donation, $N!',12340);
