INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (7828,66,0,0,0,0,0,0,0,'A job well done, $R. The Revantusk thank you for your contribution.',12340),
	 (7829,21,0,0,0,0,0,0,0,'You have proven a worthy ally to the Revantusk, $N. Well done.',12340),
	 (7830,1,0,0,0,1000,0,0,0,'<Markhor examines the plume.>$B$BI wonder how many of our hunters this beast devoured before you brought it to justice.',12340),
	 (7831,4,0,0,0,0,0,0,0,'Wonderful! We thank you for your generous donation, $N!',12340),
	 (7832,2,0,0,0,0,0,0,0,'$N - without heroes like you working on behalf of the tribe, we''d surely suffer. Thank you for your continued efforts!',12340),
