INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (7838,0,0,0,0,0,0,0,0,'Much blood have you spilt on the Arena floor and I be glad to name you Grandmaster of the Arena!',12340),
	 (7839,1,4,0,0,0,0,0,0,'My tools! You found them! Oh glorious day! Thank you, $N.',12340),
	 (7840,0,0,0,0,0,0,0,0,'<Lard takes the huge haunch of meat from you and stuffs it in his face.>$B$BDis hit da spot! Tanks little one.$B$BLard make you special picnic basket for help Lard.',12340),
	 (7841,1,0,0,0,0,0,0,0,'It be lookin'' like the Revantusk are forgin'' new alliances as well, mon! You done good.',12340),
	 (7842,1,0,0,0,0,0,0,0,'Oh, mon, this gonna be good. One more step to go and Wildhammer see that they can''t mess with troll!',12340),
	 (7843,1,1,0,0,0,0,0,0,'I wish I coulda been there to see the look on their faces, mon. Are they packing up their bags? Leavin'' town?$B$BYou done good, $N. Real good. Otho reward you with the big mojo.',12340),
	 (7844,1,0,0,0,0,0,0,0,'Well done, $C. Zul''jin himself could not have done a better job!',12340),
	 (7845,0,0,0,0,0,0,0,0,'You must act quickly, $N. Surely the guards have been alerted to your presence.',12340),
	 (7846,0,0,0,0,0,0,0,0,'Freedom at last! Thank you, $N. Revantusk will know your deeds!',12340),
	 (7847,2,0,0,0,0,0,0,0,'You have done the Revantusk a great service, $N! We owe you a great debt of gratitude.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (7848,0,0,0,0,0,0,0,0,'I am now able to transport you to the Molten Core. Ask and it shall be done.',12340),
	 (7849,1,2,0,0,0,0,0,0,'My dearest brother, how I will miss you...$B$BThank you for your assistance, $N. You are truly a hero in my eyes.',12340),
	 (7850,1,0,0,0,0,0,0,0,'The dark energy that compels the Vilebranch has been lifted - for now. We must remain ever vigilant in our battle against evil, as even if the Vile Priestess is destroyed, another soon takes her place.',12340),
	 (7861,21,0,0,0,0,0,0,0,'A crippling blow to the Vilebranch, indeed. You shall be richly rewarded, $N.',12340),
	 (7862,1,0,0,0,0,0,0,0,'You are indeed a worthy candidate for the new position, $N. Accept this trinket as a token of our appreciation for your hard work. I will be reviewing all applications next year.',12340),
	 (7863,0,0,0,0,0,0,0,0,'You''ve certainly begun to prove yourself to us, $N. As a reward, please take this care package! Inside it you''ll find rations and bandages that are usable only inside Warsong Gulch. $B$BAs you continue to prove yourself inside the Gulch, you''ll find that these items will become available to you for purchase. Rations become available when you are Friendly with us, and bandages when you are Honored.',12340),
	 (7864,0,0,0,0,0,0,0,0,'You''ve certainly begun to prove yourself to us, $N. As a reward, please take this care package! Inside it you''ll find rations and bandages that are usable only inside Warsong Gulch. $B$BAs you continue to prove yourself inside the Gulch, you''ll find that these items will become available to you for purchase. Rations become available when you are Friendly with us, and bandages when you are Honored.',12340),
	 (7865,0,0,0,0,0,0,0,0,'You''ve certainly begun to prove yourself to us, $N. As a reward, please take this care package! Inside it you''ll find rations and bandages that are usable only inside Warsong Gulch. $B$BAs you continue to prove yourself inside the Gulch, you''ll find that these items will become available to you for purchase. Rations become available when you are Friendly with us, and bandages when you are Honored.',12340),
	 (7866,0,0,0,0,0,0,0,0,'You''ve certainly begun to prove yourself to us, $N. As a reward, please take this care package! Inside it you''ll find rations and bandages that are usable only inside Warsong Gulch. $B$BAs you continue to prove yourself inside the Gulch, you''ll find that these items will become available to you for purchase. Rations become available when you are Friendly with us, and bandages when you are Honored.',12340),
	 (7867,0,0,0,0,0,0,0,0,'You''ve certainly begun to prove yourself to us, $N. As a reward, please take this care package! Inside it you''ll find rations and bandages that are usable only inside Warsong Gulch. $B$BAs you continue to prove yourself inside the Gulch, you''ll find that these items will become available to you for purchase. Rations become available when you are Friendly with us, and bandages when you are Honored.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (7868,0,0,0,0,0,0,0,0,'You''ve certainly begun to prove yourself to us, $N. As a reward, please take this care package! Inside it you''ll find rations and bandages that are usable only inside Warsong Gulch. $B$BAs you continue to prove yourself inside the Gulch, you''ll find that these items will become available to you for purchase. Rations become available when you are Friendly with us, and bandages when you are Honored.',12340),
	 (7874,0,0,0,0,0,0,0,0,'<Captain Shatterskull roars in triumph.>$B$BHow much more can they withstand? How many more Alliance filth must perish at the hands of the Horde for them to retreat? Only time will tell, $R.',12340),
	 (7875,0,0,0,0,0,0,0,0,'<Captain Shatterskull roars in triumph.>$B$BHow much more can they withstand? How many more Alliance filth must perish at the hands of the Horde for them to retreat? Only time will tell, $R.',12340),
	 (7876,0,0,0,0,0,0,0,0,'<Captain Shatterskull roars in triumph.>$B$BHow much more can they withstand? How many more Alliance filth must perish at the hands of the Horde for them to retreat? Only time will tell, $R.',12340),
	 (7877,0,0,0,0,0,0,0,0,'You open the chest to find...',12340),
	 (7886,0,0,0,0,0,0,0,0,'Thank you, $N. Your exploits in Warsong Gulch ring throughout Ashenvale Forest.',12340),
	 (7887,0,0,0,0,0,0,0,0,'Thank you, $N. Your exploits in Warsong Gulch ring throughout Ashenvale Forest.',12340),
	 (7888,0,0,0,0,0,0,0,0,'Thank you, $N. Your exploits in Warsong Gulch ring throughout Ashenvale Forest.',12340),
	 (7921,0,0,0,0,0,0,0,0,'Thank you, $N. Your exploits in Warsong Gulch ring throughout Ashenvale Forest.',12340),
	 (7922,0,0,0,0,0,0,0,0,'The night elves and their allies must tremble at even the whisper of your name! For the Horde!',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (7923,0,0,0,0,0,0,0,0,'The night elves and their allies must tremble at even the whisper of your name! For the Horde!',12340),
	 (7924,0,0,0,0,0,0,0,0,'The night elves and their allies must tremble at even the whisper of your name! For the Horde!',12340),
	 (7925,0,0,0,0,0,0,0,0,'The night elves and their allies must tremble at even the whisper of your name! For the Horde!',12340),
	 (8292,0,0,0,0,0,0,0,0,'Thank you, $N. Your exploits in Warsong Gulch ring throughout Ashenvale Forest.',12340),
	 (8293,0,0,0,0,0,0,0,0,'The night elves and their allies must tremble at even the whisper of your name! For the Horde!',12340),
	 (8294,0,0,0,0,0,0,0,0,'<Captain Shatterskull roars in triumph.>$B$BHow much more can they withstand? How many more Alliance filth must perish at the hands of the Horde for them to retreat? Only time will tell, $R.',12340),
	 (8325,4,1,0,0,0,0,0,0,'You have successfully completed your first task; for that, you are to be congratulated. Such success gives me faith that you will turn out better than those young blood elves who fail to heed the lessons of their masters. Continued success will be rewarded - not only with knowledge, but also with tangible rewards as well.$B$BYour work here, however, is not finished. There is much more to learn, my young friend...',20886),
	 (8326,4,1,0,0,0,0,0,0,'The tower and surrounding areas should now be relatively secure, though only for the time being.  You have done well in providing us with a buffer of security, but we will need to reassert control over the entire isle if we are to survive here in the long run.  This will involve tackling much greater threats than errant mana wyrms and lynxes.$B$BTake this, $n - you will no doubt make good use of it for the tasks to come.',20886),
	 (8327,2,1,0,0,0,0,0,0,'Magistrix Erona told me you''d be along quick enough, $N. The Falthrien Academy to our west - the huge floating building with the ornate spires - is in bad shape. You''re going to be leading the effort to recapture it from one of the Wretched - a $R who has forever succumbed to their basest cravings.$B$BI hope you''re ready to work. This is not only going to be a lesson about danger, but also of what happens when you forsake the realities of who you are.',12340),
	 (8330,21,1,0,0,0,0,0,0,'Well done - I knew you''d be perfect for the task.  Once it''s safe to make use of our outdoor facilities on the isle, I''ll be putting these things to good use.$B$BLike I mentioned, please feel free to keep the satchel.  Also, you may find this piece of armor to be useful.  Consider it ample compensation for a simple task performed dutifully!',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (8334,1,1,0,0,0,0,0,0,'While the deaths of the tenders give me no joy whatsoever, it does show me that you''re ready for the most important task you''ll do here on Sunstrider Isle. Take this and put it to good use; you''ll need good items and sharp wits for the task ahead. Our reassertion of control over the island depends on it.',12340),
	 (8335,2,1,0,0,0,0,0,0,'Felendren''s head... you are to be commended, $N.  You''ve succeeded where others, like Felendren, have utterly failed.  Perhaps you are truly ready to be a contributing member of $R society.$B$BYour success here means that you are capable of surviving the greater threats that lurk in Eversong... and believe me, there are plenty to face.',12340),
	 (8336,1,1,0,0,0,0,0,0,'Splendid - these will do nicely.  I''ve been doing quite a bit of thinking on the current malaise Sunstrider Isle suffers under.  One possible course of action I had pondered was to collect these arcane slivers from the beasts on the isle.  In doing so, they could be experimented on; this would provide a potential source of culpability.$B$BAnyway, I will tend to the research.  Allow me to place this incantation on you.  I believe you''ll make good use of it!',12340),
	 (8338,1,1,0,0,0,0,0,0,'This is... most interesting.  And when I say interesting, I mean more disturbing than anything else.$B$BOur efforts to reassert control over the isle in the time following the destruction of the Sunwell have been a challenge.  I suspect that whatever foul source is corrupting the isle is at the heart of it all; this sliver may be of some aid in uncovering what''s really going on.$B$BYou were wise to bring this to me, $N. Take this as compensation for your diligence.  Thank you.',12340),
	 (8345,2,1,1,0,0,0,0,0,'Ah, $N - thank you for sharing your experience at the Shrine of Dath''Remar. First off, you should be commended for your sense of duty and respect - it will serve you well not only here, but in all of Azeroth as well.$B$BAs for the odd sensation, it is no doubt a contributing part of the taint that has befallen Sunstrider Isle. We shall keep an eye on it; thank you for alerting us to it!',12340),
	 (8346,1,1,0,0,0,0,0,0,'You''ve done well today, $N. Your willingness to learn shows that you may very well rise above the unyielding cravings you must endure as a $R.$B$BRest not on your laurels, young one, but instead seek to master what you have learned. Only through diligence will we as a race survive.$B$BTake this ',12340),
	 (8347,1,1,0,0,0,0,0,0,'Well hello there, $C! I heard that a resourceful young $R formerly in the service of Magistrix Erona might be making their way down here to help us Outrunners out. We certainly welcome the help, especially from someone who''s proven to be so competent.$B$BI hope you''re interested in running an errand or two for us.',12340),
	 (8350,2,1,0,0,0,0,0,0,'Thank you, I do appreciate the prompt delivery.$B$BWhile you''re here, please make yourself comfortable.  If you haven''t done so already, feel free to get a hearthstone and bind yourself here.  Using a hearthstone will allow you to recall to an inn once every hour.  If you ever lose your hearthstone, simply return to any inn - an innkeeper will gladly get you a new one.',20886),
	 (8463,0,0,0,0,0,0,0,0,'Excellent work, $N.',12340),
	 (8468,4,0,0,0,0,0,0,0,'That scoundrel, Thaelis, finally met his fate.  Good job, $N.  Things should be quiet with the Wretched for a while.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (8472,0,0,0,0,0,0,0,0,'You''ve done well, $N.  With our arcane sanctums not operating at full capacity, these power cores will go a long way in supplementing our needs.',12340),
	 (8473,0,0,0,0,0,0,0,0,'So, it is done. Curse these times that have driven us to desperate measures... and curse our enemy, the Scourge!$B$BLearn this, $N. Our lands must be protected, no matter what the cost. We shall prevail!',12340),
	 (8474,18,0,0,0,0,0,0,0,'This... this pendant.  I gave it to Old Whitebark after his people helped us rebuild our village.$B$BI guess this means he''s...$B$B<The blood elf clears her throat as she regains her composure.>$B$BI appreciate you bringing this to me, $N.  There is something I''d like to ask of you.',12340),
	 (8475,0,0,0,0,0,0,0,0,'We don''t anticipate the Scourge letting up on their attacks any time soon, but we still appreciate any help we get guarding the Scar.',12340),
	 (8476,0,0,0,0,0,0,0,0,'Good work, $N. With more people like you we''ll soon restore our lands to their former glory.',12340),
	 (8477,1,0,0,0,0,0,0,0,'There''s truth to the rumors! This hammer is light and strong at once; I shall manage to complete several of my unfinished projects.  And of course, I''ll let you have first pick. ',12340),
	 (8479,0,0,0,0,0,0,0,0,'Ya, $Gdad:mon;.  Zul''Marosh had this comin''.  He burn down Ven''jashi''s village.  I kill many Amani before they put me in this cage.  I hide something in the sand, my gift for you now.$B$BAh... ah, the poison... it spread now, mon.  Time to rest...',12340),
	 (8480,2,0,0,0,0,0,0,0,'Great job, $N. Let''s show the Wretched what we''re made of!',12340),
	 (8482,5,0,0,0,0,0,0,0,'Are you sure you found these on a night elf? They''re clearly written in Dwarven...$B$BFrom what I can understand of this letter, whoever wrote this did not cause the malfunction, but rather was sent here as a spy to observe the results of it. They call our endeavors reckless and dangerous... but who?$B$BOf course! That envoy from Ironforge! We were fools to trust anyone belonging to the Alliance!',12340),
	 (8483,5,0,0,0,0,0,0,0,'So, the deed is done. Excellent job.$B$BWord has been passed to the ranger general and believe me, the dwarves will pay dearly for their treason.$B$BYou''ve been of great service to your people today, $N.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (8486,1,0,0,0,0,0,0,0,'Thank you, $N. Now that we have the wraiths under control we can send someone in to assess the damage. Hopefully this wasn''t anything permanent.',12340),
	 (8487,1,0,0,0,0,0,0,0,'Excellent. I will cast an augmentation enchantment on the samples so I can more clearly analyze the taint on the soil.',12340),
	 (8488,1,0,0,0,0,0,0,0,'My endeavors are hopeless, $N. The very nature of the soil has been altered... the taint is irreversible. Thank you for your assistance. I''ll need to ask one last task of you.',12340),
	 (8490,1,0,0,0,0,0,0,0,'Excellent.  The defenses should hold off the Scourge a bit longer.  Thank you for lending us a hand, $N.',12340),
	 (8491,0,0,0,0,0,0,0,0,'These will do perfectly, $N. Take this piece of armor as a reward. I''ll be able to make more with the pelts you brought me.',12340),
	 (8547,0,0,0,0,0,0,0,0,'You are indeed a special hero, $N. We welcome you to the world of Azeroth, and offer you one of these unique gifts!',12340),
	 (8884,1,1,0,0,0,0,0,0,'A job well done. by the smell of it, I''d say you returned all that I asked for, and possibly more. I''m sure we can find some use for these, in a stew, or somesuch.$B$BAlas, it does not appear that your efforts have done the trick; the murlocs are not in retreat. This calls for more direct action! ',12340),
	 (8885,15,66,0,0,0,0,0,0,'At last! Though the Grimscale did not route. as hoped, it was entertaining to watch them panic in confusion when you laid low their so-called chieftain. You have my thanks, and the gratitude of the sin''dorei of Silvermoon City!$B$BPlease, take one of these in thanks for the service that you have rendered. ',12340),
	 (8886,4,1,1,0,0,0,0,0,'You did it! You''ve saved me from ruin and delivered my revenge upon those disgusting creatures!$B$BNow if I can just get these pretty rangers here to help me with this cargo, I''ll finally get out of here! I''ll have to come back when Velendris has retaken the shipyard.$B$BHere, take this coin. It''s what little I can afford, and the least that I can do to reward your efforts.',12340),
	 (8887,1,0,0,0,0,0,0,0,'Oh you sweet, sweet $c! I had no idea that those disgusting Grimscale murlocs had also pirated away with my navigation rudders! Without them, I would have no chance of navigating the seas again once we retake the anchorage and repair the ship.$B$BThank you very much! Here, take this coin as a sign of my appreciation.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (8888,6,1,0,0,0,0,0,0,'The magister was concerned for my wellbeing? How sweet; I wish that he had shown such an interest before, when we were at the Spire.$B$BThat doesn''t matter now. Please listen carefully, $C, as I have a favor to ask of you.',12340),
	 (8889,1,1,0,0,0,0,0,0,'I am grateful to you for your assistance, but saddened to hear that some of my fellow apprentices have fallen to their addiction.$B$BWith the power to the Spire cut off, I think I''ll stay here a while and see if things calm down long enough for me to sneak in and retrieve their remains.',12340),
	 (8890,5,18,0,0,0,0,0,0,'No! I was too late. It is all my fault.$B$BMy investigation into purifying alternative magical sources got out of hand before I could put a stop to it. If only I had gone myself... or that they had listened to me, and heeded my warnings!$B$BI have blood on my hands, $C. I thank you, though, for putting to rest the tortured souls of my former apprentices. It is some small consolation that they will not linger in that state where a Blood Elf is better off dead.',12340),
	 (8891,1,1,1,0,0,0,0,0,'Here it is, $N, the proof of my crime. This journal contains all of my ill-conceived studies.$B$BHeedless of the warnings, I continued my research, until it was almost too late. Then, when I grasped my error, I did what I could. But by then, some of my pupils had already gone too far. I evacuated the Spire to get them away from the corruption, but in my haste, forgot to shutdown the power sources.$B$BI will burn this tome so that no one else falls prey to its contents. I only wanted to help the sin''dorei.',12340),
	 (8892,0,0,0,0,0,0,0,0,'That''ll teach them not to mess with us.  Good work, $N.',12340),
	 (8894,1,1,0,0,0,0,0,0,'Well, I suppose that will have to do, now won''t it? Thanks for the help, $c. I can only hope to get this mess completely cleaned up before the Magister returns to Duskwither Spire.$B$BTake this pocket change; it''s not much but it''s all that I have at the moment. Feel free to dispatch a few more of the beasties on your way out, if you''d be so kind.',12340),
	 (8895,0,0,0,0,0,0,0,0,'Thank you, $N.  I''ve been expecting this letter.',12340),
	 (9035,0,0,0,0,0,0,0,0,'They''re gone now. Scared the breeches out of them with a well-placed fireball! Unfortunately for me, they threw our precious cargo into the river.',12340),
	 (9062,0,0,0,0,0,0,0,0,'The book is completely soaked. Instructor Antheol''s not going to like this at all.$B$BHere, take this money. I have an idea.',12340),
	 (9064,0,0,0,0,0,0,0,0,'You say those two incompetent fools bribed you to lie to me? You''ve done very well in coming to me, $N.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (9066,0,0,0,0,0,0,0,0,'Excellent job, $N. Don''t worry, they''re not stuck in that form permanently.  Their apprenticeship, however, won''t be restored until they earn it back.',12340),
	 (9067,1,1,0,0,0,0,0,0,'You''re quite the energetic young $gman:woman;, aren''t you?$B$BThis all looks very adequate. You certainly deserve compensation for gathering up all of this for me, and something a little extra I think.$B$BOh, I almost forgot, here''s an invitation to the party. And, $c, next time that you drop in make sure to dress up in something a little more... festive.',12340),
	 (9076,0,0,0,0,0,0,0,0,'You defeated him after all!  Undoubtedly my men softened him up for you.$B$BI jest, $c.  You''ve done well.  You''ll make a name for yourself if you keep your nose clean.',12340),
	 (9119,0,0,0,0,0,0,0,0,'Look around you. Things aren''t exactly in order.$B$BWe have a severe malfunction at the West Sanctum. Let us do our best to prevent matters from getting worse.',12340),
	 (9130,1,0,0,0,0,0,0,0,'Lymel wants you to head up to Silvermoon City and bring back her goods. huh? Sure. I can get you there quickly... for a small fee, of course.',12340),
	 (9133,5,6,0,0,0,0,0,0,'What''s this? Has Lymel''s rotting brain finally slid out of her head? She wants all of this!?$B$BDid you bring anyone with you to help take it back?',12340),
	 (9134,6,1,0,0,0,0,0,0,'Back down to Tranquillien in the Ghostlands, then? Sure, I can get you there fast!',12340),
	 (9135,1,0,0,0,0,0,0,0,'Well, I guess if he said that the rest of it will be coming quickly overland, then I''ll take him at his word.  He''s certainly never failed to provide the goods in the short time that we''ve been working together.$B$BThank you, $N, you''re a credit to the sin''dorei!  Here take this coin... it''s done nothing but jingle around in my pocket all day.',12340),
	 (9138,1,0,0,0,0,0,0,0,'Outstanding! But, there''s much to be done before the Scourge menace is completely driven from mighty Quel''Thalas!$B$BHere, take this coin... it''s not much, but you''ve earned it.',12340),
	 (9139,1,0,0,0,0,0,0,0,'Your success at Goldenmist Village takes us another step closer to taking our land back. Don''t fool yourself though, $c; this fight is far from over.$B$BHere, you''ve more than earned this. You may need it when you go up against Windrunner Village.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (9140,5,0,0,0,0,0,0,0,'You''ve done it, $N. You''ve broken the Scourge hold on the three villages! Now we can focus our forces with greater ease against the Scourge on the Dead Scar and south at Deatholme.$B$BHere, take your choice of any one of these. I trust that you''re not going anywhere? We can really use your continued assistance!',12340),
	 (9143,1,0,0,0,0,0,0,0,'I appreciate your efforts, $c! Thank you. Now, we can say that this expedition and all the lives lost on it haven''t been in vain.',12340),
	 (9144,0,0,0,0,0,0,0,0,'Help me, stranger. I must... reach Tranquillien... I cannot fail.$B$B<The blood elf falls back into unconsciousness as his eyes go blank.>',12340),
	 (9145,1,0,0,0,0,0,0,0,'Good to hear that Lethvalin made it to safety. and that he was smart enough to ask you for help instead of just waiting there.$B$BI hope that Ranger Salissa made it safely to Farstrider Enclave.',12340),
	 (9146,1,0,0,0,0,0,0,0,'That''s dire news indeed -- I completely overestimated Tomathren''s ability to lead. I''ll see to it that a group is dispatched to safely bring him and Valanna back in.$B$BUnfortunately, we never heard from Ranger Salissa, so I fear the worst in her case.$B$BYou''ve done the Farstriders a great service this day, $c. Please take one of these as a small token of our appreciation.',12340),
	 (9147,0,0,0,0,0,0,0,0,'Just in time, $N! I was about ready to start digging a hole for our friend here.$B$BMy potion seems to be working; he''s coming to.$B$BHey, I think he''s trying to get your attention. Why don''t you talk to him?',12340),
	 (9148,0,0,0,0,0,0,0,0,'Finally!  We''ve waited for a response from the regent lord for weeks! Let me see here...$B$B<Vandril begins to read the letter.>$B$BWhat''s this? A dark presence? He senses a dark presence in the Ghostlands?! No kidding; I could have told him that!$B$BThis is what we''ve been waiting for?',12340),
	 (9149,0,0,0,0,0,0,0,0,'Excellent!  These spines will be invaluable to my research!  When I find a cure for the plague and word of my name spreads I''ll make sure to make mention of you!$B$BIn the meantime, take these as a reward.  You might need them if you decide to go back to the coast.',12340),
	 (9150,0,0,0,0,0,0,0,0,'These are remarkably powerful, $N.  I''m very pleased with your work.',12340),
	 (9151,0,0,0,0,0,0,0,0,'Darenis sent you? Very well, I suppose we can use your aid in fighting Dar''Khan''s forces.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (9152,1,0,0,0,0,0,0,0,'With the rest of my supplies here. I can finally open shop. I''m sure that the high executor will be most pleased to hear that the war on Dar''Khan and the Scourge can commence.$B$BAnd, of course, there''s the small matter of your recompense. Very well, $c, here is the coin that I alluded to. Do be sure to drop by should you find yourself in need of any trade goods.',12340),
	 (9155,0,0,0,0,0,0,0,0,'Not bad, $N. Keep it up, we could use a few more people like you around here.',12340),
	 (9156,0,0,0,0,0,0,0,0,'Ah... Luzran and Knucklerot! Not looking so tough anymore, are you? I can see you''re still looking ugly as ever.$B$BTake one of these rewards, $N. You''ve earned it.',12340),
	 (9157,0,0,0,0,0,0,0,0,'With these necklaces we shall once again summon Aquantion.  The rebellious elemental will pay and our deaths will be avenged!',12340),
	 (9158,0,0,0,0,0,0,0,0,'You''ve done well, $N. It''s important that the plague doesn''t spread to the healthy wildlife in Eversong. I have more work for you if you''re looking for something to do.',12340),
	 (9159,0,0,0,0,0,0,0,0,'You''ve taken your task seriously and thus I''d like to present you with suitable rewards. We need more allies with your courage and determination, $N.',12340),
	 (9160,1,0,0,0,0,0,0,0,'Disappointing that the night elves'' plans were not readily apparent at An''daroth. However, those objects that looked like small magically-grown trees with powered orbs atop them sound interesting. It would appear that we''ll need to be more direct in our information gathering efforts.$B$BHere, take this coin and these potions. I believe that you''ll have use for them before we''re done dealing with these night elves.',12340),
	 (9161,0,0,0,0,0,0,0,0,'After browsing through the first few pages of this old book, you come to the conclusion that it once belonged to the one known as Dar''Khan Drathir.',12340),
	 (9162,0,0,0,0,0,0,0,0,'This information is very valuable, $N.  We all knew about Dar''Khan''s plans to steal the power of the Sunwell for the Scourge, but much of the information found here is completely new to us.  Magister Kaendris at the Sanctum of the Sun will want to look at this. ',12340),
	 (9163,1,0,0,0,0,0,0,0,'Troubling! These plans show the night elf forces at An''daroth, which we already knew, but also at An''owyn, a more remote ley-line nexus to the southeast.$B$BThere is a third nexus to the east, which is not mentioned, named An''telas. I have a very bad feeling about all of this, $c.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (9164,0,0,0,0,0,0,0,0,'Excellent job, $N. Without your help those prisoners would''ve lost their minds and souls to the Scourge.',12340),
	 (9166,5,5,0,0,0,0,0,0,'It was just horrible! Night elves! They conjured their moon crystal here for some nefarious plot, but I snuck away and gathered a larger group of our scouts and casters from the nearby Sanctum of the Sun. We killed most of them and the rest of the group is hunting down the remnants!$B$BI''m glad that you''re here now; I was only left a couple of scouts for protection! It''s not safe out here!$B$BGive me a moment and I''ll read through these plans to see what the night elves are up to.',12340),
	 (9167,0,0,0,0,0,0,0,0,'Today you''ve dealt a deadly blow to the Scourge''s grasp in the region.$B$BWith the vile traitor gone, it shall not be long before we''ve reclaimed our lands and our greatness is restored once again.',12340),
	 (9169,1,2,0,0,0,0,0,0,'That''s a relief, $c! I can assure you that if you hadn''t deactivated those scrying orbs we would be in a more tenuous position than the one we''re already in! To think, surrounded by enemies, and one of them able to spy upon our every move!$B$BBut now we don''t need to worry about that thanks to you! Here, take this, I want you to be rewarded for your efforts and I just happen to have a few things here that I no longer have any use for.$B$BThank you again, $N!',12340),
	 (9170,0,0,0,0,0,0,0,0,'Dar''Khan''s armies will soon fall. The Scourge shall not stand a chance against the combined might of the sin''dorei and the Forsaken.',12340),
	 (9171,1,1,1,0,0,0,0,0,'Very well, these will have to do.  No, don''t describe them crawling around, I don''t want to know!  I''ll work my magic upon these legs and they''ll turn out quite tasty.  A little spice here, a pinch of herb there, and then of course some arcane ingredients, and voila, a meal fit for a queen... or in this case, a dame.$B$BYour service has been adequate, $c.  Here, take this recipe and some samples.',12340),
	 (9172,0,0,0,0,0,0,0,0,'This book... it can''t be!  It''s Dar''Khan''s very own handwriting.  There must be information here that will reveal a weakness in our opponent.$B$BYou''ve done well in coming to us, $N.  The Farstriders have shown great wisdom in leaving this matter in our hands.  This armor should help you further our cause. ',12340),
	 (9173,1,0,0,0,0,0,0,0,'I''m certain that Lady Sylvanas will be pleased to hear that we''ve made progress in the matter.$B$BHere, take this coin as payment for your efforts.',12340),
	 (9174,0,0,0,0,0,0,0,0,'You''ve avenged our deaths and broken Aquantion''s grasp on our souls. We may finally rest.',12340),
	 (9175,6,0,0,0,0,0,0,0,'You say that you found it on one of the Scourge at Windrunner Spire and that there''s an inscription on it? Let me see!Here, take this coin for a job well done. ',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (9176,0,0,0,0,0,0,0,0,'The rumors were true!  The stone of light and the stone of flame do exist!  We shall use their power to create weapons against Dar''Khan.$B$BUse them when the time is right and the energies of the Sunwell, trapped within these objects, will vanquish him with the very power he sought to steal from us!',12340),
	 (9192,1,0,0,0,0,0,0,0,'That''s a fair job of butchery you managed there, $c. We''ll get the miners back to work now. I''m sure they''ll be disappointed that their break is over, but there''s armor and weaponry to be made, and that requires ore to be mined.$B$BHere, take this as payment for doing your duty. Go get your armor and weapons repaired, and have a drink on me.',12340),
	 (9193,1,0,0,0,0,0,0,0,'Disgusting, but necessary I can assure you. You have done us good service by investigating this matter, Please, take this as a token of our generosity and appreciation. ',12340),
	 (9199,1,0,0,0,0,0,0,0,'Mummies being raised by troll priests... clever! The Shadowpine trolls must be trying to bolster their numbers through necromantic means. I''d wager that these oracles were using the juju in their reanimation ritual.$B$BOnce again you perform your duty as befits a $C of your growing reputation. Take this with our gratitude.',12340),
	 (9207,1,0,0,0,0,0,0,0,'My apprentice was unable to take care of this herself?  I shall have a word with her when she returns then, gnolls or not.  Speaking of which, why didn''t she return with you?$B$B<The magister sighs.>$B$BThat one is a handful, and is going to be quite a challenge to properly train.  Thank you, for bringing these samples to me.  We are hoping that we can uncover some special property from them that will help in the fight against the Scourge.$B$BPlease take this coin as a token of my appreciation.',12340),
	 (9212,1,0,0,0,0,0,0,0,'You''re quite the hero, $c, to get her out of there alive.  I suppose we''ll have to mount an offensive to clear out those catacombs too.  As if we didn''t have enough trouble with the living trolls!$B$BYou''ve done a great thing today, I should reward you.  Take your pick from any of these.',12340),
	 (9214,1,0,0,0,0,0,0,0,'I''ll immediately send a few rangers out to survey the damage that you wreaked upon the Shadowpine trolls. I''ve no doubt that we''ll be able to mop up after your offensive and launch an attack on the Scourge soon if these weapons are any indication of your success.$B$BHere, I want you to take this coin in payment. It''s burning a hole in my pouch anyway.',12340),
	 (9215,1,0,0,0,0,0,0,0,'Ah. Kel''gash''s head is what smelled so bad. That''s a nice piece of work there, $C!$B$BWith their chieftain dead, the Shadowpine trolls should be in total disarray. Combined with your recent efforts to decimate their numbers, this should be the perfect opportunity to launch our counter-offensive against them and wipe them out for good.$B$BYou have my thanks, Might I interest you in one of these? ',12340),
	 (9216,0,0,0,0,0,0,0,0,'Take this draught, $N.  After you drink it, your physical strength against the Scourge will receive a boost. If you need more than this sample bring me more hearts.',12340),
	 (9217,0,0,0,0,0,0,0,0,'This will provide you with greater power against the Scourge. Bring more hearts if you find them, $n.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (9218,0,0,0,0,0,0,0,0,'Take this, $N.  You''ll feel the difference immediately!$B$BFeel free to bring more spinal dust; I can use as much of it as you can provide.  Side effects?  You might start feeling your joints acting up a bit.  Nothing permanent, I assure you!',12340),
	 (9219,0,0,0,0,0,0,0,0,'This dust is as potent as ever, $n. Keep bringing it to me if you''re in need to boost your magical powers against the Scourge.',12340),
	 (9220,0,0,0,0,0,0,0,0,'The Scourge has felt our wrath, $N. It won''t be long before their cursed citadel lies in ruins.$B$BWith their numbers weakened, it is time to launch an attack on more strategic targets.',12340),
	 (9252,0,0,0,0,0,0,0,0,'Many thanks, $N. Our job is a thankless one, but today you helped make it a bit easier.',12340),
	 (9253,0,0,0,0,0,0,0,0,'You must''ve been sent by someone at Fairbreeze Village. I knew it would just be a matter of time until help arrived.',12340),
	 (9254,0,0,0,0,0,0,0,0,'It''s so nice of my old mentor to check on me. It''s too bad she lost faith in my research long ago.$B$BDon''t waste your time trying to get me to return to her; you can either help me with my research or leave.',12340),
	 (9255,0,0,0,0,0,0,0,0,'These notes... are shocking. If they''re correct it means the damage to the land on the Dead Scar is irreversible.$B$BI''ll notify the grand magister right away. More reason for our race to escape this world and find our true fate in Outland.',12340),
	 (9256,0,0,0,0,0,0,0,0,'Thanks for coming, $N. Things are worse than we had anticipated. The Wretched have taken over Sunsail Anchorage in its entirety.',12340),
	 (9258,0,0,0,0,0,0,0,0,'Ah, my brother sent you. I do have a task I could use assistance with.',12340),
	 (9274,0,0,0,0,0,0,0,0,'I appreciate your help, $N. It pains me to see the spirits of my ancestors in their pitiful state. May they finally get the rest they deserve.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (9275,4,1,0,0,0,0,0,0,'Ah, excellent! I knew that a $r-delivery system would make for the most efficient application of the poison. With any luck the Shadowpine trolls will get fat on it before keeling over. That should get them off of the backs of the Farstriders, and me back to Tranquillien.$B$BIt has been a pleasure working with you, $c!',12340),
	 (9276,1,0,0,0,0,0,0,0,'Good, good! You handled that very well! Let''s see if you''re up to something a little more difficult now.',12340),
	 (9277,4,1,0,0,0,0,0,0,'Unbelievable! You really should talk to the captain about joining up as a Farstrider.$B$BAlright, $N, you''ve given us the breathing room that we need to continue building up our forces here. Actually, by your account there aren''t many of those trolls left at all! Maybe now we can join with Tranquillien and attack Deatholme?$B$BI think you''ve earned a little something. Take your pick.',12340),
	 (9278,0,0,0,0,0,0,0,0,'You are indeed a special hero, $N. We welcome you to the world of Azeroth, and offer you one of these unique gifts!',12340),
	 (9279,2,1,0,0,0,0,0,0,'$N, by my eternal soul, it is good to see you!  I don''t know why the Exodar crashed.  Only those of us that were in this part of the ship remain.$B$BThere''s not much time if we''re to save everyone that we can!',12340),
	 (9280,1,0,0,0,0,0,0,0,'Regrettable that those creatures had to die so that we might live - indiscriminate killing is not the draenei way.  However, the blood you gathered will replenish our healing crystals, so their deaths will not be in vain.',12340),
	 (9281,0,0,0,0,0,0,0,0,'Thanks for giving me a hand, $N. I was dreading the thought of venturing into the woods this close to Deatholme.',12340),
	 (9282,0,0,0,0,0,0,0,0,'Kaendris sent you? I might have a task for you, $c.',12340),
	 (9283,4,0,0,0,0,0,0,0,'The Light be praised! You''ve done what only a true $g hero : heroine; could have done, $N! The draenei you saved owes their continued life to your selflessness!$B$BPlease, take this supply pouch. You look like you can use it more than I.',12340),
	 (9293,1,0,0,0,0,0,0,0,'These will do. Thank you, $c!$B$BWhile you were out, I managed to gather some equipment together to make an analysis of the samples.  This should only take a moment.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (9294,1,4,0,0,0,0,0,0,'From what you describe, the neutralizing agent worked! I just wish that I knew how long it will last; we really need to remove that power crystal from the lake entirely.$B$BThank you, $N! I will tell Tedon to try the neutralizing agent on one of the captured beasts at once.',12340),
	 (9303,1,0,0,0,0,0,0,0,'With many of the owlkin now inoculated, we can focus on getting out of here and not have to worry about wiping out the owlkin population in the area.$B$BHere, choose from these.  You''ve done good work, and you deserve to be rewarded!',12340),
	 (9305,1,0,0,0,0,0,0,0,'Let me take a look at those.$B$BYes, I think that these will do nicely; good job, $N. The emitter is rather complex so it may take some time to finish the repairs. I''ll let you know when it''s ready.$b$bIn the meantime, you might see if Vindicator Aldar has anything he could use you for.',12340),
	 (9309,0,0,0,0,0,0,0,0,'Help... blood elves!  They... ambushed... me.  Don''t have... long.',12340),
	 (9311,1,1,0,0,0,0,0,0,'I thank you for dealing with the blood elf surveyor.  Surely she was their leader.  Rest assured, we will deal with whatever remnant of them is still nearby.$B$BPlease, take one of these weapons as a sign of my gratitude.',12340),
	 (9312,1,5,0,0,0,0,0,0,'I got it, I got it!  I think I managed to fix the emitter!  Here, I''ll just activate this last crystal and that should do it.$B$BTake a look at the emitter, $N.  It looks like it''s beginning to work... someone is appearing!',12340),
	 (9313,1,1,2,0,0,0,0,0,'Ah, good to see you again!  I''m glad that we were both able to get our emitters fixed or we might never have found one another.  And don''t worry, we''ll see to it that Ammen Vale gets help and supplies.$B$BSpeaking of assistance, now that you''re here, go around and introduce yourself to the others.  I know that there''s plenty to do.',12340),
	 (9314,1,0,0,0,0,0,0,0,'Oh, you must be one of the survivors we''ve been hearing about!$b$bI''m glad that you came. Don''t worry, we will send someone to see to Aeun''s injured leg.$B$BI''m most interested in hearing all about your harrowing story of survival. You''re a brave one to have made it all the way here.',12340),
	 (9315,1,0,0,0,0,0,0,0,'I apologize for the shoddy intelligence, $c.  Had I known of this Anok''suten ahead of time, I surely would have told you.$B$BWe''re spread too thin and things are slipping through the cracks!',12340),
	 (9327,1,1,0,0,0,0,0,0,'I know that we Forsaken appear monstrous to your eyes, but I assure you we mean your people no harm. We are here because of a common enemy: Dar''Khan the traitor! He has returned and now commands the Scourge that are invading this land from his steadfast, Deatholme, to the south.$B$BOur leader, Lady Sylvanas Windrunner, originally hails from these lands, and in fact used to be an elf. She has a history with Dar''Khan and wants him dead as much as your people do.$B$BWe will defeat him together, $c!',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (9328,0,0,0,0,0,0,0,0,'Now that''s one face I was not expecting to see so soon.$B$BThis is quite the good news, $N, in more ways than you can imagine. ',12340),
	 (9329,0,0,0,0,0,0,0,0,'We Forsaken are here because of a common enemy with the blood elves: Dar''Khan! He has returned and now commands the Scourge that are invading this land from his steadfast, Deatholme, to the south.$B$BLady Sylvanas Windrunner, who originally hails from these lands, and used to be an elf, has a history with Dar''Khan and wants him dead!$B$BWe will defeat him, $C, and you will help us do it!',12340),
	 (9352,0,0,0,0,0,0,0,0,'Night elves? Here? Those rats!$B$BDo you suppose they had anything to do with the malfunction in my sanctum? If you have any information, you''d better take it to Captain Sunbrand at once!',12340),
	 (9358,0,0,0,0,0,0,0,0,'You''re here to help us? Why didn''t you say so earlier? We can always use a hand!',12340),
	 (9359,0,0,0,0,0,0,0,0,'You''re here to help? Excellent!$B$BThe battle against the Amani trolls has taken its toll on us and capable fighters such as yourself are always welcome.',12340),
	 (9360,0,0,0,0,0,0,0,0,'The trolls have been keeping us pinned here while planning an attack on Fairbreeze Village. We were not expecting this at all.',12340),
	 (9363,0,0,0,0,0,0,0,0,'The information you''ve brought is of vital importance, $N.  Now that we know of the trolls'' plans we can prepare for an attack.$B$BWe won''t be caught with our guard down.',12340),
	 (9369,0,0,0,0,0,0,0,0,'Regrettable that those creatures had to die so that we might live - indiscriminate killing is not the draenei way. However, the blood you gathered will replenish our healing crystals, so their deaths will not be in vain.',12340),
	 (9371,1,0,0,0,0,0,0,0,'Oh, thank goodness you''ve come.  We have much to do.',12340),
	 (9394,6,5,0,0,0,0,0,0,'Who are you? You''re not one of the magister''s apprentices, that''s for certain!$B$BSent here to help me clean up this mess, no doubt!',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (9395,1,1,6,0,0,0,0,0,'Ah, good of Magistrix Dawnstrider to finally respond to my simple requests.  I should take up the matter of her attitude with the regent lord in Silvermoon. She''s quite rude!$B$BNothing for you to concern yourself with though. Now that you''re here, maybe I''ll finally be able to get those party supplies that I''ve been waiting for? ',12340),
	 (9409,1,6,0,0,0,0,0,0,'Good work!  This will do nicely to replenish our depleted healing crystals.$B$BBut now that you''re here, I think I have another use for you, if you''re willing?',12340),
	 (9452,1,1,0,0,0,0,0,0,'I hope the murlocs didn''t cause too much trouble, $N. I owe you a great debt of gratitude for all that you''ve done.$B$BPerhaps I could teach you how to fish? I''ll even supply the fishing pole and a bauble.',12340),
	 (9453,1,1,1,0,0,0,0,0,'Poor Diktynna... That murloc gave her quite a scare.$B$B<Acteon sighs.>$B$BHopefully she will recover from the injuries soon...$B$BSo I presume you''re looking for work. Well there''s plenty of that to be found at Azure Watch!',12340),
	 (9454,1,0,0,0,0,0,0,0,'Well done, $n, well done!$b$bHere, I cooked up some tenderloins while you were gone. Maybe you''d like the recipe, too?',12340),
	 (9455,6,0,0,0,0,0,0,0,'How did such a thing end up in the stomach of a nightstalker? Could the debris from the crash have contaminated more beasts?',12340),
	 (9456,1,0,0,0,0,0,0,0,'I just hope it''s not too late...',12340),
	 (9463,5,0,0,0,0,0,0,0,'Let us hope that this ointment will strengthen her spirit!',12340),
	 (9473,1,0,0,0,0,0,0,0,'Watch as the plant works its magic.',12340),
	 (9505,0,0,0,0,0,0,0,0,'You say that you''ve found one of our crew and that she is injured? I will send one of my crewmen to your village immediately!',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (9506,1,1,1,0,0,0,0,0,'You''re a resourceful one! With our navigation gear, we can figure out just how far we''ve veered off course.$b$bBut wait, what''s this? There''s something rolled up in the map. Let me see...$b$bThese are orders from Mogul Razdunk of the Venture Company. According to these plans, they''re here to strip-mine the island of the crystal wreckage, then hijack our ships once they''re finished.$b$bBy Bronzebeard''s bushy brow! This is why they forced us to land? How could they know of our plans?$b$bI smell a traitor...',12340),
	 (9512,1,1,1,0,0,0,0,0,'Bless yer heart, stranger. This''ll go a long ways in liftin'' the morale o'' the crew.
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (9537,5,5,1,0,0,0,0,0,'Incredible! This was all part of their master plan!$B$BThis information must reach the king and your own leaders. The implications are staggering.',12340),
	 (9538,0,0,0,0,0,0,0,0,'The totem has various primal markings. You see owls, bears, wolves and stags carved into the surface.$B$BYou note a strange collection of symbols that makes your mouth form the word A-K-I-D-A.',12340),
	 (9539,0,0,0,0,0,0,0,0,'The totem has various primal markings. You see owls, bears, wolves and stags carved into the surface of the totem.$B$BYou note a strange collection of symbols that makes your mouth form the word C-O-O.',12340),
	 (9540,0,0,0,0,0,0,0,0,'The totem has various primal markings. You see owls, bears, wolves and stags carved into the surface of the totem.$B$BYou note a strange collection of symbols that makes your mouth form the word T-I-K-T-I.',12340),
	 (9541,0,0,0,0,0,0,0,0,'The totem has various primal markings. You see owls, bears, wolves and stags carved into the surface of the totem.$B$BYou note a strange collection of symbols that makes your mouth form the word Y-O-R.',12340),
	 (9542,0,0,0,0,0,0,0,0,'As you read the totem, your mouth forms the word V-A-R-K. You understand this to mean justice.',12340),
	 (9544,1,1,15,0,0,0,0,0,'[Furbolg] The prophecy spoke of one that would rise and deliver us from the oppressive grasp of Bristlelimb -- that the spirits themselves would herald the arrival of this hero.$B$BAnd now, you have come.$B$BI humble myself before you, great one.',12340),
	 (9548,1,0,0,0,0,0,0,0,'This is fantastic! The theft of my equipment has given me more insight into the nature of these murlocs than I could have possibly gained in weeks of observations!$B$BI know what I''m going to say in my report already.$B$B''When faced with the products of a technologically superior culture, the Blacksilt displayed none of the curiosity characteristic of emerging cultures in humanoid species.''$B$BIt''s brilliant! The gentlemen in Ironforge are going to love it! I can''t thank you enough, $N.',12340),
	 (9549,4,0,0,0,0,0,0,0,'Astounding, simply astounding! These are perfect, $N. I can already see them under the glass in the museum in Ironforge. The text for the display is virtually writing itself in my head!$B$BYour help has been invaluable in getting my studies back on track. How do you spell your name? I''ll make sure it appears in my report as co-author.$B$BOne of the chaps on the ship gave me this ''treasure map'' to cover a gambling debt, but mythology isn''t my area of study. Superstitious lot, sailors. ',12340),
	 (9550,0,0,0,0,0,0,0,0,'Examining the book carefully, you conclude that it must be a journal. Its pages are filled with an elegant script differing from that of the map. The text of many of the pages is obscured by drawings and writing in the mapmaker''s hand.$B$BIt''s nearly impossible to make out the text beneath the mapmaker''s tales of drunken carousing during shore leave. ',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (9557,1,0,0,0,0,0,0,0,'Hmm... this is most intriguing. Yes, I should be able to make out what the original author wrote in the pages of this book.$B$BI should have everything I need for the process. This should only take a moment.',12340),
	 (9559,0,0,0,0,0,0,0,0,'For centuries, we lived in relative peace with the creatures of the land. Several months ago, Kurz began to see dark omens. The peace that we enjoyed for so long was to be lost. The extent of the catastrophe could not be known!$B$BSo it would be that the gods would shatter our land - turning both friend and foe against us. But there was something else... Amidst the chaos, a hero would rise: A hero not of Stillpine blood. The Promised One would deliver us from devastation.$B$BThat prophesied hero was you.',12340),
	 (9560,0,0,0,0,0,0,0,0,'Not only is the prophecy true, this armor is also amazing! Surely it is armor fit for a champion! And I will sell it to you at discounted prices, furless one.$B$BI jest... The first piece is complimentary.',12340),
	 (9561,0,0,0,0,0,0,0,0,'Grasses and shrubs cover an unnatural bulge in the earth.$B$BA few minutes spent digging reveals an old box, almost certainly the one mentioned in Nolkai''s journal.',12340),
	 (9562,4,0,0,0,0,0,0,0,'Mmmmm... Delicious grain... Parkat will be delighted!',12340),
	 (9564,0,0,0,0,0,0,0,0,'<Gurf spits on the clump of fur and tries to affix it to the hairless patch on his backside.>$B$BThis will have to do for now! Hopefully one of the shaman will be able to repair the damage.',12340),
	 (9565,0,0,0,0,0,0,0,0,'The blood crystal radiates a sickly aura that seeps into the water of the cave.',12340),
	 (9566,0,0,0,0,0,0,0,0,'These blood crystals that you saw; my scouts have seen many more to the north.$B$BI thank you for aid but now ask that you leave me to confer with the elders. I will call for you once I have spoken with the other elders of the village.',12340),
	 (9567,1,0,0,0,0,0,0,0,'Well done, $N. Let me see what I can learn from this glyph, so we can plan our next move.',12340),
	 (9569,1,0,0,0,0,0,0,0,'Without their leader, and with the recovery of the corrupted crystals underway, we can safely keep the satyr in check. Light knows how many more of these wretched creatures are out there.$B$BHarbinger Mikolaas and I are grateful for the help you''ve provided in dealing with the satyr before they could become a larger threat. Your work stands as a reminder that vigilance is the key to victory against the Legion and its minions.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (9570,0,0,0,0,0,0,0,0,'The Promised One has emerged victorious!$B$BThe prophecy is nearly complete. Now about that hide...',12340),
	 (9571,0,0,0,0,0,0,0,0,'This is the strongest armor I''ve ever made! Make good use of it, $N.',12340),
	 (9573,0,0,0,0,0,0,0,0,'This may very well be the opportunity that we needed! I will send an attack at once! The Stillpine thank you for your service, $N!',12340),
	 (9574,1,0,0,0,0,0,0,0,'There''s more than enough here for my research. Thank you, $N. If you find any other evidence that the crystals are corrupting Bloodmyst''s native creatures, let me know right away.',12340),
	 (9576,1,0,0,0,0,0,0,0,'This is most curious, $C. I don''t believe we''ve ever seen the murlocs wearing any kind of adornment before.$B$BGiven the corrupting influence that the crystal shards are known to have, the murloc that wore this pendant must have believed it granted him power over his fellows. I wouldn''t be surprised if he had rapidly outgrown his fellow murlocs and gained in strength.',12340),
	 (9578,0,0,0,0,0,0,0,0,'The corpse appears to be dressed in the manner of an Exodar technician, but the pendant described by Morae is absent.',12340),
	 (9579,1,1,0,0,0,0,0,0,'<You tell Morae of your findings in the wreckage of the Cryo-Core.>$B$BSo... he''s...$B$BI guess I knew on some level, but just wouldn''t let myself believe it. It''s not the news I was hoping for, but you have my deepest thanks for finding Galaen.',12340),
	 (9580,1,0,0,0,0,0,0,0,'This will keep us supplied for quite a while, and preparing it for consumption will certainly keep me busy. Thank you for your help, $n.',12340),
	 (9581,1,0,0,0,0,0,0,0,'This crystal shard will give our researchers a baseline to compare against samples from other parts of the island, since it comes from one of Bloodmyst''s less corrupted regions.$B$BI won''t be able to send it off until we have a full set of samples, but this is a great start. If you''re willing to help gather the other samples, I''ll see to it that you''re rewarded for your efforts.',12340),
	 (9584,1,0,0,0,0,0,0,0,'<Harbinger Mikolaas examines the crystal shard.>$B$BThis shard is much different from the initial sample.$B$B<Harbinger Mikolaas holds the crystal up to catch the light.>$B$BDo you see how it pulsates like that? That''s worrisome. I''ll make a note in my report of the alterations the blood elves appear to have made to this crystal. Thank you again for your help, $N.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (9585,1,0,0,0,0,0,0,0,'<Harbinger Mikolaas accepts the last crystal from you.>$B$BThat rounds out the set. All that remains to be done is to box them and send them to the Exodar.$B$B<The harbinger seems glad to be done with the task.>$B$BDon''t get me wrong, $N, I''m sure the research is valuable, but we''re faced with a number of other pressing problems out here. ',12340),
	 (9594,1,0,0,0,0,0,0,0,'You''ve done well in bringing this to me, $N. This is, without a doubt, an armor fragment from a felguard.$B$BThen, it is as I feared. The Nazzivus satyr are renewing their contacts with the Burning Legion. If we don''t stop them, the satyrs and their demonic allies will overrun us. I will notify Harbinger Mikolaas right away.',12340),
	 (9602,1,1,0,0,0,0,0,0,'<Exarch Menelaous takes the letter from you and begins to read it.>$B$BDamn them... Damn them all to the Nether. They''ve had a spy watching everything that we''ve done! And for how long?$B$BI will notify Velen at once!$B$BYou''ve done us a great service, $N. Be on guard as I will be contacting you once the Prophet has given me instruction as to what to do.',12340),
	 (9603,1,0,0,0,0,0,0,0,'So you need to go to the Exodar?$B$BThat''s going to be a long trip, but don''t worry, I have a way to get you there very quickly.',12340),
	 (9604,1,0,0,0,0,0,0,0,'So you''ve brought Topher''s list. Excellent! I was hoping to receive this today. Let''s see what he needs.$B$B<Nurguni reads over the list and begins placing various items in a box.>$B$BThat''s most of what he requested. The pieces for the beds are simply too large to be delivered by hippogryph, but I''ll make arrangements to have them sent by wagon. ',12340),
	 (9605,1,0,0,0,0,0,0,0,'So you''re headed back to Blood Watch with this package? No problem at all, $C. Just speak with me again and we''ll get you on your way with those supplies.',12340),
	 (9606,1,0,0,0,0,0,0,0,'<Handing Topher the box, you tell him that Nurguni is making arrangements to have the larger items delivered by wagon.>$B$BSplendid! Now, I''ll finally be able to set up some beds and a first aid station so that we can better treat the wounded and any survivors we encounter.$B$BI can''t thank you enough for your help, $N. You have my thanks and that of the Blood Watch''s vindicators.',12340),
	 (9612,1,4,0,0,0,0,0,0,'Well done, $N. Well done indeed! You are turning out to be a special $R - a cut above the others of your age. Take this as a reward!',12340),
	 (9616,5,0,0,0,0,0,0,0,'By the beardless, geometric head of O''ros! It is good you brought this to me, $N. These blood elves are out for... well, blood. Velen will be informed at once! Take this as a reward.',12340),
	 (9620,0,0,0,0,0,0,0,0,'The bodies of the $R survey team are scattered all over the ground here, pierced by naga weaponry. The area is littered with the remains of their supplies and survey equipment, but their data crystals are nowhere to be seen.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (9622,6,1,1,0,0,0,0,0,'Visions you say? Interesting... And this prophecy has come to pass?$B$BBut you say they saw the power core of the Exodar? And O''ros was also in the vision? What can it mean?',12340),
	 (9623,0,0,0,0,0,0,0,0,'<Torallius sighs.>$B$BAlright, let me have a look at those orders.',12340),
	 (9624,1,0,0,0,0,0,0,0,'Did you have a difficult time finding enough? It''s been taking me longer with each trip.$B$BSoon, I''ll have to stop altogether since I won''t be able to spare the time. Thank you for gathering the pears for me, $N. It gives me a chance to make a last pie or two before the season''s out.',12340),
	 (9625,0,0,0,0,0,0,0,0,'Well ya made it this far! Let''s put ya to work before you get too bloodied up.',12340),
	 (9628,1,0,0,0,0,0,0,0,'<You tell Harbinger Mikolaas of the survey team''s fate. He accepts the crystal from you, but remains silent for a long moment.>$B$BThey were good men, $N, and they knew their mission would be dangerous. I''m grateful for your help in locating the team and recovering the crystal.$B$B<The harbinger''s fists clench.>$B$BWe''ve lost too many good men already, and our mission has only just begun.',12340),
	 (9629,4,0,0,0,0,0,0,0,'Well done, $N. I was worried that the marking device might malfunction, but it seems like everything went according to plan.',12340),
	 (9632,1,0,0,0,0,0,0,0,'I can help you get to Auberdine. Fortunately, it''s only a short boat trip away! ',12340),
	 (9633,1,0,0,0,0,0,0,0,'<Thundris accepts the letter from you and reads it quickly, nodding.>$B$BThe isles the $R call Azuremyst and Bloodmyst were inhabited long ago by my people. Some of the threats faced by Anchorite Paetheus and his brethren are ancient enemies of the night elves.$B$BI am certain that the people of Auberdine are willing to provide what aid we can to our new allies. As soon as I have spoken with the townspeople and the sentinels, I will send word to Paetheus.',12340),
	 (9634,1,0,0,0,0,0,0,0,'Well done, $N. The ravager population will bear watching for some time to come, but we''ve made a good start.',12340),
	 (9641,1,0,0,0,0,0,0,0,'Well done. These will provide the raw materials for another batch of enhancement crystals.$B$BYou''re welcome to choose from among the three kinds of crystals I can make. I find each of them useful for stalking different kinds of prey.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (9642,1,0,0,0,0,0,0,0,'Very well, here are the crystals that I have, $N. Use them well.',12340),
	 (9643,1,0,0,0,0,0,0,0,'These seem sturdy enough to do the job. Thank you for your help, $N. Your contribution to Blood Watch''s defense will not be forgotten.',12340),
	 (9646,1,0,0,0,0,0,0,0,'Well done. From what I''ve heard, it couldn''t have been an easy fight. You''ve more than earned your reward, $N.',12340),
	 (9647,1,0,0,0,0,0,0,0,'In time, we''ll have to devise a plan for returning the species to its native state, but for now, periodically culling their numbers is about the best we can hope for. Thank you for your help, $N.',12340),
	 (9648,1,1,0,0,0,0,0,0,'Well, I did warn you - did I not? Hopefully this payment more than makes up for the mild discomfort that you may have suffered. Return to me when you have gained strength and perhaps I will have another job for you - mushrooms of course!',12340),
	 (9649,0,0,0,0,0,0,0,0,'I hope this wasn''t too strenuous a task, $N. Once again you have proven yourself a competent and considerate $r. I offer my gratitude and a small bit of monetary compensation.
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (9669,0,0,0,0,0,0,0,0,'Incredible! Did you find any survivors?$B$B<Achelus lowers his voice to a whisper.>$B$BI''ll be honest, $N; nobody else was willing to take on this mission. You are a brave $c...',12340),
	 (9670,5,1,0,0,0,0,0,0,'You rescued over half the team! Word of your deed will definitely get back to Blood Watch and the exarch. Thanks again, $N.',12340),
	 (9671,6,1,5,0,0,0,0,0,'Are you $N? It''s about time! I''d just about given up on finding you!$B$BThere''s an urgent message waiting for you at the mailbox. The person that gave it to me was a human admiral from Azuremyst. Admiral Odesy-something... the name escapes me. He said you would know who he was.$B$B<Hermesius shrugs.>',12340),
	 (9672,0,0,0,0,0,0,0,0,'Have you heard of the bloodcurse, landlubber? No, of course you haven''t. The bloodcurse is what sunk all these ships. The spoiled, desecrated part of the water here is known as Bloodcursed Reef - a part of the world you never want to visit. I''ve been here myself for 20 years.$B$BScurvy my foot! I died on these wild shores as food for the dragons... Ah, but that''s another story for another time. Right now, we have to help the poor souls that are trapped in that reef.',12340),
	 (9674,1,0,0,0,0,0,0,0,'A good start, but there''s much more to be done!',12340),
	 (9682,0,0,0,0,0,0,0,0,'You have done the hopeless ones a great service, $N. There is but one final task: Destroy the leader of the Bloodcursed.',12340),
	 (9683,0,0,0,0,0,0,0,0,'You did it! Hundreds of souls are grateful for all that you have done.$B$BAllow me to make an offering...',12340),
	 (9687,6,1,274,0,0,0,0,0,'A ritual? The owlkin had lived in harmony with the land for thousands of years. Such a thing is an aberration!$B$BSuch a pity...',12340),
	 (9688,0,0,0,0,0,0,0,0,'As reprehensible as your task was, it had to be done. Now you must look into the face of evil.',12340),
	 (9689,6,1,1,2,0,0,0,0,'How long has it been? A thousand years? Ten-thousand perhaps? You have done me and the memory of my people a great service, $N. Please accept this item of power as a token of appreciation from Loreth''Aran - in honor of your deeds.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (9693,0,0,0,0,0,0,0,0,'Ah, $N... I''ve heard about you. You''re the one that made the Kessel Run in under 15 minutes, right? Bah, probably not.$B$BAre you ready to spill some blood in the name of the Light? For Velen? For Argus?$B$B<Boros laughs.>$B$BI''ll slow down.',12340),
	 (9694,3,1,0,1,0,0,0,0,'You have returned - and in one piece!$B$BI have some good news, $N. We have received some new information about the possible location of more survivors. A new crash site has been discovered! When I am done attending to those matters, I will call for you.',12340),
	 (9696,1,1,0,0,0,0,0,0,'<Elysia reads from the document.>$B$BIf what this document says is true, the blood elves have opened a portal to the Outland! It would certainly explain their seemingly endless numbers...',12340),
	 (9698,1,1,0,0,0,0,0,0,'<Velen begins to read the document.>$B$BInteresting... This does indeed explain much.',12340),
	 (9699,1,1,0,0,0,0,0,0,'It''s a good plan, but a dangerous one. I''m sure you''ll be fine.',12340),
	 (9700,1,6,1,0,0,0,0,0,'How many did you say you saw at the Warp Piston? Just how many times have they opened up this sun portal? This is very bad news...$B$BAlas, you have learned all that I am able to teach you, $N. Kuros will call for you when it is time.',12340),
	 (9703,6,0,0,0,0,0,0,0,'Just blood elves? No survivors? This is troubling. I''ll need some time to think this through, $N. Perhaps Aesom or Boros have an assignment for you to complete.',12340),
	 (9704,0,0,0,0,0,0,0,0,'The outrunner''s belongings have all been stolen with the exception of one package. It seems to match Alarion''s description of Erona''s package.',12340),
	 (9705,0,0,0,0,0,0,0,0,'By the Sunwell!  That''s the third outrunner we''ve lost this month.$B$BI appreciate your courage in venturing into Dawning Street.  The guards need to keep a closer eye on these blasted Wretched.',12340),
	 (9706,18,1,15,0,0,0,0,0,'<Kuros'' face turns pale as he reads the journal; tears stream down his face.>$B$BSaruan was my master... my teacher... my mentor... I took his place among the Triumvirate only recently - after we had given up searching for him.$B$B<Kuros'' face contorts in anger.>$B$BMatis...',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (9711,1,1,0,0,0,0,0,0,'The Triumvirate has decided to try Matis immediately. You have brought an arch-criminal to justice on this day, young $r.$B$BYou have performed admirably for two of three; only Aesom remains.
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (9760,1,1,0,0,0,0,0,0,'Perhaps you will be the one to deliver our people into a new age of prosperity and peace.',12340),
	 (9761,0,0,0,0,0,0,0,0,'Hopefully a hero arrives before they are able to call forth reinforcements to guard the area you just secured.',12340),
	 (9762,1,1,1,1,0,0,0,0,'These islands will serve as the home to thousands. Most of these people will remain here their entire lives. If you so desired, you could do the same. But that''s not what you want, is it, $N?$B$B<Velen nods.>$B$BYou will do many more great things before you pass. You must embrace your destiny and meet it head on!$B$BBefore you leave, I present you with two gifts: This tabard is worn by only the most revered of the Hand of Argus and this signet ring worn by our wisest sages. Wear them both with pride, $N.',12340),
	 (9779,1,1,0,0,0,0,0,0,'<Vindicator Boros eyes the document.>$B$BThis is in Thalassian. Fortunately, I know just the person that can translate it...',12340),
	 (9798,0,0,0,0,0,0,0,0,'Here, let me read those plans.$B$BThe blood elves have followed us here?  They are evil to the core and should be wiped from existence!$B$B<The vindicator takes a moment to regain his composure.>$B$BI apologize, that was uncalled for.  We are indebted to you for uncovering this information, $N.',12340),
	 (9799,1,0,0,0,0,0,0,0,'These look like fine specimens.  Thank you for performing the field work.  Once I can find the time to analyze these, I should be able to tell what it will take to restore the fields.',12340),
	 (9811,0,0,0,0,0,0,0,0,'So you killed Dar''Khan, $R?  Impressive.  I''ve a feeling my people and yours will soon get to be very good friends.',12340),
	 (9877,0,0,0,0,0,0,0,0,'Janeda''s sending you to rescue the Deatholme prisoners? She must think very highly of you, $N.',12340),
	 (10063,1,1,0,0,0,0,0,0,'I thought so! That grumpy old dwarf was supposed to help me carry my equipment and gather data, but all he does is sit in that strange draenei town, drinking himself into a stupor.',12340),
	 (10064,0,0,0,0,0,0,0,0,'I was hoping Blood Watch would send reinforcements once they learned what we''re up against.',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (10065,0,0,0,0,0,0,0,0,'It looks a bit better out there, but I still wonder if I wouldn''t be better off waiting for a medic here.',12340),
	 (10066,1,1,1,0,0,0,0,0,'Well done, $N. It''s going to be much easier to get reinforcements from Blood Watch, or launch strikes against the Sunhawks without having to worry about what the tanglers are up to.',12340),
	 (10067,1,1,1,0,0,0,0,0,'Well done, $N. It''s important not to overlook any opportunity to deny the Sunhawks sustenance.',12340),
	 (10068,0,0,0,0,0,0,0,0,'Ah good, a $C. I''ve been expecting you.$BThere are a few tasks that I have which you are particularly suited to.',12340),
	 (10069,0,0,0,0,0,0,0,0,'Ah good, a $C. I''ve been expecting you.$B$BThere are a few tasks that I have to which you are particularly suited to.',12340),
	 (10070,0,0,0,0,0,0,0,0,'Ah good, a $C. I''ve been expecting you.$B$BThere are a few tasks that I have to which you are particularly suited to.',12340),
	 (10071,1,0,0,0,0,0,0,0,'Ah good, a $C. I''ve been expecting you.$B$BThere are a few tasks that I have to which you are particularly suited to.',12340),
	 (10072,0,0,0,0,0,0,0,0,'Ah good, a $C. I''ve been expecting you.$B$BThere are a few tasks that I have to which you are particularly suited to.',12340),
	 (10073,1,0,0,0,0,0,0,0,'Well done, $n. You are quickly becoming one of my best students and I look forward to continuing your training in the future.',20886),
	 (10166,0,0,0,0,0,0,0,0,'I no longer belong to this world and must admit defeat.  The land has forever changed and nothing will ever be the same.Leave the pendant here with me, maybe one day, long after the elves are gone, a new tree will grow on this very spot - amongst a burnt forest and the husks of dead treants. ',12340);
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES
	 (10302,1,1,0,0,0,0,0,0,'You''re finished? That''s good news. Hopefully, we can find a way to avoid the killing of these mutated beasts in the future.$b$bI believe I have formed a plan that might give us an alternative solution to this problem, but I will need your help.',12340),
	 (10303,0,0,0,0,0,0,0,0,'These blood elves mean to kill us all. How are we to divert them from this course?',12340),
	 (10304,6,0,0,0,0,0,0,0,'$N, is it? I''ve heard good things about you and the work you''ve been doing in the short time since you came to.$B$BWe''ll definitely need your help getting things back to normal. Zhanaa, over there, could also use your help, I''m sure.',12340),
	 (10324,1,0,0,0,0,0,0,0,'Wonderful! You''re turning into quite the hunter, $n.$b$bHow would you like to look more like me? Well here is your chance! While you were out hunting, I fashioned these items out of some buck hides I had laying around. Take your pick!',12340),
	 (10428,1,0,0,0,0,0,0,0,'My family... What have I done... What could I have done?$b$bWhy must I be punished so?',12340),
	 (11163,1,0,0,0,0,0,0,0,'<Donna looks around and then whispers to you.>$B$B$N, what I''m about to tell you must remain confidential, understood?$B$BI''ve been sent by the Shattrath Peacekeepers to infiltrate Budd''s gang here. Truth be told, since you first arrived you''ve been a key person of interest in my investigation.$B$BBut your deeds have since cleared you of any suspicion. In fact, for your slaying of the crazed warlord, Zul''Jin, I''m compelled to reward you for your efforts.',12340);
